    private record HungerGamesMapDefinition(
        String key,
        String displayName,
        String structureId,
        Double borderCenterX,
        Double borderCenterZ,
        Double borderSize
    ) {
        private boolean hasCustomBorder() {
            return borderCenterX != null && borderCenterZ != null && borderSize != null && borderSize > 0.0D;
        }

        private boolean hasCustomCenter() {
            return borderCenterX != null && borderCenterZ != null;
        }

        private boolean hasCustomBorderSize() {
            return borderSize != null && borderSize > 0.0D;
        }
    }
