    private enum FakePcsDivePart {
        FRAME(null, null),
        HEAD("hydra:plane_dive_head", FakePcsDiveGltfImporter.Part.HEAD),
        BODY("hydra:plane_dive_body", FakePcsDiveGltfImporter.Part.BODY),
        RIGHT_ARM("hydra:plane_dive_right_arm", FakePcsDiveGltfImporter.Part.RIGHT_ARM),
        LEFT_ARM("hydra:plane_dive_left_arm", FakePcsDiveGltfImporter.Part.LEFT_ARM),
        RIGHT_LEG("hydra:plane_dive_right_leg", FakePcsDiveGltfImporter.Part.RIGHT_LEG),
        LEFT_LEG("hydra:plane_dive_left_leg", FakePcsDiveGltfImporter.Part.LEFT_LEG);

        private final String modelId;
        private final FakePcsDiveGltfImporter.Part rigPart;

        FakePcsDivePart(String modelId, FakePcsDiveGltfImporter.Part rigPart) {
            this.modelId = modelId;
            this.rigPart = rigPart;
        }

        private boolean isRigPart() {
            return rigPart != null;
        }

        private NamespacedKey modelKey() {
            return modelId == null ? null : NamespacedKey.fromString(modelId);
        }

        private FakePcsDiveGltfImporter.Part rigPart() {
            return rigPart;
        }
    }

    private enum FakePcsDiveAnimationMode {
        FRAMES,
        RIG;

        private static FakePcsDiveAnimationMode parse(String rawValue) {
            if (rawValue == null || rawValue.isBlank()) {
                return FRAMES;
            }
            try {
                return FakePcsDiveAnimationMode.valueOf(rawValue.trim().toUpperCase(Locale.ROOT));
            } catch (IllegalArgumentException ex) {
                return FRAMES;
            }
        }
    }

    private enum MatchWorldGenerationMode {
        DATAPACK,
        LEGACY_PLUGIN;

        private static MatchWorldGenerationMode parse(String rawValue) {
            if (rawValue == null || rawValue.isBlank()) {
                return DATAPACK;
            }
            try {
                return MatchWorldGenerationMode.valueOf(rawValue.trim().toUpperCase(Locale.ROOT));
            } catch (IllegalArgumentException ex) {
                return DATAPACK;
            }
        }
    }

