    public QueueService(JavaPlugin plugin, AuctionHouseService auctionHouseService) {
        this.plugin = plugin;
        this.auctionHouseService = auctionHouseService;
        this.matchWorldService = new MatchWorldService(plugin, new MatchWorldService.CleanupHooks() {
            @Override public void returnPlayerToHub(Player player) { QueueService.this.returnToHub(player, true); }
            @Override public void retryCleanup(String worldName) { cleanupSingleWorld(worldName); }
            @Override public boolean isReserved(String worldName) {
                return isActiveMatchWorldValue(worldName) || isPrewarmedMatchWorldValue(worldName);
            }
            @Override public boolean hasGenerationFlight(String worldName) {
                BrGenerationFlight flight = brGenerationFlightsByWorld.get(worldName);
                return flight != null && !flight.isTerminal() && !flight.canceled;
            }
            @Override public void onFolderDeleted(String worldName) {
                if (networkHungerGamesReservationByWorld.remove(worldName) != null
                    && plugin instanceof HGLootPlugin hydra && hydra.networkBridgeService() != null) {
                    hydra.networkBridgeService().worldCleaned(worldName);
                }
            }
            @Override public void onCleanupFinished(String worldName) { managedMatchWorlds.remove(worldName); }
        });
        this.hungerGamesDuoGlowService = new ViewerGlowService(plugin);
        this.structureMarkerKey = new NamespacedKey(plugin, "structure_marker");
        this.structureMarkerIdKey = new NamespacedKey(plugin, "structure_marker_id");
        this.spectatorItemKey = new NamespacedKey(plugin, "spectator_item_action");
        this.underworldLootKey = new NamespacedKey(plugin, "underworld_loot_anchor");
        this.underworldLootTableKey = new NamespacedKey(plugin, "underworld_loot_table");
        this.leaderboardMarkerKey = new NamespacedKey(plugin, "hydra_leaderboard_marker");
        this.leaderboardTypeKey = new NamespacedKey(plugin, "hydra_leaderboard_type");
        this.leaderboardIdKey = new NamespacedKey(plugin, "hydra_leaderboard_id");
        this.leaderboardLineKey = new NamespacedKey(plugin, "hydra_leaderboard_line");
        this.hellscapePatrolKey = new NamespacedKey(plugin, "hellscape_patrol");
        this.hellscapePatrolRoleKey = new NamespacedKey(plugin, "hellscape_patrol_role");
        this.hungerGamesBowProjectileKey = new NamespacedKey(plugin, "hg_bow_projectile");
        for (QueueType type : QueueType.values()) {
            queues.put(type, new LinkedHashSet<>());
        }
        loadConfig();
    }

