    public String activeHungerGamesMapKey() {
        String key = normalizeHungerGamesMapKey(hungerGamesMapSelectionKey);
        if (RANDOM_HUNGER_GAMES_MAP_KEY.equals(key)) {
            return RANDOM_HUNGER_GAMES_MAP_KEY;
        }
        HungerGamesMapDefinition definition = resolveHungerGamesMapDefinition(hungerGamesStructureId, hungerGamesMapName);
        return definition == null ? OUTCOVE_HUNGER_GAMES_MAP_KEY : definition.key();
    }

    public boolean isHungerGamesMapActive(String mapKey) {
        return Objects.equals(activeHungerGamesMapKey(), normalizeHungerGamesMapKey(mapKey));
    }

    public void summonLifetimeKillsLeaderboard(Player player) {
        summonDebugLeaderboard(player, DebugLeaderboardType.KILLS);
    }

    public void summonDebugLeaderboard(Player player, DebugLeaderboardType type) {
        summonDebugLeaderboard(player, type, leaderboardAnchor(player), true);
    }

    public void summonDebugLeaderboard(Player player, DebugLeaderboardType type, Location anchor) {
        summonDebugLeaderboard(player, type, anchor, false);
    }

    public void summonDebugLeaderboard(Player player, DebugLeaderboardType type, Location anchor, boolean adjustToSurface) {
        if (type == null) {
            return;
        }
        if (player == null || !player.isOnline()) {
            return;
        }
        if (anchor == null || anchor.getWorld() == null) {
            player.sendMessage(PREFIX + ChatColor.RED + "Invalid leaderboard location.");
            return;
        }
        anchor = adjustToSurface ? safeLeaderboardAnchor(anchor) : exactLeaderboardAnchor(anchor);
        int removed = clearNearbyDebugLeaderboards(anchor, null, DEBUG_LEADERBOARD_CLEAR_RADIUS);
        UUID boardId = UUID.randomUUID();
        for (int lineIndex = 0; lineIndex < DEBUG_LEADERBOARD_LINE_COUNT; lineIndex++) {
            Location lineLocation = leaderboardLineLocation(anchor, lineIndex);
            spawnDebugLeaderboardLine(lineLocation, boardId, type.key(), lineIndex);
        }
        spawnDebugLeaderboardInteraction(anchor, boardId, type.key());
        refreshAllDebugLeaderboards();
        int placed = collectDebugLeaderboards(type.key()).getOrDefault(boardId, List.of()).size();
        player.sendMessage(PREFIX + ChatColor.GREEN + "Placed " + ChatColor.WHITE + type.menuLabel()
            + ChatColor.GREEN + " leaderboard."
            + ChatColor.GRAY + " Lines=" + ChatColor.WHITE + placed
            + (removed > 0 ? ChatColor.GRAY + " Replaced nearby board." : ""));
    }

    private Location exactLeaderboardAnchor(Location anchor) {
        Location exact = anchor.clone();
        exact.setX(exact.getBlockX() + 0.5D);
        exact.setZ(exact.getBlockZ() + 0.5D);
        exact.setY(exact.getY() + 2.2D);
        return exact;
    }

    private Location safeLeaderboardAnchor(Location anchor) {
        Location safe = anchor.clone();
        int highest = safe.getWorld().getHighestBlockYAt(safe);
        safe.setY(Math.max(safe.getY(), highest + 3.2D));
        return safe;
    }

    private Location leaderboardLineLocation(Location anchor, int lineIndex) {
        double extraGap = lineIndex >= 3 ? 0.14D : 0.0D;
        return anchor.clone().subtract(0.0D, (lineIndex * DEBUG_LEADERBOARD_LINE_SPACING) + extraGap, 0.0D);
    }

    public void clearNearbyLifetimeKillsLeaderboards(Player player) {
        clearNearbyDebugLeaderboards(player);
    }

    public void clearNearbyDebugLeaderboards(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        int removed = clearNearbyDebugLeaderboards(
            player.getLocation(),
            null,
            DEBUG_LEADERBOARD_NEARBY_CLEAR_RADIUS
        );
        if (removed <= 0) {
            player.sendMessage(PREFIX + ChatColor.YELLOW + "No nearby leaderboard found.");
            return;
        }
        clearOrphanedPersonalLeaderboardViews();
        player.sendMessage(PREFIX + ChatColor.GREEN + "Cleared nearby leaderboards.");
    }

    public void clearDebugLeaderboards(Player player, DebugLeaderboardType type) {
        if (player == null || !player.isOnline()) {
            return;
        }
        int removed = clearAllDebugLeaderboards(type == null ? null : Set.of(type.key()));
        clearOrphanedPersonalLeaderboardViews();
        player.sendMessage(PREFIX + (removed <= 0
            ? ChatColor.YELLOW + "No matching leaderboard found."
            : ChatColor.GREEN + "Cleared " + removed + " leaderboard line(s)."));
    }

    public void clearDebugLeaderboards(Player player, Set<String> typeKeys) {
        if (player == null || !player.isOnline()) {
            return;
        }
        int removed = clearAllDebugLeaderboards(typeKeys);
        clearOrphanedPersonalLeaderboardViews();
        player.sendMessage(PREFIX + (removed <= 0
            ? ChatColor.YELLOW + "No matching leaderboard found."
            : ChatColor.GREEN + "Cleared " + removed + " leaderboard line(s)."));
    }

    public void refreshLeaderboards(Player sender) {
        invalidateLeaderboardCache();
        refreshAllDebugLeaderboards();
        if (sender != null) {
            sender.sendMessage(PREFIX + ChatColor.GREEN + "Leaderboards refreshed.");
        }
    }

    public void reloadLeaderboardData(Player sender) {
        loadPlayerStats();
        refreshAllDebugLeaderboards();
        if (sender != null) {
            sender.sendMessage(PREFIX + ChatColor.GREEN + "Leaderboard data reloaded.");
        }
    }

    public void sendLeaderboardDebug(Player sender) {
        if (sender == null) {
            return;
        }
        Map<UUID, List<Entity>> boards = collectDebugLeaderboards(null);
        int lines = 0;
        for (List<Entity> boardLines : boards.values()) {
            lines += boardLines.size();
        }
        int entities = countDebugLeaderboardEntities(null);
        sender.sendMessage(ChatColor.DARK_AQUA + "[Leaderboard] " + ChatColor.GRAY + "Boards: " + ChatColor.WHITE + boards.size());
        sender.sendMessage(ChatColor.DARK_AQUA + "[Leaderboard] " + ChatColor.GRAY + "Lines: " + ChatColor.WHITE + lines
            + ChatColor.GRAY + ", entities=" + ChatColor.WHITE + entities);
        sender.sendMessage(ChatColor.DARK_AQUA + "[Leaderboard] " + ChatColor.GRAY + "Data: "
            + ChatColor.WHITE + "kills=" + lifetimeKills.size()
            + ChatColor.GRAY + ", totalWins=" + lifetimeWins.size()
            + ChatColor.GRAY + ", brWins=" + brLifetimeWins.size()
            + ChatColor.GRAY + ", hgWins=" + hgLifetimeWins.size()
            + ChatColor.GRAY + ", level=" + (progressionService == null ? 0 : progressionService.levelSnapshot().size())
            + ChatColor.GRAY + ", money=" + moneyStatMap().size());
    }

    public void sendLeaderboard(Player player, DebugLeaderboardType type) {
        if (player == null || type == null) {
            return;
        }
        player.sendMessage(ChatColor.AQUA + "" + ChatColor.BOLD + type.title());
        player.sendMessage(ChatColor.DARK_GRAY + "━━━━━━━━━━━━");
        List<DebugLeaderboardEntry> entries = topDebugLeaderboardEntries(type, DEBUG_LEADERBOARD_ENTRY_COUNT);
        if (entries.isEmpty()) {
            player.sendMessage(ChatColor.DARK_GRAY + "No data yet");
        }
        for (int i = 0; i < entries.size(); i++) {
            DebugLeaderboardEntry entry = entries.get(i);
            player.sendMessage(rankColor(i + 1) + "#" + (i + 1)
                + " " + ChatColor.WHITE + trimLeaderboardName(displayName(entry.playerId()))
                + ChatColor.DARK_GRAY + " - "
                + leaderboardValueColor(type) + leaderboardValueLabel(type, entry.value()));
        }
        int playerRank = rankOfPlayer(type, player.getUniqueId());
        if (playerRank > DEBUG_LEADERBOARD_ENTRY_COUNT) {
            DebugLeaderboardEntry ownEntry = leaderboardEntry(type, player.getUniqueId());
            if (ownEntry != null) {
                player.sendMessage(ChatColor.DARK_GRAY + "...");
                player.sendMessage(rankColor(playerRank) + "#" + playerRank
                    + " " + ChatColor.WHITE + trimLeaderboardName(displayName(player.getUniqueId()))
                    + ChatColor.DARK_GRAY + " - "
                    + leaderboardValueColor(type) + leaderboardValueLabel(type, ownEntry.value()));
            }
        }
        player.sendMessage(ChatColor.DARK_GRAY + "━━━━━━━━━━━━");
    }

    public void removeViewedDebugLeaderboard(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        Entity entity = viewedDebugLeaderboardLine(player);
        if (entity == null) {
            player.sendMessage(PREFIX + ChatColor.YELLOW + "No leaderboard in view.");
            return;
        }
        UUID boardId = debugLeaderboardId(entity);
        if (boardId == null || removeDebugLeaderboard(boardId) <= 0) {
            player.sendMessage(PREFIX + ChatColor.YELLOW + "No leaderboard in view.");
            return;
        }
        removePersonalLeaderboardViews(boardId);
        player.sendMessage(PREFIX + ChatColor.GREEN + "Removed leaderboard.");
    }

    public void switchViewedDebugLeaderboard(Player player, DebugLeaderboardType type) {
        if (player == null || !player.isOnline() || type == null) {
            return;
        }
        Entity entity = viewedDebugLeaderboardLine(player);
        if (entity == null) {
            player.sendMessage(PREFIX + ChatColor.YELLOW + "No leaderboard in view.");
            return;
        }
        UUID boardId = debugLeaderboardId(entity);
        if (boardId == null) {
            player.sendMessage(PREFIX + ChatColor.YELLOW + "No leaderboard in view.");
            return;
        }
        List<Entity> entities = collectDebugLeaderboardEntities(null).getOrDefault(boardId, List.of());
        if (entities.isEmpty()) {
            player.sendMessage(PREFIX + ChatColor.YELLOW + "No leaderboard in view.");
            return;
        }
        for (Entity line : entities) {
            if (line != null && line.isValid()) {
                line.getPersistentDataContainer().set(leaderboardTypeKey, PersistentDataType.STRING, type.key());
            }
        }
        removePersonalLeaderboardViews(boardId);
        refreshAllDebugLeaderboards();
        player.sendMessage(PREFIX + ChatColor.GREEN + "Leaderboard switched to "
            + ChatColor.WHITE + type.menuLabel() + ChatColor.GREEN + ".");
    }

    public boolean selectHungerGamesMap(String mapKey, CommandSender sender) {
        String normalizedMapKey = normalizeHungerGamesMapKey(mapKey);
        if (RANDOM_HUNGER_GAMES_MAP_KEY.equals(normalizedMapKey)) {
            List<HungerGamesMapDefinition> available = availableHungerGamesMapDefinitions();
            if (available.isEmpty()) {
                if (sender != null) {
                    sender.sendMessage(ChatColor.RED + "No Hunger Games maps are available on the server.");
                }
                return false;
            }
            hungerGamesMapSelectionKey = RANDOM_HUNGER_GAMES_MAP_KEY;
            hungerGamesMapName = RANDOM_HUNGER_GAMES_MAP_NAME;
            plugin.getConfig().set("queue.hunger_games.map_selection_key", hungerGamesMapSelectionKey);
            plugin.getConfig().set("queue.hunger_games.map_name", hungerGamesMapName);
            plugin.saveConfig();
            clearStaleHungerGamesPrewarm();
            if (sender != null) {
                sender.sendMessage(PREFIX + "Active Hunger Games map mode set to " + ChatColor.GOLD + RANDOM_HUNGER_GAMES_MAP_NAME + ChatColor.GRAY + ".");
            }
            plugin.getLogger().info("[Queue] Active Hunger Games map mode set to Random by "
                + (sender == null ? "system" : sender.getName()) + ".");
            Bukkit.getScheduler().runTask(plugin, () -> startupPrewarmMatchWorld(QueueType.HUNGERGAMES));
            return true;
        }
        HungerGamesMapDefinition definition = hungerGamesMapDefinitionByKey(mapKey);
        if (definition == null) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "Unknown Hunger Games map.");
            }
            return false;
        }
        String normalizedStructureId = normalizeStructureId(definition.structureId());
        if (resolveHydraStructure(normalizedStructureId) == null) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "That Hunger Games map is not available on the server yet.");
            }
            plugin.getLogger().warning("[Queue] HG map selection failed for " + definition.displayName()
                + " because structure " + normalizedStructureId + " is missing.");
            return false;
        }
        hungerGamesMapSelectionKey = definition.key();
        hungerGamesStructureId = normalizedStructureId;
        hungerGamesMapName = definition.displayName();
        plugin.getConfig().set("queue.hunger_games.map_selection_key", hungerGamesMapSelectionKey);
        plugin.getConfig().set("queue.hunger_games.structure_id", hungerGamesStructureId);
        plugin.getConfig().set("queue.hunger_games.map_name", hungerGamesMapName);
        plugin.saveConfig();
        clearStaleHungerGamesPrewarm();
        if (sender != null) {
            sender.sendMessage(PREFIX + "Active Hunger Games map set to " + ChatColor.GOLD + hungerGamesMapName + ChatColor.GRAY + ".");
        }
        plugin.getLogger().info("[Queue] Active Hunger Games map set to " + hungerGamesMapName
            + " (" + hungerGamesStructureId + ") by " + (sender == null ? "system" : sender.getName()) + ".");
        Bukkit.getScheduler().runTask(plugin, () -> startupPrewarmMatchWorld(QueueType.HUNGERGAMES));
        return true;
    }

    public List<String> availableBattleRoyaleTerrainProfiles(CommandSender sender) {
        List<String> profiles = new ArrayList<>();
        for (BrTerrainProfile profile : BrTerrainProfile.values()) {
            if (profile == BrTerrainProfile.VALOUS && !hasValousDevelopmentAccess(sender)) {
                continue;
            }
            profiles.add(profile.configKey());
        }
        return profiles;
    }

    public boolean selectBattleRoyaleTerrainProfile(String rawProfile, CommandSender sender) {
        BrTerrainProfile profile = BrTerrainProfile.fromConfigOrNull(rawProfile);
        if (profile == null) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "Unknown BR terrain profile. Use: "
                    + String.join(", ", availableBattleRoyaleTerrainProfiles(sender)));
            }
            return false;
        }
        if (profile == BrTerrainProfile.VALOUS && !hasValousDevelopmentAccess(sender)) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "Valous is development-only. Dev or Owner access is required.");
            }
            plugin.getLogger().warning("[Queue][ValousSafety] event=public_selection_rejected actor="
                + valousActorName(sender) + " source=admin_br_switch profile=valous");
            return false;
        }
        if (hasActiveBrProfileSelectionState()) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "Stop active BR matches and clear the BR queue before switching terrain profiles.");
            }
            return false;
        }

        for (QueueType type : List.of(QueueType.SOLO, QueueType.DUO)) {
            cancelUnclaimedBrGeneration(type, "terrain_profile_changed");
            for (String worldName : prewarmedMatchWorldsFor(type)) {
                removePrewarmedMatchWorld(type, worldName);
                cleanupOrDetachPrewarmedWorld(worldName, "[Queue] Cleared stale BR prewarm world for terrain profile switch");
            }
            prewarmCooldownUntilMs.remove(type);
            countdowns.remove(type);
            pendingMatchStarts.remove(type);
            matchStartInProgress.remove(type);
            brMatchStartRetryTokens.remove(type);
            prewarmInProgress.remove(type);
        }
        valousSafetyLoggedSources.clear();
        valousDevelopmentTestArmed = false;
        valousReadyFactoryEnabled = false;
        valousReadyFactoryWorldName = null;
        valousReadyFactoryReplacementPending = false;

        brTerrainEnabled = true;
        brTerrainProfile = profile;
        matchWorldEnvironment = profile == BrTerrainProfile.HELLSCAPE
            ? World.Environment.NETHER
            : World.Environment.NORMAL;
        matchWorldGenerationMode = switch (profile) {
            case HYDRA_WILDS, HELLSCAPE, VALOUS -> MatchWorldGenerationMode.DATAPACK;
            case NORMAL_ISLAND, AEOS_ISLES -> MatchWorldGenerationMode.LEGACY_PLUGIN;
        };
        if (profile == BrTerrainProfile.VALOUS) {
            brTerrainMinYHint = -208;
            brTerrainMaxYHint = 511;
        } else if (brTerrainMaxYHint <= 150) {
            brTerrainMinYHint = -200;
            brTerrainMaxYHint = 500;
        }

        plugin.getConfig().set("queue.match_world.br_terrain.enabled", true);
        plugin.getConfig().set("queue.match_world.br_terrain.profile", brTerrainProfile.configKey());
        plugin.getConfig().set("queue.match_world.environment", matchWorldEnvironment.name());
        plugin.getConfig().set("queue.match_world.generation_mode", matchWorldGenerationMode.name().toLowerCase(Locale.ROOT));
        plugin.getConfig().set("queue.match_world.br_terrain.vertical_min_hint", brTerrainMinYHint);
        plugin.getConfig().set("queue.match_world.br_terrain.vertical_max_hint", brTerrainMaxYHint);
        plugin.saveConfig();

        if (profile == BrTerrainProfile.VALOUS) {
            boolean testReady = isValousDevelopmentTestReady();
            valousDevelopmentTestArmed = testReady;
            if (sender != null) {
                sender.sendMessage(testReady
                    ? ChatColor.GREEN + "Valous development test mode armed. Dev and Owner players may queue and force-start BR."
                    : ChatColor.YELLOW + "Valous selected, but testing is blocked because its datapack registries are not loaded."
                        + " Enable file/hydra_valous.zip and restart the server.");
            }
            plugin.getLogger().info("[Queue][ValousSafety] event=development_selection_allowed actor="
                + valousActorName(sender) + " profile=valous live_start=" + (testReady ? "development_only" : "blocked")
                + " registry_loaded=" + isValousRegistryLoaded() + " template_ready=" + isValousTemplateAvailable());
            if (!testReady) {
                logValousDatapackUnavailable();
            }
        } else if (sender != null) {
            sender.sendMessage(PREFIX + "BR terrain profile set to " + ChatColor.GOLD + profile.displayName()
                + ChatColor.GRAY + ". New BR worlds will use this profile.");
        }
        plugin.getLogger().info("[Queue] BR terrain profile switched to " + profile.configKey()
            + " (environment=" + matchWorldEnvironment.name()
            + ", generation=" + matchWorldGenerationMode.name().toLowerCase(Locale.ROOT) + ").");
        return true;
    }

    private boolean hasActiveBrProfileSelectionState() {
        for (QueueType type : List.of(QueueType.SOLO, QueueType.DUO)) {
            if (hasActiveMatchWorld(type) || queueSize(type) > 0 || hasPendingMatchStart(type)) {
                return true;
            }
        }
        return false;
    }

    public void handleValousGenerationAdmin(CommandSender sender, String[] args) {
        if (!hasValousDevelopmentAccess(sender)) {
            sender.sendMessage(ChatColor.RED + "Valous generation tools require Dev or Owner access.");
            return;
        }
        if (args.length > 0 && args[0].equalsIgnoreCase("export")) {
            handleValousWorldReviewExport(
                sender,
                java.util.Arrays.copyOfRange(args, 1, args.length)
            );
            return;
        }
        if (brTerrainProfile != BrTerrainProfile.VALOUS) {
            sender.sendMessage(ChatColor.RED + "Select Valous first with /admin br switch valous.");
            return;
        }
        if (args.length == 0 || args[0].equalsIgnoreCase("status")) {
            sendValousGenerationStatus(sender);
            return;
        }
        if (args[0].equalsIgnoreCase("prepare")) {
            enableValousReadyFactory(sender);
            return;
        }
        if (args[0].equalsIgnoreCase("stop")) {
            disableValousReadyFactory(sender);
            return;
        }
        if (!args[0].equalsIgnoreCase("size") || args.length < 2) {
            sender.sendMessage(ChatColor.RED
                + "Usage: /admin br valous <status|prepare|stop|size|export>");
            return;
        }
        ValousGenerationSize requested = ValousGenerationSize.parse(args[1]);
        if (requested == null) {
            sender.sendMessage(ChatColor.RED + "Usage: /admin br valous size <quick|medium|full>");
            return;
        }
        if (hasActiveBrProfileSelectionState()) {
            sender.sendMessage(ChatColor.RED + "Stop active BR matches and clear BR queues before changing Valous size.");
            return;
        }
        valousReadyFactoryEnabled = false;
        valousReadyFactoryWorldName = null;
        valousReadyFactoryReplacementPending = false;
        for (QueueType type : List.of(QueueType.SOLO, QueueType.DUO)) {
            cancelUnclaimedBrGeneration(type, "valous_development_size_changed");
            prewarmInProgress.remove(type);
            prewarmCooldownUntilMs.remove(type);
        }
        valousGenerationSize = requested;
        plugin.getConfig().set(
            "queue.match_world.br_terrain.valous.development_generation_size",
            requested.key
        );
        plugin.saveConfig();
        sender.sendMessage(ChatColor.GREEN + "Valous development generation size set to "
            + requested.key.toUpperCase(Locale.ROOT) + ChatColor.GRAY + " (border "
            + effectiveBrTerrainBorderDiameter() + ", preload " + effectiveBrTerrainPreloadDiameter() + ").");
        plugin.getLogger().warning("[Queue][ValousTest] event=development_size_changed actor="
            + valousActorName(sender) + " size=" + requested.key
            + " border=" + effectiveBrTerrainBorderDiameter()
            + " preload=" + effectiveBrTerrainPreloadDiameter() + " development_only=true");
    }

    private void handleValousWorldReviewExport(CommandSender sender, String[] args) {
        if (args.length > 0 && args[0].equalsIgnoreCase("status")) {
            sendValousWorldReviewStatus(sender);
            return;
        }
        if (args.length > 0 && args[0].equalsIgnoreCase("cancel")) {
            ValousWorldReviewExporter.Job job = valousWorldReviewExportJob;
            if (job == null) {
                sender.sendMessage(ChatColor.RED + "No Valous world review export is running.");
                return;
            }
            job.cancel();
            sender.sendMessage(ChatColor.YELLOW + "Valous world review export canceled.");
            return;
        }
        if (args.length > 0 && args[0].equalsIgnoreCase("open")) {
            ValousWorldReviewExporter.Result result = valousWorldReviewExportResult;
            if (result == null || !result.passed() || result.indexPath() == null) {
                sender.sendMessage(ChatColor.RED + "No completed Valous review report is available.");
                return;
            }
            sender.sendMessage(ChatColor.GREEN + "Latest Valous review:");
            sender.sendMessage(ChatColor.WHITE + result.indexPath().toAbsolutePath().toString());
            return;
        }
        if (valousWorldReviewExportJob != null) {
            sender.sendMessage(ChatColor.RED + "A Valous world review export is already running: "
                + valousWorldReviewExportJob.status());
            return;
        }

        String target = "";
        ValousWorldReviewExporter.Mode mode = ValousWorldReviewExporter.Mode.REVIEW;
        if (args.length > 0) {
            ValousWorldReviewExporter.Mode firstAsMode =
                ValousWorldReviewExporter.Mode.parse(args[0]);
            if (firstAsMode != null) {
                mode = firstAsMode;
            } else {
                target = args[0];
                if (args.length > 1) {
                    mode = ValousWorldReviewExporter.Mode.parse(args[1]);
                }
            }
        }
        if (mode == null) {
            sender.sendMessage(ChatColor.RED
                + "Usage: /admin br valous export <world|current|ready> [review|full|route]");
            return;
        }
        if (mode == ValousWorldReviewExporter.Mode.FULL) {
            sender.sendMessage(ChatColor.RED
                + "Every-Y Full export belongs to exporter Phase 2 and is not available yet.");
            return;
        }

        World world = resolveValousReviewWorld(sender, target);
        if (world == null) {
            return;
        }
        ValousPregenerationLedger ledger = valousPregenerationLedgers.get(world.getName());
        String safetyFailure = valousReviewSafetyFailure(world, ledger);
        if (!safetyFailure.isBlank()) {
            sender.sendMessage(ChatColor.RED + "Valous export rejected: " + safetyFailure + ".");
            plugin.getLogger().warning("[Queue][ValousReview] event=start_rejected actor="
                + valousActorName(sender) + " world=" + world.getName()
                + " reason=" + safetyFailure + " generate=false modified=false");
            return;
        }

        ValousPrototypeValidator.Result validation =
            valousPrototypeValidationResults.get(world.getName());
        ValousRoutePostProcessor.Result route =
            valousRoutePostProcessResults.get(world.getName());
        ValousGenerationSize size = valousGenerationSizesByWorld.getOrDefault(
            rootMatchWorldName(world.getName()),
            valousGenerationSize
        );
        Path outputRoot = plugin.getDataFolder().toPath().resolve("valous-world-reviews");
        Path validationReport = validation == null || validation.reportDirectory() == null
            ? null
            : validation.reportDirectory().resolve("validation.json");
        Path routeReport = route == null ? null : route.reportPath();
        UUID worldId = world.getUID();
        UUID token = ledger.generationToken();
        ValousWorldReviewExporter.LifecycleGuard guard =
            new ValousWorldReviewExporter.LifecycleGuard() {
                @Override
                public boolean isCurrent() {
                    ValousPregenerationLedger current =
                        valousPregenerationLedgers.get(world.getName());
                    if (current == null
                        || !worldId.equals(current.worldId())
                        || !token.equals(current.generationToken())) {
                        return false;
                    }
                    BrGenerationFlight flight = brGenerationFlightsByWorld.get(world.getName());
                    return flight == null || token.equals(flight.token);
                }

                @Override
                public boolean isCanceled() {
                    ValousPregenerationLedger current =
                        valousPregenerationLedgers.get(world.getName());
                    BrGenerationFlight flight = brGenerationFlightsByWorld.get(world.getName());
                    return current == null || current.canceled()
                        || (flight != null && flight.canceled);
                }

                @Override
                public boolean isWorldUnloading() {
                    return matchWorldService.isCleaning(world.getName())
                        || Bukkit.getWorld(worldId) != world;
                }
            };
        ValousWorldReviewExporter.Settings settings =
            new ValousWorldReviewExporter.Settings(
                mode,
                size.borderDiameter,
                Math.max(16, size.borderDiameter - 8),
                outputRoot,
                validationReport,
                routeReport,
                route,
                validation,
                guard
            );
        final UUID requesterId = sender instanceof Player player ? player.getUniqueId() : null;
        valousWorldReviewExportResult = null;
        ValousWorldReviewExporter.Job startedJob = ValousWorldReviewExporter.start(
            plugin,
            world,
            ledger,
            settings,
            result -> completeValousWorldReviewExport(requesterId, result)
        );
        valousWorldReviewExportJob = startedJob.isFinished() ? null : startedJob;
        sender.sendMessage(ChatColor.GREEN + "Started " + mode.key()
            + " Valous review export for " + world.getName() + ".");
        sender.sendMessage(ChatColor.GRAY
            + "The exporter reads ledger-approved chunks only and cannot generate or modify terrain.");
    }

    private World resolveValousReviewWorld(CommandSender sender, String target) {
        if (target != null && !target.isBlank() && target.equalsIgnoreCase("current")) {
            if (!(sender instanceof Player player)) {
                sender.sendMessage(ChatColor.RED + "Console must specify a world or use ready.");
                return null;
            }
            World current = player.getWorld();
            if (!valousPregenerationLedgers.containsKey(current.getName())) {
                sender.sendMessage(ChatColor.RED + "Your current world is not an exportable Valous world.");
                return null;
            }
            return current;
        }
        if (target != null && !target.isBlank() && target.equalsIgnoreCase("ready")) {
            World ready = valousReadyFactoryWorldName == null
                ? null
                : Bukkit.getWorld(valousReadyFactoryWorldName);
            if (ready == null) {
                sender.sendMessage(ChatColor.RED + "No loaded READY Valous world is available.");
            }
            return ready;
        }
        if (target != null && !target.isBlank()) {
            World exact = Bukkit.getWorld(target);
            if (exact == null || !valousPregenerationLedgers.containsKey(exact.getName())) {
                sender.sendMessage(ChatColor.RED
                    + "No loaded ledger-backed Valous world named " + target + " exists.");
                return null;
            }
            return exact;
        }
        List<World> candidates = valousPregenerationLedgers.entrySet().stream()
            .filter(entry -> entry.getValue().isComplete())
            .map(entry -> Bukkit.getWorld(entry.getKey()))
            .filter(Objects::nonNull)
            .filter(world -> !matchWorldService.isCleaning(world.getName()))
            .toList();
        if (candidates.size() != 1) {
            sender.sendMessage(ChatColor.RED + "Specify a world, current, or ready. Exportable worlds: "
                + candidates.stream().map(World::getName).sorted().toList());
            return null;
        }
        return candidates.getFirst();
    }

    private String valousReviewSafetyFailure(
        World world,
        ValousPregenerationLedger ledger
    ) {
        if (world == null || ledger == null) {
            return "missing completed Valous ledger";
        }
        if (!ledger.isComplete()
            || ledger.completedChunkKeys().size() != ledger.expectedChunkCount()
            || !ledger.failedChunkKeys().isEmpty()) {
            return "pregeneration is incomplete";
        }
        if (!world.getUID().equals(ledger.worldId())) {
            return "world UUID does not match ledger";
        }
        if (ledger.canceled()) {
            return "generation was canceled";
        }
        if (matchWorldService.isCleaning(world.getName())) {
            return "world cleanup is active";
        }
        BrGenerationFlight flight = brGenerationFlightsByWorld.get(world.getName());
        if (flight != null && (!ledger.generationToken().equals(flight.token)
            || flight.canceled || flight.isTerminal())) {
            return "generation token is stale";
        }
        return "";
    }

    private void completeValousWorldReviewExport(
        UUID requesterId,
        ValousWorldReviewExporter.Result result
    ) {
        valousWorldReviewExportJob = null;
        valousWorldReviewExportResult = result;
        CommandSender recipient = requesterId == null ? Bukkit.getConsoleSender() : Bukkit.getPlayer(requesterId);
        if (recipient == null) {
            return;
        }
        if (result != null && result.passed()) {
            recipient.sendMessage(ChatColor.GREEN + "Valous review export complete.");
            recipient.sendMessage(ChatColor.WHITE + result.indexPath().toAbsolutePath().toString());
            recipient.sendMessage(ChatColor.GRAY + "ZIP: " + result.zipPath().toAbsolutePath());
        } else {
            recipient.sendMessage(ChatColor.RED + "Valous review export failed: "
                + (result == null ? "unknown" : result.failureReason()));
        }
    }

    private void sendValousWorldReviewStatus(CommandSender sender) {
        ValousWorldReviewExporter.Job job = valousWorldReviewExportJob;
        if (job != null) {
            sender.sendMessage(ChatColor.GOLD + "Valous review export: "
                + ChatColor.WHITE + job.status());
            return;
        }
        ValousWorldReviewExporter.Result result = valousWorldReviewExportResult;
        if (result == null) {
            sender.sendMessage(ChatColor.GRAY + "No Valous review export has run this session.");
            return;
        }
        sender.sendMessage(ChatColor.GOLD + "Latest Valous review: "
            + (result.passed() ? ChatColor.GREEN + "PASS" : ChatColor.RED + "FAIL"));
        sender.sendMessage(ChatColor.GRAY + result.worldName() + " "
            + result.mode().key() + " in " + result.durationMs() + "ms");
        if (result.indexPath() != null) {
            sender.sendMessage(ChatColor.WHITE + result.indexPath().toAbsolutePath().toString());
        }
    }

    /**
     * Isolated validation harness hook. Production startup leaves this false.
     */
    public void setValousDiagnosticSeedFallbackEnabled(boolean enabled) {
        valousDiagnosticSeedFallbackEnabled = enabled;
        plugin.getLogger().warning("[Queue][ValousSeed] event=diagnostic_fallback_changed enabled="
            + enabled + " development_only=true");
    }

    /**
     * Samples the cheap hard-gate stages without creating a world.
     */
    public CompletableFuture<String> sampleValousSeedHardGates(int sampleCount) {
        return CompletableFuture.supplyAsync(() -> {
            ValousSeedSelector.SampleReport report = ValousSeedSelector.sample(sampleCount);
            String summary = "sampled=" + report.sampledSeeds()
                + " coarse=" + report.coarseAccepted()
                + " island_hard=" + report.islandHardCandidates()
                + " predicted_hard=" + report.predictedHardAccepted()
                + " acceptance=" + formatRatio(report.predictedHardAcceptanceRate())
                + " sample_ms=" + report.sampleMs()
                + " rejects=" + report.rejectionCounts();
            plugin.getLogger().info("[Queue][ValousSeed] event=hard_gate_sample_complete " + summary);
            return summary;
        });
    }

    /**
     * Isolated selector-analysis harness hook. This samples seeds and registry-backed
     * biome data only; it cannot prepare or create a match world.
     */
    public CompletableFuture<Path> runValousSeedCalibration(int sampleCount) {
        Path output = plugin.getDataFolder().toPath()
            .resolve("valous-seed-calibration-v1.2.4.json");
        plugin.getLogger().info("[Queue][ValousSeed] event=calibration_started samples="
            + Math.max(100_000, sampleCount) + " world_generation=false");
        return CompletableFuture.supplyAsync(() -> ValousSeedCalibration.run(sampleCount, output))
            .whenComplete((path, error) -> {
                if (error == null) {
                    plugin.getLogger().info("[Queue][ValousSeed] event=calibration_complete report="
                        + path + " world_generation=false");
                } else {
                    plugin.getLogger().log(java.util.logging.Level.SEVERE,
                        "[Queue][ValousSeed] event=calibration_failed world_generation=false",
                        error);
                }
            });
    }

    public CompletableFuture<Path> runValousQuickSeedCalibration(int sampleCount) {
        Path output = plugin.getDataFolder().toPath()
            .resolve("valous-quick-seed-calibration-v1.2.4.json");
        plugin.getLogger().info("[Queue][ValousSeed] event=quick_calibration_started samples="
            + Math.max(100_000, sampleCount) + " world_generation=false");
        return CompletableFuture.supplyAsync(() ->
            ValousSeedCalibration.runQuickOnly(sampleCount, output));
    }

    public CompletableFuture<ValousQuickRegressionResult> runValousQuickPolicyRegression(
        int sampleCount
    ) {
        return CompletableFuture.supplyAsync(() -> {
            ValousSeedSelector.PolicySampleReport report = ValousSeedSelector.samplePolicy(
                ValousSeedSelector.Policy.QUICK_PROTOTYPE,
                sampleCount
            );
            double staticFeasibility = report.staticFeedCandidates() == 0
                ? 0.0D
                : report.staticPairCandidates() / (double) report.staticFeedCandidates();
            ValousQuickRegressionResult result = new ValousQuickRegressionResult(
                report.sampledSeeds(),
                report.hardAccepted(),
                report.hardAcceptanceRate(),
                report.medianAttempts(),
                report.p95Attempts(),
                report.sampleMs(),
                report.averageSeedMs(),
                report.staticFeedCandidates(),
                report.staticPairCandidates(),
                staticFeasibility,
                report.rejectionCounts(),
                report.medianAttempts() * report.averageSeedMs() <= 5_000.0D
                    && staticFeasibility >= 0.90D
            );
            plugin.getLogger().info("[Queue][ValousSeed] event=quick_policy_regression_complete"
                + " policy=" + ValousSeedSelector.Policy.QUICK_PROTOTYPE.id()
                + " sampled=" + result.sampledSeeds()
                + " accepted=" + result.hardAccepted()
                + " acceptance=" + formatRatio(result.hardAcceptanceRate())
                + " median_attempts=" + formatRatio(result.medianAttempts())
                + " p95_attempts=" + formatRatio(result.p95Attempts())
                + " average_seed_ms=" + formatRatio(result.averageSeedMs())
                + " static_feasibility=" + formatRatio(result.staticFeasibility())
                + " passed=" + result.passed()
                + " rejects=" + result.rejectionCounts());
            return result;
        });
    }

    public record ValousQuickRegressionResult(
        int sampledSeeds,
        int hardAccepted,
        double hardAcceptanceRate,
        double medianAttempts,
        double p95Attempts,
        long sampleMs,
        double averageSeedMs,
        int staticFeedCandidates,
        int staticPairCandidates,
        double staticFeasibility,
        Map<String, Integer> rejectionCounts,
        boolean passed
    ) {
    }

    public void sendValousGenerationStatus(CommandSender sender) {
        sender.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.GOLD + "Valous Generation Status");
        sender.sendMessage(ChatColor.GRAY + "Selected size: " + ChatColor.WHITE + valousGenerationSize.key
            + ChatColor.DARK_GRAY + " (border " + effectiveBrTerrainBorderDiameter()
            + ", preload " + effectiveBrTerrainPreloadDiameter() + ")");
        sender.sendMessage(ChatColor.GRAY + "Ready factory: "
            + (valousReadyFactoryEnabled ? ChatColor.GREEN + "ENABLED" : ChatColor.RED + "DISABLED")
            + ChatColor.DARK_GRAY + (valousReadyFactoryReplacementPending ? " (replacement pending)" : ""));
        List<BrGenerationFlight> flights = brGenerationFlights.values().stream()
            .filter(flight -> flight.key.terrainProfile() == BrTerrainProfile.VALOUS)
            .sorted(Comparator.comparing(flight -> flight.key.queueType().key()))
            .toList();
        if (flights.isEmpty()) {
            sender.sendMessage(ChatColor.GRAY + "No active Valous generation.");
            return;
        }
        long now = System.currentTimeMillis();
        for (BrGenerationFlight flight : flights) {
            long elapsedMs = Math.max(1L, now - flight.createdAtMs);
            int total = Math.max(1, flight.totalChunks);
            int generated = Math.max(0, Math.min(total, flight.generatedChunks));
            double percent = generated * 100.0D / total;
            long etaMs = generated <= 0 ? -1L : Math.max(0L, (long) ((total - generated) * (elapsedMs / (double) generated)));
            String ownership = flight.state == BrGenerationState.ACTIVE
                ? "active"
                : flight.ownerReservationId != null ? "claimed" : flight.canceled ? "abandoned" : "unclaimed";
            sender.sendMessage(ChatColor.AQUA + flight.key.queueType().displayName()
                + ChatColor.GRAY + " world=" + ChatColor.WHITE + flight.worldName
                + ChatColor.GRAY + " seed=" + ChatColor.WHITE + flight.seed);
            sender.sendMessage(ChatColor.GRAY + "  state=" + ChatColor.WHITE + flight.state
                + ChatColor.GRAY + " policy=" + ChatColor.WHITE + flight.valousPolicy.id()
                + ChatColor.GRAY + " owner=" + ChatColor.WHITE + ownership
                + ChatColor.GRAY + " chunks=" + ChatColor.WHITE + generated + "/" + total
                + ChatColor.GRAY + " (" + String.format(Locale.ROOT, "%.1f", percent) + "%)");
            sender.sendMessage(ChatColor.GRAY + "  elapsed=" + ChatColor.WHITE + formatGenerationDuration(elapsedMs)
                + ChatColor.GRAY + " eta=" + ChatColor.WHITE
                + (etaMs < 0 ? "calculating" : formatGenerationDuration(etaMs)));
            BrWorldPreparationState preparation = brWorldPreparationStates.get(flight.worldName);
            if (preparation != null) {
                sender.sendMessage(ChatColor.GRAY + "  prototype_phase=" + ChatColor.WHITE + preparation.phase);
            }
            ValousRoutePostProcessor.Result postProcess = valousRoutePostProcessResults.get(flight.worldName);
            if (postProcess != null) {
                sender.sendMessage(ChatColor.GRAY + "  route_postprocess=" + (postProcess.passed()
                    ? ChatColor.GREEN + "PASS"
                    : ChatColor.RED + "FAIL " + postProcess.failureReason()));
                sender.sendMessage(ChatColor.GRAY + "  route_chunks=" + ChatColor.WHITE
                    + postProcess.modifiedChunks().size()
                    + ChatColor.GRAY + " blocks=" + ChatColor.WHITE
                    + (postProcess.blocksRemoved() + postProcess.blocksPlaced())
                    + ChatColor.GRAY + " fluids=" + ChatColor.WHITE + postProcess.fluidsRemoved());
            }
            ValousPrototypeValidator.Result prototype = valousPrototypeValidationResults.get(flight.worldName);
            if (prototype != null) {
                sender.sendMessage(ChatColor.GRAY + "  prototype=" + (prototype.passed()
                    ? ChatColor.GREEN + "PASS"
                    : ChatColor.RED + "FAIL " + prototype.failureReason()));
                sender.sendMessage(ChatColor.GRAY + "  lush_entrance=" + ChatColor.WHITE
                    + formatValousPrototypePoint(prototype.lushEntrance())
                    + ChatColor.GRAY + " molten_return=" + ChatColor.WHITE
                    + formatValousPrototypePoint(prototype.moltenReturn()));
                sender.sendMessage(ChatColor.GRAY + "  lush_to_molten=" + ChatColor.WHITE
                    + prototype.lushToMoltenSampledLength()
                    + ChatColor.GRAY + " return=" + ChatColor.WHITE
                    + prototype.moltenToSurfaceSampledLength());
            }
        }
    }

    private String formatValousPrototypePoint(ValousPrototypeValidator.BlockPoint point) {
        return point == null ? "missing" : point.x() + "," + point.y() + "," + point.z();
    }

    private void enableValousReadyFactory(CommandSender sender) {
        if (!isValousDevelopmentTestReady()) {
            sender.sendMessage(ChatColor.RED
                + "Valous development testing is not ready because its registry or template is unavailable.");
            logValousDatapackUnavailable();
            return;
        }
        if (!valousDevelopmentTestArmed) {
            valousDevelopmentTestArmed = true;
            plugin.getLogger().info("[Queue][ValousSafety] event=development_selection_allowed actor="
                + valousActorName(sender) + " profile=valous live_start=development_only"
                + " source=admin_br_valous_prepare registry_loaded=true template_ready=true");
        }
        valousReadyFactoryEnabled = true;
        sender.sendMessage(ChatColor.GREEN + "Valous ready-world factory enabled. Preparing one "
            + valousGenerationSize.key.toUpperCase(Locale.ROOT) + " development world.");
        plugin.getLogger().warning("[Queue][ValousFactory] event=enabled actor=" + valousActorName(sender)
            + " size=" + valousGenerationSize.key + " development_only=true");
        startValousReadyFactoryIfIdle("admin_prepare");
    }

    private void disableValousReadyFactory(CommandSender sender) {
        valousReadyFactoryEnabled = false;
        valousReadyFactoryReplacementPending = false;
        BrGenerationFlight flight = currentValousFactoryFlight();
        if (flight != null && !flight.isClaimed() && flight.state != BrGenerationState.ACTIVE) {
            cancelBrGenerationFlight(flight, "factory_disabled", true);
        }
        sender.sendMessage(ChatColor.YELLOW + "Valous ready-world factory disabled.");
        plugin.getLogger().warning("[Queue][ValousFactory] event=disabled actor=" + valousActorName(sender)
            + " active_world_preserved=true");
    }

    private String formatGenerationDuration(long durationMs) {
        long seconds = Math.max(0L, durationMs / 1000L);
        long hours = seconds / 3600L;
        long minutes = (seconds % 3600L) / 60L;
        long remainingSeconds = seconds % 60L;
        return hours > 0
            ? String.format(Locale.ROOT, "%dh %02dm %02ds", hours, minutes, remainingSeconds)
            : String.format(Locale.ROOT, "%dm %02ds", minutes, remainingSeconds);
    }

    private void cancelUnclaimedBrGeneration(QueueType type, String reason) {
        if (!isBattleRoyaleType(type)) {
            return;
        }
        for (BrGenerationFlight flight : new ArrayList<>(brGenerationFlights.values())) {
            if (flight.key.queueType() == type && !flight.isClaimed() && flight.state != BrGenerationState.ACTIVE) {
                cancelBrGenerationFlight(flight, reason, true);
            }
        }
    }

    private void startValousReadyFactoryIfIdle(String source) {
        if (!valousReadyFactoryEnabled
            || brTerrainProfile != BrTerrainProfile.VALOUS
            || !valousDevelopmentTestArmed
            || !isValousDevelopmentTestReady()) {
            return;
        }
        if (hasActiveMatchWorld(QueueType.SOLO) || hasActiveMatchWorld(QueueType.DUO)) {
            valousReadyFactoryReplacementPending = true;
            plugin.getLogger().info("[Queue][ValousFactory] event=prepare_deferred source=" + source
                + " reason=active_br_match");
            return;
        }
        if (valousReadyFactoryWorldName != null) {
            World ready = Bukkit.getWorld(valousReadyFactoryWorldName);
            BrGenerationFlight readyFlight = brGenerationFlightsByWorld.get(valousReadyFactoryWorldName);
            if (ready != null && readyFlight != null && readyFlight.factoryManaged
                && readyFlight.state == BrGenerationState.READY
                && readyFlight.compatibility.equals(currentBrGenerationCompatibility(QueueType.SOLO))) {
                return;
            }
            valousReadyFactoryWorldName = null;
        }
        BrGenerationFlight existing = currentValousFactoryFlight();
        if (existing != null) {
            logBrGenerationEvent(existing, "factory_waiting", source);
            return;
        }

        valousReadyFactoryReplacementPending = false;
        CompletableFuture<World> future = acquireBrGenerationFlight(QueueType.SOLO, true);
        BrGenerationFlight flight = currentValousFactoryFlight();
        if (flight == null) {
            plugin.getLogger().warning("[Queue][ValousFactory] event=prepare_failed source=" + source
                + " reason=flight_not_registered");
            return;
        }
        plugin.getLogger().warning("[Queue][ValousFactory] event=prepare_started source=" + source
            + " token=" + flight.token + " world=" + flight.worldName + " size=" + valousGenerationSize.key
            + " development_only=true");
        future.whenComplete((world, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
            if (!valousReadyFactoryEnabled || flight.canceled || !flight.factoryManaged) {
                return;
            }
            if (error != null || world == null || !isCurrentBrGenerationFlight(flight)) {
                valousReadyFactoryReplacementPending = true;
                plugin.getLogger().warning("[Queue][ValousFactory] event=prepare_failed token=" + flight.token
                    + " reason=" + (error == null ? "world_unavailable" : error.getClass().getSimpleName()));
                valousReadyFactoryEnabled = false;
                valousReadyFactoryReplacementPending = false;
                plugin.getLogger().severe("[Queue][ValousFactory] event=feasibility_run_stopped token="
                    + flight.token + " action=no_automatic_replacement");
                return;
            }
            if (flight.ownerReservationId == null) {
                valousReadyFactoryWorldName = world.getName();
                prewarmCreatedAtMs.put(world.getName(), System.currentTimeMillis());
                plugin.getLogger().warning("[Queue][ValousFactory] event=ready token=" + flight.token
                    + " world=" + world.getName() + " seed=" + world.getSeed()
                    + " size=" + valousGenerationSize.key + " development_only=true");
            }
            resolvePendingMatchStart(QueueType.SOLO);
            resolvePendingMatchStart(QueueType.DUO);
        }));
    }

    private void scheduleValousFactoryReplacement(String consumedWorldName) {
        if (!valousReadyFactoryEnabled || brTerrainProfile != BrTerrainProfile.VALOUS) {
            return;
        }
        valousReadyFactoryReplacementPending = true;
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (!valousReadyFactoryEnabled || brTerrainProfile != BrTerrainProfile.VALOUS) {
                return;
            }
            if (Bukkit.getWorld(consumedWorldName) != null
                || hasActiveMatchWorld(QueueType.SOLO)
                || hasActiveMatchWorld(QueueType.DUO)) {
                scheduleValousFactoryReplacement(consumedWorldName);
                return;
            }
            startValousReadyFactoryIfIdle("consumed_world_cleanup_complete");
        }, 100L);
    }

    private boolean hasValousDevelopmentAccess(CommandSender sender) {
        return sender != null && sender.hasPermission("hgloot.debug");
    }

    private String valousActorName(CommandSender sender) {
        return sender == null ? "system" : sender.getName();
    }

    private boolean isValousLiveBrBlocked(QueueType type) {
        return isBattleRoyaleType(type)
            && brTerrainProfile == BrTerrainProfile.VALOUS
            && (!valousDevelopmentTestArmed || !isValousDevelopmentTestReady());
    }

    private boolean rejectValousLiveBr(
        QueueType type,
        CommandSender recipient,
        String source,
        boolean explicitAttempt
    ) {
        if (!isBattleRoyaleType(type) || brTerrainProfile != BrTerrainProfile.VALOUS) {
            return false;
        }
        boolean testReady = valousDevelopmentTestArmed && isValousDevelopmentTestReady();
        boolean internalTestStep = recipient == null;
        boolean authorizedTester = recipient != null && hasValousDevelopmentAccess(recipient);
        if (testReady && (internalTestStep || authorizedTester)) {
            return false;
        }
        if (recipient != null) {
            recipient.sendMessage(testReady
                ? ChatColor.RED + "Valous testing is limited to Dev and Owner players."
                : ChatColor.RED + "Valous testing is unavailable because its datapack registries are not loaded."
                    + " Enable file/hydra_valous.zip and restart the server.");
        }
        String logKey = type.key() + ":" + source;
        if (explicitAttempt || valousSafetyLoggedSources.add(logKey)) {
            plugin.getLogger().warning("[Queue][ValousSafety] event=valous_start_blocked queue="
                + type.key() + " source=" + source + " generation="
                + matchWorldGenerationMode.name().toLowerCase(Locale.ROOT));
        }
        return true;
    }

    private void logValousDatapackUnavailable() {
        if (brTerrainProfile != BrTerrainProfile.VALOUS
            || !valousSafetyLoggedSources.add("datapack_unavailable")) {
            return;
        }
        plugin.getLogger().warning("[Queue][ValousSafety] event=datapack_unavailable profile=valous"
            + " reason=registry_or_template_unavailable action=br_disabled");
    }

    private boolean isValousDevelopmentTestReady() {
        return isValousRegistryLoaded() && isValousTemplateAvailable();
    }

    private boolean isValousRegistryLoaded() {
        NamespacedKey mushroomThicket = NamespacedKey.fromString("hydra_valous:mushroom_thicket");
        return mushroomThicket != null && Registry.BIOME.get(mushroomThicket) != null;
    }

    private boolean isValousTemplateAvailable() {
        Path templatePath = Bukkit.getWorldContainer().toPath().resolve(VALOUS_TEMPLATE_WORLD_NAME);
        return Files.isDirectory(templatePath)
            && Files.isRegularFile(templatePath.resolve("level.dat"))
            && Files.isRegularFile(templatePath.resolve("datapacks").resolve(VALOUS_DATAPACK_FILE_NAME));
    }

    private void clearStaleHungerGamesPrewarm() {
        for (QueueType type : List.of(QueueType.HUNGERGAMES, QueueType.HUNGERGAMES_DUOS)) {
            clearStaleHungerGamesPrewarm(type);
        }
    }

    private void clearStaleHungerGamesPrewarm(QueueType type) {
        List<String> worldNames = prewarmedMatchWorldsFor(type);
        prewarmedMatchWorldsByType.remove(type);
        prewarmCooldownUntilMs.remove(type);
        for (String worldName : worldNames) {
            prewarmCreatedAtMs.remove(worldName);
            if (activeMatchWorldsFor(type).contains(worldName)) {
                continue;
            }
            cleanupOrDetachPrewarmedWorld(worldName, "[Queue] Cleared stale Hunger Games prewarm world");
        }
    }

    private List<HungerGamesMapDefinition> availableHungerGamesMapDefinitions() {
        List<HungerGamesMapDefinition> available = new ArrayList<>();
        for (HungerGamesMapDefinition definition : hungerGamesMapDefinitions()) {
            if (resolveHydraStructure(normalizeStructureId(definition.structureId())) != null) {
                available.add(definition);
            }
        }
        return available;
    }

    private HungerGamesMapDefinition chooseHungerGamesMapForMatch() {
        String selectionKey = normalizeHungerGamesMapKey(hungerGamesMapSelectionKey);
        if (RANDOM_HUNGER_GAMES_MAP_KEY.equals(selectionKey)) {
            List<HungerGamesMapDefinition> available = availableHungerGamesMapDefinitions();
            if (available.isEmpty()) {
                return resolveHungerGamesMapDefinition(hungerGamesStructureId, hungerGamesMapName);
            }
            return available.get(ThreadLocalRandom.current().nextInt(available.size()));
        }
        HungerGamesMapDefinition selected = resolveHungerGamesMapDefinition(hungerGamesStructureId, hungerGamesMapName);
        if (selected != null) {
            return selected;
        }
        return hungerGamesMapDefinitionByKey(selectionKey);
    }

    public boolean isPlayerInMatch(UUID playerId) {
        return playerId != null && inMatchPlayers.contains(playerId);
    }

    public boolean isPlayerInHydraMatchOrSpectating(UUID playerId) {
        return playerId != null && (inMatchPlayers.contains(playerId) || spectatingMatchWorlds.containsKey(playerId));
    }

    public boolean isCustomSpectator(UUID playerId) {
        return playerId != null && spectatingMatchWorlds.containsKey(playerId);
    }

    public boolean spectateTargetMatch(Player spectator, Player target) {
        return spectateTargetMatch(spectator, target, spectatableMatchId(target));
    }

    public String spectatableMatchId(Player target) {
        if (target == null || !target.isOnline() || target.getWorld() == null) return null;
        UUID targetId = target.getUniqueId();
        String worldName = inMatchWorlds.get(targetId);
        if (worldName == null) worldName = spectatingMatchWorlds.get(targetId);
        if (worldName == null || !isSameMatchSessionWorld(worldName, target.getWorld().getName())) return null;
        QueueType type = resolveQueueTypeForWorld(worldName);
        String root = rootMatchWorldName(worldName);
        return type == null || root == null ? null : "queue:" + type.key() + ":" + root;
    }

    public boolean spectateTargetMatch(Player spectator, Player target, String expectedMatchId) {
        if (spectator == null || target == null || !spectator.isOnline() || !target.isOnline()) {
            return false;
        }
        if (expectedMatchId == null || !expectedMatchId.equals(spectatableMatchId(target))) return false;
        UUID spectatorId = spectator.getUniqueId();
        UUID targetId = target.getUniqueId();
        if (spectatorId.equals(targetId)) {
            spectator.sendMessage(ChatColor.RED + "You cannot spectate yourself.");
            return true;
        }
        String worldName = inMatchWorlds.get(targetId);
        if (worldName == null) {
            worldName = spectatingMatchWorlds.get(targetId);
        }
        if (worldName == null) {
            return false;
        }
        if (isPlayerActivelyQueuedOrBound(spectatorId)) {
            spectator.sendMessage(ChatColor.RED + "Leave your queue before spectating a match.");
            return true;
        }
        if (inMatchPlayers.contains(spectatorId) || spectatingMatchWorlds.containsKey(spectatorId)) {
            String currentWorld = inMatchWorlds.get(spectatorId);
            if (currentWorld == null) {
                currentWorld = spectatingMatchWorlds.get(spectatorId);
            }
            if (currentWorld != null && isSameMatchSessionWorld(currentWorld, worldName)) {
                spectator.sendMessage(ChatColor.RED + "You are already in that match.");
                return true;
            }
            spectator.sendMessage(ChatColor.RED + "Leave your current match before spectating another one.");
            return true;
        }
        QueueType type = resolveQueueTypeForWorld(worldName);
        if (type == null) {
            return false;
        }
        String destinationWorld = worldName;
        return transitionTravel(spectator, () -> {
            String currentTargetWorld = inMatchWorlds.get(targetId);
            if (currentTargetWorld == null) currentTargetWorld = spectatingMatchWorlds.get(targetId);
            if (!target.isOnline() || !isSameMatchSessionWorld(destinationWorld, currentTargetWorld)
                || !expectedMatchId.equals(spectatableMatchId(target))
                || isPlayerActivelyQueuedOrBound(spectatorId)
                || inMatchPlayers.contains(spectatorId) || spectatingMatchWorlds.containsKey(spectatorId)) {
                spectator.sendMessage(ChatColor.RED + "That match is no longer available to spectate.");
                if (plugin instanceof HGLootPlugin hydra)
                    SpectatorRouteTrace.midpoint(hydra, spectator, target, expectedMatchId, false);
                return;
            }
            spectator.teleport(target.getLocation());
            setCustomSpectatorState(spectator, destinationWorld, true);
            if (plugin instanceof HGLootPlugin hydra)
                SpectatorRouteTrace.midpoint(hydra, spectator, target, expectedMatchId, true);
        });
    }

    private boolean transitionTravel(Player player, Runnable midpoint) {
        if (plugin instanceof HGLootPlugin hydra) return hydra.transitionTravel(player, midpoint);
        midpoint.run();
        return true;
    }

    public String playerAudienceKey(Player player) {
        if (player == null || !player.isOnline()) {
            return null;
        }
        UUID playerId = player.getUniqueId();
        String worldName = inMatchWorlds.get(playerId);
        if (worldName == null) {
            worldName = spectatingMatchWorlds.get(playerId);
        }
        if (worldName == null) {
            return null;
        }
        String currentWorldName = player.getWorld() == null ? null : player.getWorld().getName();
        if (currentWorldName == null || !isSameMatchSessionWorld(worldName, currentWorldName)) {
            return null;
        }
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null) {
            return null;
        }
        QueueType type = inMatchTypes.get(playerId);
        if (type == null) {
            type = resolveQueueTypeForWorld(worldName);
        }
        String prefix = isHungerGames(type) ? "hg" : "br";
        return prefix + ":" + rootWorldName;
    }

    public boolean isMatchAudienceSpectator(UUID playerId) {
        return isCustomSpectator(playerId);
    }

    public boolean isMatchAudienceAlive(UUID playerId) {
        return playerId != null && inMatchPlayers.contains(playerId) && !spectatingMatchWorlds.containsKey(playerId);
    }

    public boolean canUseLegendaryCombat(Player player) {
        if (player == null || !player.isOnline() || player.isDead()
            || player.getGameMode() == GameMode.SPECTATOR) {
            return false;
        }
        UUID playerId = player.getUniqueId();
        if (isMatchAudienceAlive(playerId)) {
            return playerAudienceKey(player) != null
                && !isHungerGamesStartFrozen(player)
                && !isHungerGamesCombatGraceActive(player);
        }
        return player.hasPermission("hgloot.debug")
            && !isLobbyWorld(player)
            && !isPlayerQueued(playerId)
            && !isCustomSpectator(playerId)
            && player.getWorld() != null
            && player.getWorld().getPVP();
    }

    public boolean isLegalLegendaryCombatTarget(Player attacker, Player target) {
        if (attacker == null || target == null || !target.isOnline() || target.isDead()
            || target.getGameMode() == GameMode.SPECTATOR || target.isInvulnerable()
            || attacker.getWorld() == null || !attacker.getWorld().equals(target.getWorld())) {
            return false;
        }
        UUID attackerId = attacker.getUniqueId();
        UUID targetId = target.getUniqueId();
        if (isMatchAudienceAlive(attackerId)) {
            return isMatchAudienceAlive(targetId)
                && Objects.equals(playerAudienceKey(attacker), playerAudienceKey(target));
        }
        return attacker.hasPermission("hgloot.debug")
            && !isLobbyWorld(attacker)
            && !isLobbyWorld(target)
            && !isPlayerQueued(attackerId)
            && !isCustomSpectator(attackerId)
            && !isCustomSpectator(targetId);
    }

    public boolean isProtectedMatchTeammate(UUID firstPlayerId, UUID secondPlayerId) {
        if (firstPlayerId == null || secondPlayerId == null
            || !inMatchPlayers.contains(firstPlayerId) || !inMatchPlayers.contains(secondPlayerId)) {
            return false;
        }
        String firstWorld = inMatchWorlds.get(firstPlayerId);
        String secondWorld = inMatchWorlds.get(secondPlayerId);
        return firstWorld != null && secondWorld != null
            && isSameMatchSessionWorld(firstWorld, secondWorld)
            && sameActiveDuoTeam(firstPlayerId, secondPlayerId);
    }

    public boolean isPlayerQueued(UUID playerId) {
        return playerId != null && queuedPlayers.containsKey(playerId);
    }

    public boolean isPlayerActivelyQueuedOrBound(UUID playerId) {
        if (playerId == null) return false;
        QueueType type = queuedPlayers.get(playerId);
        return (type != null && queues.get(type) != null && queues.get(type).contains(playerId))
            || pendingMatchLaunches.containsKey(playerId);
    }

    public boolean isPlayerCommittedToMatchStart(UUID playerId) {
        return playerId != null && pendingMatchLaunches.containsKey(playerId);
    }

    public boolean isPlayerQueuedFor(UUID playerId, QueueType type) {
        return playerId != null && type != null && queuedPlayers.get(playerId) == type;
    }

    public static boolean isHungerGames(QueueType type) {
        return type == QueueType.HUNGERGAMES || type == QueueType.HUNGERGAMES_DUOS;
    }

    public boolean isLobbyWorld(Player player) {
        if (player == null || player.getWorld() == null) {
            return false;
        }
        if (lobbySpawn == null || lobbySpawn.getWorld() == null) {
            return !isPlayerQueued(player.getUniqueId()) && !isPlayerInHydraMatchOrSpectating(player.getUniqueId());
        }
        return Objects.equals(player.getWorld().getUID(), lobbySpawn.getWorld().getUID());
    }

    public int hungerGamesTabActivityCount() {
        return tabActivityCount(QueueType.HUNGERGAMES) + tabActivityCount(QueueType.HUNGERGAMES_DUOS);
    }

    /** Read-only TAB data for the exact match that currently owns this viewer. */
    public TabMatchSnapshot tabMatchSnapshot(Player viewer) {
        if (viewer == null || playerAudienceKey(viewer) == null) return null;
        UUID playerId = viewer.getUniqueId();
        String trackedWorld = inMatchWorlds.get(playerId);
        if (trackedWorld == null) trackedWorld = spectatingMatchWorlds.get(playerId);
        String rootWorld = rootMatchWorldName(trackedWorld);
        QueueType type = resolveQueueTypeForWorld(rootWorld);
        if (rootWorld == null || type == null || !isActiveMatchWorldValue(rootWorld)) return null;
        String mode = isHungerGames(type)
            ? (type == QueueType.HUNGERGAMES_DUOS ? "HG DUOS" : "HG SOLOS")
            : "BATTLE ROYALE";
        Integer borderSeconds = null;
        World world = Bukkit.getWorld(rootWorld);
        if (isHungerGames(type)) borderSeconds = matchBorderService.tabCountdown(world, rootWorld,
            borderSettingsForWorld(rootWorld), System.currentTimeMillis());
        return new TabMatchSnapshot(mode, activeParticipantCountInWorld(rootWorld), borderSeconds);
    }

    public record TabMatchSnapshot(String mode, int alive, Integer borderSeconds) {}

    public int battleRoyaleTabActivityCount() {
        return tabActivityCount(QueueType.SOLO) + tabActivityCount(QueueType.DUO);
    }

    public int battleRoyaleWaitingCount() {
        return queueSize(QueueType.SOLO) + queueSize(QueueType.DUO);
    }

    public int battleRoyalePlayingCount() {
        return activePlayerCount(QueueType.SOLO) + activePlayerCount(QueueType.DUO);
    }

    public int hungerGamesWaitingCount() {
        return queueSize(QueueType.HUNGERGAMES) + queueSize(QueueType.HUNGERGAMES_DUOS);
    }

    public int hungerGamesPlayingCount() {
        return activePlayerCount(QueueType.HUNGERGAMES) + activePlayerCount(QueueType.HUNGERGAMES_DUOS);
    }

    public String gameHubOwnershipTag(UUID playerId) {
        if (playerId == null) {
            return null;
        }
        if (plugin instanceof HGLootPlugin hydra && hydra.networkBridgeService() != null) {
            String networkTag = hydra.networkBridgeService().ownershipTag(playerId);
            if (networkTag != null) {
                return networkTag;
            }
        }
        if (plugin instanceof HGLootPlugin hydra
            && hydra.minigameRouletteService() != null
            && hydra.minigameRouletteService().isTournamentMember(playerId)) {
            return "MR";
        }
        QueueType type = queuedPlayers.get(playerId);
        if (type == null) {
            type = inMatchTypes.get(playerId);
        }
        if (type == null) {
            String spectatorWorld = spectatingMatchWorlds.get(playerId);
            type = spectatorWorld == null ? null : resolveQueueTypeForWorld(spectatorWorld);
        }
        if (isHungerGames(type)) {
            return "HG";
        }
        return type == QueueType.SOLO || type == QueueType.DUO ? "BR" : null;
    }

    private int activePlayerCount(QueueType type) {
        int count = 0;
        for (UUID playerId : inMatchPlayers) {
            if (inMatchTypes.get(playerId) == type && !spectatingMatchWorlds.containsKey(playerId)) {
                count++;
            }
        }
        return count;
    }

    private int miniGamesTabActivityCount() {
        if (!(plugin instanceof HGLootPlugin hydra)) {
            return 0;
        }
        int directMinigameCount = 0;
        if (hydra.spleefService() != null) {
            directMinigameCount += hydra.spleefService().tabActivityCount();
        }
        if (hydra.voidRouletteService() != null) {
            directMinigameCount += hydra.voidRouletteService().tabActivityCount();
        }
        if (hydra.bridgeService() != null) {
            directMinigameCount += hydra.bridgeService().tabActivityCount();
        }
        int rouletteCount = hydra.minigameRouletteService() == null
            ? 0
            : hydra.minigameRouletteService().sidebarActivityCount();
        return Math.max(directMinigameCount, rouletteCount);
    }

    private int tabActivityCount(QueueType type) {
        if (type == null) {
            return 0;
        }
        LinkedHashSet<UUID> players = new LinkedHashSet<>();
        LinkedHashSet<UUID> queue = queues.get(type);
        if (queue != null) {
            players.addAll(queue);
        }
        for (UUID playerId : inMatchPlayers) {
            if (inMatchTypes.get(playerId) == type) {
                players.add(playerId);
            }
        }
        for (Map.Entry<UUID, String> entry : spectatingMatchWorlds.entrySet()) {
            QueueType spectatorType = resolveQueueTypeForWorld(entry.getValue());
            if (spectatorType == type) {
                players.add(entry.getKey());
            }
        }
        return players.size();
    }

    public boolean rejoinBattleRoyale(Player player, boolean automatic) {
        if (player == null || !player.isOnline()) {
            return false;
        }
        UUID playerId = player.getUniqueId();
        BattleRoyalePlayerSnapshot snapshot = brRejoinSnapshots.get(playerId);
        if (snapshot == null) {
            if (!automatic) {
                if (inMatchPlayers.contains(playerId) || spectatingMatchWorlds.containsKey(playerId)) {
                    player.sendMessage(ChatColor.YELLOW + "Already in a match.");
                } else {
                    player.sendMessage(ChatColor.RED + "No match to rejoin.");
                }
            }
            return false;
        }
        if (!hasActiveMatchSession(snapshot.type, snapshot.worldName)) {
            clearBattleRoyaleSnapshots(playerId);
            if (!automatic) {
                player.sendMessage(ChatColor.RED + "Match no longer active.");
            }
            return false;
        }

        boolean restored = snapshot.spectator
            ? restoreBattleRoyaleSpectatorState(player, snapshot)
            : restoreBattleRoyaleLiveState(player, snapshot, false);
        if (!restored) {
            if (!automatic) {
                player.sendMessage(ChatColor.RED + "Rejoin failed.");
            }
            return false;
        }

        brRejoinSnapshots.remove(playerId);
        removeReconnectZombie(playerId, false);
        player.sendMessage(ChatColor.GREEN + (snapshot.spectator
            ? "Rejoined as spectator."
            : "Rejoined match."));
        return true;
    }

    public boolean reviveBattleRoyale(CommandSender sender, Player target) {
        return reviveQueuedMatch(sender, target, QueueType.SOLO, QueueType.DUO);
    }

    public boolean reviveHungerGames(CommandSender sender, Player target) {
        return reviveQueuedMatch(sender, target, QueueType.HUNGERGAMES, QueueType.HUNGERGAMES_DUOS);
    }

    public boolean reviveAnyMatch(CommandSender sender, Player target) {
        return reviveQueuedMatch(sender, target, QueueType.SOLO, QueueType.DUO,
            QueueType.HUNGERGAMES, QueueType.HUNGERGAMES_DUOS);
    }

    private boolean reviveQueuedMatch(CommandSender sender, Player target, QueueType... allowedTypes) {
        if (target == null || !target.isOnline()) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "That player is not online.");
            }
            return false;
        }
        UUID targetId = target.getUniqueId();
        if (inMatchPlayers.contains(targetId)) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + target.getName() + " is already alive in a match.");
            }
            return false;
        }
        BattleRoyalePlayerSnapshot snapshot = brReviveSnapshots.get(targetId);
        if (snapshot == null) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "No revive snapshot is available for " + target.getName() + ".");
            }
            return false;
        }
        boolean allowed = false;
        for (QueueType allowedType : allowedTypes) {
            if (snapshot.type == allowedType) {
                allowed = true;
                break;
            }
        }
        if (!allowed) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + target.getName() + " does not have a revive snapshot for that queue.");
            }
            return false;
        }
        if (!hasActiveMatchSession(snapshot.type, snapshot.worldName)) {
            clearBattleRoyaleSnapshots(targetId);
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "That match is no longer active.");
            }
            return false;
        }
        if (!restoreBattleRoyaleLiveState(target, snapshot, true)) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "Could not revive " + target.getName() + ".");
            }
            return false;
        }

        brRejoinSnapshots.remove(targetId);
        brReviveSnapshots.remove(targetId);
        return true;
    }

    public int borderShrinkTimerRemaining(World world) {
        if (world == null || !isActiveMatchWorldValue(world.getName())) return -1;
        return matchBorderService.timerRemaining(world.getName(), borderShrinkIntervalSecondsForWorld(world.getName()),
            System.currentTimeMillis());
    }

    public int adjustBorderShrinkTimer(World world, int deltaSeconds) {
        if (world == null || !isActiveMatchWorldValue(world.getName())
            || borderShrinkStepForWorld(world.getName()) <= 0.0D) return -1;
        return matchBorderService.adjustTimer(world.getName(), borderShrinkIntervalSecondsForWorld(world.getName()),
            deltaSeconds, System.currentTimeMillis());
    }

    public void start() {
        if (tickTask != null) {
            tickTask.cancel();
        }
        if (fakePcsPlaneTask != null) {
            fakePcsPlaneTask.cancel();
        }
        if (hungerGamesDuoGlowTask != null) {
            hungerGamesDuoGlowTask.cancel();
        }
        tickTask = Bukkit.getScheduler().runTaskTimer(plugin, this::tickQueues, 20L, 20L);
        fakePcsPlaneTask = Bukkit.getScheduler().runTaskTimer(plugin, this::tickFakePcsPlaneRides, 1L, 1L);
        hungerGamesDuoGlowTask = Bukkit.getScheduler().runTaskTimer(
            plugin,
            this::refreshHungerGamesDuoGlows,
            10L,
            10L
        );
        boolean standalone = !(plugin instanceof HGLootPlugin hydra) || hydra.networkNodeConfig() == null
            || !hydra.networkNodeConfig().enabled();
        boolean hungerGamesNode = plugin instanceof HGLootPlugin hydra
            && hydra.networkNodeConfig() != null
            && hydra.networkNodeConfig().role() == hgloot.plugin.network.BackendRole.HG;
        if (standalone) {
            ensureBundledHellscapeStructureTemplatesAvailable();
            ensureBundledHungerGamesMapStructureTemplatesAvailable();
            prepareGlobalStructureTemplates();
            preloadHungerGamesMapStructures();
            Bukkit.getScheduler().runTaskLater(plugin, () -> cleanupStaleMatchWorldFolders(null, null), 5L);
            Bukkit.getScheduler().runTaskLater(plugin, () -> startupPrewarmMatchWorld(QueueType.HUNGERGAMES), 40L);
        } else if (hungerGamesNode) {
            ensureBundledHungerGamesMapStructureTemplatesAvailable();
            prepareGlobalStructureTemplates();
            Bukkit.getScheduler().runTaskLater(plugin, () -> cleanupStaleMatchWorldFolders(null, null), 5L);
            Bukkit.getScheduler().runTaskLater(plugin, () -> startupPrewarmMatchWorld(QueueType.HUNGERGAMES), 40L);
        }
        Bukkit.getScheduler().runTaskLater(plugin, this::clearLegacyDebugLeaderboards, 30L);
        Bukkit.getScheduler().runTaskLater(plugin, this::refreshAllDebugLeaderboards, 40L);
    }

    private void preloadHungerGamesMapStructures() {
        long startedAt = System.currentTimeMillis();
        int loaded = 0;
        LinkedHashSet<String> targetIds = new LinkedHashSet<>();
        for (HungerGamesMapDefinition definition : hungerGamesMapDefinitions()) {
            targetIds.add(normalizeStructureId(definition.structureId()));
        }
        if (!hungerGamesStructureId.isBlank()) {
            targetIds.add(normalizeStructureId(hungerGamesStructureId));
        }
        for (String structureId : targetIds) {
            if (structureId.isBlank()) {
                continue;
            }
            if (resolveHydraStructure(structureId) != null) {
                loaded++;
            } else {
                plugin.getLogger().warning("[Queue] Could not preload Hunger Games map structure " + structureId + ".");
            }
        }
        long elapsed = System.currentTimeMillis() - startedAt;
        if (loaded > 0) {
            plugin.getLogger().info("[Queue] Preloaded " + loaded + " Hunger Games map structure(s) into cache in "
                + elapsed + "ms.");
        }
    }

    private void startupPrewarmMatchWorld(QueueType type) {
        if (type == null || !matchWorldEnabled) {
            return;
        }
        String activeWorld = primaryActiveMatchWorld(type);
        if (!isHungerGames(type) && activeWorld != null && hasMatchPlayersInWorld(activeWorld)) {
            return;
        }
        if (!shouldRequestPrewarmedMatchWorld(type)) {
            return;
        }
        if (System.currentTimeMillis() < prewarmCooldownUntilMs.getOrDefault(type, 0L)) {
            return;
        }
        if (!prewarmInProgress.add(type)) {
            return;
        }
        createMatchWorldAsync(type).whenComplete((world, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
            try {
                if (error != null) {
                    prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + 10_000L);
                    plugin.getLogger().warning("[Queue] startup prewarm failed for " + type.displayName()
                        + ": " + error.getMessage());
                    return;
                }
                if (world == null) {
                    prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + 10_000L);
                    plugin.getLogger().warning("[Queue] startup prewarm failed: could not create world for " + type.displayName());
                    return;
                }
                String worldName = world.getName();
                String currentActive = primaryActiveMatchWorld(type);
                if (!isHungerGames(type) && currentActive != null && hasMatchPlayersInWorld(currentActive)) {
                    cleanupOrDetachPrewarmedWorld(worldName,
                        "[Queue] Discarded startup prewarm because an active match is already using " + currentActive);
                    return;
                }
                if (!isBattleRoyaleType(type)
                    && hasEnoughCompletedPrewarmedMatchWorlds(type)
                    && !hasPendingMatchStart(type)) {
                    cleanupOrDetachPrewarmedWorld(worldName,
                        "[Queue] Discarded duplicate startup prewarm for " + type.displayName());
                    return;
                }
                addPrewarmedMatchWorld(type, worldName);
                plugin.getLogger().info("[Queue] Startup-prewarmed " + type.displayName() + " world: " + worldName);
            } finally {
                prewarmInProgress.remove(type);
                resolvePendingMatchStart(type);
            }
        }));
    }

    /**
     * When enabled, keep one Hunger Games arena prepared in the background even with an
     * empty queue, and rebuild the next one after a match consumes the ready arena. Reuses
     * the queue-independent startup prewarm path (which no-ops if one is ready/in progress).
     */
    private void maybeKeepHungerGamesReadyArena(QueueType type) {
        if (!matchWorldEnabled || !hungerGamesKeepReadyArena) {
            return;
        }
        startupPrewarmMatchWorld(type);
    }

    private void preloadCornucopiaTemplateIdle() {
        if (!cornucopiaSpawnStructureEnabled) {
            return;
        }
        if (cornucopiaTemplatePreloaded) {
            return;
        }
        String structureId = normalizeStructureId(cornucopiaStructureId);
        if (structureId.isBlank()) {
            return;
        }
        World world = Bukkit.getWorlds().stream()
            .filter(w -> w.getEnvironment() == World.Environment.NORMAL)
            .findFirst()
            .orElse(null);
        if (world == null) {
            return;
        }

        int x = world.getSpawnLocation().getBlockX() + 8192;
        int z = world.getSpawnLocation().getBlockZ() + 8192;
        int y = Math.max(world.getMinHeight() + 1, Math.min(world.getMaxHeight() - 2, 100));
        String command = "execute in " + commandWorldId(world)
            + " run place template " + structureId + " " + x + " " + y + " " + z;
        boolean dispatched = Bukkit.dispatchCommand(Bukkit.getConsoleSender(), command);
        cornucopiaTemplatePreloaded = true;
        plugin.getLogger().info("Cornucopia template preload requested for " + structureId
            + " in " + world.getName() + " (dispatch=" + dispatched + ").");
    }

    public void shutdown() {
        shuttingDown = true;
        ValousWorldReviewExporter.Job reviewJob = valousWorldReviewExportJob;
        valousWorldReviewExportJob = null;
        if (reviewJob != null) {
            reviewJob.cancel();
        }
        savePlayerStats();
        if (tickTask != null) {
            tickTask.cancel();
            tickTask = null;
        }
        if (fakePcsPlaneTask != null) {
            fakePcsPlaneTask.cancel();
            fakePcsPlaneTask = null;
        }
        if (hungerGamesDuoGlowTask != null) {
            hungerGamesDuoGlowTask.cancel();
            hungerGamesDuoGlowTask = null;
        }
        clearHungerGamesDuoGlows();
        for (UUID playerId : new ArrayList<>(fakePcsStates.keySet())) {
            Player player = Bukkit.getPlayer(playerId);
            if (player != null && player.isOnline()) {
                clearFakePcsState(player);
            }
        }
        for (UUID playerId : new ArrayList<>(hungerGamesCombatGraceUntilMs.keySet())) {
            Player player = Bukkit.getPlayer(playerId);
            if (player != null && player.isOnline()) {
                player.removePotionEffect(PotionEffectType.FIRE_RESISTANCE);
            }
        }
        hungerGamesCombatGraceUntilMs.clear();
        queues.values().forEach(Set::clear);
        queuedPlayers.clear();
        pendingMatchLaunches.clear();
        inMatchPlayers.clear();
        inMatchTypes.clear();
        inMatchWorlds.clear();
        duoTeamByPlayer.clear();
        hungerGamesLocalLobbyIds.clear();
        hungerGamesLaunchCallbacksInFlight.clear();
        hungerGamesDuoWorlds.clear();
        hungerGamesDuoRosters.clear();
        hungerGamesDuoTeamColors.clear();
        matchKills.clear();
        hungerGamesUtilityCrafts.clear();
        lifetimeKills.clear();
        lifetimeWins.clear();
        brLifetimeKills.clear();
        hgLifetimeKills.clear();
        brLifetimeWins.clear();
        hgLifetimeWins.clear();
        rouletteLifetimeWins.clear();
        lifetimeDamageDealt.clear();
        brLifetimeDamageDealt.clear();
        hgLifetimeDamageDealt.clear();
        matchStartedAtMs.clear();
        matchBorderService.clearAll();
        brTestParticipants.clear();
        brDevelopmentTestQueues.clear();
        brDevelopmentTestWorlds.clear();
        cornucopiaCampEnteredAtMs.clear();
        cornucopiaCampWarned.clear();
        cornucopiaCampNextPressureAtMs.clear();
        matchWorldService.clearOwnership();
        prewarmedMatchWorldsByType.clear();
        managedMatchWorldTypes.clear();
        prewarmInProgress.clear();
        prewarmCooldownUntilMs.clear();
        prewarmCreatedAtMs.clear();
        matchWorldPrepareNoticeAtMs.clear();
        pendingMatchStarts.clear();
        brMatchStartRetryTokens.clear();
        endingMatchWorlds.clear();
        for (WorldChunkPreloadState state : fullWorldPreloadStates.values()) {
            if (state.task != null) {
                state.task.cancel();
            }
        }
        fullWorldPreloadStates.clear();
        for (BrGenerationFlight flight : new ArrayList<>(brGenerationFlights.values())) {
            flight.canceled = true;
            if (!flight.completionFuture.isDone()) {
                flight.completionFuture.complete(null);
            }
        }
        brGenerationFlights.clear();
        brGenerationFlightsByWorld.clear();
        brWorldPreparationStates.clear();
        fakePcsStates.clear();
        fakePcsOriginalChestplates.clear();
        clearAllFakePcsPlaneDisplays();
        fakePcsPlaneDisplayIds.clear();
        clearAllFakePcsDiveDisplays();
        fakePcsDiveDisplayIds.clear();
        fakePcsDiveAnimFrames.clear();
        fakePcsDiveAnimStartedTicks.clear();
        fakePcsOriginalInvisibleStates.clear();
        pendingSpectatorRespawnWorld.clear();
        spectatingMatchWorlds.clear();
        cleanupAllReconnectBodies(false);
        brRejoinSnapshots.clear();
        brReviveSnapshots.clear();
        reconnectZombieExpiresAtMs.clear();
        countdowns.clear();
        structureRejectSummaries.clear();
        structureRuleOverrides.clear();
        structureRuleCache.clear();
        for (BukkitTask task : winnerReturnTasks.values()) {
            task.cancel();
        }
        winnerReturnTasks.clear();
        for (HungerGamesPlacedBlock placement : hungerGamesPlacedBlocks.values()) {
            if (placement.task != null) placement.task.cancel();
        }
        hungerGamesPlacedBlocks.clear();
        for (BukkitTask task : hungerGamesKothStartTasks.values()) {
            task.cancel();
        }
        hungerGamesKothStartTasks.clear();
        hungerGamesKothStartAtMs.clear();
        for (BukkitTask task : hungerGamesChestRefillTasks.values()) {
            task.cancel();
        }
        hungerGamesChestRefillTasks.clear();
        hungerGamesChestRefillCompleted.clear();
        for (List<BukkitTask> taskGroup : hungerGamesChestRefillWarningTasks.values()) {
            if (taskGroup == null) {
                continue;
            }
            for (BukkitTask task : taskGroup) {
                if (task != null) {
                    task.cancel();
                }
            }
        }
        hungerGamesChestRefillWarningTasks.clear();
        hungerGamesChestRefillDelaySecondsByWorld.clear();
        for (List<BukkitTask> taskGroup : cornucopiaRefillTasks.values()) {
            if (taskGroup == null) {
                continue;
            }
            for (BukkitTask task : taskGroup) {
                if (task != null) {
                    task.cancel();
                }
            }
        }
        cornucopiaRefillTasks.clear();
        hungerGamesLootPlans.clear();
        STRUCTURE_PROTECTION_MASKS.clear();
        if (matchWorldAutoCleanup) {
            for (String worldName : new ArrayList<>(managedMatchWorlds)) {
                cleanupWorld(worldName);
            }
        }
    }

