    private String queueAudienceLabel(QueueType type) {
        return switch (type) {
            case SOLO -> "Solo Queue";
            case DUO -> "Duo Queue";
            case HUNGERGAMES, HUNGERGAMES_DUOS -> hungerGamesQueueModeLabel(type) + " Queue";
        };
    }

    private String hungerGamesQueueModeLabel(QueueType type) {
        return type == QueueType.HUNGERGAMES_DUOS
            ? "Hunger Games Duos"
            : "Hunger Games Solos";
    }

    private String hungerGamesMatchModeLabel(String worldName) {
        return hungerGamesDuoWorlds.contains(rootMatchWorldName(worldName))
            ? "Hunger Games Duos"
            : "Hunger Games Solos";
    }

