    public void setLifetimeKills(UUID playerId, int kills) {
        if (playerId == null) {
            return;
        }
        int safeKills = Math.max(0, kills);
        if (safeKills == 0) {
            lifetimeKills.remove(playerId);
        } else {
            lifetimeKills.put(playerId, safeKills);
        }
        savePlayerStats();
        refreshStatsPresentation(playerId);
    }

    public void setLifetimeWins(UUID playerId, int wins) {
        if (playerId == null) {
            return;
        }
        int safeWins = Math.max(0, wins);
        if (safeWins == 0) {
            lifetimeWins.remove(playerId);
        } else {
            lifetimeWins.put(playerId, safeWins);
        }
        savePlayerStats();
        refreshStatsPresentation(playerId);
    }

    public void setLifetimeWins(UUID playerId, String mode, int wins) {
        if (playerId == null) {
            return;
        }
        String normalizedMode = mode == null ? "total" : mode.toLowerCase(Locale.ROOT);
        int safeWins = Math.max(0, wins);
        Map<UUID, Integer> target = switch (normalizedMode) {
            case "hg", "hungergames", "hunger_games" -> hgLifetimeWins;
            case "br", "battleroyale", "battle_royale" -> brLifetimeWins;
            case "all", "total", "overall" -> lifetimeWins;
            default -> null;
        };
        if (target == null) {
            return;
        }
        if (safeWins == 0) {
            target.remove(playerId);
        } else {
            target.put(playerId, safeWins);
        }
        if (target != lifetimeWins) {
            int combinedWins = brLifetimeWins.getOrDefault(playerId, 0) + hgLifetimeWins.getOrDefault(playerId, 0);
            if (combinedWins == 0) {
                lifetimeWins.remove(playerId);
            } else {
                lifetimeWins.put(playerId, combinedWins);
            }
        }
        savePlayerStats();
        refreshStatsPresentation(playerId);
    }

    public void resetLifetimeWins(UUID playerId) {
        if (playerId == null) {
            return;
        }
        lifetimeWins.remove(playerId);
        brLifetimeWins.remove(playerId);
        hgLifetimeWins.remove(playerId);
        rouletteLifetimeWins.remove(playerId);
        savePlayerStats();
        refreshStatsPresentation(playerId);
    }

    public void resetLifetimeWins(UUID playerId, String mode) {
        if (playerId == null) {
            return;
        }
        String normalizedMode = mode == null ? "all" : mode.toLowerCase(Locale.ROOT);
        switch (normalizedMode) {
            case "hg", "hungergames", "hunger_games" -> hgLifetimeWins.remove(playerId);
            case "br", "battleroyale", "battle_royale" -> brLifetimeWins.remove(playerId);
            case "all", "total", "overall" -> {
                resetLifetimeWins(playerId);
                return;
            }
            default -> {
                return;
            }
        }
        int combinedWins = brLifetimeWins.getOrDefault(playerId, 0) + hgLifetimeWins.getOrDefault(playerId, 0);
        if (combinedWins == 0) {
            lifetimeWins.remove(playerId);
        } else {
            lifetimeWins.put(playerId, combinedWins);
        }
        savePlayerStats();
        refreshStatsPresentation(playerId);
    }

