    public void joinQueue(Player player, QueueType type) {
        joinQueue(player, type, true);
    }

    public void forceJoinQueue(Player player, QueueType type) {
        joinQueue(player, type, false);
    }

    public void joinHungerGamesSolo(Player player) {
        if (player == null) {
            return;
        }
        joinQueue(player, QueueType.HUNGERGAMES, false);
    }

    public void joinHungerGamesDuos(Player player) {
        if (player == null) {
            return;
        }
        joinQueue(player, QueueType.HUNGERGAMES_DUOS, true);
    }

    private void joinQueue(Player player, QueueType type, boolean includeParty) {
        if (player == null || type == null) {
            return;
        }
        if (plugin instanceof HGLootPlugin hydra && hydra.kitEditorService() != null
            && (hydra.kitEditorService().isEditing(player.getUniqueId())
                || hydra.kitEditorService().isRecovering(player.getUniqueId()))) {
            player.sendMessage(ChatColor.RED + "Finish or cancel your kit edit before queueing.");
            return;
        }
        if (pendingMatchLaunches.containsKey(player.getUniqueId())) {
            sendQueueMessage(player, type, ChatColor.RED + "Leave your pending match before joining another queue.");
            return;
        }
        if (plugin instanceof HGLootPlugin bossRushPlugin && bossRushPlugin.bossRushService() != null
            && bossRushPlugin.bossRushService().ownsPlayer(player.getUniqueId())) {
            player.sendMessage(ChatColor.RED + "You are already committed to Boss Rush.");
            return;
        }
        if (plugin instanceof HGLootPlugin hydra && hydra.minigameRouletteService() != null
            && hydra.minigameRouletteService().blockOtherModeEntry(player)) {
            return;
        }
        if (brDevelopmentTestQueues.contains(type)) {
            player.sendMessage(ChatColor.RED + "That BR queue is reserved for a development test match.");
            return;
        }
        if (rejectValousLiveBr(type, player, "join", true)) {
            return;
        }
        UUID playerId = player.getUniqueId();
        String lockKey = isHungerGames(type) ? "hg" : "br";
        if (plugin instanceof HGLootPlugin hydra && hydra.isModeLocked(lockKey)) {
            player.sendMessage(HydraIcons.LOCKED + " " + ChatColor.RED + HGLootPlugin.modeDisplayName(lockKey) + " is currently locked.");
            return;
        }
        String requiredPermission = queueJoinPermission(type);
        if (!player.hasPermission(requiredPermission)) {
            player.sendMessage(ChatColor.RED + "You do not have the required rank for " + type.displayName() + " queue.");
            return;
        }
        if (type == QueueType.DUO) {
            joinDuoQueue(player);
            return;
        }
        if (isHungerGames(type) && plugin instanceof HGLootPlugin hydra
            && hydra.networkBridgeService() != null && hydra.networkBridgeService().ownsHungerGamesQueueEntry()) {
            boolean networkDuos = type == QueueType.HUNGERGAMES_DUOS;
            hydra.networkBridgeService().queueHungerGames(player, networkDuos, partyService);
            return;
        }
        if (includeParty && type != QueueType.HUNGERGAMES
            && partyService != null && partyService.isInParty(playerId)) {
            if (type == QueueType.SOLO) {
                sendQueueMessage(player, type, ChatColor.RED
                    + "Battle Royale Solo cannot queue a party. Leave the party or use Duo with exactly 2 players.");
                return;
            }
            joinPartyQueue(player, type);
            return;
        }
        if (inMatchPlayers.contains(playerId)) {
            sendQueueMessage(player, type, ChatColor.RED + "You are already in a match.");
            return;
        }

        QueueType existing = queuedPlayers.get(playerId);
        if (existing != null && existing == type) {
            sendQueueMessage(player, type, ChatColor.YELLOW + "Already in " + queueAudienceLabel(type) + ".");
            return;
        }

        if (queueSize(type) >= idealPlayersFor(type)) {
            sendQueueMessage(player, type, ChatColor.RED + queueAudienceLabel(type) + " is full.");
            return;
        }

        if (existing != null) {
            removeFromQueue(playerId, existing);
            maybeCleanupPrewarmedWorld(existing);
        }

        queues.get(type).add(playerId);
        queuedPlayers.put(playerId, type);
        ensureHungerGamesLocalLobbyId(type);
        sendQueueMessage(player, type, simpleQueueJoinMessage(player.getName(), type));
        plugin.getLogger().info("[Queue] join: " + player.getName() + " -> " + type.displayName()
            + " (" + queueSize(type) + "/" + idealPlayersFor(type) + ")");
        if (isHungerGames(type)) {
            logHungerGamesPlayerTransition(player, "queue_joined", "mode=" + hungerGamesQueueModeLabel(playerId));
        }
        notifyQueuedPlayersOfJoin(type, List.of(playerId), player.getName());
        HydraSounds.playQueueJoin(player);
        enableValousReadyFactoryForQueueDemand(type, player);
        if (isHungerGames(type) && plugin instanceof HGLootPlugin hydra
            && hydra.gameHubService() != null) {
            sendPlayerToGameHub(player, () -> hydra.menuService().refreshHubInterface(player));
        }
        requestPrewarmAfterPlayerStaging(type);
        tryStartCountdown(type);
        updateAllSidebars();
    }

    private void joinDuoQueue(Player leader) {
        UUID leaderId = leader.getUniqueId();
        if (inMatchPlayers.contains(leaderId)) {
            sendQueueMessage(leader, QueueType.DUO, ChatColor.RED + "You are already in a match.");
            return;
        }
        if (partyService == null) {
            sendQueueMessage(leader, QueueType.DUO, ChatColor.RED + "Party service is unavailable right now.");
            return;
        }
        if (!partyService.isInParty(leaderId)) {
            sendQueueMessage(leader, QueueType.DUO, ChatColor.RED + "Duo queue requires a party of 2.");
            return;
        }
        UUID partyLeader = partyService.getLeader(leaderId);
        if (partyLeader == null || !partyLeader.equals(leaderId)) {
            sendQueueMessage(leader, QueueType.DUO, ChatColor.RED + "Only the party leader can queue your duo.");
            return;
        }

        List<UUID> members = new ArrayList<>(partyService.getPartyMembers(leaderId));
        if (members.size() != 2) {
            sendQueueMessage(leader, QueueType.DUO, ChatColor.RED + "Duo queue requires exactly 2 party members.");
            return;
        }

        for (UUID memberId : members) {
            Player member = Bukkit.getPlayer(memberId);
            if (member == null || !member.isOnline()) {
                sendQueueMessage(leader, QueueType.DUO, ChatColor.RED + "All duo members must be online before queueing.");
                return;
            }
            if (inMatchPlayers.contains(memberId)) {
                sendQueueMessage(leader, QueueType.DUO, ChatColor.RED + member.getName() + " is already in a match.");
                return;
            }
            if (!member.hasPermission(queueJoinPermission(QueueType.DUO))) {
                sendQueueMessage(leader, QueueType.DUO, ChatColor.RED + member.getName()
                    + " does not have access to Duo queue.");
                return;
            }
        }

        boolean alreadyQueued = true;
        for (UUID memberId : members) {
            if (queuedPlayers.get(memberId) != QueueType.DUO) {
                alreadyQueued = false;
                break;
            }
        }
        if (alreadyQueued) {
            sendQueueMessage(leader, QueueType.DUO, ChatColor.YELLOW + "Already in Duo Queue.");
            return;
        }

        for (UUID memberId : members) {
            QueueType existing = queuedPlayers.get(memberId);
            if (existing != null) {
                removeFromQueue(memberId, existing);
            }
        }

        LinkedHashSet<UUID> duoQueue = queues.get(QueueType.DUO);
        for (UUID memberId : members) {
            duoQueue.add(memberId);
            queuedPlayers.put(memberId, QueueType.DUO);
            duoTeamByPlayer.put(memberId, leaderId);
        }

        for (UUID memberId : members) {
            Player member = Bukkit.getPlayer(memberId);
            if (member == null || !member.isOnline()) {
                continue;
            }
            sendQueueMessage(member, QueueType.DUO, simpleQueueJoinMessage(member.getName(), QueueType.DUO));
            HydraSounds.playQueueJoin(member);
        }
        plugin.getLogger().info("[Queue] join: duo team led by " + leader.getName()
            + " -> Duo (" + queueSize(QueueType.DUO) + "/" + idealPlayersFor(QueueType.DUO) + ")");
        notifyQueuedPlayersOfJoin(QueueType.DUO, members, formatQueuedMemberNames(members));
        enableValousReadyFactoryForQueueDemand(QueueType.DUO, leader);
        maybePrewarmMatchWorld(QueueType.DUO);
        tryStartCountdown(QueueType.DUO);
        updateAllSidebars();
    }

    private void notifyQueuedPlayersOfJoin(QueueType type, Collection<UUID> joinedIds, String joinedLabel) {
        if (type == null || joinedIds == null || joinedIds.isEmpty() || joinedLabel == null || joinedLabel.isBlank()) {
            return;
        }
        String message = queueMessage(type, simpleQueueJoinMessage(joinedLabel, type));
        for (UUID queuedId : queues.get(type)) {
            if (joinedIds.contains(queuedId)) {
                continue;
            }
            Player queuedPlayer = Bukkit.getPlayer(queuedId);
            if (queuedPlayer == null || !queuedPlayer.isOnline()) {
                continue;
            }
            queuedPlayer.sendMessage(message);
        }
    }

    private String formatQueuedMemberNames(Collection<UUID> memberIds) {
        List<String> names = new ArrayList<>();
        for (UUID memberId : memberIds) {
            Player member = Bukkit.getPlayer(memberId);
            if (member != null && member.isOnline()) {
                names.add(member.getName());
            }
        }
        return names.isEmpty() ? "A duo team" : String.join(" & ", names);
    }

    private void notifyQueuedPlayersOfLeave(QueueType type, String leftLabel) {
        if (type == null || leftLabel == null || leftLabel.isBlank()) {
            return;
        }
        String message = queueMessage(type, ChatColor.WHITE + leftLabel + ChatColor.GRAY + " left " + simpleQueueName(type));
        for (UUID queuedId : queues.get(type)) {
            Player queuedPlayer = Bukkit.getPlayer(queuedId);
            if (queuedPlayer == null || !queuedPlayer.isOnline()) {
                continue;
            }
            queuedPlayer.sendMessage(message);
        }
    }

    private String simpleQueueJoinMessage(String playerLabel, QueueType type) {
        int current = queueSize(type);
        int needed = idealPlayersFor(type);
        return HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.WHITE + playerLabel
            + ChatColor.GRAY + " Joined " + ChatColor.WHITE + simpleQueueName(type)
            + ChatColor.GRAY + " (" + ChatColor.WHITE + current + "/" + needed
            + ChatColor.GRAY + ") Needed";
    }

    private String simpleQueueName(QueueType type) {
        if (type == null) {
            return "Queue";
        }
        return switch (type) {
            case SOLO -> "Battle Royale";
            case DUO -> "Battle Royale";
            case HUNGERGAMES, HUNGERGAMES_DUOS -> "Hunger Games";
        };
    }

    public void leaveQueueOrMatch(Player player) {
        UUID playerId = player.getUniqueId();
        QueueType queuedType = queuedPlayers.get(playerId);
        if (queuedType != null) {
            CountdownState countdown = countdowns.get(queuedType);
            if (countdown != null && countdown.secondsRemaining <= leaveLockSeconds) {
                sendQueueMessage(player, queuedType, ChatColor.RED + "Queue is locked for start ("
                    + countdown.secondsRemaining + "s left).");
                HydraSounds.playError(player);
                return;
            }
            if (queuedType == QueueType.DUO
                || queuedType == QueueType.HUNGERGAMES_DUOS) {
                UUID teamId = queuedType == QueueType.DUO
                    ? duoTeamByPlayer.get(playerId)
                    : hungerGamesDuoQueueGroup(playerId);
                if (teamId != null) {
                    List<UUID> queuedTeam = new ArrayList<>();
                    for (UUID id : queues.get(queuedType)) {
                        UUID queuedTeamId = queuedType == QueueType.DUO
                            ? duoTeamByPlayer.get(id)
                            : hungerGamesDuoQueueGroup(id);
                        if (teamId.equals(queuedTeamId)) {
                            queuedTeam.add(id);
                        }
                    }
                    if (!queuedTeam.isEmpty()) {
                        for (UUID id : queuedTeam) {
                            removeFromQueue(id, queuedType);
                        }
                        for (UUID id : queuedTeam) {
                            Player member = Bukkit.getPlayer(id);
                            if (member == null || !member.isOnline()) {
                                continue;
                            }
                            if (id.equals(playerId)) {
                                member.sendMessage(HydraIcons.EXCLAMATION + " " + ChatColor.GREEN + "You left the queue.");
                            } else {
                                sendQueueMessage(member, queuedType, ChatColor.YELLOW + player.getName()
                                    + " left the team queue.");
                            }
                            HydraSounds.playQueueLeave(member);
                            if (isHungerGames(queuedType)) {
                                returnToHubPresented(member, true);
                            }
                        }
                        maybeCleanupPrewarmedWorld(queuedType);
                        updateAllSidebars();
                        return;
                    }
                }
            }
            removeFromQueue(playerId, queuedType);
            player.sendMessage(HydraIcons.EXCLAMATION + " " + ChatColor.GREEN + "You left the queue.");
            HydraSounds.playQueueLeave(player);
            maybeCleanupPrewarmedWorld(queuedType);
            updateAllSidebars();
            if (isHungerGames(queuedType)) {
                returnToHubPresented(player, true);
            }
            return;
        }

        PendingMatchLaunch pendingLaunch = pendingMatchLaunches.remove(playerId);
        if (pendingLaunch != null) {
            clearBattleRoyaleSnapshots(playerId);
            clearCustomSpectatorState(player);
            returnToHubPresented(player, true);
            player.sendMessage(HydraIcons.EXCLAMATION + " " + ChatColor.GREEN + "You left the queue.");
            HydraSounds.playQueueLeave(player);
            updateAllSidebars();
            return;
        }

        if (inMatchPlayers.contains(playerId)) {
            removeFromMatch(playerId, player, true);
            player.sendMessage(HydraIcons.EXCLAMATION + " " + ChatColor.GREEN + "You left the match.");
            return;
        }

        if (spectatingMatchWorlds.containsKey(playerId) || pendingSpectatorRespawnWorld.containsKey(playerId)) {
            String worldName = spectatingMatchWorlds.remove(playerId);
            pendingSpectatorRespawnWorld.remove(playerId);
            clearBattleRoyaleSnapshots(playerId);
            syncSpectatorVisibility(worldName);
            returnToHub(player, true);
            player.sendMessage(ChatColor.YELLOW + "Left spectator mode.");
            return;
        }

        player.sendMessage(ChatColor.YELLOW + "Not in queue.");
        HydraSounds.playError(player);
    }

    public void sendStatus(Player player, QueueType filter) {
        UUID playerId = player.getUniqueId();
        if (inMatchPlayers.contains(playerId)) {
            player.sendMessage(ChatColor.GREEN + "In match.");
            return;
        }

        QueueType queuedType = queuedPlayers.get(playerId);
        if (queuedType != null) {
            player.sendMessage(ChatColor.GREEN + "In queue (" + queueSize(queuedType)
                + "/" + idealPlayersFor(queuedType) + ").");
            sendQueueLine(player, queuedType);
        } else {
            player.sendMessage(ChatColor.GRAY + "In lobby.");
            if (filter != null) {
                sendQueueLine(player, filter);
            }
        }
    }

    public void sendPlayerToHub(Player player) {
        UUID playerId = player.getUniqueId();

        QueueType queuedType = queuedPlayers.get(playerId);
        if (queuedType != null) {
            removeFromQueue(playerId, queuedType);
            maybeCleanupPrewarmedWorld(queuedType);
        }

        if (inMatchPlayers.contains(playerId)) {
            removeFromMatch(playerId, player, true);
            return;
        }

        String spectatorWorld = spectatingMatchWorlds.remove(playerId);
        pendingSpectatorRespawnWorld.remove(playerId);
        clearBattleRoyaleSnapshots(playerId);
        syncSpectatorVisibility(spectatorWorld);
        inMatchTypes.remove(playerId);
        inMatchWorlds.remove(playerId);
        inMatchPlayers.remove(playerId);
        matchKills.remove(playerId);
        returnToHub(player, true);
    }

    /** Moves a player physically without changing queue or tournament ownership. */
    public boolean sendPlayerToGameHub(Player player) {
        return sendPlayerToGameHub(player, null);
    }

    /** Deliberate lobby handoff; the optional continuation runs only after arrival. */
    public boolean sendPlayerToGameHub(Player player, Runnable onArrival) {
        if (player == null || !player.isOnline() || !(plugin instanceof HGLootPlugin hydra)
            || hydra.gameHubService() == null) {
            return false;
        }
        if (!hydra.gameHubService().isReadyForEntry()) {
            player.sendMessage(ChatColor.YELLOW + "The game lobby is still preparing.");
            return false;
        }
        UUID playerId = player.getUniqueId();
        QueueType queuedTypeAtTransfer = queuedPlayers.get(playerId);
        boolean hungerGamesQueueTransfer = isHungerGames(queuedTypeAtTransfer);
        long transferStartedAt = System.currentTimeMillis();
        if (hungerGamesQueueTransfer) {
            logHungerGamesPlayerTransition(player, "gamehub_transfer_started", "from=" + player.getWorld().getName());
        }
        QueueType activeType = inMatchTypes.get(playerId);
        String spectatorWorld = spectatingMatchWorlds.get(playerId);
        QueueType spectatorType = spectatorWorld == null ? null : resolveQueueTypeForWorld(spectatorWorld);
        String pendingRespawnWorld = pendingSpectatorRespawnWorld.get(playerId);
        QueueType pendingRespawnType = pendingRespawnWorld == null ? null : resolveQueueTypeForWorld(pendingRespawnWorld);
        if (isHungerGames(activeType) || isHungerGames(spectatorType) || isHungerGames(pendingRespawnType)) {
            plugin.getLogger().warning("[GameHub] Rejected stale HG handoff for " + player.getName()
                + " active=" + activeType + " spectatorWorld=" + spectatorWorld
                + " pendingRespawnWorld=" + pendingRespawnWorld + ".");
            return false;
        }
        Runnable arrival = () -> {
            if (!player.isOnline()) return;
            if (hungerGamesQueueTransfer && (queuedPlayers.get(playerId) != queuedTypeAtTransfer
                || pendingMatchLaunches.containsKey(playerId) || inMatchPlayers.contains(playerId)
                || pendingSpectatorRespawnWorld.containsKey(playerId)
                || spectatingMatchWorlds.containsKey(playerId))) {
                logHungerGamesPlayerTransition(player, "gamehub_transfer_expired",
                    "currentQueue=" + queuedPlayers.get(playerId) + " world=" + player.getWorld().getName());
                return;
            }
            clearCustomSpectatorState(player);
            clearHungerGamesStartFreeze(player);
            clearHungerGamesCombatGrace(player);
            boolean entered = hydra.gameHubService().enter(player);
            if (hungerGamesQueueTransfer) {
                logHungerGamesPlayerTransition(
                    player,
                    entered ? "gamehub_transfer_complete" : "gamehub_transfer_failed",
                    "world=" + player.getWorld().getName() + " elapsed_ms="
                        + (System.currentTimeMillis() - transferStartedAt)
                );
            }
            if (entered && onArrival != null) onArrival.run();
        };
        if (hydra.gameHubService().isGameHub(player.getWorld())) {
            arrival.run();
            return true;
        }
        if (!transitionTravel(player, arrival)) {
            // A compulsory lobby handoff must not leave the player in the old state.
            arrival.run();
        }
        return true;
    }

    private void requestPrewarmAfterPlayerStaging(QueueType type) {
        if (!isHungerGames(type)) {
            maybePrewarmMatchWorld(type);
            return;
        }
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (queueSize(type) <= 0) {
                plugin.getLogger().info("[Queue][HGPreparation] event=prewarm_skipped reason=queue_empty_after_gamehub_staging");
                return;
            }
            maybePrewarmMatchWorld(type);
        }, HUNGER_GAMES_GAMEHUB_SETTLE_TICKS);
    }

    private void logHungerGamesPlayerTransition(Player player, String event, String detail) {
        if (player == null) {
            return;
        }
        plugin.getLogger().info("[Queue][HGPlayer] event=" + event + " player=" + player.getName()
            + " uuid=" + player.getUniqueId() + (detail == null || detail.isBlank() ? "" : " " + detail));
    }

    private String hungerGamesQueueModeLabel(UUID playerId) {
        return queuedPlayers.get(playerId) == QueueType.HUNGERGAMES_DUOS ? "duos" : "solo";
    }

    private void requireDevelopmentHandshake() {
        if (!(plugin instanceof HGLootPlugin hydra) || !hydra.networkNodeConfig().enabled()
            || hydra.networkNodeConfig().role() != hgloot.plugin.network.BackendRole.HG
            || !plugin.getConfig().getBoolean("network.hg_handshake_development", false) || !Bukkit.isPrimaryThread()) {
            throw new IllegalStateException("HG development handshake is disabled or called off the server thread");
        }
    }

    public CompletableFuture<String> prepareDevelopmentHungerGames(UUID attempt, int players) {
        requireDevelopmentHandshake();
        if (players < 1 || players > idealPlayersFor(QueueType.HUNGERGAMES)
            || hasActiveMatchWorld(QueueType.HUNGERGAMES) || matchStartInProgress.contains(QueueType.HUNGERGAMES)) {
            return CompletableFuture.failedFuture(new IllegalStateException("HG backend is not available for this roster"));
        }
        String name = "HG-World-Dev-" + attempt;
        CompletableFuture<String> result = new CompletableFuture<>();
        createHungerGamesMatchWorldAsync(name).whenComplete((world, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
            try {
                if (error != null || world == null || !ensureMatchWorldReady(world, QueueType.HUNGERGAMES)) {
                    result.completeExceptionally(new IllegalStateException("HG world preparation failed", error));
                    return;
                }
                List<Location> spawns = generateMatchSpawns(world, players, QueueType.HUNGERGAMES);
                if (spawns.size() < players || spawns.stream().anyMatch(s -> !s.getBlock().isPassable()
                    || !s.clone().add(0, 1, 0).getBlock().isPassable() || s.clone().add(0, -1, 0).getBlock().isPassable())) {
                    result.completeExceptionally(new IllegalStateException("HG spawn terrain is not safe"));
                    return;
                }
                for (Location spawn : spawns) world.addPluginChunkTicket(spawn.getBlockX() >> 4, spawn.getBlockZ() >> 4, plugin);
                developmentNetworkSpawns.put(name, List.copyOf(spawns));
                result.complete(name);
            } catch (RuntimeException failure) {
                result.completeExceptionally(failure);
            }
        }));
        return result;
    }

    public boolean admitDevelopmentHungerGames(Player player, String worldName, int index) {
        requireDevelopmentHandshake();
        World world = Bukkit.getWorld(worldName);
        List<Location> spawns = developmentNetworkSpawns.get(worldName);
        if (spawns == null || index < 0 || index >= spawns.size() || !ensureMatchWorldReady(world, QueueType.HUNGERGAMES)) return false;
        player.setGameMode(GameMode.ADVENTURE);
        player.setFallDistance(0);
        return player.teleport(spawns.get(index));
    }

    public boolean startDevelopmentHungerGames(UUID session, String worldName, List<UUID> roster,
                                               Map<UUID, UUID> groups, boolean duos) {
        requireDevelopmentHandshake();
        if (!developmentNetworkSpawns.containsKey(worldName) || !ensureMatchWorldReady(Bukkit.getWorld(worldName), QueueType.HUNGERGAMES)) return false;
        Map<UUID, UUID> teams = duos ? assignHungerGamesDuoTeams(roster, groups, ThreadLocalRandom.current()) : Map.of();
        developmentNetworkPreparedWorld = worldName;
        try {
            return startNetworkHungerGamesReservation(session.toString(), roster, teams, duos);
        } finally { developmentNetworkPreparedWorld = null; }
    }

    public boolean restoreDevelopmentHungerGames(Player player, String worldName) {
        requireDevelopmentHandshake();
        if (!hasActiveMatchSession(QueueType.HUNGERGAMES, worldName)) return false;
        if (rejoinBattleRoyale(player, true)) return true;
        if (worldName.equals(inMatchWorlds.get(player.getUniqueId())) && player.getWorld().getName().equals(worldName)) return true;
        // Expired/dead reconnect bodies have no live snapshot. Never recreate them as living players.
        if (!player.teleport(Bukkit.getWorld(worldName).getSpawnLocation())) return false;
        setCustomSpectatorState(player, worldName, false);
        return true;
    }

    public boolean cleanupDevelopmentHungerGames(UUID attempt) {
        requireDevelopmentHandshake();
        String worldName = "HG-World-Dev-" + attempt;
        World world = Bukkit.getWorld(worldName);
        if (world != null && !world.getPlayers().isEmpty()) return false;
        if (world == null && !Files.exists(Bukkit.getWorldContainer().toPath().resolve(worldName))) {
            developmentNetworkSpawns.remove(worldName);
            return true;
        }
        if (!matchWorldService.isCleaning(worldName)) {
            if (hasActiveMatchSession(QueueType.HUNGERGAMES, worldName)) finishMatchWorld(QueueType.HUNGERGAMES, worldName);
            else cleanupWorld(worldName);
        }
        return false;
    }

    /** Imports one proxy reservation into the existing HG engine on the dedicated HG backend. */
    public boolean startNetworkHungerGamesReservation(
        String reservationId,
        Collection<UUID> roster,
        Map<UUID, UUID> teamByPlayer,
        boolean duos
    ) {
        if (reservationId == null || reservationId.isBlank() || roster == null || roster.isEmpty()) {
            return false;
        }
        if (pendingNetworkHungerGamesReservationId != null || hasActiveMatchWorld(QueueType.HUNGERGAMES)
            || matchStartInProgress.contains(QueueType.HUNGERGAMES)) {
            plugin.getLogger().warning("[Network] rejected duplicate HG reservation=" + reservationId);
            return false;
        }
        LinkedHashSet<UUID> queue = queues.get(QueueType.HUNGERGAMES);
        for (UUID playerId : roster) {
            Player player = Bukkit.getPlayer(playerId);
            if (player == null || !player.isOnline()) {
                plugin.getLogger().warning("[Network] HG reservation missing online player=" + playerId);
                return false;
            }
            if (queuedPlayers.containsKey(playerId) || pendingMatchLaunches.containsKey(playerId)
                || inMatchPlayers.contains(playerId)) {
                return false;
            }
        }
        if (!queue.isEmpty() || !queues.get(QueueType.HUNGERGAMES_DUOS).isEmpty()
            || hasActiveMatchWorld(QueueType.HUNGERGAMES_DUOS)
            || matchStartInProgress.contains(QueueType.HUNGERGAMES_DUOS)) {
            return false;
        }
        pendingNetworkHungerGamesReservationId = reservationId;
        pendingNetworkHungerGamesDuos = duos;
        for (UUID playerId : roster) {
            queue.add(playerId);
            queuedPlayers.put(playerId, QueueType.HUNGERGAMES);
            UUID teamId = teamByPlayer == null ? null : teamByPlayer.get(playerId);
            if (teamId != null) {
                duoTeamByPlayer.put(playerId, teamId);
            }
        }
        plugin.getLogger().info("[Network] imported HG reservation=" + reservationId
            + " roster=" + roster.size());
        startMatch(QueueType.HUNGERGAMES, true, null);
        return true;
    }

    private void failPendingNetworkHungerGamesReservation(String reason) {
        if (pendingNetworkHungerGamesReservationId == null) {
            return;
        }
        String reservationId = pendingNetworkHungerGamesReservationId;
        pendingNetworkHungerGamesReservationId = null;
        pendingNetworkHungerGamesDuos = false;
        LinkedHashSet<UUID> queue = queues.get(QueueType.HUNGERGAMES);
        for (UUID playerId : List.copyOf(queue)) {
            if (queuedPlayers.get(playerId) == QueueType.HUNGERGAMES) {
                queuedPlayers.remove(playerId);
            }
            duoTeamByPlayer.remove(playerId);
        }
        queue.clear();
        plugin.getLogger().warning("[Network] clearing failed HG reservation=" + reservationId
            + " reason=" + reason);
        if (plugin instanceof HGLootPlugin hydra && hydra.networkBridgeService() != null) {
            hydra.networkBridgeService().reservationFailed(reason);
        }
    }

    public void sendAdminList(CommandSender sender) {
        sender.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.GOLD + "Queue Admin List");
        for (QueueType type : QueueType.values()) {
            LinkedHashSet<UUID> queue = queues.get(type);
            List<String> names = new ArrayList<>();
            for (UUID id : queue) {
                BrTestParticipant placeholder = brTestParticipants.get(id);
                if (placeholder != null) {
                    names.add(placeholder.displayName());
                    continue;
                }
                Player player = Bukkit.getPlayer(id);
                names.add(player != null ? player.getName() : id.toString());
            }
            sender.sendMessage(ChatColor.GRAY + type.displayName() + ": "
                + ChatColor.WHITE + queue.size() + ChatColor.DARK_GRAY + " -> " + names);
        }
        sender.sendMessage(ChatColor.GRAY + "In match: " + ChatColor.WHITE + inMatchPlayers.size());
        sender.sendMessage(ChatColor.GRAY + "Auto win trigger: "
            + (autoWinTriggerEnabled ? ChatColor.GREEN + "ENABLED" : ChatColor.RED + "DISABLED"));
    }

    public void handleBrTestAdmin(CommandSender sender, String[] args) {
        if (sender == null || !sender.hasPermission("hgloot.debug")) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "BR test matches require Dev or Owner access.");
            }
            return;
        }
        String sub = args.length == 0 ? "status" : args[0].toLowerCase(Locale.ROOT);
        switch (sub) {
            case "create" -> {
                int count = args.length >= 2 ? parseBoundedTestBotCount(args[1]) : 1;
                if (count < 1) {
                    sender.sendMessage(ChatColor.RED + "Usage: /admin br test create [1-16]");
                    return;
                }
                createBrDevelopmentTest(sender, count);
            }
            case "addbot" -> {
                int count = args.length >= 2 ? parseBoundedTestBotCount(args[1]) : 1;
                if (count < 1) {
                    sender.sendMessage(ChatColor.RED + "Usage: /admin br test addbot [1-16]");
                    return;
                }
                addBrTestPlaceholders(sender, count);
            }
            case "removebot" -> {
                int count = args.length >= 2 ? parseBoundedTestBotCount(args[1]) : 1;
                if (count < 1) {
                    sender.sendMessage(ChatColor.RED + "Usage: /admin br test removebot [1-16]");
                    return;
                }
                removeBrTestPlaceholders(sender, count);
            }
            case "start" -> startBrDevelopmentTest(sender);
            case "join" -> {
                if (sender instanceof Player player) {
                    joinBrDevelopmentTest(player, args.length >= 2 ? args[1] : null, false);
                } else {
                    sender.sendMessage(ChatColor.RED + "Only a player can join a BR test match.");
                }
            }
            case "spectate" -> {
                if (sender instanceof Player player) {
                    joinBrDevelopmentTest(player, args.length >= 2 ? args[1] : null, true);
                } else {
                    sender.sendMessage(ChatColor.RED + "Only a player can spectate a BR test match.");
                }
            }
            case "stop" -> stopBrDevelopmentTest(sender, args.length >= 2 ? args[1] : null);
            case "status" -> sendBrDevelopmentTestStatus(sender);
            default -> sendBrDevelopmentTestHelp(sender);
        }
    }

    private void joinPartyQueue(Player leader, QueueType type) {
        UUID leaderId = leader.getUniqueId();
        UUID partyLeader = partyService.getLeader(leaderId);
        if (partyLeader == null || !partyLeader.equals(leaderId)) {
            sendQueueMessage(leader, type, ChatColor.RED + "Only the party leader can queue the party.");
            return;
        }

        List<UUID> members = new ArrayList<>(partyService.getPartyMembers(leaderId));
        if (type == QueueType.HUNGERGAMES_DUOS && members.size() > 2) {
            sendQueueMessage(leader, type, ChatColor.RED + "Duos only supports parties of up to 2 players.");
            return;
        }
        if (members.isEmpty()) {
            sendQueueMessage(leader, type, ChatColor.RED + "Your party has no available members.");
            return;
        }

        int additions = 0;
        List<Player> onlineMembers = new ArrayList<>(members.size());
        for (UUID memberId : members) {
            Player member = Bukkit.getPlayer(memberId);
            if (member == null || !member.isOnline()) {
                sendQueueMessage(leader, type, ChatColor.RED + "All party members must be online before queueing.");
                return;
            }
            if (plugin instanceof HGLootPlugin hydra && hydra.kitEditorService() != null
                && (hydra.kitEditorService().isEditing(memberId)
                    || hydra.kitEditorService().isRecovering(memberId))) {
                sendQueueMessage(leader, type, ChatColor.RED + member.getName()
                    + " must finish their kit edit before queueing.");
                return;
            }
            if (plugin instanceof HGLootPlugin hydra && hydra.bossRushService() != null
                && hydra.bossRushService().ownsPlayer(memberId)) {
                plugin.getLogger().fine("[PartyCommitment] HG queue rejected leader=" + leaderId
                    + " member=" + memberId + " owner=BossRush queue=" + type);
                sendQueueMessage(leader, type, ChatColor.RED + member.getName() + " is committed to Boss Rush.");
                return;
            }
            if (plugin instanceof HGLootPlugin hydra && hydra.minigameRouletteService() != null
                && hydra.minigameRouletteService().isTournamentMember(memberId)) {
                plugin.getLogger().fine("[PartyCommitment] HG queue rejected leader=" + leaderId
                    + " member=" + memberId + " owner=MinigameRoulette queue=" + type);
                sendQueueMessage(leader, type, ChatColor.RED + member.getName()
                    + " is committed to Minigame Roulette.");
                return;
            }
            if (inMatchPlayers.contains(memberId) || spectatingMatchWorlds.containsKey(memberId)
                || pendingMatchLaunches.containsKey(memberId)) {
                plugin.getLogger().fine("[PartyCommitment] HG queue rejected leader=" + leaderId
                    + " member=" + memberId + " inMatch=" + inMatchPlayers.contains(memberId)
                    + " spectating=" + spectatingMatchWorlds.containsKey(memberId)
                    + " pendingLaunch=" + pendingMatchLaunches.containsKey(memberId));
                sendQueueMessage(leader, type, ChatColor.RED + member.getName() + " is already in a match.");
                return;
            }
            if (!member.hasPermission(queueJoinPermission(type))) {
                sendQueueMessage(leader, type, ChatColor.RED + member.getName()
                    + " does not have access to " + type.displayName() + ".");
                return;
            }
            if (queuedPlayers.get(memberId) != type) {
                additions++;
            }
            onlineMembers.add(member);
        }

        if (additions == 0) {
            sendQueueMessage(leader, type, ChatColor.YELLOW + "Your party is already in " + queueAudienceLabel(type) + ".");
            return;
        }
        if (queueSize(type) + additions > idealPlayersFor(type)) {
            sendQueueMessage(leader, type, ChatColor.RED + queueAudienceLabel(type)
                + " does not have room for your entire party.");
            return;
        }

        for (UUID memberId : members) {
            QueueType existing = queuedPlayers.get(memberId);
            if (existing != null && existing != type) {
                removeFromQueue(memberId, existing);
                maybeCleanupPrewarmedWorld(existing);
            }
        }
        for (UUID memberId : members) {
            queues.get(type).add(memberId);
            queuedPlayers.put(memberId, type);
        }
        ensureHungerGamesLocalLobbyId(type);
        for (Player member : onlineMembers) {
            sendQueueMessage(member, type, simpleQueueJoinMessage(member.getName(), type));
            HydraSounds.playQueueJoin(member);
        }
        plugin.getLogger().info("[Queue] join: party led by " + leader.getName() + " (" + members.size()
            + " players) -> " + type.displayName() + " (" + queueSize(type) + "/" + idealPlayersFor(type) + ")");
        if (isHungerGames(type)) {
            for (Player member : onlineMembers) {
                logHungerGamesPlayerTransition(member, "queue_joined", "mode=" + hungerGamesQueueModeLabel(member.getUniqueId()));
            }
        }
        notifyQueuedPlayersOfJoin(type, members, formatQueuedMemberNames(members));
        enableValousReadyFactoryForQueueDemand(type, leader);
        if (isHungerGames(type) && plugin instanceof HGLootPlugin hydra
            && hydra.gameHubService() != null) {
            for (Player member : onlineMembers) {
                sendPlayerToGameHub(member, () -> hydra.menuService().refreshHubInterface(member));
            }
        }
        requestPrewarmAfterPlayerStaging(type);
        tryStartCountdown(type);
        updateAllSidebars();
    }

    private void createBrDevelopmentTest(CommandSender sender, int count) {
        QueueType type = QueueType.SOLO;
        if (hasActiveMatchWorld(type) || hasPendingMatchStart(type) || matchStartInProgress.contains(type)) {
            sender.sendMessage(ChatColor.RED + "Stop the active or pending Solo BR match before creating a test.");
            return;
        }
        if (queueSize(type) > 0 || brDevelopmentTestQueues.contains(type)) {
            sender.sendMessage(ChatColor.RED + "Solo BR queue must be empty before creating a test match.");
            return;
        }
        brDevelopmentTestQueues.add(type);
        addBrTestPlaceholders(sender, count);
        plugin.getLogger().warning("[Queue][BrTest] event=test_created actor=" + sender.getName()
            + " queue=solo placeholders=" + queuedBrTestPlaceholderCount(type)
            + " rewards=disabled public=false");
        sender.sendMessage(ChatColor.GREEN + "Created a development Solo BR test with "
            + queuedBrTestPlaceholderCount(type) + " placeholder participant(s).");
        sender.sendMessage(ChatColor.GRAY + "Run /admin br test start. You may disconnect while it prepares or runs.");
    }

    private void addBrTestPlaceholders(CommandSender sender, int count) {
        QueueType type = QueueType.SOLO;
        if (!brDevelopmentTestQueues.contains(type)) {
            sender.sendMessage(ChatColor.RED + "Create a test first with /admin br test create [count].");
            return;
        }
        if (hasActiveBrDevelopmentTest()) {
            sender.sendMessage(ChatColor.RED + "Placeholders cannot be added after the test match starts.");
            return;
        }
        int current = queuedBrTestPlaceholderCount(type);
        int toAdd = Math.min(count, BR_TEST_MAX_PLACEHOLDERS - current);
        if (toAdd <= 0) {
            sender.sendMessage(ChatColor.YELLOW + "The test already has the maximum 16 placeholders.");
            return;
        }
        for (int index = 0; index < toAdd; index++) {
            UUID id = UUID.randomUUID();
            BrTestParticipant participant = new BrTestParticipant(
                "[BOT] Test-" + nextBrTestPlaceholderNumber(),
                type
            );
            brTestParticipants.put(id, participant);
            queues.get(type).add(id);
            queuedPlayers.put(id, type);
        }
        maybePrewarmMatchWorld(type);
        updateAllSidebars();
        plugin.getLogger().info("[Queue][BrTest] event=placeholders_added actor=" + sender.getName()
            + " added=" + toAdd + " queued=" + queuedBrTestPlaceholderCount(type));
        sender.sendMessage(ChatColor.GREEN + "Added " + toAdd + " BR test placeholder(s). Total: "
            + queuedBrTestPlaceholderCount(type) + ".");
    }

    private void removeBrTestPlaceholders(CommandSender sender, int count) {
        QueueType type = QueueType.SOLO;
        if (!brDevelopmentTestQueues.contains(type) || hasActiveBrDevelopmentTest()) {
            sender.sendMessage(ChatColor.RED + "Queued test placeholders can only be removed before the match starts.");
            return;
        }
        List<UUID> queuedBots = queuedBrTestPlaceholderIds(type);
        int removed = 0;
        for (int index = queuedBots.size() - 1; index >= 0 && removed < count; index--) {
            UUID id = queuedBots.get(index);
            removeFromQueue(id, type, QueueRemovalReason.LEAVE);
            brTestParticipants.remove(id);
            removed++;
        }
        if (queuedBrTestPlaceholderCount(type) == 0) {
            brDevelopmentTestQueues.remove(type);
        }
        updateAllSidebars();
        sender.sendMessage(ChatColor.GREEN + "Removed " + removed + " placeholder(s). Remaining: "
            + queuedBrTestPlaceholderCount(type) + ".");
    }

    private void startBrDevelopmentTest(CommandSender sender) {
        QueueType type = QueueType.SOLO;
        if (!brDevelopmentTestQueues.contains(type) || queuedBrTestPlaceholderCount(type) == 0) {
            sender.sendMessage(ChatColor.RED + "Create a test first with /admin br test create [count].");
            return;
        }
        if (hasActiveBrDevelopmentTest()) {
            sender.sendMessage(ChatColor.YELLOW + "A BR development test is already active.");
            return;
        }
        plugin.getLogger().warning("[Queue][BrTest] event=start_requested actor=" + sender.getName()
            + " queue=solo placeholders=" + queuedBrTestPlaceholderCount(type));
        forceStart(type, sender);
    }

    private void joinBrDevelopmentTest(Player player, String requestedWorld, boolean spectator) {
        String worldName = resolveBrDevelopmentTestWorld(requestedWorld);
        if (worldName == null) {
            player.sendMessage(ChatColor.RED + "No active BR development test"
                + (requestedWorld == null ? "." : " matches '" + requestedWorld + "'."));
            return;
        }
        if (endingMatchWorlds.contains(worldName)) {
            player.sendMessage(ChatColor.RED + "That test match is ending.");
            return;
        }
        UUID playerId = player.getUniqueId();
        if (inMatchPlayers.contains(playerId) || spectatingMatchWorlds.containsKey(playerId)) {
            String current = inMatchWorlds.get(playerId);
            if (current == null) {
                current = spectatingMatchWorlds.get(playerId);
            }
            if (isSameMatchSessionWorld(worldName, current)) {
                player.sendMessage(ChatColor.YELLOW + "You are already in that test match.");
            } else {
                player.sendMessage(ChatColor.RED + "Leave your current match before joining the test.");
            }
            return;
        }
        QueueType queuedType = queuedPlayers.get(playerId);
        if (queuedType != null) {
            removeFromQueue(playerId, queuedType);
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            player.sendMessage(ChatColor.RED + "The BR test world is not loaded.");
            return;
        }
        clearBattleRoyaleSnapshots(playerId);
        clearCustomSpectatorState(player);
        player.teleport(brDevelopmentTestSpawn(world));
        if (spectator) {
            setCustomSpectatorState(player, worldName, true);
        } else {
            inMatchPlayers.add(playerId);
            inMatchTypes.put(playerId, QueueType.SOLO);
            inMatchWorlds.put(playerId, worldName);
            matchKills.put(playerId, 0);
            resetMatchRewardStats(playerId);
            if (menuService != null) {
                menuService.preparePlayerForMatch(player);
            }
            player.setGameMode(GameMode.SURVIVAL);
            healBrDevelopmentTestPlayer(player);
            player.setFallDistance(0.0F);
            player.setNoDamageTicks(60);
            player.sendMessage(ChatColor.GREEN + "Joined development BR test " + worldName + ".");
        }
        refreshSidebar(player);
        syncSpectatorVisibility(worldName);
        plugin.getLogger().info("[Queue][BrTest] event=staff_join actor=" + player.getName()
            + " world=" + worldName + " role=" + (spectator ? "spectator" : "combatant"));
    }

    private void stopBrDevelopmentTest(CommandSender sender, String requestedWorld) {
        String worldName = resolveBrDevelopmentTestWorld(requestedWorld);
        if (worldName == null) {
            if (brDevelopmentTestQueues.remove(QueueType.SOLO)) {
                pendingMatchStarts.remove(QueueType.SOLO);
                clearMatchStartInProgress(QueueType.SOLO);
                cancelCountdown(QueueType.SOLO, "Development test canceled.");
                cancelUnclaimedBrGeneration(QueueType.SOLO, "development_test_canceled");
                clearQueuedBrTestPlaceholders(QueueType.SOLO);
                maybeCleanupPrewarmedWorld(QueueType.SOLO);
                sender.sendMessage(ChatColor.GREEN + "Canceled the queued BR development test.");
                return;
            }
            sender.sendMessage(ChatColor.YELLOW + "No active BR development test to stop.");
            return;
        }
        plugin.getLogger().warning("[Queue][BrTest] event=stop_requested actor=" + sender.getName()
            + " world=" + worldName);
        List<Player> combatants = new ArrayList<>();
        for (Map.Entry<UUID, String> entry : new ArrayList<>(inMatchWorlds.entrySet())) {
            if (!isSameMatchSessionWorld(worldName, entry.getValue())) {
                continue;
            }
            Player player = Bukkit.getPlayer(entry.getKey());
            if (player != null && player.isOnline()) {
                combatants.add(player);
            }
        }
        QueueType type = resolveQueueTypeForWorld(worldName);
        finishMatchWorld(type == null ? QueueType.SOLO : type, worldName);
        for (Player combatant : combatants) {
            returnToHub(combatant, true);
        }
        sender.sendMessage(ChatColor.GREEN + "Stopped BR development test " + worldName + ".");
    }

    private void sendBrDevelopmentTestStatus(CommandSender sender) {
        int queued = queuedBrTestPlaceholderCount(QueueType.SOLO);
        sender.sendMessage(ChatColor.GOLD + "BR Development Test");
        sender.sendMessage(ChatColor.GRAY + "Queue: " + (brDevelopmentTestQueues.contains(QueueType.SOLO)
            ? ChatColor.GREEN + "ARMED" : ChatColor.DARK_GRAY + "inactive")
            + ChatColor.GRAY + " | placeholders=" + ChatColor.WHITE + queued);
        if (brDevelopmentTestWorlds.isEmpty()) {
            sender.sendMessage(ChatColor.GRAY + "Active test world: " + ChatColor.DARK_GRAY + "none");
            return;
        }
        for (String worldName : new ArrayList<>(brDevelopmentTestWorlds)) {
            sender.sendMessage(ChatColor.GRAY + "World: " + ChatColor.WHITE + worldName
                + ChatColor.GRAY + " | placeholders=" + ChatColor.WHITE + activeBrTestPlaceholderCount(worldName)
                + ChatColor.GRAY + " | real=" + ChatColor.WHITE + activePlayersInWorld(worldName).size()
                + ChatColor.GRAY + " | spectators=" + ChatColor.WHITE + countSpectatorsInWorld(worldName));
        }
    }

