        sender.sendMessage(ChatColor.GOLD + "BR Development Test Commands");
        sender.sendMessage(ChatColor.GRAY + "/admin br test create [1-16]");
        sender.sendMessage(ChatColor.GRAY + "/admin br test addbot [1-16]");
        sender.sendMessage(ChatColor.GRAY + "/admin br test removebot [1-16]");
