    private int parseBoundedTestBotCount(String raw) {
        Integer parsed = parseIntOrNull(raw);
        return parsed == null || parsed < 1 || parsed > BR_TEST_MAX_PLACEHOLDERS ? -1 : parsed;
    }

    private int nextBrTestPlaceholderNumber() {
        int next = 1;
        Set<String> names = new HashSet<>();
        for (BrTestParticipant participant : brTestParticipants.values()) {
            names.add(participant.displayName());
        }
        while (names.contains("[BOT] Test-" + next)) {
            next++;
        }
        return next;
    }

    private List<UUID> queuedBrTestPlaceholderIds(QueueType type) {
        List<UUID> ids = new ArrayList<>();
        LinkedHashSet<UUID> queue = queues.get(type);
        if (queue == null) {
            return ids;
        }
        for (UUID id : queue) {
            BrTestParticipant participant = brTestParticipants.get(id);
            if (participant != null
                && participant.queueType == type
                && participant.state == BrTestParticipantState.QUEUED) {
                ids.add(id);
            }
        }
        return ids;
    }

    private int queuedBrTestPlaceholderCount(QueueType type) {
        return queuedBrTestPlaceholderIds(type).size();
    }

    private int activeBrTestPlaceholderCount(String worldName) {
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null) {
            return 0;
        }
        int count = 0;
        for (BrTestParticipant participant : brTestParticipants.values()) {
            if (participant.state == BrTestParticipantState.ACTIVE
                && isSameMatchSessionWorld(rootWorldName, participant.worldName)) {
                count++;
            }
        }
        return count;
    }

    private boolean hasActiveBrDevelopmentTest() {
        return !brDevelopmentTestWorlds.isEmpty();
    }

    private boolean isBrDevelopmentTestWorld(String worldName) {
        String rootWorldName = rootMatchWorldName(worldName);
        return rootWorldName != null && brDevelopmentTestWorlds.contains(rootWorldName);
    }

    private void clearQueuedBrTestPlaceholders(QueueType type) {
        for (UUID id : queuedBrTestPlaceholderIds(type)) {
            removeFromQueue(id, type, QueueRemovalReason.LEAVE);
        }
    }

    private void clearActiveBrTestPlaceholders(String worldName) {
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null) {
            return;
        }
        brTestParticipants.entrySet().removeIf(entry -> {
            BrTestParticipant participant = entry.getValue();
            return participant.state == BrTestParticipantState.ACTIVE
                && isSameMatchSessionWorld(rootWorldName, participant.worldName);
        });
    }

    private String resolveBrDevelopmentTestWorld(String requestedWorld) {
        if (requestedWorld != null && !requestedWorld.isBlank()) {
            for (String worldName : brDevelopmentTestWorlds) {
                if (worldName.equalsIgnoreCase(requestedWorld)
                    || isSameMatchSessionWorld(worldName, requestedWorld)) {
                    return worldName;
                }
            }
            return null;
        }
        return brDevelopmentTestWorlds.size() == 1
            ? brDevelopmentTestWorlds.iterator().next()
            : null;
    }

    public List<String> brDevelopmentTestWorldNames() {
        return List.copyOf(brDevelopmentTestWorlds);
    }

    private Location brDevelopmentTestSpawn(World world) {
        WorldBorder border = world.getWorldBorder();
        int x = (int) Math.floor(border.getCenter().getX());
        int z = (int) Math.floor(border.getCenter().getZ());
        int y = world.getHighestBlockYAt(x, z, HeightMap.MOTION_BLOCKING_NO_LEAVES) + 2;
        y = Math.max(world.getMinHeight() + 2, Math.min(world.getMaxHeight() - 2, y));
        return new Location(world, x + 0.5D, y, z + 0.5D, 0.0F, 0.0F);
    }

    private void healBrDevelopmentTestPlayer(Player player) {
        AttributeInstance maxHealthAttribute = player.getAttribute(Attribute.MAX_HEALTH);
        double maxHealth = maxHealthAttribute == null ? 20.0D : Math.max(1.0D, maxHealthAttribute.getValue());
        player.setHealth(maxHealth);
        player.setFoodLevel(20);
        player.setSaturation(20.0F);
        player.setExhaustion(0.0F);
        player.setFireTicks(0);
        player.setFreezeTicks(0);
        player.setInvulnerable(false);
        player.setRemainingAir(player.getMaximumAir());
        for (PotionEffect effect : player.getActivePotionEffects()) {
            player.removePotionEffect(effect.getType());
        }
    }

    /** Staff-facing Hunger Games overview: queue, preparation, ready arena, and active matches. */
    public void sendHungerGamesAdminStatus(CommandSender sender) {
        sender.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.GOLD + "Hunger Games Status");
        sendHungerGamesAdminStatus(sender, QueueType.HUNGERGAMES);
        sendHungerGamesAdminStatus(sender, QueueType.HUNGERGAMES_DUOS);
    }

    /** Targets only a loaded, active HG instance; never a ready or stale world. */
    public void handleHungerGamesBorderAdmin(Player sender, String[] args) {
        if (args.length < 1 || args.length > 3) {
            sender.sendMessage(ChatColor.RED + "Usage: /admin hg border <info|set|add|remove> [blocks] [active-world]");
            return;
        }
        String action = args[0].toLowerCase(Locale.ROOT);
        boolean info = action.equals("info");
        if (!info && !action.equals("set") && !action.equals("add") && !action.equals("remove")) {
            sender.sendMessage(ChatColor.RED + "Usage: /admin hg border <info|set|add|remove> [blocks] [active-world]");
            return;
        }
        if ((info && args.length > 2) || (!info && args.length < 2)) {
            sender.sendMessage(ChatColor.RED + "Usage: /admin hg border " + action
                + (info ? " [active-world]" : " <blocks> [active-world]"));
            return;
        }
        double amount = 0.0D;
        if (!info) {
            try {
                amount = Double.parseDouble(args[1]);
            } catch (NumberFormatException exception) {
                sender.sendMessage(ChatColor.RED + "Border blocks must be a positive number.");
                return;
            }
            if (!Double.isFinite(amount) || amount <= 0.0D) {
                sender.sendMessage(ChatColor.RED + "Border blocks must be a positive number.");
                return;
            }
        }
        String requestedWorld = info && args.length == 2 ? args[1] : !info && args.length == 3 ? args[2] : null;
        LinkedHashSet<String> active = new LinkedHashSet<>(activeMatchWorldsFor(QueueType.HUNGERGAMES));
        active.addAll(activeMatchWorldsFor(QueueType.HUNGERGAMES_DUOS));
        String worldName = requestedWorld;
        if (worldName == null) {
            worldName = active.contains(sender.getWorld().getName())
                ? sender.getWorld().getName() : active.size() == 1 ? active.iterator().next() : null;
        }
        if (worldName == null || !active.contains(worldName)) {
            sender.sendMessage(ChatColor.RED + "Choose an active HG world. Active: " + active);
            return;
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            sender.sendMessage(ChatColor.RED + "That HG match world is not loaded.");
            return;
        }
        WorldBorder border = world.getWorldBorder();
        if (info) {
            sender.sendMessage(ChatColor.AQUA + worldName + ChatColor.GRAY + " border: "
                + ChatColor.WHITE + Math.round(border.getSize()) + " blocks"
                + ChatColor.GRAY + " centered at " + ChatColor.WHITE
                + Math.round(border.getCenter().getX()) + ", " + Math.round(border.getCenter().getZ()));
            return;
        }
        double current = border.getSize();
        double target = switch (action) {
            case "set" -> amount;
            case "add" -> current + amount;
            default -> current - amount;
        };
        if (!Double.isFinite(target) || target < 16.0D || target > 59_999_968.0D) {
            sender.sendMessage(ChatColor.RED + "Resulting border diameter must be 16 to 59,999,968 blocks.");
            return;
        }
        int seconds = target < current ? hungerGamesBorderShrinkSeconds(current, target) : 0;
        if (seconds > 0) {
            border.changeSize(target, seconds * 20L);
        } else {
            border.setSize(target);
        }
        sender.sendMessage(ChatColor.GREEN + "HG border " + worldName + " set toward "
            + Math.round(target) + " blocks" + (seconds > 0 ? " over " + seconds + "s." : "."));
    }

    private void sendHungerGamesAdminStatus(CommandSender sender, QueueType type) {
        sender.sendMessage(ChatColor.AQUA + type.displayName() + ChatColor.GRAY + " lobby="
            + hungerGamesLocalLobbyIds.getOrDefault(type, "none"));

        LinkedHashSet<UUID> queue = queues.get(type);
        List<String> queueNames = new ArrayList<>();
        for (UUID id : queue) {
            Player queued = Bukkit.getPlayer(id);
            queueNames.add(queued != null ? queued.getName() : id.toString());
        }
        sender.sendMessage(ChatColor.GRAY + "Queue: " + ChatColor.WHITE + queue.size()
            + "/" + idealPlayersFor(type) + ChatColor.DARK_GRAY + " " + queueNames);
        CountdownState countdown = countdowns.get(type);
        if (countdown != null) {
            sender.sendMessage(ChatColor.GRAY + "Countdown: " + ChatColor.WHITE + countdown.secondsRemaining + "s");
        }

        boolean preparing = prewarmInProgress.contains(type);
        Deque<PendingStart> pendingStarts = pendingMatchStarts.get(type);
        int pendingCount = pendingStarts == null ? 0 : pendingStarts.size();
        sender.sendMessage(ChatColor.GRAY + "Preparing world: "
            + (preparing ? ChatColor.YELLOW + "yes" : ChatColor.WHITE + "no")
            + (pendingCount > 0 ? ChatColor.YELLOW + " (" + pendingCount + " start pending)" : ""));

        List<String> prewarmed = prewarmedMatchWorldsFor(type);
        sender.sendMessage(ChatColor.GRAY + "Ready arena: "
            + (!prewarmed.isEmpty()
                ? ChatColor.GREEN + String.valueOf(prewarmed.size()) + ChatColor.DARK_GRAY + " " + prewarmed
                : ChatColor.WHITE + "0")
            + (hungerGamesKeepReadyArena ? ChatColor.DARK_GRAY + " [keep-ready on]" : ""));

        List<String> activeWorlds = activeMatchWorldsFor(type);
        sender.sendMessage(ChatColor.GRAY + "Active matches: " + ChatColor.WHITE + activeWorlds.size());
        for (String worldName : activeWorlds) {
            int alive = activePlayersInWorld(worldName).size();
            int spectators = countSpectatorsInWorld(worldName);
            long startedAt = matchStartedAtMs.getOrDefault(worldName, 0L);
            String elapsed = startedAt > 0 ? ((System.currentTimeMillis() - startedAt) / 1000L) + "s" : "?";
            boolean koth = kothService != null && kothService.isActiveInWorld(worldName);
            sender.sendMessage(ChatColor.AQUA + "  - " + worldName
                + ChatColor.GRAY + " map=" + ChatColor.WHITE + hungerGamesMapDisplayName(worldName)
                + ChatColor.GRAY + " alive=" + ChatColor.WHITE + alive
                + ChatColor.GRAY + " spec=" + ChatColor.WHITE + spectators
                + ChatColor.GRAY + " elapsed=" + ChatColor.WHITE + elapsed
                + (koth ? ChatColor.LIGHT_PURPLE + " [KOTH]" : ""));
        }
    }

    /**
     * Admin tool: inject a player into a live Hunger Games match (Phase 4). Mirrors the
     * per-player onboarding in finalizePreparedMatchLaunch. Allowed only before the
     * deathmatch/KOTH phase and while the match is not ending.
     */
    public void adminAddPlayerToMatch(CommandSender sender, Player target, String worldNameOrNull) {
        QueueType type = QueueType.HUNGERGAMES;
        if (target == null || !target.isOnline()) {
            sender.sendMessage(ChatColor.RED + "Target player is not online.");
            return;
        }
        String worldName;
        if (worldNameOrNull != null && !worldNameOrNull.isBlank()) {
            worldName = resolveActiveHungerGamesWorld(worldNameOrNull);
            if (worldName == null) {
                sender.sendMessage(ChatColor.RED + "No active Hunger Games match world named '" + worldNameOrNull + "'.");
                return;
            }
        } else {
            worldName = primaryActiveMatchWorld(type);
            if (worldName == null) {
                worldName = primaryActiveMatchWorld(QueueType.HUNGERGAMES_DUOS);
            }
            if (worldName == null) {
                sender.sendMessage(ChatColor.RED + "No active Hunger Games match to add a player to.");
                return;
            }
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            sender.sendMessage(ChatColor.RED + "Match world '" + worldName + "' is not loaded.");
            return;
        }
        type = resolveQueueTypeForWorld(worldName);
        if (endingMatchWorlds.contains(worldName)) {
            sender.sendMessage(ChatColor.RED + "That match is ending; cannot add players.");
            return;
        }
        if (kothService != null && kothService.isActiveInWorld(worldName)) {
            sender.sendMessage(ChatColor.RED + "Deathmatch (KOTH) has started; too late to add players.");
            return;
        }
        UUID targetId = target.getUniqueId();
        if (inMatchPlayers.contains(targetId) || pendingMatchLaunches.containsKey(targetId)) {
            sender.sendMessage(ChatColor.RED + target.getName() + " is already in a match.");
            return;
        }

        // Clean any prior queue/spectator state.
        QueueType queuedType = queuedPlayers.get(targetId);
        if (queuedType != null) {
            removeFromQueue(targetId, queuedType);
            maybeCleanupPrewarmedWorld(queuedType);
        }
        String spectatorWorld = spectatingMatchWorlds.remove(targetId);
        pendingSpectatorRespawnWorld.remove(targetId);
        clearBattleRoyaleSnapshots(targetId);
        clearCustomSpectatorState(target);

        // Onboard as a live combatant.
        inMatchPlayers.add(targetId);
        inMatchTypes.put(targetId, type);
        matchKills.put(targetId, 0);
        inMatchWorlds.put(targetId, worldName);
        if (hungerGamesDuoWorlds.contains(rootMatchWorldName(worldName))) {
            String root = rootMatchWorldName(worldName);
            duoTeamByPlayer.put(targetId, targetId);
            Map<UUID, Set<UUID>> roster = hungerGamesDuoRosters.computeIfAbsent(root, ignored -> new LinkedHashMap<>());
            roster.put(targetId, new LinkedHashSet<>(List.of(targetId)));
            hungerGamesDuoTeamColors.put(root, assignHungerGamesDuoTeamColors(roster.keySet()));
        }
        if (menuService != null) {
            menuService.preparePlayerForMatch(target);
        }
        Location spawn = safeHungerGamesAddSpawn(world);
        if (spawn != null) {
            if (spawn.getWorld() != null
                && !isChunkLoadedAt(spawn.getWorld(), spawn.getBlockX(), spawn.getBlockZ())) {
                loadChunkSquare(spawn.getWorld(), spawn.getBlockX(), spawn.getBlockZ(), 0, true);
            }
            target.teleport(spawn);
        }
        target.setGameMode(GameMode.SURVIVAL);
        fullyHealMatchPlayer(target, type);
        target.setFallDistance(0.0f);
        target.setNoDamageTicks(60); // brief grace so a late join is not instakilled on arrival
        refreshSidebar(target);
        target.sendMessage(HYDRA_PREFIX + ChatColor.AQUA + "You were added to the Hunger Games match.");
        target.playSound(target.getLocation(), Sound.ENTITY_PLAYER_LEVELUP, 1.0f, 1.1f);

        if (spectatorWorld != null) {
            syncSpectatorVisibility(spectatorWorld);
        }
        syncSpectatorVisibility(worldName);
        maybeEvaluateMatchState(type, worldName);

        int alive = activePlayersInWorld(worldName).size();
        sender.sendMessage(ChatColor.GREEN + "Added " + target.getName() + " to HG match " + worldName
            + " (" + alive + " alive).");
        notifyMatchWorldPlayers(worldName, HYDRA_PREFIX + ChatColor.YELLOW + target.getName()
            + " was added to the match.");
        plugin.getLogger().info("[Queue] Admin " + sender.getName() + " added " + target.getName()
            + " to HG match " + worldName);
    }

    private String resolveActiveHungerGamesWorld(String name) {
        if (name == null || name.isBlank()) {
            return null;
        }
        for (Map.Entry<QueueType, String> entry : activeMatchWorldEntries()) {
            String active = entry.getValue();
            if (isHungerGames(entry.getKey()) && (active.equalsIgnoreCase(name)
                || isSameMatchSessionWorld(rootMatchWorldName(active), name))) {
                return active;
            }
        }
        return null;
    }

    private Location safeHungerGamesAddSpawn(World world) {
        if (world == null) {
            return null;
        }
        // Prefer the arena centre (world spawn): it is always inside a shrinking border
        // and sits on the cornucopia surface, so a late joiner can't land outside the
        // border or in the void.
        Location center = world.getSpawnLocation();
        if (center != null && center.getWorld() != null) {
            return center;
        }
        List<Location> spawns = generateHungerGamesSpawns(world, 1);
        if (spawns != null && !spawns.isEmpty() && spawns.get(0) != null) {
            return spawns.get(0);
        }
        return center;
    }

    private int countSpectatorsInWorld(String worldName) {
        if (worldName == null) {
            return 0;
        }
        String root = rootMatchWorldName(worldName);
        int count = 0;
        for (String spectatingWorld : spectatingMatchWorlds.values()) {
            if (isSameMatchSessionWorld(root, spectatingWorld)) {
                count++;
            }
        }
        return count;
    }

    private String hungerGamesMapDisplayName(String worldName) {
        HungerGamesMapDefinition definition = hungerGamesMapDefinitionByKey(hungerGamesMapKeysByWorld.get(worldName));
        if (definition != null) {
            return definition.displayName();
        }
        String key = hungerGamesMapKeysByWorld.get(worldName);
        return key == null || key.isBlank() ? "?" : key;
    }

    private void notifyMatchWorldPlayers(String worldName, String message) {
        World world = worldName == null ? null : Bukkit.getWorld(worldName);
        if (world == null) {
            return;
        }
        for (Player player : world.getPlayers()) {
            player.sendMessage(message);
        }
    }

    public void sendCaveDebug(Player player) {
        if (!hasQueueAdminAccess(player)) {
            return;
        }
        if (!brTerrainEnabled) {
            player.sendMessage(HydraIcons.EXCLAMATION_RED + " " + ChatColor.RED + "BR terrain is disabled in config.");
            return;
        }

        World world = player.getWorld();
        Location location = player.getLocation();
        int x = location.getBlockX();
        int y = location.getBlockY();
        int z = location.getBlockZ();
        int minY = Math.max(world.getMinHeight(), brTerrainMinYHint);
        int maxY = Math.min(world.getMaxHeight() - 1, brTerrainMaxYHint);
        if (maxY <= minY + 8) {
            maxY = world.getMaxHeight() - 1;
            minY = world.getMinHeight();
        }

        BattleRoyaleChunkGenerator generator = new BattleRoyaleChunkGenerator(
            brTerrainMapDiameter,
            brTerrainMinYHint,
            brTerrainMaxYHint,
            brTerrainProfile,
            brTerrainProfile == BrTerrainProfile.AEOS_ISLES,
            false,
            originExclusionRadius()
        );
        BattleRoyaleChunkGenerator.CaveDebugSnapshot debug =
            generator.sampleCaveDebug(world.getSeed(), x, y, z, minY, maxY);

        player.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.GOLD + "Queue Cave Debug");
        player.sendMessage(ChatColor.GRAY + "World: " + ChatColor.WHITE + world.getName()
            + ChatColor.DARK_GRAY + " seed=" + ChatColor.WHITE + world.getSeed());
        player.sendMessage(ChatColor.GRAY + "Pos: " + ChatColor.WHITE + x + ", " + y + ", " + z);
        player.sendMessage(ChatColor.GRAY + "Surface: " + ChatColor.WHITE + debug.surfaceBiome().name()
            + ChatColor.DARK_GRAY + " topY=" + ChatColor.WHITE + debug.topY()
            + ChatColor.DARK_GRAY + " depth=" + ChatColor.WHITE + debug.depth());
        player.sendMessage(ChatColor.GRAY + "Profile: " + ChatColor.WHITE + debug.profile().name()
            + ChatColor.DARK_GRAY + " distance=" + ChatColor.WHITE
            + String.format(Locale.US, "%.1f", debug.distance()));
        player.sendMessage(ChatColor.GRAY + "Bands: " + ChatColor.WHITE
            + String.format(Locale.US, "%.3f", debug.heightWeight())
            + ChatColor.DARK_GRAY + " network=" + ChatColor.WHITE
            + String.format(Locale.US, "%.3f", debug.networkMask())
            + ChatColor.DARK_GRAY + " entrance=" + ChatColor.WHITE + debug.entranceBand());
        player.sendMessage(ChatColor.GRAY + "Fields: " + ChatColor.WHITE + "tunnel="
            + String.format(Locale.US, "%.3f", debug.tunnel())
            + ChatColor.DARK_GRAY + " cavern=" + ChatColor.WHITE + String.format(Locale.US, "%.3f", debug.cavern())
            + ChatColor.DARK_GRAY + " shaft=" + ChatColor.WHITE + String.format(Locale.US, "%.3f", debug.shaft())
            + ChatColor.DARK_GRAY + " conn=" + ChatColor.WHITE + String.format(Locale.US, "%.3f", debug.connectivity()));
        player.sendMessage(ChatColor.GRAY + "Score: " + ChatColor.WHITE
            + String.format(Locale.US, "%.3f", debug.carveScore())
            + ChatColor.DARK_GRAY + " threshold=" + ChatColor.WHITE
            + String.format(Locale.US, "%.3f", debug.threshold()));
        player.sendMessage(ChatColor.GRAY + "Decision: "
            + (debug.shouldCarve() ? ChatColor.GREEN + "CARVE" : ChatColor.RED + "SOLID")
            + ChatColor.DARK_GRAY + " (" + debug.reason() + ")");
    }

    public void clearQueue(QueueType typeOrNull) {
        if (typeOrNull == null) {
            for (QueueType type : QueueType.values()) {
                clearQueue(type);
            }
            return;
        }

        LinkedHashSet<UUID> queue = queues.get(typeOrNull);
        for (UUID id : new ArrayList<>(queue)) {
            removeFromQueue(id, typeOrNull);
            Player player = Bukkit.getPlayer(id);
            if (player != null) {
                player.sendMessage(ChatColor.YELLOW + "Queue cleared.");
                if (isHungerGames(typeOrNull) && player.isOnline()) {
                    returnToHub(player, true);
                }
            }
        }
        cancelCountdown(typeOrNull, "Queue cleared by admin.");
        maybeCleanupPrewarmedWorld(typeOrNull);
    }

    public void forceStart(QueueType type, CommandSender sender) {
        if (matchStartInProgress.contains(type)) {
            sender.sendMessage(ChatColor.YELLOW + type.displayName()
                + " already has a start pending. The current world preparation will be reused.");
            return;
        }
        plugin.getLogger().info("[Queue] forcestart requested by " + sender.getName() + " for " + type.displayName());
        startMatch(type, true, sender);
    }

    /** Local queue generations, globally numbered across Solo/Duos for this service lifetime. */
    public List<String> hungerGamesLocalLobbyIds(boolean duos) {
        QueueType type = duos ? QueueType.HUNGERGAMES_DUOS : QueueType.HUNGERGAMES;
        String id = hungerGamesLocalLobbyIds.get(type);
        return localHungerGamesQueuesAvailable() && id != null && queueSize(type) > 0
            ? List.of(id) : List.of();
    }

    /** Null/blank selects the current queue; explicit stale or foreign IDs never fall back. */
    public boolean forceStartHungerGames(boolean duos, String localLobbyId, CommandSender sender) {
        Objects.requireNonNull(sender, "sender");
        QueueType type = duos ? QueueType.HUNGERGAMES_DUOS : QueueType.HUNGERGAMES;
        List<String> ids = hungerGamesLocalLobbyIds(duos);
        if (ids.isEmpty()) {
            sender.sendMessage(ChatColor.RED + "No local " + type.displayName() + " lobby is queued.");
            return false;
        }
        if (localLobbyId != null && !localLobbyId.isBlank()
            && !ids.contains(localLobbyId.trim().toLowerCase(Locale.ROOT))) {
            sender.sendMessage(ChatColor.RED + "No local " + type.displayName() + " lobby named '"
                + localLobbyId + "'. Current lobby: " + ids.getFirst());
            return false;
        }
        if (matchStartInProgress.contains(type) || hasPendingMatchStart(type)) {
            sender.sendMessage(ChatColor.YELLOW + ids.getFirst() + " already has a start pending.");
            return false;
        }
        forceStart(type, sender);
        return true;
    }

    private boolean localHungerGamesQueuesAvailable() {
        return pendingNetworkHungerGamesReservationId == null
            && (!(plugin instanceof HGLootPlugin hydra) || hydra.networkNodeConfig() == null
                || !hydra.networkNodeConfig().enabled());
    }

    private void ensureHungerGamesLocalLobbyId(QueueType type) {
        if (isHungerGames(type) && queueSize(type) > 0 && localHungerGamesQueuesAvailable()) {
            hungerGamesLocalLobbyIds.computeIfAbsent(type, ignored -> "hg-" + nextHungerGamesLocalLobbyNumber++);
        }
    }

    public void triggerWinCheck(QueueType typeOrNull, CommandSender sender) {
        if (typeOrNull != null) {
            List<String> worlds = activeMatchWorldsFor(typeOrNull);
            if (worlds.isEmpty()) {
                sender.sendMessage(ChatColor.YELLOW + "No active " + typeOrNull.displayName() + " match to check.");
                return;
            }
            for (String worldName : worlds) {
                int alive = activePlayersInWorld(worldName).size();
                evaluateMatchState(typeOrNull, worldName);
                sender.sendMessage(ChatColor.GREEN + "Win check triggered for "
                    + typeOrNull.displayName() + " " + worldName + " (" + alive + " alive before check).");
            }
            return;
        }

        List<Map.Entry<QueueType, String>> activeEntries = activeMatchWorldEntries();
        if (activeEntries.isEmpty()) {
            sender.sendMessage(ChatColor.YELLOW + "No active matches to check.");
            return;
        }
        int checks = 0;
        for (Map.Entry<QueueType, String> entry : activeEntries) {
            QueueType type = entry.getKey();
            String worldName = entry.getValue();
            if (worldName == null) {
                continue;
            }
            evaluateMatchState(type, worldName);
            checks++;
        }
        sender.sendMessage(ChatColor.GREEN + "Win check triggered for " + checks + " active match(es).");
    }

    public void triggerHungerGamesWinCheck(CommandSender sender) {
        triggerWinCheck(QueueType.HUNGERGAMES, sender);
        triggerWinCheck(QueueType.HUNGERGAMES_DUOS, sender);
    }

    public List<String> activeHungerGamesWorldNames() {
        return activeMatchWorldEntries().stream()
            .filter(entry -> isHungerGames(entry.getKey())).map(Map.Entry::getValue).toList();
    }

    public boolean forceEndHungerGames(String worldOrNull, CommandSender sender) {
        String target = worldOrNull;
        if ((target == null || target.isBlank()) && sender instanceof Player player
            && isHungerGames(resolveQueueTypeForWorld(player.getWorld().getName()))) {
            target = player.getWorld().getName();
        }
        List<String> worlds = activeHungerGamesWorldNames();
        if (target == null || target.isBlank()) {
            if (worlds.size() != 1) {
                sender.sendMessage(ChatColor.RED + "Specify an active HG world: " + worlds);
                return false;
            }
            target = worlds.getFirst();
        }
        String world = resolveActiveHungerGamesWorld(target);
        if (world == null) {
            sender.sendMessage(ChatColor.RED + "No active HG world named '" + target + "'.");
            return false;
        }
        return forceEndMatch(resolveQueueTypeForWorld(world), world, sender);
    }

    public boolean forceEndMatch(QueueType type, String worldOrNull, CommandSender sender) {
        if (type == null) {
            if (sender != null) {
                sender.sendMessage(ChatColor.RED + "Match type is required.");
            }
            return false;
        }
        List<String> activeWorlds = activeMatchWorldsFor(type);
        if (activeWorlds.isEmpty()) {
            if (sender != null) {
                sender.sendMessage(ChatColor.YELLOW + "No active " + type.displayName() + " match to force-end.");
            }
            return false;
        }

        String targetWorld = resolveForceEndWorld(type, worldOrNull, activeWorlds);
        if (targetWorld == null) {
            if (sender != null) {
                if (worldOrNull == null || worldOrNull.isBlank()) {
                    sender.sendMessage(ChatColor.RED + "Multiple active " + type.displayName()
                        + " matches exist. Provide a world name: " + activeWorlds);
                } else {
                    sender.sendMessage(ChatColor.RED + "No active " + type.displayName()
                        + " match matches '" + worldOrNull + "'. Active: " + activeWorlds);
                }
            }
            return false;
        }

        broadcastMatchWorldMessage(targetWorld, HydraIcons.EXCLAMATION_RED + " " + ChatColor.RED
            + "This match was ended by staff.");
        plugin.getLogger().warning("[Queue] force-end requested by "
            + (sender == null ? "system" : sender.getName()) + " for " + type.displayName()
            + " world=" + targetWorld);
        finishMatchWorld(type, targetWorld);
        if (sender != null) {
            sender.sendMessage(ChatColor.GREEN + "Force-ended " + type.displayName() + " match " + targetWorld + ".");
        }
        return true;
    }

    private String resolveForceEndWorld(QueueType type, String worldOrNull, List<String> activeWorlds) {
        if (activeWorlds == null || activeWorlds.isEmpty()) {
            return null;
        }
        if (worldOrNull == null || worldOrNull.isBlank()) {
            return activeWorlds.size() == 1 ? activeWorlds.get(0) : null;
        }
        String normalized = worldOrNull.trim();
        for (String worldName : activeWorlds) {
            if (worldName.equalsIgnoreCase(normalized)
                || isSameMatchSessionWorld(rootMatchWorldName(worldName), normalized)) {
                return worldName;
            }
        }
        return null;
    }

    public boolean isAutoWinTriggerEnabled() {
        return autoWinTriggerEnabled;
    }

    public void setAutoWinTriggerEnabled(boolean enabled, CommandSender sender) {
        if (autoWinTriggerEnabled == enabled) {
            if (sender != null) {
                sender.sendMessage(ChatColor.GRAY + "Auto win trigger is already "
                    + (enabled ? ChatColor.GREEN + "ENABLED" : ChatColor.RED + "DISABLED") + ChatColor.GRAY + ".");
            }
            return;
        }

        autoWinTriggerEnabled = enabled;
        plugin.getConfig().set("queue.settings.auto_win_trigger", autoWinTriggerEnabled);
        plugin.saveConfig();

        String state = enabled ? "ENABLED" : "DISABLED";
        String actor = sender != null ? sender.getName() : "system";
        plugin.getLogger().info("[Queue] Auto win trigger " + state + " by " + actor);

        if (sender != null) {
            sender.sendMessage(ChatColor.GREEN + "Auto win trigger is now "
                + (enabled ? ChatColor.GREEN + "ENABLED" : ChatColor.RED + "DISABLED") + ChatColor.GREEN + ".");
        }

        if (!enabled) {
            return;
        }

        for (Map.Entry<QueueType, String> entry : activeMatchWorldEntries()) {
            QueueType type = entry.getKey();
            String worldName = entry.getValue();
            if (type == null || worldName == null || worldName.isBlank()) {
                continue;
            }
            evaluateMatchState(type, worldName);
        }
    }

