    public int cleanupStaleHungerGamesWorldFolders(CommandSender sender) {
        return cleanupStaleMatchWorldFolders(sender, QueueType.HUNGERGAMES);
    }

    public int cleanupStaleMatchWorldFolders(CommandSender sender, QueueType cleanupType) {
        if (!matchWorldAutoCleanup) {
            if (sender != null) {
                sender.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.YELLOW + "Match world cleanup is disabled.");
            }
            return 0;
        }
        Set<String> cleanupRoots = matchWorldService.staleRoots(Bukkit.getWorldContainer().toPath(),
            root -> isGeneratedMatchWorldName(root, cleanupType), this::isLiveOrReservedMatchWorld,
            this::generatedMatchRootName, QueueService::linkedNetherWorldName);
        for (String rootWorldName : cleanupRoots) {
            cleanupWorld(rootWorldName);
        }
        int cleaned = cleanupRoots.size();
        if (cleaned > 0) {
            plugin.getLogger().info("[Queue] Queued stale " + cleanupFamilyLabel(cleanupType)
                + " world cleanup for " + cleaned + " world(s).");
        }
        if (sender != null) {
            sender.sendMessage(HydraIcons.EXCLAMATION + " " + ChatColor.GREEN
                + "Queued stale " + cleanupFamilyLabel(cleanupType) + " cleanup for " + cleaned + " world(s).");
        }
        return cleaned;
    }

    private String generatedMatchRootName(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return "";
        }
        if (worldName.endsWith(MATCH_NETHER_WORLD_SUFFIX)) {
            return worldName.substring(0, worldName.length() - MATCH_NETHER_WORLD_SUFFIX.length());
        }
        return worldName;
    }

    private boolean isGeneratedMatchWorldName(String rootWorldName, QueueType cleanupType) {
        if (rootWorldName == null || rootWorldName.isBlank()) {
            return false;
        }
        boolean hungerGames = isGeneratedHungerGamesWorldName(rootWorldName);
        boolean battleRoyale = isGeneratedBattleRoyaleWorldName(rootWorldName);
        if (isHungerGames(cleanupType)) {
            return hungerGames;
        }
        if (cleanupType == QueueType.SOLO || cleanupType == QueueType.DUO) {
            return battleRoyale;
        }
        return hungerGames || battleRoyale;
    }

    private String cleanupFamilyLabel(QueueType cleanupType) {
        if (isHungerGames(cleanupType)) {
            return "Hunger Games";
        }
        if (cleanupType == QueueType.SOLO || cleanupType == QueueType.DUO) {
            return "Battle Royale";
        }
        return "match";
    }

    public void setLobby(Location location) {
        this.lobbySpawn = location.clone();
        saveSpawns();
    }

    public void setArenaSpawn(int index, Location location) {
        while (arenaSpawns.size() < index) {
            arenaSpawns.add(null);
        }
        arenaSpawns.set(index - 1, location.clone());
        saveSpawns();
    }

    public boolean removeArenaSpawn(int index) {
        if (index < 1 || index > arenaSpawns.size()) {
            return false;
        }
        arenaSpawns.remove(index - 1);
        saveSpawns();
        return true;
    }

    public void sendArenaList(CommandSender sender) {
        sender.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.GOLD + "Queue Arenas");
        if (lobbySpawn == null || lobbySpawn.getWorld() == null) {
            sender.sendMessage(ChatColor.GRAY + "Lobby: " + ChatColor.RED + "not set");
        } else {
            sender.sendMessage(ChatColor.GRAY + "Lobby: " + locationLabel(lobbySpawn));
        }
        if (arenaSpawns.isEmpty()) {
            sender.sendMessage(ChatColor.GRAY + "Arena spawns: " + ChatColor.RED + "none");
            return;
        }
        for (int i = 0; i < arenaSpawns.size(); i++) {
            Location location = arenaSpawns.get(i);
            if (location == null || location.getWorld() == null) {
                sender.sendMessage(ChatColor.GRAY + "#" + (i + 1) + ": " + ChatColor.RED + "unset");
                continue;
            }
            sender.sendMessage(ChatColor.GRAY + "#" + (i + 1) + ": " + locationLabel(location));
        }
    }

