    public boolean placeRandomStructureAtPlayer(Player player) {
        if (!hasQueueAdminAccess(player)) {
            return false;
        }
        if (matchStructureZipIds.isEmpty()) {
            player.sendMessage(ChatColor.RED + "No structure IDs loaded from zip.");
            return false;
        }
        World world = player.getWorld();
        List<String> eligible = matchStructureZipIds.stream()
            .filter(id -> isWorldAllowedForStructure(world, id))
            .toList();
        if (eligible.isEmpty()) {
            player.sendMessage(ChatColor.RED + "No structure IDs are valid for this world.");
            return false;
        }
        String id = eligible.get(ThreadLocalRandom.current().nextInt(eligible.size()));
        return placeStructureByIdAtPlayer(player, id);
    }

    public boolean placeBundledStructureAtPlayer(Player player, String rawSeedId) {
        if (!hasQueueAdminAccess(player)) {
            return false;
        }
        if (matchStructureZipIds.isEmpty()) {
            player.sendMessage(ChatColor.RED + "No structure IDs loaded from zip.");
            return false;
        }

        String seedId;
        if (rawSeedId == null || rawSeedId.isBlank()) {
            seedId = matchStructureZipIds.get(ThreadLocalRandom.current().nextInt(matchStructureZipIds.size()));
        } else {
            seedId = normalizeStructureId(rawSeedId);
            boolean known = matchStructureZipIds.stream()
                .map(QueueService::normalizeStructureId)
                .anyMatch(seedId::equals);
            if (!known) {
                player.sendMessage(ChatColor.RED + "Unknown structure id: " + rawSeedId);
                return false;
            }
        }

        World world = player.getWorld();
        if (!isWorldAllowedForStructure(world, seedId)) {
            player.sendMessage(ChatColor.RED + seedId + " is Nether-only and can only spawn in Nether worlds.");
            return false;
        }
        double zoneRadius = structureZoneRadius();
        List<Location> occupiedCenters = collectStructureMarkerCenters(world);
        boolean requireWater = requiresWaterSpawn(seedId);
        boolean requireMineshaft = isMineshaftStructure(seedId);
        Location target = findPlacementCandidate(
            world,
            player.getLocation().getX(),
            player.getLocation().getZ(),
            30.0D,
            requireWater,
            seedId,
            occupiedCenters,
            zoneRadius,
            matchStructureZipEdgeBuffer,
            requireWater ? ResourceZone.WETLAND : (requireMineshaft ? ResourceZone.ROCK : null)
        );
        if (target == null) {
            player.sendMessage(ChatColor.RED + "No valid placement found nearby for bundle.");
            return false;
        }

        int bundlePlaced = placeStructureBundleAt(
            world,
            seedId,
            target.getBlockX(),
            target.getBlockY(),
            target.getBlockZ(),
            matchStructureBundleDepth,
            occupiedCenters,
            zoneRadius
        );
        if (bundlePlaced <= 0) {
            player.sendMessage(ChatColor.RED + "Failed to place bundled structure.");
            return false;
        }

        player.sendMessage(ChatColor.GREEN + "Placed bundled structure (seed=" + seedId
            + ", depth=" + matchStructureBundleDepth + ") at "
            + target.getBlockX() + ", " + target.getBlockY() + ", " + target.getBlockZ() + ".");
        return true;
    }

    public boolean placeStructureByIdAtPlayer(Player player, String rawId) {
        if (!hasQueueAdminAccess(player)) {
            return false;
        }
        if (matchStructureZipIds.isEmpty()) {
            player.sendMessage(ChatColor.RED + "No structure IDs loaded from zip.");
            return false;
        }
        String id = normalizeStructureId(rawId);
        boolean known = matchStructureZipIds.stream()
            .map(QueueService::normalizeStructureId)
            .anyMatch(id::equals);
        if (!known) {
            player.sendMessage(ChatColor.RED + "Unknown structure id: " + rawId);
            return false;
        }

        World world = player.getWorld();
        if (!isWorldAllowedForStructure(world, id)) {
            player.sendMessage(ChatColor.RED + id + " is Nether-only and can only spawn in Nether worlds.");
            return false;
        }
        double zoneRadius = structureZoneRadius();
        List<Location> occupiedCenters = collectStructureMarkerCenters(world);
        boolean requireWater = requiresWaterSpawn(id);
        boolean requireMineshaft = isMineshaftStructure(id);
        Location target = findPlacementCandidate(
            world,
            player.getLocation().getX(),
            player.getLocation().getZ(),
            30.0D,
            requireWater,
            id,
            occupiedCenters,
            zoneRadius,
            matchStructureZipEdgeBuffer,
            requireWater ? ResourceZone.WETLAND : (requireMineshaft ? ResourceZone.ROCK : null)
        );
        if (target == null) {
            player.sendMessage(ChatColor.RED + "No valid placement found nearby for " + id + ".");
            return false;
        }

        boolean ok = placeStructureAt(world, id, target.getBlockX(), target.getBlockY(), target.getBlockZ(), true);
        if (!ok) {
            player.sendMessage(ChatColor.RED + "Failed to place " + id + ".");
            return false;
        }

        player.sendMessage(ChatColor.GREEN + "Placed " + id + " at "
            + target.getBlockX() + ", " + target.getBlockY() + ", " + target.getBlockZ() + ".");
        return true;
    }

    public int placeStructureGridAtPlayer(Player player, int count) {
        if (!hasQueueAdminAccess(player)) {
            return 0;
        }
        if (matchStructureZipIds.isEmpty()) {
            player.sendMessage(ChatColor.RED + "No structure IDs loaded from zip.");
            return 0;
        }
        int clamped = Math.max(1, Math.min(64, count));
        int side = (int) Math.ceil(Math.sqrt(clamped));
        double zoneRadius = structureZoneRadius();
        int spacing = Math.max((int) Math.ceil(zoneRadius * 2.0D), Math.max(64, matchStructureZipMinDistance));
        Location base = player.getLocation();
        World world = base.getWorld();
        if (world == null) {
            return 0;
        }

        int halfSpan = ((side - 1) * spacing) / 2;
        List<String> ids = new ArrayList<>(matchStructureZipIds);
        Collections.shuffle(ids, ThreadLocalRandom.current());
        List<Location> occupiedCenters = collectStructureMarkerCenters(world);
        int placed = 0;

        for (int row = 0; row < side && placed < clamped; row++) {
            for (int col = 0; col < side && placed < clamped; col++) {
                String id = ids.get((row * side + col) % ids.size());
                if (!isWorldAllowedForStructure(world, id)) {
                    continue;
                }
                int x = base.getBlockX() - halfSpan + (col * spacing);
                int z = base.getBlockZ() - halfSpan + (row * spacing);
                if (!isWithinWorldBorder(world, x, z, matchStructureZipEdgeBuffer)) {
                    continue;
                }
                if (!isOutsideOriginExclusion(x, z)) {
                    continue;
                }
                boolean requireWater = requiresWaterSpawn(id);
                Integer y = pickPlacementYForStructure(world, id, x, z, requireWater);
                if (y == null) {
                    continue;
                }
                if (isMineshaftStructure(id)) {
                    if (!isMountainSurfaceBiome(world, x, z) || !hasTreeCoverNear(world, x, z, 6)) {
                        continue;
                    }
                }
                Location candidate = new Location(world, x, y, z);
                if (!isFarEnough(occupiedCenters, candidate, zoneRadius)) {
                    continue;
                }
                if (placeStructureAt(world, id, x, y, z, true)) {
                    placed++;
                    occupiedCenters.add(candidate);
                }
            }
        }
        player.sendMessage(ChatColor.GREEN + "Grid placed " + placed + "/" + clamped + " structure(s).");
        return placed;
    }

    public int previewMatchStructurePlacement(Player player) {
        if (!hasQueueAdminAccess(player)) {
            return 0;
        }
        if (matchStructureZipIds.isEmpty()) {
            player.sendMessage(ChatColor.RED + "No structure IDs loaded from zip.");
            return 0;
        }
        World world = player.getWorld();
        WorldBorder border = world.getWorldBorder();
        double half = Math.max(16.0D, (border.getSize() / 2.0D) - 8.0D);
        double radius = Math.min(matchStructureZipRadius, half);
        double centerX = border.getCenter().getX();
        double centerZ = border.getCenter().getZ();

        List<String> ids = new ArrayList<>(matchStructureZipIds);
        Collections.shuffle(ids, ThreadLocalRandom.current());
        if (matchStructureZipMaxCount > 0 && ids.size() > matchStructureZipMaxCount) {
            ids = new ArrayList<>(ids.subList(0, matchStructureZipMaxCount));
        }

        List<Location> placedCenters = new ArrayList<>();
        int placed = 0;
        placedCenters.addAll(collectStructureMarkerCenters(world));
        double minDistance = structureZoneRadius();

        for (String id : ids) {
            if (!isWorldAllowedForStructure(world, id)) {
                continue;
            }
            boolean requireWater = requiresWaterSpawn(id);
            boolean requireMineshaft = isMineshaftStructure(id);
            Location target = findPlacementCandidate(
                world,
                centerX,
                centerZ,
                radius,
                requireWater,
                id,
                placedCenters,
                minDistance,
                matchStructureZipEdgeBuffer,
                requireWater ? ResourceZone.WETLAND : (requireMineshaft ? ResourceZone.ROCK : null)
            );
            if (target == null) {
                continue;
            }
            if (placeStructureAt(world, id, target.getBlockX(), target.getBlockY(), target.getBlockZ(), true)) {
                placed++;
                placedCenters.add(target);
            }
        }

        player.sendMessage(ChatColor.GREEN + "Preview placed " + placed + "/" + ids.size() + " structure(s).");
        return placed;
    }

    public void locateStructureMarkers(Player player, int radius) {
        locateStructureMarkers(player, null, radius);
    }

    public void locateStructureMarkers(Player player, String rawStructureId, int radius) {
        if (!hasQueueAdminAccess(player)) {
            return;
        }
        World world = player.getWorld();
        String normalizedFilter = "";
        if (rawStructureId != null && !rawStructureId.isBlank()) {
            normalizedFilter = normalizeHydraQueueStructureId(rawStructureId);
            if (normalizedFilter.isBlank()) {
                normalizedFilter = normalizeStructureId(rawStructureId);
            }
        }
        String structureFilter = normalizedFilter;
        List<Entity> markers = world.getNearbyEntities(player.getLocation(), radius, radius, radius).stream()
            .filter(this::isStructureMarker)
            .filter(entity -> structureFilter.isBlank() || structureFilter.equals(markerStructureId(entity)))
            .sorted((a, b) -> Double.compare(
                a.getLocation().distanceSquared(player.getLocation()),
                b.getLocation().distanceSquared(player.getLocation())
            ))
            .toList();
        if (markers.isEmpty()) {
            if (structureFilter.isBlank()) {
                player.sendMessage(ChatColor.YELLOW + "No structure markers found within radius " + radius + ".");
            } else {
                player.sendMessage(ChatColor.YELLOW + "No structure markers found for "
                    + ChatColor.WHITE + structureFilter + ChatColor.YELLOW + " within radius " + radius + ".");
            }
            return;
        }

        player.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.GOLD + "Queue Structure Marker Locations");
        player.sendMessage(ChatColor.GRAY + "World: " + ChatColor.WHITE + world.getName()
            + ChatColor.DARK_GRAY + " radius=" + ChatColor.WHITE + radius
            + ChatColor.DARK_GRAY + " found=" + ChatColor.WHITE + markers.size());
        if (!structureFilter.isBlank()) {
            player.sendMessage(ChatColor.GRAY + "Filter: " + ChatColor.WHITE + structureFilter);
        }

        int shown = 0;
        for (Entity marker : markers) {
            Location loc = marker.getLocation();
            String id = markerStructureId(marker);
            String safeId = (id == null || id.isBlank()) ? "unknown" : id;
            double distance = Math.sqrt(loc.distanceSquared(player.getLocation()));
            player.sendMessage(ChatColor.DARK_GRAY + "- " + ChatColor.WHITE + safeId
                + ChatColor.GRAY + " @ " + ChatColor.AQUA + loc.getBlockX() + ", "
                + loc.getBlockY() + ", " + loc.getBlockZ()
                + ChatColor.DARK_GRAY + " (" + String.format(Locale.US, "%.1f", distance) + "m)");
            shown++;
            if (shown >= 30 && markers.size() > shown) {
                player.sendMessage(ChatColor.DARK_GRAY + "... (" + (markers.size() - shown) + " more)");
                break;
            }
        }
    }

    public void sendStructureSpawnReport(Player player, int radiusFromCenter) {
        if (!hasQueueAdminAccess(player)) {
            return;
        }
        World world = player.getWorld();
        WorldBorder border = world.getWorldBorder();
        double centerX = border.getCenter().getX();
        double centerZ = border.getCenter().getZ();
        double radius = Math.max(0.0D, radiusFromCenter);

        List<ArmorStand> markers = world.getEntitiesByClass(ArmorStand.class).stream()
            .filter(this::isStructureMarker)
            .filter(entity -> {
                if (radius <= 0.0D) {
                    return true;
                }
                Location loc = entity.getLocation();
                return Math.hypot(loc.getX() - centerX, loc.getZ() - centerZ) <= radius;
            })
            .sorted((a, b) -> Double.compare(
                Math.hypot(a.getLocation().getX() - centerX, a.getLocation().getZ() - centerZ),
                Math.hypot(b.getLocation().getX() - centerX, b.getLocation().getZ() - centerZ)
            ))
            .toList();

        if (markers.isEmpty()) {
            if (radius > 0.0D) {
                player.sendMessage(ChatColor.YELLOW + "No structure markers found within " + (int) radius + " blocks of world center.");
            } else {
                player.sendMessage(ChatColor.YELLOW + "No structure markers found in this world.");
            }
            return;
        }

        player.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.GOLD + "Queue Structure Spawn Report");
        player.sendMessage(ChatColor.GRAY + "World: " + ChatColor.WHITE + world.getName()
            + ChatColor.DARK_GRAY + " center=" + ChatColor.WHITE
            + (int) Math.round(centerX) + ", " + (int) Math.round(centerZ)
            + ChatColor.DARK_GRAY + " found=" + ChatColor.WHITE + markers.size());
        if (radius > 0.0D) {
            player.sendMessage(ChatColor.GRAY + "Filter radius: " + ChatColor.WHITE + (int) radius);
        }

        int shown = 0;
        for (ArmorStand marker : markers) {
            Location loc = marker.getLocation();
            String id = markerStructureId(marker);
            String safeId = (id == null || id.isBlank()) ? "unknown" : id;
            double centerDistance = Math.hypot(loc.getX() - centerX, loc.getZ() - centerZ);
            player.sendMessage(ChatColor.DARK_GRAY + "- " + ChatColor.WHITE + safeId
                + ChatColor.GRAY + " @ " + ChatColor.AQUA + loc.getBlockX() + ", "
                + loc.getBlockY() + ", " + loc.getBlockZ()
                + ChatColor.DARK_GRAY + " (center "
                + String.format(Locale.US, "%.1f", centerDistance) + "m)");
            shown++;
            if (shown >= 60 && markers.size() > shown) {
                player.sendMessage(ChatColor.DARK_GRAY + "... (" + (markers.size() - shown) + " more)");
                break;
            }
        }
    }

    public void sendStructureRejectSummary(Player player) {
        if (!hasQueueAdminAccess(player)) {
            return;
        }
        if (player == null) {
            return;
        }
        World world = player.getWorld();
        if (world == null) {
            player.sendMessage(ChatColor.RED + "Could not resolve your world.");
            return;
        }
        StructureRejectSummary summary = structureRejectSummaries.get(world.getName());
        if (summary == null) {
            player.sendMessage(ChatColor.YELLOW + "No structure rejection summary captured for this world yet.");
            return;
        }

        int totalRejects = totalRejects(summary.rejectCounts());
        long ageSeconds = Math.max(0L, (System.currentTimeMillis() - summary.generatedAtMs()) / 1000L);
        player.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.GOLD + "Queue Structure Reject Summary");
        player.sendMessage(ChatColor.GRAY + "World: " + ChatColor.WHITE + world.getName()
            + ChatColor.DARK_GRAY + " age=" + ChatColor.WHITE + ageSeconds + "s");
        player.sendMessage(ChatColor.GRAY + "Placed: " + ChatColor.WHITE + summary.placed()
            + ChatColor.DARK_GRAY + " / planned " + ChatColor.WHITE + summary.planned()
            + ChatColor.DARK_GRAY + " bundled=" + ChatColor.WHITE + summary.bundled());
        player.sendMessage(ChatColor.GRAY + "Rejected attempts: " + ChatColor.WHITE + totalRejects);

        if (summary.rejectCounts().isEmpty()) {
            player.sendMessage(ChatColor.GREEN + "No rejection reasons were recorded.");
            return;
        }

        int shown = 0;
        for (Map.Entry<String, Integer> entry : sortedRejectEntries(summary.rejectCounts())) {
            player.sendMessage(ChatColor.DARK_GRAY + "- "
                + ChatColor.WHITE + entry.getKey()
                + ChatColor.GRAY + ": "
                + ChatColor.AQUA + entry.getValue());
            shown++;
            if (shown >= 14 && summary.rejectCounts().size() > shown) {
                player.sendMessage(ChatColor.DARK_GRAY + "... (" + (summary.rejectCounts().size() - shown) + " more)");
                break;
            }
        }
    }

    public void validateStructureMarkers(Player player, int radius) {
        if (!hasQueueAdminAccess(player)) {
            return;
        }
        World world = player.getWorld();
        List<Entity> markers = world.getNearbyEntities(player.getLocation(), radius, radius, radius).stream()
            .filter(this::isStructureMarker)
            .toList();
        if (markers.isEmpty()) {
            player.sendMessage(ChatColor.YELLOW + "No structure markers found within radius " + radius + ".");
            return;
        }

        Map<String, Integer> countsById = new HashMap<>();
        double minDistance = Double.MAX_VALUE;
        for (int i = 0; i < markers.size(); i++) {
            Entity a = markers.get(i);
            String id = markerStructureId(a);
            String safeId = id == null ? "unknown" : id;
            Integer current = countsById.get(safeId);
            countsById.put(safeId, current == null ? 1 : current + 1);
            Location al = a.getLocation();
            for (int j = i + 1; j < markers.size(); j++) {
                double dist = al.distance(markers.get(j).getLocation());
                if (dist < minDistance) {
                    minDistance = dist;
                }
            }
        }

        player.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.GOLD + "Queue Structure Validation");
        player.sendMessage(ChatColor.GRAY + "World: " + ChatColor.WHITE + world.getName());
        player.sendMessage(ChatColor.GRAY + "Markers: " + ChatColor.WHITE + markers.size());
        player.sendMessage(ChatColor.GRAY + "Unique IDs: " + ChatColor.WHITE + countsById.size());
        if (minDistance != Double.MAX_VALUE) {
            player.sendMessage(ChatColor.GRAY + "Closest pair: " + ChatColor.WHITE + String.format(Locale.US, "%.1f", minDistance) + " blocks");
        }
        int shown = 0;
        for (Map.Entry<String, Integer> entry : countsById.entrySet()) {
            player.sendMessage(ChatColor.DARK_GRAY + "- " + entry.getKey() + ": " + entry.getValue());
            shown++;
            if (shown >= 8 && countsById.size() > shown) {
                player.sendMessage(ChatColor.DARK_GRAY + "... (" + (countsById.size() - shown) + " more)");
                break;
            }
        }
    }

    public int clearStructureMarkers(Player player, int radius) {
        if (!hasQueueAdminAccess(player)) {
            return 0;
        }
        World world = player.getWorld();
        List<Entity> markers = new ArrayList<>(world.getNearbyEntities(player.getLocation(), radius, radius, radius));
        int removed = 0;
        for (Entity entity : markers) {
            if (!isStructureMarker(entity)) {
                continue;
            }
            entity.remove();
            removed++;
        }
        STRUCTURE_PROTECTION_MASKS.remove(world.getName());
        player.sendMessage(ChatColor.YELLOW + "Removed " + removed + " structure marker(s).");
        return removed;
    }

    @EventHandler
    public void onPlayerJoin(PlayerJoinEvent event) {
        Player player = event.getPlayer();
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (player == null || !player.isOnline()) {
                return;
            }
            if (plugin instanceof HGLootPlugin hydra && hydra.networkNodeConfig() != null
                && hydra.networkNodeConfig().enabled()
                && hydra.networkNodeConfig().role() != hgloot.plugin.network.BackendRole.HUB) {
                // NetworkBridgeService owns placement after a proxy backend transfer.
                return;
            }
            hidePersonalLeaderboardViewsFrom(player);
            if (rejoinBattleRoyale(player, true)) {
                return;
            }
            if (!inMatchPlayers.contains(player.getUniqueId())
                && !spectatingMatchWorlds.containsKey(player.getUniqueId())
                && !pendingSpectatorRespawnWorld.containsKey(player.getUniqueId())) {
                returnToHub(player, false);
            } else {
                refreshSidebar(player);
            }
        }, 2L);
    }

    @EventHandler
    public void onPlayerQuit(PlayerQuitEvent event) {
        Player player = event.getPlayer();
        UUID playerId = player.getUniqueId();
        if (queuedPlayers.containsKey(playerId)
            || inMatchPlayers.contains(playerId)
            || spectatingMatchWorlds.containsKey(playerId)
            || pendingSpectatorRespawnWorld.containsKey(playerId)) {
            event.quitMessage(null);
        }
        clearLeaderboardPlayerViews(player);
        leaderboardInteractCooldownUntilMs.remove(playerId);
        sidebarContentSignatures.remove(playerId);
        clearFakePcsState(player);
        clearHungerGamesStartFreeze(player);
        clearHungerGamesCombatGrace(player);
        clearCornucopiaCampState(playerId);
        aeosLaunchPadCooldownUntilMs.remove(playerId);
        pendingLegendaryKillContexts.remove(playerId);
        lastDamageTakenHearts.remove(playerId);
        QueueType queuedType = queuedPlayers.get(playerId);
        if (queuedType != null) {
            removeFromQueue(playerId, queuedType);
        }
        if (inMatchPlayers.contains(playerId)) {
            QueueType matchType = inMatchTypes.get(playerId);
            String worldName = inMatchWorlds.get(playerId);
            if (supportsReviveSnapshot(matchType) && worldName != null && hasActiveMatchSession(matchType, worldName)) {
                BattleRoyalePlayerSnapshot snapshot = captureBattleRoyaleSnapshot(player, matchType, worldName, false);
                if (snapshot != null) {
                    clearCornucopiaCampState(playerId);
                    brRejoinSnapshots.put(playerId, snapshot);
                    spawnReconnectZombie(player, snapshot);
                    return;
                }
            }
            removeFromMatch(playerId, null, false);
        }
        String spectatorWorld = spectatingMatchWorlds.get(playerId);
        String pendingWorld = pendingSpectatorRespawnWorld.get(playerId);
        String trackedWorld = spectatorWorld != null ? spectatorWorld : pendingWorld;
        QueueType trackedType = resolveQueueTypeForWorld(trackedWorld);
        if (trackedWorld != null && supportsReviveSnapshot(trackedType)) {
            BattleRoyalePlayerSnapshot snapshot = captureBattleRoyaleSnapshot(player, trackedType, trackedWorld, true);
            if (snapshot != null) {
                if (spectatorWorld == null) {
                    spectatingMatchWorlds.put(playerId, trackedWorld);
                    pendingSpectatorRespawnWorld.remove(playerId);
                }
                brRejoinSnapshots.put(playerId, snapshot);
                if (isHungerGames(trackedType)) {
                    logHungerGamesPlayerTransition(player, "spectator_logout_preserved",
                        "match=" + trackedWorld + " pending=" + (spectatorWorld == null));
                }
                return;
            }
        }
        if (spectatorWorld != null) {
            spectatingMatchWorlds.remove(playerId);
            clearCustomSpectatorState(player);
            syncSpectatorVisibility(spectatorWorld);
        }
        pendingSpectatorRespawnWorld.remove(playerId);
    }

    @EventHandler
    public void onPlayerDeath(PlayerDeathEvent event) {
        Player player = event.getEntity();
        UUID playerId = player.getUniqueId();
        clearFakePcsState(player);
        clearHungerGamesStartFreeze(player);
        clearHungerGamesCombatGrace(player);
        if (plugin instanceof HGLootPlugin hydra
            && hydra.gameHubService() != null
            && hydra.gameHubService().isFightPit(player.getLocation())) {
            return;
        }
        applyCustomDeathMessage(event);
        if (isHungerGames(inMatchTypes.get(playerId))) {
            sendHungerGamesDeathMessage(event);
        }
        if (!inMatchPlayers.contains(playerId)) {
            lastDamageTakenHearts.remove(playerId);
            return;
        }
        String worldName = inMatchWorlds.get(playerId);
        QueueType type = inMatchTypes.get(playerId);
        int placement = isHungerGames(type) && worldName != null
            ? activeParticipantCountInWorld(worldName)
            : 0;
        awardKill(event);
        if (isHungerGames(type) && worldName != null
            && plugin instanceof HGLootPlugin hydra && hydra.battlePassService() != null) {
            hydra.battlePassService().completeHgMatch(playerId, rootMatchWorldName(worldName), placement);
        }
        if (supportsReviveSnapshot(type) && worldName != null && hasActiveMatchSession(type, worldName)) {
            BattleRoyalePlayerSnapshot snapshot = captureBattleRoyaleSnapshot(player, type, worldName, false);
            if (snapshot != null) {
                brReviveSnapshots.put(playerId, snapshot);
            }
        }
        if (isHungerGames(type)) {
            restoreStandardPlayerHealth(player);
        }
        if (worldName != null) {
            pendingSpectatorRespawnWorld.put(playerId, worldName);
            if (isHungerGames(type)) {
                logHungerGamesPlayerTransition(player, "death_pending_spectator",
                    "match=" + worldName + " mode=" + type + " queue=" + queuedPlayers.get(playerId));
            }
        }
        removeFromMatch(playerId, null, false);
        sendDeathRecap(player, event);
    }

    @EventHandler
    public void onPlayerRespawn(PlayerRespawnEvent event) {
        UUID playerId = event.getPlayer().getUniqueId();
        clearFakePcsState(event.getPlayer());
        clearHungerGamesStartFreeze(event.getPlayer());
        clearHungerGamesCombatGrace(event.getPlayer());
        String worldName = pendingSpectatorRespawnWorld.get(playerId);
        if (worldName == null) {
            return;
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            pendingSpectatorRespawnWorld.remove(playerId, worldName);
            if (isHungerGames(resolveQueueTypeForWorld(worldName))) {
                plugin.getLogger().warning("[Queue][HGDeath] respawn_world_missing player=" + playerId
                    + " match=" + worldName);
            }
            if (lobbySpawn != null && lobbySpawn.getWorld() != null) {
                event.setRespawnLocation(lobbySpawn);
            }
            return;
        }
        event.setRespawnLocation(world.getSpawnLocation());
        if (isHungerGames(resolveQueueTypeForWorld(worldName))) {
            logHungerGamesPlayerTransition(event.getPlayer(), "respawn_destination_selected",
                "match=" + worldName + " destination=" + world.getSpawnLocation());
        }
        Bukkit.getScheduler().runTask(plugin, () -> {
            Player player = event.getPlayer();
            if (!player.isOnline()) {
                return;
            }
            if (!worldName.equals(pendingSpectatorRespawnWorld.get(playerId))) {
                return;
            }
            if (!worldName.equals(player.getWorld().getName())) {
                if (isHungerGames(resolveQueueTypeForWorld(worldName))) {
                    plugin.getLogger().warning("[Queue][HGDeath] spectator_setup_world_mismatch player=" + playerId
                        + " expected=" + worldName + " actual=" + player.getWorld().getName());
                }
                return;
            }
            setCustomSpectatorState(player, worldName, true);
            pendingSpectatorRespawnWorld.remove(playerId, worldName);
            if (isHungerGames(resolveQueueTypeForWorld(worldName))) {
                logHungerGamesPlayerTransition(player, "spectator_ready", "match=" + worldName);
            }
            player.sendTitle(ChatColor.RED + "" + ChatColor.BOLD + "ELIMINATED",
                ChatColor.GRAY + "Use the compass to spectate.", 5, 40, 10);
            HydraSounds.playSpectatorEnter(player);
        });
    }

    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onPlayerPortal(PlayerPortalEvent event) {
        if (event.getCause() != PlayerTeleportEvent.TeleportCause.NETHER_PORTAL) {
            return;
        }
        Player player = event.getPlayer();
        World sourceWorld = player.getWorld();
        if (sourceWorld == null) {
            return;
        }
        String sourceWorldName = sourceWorld.getName();
        String rootWorldName = rootMatchWorldName(sourceWorldName);
        QueueType type = resolveQueueTypeForWorld(rootWorldName);
        if (type == null || isHungerGames(type) || !brMatchWorlds.contains(rootWorldName)) {
            return;
        }

        World targetWorld;
        double targetX;
        double targetZ;
        int preferredY;
        if (sourceWorld.getEnvironment() == World.Environment.NORMAL) {
            targetWorld = getOrCreateLinkedNetherWorld(rootWorldName, type);
            if (targetWorld == null) {
                return;
            }
            targetX = event.getFrom().getX() / 8.0D;
            targetZ = event.getFrom().getZ() / 8.0D;
            preferredY = Math.max(targetWorld.getMinHeight() + 8, Math.min(targetWorld.getMaxHeight() - 4, 96));
        } else if (sourceWorld.getEnvironment() == World.Environment.NETHER && isLinkedNetherMatchWorld(sourceWorldName)) {
            targetWorld = Bukkit.getWorld(rootWorldName);
            if (targetWorld == null) {
                return;
            }
            targetX = event.getFrom().getX() * 8.0D;
            targetZ = event.getFrom().getZ() * 8.0D;
            preferredY = Math.max(targetWorld.getMinHeight() + 2,
                targetWorld.getHighestBlockYAt((int) Math.round(targetX), (int) Math.round(targetZ), HeightMap.MOTION_BLOCKING_NO_LEAVES) + 1);
        } else {
            return;
        }

        Location destination = findSafePortalDestination(targetWorld, targetX, targetZ, preferredY);
        if (destination == null) {
            destination = targetWorld.getSpawnLocation().clone().add(0.5D, 0.0D, 0.5D);
        }
        destination.setYaw(event.getFrom().getYaw());
        destination.setPitch(event.getFrom().getPitch());
        ensureSpawnSpace(destination);
        event.setTo(destination);
    }

    @EventHandler
    public void onPlayerChangedWorld(PlayerChangedWorldEvent event) {
        Player player = event.getPlayer();
        String fromWorldName = event.getFrom() == null ? null : event.getFrom().getName();
        String toWorldName = player.getWorld() == null ? null : player.getWorld().getName();
        if (!isSameMatchSessionWorld(fromWorldName, toWorldName) || Objects.equals(fromWorldName, toWorldName)) {
            return;
        }

        UUID playerId = player.getUniqueId();
        if (inMatchPlayers.contains(playerId) && inMatchWorlds.containsKey(playerId)) {
            inMatchWorlds.put(playerId, toWorldName);
        }
        if (spectatingMatchWorlds.containsKey(playerId)) {
            spectatingMatchWorlds.put(playerId, toWorldName);
        }
        if (pendingSpectatorRespawnWorld.containsKey(playerId)) {
            pendingSpectatorRespawnWorld.put(playerId, toWorldName);
        }

        syncSpectatorVisibility(fromWorldName);
        syncSpectatorVisibility(toWorldName);
        refreshSidebar(player);
    }

    @EventHandler
    public void onSpectatorInteract(PlayerInteractEvent event) {
        Player player = event.getPlayer();
        if (isFakePcsControlled(player)) {
            event.setCancelled(true);
            return;
        }
        if (!isCustomSpectator(player)) {
            return;
        }
        if (event.getAction() != Action.RIGHT_CLICK_AIR && event.getAction() != Action.RIGHT_CLICK_BLOCK) {
            event.setCancelled(true);
            return;
        }

        String action = readSpectatorAction(event.getItem());
        event.setCancelled(true);
        if (SPECTATOR_ACTION_TELEPORT_COMPASS.equals(action)) {
            openSpectatorTeleportMenu(player);
            return;
        }
        if (SPECTATOR_ACTION_HUB_PAPER.equals(action)) {
            String worldName = spectatingMatchWorlds.remove(player.getUniqueId());
            clearCustomSpectatorState(player);
            syncSpectatorVisibility(worldName);
            returnToHub(player, true);
            player.sendMessage(ChatColor.GRAY + "Returned to hub.");
            return;
        }
        if (SPECTATOR_ACTION_HG_REQUEUE.equals(action)) {
            String worldName = spectatingMatchWorlds.get(player.getUniqueId());
            if (!isHungerGames(resolveQueueTypeForWorld(worldName))) {
                player.sendMessage(ChatColor.RED + "Requeue is only available after an HG elimination.");
                return;
            }
            boolean duos = hungerGamesDuoWorlds.contains(rootMatchWorldName(worldName));
            leaveQueueOrMatch(player);
            Bukkit.getScheduler().runTask(plugin, () -> {
                if (player.isOnline() && !isPlayerQueued(player.getUniqueId())
                    && !isPlayerInHydraMatchOrSpectating(player.getUniqueId())) {
                    // Requeue only this spectator, never pull a still-playing party member.
                    joinQueue(player, duos ? QueueType.HUNGERGAMES_DUOS : QueueType.HUNGERGAMES, false);
                }
            });
        }
    }

    @EventHandler
    public void onSpectatorInventoryClick(InventoryClickEvent event) {
        if (!(event.getWhoClicked() instanceof Player player)) {
            return;
        }
        boolean spectator = isCustomSpectator(player);
        boolean teleportMenu = isSpectatorTeleportMenu(event);
        if (!spectator && !teleportMenu) {
            return;
        }
        event.setCancelled(true);

        if (!teleportMenu) {
            return;
        }
        if (event.getClickedInventory() == null || event.getCurrentItem() == null) {
            return;
        }
        if (event.getClickedInventory() != event.getView().getTopInventory()) {
            return;
        }

        String action = readSpectatorAction(event.getCurrentItem());
        if (action == null || action.isBlank()) {
            return;
        }
        if (SPECTATOR_ACTION_CLOSE.equals(action)) {
            player.closeInventory();
            return;
        }
        if (!action.startsWith(SPECTATOR_ACTION_TARGET_PREFIX)) {
            return;
        }

        String rawUuid = action.substring(SPECTATOR_ACTION_TARGET_PREFIX.length());
        UUID targetId;
        try {
            targetId = UUID.fromString(rawUuid);
        } catch (IllegalArgumentException ignored) {
            player.sendMessage(ChatColor.RED + "Invalid target.");
            return;
        }

        String worldName = spectatingMatchWorlds.get(player.getUniqueId());
        if (worldName == null) {
            player.sendMessage(ChatColor.RED + "Not spectating.");
            player.closeInventory();
            return;
        }
        if (!inMatchPlayers.contains(targetId)) {
            player.sendMessage(ChatColor.YELLOW + "Player not alive.");
            return;
        }
        String targetWorld = inMatchWorlds.get(targetId);
        if (!isSameMatchSessionWorld(worldName, targetWorld)) {
            player.sendMessage(ChatColor.YELLOW + "Player not in match.");
            return;
        }

        Player target = Bukkit.getPlayer(targetId);
        if (target == null || !target.isOnline()) {
            player.sendMessage(ChatColor.YELLOW + "Target offline.");
            return;
        }
        transitionTravel(player, () -> {
            if (!player.isOnline() || !target.isOnline() || !inMatchPlayers.contains(targetId)
                || !isSameMatchSessionWorld(spectatingMatchWorlds.get(player.getUniqueId()), inMatchWorlds.get(targetId))) {
                return;
            }
            player.teleport(target.getLocation().clone().add(0.0D, 1.0D, 0.0D));
            player.sendMessage(ChatColor.GRAY + "Teleported to " + ChatColor.WHITE + target.getName());
        });
    }

