    @EventHandler(ignoreCancelled = true)
    public void onHungerGamesStartFreezeMove(PlayerMoveEvent event) {
        Player player = event.getPlayer();
        if (!isHungerGamesStartFrozen(player) || event.getTo() == null) {
            return;
        }
        Location from = event.getFrom();
        Location to = event.getTo();
        if (from.getX() == to.getX() && from.getY() == to.getY() && from.getZ() == to.getZ()) {
            return;
        }
        Location locked = lockedHungerGamesStartLocation(player, to.getYaw(), to.getPitch());
        player.setSprinting(false);
        event.setTo(locked);
    }

