    private void constrainValousPregeneratedBounds(PlayerMoveEvent event) {
        Player player = event.getPlayer();
        Location to = event.getTo();
        if (to == null || to.getWorld() == null) {
            return;
        }
        String worldName = rootMatchWorldName(to.getWorld().getName());
        ValousGenerationSize size = valousGenerationSizesByWorld.get(worldName);
        if (size == null || (!inMatchPlayers.contains(player.getUniqueId()) && !isCustomSpectator(player))) {
            return;
        }
        WorldBorder border = to.getWorld().getWorldBorder();
        int viewDistance = valousViewDistance(size);
        double safeHalfWidth = Math.max(8.0D,
            (valousPreloadDiameter(size) / 2.0D) - (viewDistance * 16.0D) - 1.0D);
        double centerX = border.getCenter().getX();
        double centerZ = border.getCenter().getZ();
        double boundedX = clamp(to.getX(), centerX - safeHalfWidth, centerX + safeHalfWidth);
        double boundedZ = clamp(to.getZ(), centerZ - safeHalfWidth, centerZ + safeHalfWidth);
        if (boundedX == to.getX() && boundedZ == to.getZ()) {
            return;
        }
        Location bounded = to.clone();
        bounded.setX(boundedX);
        bounded.setZ(boundedZ);
        event.setTo(bounded);
    }

