    @EventHandler(ignoreCancelled = true)
    public void onAeosLaunchPadStep(PlayerMoveEvent event) {
        Player player = event.getPlayer();
        if (player.isFlying() || player.isGliding() || !isAeosTraversalWorld(player.getWorld())) {
            return;
        }
        if (event.getTo() == null) {
            return;
        }
        if (event.getFrom().getBlockX() == event.getTo().getBlockX()
            && event.getFrom().getBlockY() == event.getTo().getBlockY()
            && event.getFrom().getBlockZ() == event.getTo().getBlockZ()) {
            return;
        }
        if (player.getVelocity().getY() > 0.35D) {
            return;
        }

        long now = System.currentTimeMillis();
        long cooldownUntil = aeosLaunchPadCooldownUntilMs.getOrDefault(player.getUniqueId(), 0L);
        if (cooldownUntil > now) {
            return;
        }

        Block standingOn = event.getTo().getBlock().getRelative(0, -1, 0);
        if (standingOn.getType() != Material.SLIME_BLOCK || !isAeosBiome(standingOn.getBiome())) {
            return;
        }

        Vector velocity = player.getVelocity();
        player.setVelocity(new Vector(velocity.getX() * 0.30D, AEOS_LAUNCH_PAD_VERTICAL_VELOCITY, velocity.getZ() * 0.30D));
        player.addPotionEffect(new PotionEffect(PotionEffectType.SLOW_FALLING, AEOS_LAUNCH_PAD_SLOW_FALLING_TICKS, 0, false, true, true));
        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_SLIME_JUMP, 1.0F, 0.85F);
        aeosLaunchPadCooldownUntilMs.put(player.getUniqueId(), now + AEOS_LAUNCH_PAD_COOLDOWN_MS);
    }

    @EventHandler(ignoreCancelled = true)
    public void onFakePcsMove(PlayerMoveEvent event) {
        Player player = event.getPlayer();
        FakePcsPlayerState state = fakePcsState(player);
        if (state == null) {
            return;
        }
        player.setFallDistance(0.0F);
        if (!inMatchPlayers.contains(player.getUniqueId()) && state.phase() == FakePcsPhase.IN_PLANE) {
            clearFakePcsState(player);
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onFakePcsJump(PlayerToggleFlightEvent event) {
        Player player = event.getPlayer();
        FakePcsPlayerState state = fakePcsState(player);
        if (state == null || state.phase() != FakePcsPhase.IN_PLANE) {
            return;
        }
        event.setCancelled(true);
        fakePcsStates.put(player.getUniqueId(), launchFakePcsJump(player, state, Bukkit.getCurrentTick()));
        player.sendMessage(PREFIX + ChatColor.AQUA + "Jumped from the plane.");
        player.playSound(player.getLocation(), Sound.ENTITY_ENDER_DRAGON_FLAP, 0.9F, 1.25F);
    }

    @EventHandler
    public void onSpectatorBlockPlace(BlockPlaceEvent event) {
        if (isHungerGamesStartFrozen(event.getPlayer())) {
            event.setCancelled(true);
            return;
        }
        if (isHydraBrWorld(event.getBlockPlaced().getWorld()) && isInsideCornucopiaProtectedZone(event.getBlockPlaced().getLocation())) {
            event.setCancelled(true);
            event.getPlayer().sendMessage(ChatColor.RED + "Building disabled here.");
            return;
        }
        if (!isCustomSpectator(event.getPlayer())) {
            String reason = underworldProtectionReason(event.getPlayer(), event.getBlockPlaced());
            if (reason != null) {
                event.setCancelled(true);
                event.getPlayer().sendMessage(ChatColor.RED + reason);
                return;
            }
            if (isHungerGames(inMatchTypes.get(event.getPlayer().getUniqueId()))
                && isHungerGamesMatchWorld(event.getBlockPlaced().getWorld())
                && event.getBlockPlaced().getType() == Material.TNT) {
                ignitePlacedHungerGamesTnt(event.getBlockPlaced(), event.getPlayer());
            }
            return;
        }
        event.setCancelled(true);
    }

