    public void trackHungerGamesPlacedBlock(BlockPlaceEvent event) {
        scheduleHungerGamesPlacedBlockDecay(event.getPlayer(), event.getBlockPlaced(),
            event.getBlockReplacedState().getBlockData().clone());
    }

