    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onTntMinecartDamage(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof Player)
            || !(event.getDamager() instanceof ExplosiveMinecart)) {
            return;
        }
        event.setDamage(capTntMinecartDamage(event.getDamage()));
    }

    static double capTntMinecartDamage(double damage) {
        return Math.min(damage, TNT_MINECART_PLAYER_DAMAGE_CAP);
    }

    @EventHandler
    public void onSpectatorBlockBreak(BlockBreakEvent event) {
        if (isHungerGamesStartFrozen(event.getPlayer())) {
            event.setCancelled(true);
            return;
        }
        if (isHydraBrWorld(event.getBlock().getWorld()) && isInsideCornucopiaProtectedZone(event.getBlock().getLocation())) {
            event.setCancelled(true);
            event.getPlayer().sendMessage(ChatColor.RED + "Cannot break Cornucopia.");
            return;
        }
        if (!isCustomSpectator(event.getPlayer())) {
            HGLootPlugin hydra = plugin instanceof HGLootPlugin hydraPlugin ? hydraPlugin : null;
            if (hydra != null && hydra.spleefService() != null && hydra.spleefService().isAliveSpleefPlayer(event.getPlayer().getUniqueId())) {
                return;
            }
            if (isHungerGames(inMatchTypes.get(event.getPlayer().getUniqueId()))
                && isHungerGamesMatchWorld(event.getBlock().getWorld())) {
                if (hungerGamesPlacedBlocks.containsKey(blockLocationKey(event.getBlock().getLocation()))) {
                    return; // Any contestant may break a player placement, never authored terrain.
                }
                if (isHungerGamesTemporaryOreBedrock(event.getBlock())) {
                    event.setCancelled(true);
                    return;
                }
                if (handleHungerGamesOreBreak(event.getPlayer(), event.getBlock())) {
                    event.setCancelled(true);
                    return;
                }
                if (handleHungerGamesRespawningDecorBreak(event)) {
                    return;
                }
                event.setCancelled(true);
                return;
            }
            String reason = underworldProtectionReason(event.getPlayer(), event.getBlock());
            if (reason == null) {
                return;
            }
            event.setCancelled(true);
            event.getPlayer().sendMessage(ChatColor.RED + reason);
            return;
        }
        event.setCancelled(true);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void clearBrokenHungerGamesPlacement(BlockBreakEvent event) {
        String key = blockLocationKey(event.getBlock().getLocation());
        HungerGamesPlacedBlock placed = hungerGamesPlacedBlocks.remove(key);
        if (placed != null && placed.task != null) placed.task.cancel();
    }

    @EventHandler(ignoreCancelled = true)
    public void onHungerGamesBucketEmpty(PlayerBucketEmptyEvent event) {
        Player player = event.getPlayer();
        if (!isHungerGames(inMatchTypes.get(player.getUniqueId()))) {
            return;
        }
        Block placedBlock = event.getBlock().getRelative(event.getBlockFace());
        Material bucket = event.getBucket();
        Material fluidType = bucket == Material.WATER_BUCKET ? Material.WATER : bucket == Material.LAVA_BUCKET ? Material.LAVA : null;
        Bukkit.getScheduler().runTask(plugin, () -> {
            if (fluidType == null) {
                scheduleHungerGamesPlacedBlockDecay(player, placedBlock, null);
                return;
            }
            trackHungerGamesTemporaryFluid(player, placedBlock, fluidType);
        });
    }

    @EventHandler(ignoreCancelled = true)
    public void onHungerGamesFluidSpread(BlockFromToEvent event) {
        Block source = event.getBlock();
        Material fluidType = source.getType();
        if (fluidType != Material.WATER && fluidType != Material.LAVA) {
            return;
        }
        if (!isHungerGamesMatchWorld(source.getWorld())) {
            return;
        }
        if (!hungerGamesTemporaryFluidBlocks.containsKey(blockLocationKey(source.getLocation()))) {
            return;
        }
        Block target = event.getToBlock();
        Bukkit.getScheduler().runTask(plugin, () -> trackHungerGamesTemporaryFluid(null, target, fluidType));
    }

    @EventHandler(ignoreCancelled = true)
    public void onHungerGamesPrepareCraft(PrepareItemCraftEvent event) {
        ItemStack proposed = event.getInventory().getResult();
        String utilityId = hungerGamesUtilityRecipeId(event.getInventory().getRecipe(), proposed);
        Player utilityCrafter = event.getViewers().stream().filter(Player.class::isInstance)
            .map(Player.class::cast).filter(this::isHungerGamesActivePlayer).findFirst().orElse(null);
        if (utilityCrafter != null && utilityId != null && isHungerGamesCraftLimitReached(utilityCrafter, utilityId)) {
            event.getInventory().setResult(hungerGamesCraftLimitItem());
            return;
        }
        if (!isBlockedHungerGamesCraft(event.getInventory().getResult()) || !hasHungerGamesCraftViewer(event)) {
            return;
        }
        event.getInventory().setResult(new ItemStack(Material.AIR));
    }

    @EventHandler(ignoreCancelled = true)
    public void onHungerGamesCraftItem(CraftItemEvent event) {
        if (!(event.getWhoClicked() instanceof Player player)) {
            return;
        }
        if (!isHungerGamesActivePlayer(player)) {
            return;
        }
        if (isHungerGamesCraftLimitItem(event.getCurrentItem())) {
            event.setCancelled(true);
            player.sendMessage(ChatColor.RED + "Craft Limit Reached. You have reached the maximum crafts for this item this match.");
            return;
        }
        String utilityId = hungerGamesUtilityRecipeId(event.getRecipe(), event.getInventory().getResult());
        if (utilityId != null) {
            if (isHungerGamesCraftLimitReached(player, utilityId)) {
                event.setCancelled(true);
                player.sendMessage(ChatColor.RED + "Craft Limit Reached. You have reached the maximum crafts for this item this match.");
                return;
            }
            ItemStack result = hungerGamesUtilityCraftResult(event.getCurrentItem(), utilityId);
            if (result == null) return;
            if (event.isShiftClick()) {
                event.setCancelled(true);
                if (!canAcceptInventoryItem(player, result)) {
                    player.sendMessage(ChatColor.RED + "Your inventory is full.");
                    return;
                }
                consumeSingleCraft(event.getInventory());
                player.getInventory().addItem(result).values()
                    .forEach(leftover -> player.getWorld().dropItemNaturally(player.getLocation(), leftover));
                recordHungerGamesUtilityCraft(player, utilityId);
                Bukkit.getScheduler().runTask(plugin, player::updateInventory);
                return;
            }
            event.setCurrentItem(result);
            recordHungerGamesUtilityCraft(player, utilityId);
            return;
        }
        if (!isBlockedHungerGamesCraft(event.getCurrentItem())) {
            return;
        }
        event.setCancelled(true);
        player.sendMessage(ChatColor.RED + "Axes are disabled in Hunger Games crafting.");
    }

    @EventHandler(ignoreCancelled = true)
    public void onHungerGamesBowShoot(EntityShootBowEvent event) {
        if (!(event.getEntity() instanceof Player player) || !(event.getProjectile() instanceof AbstractArrow arrow)) {
            return;
        }
        if (!isHungerGamesActivePlayer(player) || !isPlainHungerGamesBow(event.getBow())) {
            return;
        }
        arrow.getPersistentDataContainer().set(hungerGamesBowProjectileKey, PersistentDataType.BYTE, (byte) 1);
    }

    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onHungerGamesBowDamage(EntityDamageByEntityEvent event) {
        if (!(event.getDamager() instanceof AbstractArrow arrow)
            || !(arrow.getShooter() instanceof Player shooter)
            || !arrow.getPersistentDataContainer().has(hungerGamesBowProjectileKey, PersistentDataType.BYTE)) {
            return;
        }
        if (!isHungerGamesActivePlayer(shooter)) {
            return;
        }
        event.setDamage(event.getDamage() * HUNGER_GAMES_BOW_DAMAGE_MULTIPLIER);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onValousMonsterCombatGlow(EntityDamageByEntityEvent event) {
        Monster monster = null;
        if (event.getEntity() instanceof Monster victim && isValousWorld(victim.getWorld())) {
            monster = victim;
        } else if (event.getDamager() instanceof Monster attacker && isValousWorld(attacker.getWorld())) {
            monster = attacker;
        }
        if (monster == null) {
            return;
        }
        if (!isValousMushroomBiome(monster.getLocation())) {
            return;
        }
        monster.addPotionEffect(new PotionEffect(PotionEffectType.GLOWING, VALOUS_MONSTER_GLOW_TICKS, 0, true, true, true));
    }

    @EventHandler(ignoreCancelled = true)
    public void onValousDeepMobSpawn(CreatureSpawnEvent event) {
        if (!(event.getEntity() instanceof Monster) || !isValousWorld(event.getLocation().getWorld())) {
            return;
        }
        if (event.getSpawnReason() != CreatureSpawnEvent.SpawnReason.NATURAL
            && event.getSpawnReason() != CreatureSpawnEvent.SpawnReason.CHUNK_GEN) {
            return;
        }
        if (isValousBiome(event.getLocation(), ValousPrototypeValidator.SCULK_ABYSS)) {
            event.setCancelled(true);
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onHungerGamesRodHook(PlayerFishEvent event) {
        if (event.getState() != PlayerFishEvent.State.CAUGHT_ENTITY) {
            return;
        }
        Player attacker = event.getPlayer();
        if (!(event.getCaught() instanceof Player victim) || !isHungerGamesActivePlayer(attacker) || !isHungerGamesActivePlayer(victim)) {
            return;
        }
        if (attacker.getUniqueId().equals(victim.getUniqueId())
            || isCustomSpectator(victim.getUniqueId())
            || isHungerGamesStartFrozen(attacker)
            || isHungerGamesStartFrozen(victim)
            || isHungerGamesCombatGraceActive(attacker)
            || isHungerGamesCombatGraceActive(victim)) {
            return;
        }
        Vector pull = attacker.getLocation().toVector().subtract(victim.getLocation().toVector());
        pull.setY(0.0D);
        if (pull.lengthSquared() <= 0.0001D) {
            return;
        }
        Vector velocity = victim.getVelocity().clone().multiply(HUNGER_GAMES_ROD_VELOCITY_DAMPING);
        Vector horizontalPull = pull.normalize().multiply(HUNGER_GAMES_ROD_PULL_HORIZONTAL);
        velocity.setX(velocity.getX() + horizontalPull.getX());
        velocity.setY(Math.max(HUNGER_GAMES_ROD_PULL_VERTICAL, velocity.getY() + HUNGER_GAMES_ROD_PULL_VERTICAL));
        velocity.setZ(velocity.getZ() + horizontalPull.getZ());
        victim.setFallDistance(0.0F);
        victim.setVelocity(velocity);
    }

    private boolean hasHungerGamesCraftViewer(PrepareItemCraftEvent event) {
        for (HumanEntity viewer : event.getViewers()) {
            if (viewer instanceof Player player && isHungerGamesActivePlayer(player)) {
                return true;
            }
        }
        return false;
    }

    private boolean isHungerGamesActivePlayer(Player player) {
        return player != null
            && isHungerGames(inMatchTypes.get(player.getUniqueId()))
            && isHungerGamesMatchWorld(player.getWorld())
            && !isCustomSpectator(player);
    }

    private boolean isBlockedHungerGamesCraft(ItemStack result) {
        return result != null
            && result.getType() != Material.AIR
            && result.getType().name().endsWith("_AXE");
    }

    private boolean isPlainHungerGamesBow(ItemStack bow) {
        if (bow == null || bow.getType() != Material.BOW) {
            return false;
        }
        if (!bow.hasItemMeta()) {
            return true;
        }
        ItemMeta meta = bow.getItemMeta();
        return meta == null || !meta.hasCustomModelDataComponent();
    }

    @EventHandler
    public void onUnderworldChunkLoad(ChunkLoadEvent event) {
        if (isHydraBrWorld(event.getWorld())) {
            ensureUnderworldAnchor(event.getChunk(), event.isNewChunk());
            if (event.getChunk().getX() == Math.floorDiv(cornucopiaAnchorX(), 16)
                && event.getChunk().getZ() == Math.floorDiv(cornucopiaAnchorZ(), 16)) {
                scheduleCornucopiaCenterEnsure(event.getWorld());
            }
        }
        if (!event.isNewChunk() || !isAeosWorld(event.getWorld())) {
            return;
        }
        ensureAeosTemplateWorldSynced(event.getWorld());
        scheduleAeosPlainsHousePlacement(event.getChunk());
    }

    private void scheduleCornucopiaCenterEnsure(World world) {
        scheduleCornucopiaCenterEnsure(world, 0L);
    }

    private void scheduleCornucopiaCenterEnsure(World world, long delayTicks) {
        if (world == null || !brMatchWorlds.contains(world.getName()) || !cornucopiaSpawnStructureEnabled) {
            return;
        }
        String worldName = world.getName();
        Runnable task = () -> {
            World liveWorld = Bukkit.getWorld(worldName);
            if (liveWorld == null || !brMatchWorlds.contains(liveWorld.getName())) {
                return;
            }
            if (!isCornucopiaPlacementPhaseActive(liveWorld.getName())) {
                return;
            }
            ensureCornucopiaAndPedestalsAtOrigin(liveWorld);
        };
        if (delayTicks <= 0L) {
            Bukkit.getScheduler().runTask(plugin, task);
            return;
        }
        Bukkit.getScheduler().runTaskLater(plugin, task, delayTicks);
    }

    private boolean isCornucopiaCenterAreaReady(World world) {
        if (world == null) {
            return false;
        }
        return isStructurePlacementAreaLoaded(world, cornucopiaStructureId, cornucopiaAnchorX(), cornucopiaAnchorZ(), 1)
            && isChunkSquareLoaded(world, (int) Math.floor(cornucopiaCenterX()), (int) Math.floor(cornucopiaCenterZ()), 1);
    }

    private void ensureCornucopiaCenterAreaReadyAsync(World world) {
        if (world == null || !brMatchWorlds.contains(world.getName()) || !cornucopiaSpawnStructureEnabled) {
            return;
        }
        String worldName = world.getName();
        if (!cornucopiaPlacementInProgress.add(worldName)) {
            return;
        }
        CompletableFuture<Boolean> footprintFuture = ensureStructurePlacementAreaLoadedAsync(
            world,
            cornucopiaStructureId,
            cornucopiaAnchorX(),
            cornucopiaAnchorZ(),
            1,
            true
        );
        CompletableFuture<Boolean> centerFuture = ensureChunkSquareLoadedAsync(
            world,
            (int) Math.floor(cornucopiaCenterX()),
            (int) Math.floor(cornucopiaCenterZ()),
            1,
            true
        );
        footprintFuture
            .thenCombine(centerFuture, (footprintLoaded, centerLoaded) -> Boolean.TRUE.equals(footprintLoaded)
                && Boolean.TRUE.equals(centerLoaded))
            .whenComplete((loaded, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
                World liveWorld = Bukkit.getWorld(worldName);
                cornucopiaPlacementInProgress.remove(worldName);
                if (liveWorld == null || !brMatchWorlds.contains(worldName)) {
                    return;
                }
                if (error != null || !Boolean.TRUE.equals(loaded) || !isCornucopiaCenterAreaReady(liveWorld)) {
                    plugin.getLogger().warning("[Queue] Cornucopia center area is still not ready in "
                        + worldName + "; retrying chunk preparation.");
                    scheduleCornucopiaCenterEnsure(liveWorld, 20L);
                    return;
                }
                ensureCornucopiaAndPedestalsAtOrigin(liveWorld);
            }));
    }

    private void scheduleAeosPlainsHousePlacement(Chunk chunk) {
        if (chunk == null) {
            return;
        }
        String worldName = chunk.getWorld().getName();
        int chunkX = chunk.getX();
        int chunkZ = chunk.getZ();
        Bukkit.getScheduler().runTask(plugin, () -> {
            World world = Bukkit.getWorld(worldName);
            if (world == null || !isAeosWorld(world)) {
                return;
            }
            placeAeosPlainsHouses(world, chunkX, chunkZ);
        });
    }

    private void placeAeosPlainsHouses(World world, int chunkX, int chunkZ) {
        if (world == null) {
            return;
        }
        long seed = world.getSeed();
        int minX = chunkX << 4;
        int minZ = chunkZ << 4;
        int maxX = minX + 15;
        int maxZ = minZ + 15;
        int cellMinX = Math.floorDiv(minX, AEOS_PLAINS_HOUSE_SPACING);
        int cellMaxX = Math.floorDiv(maxX, AEOS_PLAINS_HOUSE_SPACING);
        int cellMinZ = Math.floorDiv(minZ, AEOS_PLAINS_HOUSE_SPACING);
        int cellMaxZ = Math.floorDiv(maxZ, AEOS_PLAINS_HOUSE_SPACING);
        for (int cellX = cellMinX; cellX <= cellMaxX; cellX++) {
            for (int cellZ = cellMinZ; cellZ <= cellMaxZ; cellZ++) {
                int anchorX = aeosAnchorCoordinate(seed + 0xA50FL, cellX, cellZ, AEOS_PLAINS_HOUSE_SPACING, true);
                int anchorZ = aeosAnchorCoordinate(seed + 0xA50FL, cellX, cellZ, AEOS_PLAINS_HOUSE_SPACING, false);
                if (anchorX < minX || anchorX > maxX || anchorZ < minZ || anchorZ > maxZ) {
                    continue;
                }
                if (!shouldPlaceAeosPlainsHouse(seed, anchorX, anchorZ)) {
                    continue;
                }
                tryPlaceAeosPlainsHouse(world, anchorX, anchorZ);
            }
        }
    }

    private void tryPlaceAeosPlainsHouse(World world, int centerX, int centerZ) {
        if (world == null || !isAeosWorld(world)) {
            return;
        }
        int surfaceY = findRealSurfaceY(world, centerX, centerZ, false, false);
        if (surfaceY <= world.getMinHeight() + 1 || surfaceY >= world.getMaxHeight() - AEOS_PLAINS_HOUSE_HEIGHT - 2) {
            return;
        }
        Biome biome = world.getBiome(centerX, surfaceY, centerZ);
        if (biome != Biome.PLAINS) {
            return;
        }

        int originX = centerX - (AEOS_PLAINS_HOUSE_WIDTH_X / 2);
        int originZ = centerZ - (AEOS_PLAINS_HOUSE_WIDTH_Z / 2);
        if (!loadChunkSquare(world, centerX, centerZ, 1)) {
            return;
        }
        if (!isAeosHouseFootprintValid(world, originX, surfaceY, originZ)) {
            return;
        }

        flattenAeosHouseFootprint(world, originX, surfaceY, originZ);
        placeAeosTemplate(world, AEOS_PLAINS_HOUSE_TEMPLATE_ID, originX, surfaceY, originZ);
    }

    private boolean isAeosHouseFootprintValid(World world, int originX, int surfaceY, int originZ) {
        int supportedColumns = 0;
        int totalColumns = 0;
        for (int dx = -1; dx <= AEOS_PLAINS_HOUSE_WIDTH_X; dx++) {
            for (int dz = -1; dz <= AEOS_PLAINS_HOUSE_WIDTH_Z; dz++) {
                int x = originX + dx;
                int z = originZ + dz;
                int columnTop = findRealSurfaceY(world, x, z, false, false);
                Material topType = world.getBlockAt(x, columnTop, z).getType();
                if (topType.isAir() || !topType.isSolid()) {
                    return false;
                }
                if (Math.abs(columnTop - surfaceY) > 4) {
                    return false;
                }
                if (!isAeosBiome(world.getBiome(x, columnTop, z))) {
                    return false;
                }
                if (columnTop >= surfaceY - 2) {
                    supportedColumns++;
                }
                totalColumns++;
            }
        }
        return supportedColumns >= (int) Math.ceil(totalColumns * 0.82D);
    }

    private void flattenAeosHouseFootprint(World world, int originX, int surfaceY, int originZ) {
        int clearTop = Math.min(world.getMaxHeight() - 1, surfaceY + AEOS_PLAINS_HOUSE_HEIGHT + 4);
        for (int dx = -1; dx <= AEOS_PLAINS_HOUSE_WIDTH_X; dx++) {
            for (int dz = -1; dz <= AEOS_PLAINS_HOUSE_WIDTH_Z; dz++) {
                int x = originX + dx;
                int z = originZ + dz;
                int columnTop = findRealSurfaceY(world, x, z, false, false);
                int fillBase = Math.max(world.getMinHeight() + 1, surfaceY - 2);
                for (int y = fillBase; y <= surfaceY; y++) {
                    Material fill = y == surfaceY ? Material.GRASS_BLOCK : Material.DIRT;
                    world.getBlockAt(x, y, z).setType(fill, false);
                }
                for (int y = surfaceY + 1; y <= clearTop; y++) {
                    Block block = world.getBlockAt(x, y, z);
                    if (block.getType() == Material.BEDROCK) {
                        continue;
                    }
                    block.setType(Material.AIR, false);
                }
                if (columnTop < fillBase) {
                    for (int y = columnTop + 1; y < fillBase; y++) {
                        world.getBlockAt(x, y, z).setType(Material.DIRT, false);
                    }
                }
            }
        }
    }

    private boolean placeAeosTemplate(World world, String templateId, int x, int y, int z) {
        if (world == null || templateId == null || templateId.isBlank()) {
            return false;
        }
        String normalizedId = normalizeStructureId(templateId);
        if (hydraStructureTemplateFiles.containsKey(normalizedId)) {
            return placeHydraStructureDirectly(world, normalizedId, x, y, z);
        }
        String command = "execute in " + commandWorldId(world)
            + " run place template " + normalizedId + " "
            + x + " " + y + " " + z;
        return dispatchPlacementCommandWithSuccess(command);
    }

    private Structure resolveHydraStructure(String normalizedId) {
        if (normalizedId == null || normalizedId.isBlank() || !normalizedId.startsWith(HYDRA_STRUCTURE_NAMESPACE + ":")) {
            return null;
        }
        Structure cached = hydraStructureCache.get(normalizedId);
        if (cached != null) {
            return cached;
        }
        if (missingHydraStructureTemplates.contains(normalizedId)) {
            return null;
        }
        Path templatePath = hydraStructureTemplateFiles.get(normalizedId);
        if (templatePath == null || !Files.isRegularFile(templatePath)) {
            templatePath = findHydraStructureTemplatePath(normalizedId);
            if (templatePath != null && Files.isRegularFile(templatePath)) {
                hydraStructureTemplateFiles.put(normalizedId, templatePath);
            }
        }
        if (templatePath == null || !Files.isRegularFile(templatePath)) {
            missingHydraStructureTemplates.add(normalizedId);
            return null;
        }
        try {
            Structure loaded = Bukkit.getStructureManager().loadStructure(templatePath.toFile());
            hydraStructureCache.put(normalizedId, loaded);
            missingHydraStructureTemplates.remove(normalizedId);
            return loaded;
        } catch (IOException ex) {
            plugin.getLogger().warning("Failed loading Hydra structure " + normalizedId
                + " from " + templatePath + ": " + ex.getMessage());
            hydraStructureTemplateFiles.remove(normalizedId);
            hydraStructureCache.remove(normalizedId);
            return null;
        }
    }

    private Path findHydraStructureTemplatePath(String normalizedId) {
        if (normalizedId == null || normalizedId.isBlank()) {
            return null;
        }
        Path externalDirectorySource = resolveActiveStructureTemplateSource();
        Path zipSource = resolveStructureSourcePath(matchStructureZipFile);
        List<StructureTemplateSource> discovered = new ArrayList<>();
        if (externalDirectorySource != null && Files.isDirectory(externalDirectorySource)) {
            collectStructureTemplateSourcesFromDirectory(externalDirectorySource, discovered);
        } else if (zipSource != null && Files.exists(zipSource)) {
            if (Files.isDirectory(zipSource)) {
                collectStructureTemplateSourcesFromDirectory(zipSource, discovered);
            } else {
                collectStructureTemplateSourcesFromZip(zipSource, discovered);
            }
        }
        for (StructureTemplateSource source : discovered) {
            if (source == null || source.id() == null || source.sourcePath() == null) {
                continue;
            }
            if (!normalizedId.equals(normalizeStructureId(source.id()))) {
                continue;
            }
            if (Files.isRegularFile(source.sourcePath())) {
                return source.sourcePath();
            }
        }
        return null;
    }

    private boolean placeHydraStructureDirectly(World world, String normalizedId, int x, int y, int z) {
        if (world == null || normalizedId == null || normalizedId.isBlank()) {
            return false;
        }
        Structure structure = resolveHydraStructure(normalizedId);
        if (structure == null) {
            return false;
        }
        try {
            long preloadStartedAt = System.currentTimeMillis();
            if (!loadStructurePlacementArea(world, normalizedId, x, z, 1, true)) {
                plugin.getLogger().warning("Failed preloading chunk footprint for " + normalizedId
                    + " at " + x + "," + y + "," + z + " in " + world.getName() + ".");
                return false;
            }
            long preloadElapsed = System.currentTimeMillis() - preloadStartedAt;
            if (preloadElapsed >= 1000L) {
                plugin.getLogger().info("[Queue] Preloaded structure footprint for " + normalizedId
                    + " in " + world.getName() + " in " + preloadElapsed + "ms.");
            }
            structure.place(
                new Location(world, x, y, z),
                true,
                StructureRotation.NONE,
                Mirror.NONE,
                0,
                1.0F,
                ThreadLocalRandom.current()
            );
            return true;
        } catch (Exception ex) {
            plugin.getLogger().warning("Direct Hydra structure placement failed for " + normalizedId
                + " at " + x + "," + y + "," + z + " in " + world.getName() + ": " + ex.getMessage());
            hydraStructureCache.remove(normalizedId);
            return false;
        }
    }

    private void ignitePlacedHungerGamesTnt(Block block, Player player) {
        if (block == null || player == null) {
            return;
        }
        Bukkit.getScheduler().runTask(plugin, () -> {
            if (block.getType() != Material.TNT) {
                return;
            }
            Location spawn = block.getLocation().clone().add(0.5D, 0.0D, 0.5D);
            block.setType(Material.AIR, false);
            TNTPrimed primed = block.getWorld().spawn(spawn, TNTPrimed.class, tnt -> tnt.setFuseTicks(80));
            if (primed != null) {
                primed.setSource(player);
            }
            block.getWorld().playSound(spawn, Sound.ENTITY_TNT_PRIMED, 1.0F, 1.0F);
            block.getWorld().spawnParticle(Particle.SMOKE, spawn.clone().add(0.0D, 0.4D, 0.0D), 10, 0.2D, 0.1D, 0.2D, 0.01D);
        });
    }

    private boolean placeHydraStructurePaletteNoPhysics(World world, String structureId, Structure structure, int x, int y, int z) {
        if (world == null || structure == null) {
            return false;
        }
        List<Palette> palettes = structure.getPalettes();
        if (palettes.isEmpty()) {
            return true;
        }
        List<BlockState> sourceBlocks = palettes.get(0).getBlocks();
        if (sourceBlocks.isEmpty()) {
            return true;
        }

        List<BlockState> airStates = new ArrayList<>();
        List<BlockState> stableStates = new ArrayList<>();
        List<BlockState> gravityStates = new ArrayList<>();
        List<BlockState> tileStates = new ArrayList<>();
        for (BlockState sourceState : sourceBlocks) {
            if (sourceState == null) {
                continue;
            }
            Material type = sourceState.getType();
            if (sourceState instanceof TileState) {
                tileStates.add(sourceState);
            }
            if (type.isAir()) {
                airStates.add(sourceState);
            } else if (type.hasGravity()) {
                gravityStates.add(sourceState);
            } else {
                stableStates.add(sourceState);
            }
        }

        long startedAt = System.currentTimeMillis();
        try {
            applyStructurePaletteStates(world, x, y, z, airStates);
            applyStructurePaletteStates(world, x, y, z, stableStates);
            applyStructurePaletteStates(world, x, y, z, gravityStates);
            applyStructurePaletteTileStates(world, x, y, z, tileStates);
        } catch (Exception ex) {
            plugin.getLogger().warning("Manual Hydra structure placement failed for " + structureId
                + " at " + x + "," + y + "," + z + " in " + world.getName() + ": " + ex.getMessage());
            return false;
        }

        long elapsed = System.currentTimeMillis() - startedAt;
        if (elapsed >= 1000L) {
            plugin.getLogger().info("[Queue] Manually pasted structure " + structureId + " in "
                + world.getName() + " in " + elapsed + "ms (blocks=" + sourceBlocks.size()
                + ", tileStates=" + tileStates.size() + ").");
        }
        return true;
    }

    private CompletableFuture<Boolean> placeHydraStructurePaletteNoPhysicsAsync(
        World world,
        String structureId,
        Structure structure,
        int x,
        int y,
        int z
    ) {
        if (world == null || structure == null) {
            return CompletableFuture.completedFuture(false);
        }
        List<Palette> palettes = structure.getPalettes();
        if (palettes.isEmpty()) {
            return CompletableFuture.completedFuture(true);
        }
        List<BlockState> sourceBlocks = palettes.get(0).getBlocks();
        if (sourceBlocks.isEmpty()) {
            return CompletableFuture.completedFuture(true);
        }

        List<BlockState> blockStates = new ArrayList<>(sourceBlocks.size());
        List<BlockState> tileStates = new ArrayList<>();
        for (BlockState sourceState : sourceBlocks) {
            if (sourceState == null) {
                continue;
            }
            if (sourceState instanceof TileState) {
                tileStates.add(sourceState);
            }
            blockStates.add(sourceState);
        }

        CompletableFuture<Boolean> future = new CompletableFuture<>();
        long startedAt = System.currentTimeMillis();
        final int[] blockIndex = {0};
        final int[] tileIndex = {0};
        final BukkitTask[] taskRef = {null};
        taskRef[0] = Bukkit.getScheduler().runTaskTimer(plugin, () -> {
            try {
                int processedBlocks = 0;
                while (blockIndex[0] < blockStates.size() && processedBlocks < HG_STRUCTURE_PASTE_BLOCKS_PER_TICK) {
                    applyStructurePaletteState(world, x, y, z, blockStates.get(blockIndex[0]++));
                    processedBlocks++;
                }

                if (blockIndex[0] < blockStates.size()) {
                    return;
                }

                int processedTiles = 0;
                while (tileIndex[0] < tileStates.size() && processedTiles < HG_STRUCTURE_PASTE_TILES_PER_TICK) {
                    applyStructurePaletteTileState(world, x, y, z, tileStates.get(tileIndex[0]++));
                    processedTiles++;
                }

                if (tileIndex[0] < tileStates.size()) {
                    return;
                }

                long elapsed = System.currentTimeMillis() - startedAt;
                if (elapsed >= 1000L) {
                    plugin.getLogger().info("[Queue] Batched-pasted structure " + structureId + " in "
                        + world.getName() + " in " + elapsed + "ms (blocks=" + blockStates.size()
                        + ", tileStates=" + tileStates.size() + ").");
                }
                future.complete(true);
                if (taskRef[0] != null) {
                    taskRef[0].cancel();
                }
            } catch (Exception ex) {
                plugin.getLogger().warning("Batched Hydra structure placement failed for " + structureId
                    + " at " + x + "," + y + "," + z + " in " + world.getName() + ": " + ex.getMessage());
                future.complete(false);
                if (taskRef[0] != null) {
                    taskRef[0].cancel();
                }
            }
        }, 1L, 1L);
        return future;
    }

    private void applyStructurePaletteStates(World world, int originX, int originY, int originZ, List<BlockState> sourceStates) {
        if (world == null || sourceStates == null || sourceStates.isEmpty()) {
            return;
        }
        for (BlockState sourceState : sourceStates) {
            applyStructurePaletteState(world, originX, originY, originZ, sourceState);
        }
    }

    private void applyStructurePaletteTileStates(World world, int originX, int originY, int originZ, List<BlockState> tileStates) {
        if (world == null || tileStates == null || tileStates.isEmpty()) {
            return;
        }
        for (BlockState sourceState : tileStates) {
            applyStructurePaletteTileState(world, originX, originY, originZ, sourceState);
        }
    }

    private void applyStructurePaletteState(World world, int originX, int originY, int originZ, BlockState sourceState) {
        if (world == null || sourceState == null) {
            return;
        }
        int targetX = originX + sourceState.getX();
        int targetY = originY + sourceState.getY();
        int targetZ = originZ + sourceState.getZ();
        Block targetBlock = world.getBlockAt(targetX, targetY, targetZ);
        Material targetType = sourceState.getType();
        if (targetType.isAir()) {
            if (!targetBlock.getType().isAir()) {
                targetBlock.setType(Material.AIR, false);
            }
            return;
        }
        BlockData targetData = sourceState.getBlockData();
        targetBlock.setBlockData(targetData, false);
    }

    private void applyStructurePaletteTileState(World world, int originX, int originY, int originZ, BlockState sourceState) {
        if (world == null || sourceState == null) {
            return;
        }
        int targetX = originX + sourceState.getX();
        int targetY = originY + sourceState.getY();
        int targetZ = originZ + sourceState.getZ();
        BlockState copiedState = sourceState.copy(new Location(world, targetX, targetY, targetZ));
        copiedState.update(true, false);
    }

    private boolean loadStructurePlacementArea(
        World world,
        String structureId,
        int blockX,
        int blockZ,
        int paddingChunks,
        boolean generate
    ) {
        if (world == null) {
            return false;
        }
        Structure structure = resolveHydraStructure(normalizeStructureId(structureId));
        if (structure == null) {
            return loadChunkSquare(world, blockX, blockZ, Math.max(0, paddingChunks), generate);
        }
        BlockVector size = structure.getSize();
        int minChunkX = Math.floorDiv(blockX, 16) - Math.max(0, paddingChunks);
        int maxChunkX = Math.floorDiv(blockX + Math.max(0, size.getBlockX() - 1), 16) + Math.max(0, paddingChunks);
        int minChunkZ = Math.floorDiv(blockZ, 16) - Math.max(0, paddingChunks);
        int maxChunkZ = Math.floorDiv(blockZ + Math.max(0, size.getBlockZ() - 1), 16) + Math.max(0, paddingChunks);
        for (int cx = minChunkX; cx <= maxChunkX; cx++) {
            for (int cz = minChunkZ; cz <= maxChunkZ; cz++) {
                if (world.isChunkLoaded(cx, cz)) {
                    continue;
                }
                boolean loaded = world.loadChunk(cx, cz, generate);
                if (!loaded && !world.isChunkLoaded(cx, cz)) {
                    return false;
                }
            }
        }
        return true;
    }

    private int placementChunkRadius(String structureId, StructureRule rule) {
        StructureRule activeRule = rule == null ? structureRuleFor(structureId) : rule;
        int ruleRadius = Math.max(1, ((Math.max(1, activeRule.footprintRadius()) + 6) + 15) / 16);
        Structure structure = resolveHydraStructure(normalizeStructureId(structureId));
        if (structure == null) {
            return ruleRadius;
        }
        BlockVector size = structure.getSize();
        int spanX = Math.max(1, size.getBlockX());
        int spanZ = Math.max(1, size.getBlockZ());
        int structureRadius = Math.max(2, ((Math.max(spanX, spanZ) + 15) / 16) + 2);
        return Math.max(ruleRadius, structureRadius);
    }

    private int structureScanRadius(String structureId, StructureRule rule) {
        StructureRule activeRule = rule == null ? structureRuleFor(structureId) : rule;
        int radius = Math.max(4, activeRule.footprintRadius() + 6);
        Structure structure = resolveHydraStructure(normalizeStructureId(structureId));
        if (structure == null) {
            return radius;
        }
        BlockVector size = structure.getSize();
        int spanX = Math.max(1, size.getBlockX());
        int spanZ = Math.max(1, size.getBlockZ());
        return Math.max(radius, Math.max(spanX, spanZ) + 6);
    }

    private boolean isStructurePlacementAreaLoaded(World world, String structureId, int blockX, int blockZ, int paddingChunks) {
        if (world == null) {
            return false;
        }
        Structure structure = resolveHydraStructure(normalizeStructureId(structureId));
        if (structure == null) {
            return isChunkSquareLoaded(world, blockX, blockZ, Math.max(0, paddingChunks));
        }
        BlockVector size = structure.getSize();
        int minChunkX = Math.floorDiv(blockX, 16) - Math.max(0, paddingChunks);
        int maxChunkX = Math.floorDiv(blockX + Math.max(0, size.getBlockX() - 1), 16) + Math.max(0, paddingChunks);
        int minChunkZ = Math.floorDiv(blockZ, 16) - Math.max(0, paddingChunks);
        int maxChunkZ = Math.floorDiv(blockZ + Math.max(0, size.getBlockZ() - 1), 16) + Math.max(0, paddingChunks);
        for (int cx = minChunkX; cx <= maxChunkX; cx++) {
            for (int cz = minChunkZ; cz <= maxChunkZ; cz++) {
                if (!world.isChunkLoaded(cx, cz)) {
                    return false;
                }
            }
        }
        return true;
    }

    private CompletableFuture<Boolean> ensureStructurePlacementAreaLoadedAsync(
        World world,
        String structureId,
        int blockX,
        int blockZ,
        int paddingChunks,
        boolean generate
    ) {
        if (world == null) {
            return CompletableFuture.completedFuture(false);
        }
        Structure structure = resolveHydraStructure(normalizeStructureId(structureId));
        if (structure == null) {
            return ensureChunkSquareLoadedAsync(world, blockX, blockZ, Math.max(0, paddingChunks), generate);
        }
        BlockVector size = structure.getSize();
        int minChunkX = Math.floorDiv(blockX, 16) - Math.max(0, paddingChunks);
        int maxChunkX = Math.floorDiv(blockX + Math.max(0, size.getBlockX() - 1), 16) + Math.max(0, paddingChunks);
        int minChunkZ = Math.floorDiv(blockZ, 16) - Math.max(0, paddingChunks);
        int maxChunkZ = Math.floorDiv(blockZ + Math.max(0, size.getBlockZ() - 1), 16) + Math.max(0, paddingChunks);
        List<CompletableFuture<Chunk>> futures = new ArrayList<>();
        for (int cx = minChunkX; cx <= maxChunkX; cx++) {
            for (int cz = minChunkZ; cz <= maxChunkZ; cz++) {
                if (world.isChunkLoaded(cx, cz)) {
                    continue;
                }
                futures.add(world.getChunkAtAsync(cx, cz, generate, true));
            }
        }
        if (futures.isEmpty()) {
            return CompletableFuture.completedFuture(true);
        }
        return CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new))
            .handle((ignored, error) -> error == null
                && isStructurePlacementAreaLoaded(world, structureId, blockX, blockZ, paddingChunks));
    }

    private CompletableFuture<Boolean> preloadStructureFootprintAsync(
        World world,
        Structure structure,
        int blockX,
        int blockZ,
        int paddingChunks,
        boolean generate
    ) {
        if (world == null || structure == null) {
            return CompletableFuture.completedFuture(false);
        }
        BlockVector size = structure.getSize();
        int minChunkX = Math.floorDiv(blockX, 16) - Math.max(0, paddingChunks);
        int maxChunkX = Math.floorDiv(blockX + Math.max(0, size.getBlockX() - 1), 16) + Math.max(0, paddingChunks);
        int minChunkZ = Math.floorDiv(blockZ, 16) - Math.max(0, paddingChunks);
        int maxChunkZ = Math.floorDiv(blockZ + Math.max(0, size.getBlockZ() - 1), 16) + Math.max(0, paddingChunks);
        List<CompletableFuture<Chunk>> futures = new ArrayList<>();
        for (int cx = minChunkX; cx <= maxChunkX; cx++) {
            for (int cz = minChunkZ; cz <= maxChunkZ; cz++) {
                if (world.isChunkLoaded(cx, cz)) {
                    continue;
                }
                futures.add(world.getChunkAtAsync(cx, cz, generate, true));
            }
        }
        if (futures.isEmpty()) {
            return CompletableFuture.completedFuture(true);
        }
        return CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new))
            .handle((ignored, error) -> error == null);
    }

    @EventHandler(ignoreCancelled = true)
    public void onUnderworldCreatureSpawn(CreatureSpawnEvent event) {
        if (!(event.getEntity() instanceof Monster monster)) {
            return;
        }
        if (!isHydraBrWorld(monster.getWorld())) {
            return;
        }
        if (isInsideCornucopiaProtectedZone(monster.getLocation())) {
            event.setCancelled(true);
            return;
        }
        if (isHellscapeWorld(monster.getWorld())) {
            return;
        }
        if (monster.getLocation().getBlockY() > hydraUnderworldCeilingY(monster.getWorld().getMinHeight(), monster.getWorld().getMaxHeight() - 1)) {
            return;
        }
        switch (event.getSpawnReason()) {
            case NATURAL, CHUNK_GEN, REINFORCEMENTS -> tuneUnderworldMonster(monster);
            default -> {
            }
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onHellscapePatrolSpawn(CreatureSpawnEvent event) {
        if (!(event.getEntity() instanceof Piglin seedMember)) {
            return;
        }
        if (seedMember.getPersistentDataContainer().has(hellscapePatrolKey, PersistentDataType.STRING)) {
            return;
        }
        if (!isHellscapeWorld(seedMember.getWorld())) {
            return;
        }
        if (isInsideCornucopiaProtectedZone(seedMember.getLocation())) {
            event.setCancelled(true);
            return;
        }
        switch (event.getSpawnReason()) {
            case NATURAL, CHUNK_GEN -> {
            }
            default -> {
                return;
            }
        }

        Location location = seedMember.getLocation();
        if (!isHellscapePatrolOriginSafe(location)) {
            return;
        }
        HellscapeRegion region = resolveHellscapeRegion(
            seedMember.getWorld(),
            location.getBlockX(),
            location.getBlockY(),
            location.getBlockZ()
        );
        if (region != HellscapeRegion.NETHER_WASTES && region != HellscapeRegion.NETHER_WASTES_DEEP) {
            return;
        }

        String patrolCell = hellscapePatrolCellKey(seedMember.getWorld(), location.getBlockX(), location.getBlockZ());
        long now = System.currentTimeMillis();
        if (hellscapePatrolCooldownUntilMs.getOrDefault(patrolCell, 0L) > now) {
            return;
        }
        double triggerChance = region == HellscapeRegion.NETHER_WASTES_DEEP
            ? HELLSCAPE_PATROL_TRIGGER_CHANCE + 0.05D
            : HELLSCAPE_PATROL_TRIGGER_CHANCE;
        if (ThreadLocalRandom.current().nextDouble() > triggerChance) {
            return;
        }

        hellscapePatrolCooldownUntilMs.put(patrolCell, now + HELLSCAPE_PATROL_CELL_COOLDOWN_MS);
        String groupId = UUID.randomUUID().toString();
        markHellscapePatrolEntity(seedMember, groupId, "member");
        tuneHellscapePatrolMember(seedMember);
        expandHellscapePiglinPatrol(seedMember, groupId);
    }

    @EventHandler(ignoreCancelled = true)
    public void onHellscapePatrolFriendlyFire(EntityDamageByEntityEvent event) {
        String victimGroup = hellscapePatrolGroupId(event.getEntity());
        if (victimGroup == null) {
            return;
        }
        Entity attacker = hellscapePatrolAttacker(event.getDamager());
        if (attacker == null) {
            return;
        }
        String attackerGroup = hellscapePatrolGroupId(attacker);
        if (victimGroup.equals(attackerGroup)) {
            event.setCancelled(true);
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onAeosCreatureSpawn(CreatureSpawnEvent event) {
        if (!isAeosWorld(event.getLocation().getWorld())) {
            return;
        }
        if (isInsideCornucopiaProtectedZone(event.getLocation())) {
            event.setCancelled(true);
            return;
        }
        switch (event.getSpawnReason()) {
            case CUSTOM, COMMAND, SPAWNER_EGG, DISPENSE_EGG -> {
                return;
            }
            default -> event.setCancelled(true);
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onHungerGamesCreatureSpawn(CreatureSpawnEvent event) {
        if (!hungerGamesDisableMobSpawns) {
            return;
        }
        if (!isHungerGamesMatchWorld(event.getLocation().getWorld())) {
            return;
        }
        if (allowHungerGamesControlledSpawn(event.getSpawnReason())) {
            return;
        }
        event.setCancelled(true);
    }

    private boolean allowHungerGamesControlledSpawn(CreatureSpawnEvent.SpawnReason reason) {
        if (reason == null) {
            return false;
        }
        return switch (reason) {
            case CUSTOM, COMMAND, SPAWNER, TRIAL_SPAWNER, SPAWNER_EGG, DISPENSE_EGG -> true;
            default -> false;
        };
    }

    @EventHandler
    public void onSpectatorDamage(EntityDamageEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        if (isFakePcsControlled(player)) {
            event.setCancelled(true);
            return;
        }
        if (isHungerGamesStartFrozen(player)) {
            event.setCancelled(true);
            return;
        }
        if (!isCustomSpectator(player)) {
            return;
        }
        event.setCancelled(true);
    }

    @EventHandler
    public void onSpectatorDamageByEntity(EntityDamageByEntityEvent event) {
        if (event.getEntity() instanceof Player victim) {
            if (isFakePcsControlled(victim)) {
                event.setCancelled(true);
                logPvpCancel(event, null, victim, "victim_fake_pcs");
                return;
            }
            if (isHungerGamesStartFrozen(victim)) {
                event.setCancelled(true);
                logPvpCancel(event, null, victim, "victim_start_frozen");
                return;
            }
            if (isCustomSpectator(victim)) {
                event.setCancelled(true);
                logPvpCancel(event, null, victim, "victim_custom_spectator");
                return;
            }
        }

        Player attacker = null;
        if (event.getDamager() instanceof Player direct) {
            attacker = direct;
        } else if (event.getDamager() instanceof Projectile projectile && projectile.getShooter() instanceof Player shooter) {
            attacker = shooter;
        }
        if (attacker != null && isCustomSpectator(attacker)) {
            event.setCancelled(true);
            logPvpCancel(event, attacker, event.getEntity() instanceof Player victim ? victim : null, "attacker_custom_spectator");
            return;
        }
        if (attacker != null && isFakePcsControlled(attacker)) {
            event.setCancelled(true);
            logPvpCancel(event, attacker, event.getEntity() instanceof Player victim ? victim : null, "attacker_fake_pcs");
            return;
        }
        if (attacker != null && isHungerGamesStartFrozen(attacker)) {
            event.setCancelled(true);
            logPvpCancel(event, attacker, event.getEntity() instanceof Player victim ? victim : null, "attacker_start_frozen");
            return;
        }
        if (attacker != null
            && event.getEntity() instanceof Player victim
            && (isHungerGamesCombatGraceActive(attacker) || isHungerGamesCombatGraceActive(victim))) {
            event.setCancelled(true);
            logPvpCancel(
                event,
                attacker,
                victim,
                isHungerGamesCombatGraceActive(attacker) ? "attacker_combat_grace" : "victim_combat_grace"
            );
        }
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onLegendaryDamageTrack(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof Player victim)) {
            return;
        }
        Player attacker = resolveAttackingPlayer(event.getDamager());
        if (attacker == null) {
            pendingLegendaryKillContexts.remove(victim.getUniqueId());
            return;
        }
        LegendaryKillContext context = resolveLegendaryKillContext(attacker);
        if (context == null) {
            pendingLegendaryKillContexts.remove(victim.getUniqueId());
            return;
        }
        pendingLegendaryKillContexts.put(victim.getUniqueId(), context);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onDeathRecapTrack(EntityDamageEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        double hearts = Math.max(0.0D, event.getFinalDamage() / 2.0D);
        if (hearts <= 0.0D) {
            return;
        }
        lastDamageTakenHearts.put(player.getUniqueId(), hearts);
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onLifetimeDamageTrack(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof Player victim)) {
            return;
        }
        Player attacker = resolveAttackingPlayer(event.getDamager());
        if (attacker == null || attacker.getUniqueId().equals(victim.getUniqueId())) {
            return;
        }
        UUID attackerId = attacker.getUniqueId();
        if (!inMatchPlayers.contains(attackerId)) {
            return;
        }
        String attackerWorld = inMatchWorlds.get(attackerId);
        String victimWorld = inMatchWorlds.get(victim.getUniqueId());
        if (attackerWorld == null || victimWorld == null || !isSameMatchSessionWorld(attackerWorld, victimWorld)) {
            return;
        }
        if (isBrDevelopmentTestWorld(attackerWorld)) {
            return;
        }
        if (sameActiveDuoTeam(attackerId, victim.getUniqueId())) {
            return;
        }
        QueueType matchType = inMatchTypes.get(attackerId);
        if (matchType == null) {
            matchType = resolveQueueTypeForWorld(attackerWorld);
        }
        double dealt = Math.max(0.0D, event.getFinalDamage());
        if (dealt <= 0.0D) {
            return;
        }
        recordLifetimeDamage(attackerId, matchType, dealt);
    }

    static ItemStack hungerGamesUtilityCraftResult(ItemStack proposed, String utilityId) {
        if (proposed == null || proposed.getType() == Material.AIR) return null;
        ItemStack result = proposed.clone();
        int amount = switch (utilityId) {
            case "fletchers_pack" -> ThreadLocalRandom.current().nextInt(8, 13);
            case "wind_pack" -> ThreadLocalRandom.current().nextInt(4, 9);
            case "web_bundle" -> ThreadLocalRandom.current().nextInt(4, 7);
            default -> result.getAmount();
        };
        return switch (utilityId) {
            case "fletchers_pack" -> new ItemStack(Material.ARROW, amount);
            case "wind_pack" -> new ItemStack(Material.WIND_CHARGE, amount);
            case "web_bundle" -> new ItemStack(Material.COBWEB, amount);
            default -> result;
        };
    }

    private String hungerGamesUtilityRecipeId(org.bukkit.inventory.Recipe recipe, ItemStack proposed) {
        String itemId = HungerGamesUtilityItems.utilityId(proposed);
        String recipeId = RecipeRuntimeRegistrar.catalogIdFor(plugin, recipe);
        if (recipeId != null && (itemId != null || HUNGER_GAMES_CRAFT_LIMITS.containsKey(recipeId))) return recipeId;
        return itemId;
    }

    private void recordHungerGamesUtilityCraft(Player player, String utilityId) {
        hungerGamesUtilityCrafts.computeIfAbsent(player.getUniqueId(), ignored -> new HashMap<>())
            .merge(utilityId, 1, Integer::sum);
    }

    private boolean canAcceptInventoryItem(Player player, ItemStack result) {
        int remaining = result.getAmount();
        for (ItemStack stored : player.getInventory().getStorageContents()) {
            if (stored == null || stored.getType() == Material.AIR) return true;
            if (stored.isSimilar(result)) remaining -= Math.max(0, stored.getMaxStackSize() - stored.getAmount());
            if (remaining <= 0) return true;
        }
        return false;
    }

    private void consumeSingleCraft(CraftingInventory inventory) {
        ItemStack[] matrix = inventory.getMatrix();
        for (int index = 0; index < matrix.length; index++) {
            ItemStack ingredient = matrix[index];
            if (ingredient == null || ingredient.getType() == Material.AIR) continue;
            if (ingredient.getAmount() > 1) {
                ingredient.setAmount(ingredient.getAmount() - 1);
                continue;
            }
            matrix[index] = ingredient.getType() == Material.WATER_BUCKET
                ? new ItemStack(Material.BUCKET)
                : null;
        }
        inventory.setMatrix(matrix);
    }

    public boolean isActiveHungerGamesPlayer(Player player) {
        return isHungerGamesActivePlayer(player);
    }

    public boolean isAliveHungerGamesParticipant(UUID playerId) {
        return playerId != null && inMatchPlayers.contains(playerId)
            && isHungerGames(inMatchTypes.get(playerId)) && !spectatingMatchWorlds.containsKey(playerId);
    }

    public boolean isHungerGamesStartFrozen(UUID playerId) {
        Long until = playerId == null ? null : hungerGamesStartFreezeUntilMs.get(playerId);
        return until != null && until > System.currentTimeMillis();
    }

    public List<Player> activeHungerGamesEnemies(Player player) {
        if (!isHungerGamesActivePlayer(player)) return List.of();
        List<Player> enemies = new ArrayList<>();
        for (Player candidate : player.getWorld().getPlayers()) {
            if (!candidate.equals(player) && isHungerGamesActivePlayer(candidate)
                && !isProtectedMatchTeammate(player.getUniqueId(), candidate.getUniqueId())) enemies.add(candidate);
        }
        return List.copyOf(enemies);
    }

    public boolean isHungerGamesDuoParticipant(UUID playerId) {
        return hungerGamesDuoTeamId(playerId) != null;
    }

    public boolean areHungerGamesDuoTeammates(UUID viewerId, UUID targetId) {
        if (viewerId == null || targetId == null || viewerId.equals(targetId)) return false;
        String viewerWorld = hungerGamesDuoWorld(viewerId);
        String targetWorld = hungerGamesDuoWorld(targetId);
        UUID viewerTeam = hungerGamesDuoTeamId(viewerId);
        UUID targetTeam = hungerGamesDuoTeamId(targetId);
        return viewerWorld != null && viewerWorld.equals(targetWorld)
            && viewerTeam != null && viewerTeam.equals(targetTeam);
    }

    public Integer hungerGamesDuoTeamColorRgb(UUID playerId) {
        String worldName = hungerGamesDuoWorld(playerId);
        UUID teamId = hungerGamesDuoTeamId(playerId);
        if (worldName == null || teamId == null) return null;
        return hungerGamesDuoTeamColors.getOrDefault(worldName, Map.of()).get(teamId);
    }

    public Integer hungerGamesDuoTeamTabIndex(UUID playerId) {
        String worldName = hungerGamesDuoWorld(playerId);
        UUID teamId = hungerGamesDuoTeamId(playerId);
        if (worldName == null || teamId == null) return null;
        // The match roster retains insertion order and eliminated teammates until cleanup.
        int index = 0;
        for (UUID rosterTeam : hungerGamesDuoRosters.getOrDefault(worldName, Map.of()).keySet()) {
            if (rosterTeam.equals(teamId)) return index;
            index++;
        }
        return null;
    }

    private UUID hungerGamesDuoTeamId(UUID playerId) {
        String worldName = hungerGamesDuoWorld(playerId);
        if (worldName == null) return null;
        UUID activeTeam = duoTeamByPlayer.get(playerId);
        if (activeTeam != null) return activeTeam;
        for (Map.Entry<UUID, Set<UUID>> entry
            : hungerGamesDuoRosters.getOrDefault(worldName, Map.of()).entrySet()) {
            if (entry.getValue().contains(playerId)) return entry.getKey();
        }
        return null;
    }

    private void refreshHungerGamesDuoGlows() {
        Set<DuoGlowPair> desired = new HashSet<>();
        for (Player viewer : Bukkit.getOnlinePlayers()) {
            UUID viewerId = viewer.getUniqueId();
            if (!isAliveHungerGamesParticipant(viewerId) || !isHungerGamesDuoParticipant(viewerId)) continue;
            for (Player target : viewer.getWorld().getPlayers()) {
                UUID targetId = target.getUniqueId();
                if (!isAliveHungerGamesParticipant(targetId)
                    || !areHungerGamesDuoTeammates(viewerId, targetId)
                    || !shouldShowHungerGamesDuoGlow(viewer.getLocation().distanceSquared(target.getLocation()))) {
                    continue;
                }
                if (plugin instanceof HGLootPlugin hydra && hydra.playerSettingsService() != null
                    && !hydra.playerSettingsService().enabled(viewerId, PlayerSettingsService.Toggle.TEAM_GLOW)) continue;
                DuoGlowPair pair = new DuoGlowPair(viewerId, targetId);
                desired.add(pair);
                hungerGamesDuoGlowService.setGlowing(viewer, target, true);
            }
        }
        for (DuoGlowPair previous : new HashSet<>(activeHungerGamesDuoGlows)) {
            if (desired.contains(previous)) continue;
            resetHungerGamesDuoGlow(previous);
        }
        activeHungerGamesDuoGlows.clear();
        activeHungerGamesDuoGlows.addAll(desired);
    }

    public void refreshTeamGlowPreference() {
        refreshHungerGamesDuoGlows();
    }

    static boolean shouldShowHungerGamesDuoGlow(double distanceSquared) {
        return distanceSquared >= HUNGER_GAMES_DUO_GLOW_DISTANCE_SQUARED;
    }

    private void clearHungerGamesDuoGlows() {
        for (DuoGlowPair pair : new HashSet<>(activeHungerGamesDuoGlows)) {
            resetHungerGamesDuoGlow(pair);
        }
        activeHungerGamesDuoGlows.clear();
    }

    private void resetHungerGamesDuoGlow(DuoGlowPair pair) {
        Player viewer = Bukkit.getPlayer(pair.viewerId());
        Player target = Bukkit.getPlayer(pair.targetId());
        if (viewer != null && target != null) {
            hungerGamesDuoGlowService.setGlowing(viewer, target, target.isGlowing());
        }
    }

    private String hungerGamesDuoWorld(UUID playerId) {
        if (playerId == null) return null;
        String worldName = inMatchWorlds.get(playerId);
        if (worldName == null) worldName = spectatingMatchWorlds.get(playerId);
        if (worldName == null) return null;
        String root = rootMatchWorldName(worldName);
        return hungerGamesDuoWorlds.contains(root) ? root : null;
    }

    public void resyncSpectatorVisibility(World world) {
        if (world != null) syncSpectatorVisibility(rootMatchWorldName(world.getName()));
    }

    public boolean isHungerGamesCraftLimitReached(Player player, String recipeId) {
        if (player == null || recipeId == null) return false;
        Integer limit = HUNGER_GAMES_CRAFT_LIMITS.get(recipeId);
        return limit != null && hungerGamesUtilityCrafts.getOrDefault(player.getUniqueId(), Map.of())
            .getOrDefault(recipeId, 0) >= limit;
    }

    private ItemStack hungerGamesCraftLimitItem() {
        ItemStack item = new ItemStack(Material.PAPER);
        ItemMeta meta = item.getItemMeta();
        if (meta == null) return item;
        meta.displayName(Component.text("Craft Limit Reached", net.kyori.adventure.text.format.NamedTextColor.RED));
        meta.lore(List.of(Component.text("You have reached the maximum crafts for this item this match.",
            net.kyori.adventure.text.format.NamedTextColor.GRAY)));
        meta.setItemModel(new NamespacedKey("hydra", "gui/craft_limit"));
        meta.getPersistentDataContainer().set(HungerGamesUtilityItems.UTILITY_ID, PersistentDataType.STRING, "craft_limit_reached");
        item.setItemMeta(meta);
        return item;
    }

    private boolean isHungerGamesCraftLimitItem(ItemStack item) {
        return "craft_limit_reached".equals(HungerGamesUtilityItems.utilityId(item));
    }

    private boolean sameActiveDuoTeam(UUID firstPlayerId, UUID secondPlayerId) {
        if (firstPlayerId == null || secondPlayerId == null) {
            return false;
        }
        UUID firstTeam = duoTeamByPlayer.get(firstPlayerId);
        UUID secondTeam = duoTeamByPlayer.get(secondPlayerId);
        return firstTeam != null && firstTeam.equals(secondTeam);
    }

    private Player resolveAttackingPlayer(Entity damager) {
        if (damager instanceof Player direct) {
            return direct;
        }
        if (damager instanceof Projectile projectile && projectile.getShooter() instanceof Player shooter) {
            return shooter;
        }
        return null;
    }

    private void logPvpCancel(EntityDamageByEntityEvent event, Player attacker, Player victim, String reason) {
        if (event == null || reason == null || reason.isBlank()) {
            return;
        }
        String attackerName = attacker != null ? attacker.getName() : describeAttacker(event.getDamager());
        String victimName = victim != null ? victim.getName() : describeVictim(event.getEntity());
        String worldName = event.getEntity() != null && event.getEntity().getWorld() != null
            ? event.getEntity().getWorld().getName()
            : "unknown";
        plugin.getLogger().info("[PvP] Cancelled damage: reason=" + reason
            + ", attacker=" + attackerName
            + ", victim=" + victimName
            + ", world=" + worldName);
    }

    private String describeAttacker(Entity damager) {
        if (damager == null) {
            return "unknown";
        }
        if (damager instanceof Player player) {
            return player.getName();
        }
        if (damager instanceof Projectile projectile && projectile.getShooter() instanceof Player shooter) {
            return shooter.getName() + " via " + projectile.getType().name();
        }
        return damager.getType().name();
    }

    private String describeVictim(Entity entity) {
        if (entity == null) {
            return "unknown";
        }
        if (entity instanceof Player player) {
            return player.getName();
        }
        return entity.getType().name();
    }

    @EventHandler
    public void onSpectatorFoodChange(FoodLevelChangeEvent event) {
        if (!(event.getEntity() instanceof Player player)) {
            return;
        }
        if (!isCustomSpectator(player)) {
            return;
        }
        event.setCancelled(true);
        player.setFoodLevel(20);
        player.setSaturation(20.0f);
    }

    private boolean isCustomSpectator(Player player) {
        if (player == null) {
            return false;
        }
        return spectatingMatchWorlds.containsKey(player.getUniqueId());
    }

    private void setCustomSpectatorState(Player player, String worldName, boolean announce) {
        UUID playerId = player.getUniqueId();
        QueueType type = resolveQueueTypeForWorld(worldName);
        if (isHungerGames(type)) {
            restoreStandardPlayerHealth(player);
        }
        spectatingMatchWorlds.put(playerId, worldName);

        player.setGameMode(GameMode.ADVENTURE);
        player.setAllowFlight(true);
        player.setFlying(true);
        player.setFlySpeed(0.08f);
        player.setCanPickupItems(false);
        player.setInvulnerable(true);
        player.setCollidable(false);
        player.setFallDistance(0.0f);
        player.setFoodLevel(20);
        player.setSaturation(20.0f);
        player.addPotionEffect(new PotionEffect(PotionEffectType.INVISIBILITY, Integer.MAX_VALUE, 0, true, false, false));
        if (plugin instanceof HGLootPlugin hydra && hydra.playerSettingsService() != null) {
            hydra.playerSettingsService().applyHydraNightVision(player);
        }

        player.getInventory().clear();
        player.getInventory().setArmorContents(new ItemStack[] {null, null, null, null});
        player.getInventory().setItemInOffHand(null);
        player.getInventory().setItem(0, createSpectatorTeleportCompass());
        if (isHungerGames(type)) {
            player.getInventory().setItem(7, createSpectatorRequeueItem());
        }
        player.getInventory().setItem(8, createSpectatorHubPaper());
        player.updateInventory();

        if (isBattleRoyaleType(type)) {
            BattleRoyalePlayerSnapshot snapshot = captureBattleRoyaleSnapshot(player, type, worldName, true);
            if (snapshot != null) {
                brRejoinSnapshots.put(playerId, snapshot);
            }
        }
        syncSpectatorVisibility(worldName);
        if (announce) {
            player.sendMessage(ChatColor.GRAY + "Now spectating.");
        }
        refreshSidebar(player);
    }

    private void clearCustomSpectatorState(Player player) {
        if (player == null) {
            return;
        }
        player.removePotionEffect(PotionEffectType.INVISIBILITY);
        if (plugin instanceof HGLootPlugin hydra && hydra.playerSettingsService() != null) {
            hydra.playerSettingsService().clearHydraNightVision(player);
        }
        player.setInvulnerable(false);
        player.setCollidable(true);
        player.setCanPickupItems(true);
        player.setFlySpeed(0.1f);
        if (!player.isOp()) {
            player.setFlying(false);
            player.setAllowFlight(false);
        }
        restorePlayerVisibility(player);
    }

    private void restorePlayerVisibility(Player target) {
        for (Player viewer : Bukkit.getOnlinePlayers()) {
            viewer.showPlayer(plugin, target);
            target.showPlayer(plugin, viewer);
        }
    }

    private void syncSpectatorVisibility(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return;
        }
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            return;
        }

        List<Player> alivePlayers = new ArrayList<>();
        List<Player> spectators = new ArrayList<>();
        for (Player player : world.getPlayers()) {
            UUID id = player.getUniqueId();
            if (worldName.equals(spectatingMatchWorlds.get(id))) {
                spectators.add(player);
                continue;
            }
            if (inMatchPlayers.contains(id) && worldName.equals(inMatchWorlds.get(id))) {
                alivePlayers.add(player);
            }
        }

        for (Player alive : alivePlayers) {
            for (Player otherAlive : alivePlayers) {
                alive.showPlayer(plugin, otherAlive);
            }
            for (Player spectator : spectators) {
                alive.hidePlayer(plugin, spectator);
                spectator.showPlayer(plugin, alive);
            }
        }

        for (Player spectator : spectators) {
            for (Player otherSpectator : spectators) {
                if (plugin instanceof HGLootPlugin hydra && hydra.playerSettingsService() != null) {
                    hydra.playerSettingsService().syncSpectatorPair(spectator, otherSpectator);
                } else {
                    spectator.showPlayer(plugin, otherSpectator);
                }
            }
        }
    }

    private String readSpectatorAction(ItemStack stack) {
        if (stack == null || !stack.hasItemMeta()) {
            return null;
        }
        return stack.getItemMeta().getPersistentDataContainer().get(spectatorItemKey, PersistentDataType.STRING);
    }

    private ItemStack createSpectatorItem(Material material, String name, String action) {
        return createSpectatorItem(material, name, action, null);
    }

    private ItemStack createSpectatorItem(Material material, String name, String action, String model) {
        ItemStack stack = new ItemStack(material);
        ItemMeta meta = stack.getItemMeta();
        if (meta == null) {
            return stack;
        }
        meta.setDisplayName(name);
        meta.getPersistentDataContainer().set(spectatorItemKey, PersistentDataType.STRING, action);
        if (model != null) {
            meta.setItemModel(NamespacedKey.fromString(model));
        }
        stack.setItemMeta(meta);
        return stack;
    }

    private ItemStack createSpectatorTeleportCompass() {
        return createSpectatorItem(Material.COMPASS, ChatColor.AQUA + "Teleport Compass", SPECTATOR_ACTION_TELEPORT_COMPASS);
    }

    private ItemStack createSpectatorHubPaper() {
        return createSpectatorItem(Material.PAPER, ChatColor.RED + "Return to Lobby", SPECTATOR_ACTION_HUB_PAPER,
            "hydra:backspace");
    }

    private ItemStack createSpectatorRequeueItem() {
        return createSpectatorItem(Material.PAPER, ChatColor.GREEN + "Requeue Hunger Games",
            SPECTATOR_ACTION_HG_REQUEUE, "hydra:requeue");
    }

    private boolean isSpectatorTeleportMenu(InventoryClickEvent event) {
        return isSpectatorTeleportMenu(event.getView().getTitle());
    }

    private boolean isSpectatorTeleportMenu(String title) {
        return SPECTATOR_MENU_TITLE.equals(title);
    }

    private void openSpectatorTeleportMenu(Player spectator) {
        String worldName = spectatingMatchWorlds.get(spectator.getUniqueId());
        if (worldName == null) {
            spectator.sendMessage(ChatColor.RED + "Not spectating.");
            return;
        }
        Inventory inv = Bukkit.createInventory(null, 54, SPECTATOR_MENU_TITLE);
        List<UUID> alive = activePlayersInWorld(worldName);
        int slot = 0;
        for (UUID targetId : alive) {
            Player target = Bukkit.getPlayer(targetId);
            if (target == null || !target.isOnline()) {
                continue;
            }
            if (slot >= 45) {
                break;
            }
            ItemStack head = new ItemStack(Material.PLAYER_HEAD);
            SkullMeta meta = (SkullMeta) head.getItemMeta();
            if (meta == null) {
                continue;
            }
            meta.setOwningPlayer(target);
            meta.setDisplayName(ChatColor.GREEN + target.getName());
            meta.getPersistentDataContainer().set(
                spectatorItemKey,
                PersistentDataType.STRING,
                SPECTATOR_ACTION_TARGET_PREFIX + targetId
            );
            head.setItemMeta(meta);
            inv.setItem(slot, head);
            slot++;
        }

        inv.setItem(49, createSpectatorItem(Material.BARRIER, ChatColor.RED + "Close", SPECTATOR_ACTION_CLOSE));
        spectator.openInventory(inv);
    }

    private void tickQueues() {
        tickBrWorldPreparations();
        for (QueueType type : QueueType.values()) {
            pruneOfflinePlayers(type);
            int queuedCount = queueSize(type);
            CountdownState countdown = countdowns.get(type);
            int minPlayersForType = minPlayersToStartFor(type);

            if (isHungerGames(type)) {
                if (queuedCount > 0) {
                    maybePrewarmMatchWorld(type);
                } else {
                    if (type == QueueType.HUNGERGAMES || localHungerGamesQueuesAvailable()) {
                        maybeKeepHungerGamesReadyArena(type);
                    }
                }
            }

            if (matchStartInProgress.contains(type)) {
                continue;
            }

            if (brDevelopmentTestQueues.contains(type)) {
                continue;
            }

            if (countdown == null) {
                if (queuedCount >= minPlayersForType) {
                    startCountdown(type);
                }
                continue;
            }

            if (queuedCount < minPlayersForType) {
                cancelCountdown(type, "Not enough players. Countdown cancelled.");
                continue;
            }

            countdown.secondsRemaining--;
            if (isHungerGames(type) && shouldAnnounce(countdown.secondsRemaining)) {
                notifyQueue(type, ChatColor.YELLOW + "Match starts in " + countdown.secondsRemaining + "s.");
            }
            if (shouldAnnounceTitle(countdown.secondsRemaining)) {
                notifyQueueTitle(
                    type,
                    ChatColor.GOLD + "" + ChatColor.BOLD + "Game starting in " + countdown.secondsRemaining,
                    ChatColor.GRAY + queueAudienceLabel(type)
                );
            }

            if (countdown.secondsRemaining <= 0) {
                countdowns.remove(type);
                matchStartInProgress.add(type);
                if (usesQueueStartPopups(type)) {
                    sendQueueGoPopup(type);
                }
                startMatch(type, false, null);
            }
        }
        sweepPrewarmedWorlds();
        sweepDetachedHungerGamesPrewarms();
        tickCornucopiaAntiCamp();
        tickMatchBorders();
        tickHellscapeNetherWorlds();
        tickValousWorlds();
        updateAllSidebars();
    }

    private void tickCornucopiaAntiCamp() {
        long now = System.currentTimeMillis();
        Set<UUID> activeBrPlayers = new HashSet<>();
        for (UUID playerId : new ArrayList<>(inMatchPlayers)) {
            QueueType type = inMatchTypes.get(playerId);
            if (!isBattleRoyaleType(type)) {
                clearCornucopiaCampState(playerId);
                continue;
            }
            String worldName = inMatchWorlds.get(playerId);
            String rootWorldName = rootMatchWorldName(worldName);
            if (rootWorldName == null || rootWorldName.isBlank()) {
                clearCornucopiaCampState(playerId);
                continue;
            }
            long antiCampStartAt = matchStartedAtMs.getOrDefault(rootWorldName, now)
                + (BR_CORNUCOPIA_CAMP_START_DELAY_SECONDS * 1000L);
            if (now < antiCampStartAt) {
                clearCornucopiaCampState(playerId);
                continue;
            }
            Player player = Bukkit.getPlayer(playerId);
            if (player == null || !player.isOnline() || isCustomSpectator(player)) {
                clearCornucopiaCampState(playerId);
                continue;
            }
            if (!isSameMatchSessionWorld(rootWorldName, player.getWorld().getName())
                || !isInsideCornucopiaInnerZone(player.getLocation())) {
                clearCornucopiaCampState(playerId);
                continue;
            }

            activeBrPlayers.add(playerId);
            long enteredAt = cornucopiaCampEnteredAtMs.computeIfAbsent(playerId, ignored -> now);
            long elapsedSeconds = Math.max(0L, (now - enteredAt) / 1000L);
            if (elapsedSeconds >= BR_CORNUCOPIA_CAMP_WARNING_SECONDS && cornucopiaCampWarned.add(playerId)) {
                player.sendMessage(ChatColor.YELLOW + "Move out of the Cornucopia. Pressure is building here.");
            }
            if (elapsedSeconds >= BR_CORNUCOPIA_CAMP_PRESSURE_SECONDS) {
                applyCornucopiaCampPressure(player, now);
            }
        }

        for (UUID playerId : new ArrayList<>(cornucopiaCampEnteredAtMs.keySet())) {
            if (!activeBrPlayers.contains(playerId)) {
                clearCornucopiaCampState(playerId);
            }
        }
    }

    private boolean isInsideCornucopiaInnerZone(Location location) {
        if (location == null || location.getWorld() == null || !isHydraBrWorld(location.getWorld())) {
            return false;
        }
        return distanceToCornucopiaAnchor(location.getX(), location.getZ()) <= BR_CORNUCOPIA_INNER_CAMP_RADIUS;
    }

    private void applyCornucopiaCampPressure(Player player, long now) {
        if (player == null || !player.isOnline()) {
            return;
        }
        UUID playerId = player.getUniqueId();
        player.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS, 60, 0, false, true, true));
        player.addPotionEffect(new PotionEffect(PotionEffectType.WEAKNESS, 60, 0, false, true, true));
        player.sendActionBar(Component.text("Cornucopia pressure is forcing you out."));
        long nextPulseAt = cornucopiaCampNextPressureAtMs.getOrDefault(playerId, 0L);
        if (now < nextPulseAt) {
            return;
        }
        player.damage(BR_CORNUCOPIA_CAMP_PRESSURE_DAMAGE);
        cornucopiaCampNextPressureAtMs.put(playerId, now + (BR_CORNUCOPIA_CAMP_PRESSURE_PULSE_SECONDS * 1000L));
    }

    private void clearCornucopiaCampState(UUID playerId) {
        if (playerId == null) {
            return;
        }
        cornucopiaCampEnteredAtMs.remove(playerId);
        cornucopiaCampWarned.remove(playerId);
        cornucopiaCampNextPressureAtMs.remove(playerId);
    }

    private void clearCornucopiaCampStateForWorld(String worldName) {
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null || rootWorldName.isBlank()) {
            return;
        }
        for (Map.Entry<UUID, String> entry : new ArrayList<>(inMatchWorlds.entrySet())) {
            if (isSameMatchSessionWorld(rootWorldName, entry.getValue())) {
                clearCornucopiaCampState(entry.getKey());
            }
        }
    }

    private void startCountdown(QueueType type) {
        int seconds = countdownSecondsFor(type);
        countdowns.put(type, new CountdownState(seconds));
        notifyQueue(type, ChatColor.GREEN + queueAudienceLabel(type)
            + ChatColor.GRAY + " ready" + ChatColor.DARK_GRAY + " — "
            + ChatColor.GRAY + "Starting in " + ChatColor.WHITE + seconds + "s");
    }

    private void sendQueueGoPopup(QueueType type) {
        LinkedHashSet<UUID> queue = queues.get(type);
        if (queue == null || queue.isEmpty()) {
            return;
        }
        for (UUID playerId : queue) {
            Player current = Bukkit.getPlayer(playerId);
            if (current == null || !current.isOnline()) {
                continue;
            }
            current.sendTitle(ChatColor.GREEN + "" + ChatColor.BOLD + "GO!", "", 0, 18, 10);
            HydraSounds.playGo(current);
        }
    }

    private void notifyQueueTitle(QueueType type, String title, String subtitle) {
        LinkedHashSet<UUID> queue = queues.get(type);
        if (queue == null || queue.isEmpty()) {
            return;
        }
        for (UUID playerId : queue) {
            Player current = Bukkit.getPlayer(playerId);
            if (current == null || !current.isOnline()) {
                continue;
            }
            current.sendTitle(title == null ? "" : title, subtitle == null ? "" : subtitle, 5, 24, 8);
        }
    }

    private int countdownSecondsFor(QueueType type) {
        if (isHungerGames(type)) {
            return Math.max(3, hungerGamesCountdownSeconds);
        }
        return countdownSeconds;
    }

    private boolean usesQueueStartPopups(QueueType type) {
        return type != null && !useBrTerrain(type) && !isHungerGames(type);
    }

    private void clearMatchStartInProgress(QueueType type) {
        if (type != null) {
            matchStartInProgress.remove(type);
            hungerGamesLaunchCallbacksInFlight.remove(type);
        }
    }

    private int minPlayersToStartFor(QueueType type) {
        if (type == QueueType.SOLO) {
            return BR_SOLO_MIN_PLAYERS;
        }
        return minPlayersToStart;
    }

    private int idealPlayersFor(QueueType type) {
        if (type == QueueType.SOLO) {
            return BR_SOLO_MAX_PLAYERS;
        }
        return idealPlayers;
    }

    private void cancelCountdown(QueueType type, String reason) {
        if (countdowns.remove(type) == null) {
            return;
        }
        notifyQueue(type, ChatColor.YELLOW + reason);
    }

    private void tryStartCountdown(QueueType type) {
        if (brDevelopmentTestQueues.contains(type)) {
            return;
        }
        if (isValousLiveBrBlocked(type)) {
            countdowns.remove(type);
            return;
        }
        if (matchStartInProgress.contains(type)) {
            return;
        }
        if (countdowns.containsKey(type)) {
            return;
        }
        if (matchWorldEnabled && !isHungerGames(type)) {
            String activeWorld = primaryActiveMatchWorld(type);
            if (activeWorld != null) {
                if (hasMatchPlayersInWorld(activeWorld)) {
                    return;
                }
                clearStaleActiveMatchWorld(type, activeWorld, "[Queue] Cleared stale active match before countdown");
            }
        }
        if (queueSize(type) >= minPlayersToStartFor(type)) {
            startCountdown(type);
        }
    }

    private void maybePrewarmMatchWorld(QueueType type) {
        if (rejectValousLiveBr(type, null, "prewarm", false)) {
            return;
        }
        if (!matchWorldEnabled || queueSize(type) <= 0) {
            return;
        }
        if (isBattleRoyaleType(type)
            && brTerrainProfile == BrTerrainProfile.VALOUS
            && valousReadyFactoryEnabled) {
            startValousReadyFactoryIfIdle("queue_demand_" + type.key());
            return;
        }
        String activeWorld = primaryActiveMatchWorld(type);
        if (!isHungerGames(type) && activeWorld != null) {
            if (hasMatchPlayersInWorld(activeWorld)) {
                return;
            }
            clearStaleActiveMatchWorld(type, activeWorld, "[Queue] Cleared stale active match before prewarm");
        }
        if (!shouldRequestPrewarmedMatchWorld(type)) {
            return;
        }
        long now = System.currentTimeMillis();
        long cooldownUntil = prewarmCooldownUntilMs.getOrDefault(type, 0L);
        if (now < cooldownUntil) {
            return;
        }
        if (!prewarmInProgress.add(type)) {
            return;
        }
        createMatchWorldAsync(type).whenComplete((world, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
            try {
                if (error != null) {
                    prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + 10_000L);
                    plugin.getLogger().warning("[Queue] prewarm failed for " + type.displayName()
                        + ": " + error.getMessage());
                    return;
                }
                if (!matchWorldEnabled || queueSize(type) <= 0) {
                    if (world != null) {
                        String worldName = world.getName();
                        if (shouldDeferPrewarmedWorldCleanup(type, worldName)) {
                            addPrewarmedMatchWorld(type, worldName);
                        } else {
                            cleanupOrDetachPrewarmedWorld(worldName,
                                "[Queue] Discarded prewarm because match worlds are disabled or the queue is empty");
                        }
                    }
                    return;
                }
                if (!isBattleRoyaleType(type)
                    && hasEnoughCompletedPrewarmedMatchWorlds(type)
                    && !hasPendingMatchStart(type)) {
                    if (world != null) {
                        cleanupOrDetachPrewarmedWorld(world.getName(),
                            "[Queue] Discarded duplicate prewarm for " + type.displayName());
                    }
                    return;
                }
                if (world == null) {
                    prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + 10_000L);
                    plugin.getLogger().warning("[Queue] prewarm failed: could not create world for " + type.displayName());
                    return;
                }
                String worldName = world.getName();
                String currentActive = primaryActiveMatchWorld(type);
                if (!isHungerGames(type) && currentActive != null && hasMatchPlayersInWorld(currentActive)) {
                    cleanupOrDetachPrewarmedWorld(worldName,
                        "[Queue] Discarded prewarm because an active match is already using " + currentActive);
                    return;
                }
                if (queueSize(type) <= 0) {
                    if (shouldDeferPrewarmedWorldCleanup(type, worldName)) {
                        addPrewarmedMatchWorld(type, worldName);
                    } else {
                        cleanupOrDetachPrewarmedWorld(worldName,
                            "[Queue] Discarded prewarm because the queue emptied before it could be used");
                        prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + PREWARM_REQUEST_COOLDOWN_MS);
                        plugin.getLogger().info("[Queue] prewarm cleaned immediately (queue empty): "
                            + type.displayName() + " -> " + worldName);
                    }
                    return;
                }
                addPrewarmedMatchWorld(type, worldName);
                plugin.getLogger().info("Prewarmed " + type.displayName() + " world: " + worldName);
            } finally {
                prewarmInProgress.remove(type);
                resolvePendingMatchStart(type);
            }
        }));
    }

    private void maybeCleanupPrewarmedWorld(QueueType type) {
        if (type == null || queueSize(type) > 0) {
            return;
        }
        if (isBattleRoyaleType(type)) {
            if (hasClaimedPendingBrStart(type)) {
                plugin.getLogger().info("[Queue][BrGeneration] event=queue_empty_cleanup_deferred queue="
                    + type.key() + " reason=claimed_pending_start");
                return;
            }
            Deque<PendingStart> abandonedStarts = pendingMatchStarts.remove(type);
            if (abandonedStarts != null && !abandonedStarts.isEmpty()) {
                clearMatchStartInProgress(type);
            }
            for (BrGenerationFlight flight : new ArrayList<>(brGenerationFlights.values())) {
                if (flight.factoryManaged
                    || flight.key.queueType() != type
                    || flight.state == BrGenerationState.ACTIVE) {
                    continue;
                }
                cancelBrGenerationFlight(flight, "queue_emptied", true);
            }
            prewarmInProgress.remove(type);
        }
        if (prewarmInProgress.contains(type)) {
            return;
        }
        if (isHungerGames(type)
            && hungerGamesKeepReadyArena
            && prewarmedMatchWorldCount(type) <= 1) {
            return;
        }
        String worldName = firstPrewarmedMatchWorld(type);
        if (worldName == null) {
            return;
        }
        if (activeMatchWorldsFor(type).contains(worldName)) {
            return;
        }
        if (worldName.equals(valousReadyFactoryWorldName)) {
            return;
        }
        if (shouldDeferPrewarmedWorldCleanup(type, worldName)) {
            return;
        }
        removePrewarmedMatchWorld(type, worldName);
        cleanupWorld(worldName);
        prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + PREWARM_REQUEST_COOLDOWN_MS);
        plugin.getLogger().info("[Queue] prewarm cleaned (queue empty): " + type.displayName()
            + " -> " + worldName);
    }

    private boolean hasClaimedPendingBrStart(QueueType type) {
        Deque<PendingStart> starts = pendingMatchStarts.get(type);
        if (starts == null || starts.isEmpty()) {
            return false;
        }
        BrGenerationFlight flight = brGenerationFlights.values().stream()
            .filter(candidate -> candidate.key.queueType() == type
                || (candidate.factoryManaged && candidate.claimedQueueType == type))
            .filter(candidate -> !candidate.isTerminal())
            .findFirst()
            .orElse(null);
        if (flight == null || flight.ownerReservationId == null) {
            return false;
        }
        return starts.stream().anyMatch(start -> flight.ownerReservationId.equals(start.reservationId()));
    }

    private void sweepPrewarmedWorlds() {
        long now = System.currentTimeMillis();
        for (QueueType type : QueueType.values()) {
            if (prewarmInProgress.contains(type)) {
                continue;
            }
            for (String worldName : prewarmedMatchWorldsFor(type)) {
                if (isHungerGames(type)
                    && hungerGamesKeepReadyArena
                    && prewarmedMatchWorldCount(type) <= 1) {
                    break;
                }
                if (activeMatchWorldsFor(type).contains(worldName)) {
                    removePrewarmedMatchWorld(type, worldName);
                    continue;
                }
                if (worldName.equals(valousReadyFactoryWorldName)) {
                    continue;
                }
                if (queueSize(type) > 0) {
                    continue;
                }
                if (shouldDeferPrewarmedWorldCleanup(type, worldName)) {
                    continue;
                }
                long createdAt = prewarmCreatedAtMs.getOrDefault(worldName, now);
                if (now - createdAt < PREWARM_IDLE_TIMEOUT_MS) {
                    continue;
                }
                removePrewarmedMatchWorld(type, worldName);
                cleanupWorld(worldName);
                prewarmCooldownUntilMs.put(type, now + PREWARM_REQUEST_COOLDOWN_MS);
                plugin.getLogger().info("[Queue] prewarm timeout cleanup: " + type.displayName()
                    + " -> " + worldName);
            }
        }
    }

    private void sweepDetachedHungerGamesPrewarms() {
        if (detachedPrewarmedWorldsPendingShutdown.isEmpty()) {
            return;
        }
        for (String worldName : new ArrayList<>(detachedPrewarmedWorldsPendingShutdown)) {
            if (!isGeneratedHungerGamesWorldName(worldName)) {
                continue;
            }
            if (isActiveMatchWorldValue(worldName) || hasMatchPlayersInWorld(worldName)) {
                continue;
            }
            QueueType type = managedMatchWorldTypes.get(worldName);
            plugin.getLogger().warning("[Queue] Cleaning detached duplicate Hunger Games prewarm: " + worldName);
            cleanupWorld(worldName);
            if (isHungerGames(type)) {
                prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + PREWARM_REQUEST_COOLDOWN_MS);
            }
            return;
        }
    }

    private boolean shouldDeferPrewarmedWorldCleanup(QueueType type, String worldName) {
        if (type == null || worldName == null || worldName.isBlank()) {
            return false;
        }
        if (plugin.getServer().isStopping()) {
            return false;
        }
        // Paper/Moonrise can stall badly when we unload a large prewarmed world from the live
        // queue tick. Keep loaded prewarms around for reuse and let shutdown clean them up.
        World loaded = Bukkit.getWorld(worldName);
        if (loaded != null && !loaded.getPlayers().isEmpty()) {
            return true;
        }
        return useBrTerrain(type) && isMatchWorldPreparationBusy(worldName);
    }

    private void cleanupOrDetachPrewarmedWorld(String worldName, String reason) {
        if (worldName == null || worldName.isBlank()) {
            return;
        }
        BrGenerationFlight brFlight = brGenerationFlightsByWorld.get(worldName);
        if (brFlight != null && !brFlight.isClaimed() && brFlight.state != BrGenerationState.ACTIVE) {
            plugin.getLogger().info(reason + ": canceling unclaimed BR generation " + worldName + ".");
            cancelBrGenerationFlight(brFlight, "prewarm_abandoned", true);
            return;
        }
        World loaded = Bukkit.getWorld(worldName);
        if (!plugin.getServer().isStopping()
            && loaded != null
            && isGeneratedHungerGamesWorldName(worldName)
            && !isActiveMatchWorldValue(worldName)
            && loaded.getPlayers().isEmpty()) {
            QueueType type = managedMatchWorldTypes.get(worldName);
            plugin.getLogger().warning(reason + ": cleaning duplicate Hunger Games prewarm immediately: " + worldName);
            cleanupWorld(worldName);
            if (isHungerGames(type)) {
                prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + PREWARM_REQUEST_COOLDOWN_MS);
            }
            return;
        }
        if (!plugin.getServer().isStopping() && loaded != null) {
            if (detachedPrewarmedWorldsPendingShutdown.add(worldName)) {
                plugin.getLogger().info(reason + ": deferred live cleanup for " + worldName
                    + " until shutdown to avoid server-thread unload stalls.");
            }
            return;
        }
        detachedPrewarmedWorldsPendingShutdown.remove(worldName);
        cleanupWorld(worldName);
    }

    private void tickHellscapeNetherWorlds() {
        for (World world : Bukkit.getWorlds()) {
            if (!isHellscapeWorld(world)) {
                continue;
            }
            tickHellscapePlayerTerrainEffects(world);
            tickHellscapeFumeVents(world);
        }
    }

    private void tickValousWorlds() {
        for (World world : Bukkit.getWorlds()) {
            if (!isValousWorld(world)) {
                continue;
            }
            tickValousAtmosphere(world);
            tickValousPlayerTerrainEffects(world);
            tickValousGeysers(world);
            tickValousAmbientAudio(world);
        }
    }

    private void tickValousAtmosphere(World world) {
        if (world.getTime() != 18000L) {
            world.setTime(18000L);
        }
        world.setGameRule(GameRules.ADVANCE_TIME, false);
        world.setGameRule(GameRules.ADVANCE_WEATHER, true);
        if (!world.hasStorm() && world.isThundering()) {
            world.setThundering(false);
        }
    }

    private void tickValousPlayerTerrainEffects(World world) {
        for (Player player : world.getPlayers()) {
            if (!isPlayableValousPlayer(player)) {
                continue;
            }
            Location location = player.getLocation();
            int floorY = location.getBlockY() - 1;
            if (floorY < world.getMinHeight()) {
                continue;
            }
            Material surface = world.getBlockAt(location.getBlockX(), floorY, location.getBlockZ()).getType();
            if (surface == Material.MAGMA_BLOCK || surface == Material.CAMPFIRE || surface == Material.SOUL_CAMPFIRE) {
                player.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS, 35, 0, true, false, false));
                if (world.getFullTime() % 20L == 0L) {
                    player.damage(VALOUS_BOILING_GROUND_DAMAGE);
                }
            }
            if (location.getY() >= 52.0D) {
                applyValousSurfaceRegionPlayerEffects(player, world, location);
            } else {
                applyValousCaveRegionPlayerEffects(player, world, location);
            }
        }
    }

    private void applyValousSurfaceRegionPlayerEffects(Player player, World world, Location location) {
        long time = world.getFullTime();
        if (isValousBiome(location, ValousPrototypeValidator.BOILGROUNDS)) {
            if (time % 40L == 0L) {
                world.spawnParticle(Particle.ASH, location.clone().add(0.0D, 0.25D, 0.0D), 9, 0.75D, 0.12D, 0.75D, 0.01D);
                world.spawnParticle(Particle.SMOKE, location.clone().add(0.0D, 0.45D, 0.0D), 5, 0.45D, 0.18D, 0.45D, 0.008D);
            }
            if (time % 120L == 0L) {
                player.playSound(location, Sound.BLOCK_LAVA_POP, 0.18F, 0.58F);
            }
            return;
        }

        if (time % 80L == 0L) {
            player.addPotionEffect(new PotionEffect(PotionEffectType.DARKNESS, 95, 0, true, true, true));
        }
        if (time % 30L == 0L) {
            world.spawnParticle(Particle.SPORE_BLOSSOM_AIR, location.clone().add(0.0D, 0.8D, 0.0D), 10, 0.95D, 0.32D, 0.95D, 0.018D);
        }
        if (time % 140L == 0L) {
            player.playSound(location, Sound.BLOCK_FUNGUS_PLACE, 0.16F, 0.42F);
        }
    }

    private void applyValousCaveRegionPlayerEffects(Player player, World world, Location location) {
        switch (valousBiomeKey(location)) {
            case ValousPrototypeValidator.SCULK_ABYSS -> {
                if (world.getFullTime() % 80L == 0L) {
                    player.addPotionEffect(new PotionEffect(PotionEffectType.DARKNESS, 90, 0, true, true, true));
                    player.playSound(location, Sound.BLOCK_SCULK_SENSOR_CLICKING, 0.24F, 0.55F);
                }
            }
            case ValousPrototypeValidator.MOLTEN_CAVERNS -> {
                if (world.getFullTime() % 60L == 0L) {
                    player.setFireTicks(Math.max(player.getFireTicks(), 20));
                }
            }
            case ValousPrototypeValidator.FROZEN_CAVES ->
                player.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS, 45, 0, true, false, false));
            case ValousPrototypeValidator.LUSH_JUNGLE -> {
                if (world.getFullTime() % 100L == 0L) {
                    player.addPotionEffect(new PotionEffect(PotionEffectType.REGENERATION, 45, 0, true, false, true));
                }
            }
            default -> {
                // No cave-specific runtime effect outside an actual Valous cave biome.
            }
        }
    }

    private void tickValousGeysers(World world) {
        Map<Long, int[]> nearbyGeysers = new HashMap<>();
        int searchRadius = (int) Math.ceil(VALOUS_GEYSER_WARNING_RANGE) + VALOUS_GEYSER_SPACING;
        for (Player player : world.getPlayers()) {
            if (!isPlayableValousPlayer(player)) {
                continue;
            }
            Location location = player.getLocation();
            int minCellX = Math.floorDiv(location.getBlockX() - searchRadius, VALOUS_GEYSER_SPACING);
            int maxCellX = Math.floorDiv(location.getBlockX() + searchRadius, VALOUS_GEYSER_SPACING);
            int minCellZ = Math.floorDiv(location.getBlockZ() - searchRadius, VALOUS_GEYSER_SPACING);
            int maxCellZ = Math.floorDiv(location.getBlockZ() + searchRadius, VALOUS_GEYSER_SPACING);
            for (int cellX = minCellX; cellX <= maxCellX; cellX++) {
                for (int cellZ = minCellZ; cellZ <= maxCellZ; cellZ++) {
                    int anchorX = valousGeyserAnchorX(world.getSeed(), cellX, cellZ);
                    int anchorZ = valousGeyserAnchorZ(world.getSeed(), cellX, cellZ);
                    double dx = (anchorX + 0.5D) - location.getX();
                    double dz = (anchorZ + 0.5D) - location.getZ();
                    if ((dx * dx) + (dz * dz) > ((VALOUS_GEYSER_WARNING_RANGE + 3.0D) * (VALOUS_GEYSER_WARNING_RANGE + 3.0D))) {
                        continue;
                    }
                    int topY = world.getHighestBlockYAt(anchorX, anchorZ);
                    if (topY <= world.getMinHeight() || Math.abs(location.getY() - topY) > VALOUS_GEYSER_WARNING_RANGE) {
                        continue;
                    }
                    if (!isValousBiome(
                        new Location(world, anchorX + 0.5D, topY, anchorZ + 0.5D),
                        ValousPrototypeValidator.BOILGROUNDS
                    )) {
                        continue;
                    }
                    long key = (((long) anchorX) << 32) ^ (anchorZ & 0xffffffffL);
                    nearbyGeysers.putIfAbsent(key, new int[] {anchorX, anchorZ, cellX, cellZ, topY});
                }
            }
        }

        for (int[] geyser : nearbyGeysers.values()) {
            int anchorX = geyser[0];
            int anchorZ = geyser[1];
            int topY = geyser[4];
            Location ventTop = new Location(world, anchorX + 0.5D, topY + 1.0D, anchorZ + 0.5D);
            int phase = valousGeyserPhase(world, anchorX, anchorZ);
            int warningStart = VALOUS_GEYSER_IDLE_SECONDS * 20;
            int activeStart = warningStart + (VALOUS_GEYSER_WARNING_SECONDS * 20);
            if (phase >= activeStart) {
                applyValousGeyserActiveEffects(world, ventTop);
            } else if (phase >= warningStart) {
                applyValousGeyserWarningEffects(world, ventTop);
            }
        }
    }

    private void applyValousGeyserWarningEffects(World world, Location ventTop) {
        world.spawnParticle(Particle.CAMPFIRE_COSY_SMOKE, ventTop, 7, 0.35D, 0.30D, 0.35D, 0.01D);
        world.spawnParticle(Particle.SMOKE, ventTop.clone().add(0.0D, 0.35D, 0.0D), 5, 0.25D, 0.18D, 0.25D, 0.01D);
        world.playSound(ventTop, Sound.BLOCK_FIRE_EXTINGUISH, 0.38F, 0.70F);
    }

    private void applyValousGeyserActiveEffects(World world, Location ventTop) {
        world.spawnParticle(Particle.CAMPFIRE_COSY_SMOKE, ventTop.clone().add(0.0D, 1.0D, 0.0D), 30, 1.15D, 1.8D, 1.15D, 0.06D);
        world.spawnParticle(Particle.CLOUD, ventTop.clone().add(0.0D, 0.7D, 0.0D), 18, 0.7D, 1.2D, 0.7D, 0.04D);
        world.playSound(ventTop, Sound.BLOCK_LAVA_EXTINGUISH, 0.75F, 0.75F);

        double radiusSquared = VALOUS_GEYSER_RADIUS * VALOUS_GEYSER_RADIUS;
        for (Player target : world.getPlayers()) {
            if (!isPlayableValousPlayer(target)) {
                continue;
            }
            Location targetLocation = target.getLocation();
            if (targetLocation.getY() < ventTop.getY() - 2 || targetLocation.getY() > ventTop.getY() + 8) {
                continue;
            }
            if (targetLocation.distanceSquared(ventTop) > radiusSquared) {
                continue;
            }
            Vector launch = targetLocation.toVector().subtract(ventTop.toVector());
            launch.setY(0.0D);
            if (launch.lengthSquared() <= 0.001D) {
                launch = new Vector(0.0D, 0.0D, 1.0D);
            }
            launch.normalize().multiply(0.55D);
            launch.setY(1.05D);
            target.setVelocity(launch);
            target.damage(2.0D);
            target.setFireTicks(Math.max(target.getFireTicks(), 40));
        }
    }

    private void tickValousAmbientAudio(World world) {
        if (world.getFullTime() % 120L != 0L) {
            return;
        }
        for (Player player : world.getPlayers()) {
            if (!isPlayableValousPlayer(player)) {
                continue;
            }
            Location location = player.getLocation();
            String biomeKey = valousBiomeKey(location);
            if (ValousPrototypeValidator.SCULK_ABYSS.equals(biomeKey)) {
                player.playSound(location, Sound.BLOCK_SCULK_SHRIEKER_SHRIEK, 0.18F, 0.55F);
            } else if (ValousPrototypeValidator.LUSH_JUNGLE.equals(biomeKey)
                || ValousPrototypeValidator.MOLTEN_CAVERNS.equals(biomeKey)
                || ValousPrototypeValidator.FROZEN_CAVES.equals(biomeKey)) {
                player.playSound(location, Sound.AMBIENT_CAVE, 0.35F, 0.75F);
            } else if (ValousPrototypeValidator.BOILGROUNDS.equals(biomeKey)) {
                player.playSound(location, Sound.BLOCK_LAVA_AMBIENT, 0.22F, 0.55F);
            } else {
                player.playSound(location, Sound.BLOCK_FUNGUS_BREAK, 0.16F, 0.45F);
            }
        }
    }

    private boolean isPlayableValousPlayer(Player player) {
        return player != null
            && player.isOnline()
            && player.getGameMode() != GameMode.SPECTATOR
            && !isCustomSpectator(player)
            && isValousWorld(player.getWorld());
    }

    private boolean isValousWorld(World world) {
        return world != null
            && world.getEnvironment() == World.Environment.NORMAL
            && brMatchWorlds.contains(world.getName())
            && brTerrainProfile == BrTerrainProfile.VALOUS;
    }

    private boolean isValousMushroomBiome(Location location) {
        String key = valousBiomeKey(location);
        return ValousPrototypeValidator.MUSHROOM_THICKET.equals(key)
            || ValousPrototypeValidator.MUSHROOM_THICKET_COAST.equals(key);
    }

    private boolean isValousBiome(Location location, String expectedKey) {
        return expectedKey != null && expectedKey.equals(valousBiomeKey(location));
    }

    private String valousBiomeKey(Location location) {
        if (location == null || location.getWorld() == null) {
            return "";
        }
        Biome biome = location.getWorld().getBiome(
            location.getBlockX(),
            Math.max(
                location.getWorld().getMinHeight(),
                Math.min(location.getWorld().getMaxHeight() - 1, location.getBlockY())
            ),
            location.getBlockZ()
        );
        NamespacedKey key = biome == null ? null : biome.getKey();
        return key == null ? "" : key.toString();
    }

    private boolean isValousBoilgroundsColumn(long seed, int x, int z) {
        return valousIsBoilgroundsColumn(seed, x, z);
    }

    private boolean isValousMushroomThicketColumn(long seed, int x, int z) {
        return !valousIsBoilgroundsColumn(seed, x, z);
    }

    private int valousGeyserPhase(World world, int anchorX, int anchorZ) {
        int cycleTicks = (VALOUS_GEYSER_IDLE_SECONDS
            + VALOUS_GEYSER_WARNING_SECONDS
            + VALOUS_GEYSER_ACTIVE_SECONDS) * 20;
        int offset = (int) Math.round(((brHashToUnit(world.getSeed() + 0x7604L, anchorX, anchorZ) + 1.0D) * 0.5D) * cycleTicks);
        return Math.floorMod((int) (world.getFullTime() + offset), cycleTicks);
    }

    private static int valousGeyserAnchorX(long seed, int cellX, int cellZ) {
        return (cellX * VALOUS_GEYSER_SPACING)
            + (int) Math.round(((brHashToUnit(seed + 0x7601L, cellX, cellZ) + 1.0D) * 0.5D) * (VALOUS_GEYSER_SPACING - 1));
    }

    private static int valousGeyserAnchorZ(long seed, int cellX, int cellZ) {
        return (cellZ * VALOUS_GEYSER_SPACING)
            + (int) Math.round(((brHashToUnit(seed + 0x7602L, cellZ, cellX) + 1.0D) * 0.5D) * (VALOUS_GEYSER_SPACING - 1));
    }

    private void tickHellscapePlayerTerrainEffects(World world) {
        for (Player player : world.getPlayers()) {
            if (!isPlayableHellscapePlayer(player)) {
                continue;
            }
            Location location = player.getLocation();
            int floorY = location.getBlockY() - 1;
            if (floorY < world.getMinHeight()) {
                continue;
            }
            Material surface = world.getBlockAt(location.getBlockX(), floorY, location.getBlockZ()).getType();
            if (surface == HELLSCAPE_ASH_POWDER_MATERIAL) {
                player.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS, 25, 0, true, false, false));
            }
        }
    }

    private void tickHellscapeFumeVents(World world) {
        Map<Long, int[]> nearbyVentAnchors = new HashMap<>();
        int searchRadius = (int) Math.ceil(HELLSCAPE_FUME_VENT_WARNING_RANGE) + HELLSCAPE_FUME_VENT_SPACING;
        int minSearchY = Math.max(world.getMinHeight(), -64);
        int maxSearchY = Math.min(world.getMaxHeight() - 1, 256);
        for (Player player : world.getPlayers()) {
            if (!isPlayableHellscapePlayer(player)) {
                continue;
            }
            Location location = player.getLocation();
            int minCellX = Math.floorDiv(location.getBlockX() - searchRadius, HELLSCAPE_FUME_VENT_SPACING);
            int maxCellX = Math.floorDiv(location.getBlockX() + searchRadius, HELLSCAPE_FUME_VENT_SPACING);
            int minCellZ = Math.floorDiv(location.getBlockZ() - searchRadius, HELLSCAPE_FUME_VENT_SPACING);
            int maxCellZ = Math.floorDiv(location.getBlockZ() + searchRadius, HELLSCAPE_FUME_VENT_SPACING);
            for (int cellX = minCellX; cellX <= maxCellX; cellX++) {
                for (int cellZ = minCellZ; cellZ <= maxCellZ; cellZ++) {
                    int anchorX = hellscapeVentAnchorX(world.getSeed(), cellX, cellZ);
                    int anchorZ = hellscapeVentAnchorZ(world.getSeed(), cellX, cellZ);
                    double dx = (anchorX + 0.5D) - location.getX();
                    double dz = (anchorZ + 0.5D) - location.getZ();
                    if ((dx * dx) + (dz * dz) > ((HELLSCAPE_FUME_VENT_WARNING_RANGE + 3.0D) * (HELLSCAPE_FUME_VENT_WARNING_RANGE + 3.0D))) {
                        continue;
                    }
                    HellscapeSurfaceBlend blend = resolveHellscapeSurfaceBlend(world, anchorX, anchorZ);
                    if (blend.primary() != HellscapeRegion.FUME_VENTS) {
                        continue;
                    }
                    int floorY = computeHellscapeBlendedFloorY(world.getSeed(), blend, anchorX, anchorZ, minSearchY, maxSearchY);
                    int height = hellscapeVentHeight(world.getSeed(), cellX, cellZ);
                    int topY = floorY + height;
                    if (Math.abs(location.getY() - topY) > HELLSCAPE_FUME_VENT_WARNING_RANGE) {
                        continue;
                    }
                    long key = (((long) anchorX) << 32) ^ (anchorZ & 0xffffffffL);
                    nearbyVentAnchors.putIfAbsent(key, new int[] {anchorX, anchorZ, cellX, cellZ, floorY, topY});
                }
            }
        }

        for (int[] vent : nearbyVentAnchors.values()) {
            int anchorX = vent[0];
            int anchorZ = vent[1];
            int cellX = vent[2];
            int cellZ = vent[3];
            int floorY = vent[4];
            int topY = vent[5];
            int phase = hellscapeFumeVentPhase(world, anchorX, anchorZ);
            Location ventTop = new Location(world, anchorX + 0.5D, topY + 0.8D, anchorZ + 0.5D);
            int warningStart = HELLSCAPE_FUME_VENT_IDLE_SECONDS * 20;
            int activeStart = warningStart + (HELLSCAPE_FUME_VENT_WARNING_SECONDS * 20);
            if (phase >= activeStart) {
                applyHellscapeVentActiveEffects(world, ventTop, floorY, cellX, cellZ);
            } else if (phase >= warningStart) {
                applyHellscapeVentWarningEffects(world, ventTop);
            }
        }
    }

    private void applyHellscapeVentWarningEffects(World world, Location ventTop) {
        world.spawnParticle(Particle.SMOKE, ventTop, 8, 0.30D, 0.45D, 0.30D, 0.01D);
        world.spawnParticle(Particle.ASH, ventTop.clone().add(0.0D, 0.35D, 0.0D), 5, 0.22D, 0.22D, 0.22D, 0.01D);
        world.playSound(ventTop, Sound.BLOCK_FIRE_EXTINGUISH, 0.45F, 1.55F);
    }

    private void applyHellscapeVentActiveEffects(World world, Location ventTop, int floorY, int cellX, int cellZ) {
        world.spawnParticle(Particle.ASH, ventTop.clone().add(0.0D, 0.6D, 0.0D), 26, 1.6D, 0.8D, 1.6D, 0.04D);
        world.spawnParticle(Particle.SMOKE, ventTop, 18, 0.8D, 0.5D, 0.8D, 0.02D);
        world.playSound(ventTop, Sound.BLOCK_LAVA_EXTINGUISH, 0.65F, 1.10F);

        int ventHeight = hellscapeVentHeight(world.getSeed(), cellX, cellZ);
        double radiusSquared = HELLSCAPE_FUME_VENT_RADIUS * HELLSCAPE_FUME_VENT_RADIUS;
        for (Player target : world.getPlayers()) {
            if (!isPlayableHellscapePlayer(target)) {
                continue;
            }
            Location targetLocation = target.getLocation();
            if (targetLocation.getY() < floorY - 1 || targetLocation.getY() > floorY + ventHeight + 6) {
                continue;
            }
            if (targetLocation.distanceSquared(ventTop) > radiusSquared) {
                continue;
            }
            target.addPotionEffect(new PotionEffect(PotionEffectType.POISON, 80, 0, true, true, true));
        }
    }

    private boolean isPlayableHellscapePlayer(Player player) {
        return player != null
            && player.isOnline()
            && player.getGameMode() != GameMode.SPECTATOR
            && !isCustomSpectator(player);
    }

    private int hellscapeFumeVentPhase(World world, int anchorX, int anchorZ) {
        int cycleTicks = (HELLSCAPE_FUME_VENT_IDLE_SECONDS
            + HELLSCAPE_FUME_VENT_WARNING_SECONDS
            + HELLSCAPE_FUME_VENT_ACTIVE_SECONDS) * 20;
        int offset = (int) Math.round(((brHashToUnit(world.getSeed() + 0x5A04L, anchorX, anchorZ) + 1.0D) * 0.5D) * cycleTicks);
        return Math.floorMod((int) (world.getFullTime() + offset), cycleTicks);
    }

    private String hellscapePatrolCellKey(World world, int x, int z) {
        int cellX = Math.floorDiv(x, HELLSCAPE_PATROL_CELL_SIZE);
        int cellZ = Math.floorDiv(z, HELLSCAPE_PATROL_CELL_SIZE);
        return world.getName() + ":" + cellX + ":" + cellZ;
    }

    private void expandHellscapePiglinPatrol(Piglin seedMember, String groupId) {
        World world = seedMember.getWorld();
        Location origin = seedMember.getLocation();
        int extraPiglins = 2 + ThreadLocalRandom.current().nextInt(2);
        for (int i = 0; i < extraPiglins; i++) {
            Location spawn = findHellscapePatrolSpawn(world, origin, 4, 12);
            if (spawn != null) {
                Piglin member = world.spawn(spawn, Piglin.class, piglin -> {
                    markHellscapePatrolEntity(piglin, groupId, "member");
                    tuneHellscapePatrolMember(piglin);
                });
                member.setRemoveWhenFarAway(true);
            }
        }
        Location leaderSpawn = findHellscapePatrolSpawn(world, origin, 5, 13);
        if (leaderSpawn == null) {
            leaderSpawn = origin.clone();
        }
        Hoglin mount = world.spawn(leaderSpawn, Hoglin.class, hoglin -> {
            markHellscapePatrolEntity(hoglin, groupId, "mount");
            tuneHellscapePatrolMount(hoglin);
        });
        Piglin leader = world.spawn(leaderSpawn, Piglin.class, piglin -> {
            markHellscapePatrolEntity(piglin, groupId, "leader");
            tuneHellscapePatrolLeader(piglin);
        });
        mount.addPassenger(leader);
    }

    private void markHellscapePatrolEntity(Entity entity, String groupId, String role) {
        if (entity == null || groupId == null) {
            return;
        }
        entity.getPersistentDataContainer().set(hellscapePatrolKey, PersistentDataType.STRING, groupId);
        entity.getPersistentDataContainer().set(hellscapePatrolRoleKey, PersistentDataType.STRING, role == null ? "member" : role);
    }

    private void tuneHellscapePatrolMember(Piglin piglin) {
        piglin.setImmuneToZombification(true);
        piglin.setRemoveWhenFarAway(true);
    }

    private void tuneHellscapePatrolLeader(Piglin leader) {
        leader.setImmuneToZombification(true);
        leader.setRemoveWhenFarAway(true);
        leader.customName(LegacyComponentSerializer.legacySection().deserialize("§6Patrol Leader"));
        leader.setCustomNameVisible(true);
        AttributeInstance health = leader.getAttribute(Attribute.MAX_HEALTH);
        if (health != null) {
            health.setBaseValue(Math.max(24.0D, health.getBaseValue() + 8.0D));
            leader.setHealth(health.getValue());
        }
        EntityEquipment equipment = leader.getEquipment();
        if (equipment == null) {
            return;
        }
        ItemStack spear = createHellscapePatrolSpear();
        ItemMeta spearMeta = spear.getItemMeta();
        if (spearMeta != null) {
            spearMeta.displayName(LegacyComponentSerializer.legacySection().deserialize("§6Patrol Spear"));
            spear.setItemMeta(spearMeta);
        }
        spear.addUnsafeEnchantment(Enchantment.SHARPNESS, 1);
        equipment.setItemInMainHand(spear);
        equipment.setHelmet(new ItemStack(Material.GOLDEN_HELMET));
        equipment.setItemInMainHandDropChance(0.0F);
        equipment.setHelmetDropChance(0.0F);
    }

    private ItemStack createHellscapePatrolSpear() {
        Material material = Material.matchMaterial("golden_spear", true);
        if (material == null || !material.isItem()) {
            material = Material.matchMaterial("copper_spear", true);
        }
        if (material == null || !material.isItem()) {
            material = Material.GOLDEN_SWORD;
            plugin.getLogger().warning("[Hellscape] Could not resolve golden_spear/copper_spear; using golden sword fallback for patrol leader.");
        }
        return new ItemStack(material);
    }

    private void tuneHellscapePatrolMount(Hoglin hoglin) {
        hoglin.setImmuneToZombification(true);
        hoglin.setRemoveWhenFarAway(true);
        AttributeInstance health = hoglin.getAttribute(Attribute.MAX_HEALTH);
        if (health != null) {
            health.setBaseValue(Math.min(32.0D, Math.max(22.0D, health.getBaseValue() + 6.0D)));
            hoglin.setHealth(health.getValue());
        }
    }

    private boolean isHellscapePatrolOriginSafe(Location location) {
        if (location == null || location.getWorld() == null) {
            return false;
        }
        World world = location.getWorld();
        if (world.getPlayers().stream().anyMatch(player ->
            player.getWorld().equals(world)
                && player.getLocation().distanceSquared(location) < HELLSCAPE_PATROL_PLAYER_BUFFER * HELLSCAPE_PATROL_PLAYER_BUFFER
        )) {
            return false;
        }
        return !hasNearbyMaterial(location, HELLSCAPE_PATROL_PORTAL_SCAN_RADIUS, this::isPortalLikeMaterial)
            && !hasNearbyMaterial(location, HELLSCAPE_PATROL_STRUCTURE_SCAN_RADIUS, this::isHellscapeStructureMaterial);
    }

    private boolean hasNearbyMaterial(Location center, int radius, java.util.function.Predicate<Material> predicate) {
        if (center == null || center.getWorld() == null || predicate == null) {
            return false;
        }
        World world = center.getWorld();
        int minY = Math.max(world.getMinHeight(), center.getBlockY() - Math.max(3, radius / 2));
        int maxY = Math.min(world.getMaxHeight() - 1, center.getBlockY() + Math.max(3, radius / 2));
        for (int x = center.getBlockX() - radius; x <= center.getBlockX() + radius; x++) {
            for (int y = minY; y <= maxY; y++) {
                for (int z = center.getBlockZ() - radius; z <= center.getBlockZ() + radius; z++) {
                    if (predicate.test(world.getBlockAt(x, y, z).getType())) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean isPortalLikeMaterial(Material material) {
        return material == Material.NETHER_PORTAL
            || material == Material.OBSIDIAN
            || material == Material.CRYING_OBSIDIAN;
    }

    private boolean isHellscapeStructureMaterial(Material material) {
        return material == Material.NETHER_BRICKS
            || material == Material.NETHER_BRICK_FENCE
            || material == Material.NETHER_BRICK_STAIRS
            || material == Material.NETHER_BRICK_SLAB
            || material == Material.RED_NETHER_BRICKS
            || material == Material.CRACKED_NETHER_BRICKS
            || material == Material.CHISELED_NETHER_BRICKS
            || material == Material.POLISHED_BLACKSTONE_BRICKS
            || material == Material.CRACKED_POLISHED_BLACKSTONE_BRICKS
            || material == Material.CHISELED_POLISHED_BLACKSTONE
            || material == Material.POLISHED_BLACKSTONE
            || material == Material.POLISHED_BLACKSTONE_STAIRS
            || material == Material.POLISHED_BLACKSTONE_SLAB
            || material == Material.POLISHED_BLACKSTONE_WALL
            || material == Material.GILDED_BLACKSTONE
            || material == Material.LANTERN;
    }

    private Entity hellscapePatrolAttacker(Entity damager) {
        if (damager instanceof Projectile projectile) {
            ProjectileSource shooter = projectile.getShooter();
            return shooter instanceof Entity entity ? entity : null;
        }
        return damager;
    }

    private String hellscapePatrolGroupId(Entity entity) {
        if (entity == null) {
            return null;
        }
        return entity.getPersistentDataContainer().get(hellscapePatrolKey, PersistentDataType.STRING);
    }

    private Location findHellscapePatrolSpawn(World world, Location origin, int minRadius, int maxRadius) {
        if (world == null || origin == null) {
            return null;
        }
        ThreadLocalRandom random = ThreadLocalRandom.current();
        for (int attempt = 0; attempt < 18; attempt++) {
            double angle = random.nextDouble(Math.PI * 2.0D);
            double radius = minRadius + (random.nextDouble() * Math.max(1.0D, maxRadius - minRadius));
            int x = origin.getBlockX() + (int) Math.round(Math.cos(angle) * radius);
            int z = origin.getBlockZ() + (int) Math.round(Math.sin(angle) * radius);
            int startY = clamp(origin.getBlockY() + random.nextInt(-2, 5), world.getMinHeight() + 2, world.getMaxHeight() - 4);
            for (int y = startY; y >= Math.max(world.getMinHeight() + 2, startY - 10); y--) {
                Material feet = world.getBlockAt(x, y, z).getType();
                Material head = world.getBlockAt(x, y + 1, z).getType();
                Material floor = world.getBlockAt(x, y - 1, z).getType();
                if (!feet.isAir() || !head.isAir()) {
                    continue;
                }
                if (!isSafeHellscapePatrolFloor(floor)) {
                    continue;
                }
                return new Location(world, x + 0.5D, y, z + 0.5D);
            }
        }
        return null;
    }

    private boolean isSafeHellscapePatrolFloor(Material floor) {
        return floor != null
            && floor.isSolid()
            && floor != Material.LAVA
            && floor != Material.MAGMA_BLOCK
            && floor != Material.FIRE
            && floor != Material.SOUL_FIRE;
    }

    private void purgeHellscapePatrolState(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return;
        }
        String prefix = worldName + ":";
        hellscapePatrolCooldownUntilMs.keySet().removeIf(key -> key != null && key.startsWith(prefix));
    }

    private void tickBrWorldPreparations() {
        for (BrWorldPreparationState state : new ArrayList<>(brWorldPreparationStates.values())) {
            tickBrWorldPreparation(state);
        }
    }

    private void tickBrWorldPreparation(BrWorldPreparationState state) {
        if (state == null) {
            return;
        }
        if (state.phase == BrWorldPreparationPhase.READY
            || state.phase == BrWorldPreparationPhase.PROTOTYPE_VALIDATION) {
            return;
        }
        World world = Bukkit.getWorld(state.worldName);
        if (world == null) {
            brWorldPreparationStates.remove(state.worldName);
            BrGenerationFlight flight = brGenerationFlightsByWorld.get(state.worldName);
            if (flight != null && isCurrentBrGenerationFlight(flight)) {
                failBrGenerationFlight(flight, "world_unloaded_during_preparation");
                pendingMatchStarts.remove(flight.key.queueType());
                clearMatchStartInProgress(flight.key.queueType());
                cleanupWorld(state.worldName);
            }
            return;
        }
        if (!useBrTerrain(state.type)) {
            state.setPhase(BrWorldPreparationPhase.READY, 1, 1);
            return;
        }

        WorldChunkPreloadState preloadState = fullWorldPreloadStates.get(state.worldName);
        if (preloadState != null) {
            state.setPhase(BrWorldPreparationPhase.PREGENERATING, preloadState.index, preloadState.totalChunks);
            updateBrGenerationProgress(state.worldName, preloadState.index, preloadState.totalChunks);
            return;
        }

        if (state.phase == BrWorldPreparationPhase.CREATING) {
            maybeStartBrWorldPreparation(world, state.type);
            return;
        }

        if (asyncZipPlacementInProgress.contains(state.worldName)) {
            state.setPhase(
                BrWorldPreparationPhase.PREGENERATING,
                Math.max(state.completedUnits, 1),
                Math.max(state.totalUnits, 1)
            );
            return;
        }

        if (!brCenterTerrainPassComplete.contains(state.worldName)) {
            state.setPhase(BrWorldPreparationPhase.CENTER_TERRAIN, 0, 1);
            applyBrCenterTerrainPass(world);
            return;
        }

        BrGenerationFlight flight = brGenerationFlightsByWorld.get(state.worldName);
        if (flight != null && flight.key.terrainProfile() == BrTerrainProfile.VALOUS) {
            ValousRoutePostProcessor.Result routeResult = valousRoutePostProcessResults.get(state.worldName);
            if (routeResult == null) {
                state.setPhase(BrWorldPreparationPhase.CHUNK_HANDOFF, 0, 1);
                startValousRoutePostProcessing(state, flight);
                return;
            }
            if (!routeResult.passed()) {
                failValousRoutePostProcessing(state, flight, routeResult);
                return;
            }
        }

        if (shouldSpawnCornucopiaStructure(state.type) && !isCornucopiaReadyForMatchStart(world)) {
            state.setPhase(BrWorldPreparationPhase.PLACING_CORNUCOPIA, 0, 1);
            if (!cornucopiaPlacementInProgress.contains(state.worldName)) {
                ensureCornucopiaAndPedestalsAtOrigin(world);
            }
            return;
        }

        markBrWorldPreparationReady(state, "center terrain and Cornucopia prep complete");
    }

    private void maybeStartBrWorldPreparation(World world, QueueType type) {
        if (world == null || type == null || !useBrTerrain(type)) {
            return;
        }
        String worldName = world.getName();
        BrWorldPreparationState state = brWorldPreparationStates.computeIfAbsent(
            worldName,
            ignored -> new BrWorldPreparationState(worldName, type)
        );
        if (state.phase == BrWorldPreparationPhase.READY
            || state.phase == BrWorldPreparationPhase.PLACING_CORNUCOPIA
            || state.phase == BrWorldPreparationPhase.CENTER_TERRAIN
            || state.phase == BrWorldPreparationPhase.CHUNK_HANDOFF
            || state.phase == BrWorldPreparationPhase.POST_PROCESSING
            || state.phase == BrWorldPreparationPhase.PROTOTYPE_VALIDATION
            || brCenterTerrainPassComplete.contains(worldName)) {
            return;
        }
        WorldChunkPreloadState preloadState = fullWorldPreloadStates.get(worldName);
        if (preloadState != null) {
            state.setPhase(BrWorldPreparationPhase.PREGENERATING, preloadState.index, preloadState.totalChunks);
            return;
        }
        if (state.phase == BrWorldPreparationPhase.PREGENERATING && state.completedUnits > 0) {
            return;
        }
        int totalChunks = estimatedFullWorldPreloadChunkCount(world);
        state.setPhase(BrWorldPreparationPhase.PREGENERATING, 0, Math.max(1, totalChunks));
        startFullWorldChunkPreload(world, null);
    }

    private void markBrWorldPreparationReady(BrWorldPreparationState state, String reason) {
        if (state == null) {
            return;
        }
        BrGenerationFlight flight = brGenerationFlightsByWorld.get(state.worldName);
        if (flight != null && flight.key.terrainProfile() == BrTerrainProfile.VALOUS) {
            ValousPrototypeValidator.Result result = valousPrototypeValidationResults.get(state.worldName);
            if (result == null) {
                startValousPrototypeValidation(state, flight);
                return;
            }
            if (!result.passed()) {
                failValousPrototypeWorld(state, flight, result);
                return;
            }
        }
        if (state.phase != BrWorldPreparationPhase.READY) {
            plugin.getLogger().info("[Queue] BR preparation READY for " + state.worldName + " (" + reason + ").");
        }
        state.setPhase(BrWorldPreparationPhase.READY, 1, 1);
        World world = Bukkit.getWorld(state.worldName);
        if (flight != null && world != null) {
            completeBrGenerationFlightReady(flight, world);
        }
    }

    private void enableValousReadyFactoryForQueueDemand(QueueType type, Player actor) {
        if (!isBattleRoyaleType(type)
            || brTerrainProfile != BrTerrainProfile.VALOUS
            || !valousDevelopmentTestArmed
            || !isValousDevelopmentTestReady()
            || actor == null
            || !hasValousDevelopmentAccess(actor)
            || valousReadyFactoryEnabled) {
            return;
        }
        valousReadyFactoryEnabled = true;
        valousReadyFactoryReplacementPending = false;
        plugin.getLogger().warning("[Queue][ValousFactory] event=auto_enabled actor="
            + valousActorName(actor) + " source=queue_join queue=" + type.key()
            + " size=" + valousGenerationSize.key + " development_only=true");
    }

    private void startValousRoutePostProcessing(
        BrWorldPreparationState state,
        BrGenerationFlight flight
    ) {
        if (state == null || flight == null
            || valousRoutePostProcessJobs.containsKey(state.worldName)) {
            return;
        }
        World world = Bukkit.getWorld(state.worldName);
        if (world == null) {
            failBrGenerationFlight(flight, "route_postprocess_world_missing");
            return;
        }
        if (!world.getPlayers().isEmpty()) {
            failValousRoutePostProcessing(state, flight, null);
            return;
        }
        ValousPregenerationLedger ledger = valousPregenerationLedgers.get(state.worldName);
        if (ledger == null
            || !ledger.isComplete()
            || !world.getUID().equals(ledger.worldId())
            || !flight.token.equals(ledger.generationToken())) {
            plugin.getLogger().severe("[Queue][ValousHandoff] event=ledger_rejected world="
                + state.worldName + " token=" + flight.token
                + " ledger_present=" + (ledger != null)
                + " ledger_complete=" + (ledger != null && ledger.isComplete())
                + " world_uuid_match=" + (ledger != null && world.getUID().equals(ledger.worldId()))
                + " token_match=" + (ledger != null && flight.token.equals(ledger.generationToken())));
            failValousRoutePostProcessing(state, flight, null);
            return;
        }
        state.setPhase(BrWorldPreparationPhase.CHUNK_HANDOFF, 0, 1);
        transitionBrGenerationFlight(flight, BrGenerationState.CHUNK_HANDOFF, "pregeneration_ledger_handoff");
        ValousGenerationSize size = valousGenerationSizesByWorld.getOrDefault(
            rootMatchWorldName(state.worldName),
            valousGenerationSize
        );
        Path reportRoot = plugin.getDataFolder().toPath().resolve("valous-prototype-reports");
        ValousChunkHandoff.Result handoff = valousChunkHandoffResults.get(state.worldName);
        if (handoff == null) {
            if (valousChunkHandoffJobs.containsKey(state.worldName)) {
                return;
            }
            ValousChunkHandoff.Job handoffJob = ValousChunkHandoff.start(
                plugin,
                world,
                ledger,
                size.borderDiameter,
                reportRoot,
                new ValousChunkHandoff.LifecycleGuard() {
                    @Override
                    public boolean isCurrent() {
                        return isCurrentBrGenerationFlight(flight)
                            && Bukkit.getWorld(state.worldName) == world
                            && world.getUID().equals(ledger.worldId())
                            && flight.token.equals(ledger.generationToken());
                    }

                    @Override
                    public boolean isCanceled() {
                        return flight.canceled;
                    }

                    @Override
                    public boolean isWorldUnloading() {
                        return matchWorldService.isCleaning(state.worldName)
                            || Bukkit.getWorld(state.worldName) != world;
                    }

                    @Override
                    public String flightState() {
                        return flight.state.name();
                    }
                },
                result -> completeValousChunkHandoff(state, flight, result)
            );
            if (brWorldPreparationStates.get(state.worldName) == state
                && isCurrentBrGenerationFlight(flight)
                && !valousChunkHandoffResults.containsKey(state.worldName)) {
                valousChunkHandoffJobs.put(state.worldName, handoffJob);
            }
            return;
        }
        state.setPhase(BrWorldPreparationPhase.POST_PROCESSING, 0, 1);
        transitionBrGenerationFlight(flight, BrGenerationState.POSTPROCESSING, "chunk_handoff_complete");
        ValousRoutePostProcessor.Settings settings = new ValousRoutePostProcessor.Settings(
            VALOUS_PROTOTYPE_GENERATION_VERSION,
            flight.compatibility.datapackVersion(),
            flight.valousPolicy.id(),
            size.borderDiameter,
            reportRoot,
            ledger,
            handoff
        );
        ValousRoutePostProcessor.Job job = ValousRoutePostProcessor.start(
            plugin,
            world,
            settings,
            result -> completeValousRoutePostProcessing(state, flight, result)
        );
        if (brWorldPreparationStates.get(state.worldName) == state
            && isCurrentBrGenerationFlight(flight)
            && !valousRoutePostProcessResults.containsKey(state.worldName)) {
            valousRoutePostProcessJobs.put(state.worldName, job);
        }
    }

    private void completeValousChunkHandoff(
        BrWorldPreparationState state,
        BrGenerationFlight flight,
        ValousChunkHandoff.Result result
    ) {
        valousChunkHandoffJobs.remove(state.worldName);
        if (result == null
            || brWorldPreparationStates.get(state.worldName) != state
            || !isCurrentBrGenerationFlight(flight)
            || flight.canceled
            || flight.isTerminal()) {
            if (result != null && result.lease() != null) {
                result.lease().release("stale_handoff_completion");
            }
            plugin.getLogger().info("[Queue][ValousHandoff] event=stale_completion_ignored world="
                + state.worldName + " token=" + flight.token);
            return;
        }
        valousChunkHandoffResults.put(state.worldName, result);
        startValousRoutePostProcessing(state, flight);
    }

    private void completeValousRoutePostProcessing(
        BrWorldPreparationState state,
        BrGenerationFlight flight,
        ValousRoutePostProcessor.Result result
    ) {
        if (result == null
            || brWorldPreparationStates.get(state.worldName) != state
            || !isCurrentBrGenerationFlight(flight)
            || flight.canceled
            || flight.isTerminal()) {
            releaseValousChunkHandoff(state.worldName, "stale_postprocess_completion");
            plugin.getLogger().info("[Queue][ValousPostProcess] event=stale_completion_ignored world="
                + state.worldName + " token=" + flight.token);
            return;
        }
        if (!result.passed()) {
            valousRoutePostProcessJobs.remove(state.worldName);
            releaseValousChunkHandoff(state.worldName, "postprocess_rejected");
        }
        valousRoutePostProcessResults.put(state.worldName, result);
        plugin.getLogger().info("[Queue][ValousPostProcess] event=result_recorded world="
            + state.worldName + " token=" + flight.token + " status=" + result.summary()
            + " scan_ms=" + result.scanMs()
            + " planning_ms=" + result.planningMs()
            + " processing_ms=" + result.processingMs()
            + " modified_chunks=" + result.modifiedChunks().size()
            + " report=" + result.reportPath());
        if (!result.passed()) {
            failValousRoutePostProcessing(state, flight, result);
            return;
        }
        state.setPhase(BrWorldPreparationPhase.PLACING_CORNUCOPIA, 0, 1);
    }

    private void failValousRoutePostProcessing(
        BrWorldPreparationState state,
        BrGenerationFlight flight,
        ValousRoutePostProcessor.Result result
    ) {
        String detail = result == null || result.failureReason() == null || result.failureReason().isBlank()
            ? "route_postprocess_failed"
            : "route_postprocess_failed:" + result.failureReason();
        plugin.getLogger().severe("[Queue][ValousPostProcess] event=feasibility_world_rejected world="
            + state.worldName + " token=" + flight.token + " reason=" + detail
            + " action=factory_stopped");
        valousReadyFactoryEnabled = false;
        valousReadyFactoryReplacementPending = false;
        failBrGenerationFlight(flight, detail);
        abortPendingValousStartAfterPreparationFailure(state.type, state.worldName, detail);
        brWorldPreparationStates.remove(state.worldName, state);
        cleanupWorld(state.worldName);
    }

    private void startValousPrototypeValidation(
        BrWorldPreparationState state,
        BrGenerationFlight flight
    ) {
        if (state == null || flight == null
            || valousPrototypeValidationJobs.containsKey(state.worldName)) {
            return;
        }
        World world = Bukkit.getWorld(state.worldName);
        if (world == null) {
            failBrGenerationFlight(flight, "prototype_validation_world_missing");
            return;
        }
        state.setPhase(BrWorldPreparationPhase.PROTOTYPE_VALIDATION, 0, 1);
        transitionBrGenerationFlight(flight, BrGenerationState.VALIDATING, "route_postprocessing_complete");
        ValousGenerationSize size = valousGenerationSizesByWorld.getOrDefault(
            rootMatchWorldName(state.worldName),
            valousGenerationSize
        );
        Path reportRoot = plugin.getDataFolder().toPath().resolve("valous-prototype-reports");
        ValousPrototypeValidator.Settings settings = new ValousPrototypeValidator.Settings(
            VALOUS_PROTOTYPE_GENERATION_VERSION,
            flight.compatibility.datapackVersion(),
            flight.valousPolicy.id(),
            flight.valousSeedSelection,
            flight.seedSelectionMs,
            flight.createdAtMs,
            size.borderDiameter,
            reportRoot,
            valousRoutePostProcessResults.get(state.worldName),
            valousPregenerationLedgers.get(state.worldName),
            valousChunkHandoffResults.get(state.worldName),
            () -> releaseValousChunkHandoff(state.worldName, "validation_block_scan_complete")
        );
        ValousPrototypeValidator.Job job = ValousPrototypeValidator.start(
            plugin,
            world,
            settings,
            result -> completeValousPrototypeValidation(state, flight, result)
        );
        valousPrototypeValidationJobs.put(state.worldName, job);
    }

    private void completeValousPrototypeValidation(
        BrWorldPreparationState state,
        BrGenerationFlight flight,
        ValousPrototypeValidator.Result result
    ) {
        valousPrototypeValidationJobs.remove(state.worldName);
        if (result == null
            || brWorldPreparationStates.get(state.worldName) != state
            || !isCurrentBrGenerationFlight(flight)
            || flight.canceled
            || flight.isTerminal()) {
            releaseValousChunkHandoff(state.worldName, "stale_validation_completion");
            plugin.getLogger().info("[Queue][ValousPrototype] event=stale_validation_ignored world="
                + state.worldName + " token=" + flight.token);
            return;
        }
        valousPrototypeValidationResults.put(state.worldName, result);
        releaseValousChunkHandoff(state.worldName, result.passed()
            ? "validation_passed"
            : "validation_rejected");
        plugin.getLogger().info("[Queue][ValousPrototype] event=validation_complete world="
            + state.worldName + " token=" + flight.token + " status=" + result.summary()
            + " validation_ms=" + result.validationMs()
            + " generation_ms=" + result.generationMs()
            + " report=" + result.reportDirectory());
        if (!result.passed()) {
            failValousPrototypeWorld(state, flight, result);
            return;
        }
        markBrWorldPreparationReady(state, "Valous prototype traversal validation passed");
    }

    private void releaseValousChunkHandoff(String worldName, String reason) {
        ValousChunkHandoff.Job handoffJob = valousChunkHandoffJobs.remove(worldName);
        if (handoffJob != null) {
            handoffJob.cancel();
        }
        ValousChunkHandoff.Result handoffResult = valousChunkHandoffResults.remove(worldName);
        if (handoffResult != null && handoffResult.lease() != null) {
            handoffResult.lease().release(reason);
        }
    }

    private void failValousPrototypeWorld(
        BrWorldPreparationState state,
        BrGenerationFlight flight,
        ValousPrototypeValidator.Result result
    ) {
        String reason = result == null
            ? "prototype_validation_failed"
            : "prototype_validation_failed:" + result.failureReason();
        plugin.getLogger().warning("[Queue][ValousPrototype] event=world_rejected world="
            + state.worldName + " token=" + flight.token + " reason=" + reason);
        valousReadyFactoryEnabled = false;
        valousReadyFactoryReplacementPending = false;
        plugin.getLogger().severe("[Queue][ValousPrototype] event=feasibility_run_stopped world="
            + state.worldName + " token=" + flight.token + " action=factory_disabled");
        failBrGenerationFlight(flight, reason);
        abortPendingValousStartAfterPreparationFailure(state.type, state.worldName, reason);
        brWorldPreparationStates.remove(state.worldName, state);
        cleanupWorld(state.worldName);
    }

    private void updateBrGenerationProgress(String worldName, int generatedChunks, int totalChunks) {
        BrGenerationFlight flight = brGenerationFlightsByWorld.get(worldName);
        if (flight == null || !isCurrentBrGenerationFlight(flight) || flight.canceled) {
            return;
        }
        flight.generatedChunks = Math.max(0, generatedChunks);
        flight.totalChunks = Math.max(1, totalChunks);
        if (flight.ownerReservationId == null) {
            transitionBrGenerationFlight(flight, BrGenerationState.PREGENERATING, "chunk_progress");
        }
    }

    private void discardBrWorldPreparation(BrWorldPreparationState state, String reason) {
        if (state == null || state.worldName == null || state.worldName.isBlank()) {
            return;
        }
        String worldName = state.worldName;
        QueueType type = state.type;
        plugin.getLogger().warning("[Queue] Discarding BR world " + worldName + ": " + reason + ".");
        BrGenerationFlight flight = brGenerationFlightsByWorld.get(worldName);
        if (flight != null && !flight.isClaimed()) {
            cancelBrGenerationFlight(flight, "preparation_discarded:" + reason, true);
            return;
        }
        brWorldPreparationStates.remove(worldName);
        ValousPrototypeValidator.Job validationJob = valousPrototypeValidationJobs.remove(worldName);
        if (validationJob != null) {
            validationJob.cancel();
        }
        valousPrototypeValidationResults.remove(worldName);
        ValousRoutePostProcessor.Job postProcessJob = valousRoutePostProcessJobs.remove(worldName);
        if (postProcessJob != null) {
            postProcessJob.cancel();
        }
        releaseValousChunkHandoff(worldName, "world_cleanup");
        valousRoutePostProcessResults.remove(worldName);
        brCenterTerrainPassComplete.remove(worldName);
        BukkitTask centerTerrainTask = valousCenterTerrainTasks.remove(worldName);
        if (centerTerrainTask != null) {
            centerTerrainTask.cancel();
        }
        valousCenterTerrainAcquisitionInProgress.remove(worldName);
        releaseValousCenterTerrainChunks(Bukkit.getWorld(worldName), null, "preparation_discarded");
        cornucopiaPlacementInProgress.remove(worldName);
        fullWorldPreloadStates.remove(worldName);
        removePrewarmedMatchWorldValue(worldName);
        removeActiveMatchWorldValue(worldName);
        matchWorldPrepareNoticeAtMs.remove(type);
        cleanupWorld(worldName);
        if (type != null && queueSize(type) > 0) {
            prewarmCooldownUntilMs.remove(type);
            maybePrewarmMatchWorld(type);
        }
    }

    private boolean hasBrCenterStructureConflict(World world) {
        if (world == null) {
            return false;
        }
        int radius = BR_CENTER_STRUCTURE_CONFLICT_RADIUS;
        int radiusSq = radius * radius;
        int minY = world.getMinHeight() + 1;
        int maxY = Math.min(world.getMaxHeight() - 2, BR_CENTER_FLAT_DISK_TEST_CLEAR_MIN_Y);
        for (Chunk chunk : world.getLoadedChunks()) {
            int chunkMinX = chunk.getX() << 4;
            int chunkMinZ = chunk.getZ() << 4;
            int chunkMaxX = chunkMinX + 15;
            int chunkMaxZ = chunkMinZ + 15;
            int nearestX = Math.max(chunkMinX, Math.min(MID_CENTER_X, chunkMaxX));
            int nearestZ = Math.max(chunkMinZ, Math.min(MID_CENTER_Z, chunkMaxZ));
            if (squaredDistanceFromCenter(nearestX, nearestZ) > radiusSq) {
                continue;
            }
            for (BlockState state : chunk.getTileEntities()) {
                Block block = state.getBlock();
                if (squaredDistanceFromCenter(block.getX(), block.getZ()) > radiusSq) {
                    continue;
                }
                if (isBrCenterStructureConflictMaterial(block.getType())) {
                    logBrCenterStructureConflict(world, block, "tile");
                    return true;
                }
            }
        }

        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                if ((dx * dx) + (dz * dz) > radiusSq) {
                    continue;
                }
                int x = MID_CENTER_X + dx;
                int z = MID_CENTER_Z + dz;
                int surfaceY = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, x, z, true, false)));
                int scanMinY = Math.max(minY, surfaceY - BR_CENTER_STRUCTURE_CONFLICT_SCAN_BELOW_SURFACE);
                int scanMaxY = Math.min(maxY, surfaceY + BR_CENTER_STRUCTURE_CONFLICT_SCAN_ABOVE_SURFACE);
                for (int y = scanMinY; y <= scanMaxY; y++) {
                    Block block = world.getBlockAt(x, y, z);
                    if (isBrCenterStructureConflictMaterial(block.getType())) {
                        logBrCenterStructureConflict(world, block, "surface");
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static int squaredDistanceFromCenter(int x, int z) {
        int dx = x - MID_CENTER_X;
        int dz = z - MID_CENTER_Z;
        return (dx * dx) + (dz * dz);
    }

    private void logBrCenterStructureConflict(World world, Block block, String source) {
        plugin.getLogger().warning("[BR Terrain] Preserving existing structure terrain in " + world.getName()
            + " because " + block.getType()
            + " was found near mid at " + block.getX() + "," + block.getY() + "," + block.getZ()
            + " (" + source + " scan, radius=" + BR_CENTER_STRUCTURE_CONFLICT_RADIUS + ").");
    }

    private boolean isBrStructureProtectedColumn(World world, int x, int z, int minY, int maxY) {
        if (world == null) {
            return false;
        }
        int surfaceY = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, x, z, true, false)));
        int scanMinY = Math.max(minY, surfaceY - 12);
        int scanMaxY = Math.min(maxY, Math.max(surfaceY + 42, BR_CENTER_FLAT_DISK_TEST_CLEAR_MIN_Y));
        for (int ox = -2; ox <= 2; ox++) {
            for (int oz = -2; oz <= 2; oz++) {
                for (int y = scanMinY; y <= scanMaxY; y++) {
                    if (isBrCenterStructureConflictMaterial(world.getBlockAt(x + ox, y, z + oz).getType())) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean isBrCenterStructureConflictMaterial(Material type) {
        if (type == null || type.isAir()) {
            return false;
        }
        if (type == Material.CHEST
            || type == Material.TRAPPED_CHEST
            || type == Material.BARREL
            || type == Material.BELL
            || type == Material.CRAFTING_TABLE
            || type == Material.FURNACE
            || type == Material.BLAST_FURNACE
            || type == Material.SMOKER
            || type == Material.CAMPFIRE
            || type == Material.SOUL_CAMPFIRE
            || type == Material.BOOKSHELF
            || type == Material.CHISELED_BOOKSHELF
            || type == Material.LECTERN
            || type == Material.LANTERN
            || type == Material.SOUL_LANTERN) {
            return true;
        }
        String name = type.name();
        return name.endsWith("_BED")
            || name.endsWith("_DOOR")
            || name.endsWith("_TRAPDOOR")
            || name.endsWith("_FENCE")
            || name.endsWith("_FENCE_GATE")
            || name.endsWith("_WALL")
            || name.endsWith("_STAIRS")
            || name.endsWith("_SLAB")
            || name.endsWith("_PLANKS")
            || name.endsWith("_GLASS")
            || name.endsWith("_GLASS_PANE")
            || name.endsWith("_STAINED_GLASS")
            || name.endsWith("_STAINED_GLASS_PANE");
    }

    private int estimatedFullWorldPreloadChunkCount(World world) {
        ChunkPreloadArea area = resolveFullWorldPreloadArea(world);
        return area == null ? 0 : area.totalChunks();
    }

    private void applyBrCenterTerrainPass(World world) {
        if (world == null || !brMatchWorlds.contains(world.getName())) {
            return;
        }
        if (BR_CENTER_FLAT_DISK_TEST_MODE) {
            applyBrCenterFlatDiskTestPass(world);
            return;
        }
        String worldName = world.getName();
        if (!brCenterTerrainPassComplete.add(worldName)) {
            return;
        }
        int targetTop = resolveBrCenterArenaTargetTop(world);
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        long seed = world.getSeed() ^ 0xB9C37A5EL;
        int shaped = 0;
        int cleared = 0;
        int debris = 0;
        int lightTouched = 0;
        int radius = Math.max(BR_CENTER_LIGHT_TOUCH_RADIUS, BR_TRANSITION_RING_RADIUS);
        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                double distance = Math.hypot(dx, dz);
                if (distance > radius + 0.5D) {
                    continue;
                }
                int x = MID_CENTER_X + dx;
                int z = MID_CENTER_Z + dz;
                // Valous center preparation runs before the Cornucopia is placed, and the
                // datapack excludes rigid structures from this protected area. The generic
                // 5x5xvertical structure scan is prohibitively expensive across this disk.
                if (!isValousWorld(world) && isBrStructureProtectedColumn(world, x, z, minY, maxY)) {
                    continue;
                }
                int currentTop = Math.max(minY, Math.min(maxY, resolveCornucopiaSurfaceY(world, x, z)));
                if (distance <= BR_CENTER_ARENA_RADIUS) {
                    double scar = brNoise2(seed + 0x7100L, x * 0.105D, z * 0.105D);
                    int desiredTop = targetTop + (int) Math.round(scar * 0.85D);
                    shapeTerrainColumn(world, x, z, desiredTop, Math.min(maxY, targetTop + 5), 3, 3, 4);
                    int actualTop = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, x, z, false, false)));
                    applyBrArenaSurfaceMaterial(world, x, z, actualTop, seed, distance);
                    cleared += clearBrCenterObstructions(world, x, z, actualTop, 12, 0.88D, seed, true);
                    debris += maybePlaceBrArenaDebris(world, x, z, actualTop, seed, distance);
                    shaped++;
                    continue;
                }
                if (distance > BR_TRANSITION_RING_RADIUS) {
                    cleared += clearBrOuterSoftJunk(world, x, z, currentTop, seed, distance);
                    lightTouched++;
                    continue;
                }
                double t = clamp(
                    (distance - BR_CENTER_ARENA_RADIUS) / Math.max(1.0D, BR_TRANSITION_RING_RADIUS - BR_CENTER_ARENA_RADIUS),
                    0.0D,
                    1.0D
                );
                double smooth = smoothstep(t);
                double roll = brNoise2(seed + 0x7200L, x * 0.045D, z * 0.045D);
                double local = brNoise2(seed + 0x7201L, x * 0.115D, z * 0.115D);
                int transitionLift = (int) Math.round((roll * 1.15D * (1.0D - smooth)) + (local * 0.7D * smooth));
                int desiredTop = (int) Math.round((targetTop * (1.0D - smooth)) + (currentTop * smooth)) + transitionLift;
                int maxRaise = Math.max(1, (int) Math.round(brLerp(2.0D, 3.0D, smooth)));
                int maxCut = Math.max(1, (int) Math.round(brLerp(2.0D, 3.0D, smooth)));
                shapeTerrainColumn(world, x, z, desiredTop, Math.min(maxY, desiredTop + 4), maxRaise, maxCut, 3);
                int actualTop = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, x, z, false, false)));
                cleared += clearBrCenterObstructions(world, x, z, actualTop, 8, brLerp(0.38D, 0.08D, smooth), seed, false);
                if (distance < BR_CENTER_ARENA_RADIUS + 22.0D) {
                    applyBrTransitionSurfaceMaterial(world, x, z, actualTop, seed, smooth);
                }
                shaped++;
            }
        }
        plugin.getLogger().info("[BR Terrain] Center arena pass complete in " + worldName
            + " (targetTop=" + targetTop + ", innerRadius=" + BR_CENTER_ARENA_RADIUS
            + ", transitionRadius=" + BR_TRANSITION_RING_RADIUS + ", lightTouchRadius=" + BR_CENTER_LIGHT_TOUCH_RADIUS
            + ", shapedColumns=" + shaped + ", lightTouchedColumns=" + lightTouched
            + ", clearedBlocks=" + cleared + ", debrisBlocks=" + debris + ").");
    }

    private void applyBrCenterFlatDiskTestPass(World world) {
        if (isValousWorld(world)) {
            startIncrementalValousCenterFlatDiskPass(world);
            return;
        }
        applyBrCenterFlatDiskTestPassSynchronously(world);
    }

    private void applyBrCenterFlatDiskTestPassSynchronously(World world) {
        String worldName = world.getName();
        if (!brCenterTerrainPassComplete.add(worldName)) {
            return;
        }
        int targetTop = resolveBrCenterArenaTargetTop(world);
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int clearMaxY = Math.min(maxY, Math.max(
            targetTop + BR_CENTER_FLAT_DISK_TEST_CLEAR_HEADROOM,
            BR_CENTER_FLAT_DISK_TEST_CLEAR_MIN_Y
        ));
        int radius = BR_CENTER_FLAT_DISK_TEST_RADIUS;
        int blendWidth = Math.max(0, BR_CENTER_FLAT_DISK_TEST_BLEND_WIDTH);
        int outerSmoothWidth = Math.max(0, BR_CENTER_FLAT_DISK_TEST_OUTER_SMOOTH_WIDTH);
        int blendEndRadius = radius + blendWidth;
        int totalRadius = blendEndRadius + outerSmoothWidth;
        int columns = 0;
        int blendedColumns = 0;
        int outerSmoothedColumns = 0;
        int filled = 0;
        int cleared = 0;
        long seed = world.getSeed() ^ 0x5C17C1A0L;
        for (int dx = -totalRadius; dx <= totalRadius; dx++) {
            for (int dz = -totalRadius; dz <= totalRadius; dz++) {
                double distance = Math.hypot(dx, dz);
                if (distance > totalRadius + 0.5D) {
                    continue;
                }
                int x = MID_CENTER_X + dx;
                int z = MID_CENTER_Z + dz;
                if (!isValousWorld(world) && isBrStructureProtectedColumn(world, x, z, minY, maxY)) {
                    continue;
                }
                if (distance > radius + 0.5D) {
                    int currentTop = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, x, z, true, false)));
                    double edgeNoise = brNoise2(seed + 0x11L, x * 0.031D, z * 0.031D) * 5.0D;
                    double rawDelta = currentTop - targetTop;
                    boolean outerSmoothing = distance > blendEndRadius + 0.5D;
                    double smooth;
                    int maxDelta;
                    if (outerSmoothing) {
                        double t = clamp((distance - blendEndRadius + edgeNoise) / Math.max(1.0D, outerSmoothWidth), 0.0D, 1.0D);
                        smooth = smoothstep(t);
                        maxDelta = (int) Math.round(brLerp(
                            BR_CENTER_FLAT_DISK_TEST_MAX_BLEND_HEIGHT_DELTA,
                            BR_CENTER_FLAT_DISK_TEST_MAX_OUTER_HEIGHT_DELTA,
                            smooth
                        ));
                    } else {
                        double t = clamp((distance - radius + edgeNoise) / Math.max(1.0D, blendWidth), 0.0D, 1.0D);
                        smooth = smoothstep(t);
                        maxDelta = (int) Math.round(brLerp(2.0D, BR_CENTER_FLAT_DISK_TEST_MAX_BLEND_HEIGHT_DELTA, smooth));
                    }
                    int noiseLift = (int) Math.round(brNoise2(seed, x * 0.075D, z * 0.075D) * 1.4D * (1.0D - smooth));
                    int desiredTop = Math.max(minY, Math.min(maxY, targetTop
                        + (int) Math.round(clamp(rawDelta, -maxDelta, maxDelta))
                        + noiseLift));
                    int localClearMaxY = isValousWorld(world)
                        ? Math.min(maxY, desiredTop + 12)
                        : Math.min(maxY, Math.max(
                            desiredTop + Math.max(10, BR_CENTER_FLAT_DISK_TEST_CLEAR_HEADROOM / 2),
                            BR_CENTER_FLAT_DISK_TEST_CLEAR_MIN_Y
                        ));
                    for (int y = Math.max(minY, desiredTop - 5); y < desiredTop; y++) {
                        Block block = world.getBlockAt(x, y, z);
                        if (block.getType() == Material.BEDROCK) {
                            continue;
                        }
                        Material desired = y >= desiredTop - 3 ? Material.DIRT : Material.STONE;
                        if (block.getType() != desired) {
                            block.setType(desired, false);
                            filled++;
                        }
                    }
                    Block top = world.getBlockAt(x, desiredTop, z);
                    if (top.getType() != Material.GRASS_BLOCK) {
                        top.setType(Material.GRASS_BLOCK, false);
                        filled++;
                    }
                    for (int y = desiredTop + 1; y <= localClearMaxY; y++) {
                        Block block = world.getBlockAt(x, y, z);
                        Material type = block.getType();
                        if (type == Material.BEDROCK || type.isAir()) {
                            continue;
                        }
                        block.setType(Material.AIR, false);
                        cleared++;
                    }
                    if (outerSmoothing) {
                        outerSmoothedColumns++;
                    } else {
                        blendedColumns++;
                    }
                    continue;
                }
                for (int y = Math.max(minY, targetTop - 8); y < targetTop; y++) {
                    Block block = world.getBlockAt(x, y, z);
                    Material desired = y >= targetTop - 4 ? Material.DIRT : Material.STONE;
                    if (block.getType() != desired) {
                        block.setType(desired, false);
                        filled++;
                    }
                }
                Block top = world.getBlockAt(x, targetTop, z);
                if (top.getType() != Material.GRASS_BLOCK) {
                    top.setType(Material.GRASS_BLOCK, false);
                    filled++;
                }
                for (int y = targetTop + 1; y <= clearMaxY; y++) {
                    Block block = world.getBlockAt(x, y, z);
                    Material type = block.getType();
                    if (type == Material.BEDROCK || type.isAir()) {
                        continue;
                    }
                    block.setType(Material.AIR, false);
                    cleared++;
                }
                columns++;
            }
        }
        plugin.getLogger().info("[BR Terrain] Flat disk test pass complete in " + worldName
            + " (targetTop=" + targetTop + ", radius=" + radius
            + ", blendWidth=" + blendWidth + ", outerSmoothWidth=" + outerSmoothWidth
            + ", columns=" + columns + ", blendedColumns=" + blendedColumns
            + ", outerSmoothedColumns=" + outerSmoothedColumns + ", filledBlocks=" + filled
            + ", clearedBlocks=" + cleared + ").");
    }

    private void startIncrementalValousCenterFlatDiskPass(World world) {
        String worldName = world.getName();
        if (brCenterTerrainPassComplete.contains(worldName)
            || valousCenterTerrainTasks.containsKey(worldName)
            || !valousCenterTerrainAcquisitionInProgress.add(worldName)) {
            return;
        }
        ValousCenterTerrainState state = new ValousCenterTerrainState(world);
        ValousPregenerationLedger ledger = valousPregenerationLedgers.get(worldName);
        List<CompletableFuture<Chunk>> acquisitions = new ArrayList<>();
        List<Long> requiredKeys = new ArrayList<>();
        int minChunk = Math.floorDiv(-state.totalRadius, 16);
        int maxChunk = Math.floorDiv(state.totalRadius, 16);
        for (int chunkX = minChunk; chunkX <= maxChunk; chunkX++) {
            for (int chunkZ = minChunk; chunkZ <= maxChunk; chunkZ++) {
                long key = ValousPregenerationLedger.chunkKey(chunkX, chunkZ);
                if (ledger == null || !ledger.contains(key)) {
                    valousCenterTerrainAcquisitionInProgress.remove(worldName);
                    rejectValousCenterTerrainAcquisition(
                        worldName,
                        "chunk_absent_from_pregeneration_ledger:" + chunkX + "," + chunkZ
                    );
                    return;
                }
                requiredKeys.add(key);
                acquisitions.add(world.getChunkAtAsync(chunkX, chunkZ, false, true));
            }
        }
        plugin.getLogger().info("[Queue][ValousPreparation] event=center_chunk_acquisition_started world="
            + worldName + " chunks=" + requiredKeys.size() + " generate=false");
        CompletableFuture.allOf(acquisitions.toArray(CompletableFuture[]::new))
            .whenComplete((ignored, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
                if (!valousCenterTerrainAcquisitionInProgress.remove(worldName)) {
                    return;
                }
                World liveWorld = Bukkit.getWorld(worldName);
                if (error != null || liveWorld == null || !brMatchWorlds.contains(worldName)) {
                    rejectValousCenterTerrainAcquisition(
                        worldName,
                        error == null
                            ? "world_unavailable_after_chunk_acquisition"
                            : "chunk_acquisition_exception:" + error.getClass().getSimpleName()
                    );
                    return;
                }
                Set<Long> held = new LinkedHashSet<>();
                for (int index = 0; index < acquisitions.size(); index++) {
                    Chunk chunk = acquisitions.get(index).getNow(null);
                    if (chunk == null) {
                        releaseValousCenterTerrainChunks(liveWorld, held, "acquisition_failed");
                        rejectValousCenterTerrainAcquisition(
                            worldName,
                            "no_generation_chunk_acquisition_returned_null:"
                                + requiredKeys.get(index)
                        );
                        return;
                    }
                    liveWorld.addPluginChunkTicket(chunk.getX(), chunk.getZ(), plugin);
                    held.add(requiredKeys.get(index));
                }
                valousCenterTerrainHeldChunks.put(worldName, held);
                plugin.getLogger().info(
                    "[Queue][ValousPreparation] event=center_chunk_acquisition_complete world="
                        + worldName + " held=" + held.size() + " generate=false"
                );
                runIncrementalValousCenterFlatDiskPass(liveWorld, state);
            }));
    }

    private void runIncrementalValousCenterFlatDiskPass(
        World world,
        ValousCenterTerrainState state
    ) {
        String worldName = world.getName();
        plugin.getLogger().info("[Queue][ValousPreparation] event=stage_started world=" + worldName
            + " stage=center_terrain total_columns=" + state.totalCandidateColumns
            + " tick_budget_ms=" + (VALOUS_CENTER_TICK_BUDGET_NANOS / 1_000_000L)
            + " max_columns_per_tick=" + VALOUS_CENTER_MAX_COLUMNS_PER_TICK);
        BukkitTask task = new BukkitRunnable() {
            @Override
            public void run() {
                World liveWorld = Bukkit.getWorld(worldName);
                if (liveWorld == null || !brMatchWorlds.contains(worldName)) {
                    valousCenterTerrainTasks.remove(worldName);
                    releaseValousCenterTerrainChunks(liveWorld, null, "world_unavailable");
                    cancel();
                    return;
                }
                long tickStartedAt = System.nanoTime();
                int processed = 0;
                while (!state.complete()
                    && processed < VALOUS_CENTER_MAX_COLUMNS_PER_TICK
                    && System.nanoTime() - tickStartedAt < VALOUS_CENTER_TICK_BUDGET_NANOS) {
                    if (state.processNextColumn(liveWorld)) {
                        processed++;
                    }
                }
                state.maxTickNanos = Math.max(state.maxTickNanos, System.nanoTime() - tickStartedAt);
                BrWorldPreparationState preparation = brWorldPreparationStates.get(worldName);
                if (preparation != null) {
                    preparation.setPhase(
                        BrWorldPreparationPhase.CENTER_TERRAIN,
                        state.visitedColumns,
                        state.totalCandidateColumns
                    );
                }
                if (!state.complete()) {
                    return;
                }
                brCenterTerrainPassComplete.add(worldName);
                valousCenterTerrainTasks.remove(worldName);
                finalizeValousPreparedSpawn(liveWorld);
                releaseValousCenterTerrainChunks(liveWorld, null, "center_terrain_complete");
                plugin.getLogger().info("[Queue][ValousPreparation] event=stage_complete world=" + worldName
                    + " stage=center_terrain elapsed_ms=" + (System.currentTimeMillis() - state.startedAtMs)
                    + " max_tick_ms=" + String.format(Locale.ROOT, "%.3f", state.maxTickNanos / 1_000_000.0D)
                    + " target_top=" + state.targetTop
                    + " columns=" + state.columns
                    + " blended_columns=" + state.blendedColumns
                    + " outer_smoothed_columns=" + state.outerSmoothedColumns
                    + " filled_blocks=" + state.filled
                    + " cleared_blocks=" + state.cleared);
                cancel();
            }
        }.runTaskTimer(plugin, 1L, 1L);
        valousCenterTerrainTasks.put(worldName, task);
    }

    private void rejectValousCenterTerrainAcquisition(String worldName, String reason) {
        plugin.getLogger().severe(
            "[Queue][ValousPreparation] event=center_chunk_acquisition_failed world="
                + worldName + " reason=" + reason + " generate=false"
        );
        BrGenerationFlight flight = brGenerationFlightsByWorld.get(worldName);
        if (flight != null && isCurrentBrGenerationFlight(flight)) {
            failBrGenerationFlight(flight, "center_chunk_acquisition_failed:" + reason);
            pendingMatchStarts.remove(flight.key.queueType());
            clearMatchStartInProgress(flight.key.queueType());
        }
        cleanupWorld(worldName);
    }

    private void releaseValousCenterTerrainChunks(
        World world,
        Set<Long> explicitKeys,
        String reason
    ) {
        String worldName = world == null ? null : world.getName();
        Set<Long> held = explicitKeys;
        if (held == null && worldName != null) {
            held = valousCenterTerrainHeldChunks.remove(worldName);
        }
        if (held == null || held.isEmpty() || world == null) {
            return;
        }
        int released = 0;
        for (long key : held) {
            int chunkX = (int) (key >> 32);
            int chunkZ = (int) key;
            world.removePluginChunkTicket(chunkX, chunkZ, plugin);
            released++;
        }
        plugin.getLogger().info("[Queue][ValousPreparation] event=center_chunk_holds_released world="
            + world.getName() + " held=" + held.size() + " released=" + released
            + " reason=" + reason);
    }

    private void finalizeValousPreparedSpawn(World world) {
        if (world == null) {
            return;
        }
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int spawnY = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, 0, 0, true, false) + 1));
        world.setSpawnLocation(0, spawnY, 0);
        world.getWorldBorder().setCenter(0.0D, 0.0D);
        plugin.getLogger().info("[Queue][ValousPreparation] event=spawn_finalized world="
            + world.getName() + " x=0 y=" + spawnY + " z=0");
    }

    private final class ValousCenterTerrainState {
        private final int targetTop;
        private final int minY;
        private final int maxY;
        private final int clearMaxY;
        private final int radius;
        private final int blendWidth;
        private final int outerSmoothWidth;
        private final int blendEndRadius;
        private final int totalRadius;
        private final int totalCandidateColumns;
        private final long seed;
        private final long startedAtMs = System.currentTimeMillis();
        private int dx;
        private int dz;
        private int visitedColumns;
        private int columns;
        private int blendedColumns;
        private int outerSmoothedColumns;
        private int filled;
        private int cleared;
        private long maxTickNanos;

        private ValousCenterTerrainState(World world) {
            this.targetTop = resolveBrCenterArenaTargetTop(world);
            this.minY = world.getMinHeight() + 1;
            this.maxY = world.getMaxHeight() - 2;
            this.clearMaxY = Math.min(maxY, Math.max(
                targetTop + BR_CENTER_FLAT_DISK_TEST_CLEAR_HEADROOM,
                BR_CENTER_FLAT_DISK_TEST_CLEAR_MIN_Y
            ));
            this.radius = BR_CENTER_FLAT_DISK_TEST_RADIUS;
            this.blendWidth = Math.max(0, BR_CENTER_FLAT_DISK_TEST_BLEND_WIDTH);
            this.outerSmoothWidth = Math.max(0, BR_CENTER_FLAT_DISK_TEST_OUTER_SMOOTH_WIDTH);
            this.blendEndRadius = radius + blendWidth;
            this.totalRadius = blendEndRadius + outerSmoothWidth;
            int diameter = (totalRadius * 2) + 1;
            this.totalCandidateColumns = diameter * diameter;
            this.seed = world.getSeed() ^ 0x5C17C1A0L;
            this.dx = -totalRadius;
            this.dz = -totalRadius;
        }

        private boolean complete() {
            return dx > totalRadius;
        }

        private boolean processNextColumn(World world) {
            if (complete()) {
                return false;
            }
            int currentDx = dx;
            int currentDz = dz;
            dz++;
            if (dz > totalRadius) {
                dz = -totalRadius;
                dx++;
            }
            visitedColumns++;
            double distance = Math.hypot(currentDx, currentDz);
            if (distance > totalRadius + 0.5D) {
                return false;
            }
            int x = MID_CENTER_X + currentDx;
            int z = MID_CENTER_Z + currentDz;
            if (distance > radius + 0.5D) {
                int currentTop = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, x, z, true, false)));
                double edgeNoise = brNoise2(seed + 0x11L, x * 0.031D, z * 0.031D) * 5.0D;
                double rawDelta = currentTop - targetTop;
                boolean outerSmoothing = distance > blendEndRadius + 0.5D;
                double smooth;
                int maxDelta;
                if (outerSmoothing) {
                    double t = clamp(
                        (distance - blendEndRadius + edgeNoise) / Math.max(1.0D, outerSmoothWidth),
                        0.0D,
                        1.0D
                    );
                    smooth = smoothstep(t);
                    maxDelta = (int) Math.round(brLerp(
                        BR_CENTER_FLAT_DISK_TEST_MAX_BLEND_HEIGHT_DELTA,
                        BR_CENTER_FLAT_DISK_TEST_MAX_OUTER_HEIGHT_DELTA,
                        smooth
                    ));
                } else {
                    double t = clamp(
                        (distance - radius + edgeNoise) / Math.max(1.0D, blendWidth),
                        0.0D,
                        1.0D
                    );
                    smooth = smoothstep(t);
                    maxDelta = (int) Math.round(brLerp(
                        2.0D,
                        BR_CENTER_FLAT_DISK_TEST_MAX_BLEND_HEIGHT_DELTA,
                        smooth
                    ));
                }
                int noiseLift = (int) Math.round(
                    brNoise2(seed, x * 0.075D, z * 0.075D) * 1.4D * (1.0D - smooth)
                );
                int desiredTop = Math.max(minY, Math.min(maxY, targetTop
                    + (int) Math.round(clamp(rawDelta, -maxDelta, maxDelta))
                    + noiseLift));
                int localClearMaxY = Math.min(maxY, desiredTop + 12);
                for (int y = Math.max(minY, desiredTop - 5); y < desiredTop; y++) {
                    Block block = world.getBlockAt(x, y, z);
                    if (block.getType() == Material.BEDROCK) {
                        continue;
                    }
                    Material desired = y >= desiredTop - 3 ? Material.DIRT : Material.STONE;
                    if (block.getType() != desired) {
                        block.setType(desired, false);
                        filled++;
                    }
                }
                Block top = world.getBlockAt(x, desiredTop, z);
                if (top.getType() != Material.GRASS_BLOCK) {
                    top.setType(Material.GRASS_BLOCK, false);
                    filled++;
                }
                for (int y = desiredTop + 1; y <= localClearMaxY; y++) {
                    Block block = world.getBlockAt(x, y, z);
                    Material type = block.getType();
                    if (type == Material.BEDROCK || type.isAir()) {
                        continue;
                    }
                    block.setType(Material.AIR, false);
                    cleared++;
                }
                if (outerSmoothing) {
                    outerSmoothedColumns++;
                } else {
                    blendedColumns++;
                }
                return true;
            }
            for (int y = Math.max(minY, targetTop - 8); y < targetTop; y++) {
                Block block = world.getBlockAt(x, y, z);
                Material desired = y >= targetTop - 4 ? Material.DIRT : Material.STONE;
                if (block.getType() != desired) {
                    block.setType(desired, false);
                    filled++;
                }
            }
            Block top = world.getBlockAt(x, targetTop, z);
            if (top.getType() != Material.GRASS_BLOCK) {
                top.setType(Material.GRASS_BLOCK, false);
                filled++;
            }
            for (int y = targetTop + 1; y <= clearMaxY; y++) {
                Block block = world.getBlockAt(x, y, z);
                Material type = block.getType();
                if (type == Material.BEDROCK || type.isAir()) {
                    continue;
                }
                block.setType(Material.AIR, false);
                cleared++;
            }
            columns++;
            return true;
        }
    }

    private int resolveBrCenterArenaTargetTop(World world) {
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int total = 0;
        int samples = 0;
        List<Integer> valousLandHeights = isValousWorld(world) ? new ArrayList<>() : null;
        for (int dx = -BR_CENTER_TERRAIN_SAMPLE_RADIUS; dx <= BR_CENTER_TERRAIN_SAMPLE_RADIUS; dx += 4) {
            for (int dz = -BR_CENTER_TERRAIN_SAMPLE_RADIUS; dz <= BR_CENTER_TERRAIN_SAMPLE_RADIUS; dz += 4) {
                if (Math.hypot(dx, dz) > BR_CENTER_TERRAIN_SAMPLE_RADIUS + 0.5D) {
                    continue;
                }
                int height = Math.max(
                    minY,
                    Math.min(maxY, resolveCornucopiaSurfaceY(world, MID_CENTER_X + dx, MID_CENTER_Z + dz))
                );
                total += height;
                samples++;
                if (valousLandHeights != null && height >= 64) {
                    valousLandHeights.add(height);
                }
            }
        }
        int fallback = Math.max(minY, Math.min(maxY, resolveCornucopiaSurfaceY(world, MID_CENTER_X, MID_CENTER_Z)));
        if (valousLandHeights != null && !valousLandHeights.isEmpty()) {
            valousLandHeights.sort(Integer::compareTo);
            int median = valousLandHeights.get(valousLandHeights.size() / 2);
            return Math.max(72, Math.min(96, median));
        }
        if (samples <= 0) {
            return fallback;
        }
        return Math.max(minY, Math.min(maxY, Math.round(total / (float) samples)));
    }

    private int clearBrCenterObstructions(
        World world,
        int x,
        int z,
        int targetTop,
        int height,
        double chance,
        long seed,
        boolean clearWoody
    ) {
        if ((brHashToUnit(seed + 0x7300L, x, z) + 1.0D) * 0.5D > chance) {
            return 0;
        }
        int maxY = Math.min(world.getMaxHeight() - 2, targetTop + Math.max(2, height));
        int cleared = 0;
        for (int y = targetTop + 1; y <= maxY; y++) {
            Block block = world.getBlockAt(x, y, z);
            Material type = block.getType();
            if (type == Material.BEDROCK || type.isAir()) {
                continue;
            }
            if (!clearWoody && isWoodyOrLeafMaterial(type)) {
                continue;
            }
            if (isSoftClearMaterial(type) || isCornucopiaWaterMaterial(type)) {
                block.setType(Material.AIR, false);
                cleared++;
            }
        }
        return cleared;
    }

    private void applyBrArenaSurfaceMaterial(World world, int x, int z, int y, long seed, double distance) {
        Block top = world.getBlockAt(x, y, z);
        if (top.getType() == Material.BEDROCK) {
            return;
        }
        double scar = (brHashToUnit(seed + 0x7400L, x, z) + 1.0D) * 0.5D;
        Material material;
        if (distance < 10.0D && scar > 0.74D) {
            material = Material.STONE;
        } else if (scar > 0.95D) {
            material = Material.COBBLESTONE;
        } else if (scar > 0.90D) {
            material = Material.GRAVEL;
        } else if (scar > 0.80D) {
            material = Material.COARSE_DIRT;
        } else if (scar > 0.70D) {
            material = Material.DIRT;
        } else if (scar > 0.56D) {
            material = Material.DIRT_PATH;
        } else {
            material = Material.GRASS_BLOCK;
        }
        top.setType(material, false);
    }

    private void applyBrTransitionSurfaceMaterial(World world, int x, int z, int y, long seed, double blend) {
        Block top = world.getBlockAt(x, y, z);
        if (top.getType() == Material.BEDROCK) {
            return;
        }
        double scar = (brHashToUnit(seed + 0x7500L, x, z) + 1.0D) * 0.5D;
        if (scar > brLerp(0.86D, 0.96D, blend)) {
            top.setType(scar > 0.97D ? Material.GRAVEL : Material.COARSE_DIRT, false);
        }
    }

    private int maybePlaceBrArenaDebris(World world, int x, int z, int topY, long seed, double distance) {
        if (distance < 16.0D || distance > BR_CENTER_ARENA_RADIUS - 5.0D) {
            return 0;
        }
        double roll = (brHashToUnit(seed + 0x7600L, Math.floorDiv(x, 3), Math.floorDiv(z, 3)) + 1.0D) * 0.5D;
        if (roll > 0.0035D) {
            return 0;
        }
        Block above = world.getBlockAt(x, topY + 1, z);
        if (!above.getType().isAir()) {
            return 0;
        }
        above.setType(roll < 0.001D ? Material.COBBLESTONE : Material.STONE, false);
        return 1;
    }

    private int clearBrOuterSoftJunk(World world, int x, int z, int targetTop, long seed, double distance) {
        if (distance > BR_CENTER_LIGHT_TOUCH_RADIUS || (brHashToUnit(seed + 0x7700L, x, z) + 1.0D) * 0.5D > 0.05D) {
            return 0;
        }
        int maxY = Math.min(world.getMaxHeight() - 2, targetTop + 4);
        int cleared = 0;
        for (int y = targetTop + 1; y <= maxY; y++) {
            Block block = world.getBlockAt(x, y, z);
            Material type = block.getType();
            if (isBrLowVisualJunk(type)) {
                block.setType(Material.AIR, false);
                cleared++;
            }
        }
        return cleared;
    }

    private static boolean isWoodyOrLeafMaterial(Material type) {
        if (type == null) {
            return false;
        }
        String name = type.name();
        return name.endsWith("_LEAVES")
            || name.endsWith("_LOG")
            || name.endsWith("_WOOD")
            || name.endsWith("_STEM")
            || name.endsWith("_HYPHAE");
    }

    private static boolean isBrLowVisualJunk(Material type) {
        if (type == null || type.isAir() || type == Material.BEDROCK) {
            return false;
        }
        String name = type.name();
        return name.endsWith("_GRASS")
            || name.endsWith("_FERN")
            || name.endsWith("_FLOWER")
            || name.endsWith("_BUSH")
            || name.endsWith("_CARPET")
            || name.equals("VINE")
            || name.equals("SNOW")
            || name.equals("KELP")
            || name.equals("KELP_PLANT")
            || name.equals("SEAGRASS")
            || name.equals("TALL_SEAGRASS");
    }

    private ChunkPreloadArea resolveFullWorldPreloadArea(World world) {
        if (world == null) {
            return null;
        }
        WorldBorder border = world.getWorldBorder();
        double preloadDiameter = isHydraBrWorld(world)
            ? Math.max(effectiveBrTerrainBorderDiameter(), effectiveBrTerrainPreloadDiameter())
            : Math.max(16.0D, border.getSize());
        return new ChunkPreloadArea(
            preloadMinChunk(border.getCenter().getX(), preloadDiameter),
            preloadMaxChunk(border.getCenter().getX(), preloadDiameter),
            preloadMinChunk(border.getCenter().getZ(), preloadDiameter),
            preloadMaxChunk(border.getCenter().getZ(), preloadDiameter),
            preloadDiameter
        );
    }

    private static int preloadMinChunk(double center, double diameter) {
        return (int) Math.floor((center - (diameter / 2.0D)) / 16.0D);
    }

    private static int preloadMaxChunk(double center, double diameter) {
        return (int) Math.ceil((center + (diameter / 2.0D)) / 16.0D) - 1;
    }

    private boolean isBrWorldPreparationReady(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return false;
        }
        BrWorldPreparationState state = brWorldPreparationStates.get(worldName);
        return state != null && state.phase == BrWorldPreparationPhase.READY;
    }

    private boolean isCornucopiaReadyForMatchStart(World world) {
        if (world == null) {
            return false;
        }
        if (cornucopiaPlacementInProgress.contains(world.getName())) {
            return false;
        }
        if (!hasCornucopiaPresenceAtOrigin(world)) {
            return false;
        }
        if (!isCornucopiaCenterAreaReady(world)) {
            ensureCornucopiaCenterAreaReadyAsync(world);
        }
        return true;
    }

    private boolean isCornucopiaPlacementPhaseActive(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return false;
        }
        BrWorldPreparationState state = brWorldPreparationStates.get(worldName);
        if (state == null) {
            return false;
        }
        return state.phase == BrWorldPreparationPhase.PLACING_CORNUCOPIA;
    }

    private String describeBrWorldPreparation(String worldName) {
        BrWorldPreparationState state = worldName == null ? null : brWorldPreparationStates.get(worldName);
        if (state == null) {
            return "Preparing world...";
        }
        return switch (state.phase) {
            case CREATING -> "Creating world...";
            case PREGENERATING -> "Pregenerating world... " + state.progressPercent() + "%";
            case CHUNK_HANDOFF -> "Preparing generated chunks...";
            case POST_PROCESSING -> "Carving Valous gameplay routes...";
            case CENTER_TERRAIN -> "Carving center arena...";
            case PLACING_CORNUCOPIA -> "Preparing Cornucopia...";
            case PROTOTYPE_VALIDATION -> "Validating Valous traversal...";
            case READY -> "World ready.";
        };
    }

    private boolean shouldAnnounceBrWorldPreparationToPlayers(String worldName) {
        return false;
    }

    private String brWorldPreparationSidebarLine(QueueType type) {
        if (type == null || !useBrTerrain(type)) {
            return null;
        }
        String worldName = primaryActiveMatchWorld(type);
        if (worldName == null || worldName.isBlank()) {
            worldName = firstPrewarmedMatchWorld(type);
        }
        BrWorldPreparationState state = worldName == null ? null : brWorldPreparationStates.get(worldName);
        if (state == null) {
            return "Waiting";
        }
        return switch (state.phase) {
            case CREATING -> "Creating 0%";
            case PREGENERATING -> "Pregeneration " + state.progressPercent() + "%";
            case CHUNK_HANDOFF -> "Chunk handoff " + state.progressPercent() + "%";
            case POST_PROCESSING -> "Routes " + state.progressPercent() + "%";
            case CENTER_TERRAIN -> "Center " + state.progressPercent() + "%";
            case PLACING_CORNUCOPIA -> "Cornucopia " + state.progressPercent() + "%";
            case PROTOTYPE_VALIDATION -> "Validation " + state.progressPercent() + "%";
            case READY -> "Ready 100%";
        };
    }

    private void waitForBrWorldPreparationBeforeStart(
        QueueType type,
        World world,
        boolean forced,
        CommandSender triggerSender
    ) {
        if (world == null) {
            return;
        }
        maybeStartBrWorldPreparation(world, type);
        long now = System.currentTimeMillis();
        long lastNotice = matchWorldPrepareNoticeAtMs.getOrDefault(type, 0L);
        if ((now - lastNotice) >= MATCH_WORLD_PREPARE_MESSAGE_COOLDOWN_MS) {
            matchWorldPrepareNoticeAtMs.put(type, now);
            String status = describeBrWorldPreparation(world.getName());
            plugin.getLogger().info("[Queue] " + type.displayName() + " start waiting: " + status
                + " (" + world.getName() + ")");
            if (shouldAnnounceBrWorldPreparationToPlayers(world.getName())) {
                if (triggerSender != null) {
                    triggerSender.sendMessage(ChatColor.YELLOW + status);
                }
                notifyQueue(type, ChatColor.YELLOW + status);
            }
        }
        UUID retryToken = UUID.randomUUID();
        if (brMatchStartRetryTokens.putIfAbsent(type, retryToken) == null) {
            Bukkit.getScheduler().runTaskLater(
                plugin,
                () -> {
                    if (brMatchStartRetryTokens.remove(type, retryToken)) {
                        startMatch(type, forced, triggerSender);
                    }
                },
                MATCH_START_PREPARE_RETRY_TICKS
            );
        }
    }

    private void abortPendingValousStartAfterPreparationFailure(
        QueueType type,
        String worldName,
        String reason
    ) {
        if (type == null) {
            return;
        }
        Deque<PendingStart> pending = pendingMatchStarts.remove(type);
        brMatchStartRetryTokens.remove(type);
        clearMatchStartInProgress(type);
        cancelCountdown(type, "Valous world preparation failed.");
        matchWorldPrepareNoticeAtMs.remove(type);
        prewarmInProgress.remove(type);

        String message = ChatColor.RED + "Valous rejected " + worldName
            + " during final preparation. No replacement world will be generated automatically.";
        if (pending != null) {
            for (PendingStart start : pending) {
                if (start.sender() != null) {
                    start.sender().sendMessage(message);
                }
            }
        }
        notifyQueue(type, message);
        plugin.getLogger().severe("[Queue][ValousPreparation] event=pending_start_aborted queue="
            + type.key() + " world=" + worldName + " reason=" + reason
            + " pending=" + (pending == null ? 0 : pending.size())
            + " retry_invalidated=true automatic_replacement=false");
    }

    private boolean ensureMatchWorldReady(World world, QueueType type) {
        if (world == null) {
            return false;
        }
        if (isHungerGames(type) && managedMatchWorldTypes.get(world.getName()) != type) {
            return false;
        }
        if (isHungerGames(type)
            && hungerGamesPreparationStages.get(world.getName()) != HungerGamesPreparationStage.READY) {
            plugin.getLogger().warning("[Queue][HGPreparation] event=readiness_rejected world=" + world.getName()
                + " stage=" + hungerGamesPreparationStages.getOrDefault(
                    world.getName(), HungerGamesPreparationStage.NOT_STARTED));
            return false;
        }
        Location spawn = world.getSpawnLocation();
        if (spawn == null) {
            plugin.getLogger().warning("[Queue][HGPreparation] event=readiness_rejected world=" + world.getName()
                + " reason=missing_world_spawn");
            return false;
        }
        if (!world.isChunkLoaded(spawn.getBlockX() >> 4, spawn.getBlockZ() >> 4)) {
            plugin.getLogger().warning("[Queue][HGPreparation] event=readiness_rejected world=" + world.getName()
                + " reason=spawn_chunk_unloaded chunk_x=" + (spawn.getBlockX() >> 4)
                + " chunk_z=" + (spawn.getBlockZ() >> 4));
            return false;
        }
        if (useBrTerrain(type)) {
            if (!isChunkLoadedAt(world, 0, 0)) {
                return false;
            }
        }
        double borderSize = world.getWorldBorder().getSize();
        if (borderSize <= 1.0D) {
            plugin.getLogger().warning("[Queue][HGPreparation] event=readiness_rejected world=" + world.getName()
                + " reason=invalid_world_border size=" + borderSize);
            return false;
        }
        return true;
    }

    private void continueStartMatchAfterBrWorldReady(QueueType type, boolean forced, CommandSender triggerSender) {
        String localLobbyId = hungerGamesLocalLobbyIds.get(type);
        Bukkit.getScheduler().runTask(plugin, () -> {
            if (localLobbyId != null && (!localLobbyId.equals(hungerGamesLocalLobbyIds.get(type))
                || !matchStartInProgress.contains(type))) {
                return;
            }
            startMatch(type, forced, triggerSender);
        });
    }

    private void requestMatchWorldAsyncForStart(QueueType type, boolean forced, CommandSender triggerSender) {
        if (rejectValousLiveBr(type, triggerSender, "start", triggerSender != null)) {
            pendingMatchStarts.remove(type);
            clearMatchStartInProgress(type);
            return;
        }
        // Record the waiting start so it resumes when whichever prewarm is in flight
        // (this one OR a background prewarm) finishes. This is what makes a single
        // /forcestart sufficient instead of requiring a second one.
        Deque<PendingStart> pendingQueue = pendingMatchStarts.computeIfAbsent(type, ignored -> new ArrayDeque<>());
        PendingStart pending = pendingQueue.peekFirst();
        if (pending == null) {
            pending = new PendingStart(UUID.randomUUID(), forced, triggerSender);
            pendingQueue.addLast(pending);
        } else if (triggerSender != null && triggerSender != pending.sender()) {
            triggerSender.sendMessage(ChatColor.YELLOW + type.displayName()
                + " already has a pending start. Reusing the current world preparation.");
        }
        if (!prewarmInProgress.contains(type)) {
            prewarmInProgress.add(type);
            CompletableFuture<World> worldFuture = createMatchWorldAsync(type);
            // A force-start with no background prewarm creates the flight above, so
            // claim after acquisition as well as when reusing an existing flight.
            if (isBattleRoyaleType(type) && !claimBrGenerationFlight(type, pending.reservationId())) {
                prewarmInProgress.remove(type);
                pendingMatchStarts.remove(type);
                clearMatchStartInProgress(type);
                String busy = ChatColor.RED + "The prepared Valous world was claimed by another BR queue.";
                if (triggerSender != null) {
                    triggerSender.sendMessage(busy);
                }
                notifyQueue(type, busy, triggerSender);
                return;
            }
            worldFuture.whenComplete((world, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
                try {
                    if (error != null) {
                        plugin.getLogger().warning("[Queue] match world creation failed for "
                            + type.displayName() + ": " + error.getMessage());
                        prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + 10_000L);
                    } else if (world != null) {
                        maybeStartBrWorldPreparation(world, type);
                        addPrewarmedMatchWorld(type, world.getName());
                    } else {
                        prewarmCooldownUntilMs.put(type, System.currentTimeMillis() + 10_000L);
                    }
                } finally {
                    prewarmInProgress.remove(type);
                    matchWorldPrepareNoticeAtMs.remove(type);
                    resolvePendingMatchStart(type);
                }
            }));
        } else {
            if (isBattleRoyaleType(type) && !claimBrGenerationFlight(type, pending.reservationId())) {
                pendingMatchStarts.remove(type);
                clearMatchStartInProgress(type);
                String busy = ChatColor.RED + "The prepared Valous world was claimed by another BR queue.";
                if (triggerSender != null) {
                    triggerSender.sendMessage(busy);
                }
                notifyQueue(type, busy, triggerSender);
                return;
            }
        }
        long now = System.currentTimeMillis();
        long lastNotice = matchWorldPrepareNoticeAtMs.getOrDefault(type, 0L);
        if ((now - lastNotice) < MATCH_WORLD_PREPARE_MESSAGE_COOLDOWN_MS) {
            return;
        }
        matchWorldPrepareNoticeAtMs.put(type, now);
        String preparing = ChatColor.YELLOW + "Preparing " + type.displayName()
            + " world... match will start automatically when ready.";
        if (triggerSender != null) {
            triggerSender.sendMessage(preparing);
        }
        notifyQueue(type, preparing, triggerSender);
    }

    /**
     * Resume a start that was waiting on world preparation. Called from every prewarm
     * completion path (foreground and background). Fires the launch when a world is
     * ready, or reports a clear failure (and clears the pending start) so staff are
     * never left with a match stuck in "preparing".
     */
    private void resolvePendingMatchStart(QueueType type) {
        Deque<PendingStart> pendingQueue = pendingMatchStarts.get(type);
        if (pendingQueue == null || pendingQueue.isEmpty()) {
            return;
        }
        boolean canResume = hasPrewarmedMatchWorld(type)
            || (!isHungerGames(type) && hasActiveMatchWorld(type));
        if (canResume) {
            PendingStart pending = pendingQueue.removeFirst();
            if (pendingQueue.isEmpty()) {
                pendingMatchStarts.remove(type);
            }
            String ready = ChatColor.GREEN + type.displayName() + " world ready. Starting match now.";
            if (pending.sender() != null) {
                pending.sender().sendMessage(ready);
            }
            notifyQueue(type, ready, pending.sender());
            continueStartMatchAfterBrWorldReady(type, pending.forced(), pending.sender());
            return;
        }
        if (!prewarmInProgress.contains(type)) {
            PendingStart pending = pendingQueue.peekFirst();
            pendingMatchStarts.remove(type);
            // The original startMatch() left this set when it deferred to async prep;
            // clear it so the countdown/queue is not stuck after a failed preparation.
            clearMatchStartInProgress(type);
            String failed = ChatColor.RED + type.displayName()
                + " world preparation failed. Run /forcestart again to retry.";
            if (pending.sender() != null) {
                pending.sender().sendMessage(failed);
            }
            notifyQueue(type, ChatColor.RED + type.displayName() + " world preparation failed.", pending.sender());
            if (type == QueueType.HUNGERGAMES) {
                failPendingNetworkHungerGamesReservation("world_preparation_failed");
            }
        }
        // else: another prewarm is still running; its completion will resolve this.
    }

    private boolean hasPendingMatchStart(QueueType type) {
        Deque<PendingStart> pendingQueue = pendingMatchStarts.get(type);
        return pendingQueue != null && !pendingQueue.isEmpty();
    }

    private record PendingStart(UUID reservationId, boolean forced, CommandSender sender) {
    }

    private record PendingMatchLaunch(QueueType type, String worldName) {
    }

    private enum HungerGamesPreparationStage {
        NOT_STARTED,
        PREWARM_STARTED,
        WORLD_CREATED,
        PRELOAD_COMPLETE,
        STRUCTURE_PASTE_COMPLETE,
        LOOT_COMPLETE,
        READY
    }

    private int effectiveBrTerrainBorderDiameter() {
        if (brTerrainProfile != BrTerrainProfile.VALOUS) {
            return brTerrainBorderDiameter;
        }
        return valousGenerationSize.borderDiameter;
    }

    private int effectiveBrTerrainPreloadDiameter() {
        if (brTerrainProfile != BrTerrainProfile.VALOUS) {
            return brTerrainPreloadDiameter;
        }
        return valousPreloadDiameter(valousGenerationSize);
    }

    private void consumePrewarmedWorld(QueueType type, String worldName) {
        if (type == null || worldName == null || worldName.isBlank()) {
            return;
        }
        if (isHungerGames(type)) {
            releaseHungerGamesReadySpawnChunk(worldName);
        }
        BrGenerationFlight flight = brGenerationFlightsByWorld.get(worldName);
        if (flight != null && flight.factoryManaged) {
            removePrewarmedMatchWorldValue(worldName);
            valousReadyFactoryReplacementPending = valousReadyFactoryEnabled;
        } else {
            removePrewarmedMatchWorld(type, worldName);
        }
        if (flight != null && isCurrentBrGenerationFlight(flight)) {
            flight.claimedQueueType = type;
            transitionBrGenerationFlight(flight, BrGenerationState.ACTIVE, "world_consumed_by_match");
        }
    }

    private void startMatch(QueueType type, boolean forced, CommandSender triggerSender) {
        if (rejectValousLiveBr(type, triggerSender, "start", triggerSender != null)) {
            cancelCountdown(type,
                "Battle Royale is unavailable while the development-only Valous profile is selected.");
            pendingMatchStarts.remove(type);
            clearMatchStartInProgress(type);
            return;
        }
        if (type == QueueType.HUNGERGAMES_DUOS) rejectOversizedWaitingHungerGamesParties();
        matchStartInProgress.add(type);
        LinkedHashSet<UUID> queue = queues.get(type);
        int queuedCount = queue.size();
        if (!forced && queuedCount < minPlayersToStartFor(type)) {
            cancelCountdown(type, "Not enough players.");
            clearMatchStartInProgress(type);
            return;
        }
        if (queuedCount == 0) {
            maybeCleanupPrewarmedWorld(type);
            cancelCountdown(type, "Queue is empty.");
            if (triggerSender != null) {
                triggerSender.sendMessage(ChatColor.RED + "Queue is empty.");
            }
            clearMatchStartInProgress(type);
            return;
        }

        int toTake = Math.min(idealPlayersFor(type), queuedCount);
        List<UUID> selected = new ArrayList<>(toTake);
        if (type == QueueType.DUO) {
            int maxPlayers = toTake - (toTake % 2);
            Map<UUID, List<UUID>> groupedTeams = new HashMap<>();
            List<UUID> orderedTeams = new ArrayList<>();
            for (UUID id : queue) {
                UUID teamId = duoTeamByPlayer.getOrDefault(id, id);
                if (!groupedTeams.containsKey(teamId)) {
                    groupedTeams.put(teamId, new ArrayList<>());
                    orderedTeams.add(teamId);
                }
                groupedTeams.get(teamId).add(id);
            }
            for (UUID teamId : orderedTeams) {
                List<UUID> members = groupedTeams.get(teamId);
                if (members == null || members.size() < 2) {
                    continue;
                }
                if (selected.size() + 2 > maxPlayers) {
                    break;
                }
                selected.add(members.get(0));
                selected.add(members.get(1));
            }
            if (selected.size() < 2) {
                cancelCountdown(type, "Need at least one full duo team queued.");
                if (triggerSender != null) {
                    triggerSender.sendMessage(ChatColor.RED + "Need at least one full duo team queued.");
                }
                clearMatchStartInProgress(type);
                return;
            }
        } else if (type == QueueType.HUNGERGAMES_DUOS) {
            selected.addAll(selectWaitingHungerGamesDuos(toTake));
            if (selected.isEmpty() || (!forced && selected.size() < minPlayersToStartFor(type))) {
                cancelCountdown(type, "Not enough room for a complete queued party.");
                clearMatchStartInProgress(type);
                return;
            }
        } else {
            for (UUID id : queue) {
                selected.add(id);
                if (selected.size() >= toTake) {
                    break;
                }
            }
        }

        Map<UUID, UUID> selectedDuoTeams = new HashMap<>();
        if (type == QueueType.HUNGERGAMES_DUOS) {
            selectedDuoTeams.putAll(assignHungerGamesDuoTeams(selected));
        } else if (type == QueueType.DUO || (type == QueueType.HUNGERGAMES && pendingNetworkHungerGamesDuos)) {
            for (UUID id : selected) {
                selectedDuoTeams.put(id, duoTeamByPlayer.getOrDefault(id, id));
            }
        }

        List<Location> targetSpawns = new ArrayList<>();
        String matchWorldName = null;
        World matchWorld = null;

        if (type == QueueType.HUNGERGAMES && developmentNetworkPreparedWorld != null) {
            matchWorld = Bukkit.getWorld(developmentNetworkPreparedWorld);
            if (matchWorld == null || !ensureMatchWorldReady(matchWorld, type)) {
                failPendingNetworkHungerGamesReservation("development_reserved_world_lost");
                clearMatchStartInProgress(type);
                return;
            }
        }

        if (matchWorldEnabled) {
            if (!isHungerGames(type)) {
                String existingWorld = primaryActiveMatchWorld(type);
                if (existingWorld != null) {
                    if (hasMatchPlayersInWorld(existingWorld)) {
                        cancelCountdown(type, "A " + type.displayName() + " match is already running.");
                        notifyQueue(type, ChatColor.YELLOW + "Waiting for current " + type.displayName() + " match to end.");
                        clearMatchStartInProgress(type);
                        return;
                    }
                    clearStaleActiveMatchWorld(type, existingWorld, "[Queue] Cleared stale active match before start");
                    existingWorld = null;
                }
                if (existingWorld != null) {
                    World existing = Bukkit.getWorld(existingWorld);
                    if (existing != null) {
                        matchWorld = existing;
                    } else {
                        removeActiveMatchWorld(type, existingWorld);
                        matchStartedAtMs.remove(existingWorld);
                        matchBorderService.clear(existingWorld);
                    }
                }
            } else {
                // Hunger Games supports concurrent matches: sweep any finished (empty) HG
                // worlds but never block, so each new match consumes its own prewarmed/new world.
                for (String hgWorld : activeMatchWorldsFor(type)) {
                    if (!hasMatchPlayersInWorld(hgWorld)) {
                        clearStaleActiveMatchWorld(type, hgWorld,
                            "[Queue] Cleared finished HG match world before new start");
                    }
                }
            }
            if (matchWorld == null) {
                String prewarmedWorldName = firstPrewarmedMatchWorld(type);
                if (prewarmedWorldName != null) {
                    World prewarmed = Bukkit.getWorld(prewarmedWorldName);
                    if (prewarmed != null && !hasMatchPlayersInWorld(prewarmedWorldName)) {
                        matchWorld = prewarmed;
                    } else if (prewarmed != null) {
                        consumePrewarmedWorld(type, prewarmedWorldName);
                        cleanupOrDetachPrewarmedWorld(prewarmedWorldName,
                            "[Queue] Discarded occupied prewarmed world for " + type.displayName());
                    } else {
                        consumePrewarmedWorld(type, prewarmedWorldName);
                    }
                }
            }
            if (matchWorld == null) {
                requestMatchWorldAsyncForStart(type, forced, triggerSender);
                return;
            }
            if (!isHungerGames(type) && useBrTerrain(type)) {
                maybeStartBrWorldPreparation(matchWorld, type);
                matchWorldName = matchWorld.getName();
                if (!isBrWorldPreparationReady(matchWorldName)) {
                    waitForBrWorldPreparationBeforeStart(type, matchWorld, forced, triggerSender);
                    return;
                }
            }
            if (!isHungerGames(type) && useBrTerrain(type)) {
                matchWorldName = matchWorld.getName();
                claimReadyBrGenerationForStart(type, matchWorldName);
                continueStartMatchAfterSpawnPrep(
                    type,
                    selected,
                    selectedDuoTeams,
                    matchWorld,
                    matchWorldName,
                    triggerSender,
                    0
                );
                return;
            }
            if (!ensureMatchWorldReady(matchWorld, type)) {
                String failedWorldName = matchWorld.getName();
                cleanupWorld(failedWorldName);
                requestMatchWorldAsyncForStart(type, forced, triggerSender);
                return;
            }
            matchWorldName = matchWorld.getName();
            if (useBrTerrain(type)) {
                continueStartMatchAfterSpawnPrep(
                    type,
                    selected,
                    selectedDuoTeams,
                    matchWorld,
                    matchWorldName,
                    triggerSender,
                    0
                );
                return;
            }
            targetSpawns.addAll(generateMatchSpawns(matchWorld, selected.size(), type));
        } else {
            List<Location> usableSpawns = usableArenaSpawns();
            if (usableSpawns.isEmpty()) {
                cancelCountdown(type, "No arena spawns set. Use /queue setarena <index>.");
                if (triggerSender != null) {
                    triggerSender.sendMessage(ChatColor.RED + "No arena spawns set.");
                }
                clearMatchStartInProgress(type);
                return;
            }
            targetSpawns.addAll(usableSpawns);
        }

        if (targetSpawns.isEmpty()) {
            cancelCountdown(type, "No valid spawn locations found.");
            if (triggerSender != null) {
                triggerSender.sendMessage(ChatColor.RED + "No valid spawn locations found.");
            }
            if (matchWorldName != null) {
                removeActiveMatchWorld(type, matchWorldName);
                matchStartedAtMs.remove(matchWorldName);
                matchBorderService.clear(matchWorldName);
                cleanupWorld(matchWorldName);
            }
            clearMatchStartInProgress(type);
            if (type == QueueType.HUNGERGAMES) {
                failPendingNetworkHungerGamesReservation("no_valid_spawn_locations");
            }
            return;
        }

        reservePlayersForMatchLaunch(selected, type, matchWorldName);
        countdowns.remove(type);
        if (matchWorldName != null) {
            consumePrewarmedWorld(type, matchWorldName);
            addActiveMatchWorld(type, matchWorldName);
            long now = System.currentTimeMillis();
            matchStartedAtMs.put(matchWorldName, now);
            long intervalMs = Math.max(1, borderShrinkIntervalSecondsForWorld(matchWorldName)) * 1000L;
            matchBorderService.schedule(matchWorldName, now + intervalMs);
            plugin.getLogger().info("[Queue] world assigned: " + type.displayName() + " -> " + matchWorldName);
        }

        launchPreparedMatch(type, selected, selectedDuoTeams, targetSpawns, matchWorldName, triggerSender, 0);
    }

    private Map<UUID, UUID> assignHungerGamesDuoTeams(List<UUID> selected) {
        Map<UUID, UUID> groups = new HashMap<>();
        for (UUID id : selected) groups.put(id, hungerGamesDuoQueueGroup(id));
        return assignHungerGamesDuoTeams(selected, groups, ThreadLocalRandom.current());
    }

    private UUID hungerGamesDuoQueueGroup(UUID playerId) {
        UUID leader = partyService == null ? null : partyService.getLeader(playerId);
        return leader == null ? playerId : leader;
    }

    private List<UUID> selectWaitingHungerGamesDuos(int maxPlayers) {
        // Resolve parties at selection time, then keep that snapshot for the reserved launch.
        Map<UUID, List<UUID>> groups = new LinkedHashMap<>();
        for (UUID id : queues.get(QueueType.HUNGERGAMES_DUOS)) {
            groups.computeIfAbsent(hungerGamesDuoQueueGroup(id), ignored -> new ArrayList<>()).add(id);
        }
        List<UUID> selected = new ArrayList<>();
        for (List<UUID> group : groups.values()) {
            if (group.size() <= 2 && selected.size() + group.size() <= maxPlayers) selected.addAll(group);
        }
        return selected;
    }

    private void rejectOversizedWaitingHungerGamesParties() {
        if (partyService == null) return;
        for (UUID id : List.copyOf(queues.get(QueueType.HUNGERGAMES_DUOS))) {
            if (partyService.getPartySize(id) <= 2) continue;
            removeFromQueue(id, QueueType.HUNGERGAMES_DUOS);
            Player player = Bukkit.getPlayer(id);
            if (player != null && player.isOnline()) {
                sendQueueMessage(player, QueueType.HUNGERGAMES_DUOS,
                    ChatColor.RED + "Duos only supports parties of up to 2 players.");
                returnToHub(player, true);
            }
        }
    }

    static Map<UUID, UUID> assignHungerGamesDuoTeams(
        List<UUID> selected,
        Map<UUID, UUID> queuedTeams,
        RandomGenerator random
    ) {
        Map<UUID, List<UUID>> grouped = new LinkedHashMap<>();
        for (UUID id : selected) {
            grouped.computeIfAbsent(queuedTeams.getOrDefault(id, id), ignored -> new ArrayList<>()).add(id);
        }
        Map<UUID, UUID> assigned = new HashMap<>();
        List<UUID> solos = new ArrayList<>();
        for (List<UUID> members : grouped.values()) {
            if (members.size() >= 2) {
                UUID team = members.getFirst();
                members.stream().limit(2).forEach(member -> assigned.put(member, team));
            } else solos.add(members.getFirst());
        }
        for (int index = solos.size() - 1; index > 0; index--) {
            int swap = random.nextInt(index + 1);
            UUID current = solos.get(index);
            solos.set(index, solos.get(swap));
            solos.set(swap, current);
        }
        for (int index = 0; index < solos.size(); index += 2) {
            UUID team = solos.get(index);
            assigned.put(team, team);
            if (index + 1 < solos.size()) assigned.put(solos.get(index + 1), team);
        }
        return Map.copyOf(assigned);
    }

    static Map<UUID, Integer> assignHungerGamesDuoTeamColors(Collection<UUID> teamIds) {
        Map<UUID, Integer> colors = new LinkedHashMap<>();
        if (teamIds == null) return Map.of();
        int index = 0;
        for (UUID teamId : teamIds) {
            if (teamId == null || colors.containsKey(teamId)) continue;
            colors.put(teamId, hungerGamesTeamColorRgb(index));
            index++;
        }
        return Map.copyOf(colors);
    }

    static int hungerGamesTeamColorRgb(int index) {
        return HUNGER_GAMES_DUO_TEAM_COLORS.get(index % HUNGER_GAMES_DUO_TEAM_COLORS.size());
    }

    private void continueStartMatchAfterSpawnPrep(
        QueueType type,
        List<UUID> selected,
        Map<UUID, UUID> selectedDuoTeams,
        World matchWorld,
        String matchWorldName,
        CommandSender triggerSender,
        int attempt
    ) {
        if (matchWorld == null || matchWorldName == null || Bukkit.getWorld(matchWorldName) == null) {
            if (triggerSender != null) {
                triggerSender.sendMessage(ChatColor.RED + "Match world was unloaded before spawns were prepared.");
            }
            clearMatchStartInProgress(type);
            return;
        }
        if (attempt == 0) {
            plugin.getLogger().info("[Queue] preparing BR spawns in " + matchWorldName + " for "
                + selected.size() + " player(s).");
        }
        List<Location> targetSpawns = generateMatchSpawns(matchWorld, selected.size(), type);
        if (targetSpawns.isEmpty() && attempt < 4) {
            plugin.getLogger().info("[Queue] BR spawn generation retry " + (attempt + 1) + "/4 for "
                + matchWorldName + " after candidate chunk preload.");
            preloadBrSpawnCandidateChunksAsync(matchWorld)
                .whenComplete((loaded, error) -> {
                    if (error != null) {
                        plugin.getLogger().warning("[Queue] BR candidate chunk preload failed for "
                            + matchWorldName + ": " + error.getMessage());
                    } else if (Boolean.FALSE.equals(loaded)) {
                        plugin.getLogger().warning("[Queue] BR candidate chunk preload incomplete for "
                            + matchWorldName + ".");
                    }
                });
            Bukkit.getScheduler().runTaskLater(plugin, () ->
                continueStartMatchAfterSpawnPrep(
                    type,
                    selected,
                    selectedDuoTeams,
                    matchWorld,
                    matchWorldName,
                    triggerSender,
                    attempt + 1
                ), 20L);
            return;
        }
        if (targetSpawns.isEmpty()) {
            cancelCountdown(type, "No valid spawn locations found.");
            if (triggerSender != null) {
                triggerSender.sendMessage(ChatColor.RED + "No valid spawn locations found.");
            }
            cleanupWorld(matchWorldName);
            clearMatchStartInProgress(type);
            return;
        }

        reservePlayersForMatchLaunch(selected, type, matchWorldName);
        countdowns.remove(type);
        consumePrewarmedWorld(type, matchWorldName);
        addActiveMatchWorld(type, matchWorldName);
        long now = System.currentTimeMillis();
        matchStartedAtMs.put(matchWorldName, now);
        long intervalMs = Math.max(1, borderShrinkIntervalSecondsForWorld(matchWorldName)) * 1000L;
        matchBorderService.schedule(matchWorldName, now + intervalMs);
        plugin.getLogger().info("[Queue] world assigned: " + type.displayName() + " -> " + matchWorldName);
        launchPreparedMatch(type, selected, selectedDuoTeams, targetSpawns, matchWorldName, triggerSender, 0);
    }

    private boolean shouldUseFakePcs(QueueType type, String matchWorldName) {
        if (!fakePcsEnabled || matchWorldName == null || !useBrTerrain(type)) {
            return false;
        }
        ValousGenerationSize size = valousGenerationSizesByWorld.get(rootMatchWorldName(matchWorldName));
        return size == null || size == ValousGenerationSize.FULL;
    }

    private int matchStartChunkPreloadRadius(QueueType type, String matchWorldName) {
        if (useBrTerrain(type)) {
            return shouldUseFakePcs(type, matchWorldName) ? MATCH_START_BR_CHUNK_PRELOAD_RADIUS : 0;
        }
        return MATCH_START_CHUNK_PRELOAD_RADIUS;
    }

    private void launchPreparedMatch(
        QueueType type,
        List<UUID> selected,
        Map<UUID, UUID> selectedDuoTeams,
        List<Location> targetSpawns,
        String matchWorldName,
        CommandSender triggerSender,
        int prepareAttempt
    ) {
        boolean fakePcsEnabled = shouldUseFakePcs(type, matchWorldName);
        World matchWorld = matchWorldName == null ? null : Bukkit.getWorld(matchWorldName);
        if (matchWorldName != null && matchWorld == null) {
            plugin.getLogger().warning("[Queue] match world vanished before teleport: " + matchWorldName);
            finishMatchWorld(type, matchWorldName);
            if (triggerSender != null) {
                triggerSender.sendMessage(ChatColor.RED + "Match world was unloaded before players could be teleported.");
            }
            clearMatchStartInProgress(type);
            releasePendingMatchLaunches(selected, type, matchWorldName);
            if (type == QueueType.HUNGERGAMES) {
                failPendingNetworkHungerGamesReservation("match_world_unloaded_before_teleport");
            }
            return;
        }

        if (matchWorldName != null && useBrTerrain(type) && isMatchWorldPreparationBusy(matchWorldName)) {
            if (prepareAttempt == 0) {
                plugin.getLogger().info("[Queue] waiting for world prep before teleport: " + matchWorldName);
            }
            if (prepareAttempt < MATCH_START_PREPARE_MAX_RETRIES) {
                Bukkit.getScheduler().runTaskLater(
                    plugin,
                    () -> launchPreparedMatch(
                        type,
                        selected,
                        selectedDuoTeams,
                        targetSpawns,
                        matchWorldName,
                        triggerSender,
                        prepareAttempt + 1
                    ),
                    MATCH_START_PREPARE_RETRY_TICKS
                );
                return;
            }
            plugin.getLogger().warning("[Queue] timed out waiting for world prep in " + matchWorldName
                + "; continuing with preloaded player chunks.");
        }

        CompletableFuture<Boolean> preloadFuture = matchWorld == null
            ? CompletableFuture.completedFuture(true)
            : preloadMatchStartChunksAsync(
                matchWorld,
                targetSpawns,
                matchStartChunkPreloadRadius(type, matchWorldName)
            );
        preloadFuture = guardMatchStartChunkPreload(preloadFuture, matchWorldName);

        preloadFuture.whenComplete((loaded, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
            if (error != null) {
                plugin.getLogger().warning("[Queue] spawn chunk preload failed for "
                    + (matchWorldName == null ? "arena" : matchWorldName) + ": " + error.getMessage());
            } else if (!Boolean.TRUE.equals(loaded)) {
                plugin.getLogger().warning("[Queue] spawn chunk preload incomplete for "
                    + (matchWorldName == null ? "arena" : matchWorldName) + ".");
            }
            finalizePreparedMatchLaunch(type, selected, selectedDuoTeams, targetSpawns, matchWorldName, triggerSender);
        }));
    }

    private CompletableFuture<Boolean> guardMatchStartChunkPreload(CompletableFuture<Boolean> preloadFuture, String matchWorldName) {
        if (preloadFuture == null) {
            return CompletableFuture.completedFuture(false);
        }
        if (preloadFuture.isDone()) {
            return preloadFuture;
        }
        CompletableFuture<Boolean> guarded = new CompletableFuture<>();
        String targetName = matchWorldName == null ? "arena" : matchWorldName;
        BukkitTask timeoutTask = Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (guarded.complete(false)) {
                plugin.getLogger().warning("[Queue] spawn chunk preload timed out for "
                    + targetName + "; continuing with currently loaded chunks.");
            }
        }, MATCH_START_CHUNK_PRELOAD_TIMEOUT_TICKS);
        preloadFuture.whenComplete((loaded, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
            timeoutTask.cancel();
            if (error != null) {
                guarded.completeExceptionally(error);
                return;
            }
            guarded.complete(Boolean.TRUE.equals(loaded));
        }));
        return guarded;
    }

    private void finalizePreparedMatchLaunch(
        QueueType type,
        List<UUID> selected,
        Map<UUID, UUID> selectedDuoTeams,
        List<Location> targetSpawns,
        String matchWorldName,
        CommandSender triggerSender
    ) {
        boolean fakePcsEnabled = shouldUseFakePcs(type, matchWorldName);
        if (isHungerGames(type) && matchWorldName != null && !selectedDuoTeams.isEmpty()) {
            String root = rootMatchWorldName(matchWorldName);
            hungerGamesDuoWorlds.add(root);
            Map<UUID, Set<UUID>> roster = new LinkedHashMap<>();
            for (UUID id : selected) {
                if (!hasPendingMatchLaunch(id, type, matchWorldName)) {
                    continue;
                }
                UUID team = selectedDuoTeams.getOrDefault(id, id);
                roster.computeIfAbsent(team, ignored -> new LinkedHashSet<>()).add(id);
            }
            hungerGamesDuoRosters.put(root, roster);
            hungerGamesDuoTeamColors.put(root, assignHungerGamesDuoTeamColors(roster.keySet()));
        }
        int teleported = 0;
        int placeholders = 0;
        int[] arrivals = {0};
        int[] expectedArrivals = {0};
        boolean[] launchCompleted = {false};
        Runnable[] finishAfterArrival = {null};
        for (int i = 0; i < selected.size(); i++) {
            UUID id = selected.get(i);
            if (!claimPendingMatchLaunch(id, type, matchWorldName)) {
                continue;
            }
            BrTestParticipant placeholder = brTestParticipants.get(id);
            if (placeholder != null) {
                if (matchWorldName == null) {
                    brTestParticipants.remove(id);
                    continue;
                }
                placeholder.activate(matchWorldName);
                brDevelopmentTestWorlds.add(rootMatchWorldName(matchWorldName));
                placeholders++;
                continue;
            }
            Player player = Bukkit.getPlayer(id);
            if (player == null || !player.isOnline()) {
                continue;
            }
            clearBattleRoyaleSnapshots(id);
            inMatchPlayers.add(id);
            inMatchTypes.put(id, type);
            matchKills.put(id, 0);
            resetMatchRewardStats(id);
            if (type == QueueType.DUO || selectedDuoTeams.containsKey(id)) {
                duoTeamByPlayer.put(id, selectedDuoTeams.getOrDefault(id, id));
            }
            if (matchWorldName != null) {
                inMatchWorlds.put(id, matchWorldName);
            }
            Location landing = targetSpawns.get(i % targetSpawns.size()).clone();
            Location spawn = fakePcsEnabled && landing.getWorld() != null
                ? fakePcsPlaneStartLocation(landing.getWorld(), i, selected.size())
                : landing;
            int participantIndex = i;
            if (spawn.getWorld() != null
                && !isChunkLoadedAt(spawn.getWorld(), spawn.getBlockX(), spawn.getBlockZ())
                && !loadChunkSquare(spawn.getWorld(), spawn.getBlockX(), spawn.getBlockZ(), 0, true)) {
                plugin.getLogger().warning("[Queue] destination chunk failed to load for "
                    + player.getName() + " in " + spawn.getWorld().getName() + " @ "
                    + spawn.getBlockX() + "," + spawn.getBlockZ());
            }
            long transferStartedAt = System.currentTimeMillis();
            if (isHungerGames(type)) {
                logHungerGamesPlayerTransition(player, "hg_transfer_started", "world=" + matchWorldName);
            }
            Runnable arrival = () -> {
                if (!player.isOnline() || !inMatchPlayers.contains(id)
                    || (matchWorldName != null && Bukkit.getWorld(matchWorldName) == null)) return;
                clearCustomSpectatorState(player);
                if (menuService != null) menuService.preparePlayerForMatch(player);
                boolean teleportedToMatch = player.teleport(spawn);
                if (isHungerGames(type)) {
                    logHungerGamesPlayerTransition(player,
                        teleportedToMatch ? "hg_transfer_complete" : "hg_transfer_failed",
                        "world=" + matchWorldName + " elapsed_ms="
                            + (System.currentTimeMillis() - transferStartedAt));
                }
                if (!teleportedToMatch) return;
                plugin.getLogger().info("[Queue] teleported: " + player.getName()
                    + " -> " + type.displayName() + " @ " + spawn.getBlockX() + "," + spawn.getBlockY()
                    + "," + spawn.getBlockZ() + " in " + (matchWorldName == null ? "arena" : matchWorldName));
                player.setGameMode(GameMode.SURVIVAL);
                if (isHungerGames(type)) fullyHealMatchPlayer(player, type);
                player.setFallDistance(0.0f);
                if (isHungerGames(type)) applyHungerGamesStartFreeze(player, landing);
                if (fakePcsEnabled) {
                    beginFakePcsPlaneRide(player, landing.getWorld(), participantIndex, selected.size());
                    player.sendMessage(ChatColor.GREEN + "Match started.");
                    player.sendMessage(ChatColor.GRAY + (fakePcsTestingStationaryPlane
                        ? "Jump to drop." : "Jump when ready."));
                } else if (isHungerGames(type) && hungerGamesStartFreezeSeconds > 0) {
                    player.sendMessage(HYDRA_PREFIX + ChatColor.AQUA
                        + hungerGamesMatchModeLabel(matchWorldName) + " started. "
                        + ChatColor.GRAY + "Get ready.");
                } else {
                    player.sendMessage(HYDRA_PREFIX + ChatColor.GREEN + "Match started.");
                }
                player.playSound(player.getLocation(), Sound.ENTITY_PLAYER_LEVELUP, 1.0f, 1.1f);
                if (matchWorldName != null) refreshSidebar(player);
                if (++arrivals[0] >= expectedArrivals[0] && finishAfterArrival[0] != null) {
                    finishAfterArrival[0].run();
                }
            };
            if (!transitionTravel(player, arrival)) {
                plugin.getLogger().warning("[Queue] Entry fade already active for " + player.getName()
                    + "; completing the compulsory match handoff immediately.");
                arrival.run();
            }
            teleported++;
            expectedArrivals[0]++;
        }

        int scheduledPlayers = teleported;
        int placeholderPlayers = placeholders;
        finishAfterArrival[0] = () -> {
            if (launchCompleted[0]) return;
            launchCompleted[0] = true;
            if (triggerSender != null) {
                triggerSender.sendMessage(ChatColor.GREEN + "Started " + type.displayName() + " match for "
                    + scheduledPlayers + " player(s) and " + placeholderPlayers + " placeholder(s).");
            }
            if (scheduledPlayers == 0 && placeholderPlayers == 0) {
                if (matchWorldName != null) {
                    plugin.getLogger().warning("[Queue] no players teleported; cleaning world " + matchWorldName);
                    finishMatchWorld(type, matchWorldName);
                }
                clearMatchStartInProgress(type);
                if (type == QueueType.HUNGERGAMES) {
                    failPendingNetworkHungerGamesReservation("no_players_teleported");
                }
                return;
            }
            if (matchWorldName != null && Bukkit.getWorld(matchWorldName) == null) {
                plugin.getLogger().warning("[Queue] match world vanished during entry fade: " + matchWorldName);
                clearMatchStartInProgress(type);
                return;
            }
            int participantCount = scheduledPlayers + placeholderPlayers;
            broadcastMatchStart(type, participantCount);
            if (placeholderPlayers > 0 && matchWorldName != null) {
                plugin.getLogger().warning("[Queue][BrTest] event=test_active world=" + matchWorldName
                    + " placeholders=" + placeholderPlayers + " rewards=disabled auto_win=held");
            }
            if (matchWorldName != null) {
                if (isHungerGames(type)) {
                    if (type == QueueType.HUNGERGAMES
                        && pendingNetworkHungerGamesReservationId != null && plugin instanceof HGLootPlugin hydra
                        && hydra.networkBridgeService() != null) {
                        networkHungerGamesReservationByWorld.put(matchWorldName, pendingNetworkHungerGamesReservationId);
                        pendingNetworkHungerGamesReservationId = null;
                        pendingNetworkHungerGamesDuos = false;
                        hydra.networkBridgeService().matchStarted(matchWorldName);
                    }
                    scheduleHungerGamesKoth(matchWorldName, scheduledPlayers);
                    scheduleHungerGamesChestRefill(matchWorldName, scheduledPlayers);
                } else {
                    scheduleCornucopiaRefill(matchWorldName);
                }
                syncSpectatorVisibility(matchWorldName);
                maybeEvaluateMatchState(type, matchWorldName);
            }
            clearMatchStartInProgress(type);
        };
        if (scheduledPlayers == 0 || arrivals[0] >= expectedArrivals[0]) {
            finishAfterArrival[0].run();
        } else {
            Bukkit.getScheduler().runTaskLater(plugin, finishAfterArrival[0], 20L);
        }
    }

    private void reservePlayersForMatchLaunch(List<UUID> selected, QueueType type, String matchWorldName) {
        // The spawn-loading callback still owns the start guard even if every reserved player leaves.
        if (isHungerGames(type)) hungerGamesLaunchCallbacksInFlight.add(type);
        hungerGamesLocalLobbyIds.remove(type);
        PendingMatchLaunch launch = new PendingMatchLaunch(type, matchWorldName);
        for (UUID id : selected) {
            pendingMatchLaunches.put(id, launch);
            removeFromQueue(id, type, QueueRemovalReason.MATCH_START);
        }
        ensureHungerGamesLocalLobbyId(type);
    }

    private boolean hasPendingMatchLaunch(UUID playerId, QueueType type, String matchWorldName) {
        return Objects.equals(pendingMatchLaunches.get(playerId), new PendingMatchLaunch(type, matchWorldName));
    }

    private boolean claimPendingMatchLaunch(UUID playerId, QueueType type, String matchWorldName) {
        PendingMatchLaunch expected = new PendingMatchLaunch(type, matchWorldName);
        return pendingMatchLaunches.remove(playerId, expected);
    }

    private void releasePendingMatchLaunches(List<UUID> selected, QueueType type, String matchWorldName) {
        PendingMatchLaunch expected = new PendingMatchLaunch(type, matchWorldName);
        for (UUID id : selected) {
            pendingMatchLaunches.remove(id, expected);
        }
    }

    private void fullyHealMatchPlayer(Player player, QueueType type) {
        if (player == null) {
            return;
        }
        double targetMaxHealth = isHungerGames(type)
            ? HUNGER_GAMES_PLAYER_MAX_HEALTH
            : STANDARD_PLAYER_MAX_HEALTH;
        AttributeInstance maxHealthAttribute = player.getAttribute(Attribute.MAX_HEALTH);
        if (maxHealthAttribute != null) {
            maxHealthAttribute.setBaseValue(targetMaxHealth);
        }
        double maxHealth = maxHealthAttribute == null
            ? targetMaxHealth
            : Math.max(1.0D, maxHealthAttribute.getValue());
        player.setHealth(maxHealth);
        player.setFoodLevel(20);
        player.setSaturation(20.0f);
        player.setExhaustion(0.0f);
        player.setFireTicks(0);
        player.setFreezeTicks(0);
        player.setInvulnerable(false);
        player.setNoDamageTicks(0);
        player.setRemainingAir(player.getMaximumAir());
        for (PotionEffect effect : player.getActivePotionEffects()) {
            player.removePotionEffect(effect.getType());
        }
    }

    private void restoreStandardPlayerHealth(Player player) {
        if (player == null) {
            return;
        }
        AttributeInstance maxHealthAttribute = player.getAttribute(Attribute.MAX_HEALTH);
        if (maxHealthAttribute != null) {
            maxHealthAttribute.setBaseValue(STANDARD_PLAYER_MAX_HEALTH);
        }
        if (!player.isDead() && player.getHealth() > STANDARD_PLAYER_MAX_HEALTH) {
            player.setHealth(STANDARD_PLAYER_MAX_HEALTH);
        }
    }

    private boolean isHungerGamesMatchWorld(World world) {
        if (world == null) {
            return false;
        }
        return isHungerGamesMatchWorldName(world.getName());
    }

    public boolean isHungerGamesMatchWorldName(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return false;
        }
        if (activeMatchWorldsFor(QueueType.HUNGERGAMES).contains(worldName)
            || activeMatchWorldsFor(QueueType.HUNGERGAMES_DUOS).contains(worldName)) {
            return true;
        }
        if (prewarmedMatchWorldsFor(QueueType.HUNGERGAMES).contains(worldName)
            || prewarmedMatchWorldsFor(QueueType.HUNGERGAMES_DUOS).contains(worldName)) {
            return true;
        }
        QueueType managedType = managedMatchWorldTypes.get(worldName);
        if (managedType != null) {
            return isHungerGames(managedType);
        }
        return looksLikeHungerGamesWorldName(worldName)
            || (managedMatchWorlds.contains(worldName)
                && worldName.startsWith(matchWorldPrefix + "_" + QueueType.HUNGERGAMES.key() + "_"));
    }

    public boolean isVoiceChatSilverBonusEnabled() {
        return voiceChatWinSilverRewardMultiplier > 1.0D
            && (battleRoyaleWinSilverReward > 0 || hungerGamesWinSilverReward > 0);
    }

    public int voiceChatSilverBonusPercent() {
        return Math.max(0, (int) Math.round((voiceChatWinSilverRewardMultiplier - 1.0D) * 100.0D));
    }

    private static String linkedNetherWorldName(String rootWorldName) {
        if (rootWorldName == null || rootWorldName.isBlank()) {
            return null;
        }
        return rootWorldName + MATCH_NETHER_WORLD_SUFFIX;
    }

