    // --- Ready match world registry helpers (HG pool aware) ---

    private LinkedHashSet<String> prewarmedMatchWorldsMutable(QueueType type) {
        return prewarmedMatchWorldsByType.computeIfAbsent(type, ignored -> new LinkedHashSet<>());
    }

    private List<String> prewarmedMatchWorldsFor(QueueType type) {
        if (type == null) {
            return List.of();
        }
        LinkedHashSet<String> worlds = prewarmedMatchWorldsByType.get(type);
        return worlds == null ? List.of() : new ArrayList<>(worlds);
    }

    private int prewarmedMatchWorldCount(QueueType type) {
        LinkedHashSet<String> worlds = type == null ? null : prewarmedMatchWorldsByType.get(type);
        return worlds == null ? 0 : worlds.size();
    }

    private String firstPrewarmedMatchWorld(QueueType type) {
        LinkedHashSet<String> worlds = type == null ? null : prewarmedMatchWorldsByType.get(type);
        if (worlds != null && !worlds.isEmpty()) {
            return worlds.iterator().next();
        }
        if (isBattleRoyaleType(type) && valousReadyFactoryWorldName != null) {
            BrGenerationFlight flight = brGenerationFlightsByWorld.get(valousReadyFactoryWorldName);
            if (flight != null
                && flight.factoryManaged
                && !flight.isTerminal()
                && (flight.claimedQueueType == null || flight.claimedQueueType == type)
                && flight.compatibility.equals(currentBrGenerationCompatibility(type))
                && Bukkit.getWorld(valousReadyFactoryWorldName) != null) {
                return valousReadyFactoryWorldName;
            }
        }
        return null;
    }

    private boolean hasPrewarmedMatchWorld(QueueType type) {
        return firstPrewarmedMatchWorld(type) != null;
    }

    private void addPrewarmedMatchWorld(QueueType type, String worldName) {
        if (type == null || worldName == null || worldName.isBlank()) {
            return;
        }
        prewarmedMatchWorldsMutable(type).add(worldName);
        prewarmCreatedAtMs.put(worldName, System.currentTimeMillis());
    }

    private void removePrewarmedMatchWorld(QueueType type, String worldName) {
        if (type == null || worldName == null || worldName.isBlank()) {
            return;
        }
        LinkedHashSet<String> worlds = prewarmedMatchWorldsByType.get(type);
        if (worlds != null) {
            worlds.remove(worldName);
            if (worlds.isEmpty()) {
                prewarmedMatchWorldsByType.remove(type);
            }
        }
        if (worldName.equals(valousReadyFactoryWorldName)) {
            valousReadyFactoryWorldName = null;
        }
        prewarmCreatedAtMs.remove(worldName);
    }

    private void removePrewarmedMatchWorldValue(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return;
        }
        for (LinkedHashSet<String> worlds : prewarmedMatchWorldsByType.values()) {
            worlds.remove(worldName);
        }
        prewarmedMatchWorldsByType.values().removeIf(LinkedHashSet::isEmpty);
        if (worldName.equals(valousReadyFactoryWorldName)) {
            valousReadyFactoryWorldName = null;
        }
        prewarmCreatedAtMs.remove(worldName);
    }

    private boolean isPrewarmedMatchWorldValue(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return false;
        }
        if (worldName.equals(valousReadyFactoryWorldName)) {
            return true;
        }
        for (LinkedHashSet<String> worlds : prewarmedMatchWorldsByType.values()) {
            if (worlds.contains(worldName)) {
                return true;
            }
        }
        return false;
    }

    private int targetPrewarmedMatchWorldCount(QueueType type) {
        if (!isHungerGames(type)) {
            return 1;
        }
        int queuedCount = queueSize(type);
        int idealCount = Math.max(1, idealPlayersFor(type));
        int queueDemand = queuedCount <= 0 ? 0 : (int) Math.ceil((double) queuedCount / idealCount);
        int keepReadyDemand = hungerGamesKeepReadyArena ? 1 : 0;
        return Math.min(HUNGER_GAMES_READY_ARENA_POOL_MAX, Math.max(keepReadyDemand, queueDemand));
    }

    private int detachedPrewarmedMatchWorldCount(QueueType type) {
        if (type == null || detachedPrewarmedWorldsPendingShutdown.isEmpty()) {
            return 0;
        }
        int count = 0;
        for (String worldName : detachedPrewarmedWorldsPendingShutdown) {
            QueueType managedType = managedMatchWorldTypes.get(worldName);
            if (managedType == type) {
                count++;
            }
        }
        return count;
    }

    private boolean shouldRequestPrewarmedMatchWorld(QueueType type) {
        if (type == null || !matchWorldEnabled) {
            return false;
        }
        int targetCount = targetPrewarmedMatchWorldCount(type);
        if (targetCount <= 0) {
            return false;
        }
        int inProgressCount = prewarmInProgress.contains(type) ? 1 : 0;
        int reservedCount = prewarmedMatchWorldCount(type) + detachedPrewarmedMatchWorldCount(type) + inProgressCount;
        return reservedCount < targetCount;
    }

    private boolean hasEnoughCompletedPrewarmedMatchWorlds(QueueType type) {
        int targetCount = targetPrewarmedMatchWorldCount(type);
        if (targetCount <= 0) {
            return true;
        }
        int completedCount = prewarmedMatchWorldCount(type) + detachedPrewarmedMatchWorldCount(type);
        return completedCount >= targetCount;
    }

