    private String rootMatchWorldName(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return null;
        }
        String linkedRoot = matchWorldService.linkedRoot(worldName);
        if (linkedRoot != null && !linkedRoot.isBlank()) {
            return linkedRoot;
        }
        if (worldName.endsWith(MATCH_NETHER_WORLD_SUFFIX)) {
            String candidate = worldName.substring(0, worldName.length() - MATCH_NETHER_WORLD_SUFFIX.length());
            if (managedMatchWorldTypes.containsKey(candidate)
                || managedMatchWorlds.contains(candidate)
                || isActiveMatchWorldValue(candidate)
                || brMatchWorlds.contains(candidate)) {
                return candidate;
            }
        }
        return worldName;
    }

    private boolean isSameMatchSessionWorld(String firstWorldName, String secondWorldName) {
        String firstRoot = rootMatchWorldName(firstWorldName);
        String secondRoot = rootMatchWorldName(secondWorldName);
        return firstRoot != null && firstRoot.equals(secondRoot);
    }

    private boolean isLinkedNetherMatchWorld(String worldName) {
        String root = rootMatchWorldName(worldName);
        return root != null && !root.equals(worldName);
    }

    private void registerLinkedNetherWorld(String rootWorldName, String netherWorldName) {
        matchWorldService.registerLinkedNether(rootWorldName, netherWorldName);
    }

    private void unregisterLinkedNetherWorld(String worldName) {
        matchWorldService.unregisterLinkedNether(rootMatchWorldName(worldName), worldName,
            isLinkedNetherMatchWorld(worldName));
    }

    private String linkedNetherWorldForRoot(String rootWorldName) {
        if (rootWorldName == null || rootWorldName.isBlank()) {
            return null;
        }
        String mapped = matchWorldService.mappedNether(rootWorldName);
        if (mapped != null && !mapped.isBlank()) {
            return mapped;
        }
        String derived = linkedNetherWorldName(rootWorldName);
        if (derived != null && (Bukkit.getWorld(derived) != null
            || Bukkit.getWorldContainer().toPath().resolve(derived).toFile().exists())) {
            return derived;
        }
        return null;
    }

    public List<String> managedMatchWorldCommandTargets() {
        LinkedHashSet<String> names = new LinkedHashSet<>();
        names.addAll(allActiveMatchWorlds());
        for (QueueType type : QueueType.values()) {
            names.addAll(prewarmedMatchWorldsFor(type));
        }
        names.addAll(managedMatchWorlds);
        names.removeIf(name -> name == null || name.isBlank());
        return new ArrayList<>(names);
    }

    public String resolveManagedMatchWorldName(String rawWorldName) {
        if (rawWorldName == null || rawWorldName.isBlank()) {
            return null;
        }
        String trimmed = rawWorldName.trim();
        for (String candidate : managedMatchWorldCommandTargets()) {
            if (candidate.equals(trimmed) || candidate.equalsIgnoreCase(trimmed)) {
                return candidate;
            }
        }

        String canonical = canonicalizeMatchWorldCommandName(trimmed);
        if (!canonical.equals(trimmed)) {
            for (String candidate : managedMatchWorldCommandTargets()) {
                if (candidate.equals(canonical) || candidate.equalsIgnoreCase(canonical)) {
                    return candidate;
                }
            }
        }
        return null;
    }

    public int scheduledHungerGamesKothRemainingSeconds(String rawWorldName) {
        String worldName = resolveManagedMatchWorldName(rawWorldName);
        if (worldName == null || !isHungerGamesMatchWorldName(worldName)) {
            return -1;
        }
        Long scheduledAt = hungerGamesKothStartAtMs.get(worldName);
        if (scheduledAt == null) {
            return -1;
        }
        long now = System.currentTimeMillis();
        return (int) Math.max(0L, (scheduledAt - now + 999L) / 1000L);
    }

    public MatchKothScheduleResult adjustScheduledMatchKoth(String rawWorldName, int deltaSeconds) {
        String worldName = resolveManagedMatchWorldName(rawWorldName);
        if (worldName == null) {
            return MatchKothScheduleResult.INVALID_WORLD;
        }
        if (!isHungerGamesMatchWorldName(worldName)) {
            return MatchKothScheduleResult.NO_SCHEDULED_KOTH;
        }
        Long scheduledAt = hungerGamesKothStartAtMs.get(worldName);
        if (scheduledAt == null) {
            return MatchKothScheduleResult.NO_SCHEDULED_KOTH;
        }
        long now = System.currentTimeMillis();
        long adjustedAt = scheduledAt + (deltaSeconds * 1000L);
        if (adjustedAt <= now + 250L) {
            if (scheduleHungerGamesKothWithDelaySeconds(worldName, 0)) {
                return MatchKothScheduleResult.STARTED_NOW;
            }
            return MatchKothScheduleResult.NO_SCHEDULED_KOTH;
        }
        int adjustedDelaySeconds = (int) Math.max(1L, (adjustedAt - now + 999L) / 1000L);
        if (!scheduleHungerGamesKothWithDelaySeconds(worldName, adjustedDelaySeconds)) {
            return MatchKothScheduleResult.NO_SCHEDULED_KOTH;
        }
        return MatchKothScheduleResult.UPDATED;
    }

    public MatchKothScheduleResult startScheduledMatchKothNow(String rawWorldName) {
        String worldName = resolveManagedMatchWorldName(rawWorldName);
        if (worldName == null) {
            return MatchKothScheduleResult.INVALID_WORLD;
        }
        if (!isHungerGamesMatchWorldName(worldName)) {
            return MatchKothScheduleResult.NO_SCHEDULED_KOTH;
        }
        if (!hungerGamesKothStartAtMs.containsKey(worldName)) {
            return MatchKothScheduleResult.NO_SCHEDULED_KOTH;
        }
        if (!scheduleHungerGamesKothWithDelaySeconds(worldName, 0)) {
            return MatchKothScheduleResult.NO_SCHEDULED_KOTH;
        }
        return MatchKothScheduleResult.STARTED_NOW;
    }

    private String canonicalizeMatchWorldCommandName(String rawWorldName) {
        if (rawWorldName == null || rawWorldName.isBlank()) {
            return "";
        }
        String trimmed = rawWorldName.trim();
        String lower = trimmed.toLowerCase(Locale.ROOT);
        if (lower.startsWith("hg-match-")) {
            return HUNGER_GAMES_WORLD_NAME_PREFIX + trimmed.substring("hg-match-".length());
        }
        if (lower.startsWith("br-match-")) {
            return BATTLE_ROYALE_WORLD_NAME_PREFIX + trimmed.substring("br-match-".length());
        }
        if (lower.startsWith("hg-world-")) {
            return HUNGER_GAMES_WORLD_NAME_PREFIX + trimmed.substring("hg-world-".length());
        }
        if (lower.startsWith("br-world-")) {
            return BATTLE_ROYALE_WORLD_NAME_PREFIX + trimmed.substring("br-world-".length());
        }
        return trimmed;
    }

    private boolean looksLikeHungerGamesWorldName(String worldName) {
        return worldName.regionMatches(true, 0, HUNGER_GAMES_WORLD_NAME_PREFIX, 0, HUNGER_GAMES_WORLD_NAME_PREFIX.length());
    }

    private void scheduleHungerGamesKoth(String worldName) {
        scheduleHungerGamesKothWithDelaySeconds(worldName, hungerGamesKothDelaySeconds);
    }

    private void scheduleHungerGamesKoth(String worldName, int playerCount) {
        int delaySeconds = scaledHungerGamesKothDelaySeconds(playerCount);
        plugin.getLogger().info("[Queue] Scheduling HG KOTH in " + worldName + " after "
            + delaySeconds + "s for " + Math.max(0, playerCount) + " player(s).");
        scheduleHungerGamesKothWithDelaySeconds(worldName, delaySeconds);
    }

    private boolean scheduleHungerGamesKothWithDelaySeconds(String worldName, int delaySeconds) {
        cancelHungerGamesKothStart(worldName);
        if (worldName == null || worldName.isBlank() || kothService == null) {
            return false;
        }
        long delayTicks = Math.max(1L, Math.max(0, delaySeconds) * 20L);
        hungerGamesKothStartAtMs.put(worldName, System.currentTimeMillis() + (delayTicks * 50L));
        BukkitTask task = Bukkit.getScheduler().runTaskLater(plugin, () -> {
            hungerGamesKothStartTasks.remove(worldName);
            hungerGamesKothStartAtMs.remove(worldName);
            if (!hasLiveHungerGamesSession(worldName)) {
                return;
            }
            World world = Bukkit.getWorld(worldName);
            if (world == null) {
                return;
            }
            Location kothLocation = findHungerGamesKothLocation(world);
            if (kothLocation == null) {
                plugin.getLogger().warning("[Queue] Failed to find a valid HG KOTH location in " + worldName + ".");
                return;
            }
            int kothSize = hungerGamesKothSizeForWorld(worldName);
            KothService.StartResult result = kothService.startRuntimeEvent(
                kothLocation,
                0,
                hungerGamesKothCaptureSeconds,
                kothSize,
                kothSize,
                HUNGER_GAMES_KOTH_MIN_Y_OFFSET,
                HUNGER_GAMES_KOTH_MAX_Y_OFFSET
            );
            if (result != KothService.StartResult.STARTED) {
                plugin.getLogger().warning("[Queue] Failed to start HG KOTH in " + worldName + " (" + result + ").");
                return;
            }
            plugin.getLogger().info("[Queue] Started HG KOTH in " + worldName + " at "
                + kothLocation.getBlockX() + "," + kothLocation.getBlockY() + "," + kothLocation.getBlockZ() + ".");
        }, delayTicks);
        hungerGamesKothStartTasks.put(worldName, task);
        return true;
    }

    private void scheduleHungerGamesChestRefill(String worldName, int playerCount) {
        cancelHungerGamesChestRefill(worldName);
        if (worldName == null || worldName.isBlank() || menuService == null) {
            return;
        }
        HungerGamesLootPlan lootPlan = hungerGamesLootPlan(worldName);
        if (lootPlan.refillTableIds().isEmpty() || hungerGamesChestRefillFillRatio <= 0.0D) {
            return;
        }
        int delaySeconds = scaledHungerGamesChestRefillDelaySeconds(playerCount);
        hungerGamesChestRefillCompleted.remove(worldName);
        plugin.getLogger().info("[Queue] Scheduling HG chest refill in " + worldName + " after "
            + delaySeconds + "s for " + Math.max(0, playerCount) + " player(s).");
        long delayTicks = Math.max(1L, delaySeconds * 20L);
        hungerGamesChestRefillAtMs.put(worldName, System.currentTimeMillis() + (delayTicks * 50L));
        hungerGamesChestRefillDelaySecondsByWorld.put(worldName, delaySeconds);
        List<BukkitTask> warningTasks = new ArrayList<>();
        hungerGamesChestRefillWarningTasks.put(worldName, warningTasks);
        for (int warningSeconds : List.of(60, 30, 10, 5, 4, 3, 2, 1)) {
            scheduleHungerGamesRefillWarning(worldName, warningTasks, warningSeconds, delaySeconds);
        }
        BukkitTask task = Bukkit.getScheduler().runTaskLater(plugin, () -> {
            hungerGamesChestRefillTasks.remove(worldName);
            hungerGamesChestRefillWarningTasks.remove(worldName);
            hungerGamesChestRefillAtMs.remove(worldName);
            hungerGamesChestRefillDelaySecondsByWorld.remove(worldName);
            if (!hasLiveHungerGamesSession(worldName)) {
                return;
            }
            World world = Bukkit.getWorld(worldName);
            if (world == null) {
                return;
            }
            completeHungerGamesChestRefill(world, lootPlan);
        }, delayTicks);
        hungerGamesChestRefillTasks.put(worldName, task);
    }

    private int scaledHungerGamesKothDelaySeconds(int playerCount) {
        return Math.max(0, hungerGamesKothDelaySeconds);
    }

    private int scaledHungerGamesChestRefillDelaySeconds(int playerCount) {
        if (playerCount <= 10) {
            return 180;
        }
        if (playerCount <= 20) {
            return 210;
        }
        return 240;
    }

    private void scheduleHungerGamesRefillWarning(String worldName, List<BukkitTask> tasks, int warningSeconds, int delaySeconds) {
        if (worldName == null || worldName.isBlank() || tasks == null || warningSeconds <= 0
            || warningSeconds >= delaySeconds) {
            return;
        }
        long delayTicks = Math.max(1L, (delaySeconds - warningSeconds) * 20L);
        BukkitTask task = Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (!hasLiveHungerGamesSession(worldName)) {
                return;
            }
            World world = Bukkit.getWorld(worldName);
            if (world == null) {
                return;
            }
            String remaining = warningSeconds >= 60 ? "1:00"
                : warningSeconds >= 10 ? "0:" + warningSeconds : Integer.toString(warningSeconds);
            sendHungerGamesRefillActionBar(world, "Chest refill in " + remaining);
        }, delayTicks);
        tasks.add(task);
    }

    private void completeHungerGamesChestRefill(World world, HungerGamesLootPlan lootPlan) {
        if (world == null || lootPlan == null || !hungerGamesChestRefillCompleted.add(world.getName())) {
            return;
        }
        sendHungerGamesRefillActionBar(world, "Chests have been refilled!");
        for (Player player : world.getPlayers()) {
            player.playSound(player.getLocation(), Sound.ENTITY_PLAYER_LEVELUP, 1.0F, 1.0F);
        }
        refillHungerGamesMapLoot(world, lootPlan);
    }

    private void sendHungerGamesRefillActionBar(World world, String message) {
        if (world == null || message == null || message.isBlank()) {
            return;
        }
        Component actionBar = Component.text(message, net.kyori.adventure.text.format.NamedTextColor.GOLD);
        for (Player player : world.getPlayers()) {
            if (player.isOnline()) {
                player.sendActionBar(actionBar);
            }
        }
    }

    public void startHungerGamesRefillEarly(Player requester) {
        String worldName = requester == null ? null : rootMatchWorldName(requester.getWorld().getName());
        if (worldName == null || !hasLiveHungerGamesSession(worldName)) {
            if (requester != null) requester.sendMessage(ChatColor.RED + "You are not in an active Hunger Games match.");
            return;
        }
        if (hungerGamesChestRefillCompleted.contains(worldName)) {
            requester.sendMessage(ChatColor.YELLOW + "This match has already refilled its chests.");
            return;
        }
        HungerGamesLootPlan lootPlan = hungerGamesLootPlan(worldName);
        cancelHungerGamesChestRefill(worldName);
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            requester.sendMessage(ChatColor.RED + "The active Hunger Games world is unavailable.");
            return;
        }
        completeHungerGamesChestRefill(world, lootPlan);
        requester.sendMessage(ChatColor.GREEN + "Started the normal Hunger Games refill immediately.");
    }

    private void scheduleCornucopiaRefill(String worldName) {
        cancelCornucopiaRefill(worldName);
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null || rootWorldName.isBlank() || managedLootService == null) {
            return;
        }
        List<BukkitTask> tasks = new ArrayList<>();
        cornucopiaRefillTasks.put(rootWorldName, tasks);
        scheduleCornucopiaRefillAnnouncement(rootWorldName, tasks, BR_CORNUCOPIA_REFILL_WARNING_30_SECONDS);
        scheduleCornucopiaRefillAnnouncement(rootWorldName, tasks, BR_CORNUCOPIA_REFILL_WARNING_10_SECONDS);
        long refillDelayTicks = Math.max(1L, BR_CORNUCOPIA_REFILL_DELAY_SECONDS * 20L);
        BukkitTask refillTask = Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (!hasLiveBattleRoyaleMatchSession(rootWorldName)) {
                cornucopiaRefillTasks.remove(rootWorldName);
                return;
            }
            World world = Bukkit.getWorld(rootWorldName);
            if (world == null) {
                cornucopiaRefillTasks.remove(rootWorldName);
                return;
            }
            refillCornucopiaLoot(world);
            broadcastMatchWorldMessage(rootWorldName, ChatColor.GOLD + "Cornucopia refilled.");
            cornucopiaRefillTasks.remove(rootWorldName);
        }, refillDelayTicks);
        tasks.add(refillTask);
    }

    private void scheduleCornucopiaRefillAnnouncement(String worldName, List<BukkitTask> tasks, int warningSeconds) {
        if (worldName == null || worldName.isBlank() || tasks == null || warningSeconds <= 0
            || warningSeconds >= BR_CORNUCOPIA_REFILL_DELAY_SECONDS) {
            return;
        }
        long delayTicks = Math.max(1L, (BR_CORNUCOPIA_REFILL_DELAY_SECONDS - warningSeconds) * 20L);
        BukkitTask task = Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (!hasLiveBattleRoyaleMatchSession(worldName)) {
                return;
            }
            broadcastMatchWorldMessage(
                worldName,
                ChatColor.YELLOW + "Cornucopia refill in " + warningSeconds + " seconds."
            );
        }, delayTicks);
        tasks.add(task);
    }

    private void refillCornucopiaLoot(World world) {
        if (world == null || managedLootService == null) {
            return;
        }
        String lootGroup = cornucopiaLootGroup(world);
        List<Block> containers = managedLootService.collectManagedContainers(
            world,
            ManagedLootService.SOURCE_CORNUCOPIA,
            lootGroup
        );
        if (containers.isEmpty()) {
            plugin.getLogger().warning("[Cornucopia] No managed containers found to refill in " + world.getName() + ".");
            return;
        }
        int filled = 0;
        int specialFilled = 0;
        int totalGenerated = 0;
        for (Block block : containers) {
            String tableId = ThreadLocalRandom.current().nextDouble() < BR_CORNUCOPIA_SPECIAL_REFILL_CHANCE
                ? BR_CORNUCOPIA_SPECIAL_LOOT_TABLE_ID
                : BR_CORNUCOPIA_REFILL_LOOT_TABLE_ID;
            int generated = managedLootService.populateManagedContainer(
                block,
                tableId,
                ManagedLootService.SOURCE_CORNUCOPIA,
                lootGroup
            );
            if (generated > 0) {
                filled++;
                totalGenerated += generated;
                if (BR_CORNUCOPIA_SPECIAL_LOOT_TABLE_ID.equals(tableId)) {
                    specialFilled++;
                }
            }
        }
        plugin.getLogger().info("[Cornucopia] Refilled " + filled + "/" + containers.size()
            + " containers in " + world.getName() + " using " + BR_CORNUCOPIA_REFILL_LOOT_TABLE_ID
            + " with " + specialFilled + " special rolls. Generated stacks=" + totalGenerated + ".");
    }

    private void cancelCornucopiaRefill(String worldName) {
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null || rootWorldName.isBlank()) {
            return;
        }
        List<BukkitTask> tasks = cornucopiaRefillTasks.remove(rootWorldName);
        if (tasks == null) {
            return;
        }
        for (BukkitTask task : tasks) {
            if (task != null) {
                task.cancel();
            }
        }
    }

    private boolean hasLiveBattleRoyaleMatchSession(String worldName) {
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null || rootWorldName.isBlank() || endingMatchWorlds.contains(rootWorldName)) {
            return false;
        }
        QueueType type = managedMatchWorldTypes.get(rootWorldName);
        if (type != QueueType.SOLO && type != QueueType.DUO) {
            return false;
        }
        if (!activeMatchWorldsFor(type).contains(rootWorldName)) {
            return false;
        }
        return !activePlayersInWorld(rootWorldName).isEmpty();
    }

    private void broadcastMatchWorldMessage(String worldName, String message) {
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null || rootWorldName.isBlank() || message == null || message.isBlank()) {
            return;
        }
        for (Player player : Bukkit.getOnlinePlayers()) {
            if (player == null || !player.isOnline()) {
                continue;
            }
            World playerWorld = player.getWorld();
            if (playerWorld == null || !isSameMatchSessionWorld(rootWorldName, playerWorld.getName())) {
                continue;
            }
            player.sendMessage(message);
        }
    }

    private void notifyWorldPlayers(World world, String title, String subtitle) {
        if (world == null) {
            return;
        }
        for (Player player : world.getPlayers()) {
            if (player == null || !player.isOnline()) {
                continue;
            }
            player.sendTitle(title == null ? "" : title, subtitle == null ? "" : subtitle, 5, 40, 10);
            player.playSound(player.getLocation(), Sound.ENTITY_PLAYER_LEVELUP, 1.0F, 1.0F);
        }
    }

    private void cancelHungerGamesKothStart(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return;
        }
        BukkitTask task = hungerGamesKothStartTasks.remove(worldName);
        hungerGamesKothStartAtMs.remove(worldName);
        if (task != null) {
            task.cancel();
        }
    }

    private void cancelHungerGamesChestRefill(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return;
        }
        BukkitTask task = hungerGamesChestRefillTasks.remove(worldName);
        List<BukkitTask> warningTasks = hungerGamesChestRefillWarningTasks.remove(worldName);
        hungerGamesChestRefillAtMs.remove(worldName);
        hungerGamesChestRefillDelaySecondsByWorld.remove(worldName);
        if (task != null) {
            task.cancel();
        }
        if (warningTasks != null) {
            for (BukkitTask warningTask : warningTasks) {
                if (warningTask != null) {
                    warningTask.cancel();
                }
            }
        }
    }

    private Location findHungerGamesKothLocation(World world) {
        return selectHungerGamesKoth(world).location();
    }

    /**
     * The single HG KOTH selection path used by both real matches and
     * {@code /admin koth test}. Returns the chosen location plus diagnostics
     * (selection source + lodestone marker stats) so the test command can
     * report on exactly what real matches would pick.
     */
    private KothSelection selectHungerGamesKoth(World world) {
        if (world == null) {
            return new KothSelection(null, "none", 0, 0, List.of());
        }
        MarkerScan scan = scanHungerGamesKothMarkers(world);
        if (scan.chosen() != null) {
            plugin.getLogger().info("[Queue] Using HG KOTH lodestone marker at "
                + scan.chosen().getBlockX() + "," + scan.chosen().getBlockY() + "," + scan.chosen().getBlockZ()
                + " in " + world.getName() + ".");
            return new KothSelection(scan.chosen(), "lodestone", scan.found(), scan.valid(), scan.rejected());
        }
        List<HungerGamesStrongPoint> strongPoints = new ArrayList<>(hungerGamesKothStrongPoints);
        Collections.shuffle(strongPoints);
        for (HungerGamesStrongPoint strongPoint : strongPoints) {
            Location candidate = buildHungerGamesKothLocation(world, strongPoint.x(), strongPoint.z());
            if (candidate != null) {
                plugin.getLogger().info("[Queue] Using HG KOTH strong point "
                    + strongPoint.displayName() + " at " + strongPoint.x() + "," + strongPoint.z()
                    + " in " + world.getName() + ".");
                return new KothSelection(candidate, "strong point: " + strongPoint.displayName(),
                    scan.found(), scan.valid(), scan.rejected());
            }
        }
        SearchBounds bounds = hungerGamesKothSearchBounds(world);
        for (int attempt = 0; attempt < HUNGER_GAMES_KOTH_SEARCH_ATTEMPTS; attempt++) {
            int x = bounds.randomX();
            int z = bounds.randomZ();
            Location candidate = buildHungerGamesKothLocation(world, x, z);
            if (candidate != null) {
                return new KothSelection(candidate, "random", scan.found(), scan.valid(), scan.rejected());
            }
        }
        for (int x = bounds.minX(); x <= bounds.maxX(); x += 4) {
            for (int z = bounds.minZ(); z <= bounds.maxZ(); z += 4) {
                Location candidate = buildHungerGamesKothLocation(world, x, z);
                if (candidate != null) {
                    return new KothSelection(candidate, "fallback", scan.found(), scan.valid(), scan.rejected());
                }
            }
        }
        if (!strongPoints.isEmpty()) {
            plugin.getLogger().warning("[Queue] No configured HG KOTH strong points were valid in "
                + world.getName() + ", and the fallback search also failed.");
        }
        return new KothSelection(null, "none", scan.found(), scan.valid(), scan.rejected());
    }

    public void runKothSelectionTest(Player admin, int count) {
        if (admin == null) {
            return;
        }
        if (kothService == null) {
            admin.sendMessage(HydraIcons.EXCLAMATION_RED + " " + ChatColor.RED + "KOTH service is unavailable right now.");
            return;
        }
        World world = admin.getWorld();
        if (world == null) {
            admin.sendMessage(HydraIcons.EXCLAMATION_RED + " " + ChatColor.RED + "Could not resolve your current world.");
            return;
        }
        int total = Math.max(1, Math.min(count, 10));
        admin.sendMessage(HydraIcons.EXCLAMATION_ORANGE + " " + ChatColor.YELLOW + "Running KOTH selection test x" + total
            + ChatColor.GRAY + " in " + ChatColor.WHITE + world.getName()
            + (total > 1 ? ChatColor.GRAY + " (5s apart)" : "") + ChatColor.GRAY + "...");
        runKothTestIteration(admin, world.getName(), 1, total, new ArrayList<>());
    }

    private void runKothTestIteration(Player admin, String worldName, int index, int total, List<KothTestResult> results) {
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            if (admin.isOnline()) {
                admin.sendMessage(HydraIcons.EXCLAMATION_RED + " " + ChatColor.RED + "World " + worldName
                    + " is no longer loaded; aborting KOTH test.");
            }
            sendKothTestSummary(admin, worldName, results);
            return;
        }
        // Cleanup any KOTH currently active in this world (real or a prior test) before starting.
        boolean cleanedPrevious = kothService.stopEventInWorld(worldName);
        KothSelection selection = selectHungerGamesKoth(world);
        KothService.StartResult startResult = null;
        if (selection.location() != null) {
            int kothSize = hungerGamesKothSizeForWorld(worldName);
            startResult = kothService.startRuntimeEvent(
                selection.location(),
                0,
                hungerGamesKothCaptureSeconds,
                kothSize,
                kothSize,
                HUNGER_GAMES_KOTH_MIN_Y_OFFSET,
                HUNGER_GAMES_KOTH_MAX_Y_OFFSET
            );
        }
        results.add(new KothTestResult(index, selection, startResult, cleanedPrevious));
        if (admin.isOnline()) {
            admin.sendMessage(HydraIcons.EXCLAMATION + " " + ChatColor.GRAY + "Test " + index + "/" + total + ": "
                + kothTestResultLine(selection, startResult));
        }
        if (index >= total) {
            sendKothTestSummary(admin, worldName, results);
            return;
        }
        Bukkit.getScheduler().runTaskLater(plugin,
            () -> runKothTestIteration(admin, worldName, index + 1, total, results), 100L);
    }

    private String kothTestResultLine(KothSelection selection, KothService.StartResult startResult) {
        if (selection.location() == null) {
            return ChatColor.RED + "no valid location" + ChatColor.GRAY + " (source: " + selection.source() + ")";
        }
        Location loc = selection.location();
        String coord = loc.getBlockX() + ", " + loc.getBlockY() + ", " + loc.getBlockZ();
        String status = startResult == KothService.StartResult.STARTED
            ? ChatColor.GREEN + "STARTED"
            : ChatColor.RED + String.valueOf(startResult);
        return ChatColor.WHITE + coord + ChatColor.GRAY + " via " + ChatColor.AQUA + selection.source()
            + ChatColor.GRAY + " [" + status + ChatColor.GRAY + "]";
    }

    private void sendKothTestSummary(Player admin, String worldName, List<KothTestResult> results) {
        if (admin == null || !admin.isOnline()) {
            return;
        }
        String mapKey = normalizeHungerGamesMapKey(hungerGamesMapKeysByWorld.get(worldName));
        KothSelection last = results.isEmpty() ? null : results.get(results.size() - 1).selection();
        int found = last == null ? 0 : last.lodestoneFound();
        int valid = last == null ? 0 : last.lodestoneValid();
        List<String> rejected = last == null ? List.of() : last.rejected();
        admin.sendMessage(ChatColor.GOLD + "" + ChatColor.BOLD + "KOTH Selection Test Summary");
        admin.sendMessage(ChatColor.GRAY + "World: " + ChatColor.WHITE + worldName);
        admin.sendMessage(ChatColor.GRAY + "Map: " + ChatColor.WHITE
            + (mapKey == null || mapKey.isBlank() ? "unknown" : mapKey));
        admin.sendMessage(ChatColor.GRAY + "Tests run: " + ChatColor.WHITE + results.size());
        admin.sendMessage(ChatColor.GRAY + "Lodestone markers found: " + ChatColor.WHITE + found
            + ChatColor.GRAY + ", valid: " + ChatColor.WHITE + valid);
        if (rejected.isEmpty()) {
            admin.sendMessage(ChatColor.GRAY + "Rejected markers: " + ChatColor.WHITE + "none");
        } else {
            admin.sendMessage(ChatColor.GRAY + "Rejected markers:");
            for (String reason : rejected) {
                admin.sendMessage(ChatColor.DARK_GRAY + " - " + ChatColor.RED + reason);
            }
        }
        for (KothTestResult result : results) {
            admin.sendMessage(ChatColor.GRAY + " #" + result.index() + ": "
                + kothTestResultLine(result.selection(), result.startResult()));
        }
    }

    private Location buildHungerGamesKothLocation(World world, int x, int z) {
        world.getChunkAt(x >> 4, z >> 4);
        int y = world.getHighestBlockYAt(x, z, HeightMap.MOTION_BLOCKING_NO_LEAVES) + 1;
        if (y <= world.getMinHeight()) {
            return null;
        }
        if (!hasSkyLightAt(world, x, y, z)) {
            return null;
        }
        if (!isValidHungerGamesKothArea(world, x, y, z)) {
            return null;
        }
        return new Location(world, x + 0.5D, y, z + 0.5D);
    }

    private int hungerGamesKothSizeForWorld(String worldName) {
        String mapKey = normalizeHungerGamesMapKey(hungerGamesMapKeysByWorld.get(worldName));
        if (WILD_WEST_HUNGER_GAMES_MAP_KEY.equals(mapKey)) {
            return HUNGER_GAMES_KOTH_WILD_WEST_SIZE;
        }
        return HUNGER_GAMES_KOTH_DEFAULT_SIZE;
    }

    private boolean isValidHungerGamesKothArea(World world, int centerX, int centerY, int centerZ) {
        if (!isValidMatchSpawnColumn(world, centerX, centerY, centerZ) || !hasSkyLightAt(world, centerX, centerY, centerZ)) {
            return false;
        }
        for (int dx = -2; dx <= 2; dx++) {
            for (int dz = -2; dz <= 2; dz++) {
                if ((dx * dx) + (dz * dz) > 6.25D) {
                    continue;
                }
                int sampleX = centerX + dx;
                int sampleZ = centerZ + dz;
                world.getChunkAt(sampleX >> 4, sampleZ >> 4);
                int sampleY = world.getHighestBlockYAt(sampleX, sampleZ, HeightMap.MOTION_BLOCKING_NO_LEAVES) + 1;
                if (sampleY <= world.getMinHeight()) {
                    return false;
                }
                if (!isValidMatchSpawnColumn(world, sampleX, sampleY, sampleZ) || !hasSkyLightAt(world, sampleX, sampleY, sampleZ)) {
                    return false;
                }
            }
        }
        return true;
    }

    private SearchBounds hungerGamesKothSearchBounds(World world) {
        HungerGamesMapDefinition mapDefinition = world == null
            ? null
            : hungerGamesMapDefinitionByKey(hungerGamesMapKeysByWorld.get(world.getName()));
        if (mapDefinition != null && WILD_WEST_HUNGER_GAMES_MAP_KEY.equals(mapDefinition.key())) {
            int minX = (int) Math.floor(WILD_WEST_BORDER_MIN_X) + HUNGER_GAMES_KOTH_EDGE_BUFFER;
            int maxX = (int) Math.ceil(WILD_WEST_BORDER_MAX_X) - HUNGER_GAMES_KOTH_EDGE_BUFFER;
            int minZ = (int) Math.floor(WILD_WEST_BORDER_MIN_Z) + HUNGER_GAMES_KOTH_EDGE_BUFFER;
            int maxZ = (int) Math.ceil(WILD_WEST_BORDER_MAX_Z) - HUNGER_GAMES_KOTH_EDGE_BUFFER;
            return new SearchBounds(minX, maxX, minZ, maxZ);
        }
        String structureId = mapDefinition == null ? hungerGamesStructureId : mapDefinition.structureId();
        Structure structure = resolveHydraStructure(structureId);
        if (structure != null) {
            BlockVector size = structure.getSize();
            int pasteX = -Math.floorDiv(Math.max(1, size.getBlockX()), 2);
            int pasteZ = -Math.floorDiv(Math.max(1, size.getBlockZ()), 2);
            int minX = pasteX + HUNGER_GAMES_KOTH_EDGE_BUFFER;
            int maxX = pasteX + Math.max(0, size.getBlockX() - 1) - HUNGER_GAMES_KOTH_EDGE_BUFFER;
            int minZ = pasteZ + HUNGER_GAMES_KOTH_EDGE_BUFFER;
            int maxZ = pasteZ + Math.max(0, size.getBlockZ() - 1) - HUNGER_GAMES_KOTH_EDGE_BUFFER;
            if (minX <= maxX && minZ <= maxZ) {
                return new SearchBounds(minX, maxX, minZ, maxZ);
            }
        }
        int radius = Math.max(4, hungerGamesKothRandomRadius);
        return new SearchBounds(-radius, radius, -radius, radius);
    }

    private boolean hasSkyLightAt(World world, int x, int y, int z) {
        return world != null && world.getBlockAt(x, y, z).getLightFromSky() > 0;
    }

    private boolean isMatchWorldPreparationBusy(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return false;
        }
        return !isBrWorldPreparationReady(worldName)
            || asyncZipPlacementInProgress.contains(worldName)
            || cornucopiaPlacementInProgress.contains(worldName);
    }

    private Location fakePcsPlaneStartLocation(World world, int seatIndex, int totalSeats) {
        if (world == null) {
            return null;
        }
        FakePcsPlaneRoute route = fakePcsPlaneRoute(world);
        double progress = 0.04D;
        Location start = route.pointAt(progress);
        Vector side = route.side();
        double centeredIndex = seatIndex - ((Math.max(1, totalSeats) - 1) / 2.0D);
        double seatOffset = centeredIndex * FAKE_PCS_PLANE_SEAT_SPACING;
        start.add(side.clone().multiply(seatOffset));
        start.setYaw(route.yaw());
        start.setPitch(0.0F);
        return start;
    }

    private FakePcsPlaneRoute fakePcsPlaneRoute(World world) {
        WorldBorder border = world.getWorldBorder();
        double halfSize = Math.max(200.0D, (border.getSize() * 0.5D) + FAKE_PCS_PLANE_BORDER_PADDING);
        double centerX = border.getCenter().getX();
        double centerZ = border.getCenter().getZ();
        double y = Math.min(world.getMaxHeight() - 12.0D, Math.max(96.0D, FAKE_PCS_PLANE_ALTITUDE));
        return fakePcsPlaneRoute(world, centerX, centerZ, halfSize, y);
    }

    private FakePcsPlaneRoute fakePcsPlaneRoute(World world, double centerX, double centerZ, double halfSpan, double y) {
        Location start = new Location(world, centerX - halfSpan, y, centerZ);
        Location end = new Location(world, centerX + halfSpan, y, centerZ);
        Vector direction = end.toVector().subtract(start.toVector()).normalize();
        Vector side = new Vector(-direction.getZ(), 0.0D, direction.getX()).normalize();
        float yaw = locationYawFromDirection(direction);
        return new FakePcsPlaneRoute(start, end, direction, side, yaw);
    }

    private float locationYawFromDirection(Vector direction) {
        if (direction == null || direction.lengthSquared() <= 0.000001D) {
            return 0.0F;
        }
        return (float) Math.toDegrees(Math.atan2(-direction.getX(), direction.getZ()));
    }

    private void beginFakePcsPlaneRide(Player player, World world, int seatIndex, int totalSeats) {
        if (player == null || world == null) {
            return;
        }
        clearFakePcsState(player);
        FakePcsPlaneRoute route = fakePcsPlaneRoute(world);
        double centeredIndex = seatIndex - ((Math.max(1, totalSeats) - 1) / 2.0D);
        double seatOffset = centeredIndex * FAKE_PCS_PLANE_SEAT_SPACING;
        FakePcsPlayerState state = new FakePcsPlayerState(
            world.getName(),
            route,
            seatOffset,
            Bukkit.getCurrentTick(),
            (int) FAKE_PCS_PLANE_DURATION_TICKS,
            FakePcsPhase.IN_PLANE,
            -1,
            -20
        );
        fakePcsStates.put(player.getUniqueId(), state);
        player.setAllowFlight(true);
        player.setFlying(false);
        player.setInvulnerable(true);
        player.setNoDamageTicks(Integer.MAX_VALUE / 4);
        player.setFallDistance(0.0F);
        Location rideLocation = route.pointAt(0.04D).add(route.side().clone().multiply(seatOffset));
        rideLocation.setYaw(route.yaw());
        rideLocation.setPitch(0.0F);
        player.teleport(rideLocation);
        syncFakePcsPlaneDisplay(world, route, 0.04D);
    }

    public void startPlaneTest(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        World world = player.getWorld();
        double y = Math.min(world.getMaxHeight() - 12.0D, Math.max(player.getLocation().getY() + 32.0D, FAKE_PCS_PLANE_ALTITUDE));
        FakePcsPlaneRoute route = fakePcsPlaneRoute(
            world,
            player.getLocation().getX(),
            player.getLocation().getZ(),
            PLANE_TEST_HALF_SPAN,
            y
        );
        clearFakePcsState(player);
        FakePcsPlayerState state = new FakePcsPlayerState(
            world.getName(),
            route,
            0.0D,
            Bukkit.getCurrentTick(),
            0,
            FakePcsPhase.IN_PLANE,
            -1,
            -20
        );
        player.setAllowFlight(true);
        player.setFlying(false);
        player.setInvulnerable(true);
        player.setNoDamageTicks(Integer.MAX_VALUE / 4);
        player.setFallDistance(0.0F);
        Location rideLocation = route.pointAt(0.04D);
        rideLocation.setYaw(route.yaw());
        rideLocation.setPitch(0.0F);
        player.teleport(rideLocation);
        fakePcsStates.put(player.getUniqueId(), state);
        syncFakePcsPlaneDisplay(world, route, 0.04D);
        player.sendMessage(PREFIX + ChatColor.AQUA + "Plane test started." + ChatColor.GRAY
            + " Press jump to drop.");
        player.playSound(player.getLocation(), Sound.ENTITY_ENDER_DRAGON_FLAP, 0.9F, 1.25F);
    }

    private void syncFakePcsPlaneDisplay(World world, FakePcsPlaneRoute route, double progress) {
        if (world == null || route == null) {
            return;
        }
        String worldName = world.getName();
        UUID displayId = fakePcsPlaneDisplayIds.get(worldName);
        ItemDisplay display = null;
        if (displayId != null) {
            Entity existing = Bukkit.getEntity(displayId);
            if (existing instanceof ItemDisplay itemDisplay && itemDisplay.isValid()
                && itemDisplay.getWorld().equals(world)) {
                display = itemDisplay;
            } else {
                fakePcsPlaneDisplayIds.remove(worldName);
            }
        }
        Location location = route.pointAt(clamp(progress, 0.0D, 0.98D));
        location.add(0.0D, FAKE_PCS_PLANE_MODEL_Y_OFFSET, 0.0D);
        location.setYaw(0.0F);
        location.setPitch(0.0F);
        if (display == null) {
            display = createFakePcsPlaneDisplay(world, location);
            if (display == null) {
                return;
            }
            fakePcsPlaneDisplayIds.put(worldName, display.getUniqueId());
        } else if (display.getLocation().distanceSquared(location) > 0.0001D) {
            display.teleport(location);
        }
        display.setTransformation(fakePcsPlaneTransformation(route));
    }

    private ItemDisplay createFakePcsPlaneDisplay(World world, Location location) {
        if (world == null || location == null) {
            return null;
        }
        ItemDisplay display = (ItemDisplay) world.spawnEntity(location, EntityType.ITEM_DISPLAY);
        display.setGravity(false);
        display.setPersistent(false);
        display.setInvulnerable(true);
        display.setBillboard(Display.Billboard.FIXED);
        display.setInterpolationDelay(0);
        display.setInterpolationDuration(1);
        display.setTeleportDuration(1);
        display.setItemDisplayTransform(ItemDisplay.ItemDisplayTransform.NONE);
        display.setItemStack(createFakePcsPlaneDisplayItem());
        return display;
    }

    private ItemStack createFakePcsPlaneDisplayItem() {
        ItemStack displayItem = new ItemStack(Material.AMETHYST_SHARD);
        ItemMeta meta = displayItem.getItemMeta();
        NamespacedKey modelKey = NamespacedKey.fromString(FAKE_PCS_PLANE_MODEL_ID);
        if (meta == null || modelKey == null) {
            return displayItem;
        }
        meta.setItemModel(modelKey);
        meta.setDisplayName(ChatColor.DARK_AQUA + "PCS Plane");
        displayItem.setItemMeta(meta);
        return displayItem;
    }

    private Transformation fakePcsPlaneTransformation(FakePcsPlaneRoute route) {
        float yaw = route == null ? 0.0F : route.yaw();
        Quaternionf rotation = new Quaternionf().rotateY((float) Math.toRadians(180.0F - yaw));
        return new Transformation(
            new Vector3f(0.0F, 0.0F, 0.0F),
            rotation,
            new Vector3f(
                FAKE_PCS_PLANE_MODEL_SCALE,
                FAKE_PCS_PLANE_MODEL_SCALE,
                FAKE_PCS_PLANE_MODEL_SCALE
            ),
            new Quaternionf()
        );
    }

    private void clearUnusedFakePcsPlaneDisplays() {
        Set<String> activePlaneWorlds = new HashSet<>();
        for (FakePcsPlayerState state : fakePcsStates.values()) {
            if (state != null && state.phase() == FakePcsPhase.IN_PLANE && state.worldName() != null) {
                activePlaneWorlds.add(state.worldName());
            }
        }
        for (String worldName : new ArrayList<>(fakePcsPlaneDisplayIds.keySet())) {
            if (!activePlaneWorlds.contains(worldName)) {
                removeFakePcsPlaneDisplay(worldName);
            }
        }
    }

    private void clearAllFakePcsPlaneDisplays() {
        for (String worldName : new ArrayList<>(fakePcsPlaneDisplayIds.keySet())) {
            removeFakePcsPlaneDisplay(worldName);
        }
    }

    private void removeFakePcsPlaneDisplay(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return;
        }
        UUID displayId = fakePcsPlaneDisplayIds.remove(worldName);
        removeFakePcsDiveDisplayEntity(displayId);
    }

    private void tickFakePcsPlaneRides() {
        if (fakePcsStates.isEmpty()) {
            clearAllFakePcsPlaneDisplays();
            return;
        }
        int nowTick = Bukkit.getCurrentTick();
        for (Map.Entry<UUID, FakePcsPlayerState> entry : new ArrayList<>(fakePcsStates.entrySet())) {
            UUID playerId = entry.getKey();
            FakePcsPlayerState state = entry.getValue();
            Player player = Bukkit.getPlayer(playerId);
            if (player == null || !player.isOnline()) {
                fakePcsStates.remove(playerId);
                continue;
            }
            if (!Objects.equals(player.getWorld().getName(), state.worldName())) {
                fakePcsStates.remove(playerId);
                continue;
            }
            FakePcsPlayerState updated = tickFakePcsPlayer(player, state, nowTick);
            if (updated == null || updated.phase() == FakePcsPhase.LANDED) {
                clearFakePcsState(player);
                continue;
            }
            fakePcsStates.put(playerId, updated);
        }
        clearUnusedFakePcsPlaneDisplays();
    }

    private FakePcsPlayerState tickFakePcsPlayer(Player player, FakePcsPlayerState state, int nowTick) {
        return switch (state.phase()) {
            case IN_PLANE -> tickFakePcsInPlane(player, state, nowTick);
            case JUMPED -> tickFakePcsJumped(player, state, nowTick);
            case GLIDING -> tickFakePcsAirborne(player, state, nowTick);
            case LANDED -> state;
        };
    }

    private FakePcsPlayerState tickFakePcsInPlane(Player player, FakePcsPlayerState state, int nowTick) {
        boolean waitingForManualJump = state.planeDurationTicks() <= 0;
        double progress = waitingForManualJump
            ? 0.0D
            : (nowTick - state.startedTick()) / (double) Math.max(20, state.planeDurationTicks());
        if (!waitingForManualJump && !fakePcsTestingStationaryPlane && progress >= 1.0D) {
            FakePcsPlayerState jumped = launchFakePcsJump(player, state, nowTick);
            player.sendMessage(PREFIX + ChatColor.YELLOW + "Plane route ended. Jumping now.");
            return jumped;
        }
        double clamped = fakePcsTestingStationaryPlane || waitingForManualJump
            ? 0.04D
            : clamp(progress, 0.0D, 0.98D);
        syncFakePcsPlaneDisplay(player.getWorld(), state.route(), clamped);
        Location rideLocation = state.route().pointAt(clamped)
            .add(state.route().side().clone().multiply(state.seatOffset()));
        rideLocation.setYaw(state.route().yaw());
        rideLocation.setPitch(0.0F);
        if (player.getLocation().distanceSquared(rideLocation) > 0.04D) {
            player.teleport(rideLocation);
        } else {
            player.setVelocity(new Vector(0.0D, 0.0D, 0.0D));
        }
        player.setFallDistance(0.0F);
        return state;
    }

    private FakePcsPlayerState tickFakePcsJumped(Player player, FakePcsPlayerState state, int nowTick) {
        player.setFallDistance(0.0F);
        if (isFakePcsLanding(player)) {
            return state.withPhase(FakePcsPhase.LANDED, nowTick);
        }
        if (player.isGliding() || nowTick - state.jumpedTick() >= FAKE_PCS_GLIDE_ENABLE_DELAY_TICKS + 2) {
            return state.withPhase(FakePcsPhase.GLIDING, nowTick);
        }
        return state;
    }

    private FakePcsPlayerState tickFakePcsAirborne(Player player, FakePcsPlayerState state, int nowTick) {
        if (isFakePcsLanding(player)) {
            return state.withPhase(FakePcsPhase.LANDED, nowTick);
        }
        applyFakePcsDiveAnimation(player, false, nowTick);
        applyFakePcsGliderState(player, true);
        if (!player.isGliding()) {
            player.setGliding(true);
        }
        player.addPotionEffect(new PotionEffect(PotionEffectType.SLOW_FALLING, 30, 0, false, false, true));
        if (state.phase() != FakePcsPhase.GLIDING) {
            return state.withPhase(FakePcsPhase.GLIDING, nowTick);
        }
        return state;
    }

    private FakePcsPlayerState launchFakePcsJump(Player player, FakePcsPlayerState state, int nowTick) {
        if (player == null) {
            return state;
        }
        UUID playerId = player.getUniqueId();

        ItemStack originalChestplate = player.getInventory().getChestplate();
        if (!fakePcsOriginalChestplates.containsKey(playerId)) {
            fakePcsOriginalChestplates.put(playerId, originalChestplate == null ? new ItemStack(Material.AIR) : originalChestplate.clone());
        }
        applyFakePcsGliderState(player, true);
        player.addPotionEffect(new PotionEffect(PotionEffectType.SLOW_FALLING, FAKE_PCS_SLOW_FALLING_TICKS, 0, false, false, true));
        player.setAllowFlight(false);
        player.setFlying(false);
        player.setInvulnerable(true);
        player.setFallDistance(0.0F);
        player.updateInventory();

        Vector direction = state.route() == null ? null : state.route().direction();
        Vector baseVector = direction == null ? new Vector(1.0D, 0.0D, 0.0D) : direction.clone();
        if (baseVector.lengthSquared() <= 0.0001D) {
            baseVector = new Vector(1.0D, 0.0D, 0.0D);
        }
        Vector glideVector = baseVector.normalize().multiply(FAKE_PCS_JUMP_FORWARD_SPEED);
        glideVector.setY(FAKE_PCS_JUMP_DOWNWARD_SPEED);
        final Vector launchVector = glideVector.clone();
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            Player current = Bukkit.getPlayer(playerId);
            FakePcsPlayerState currentState = fakePcsStates.get(playerId);
            if (current == null || !current.isOnline() || currentState == null || currentState.phase() != FakePcsPhase.JUMPED) {
                return;
            }
            current.setVelocity(launchVector);
            current.setGliding(true);
            current.setFallDistance(0.0F);
        }, FAKE_PCS_GLIDE_ENABLE_DELAY_TICKS);
        return state.withPhase(FakePcsPhase.JUMPED, nowTick);
    }

    private Location fakePcsDropLocation(Location landing) {
        if (landing == null || landing.getWorld() == null) {
            return landing;
        }
        World world = landing.getWorld();
        double maxY = world.getMaxHeight() - 8.0D;
        double dropY = Math.min(maxY, Math.max(landing.getY() + FAKE_PCS_MIN_CLEARANCE, landing.getY() + FAKE_PCS_DROP_HEIGHT));
        return landing.clone().set(landing.getX(), dropY, landing.getZ());
    }

    private void beginFakePcsDrop(Player player, Location landing) {
        if (player == null || landing == null || landing.getWorld() == null) {
            return;
        }
        Vector launchDirection = landing.toVector().subtract(player.getLocation().toVector());
        launchDirection.setY(0.0D);
        if (launchDirection.lengthSquared() <= 0.0001D) {
            launchDirection = player.getLocation().getDirection().setY(0.0D);
        }
        if (launchDirection.lengthSquared() <= 0.0001D) {
            launchDirection = new Vector(1.0D, 0.0D, 0.0D);
        }
        player.setInvulnerable(true);
        player.setNoDamageTicks(Integer.MAX_VALUE / 4);
        player.setFallDistance(0.0F);
        FakePcsPlayerState state = new FakePcsPlayerState(
            landing.getWorld().getName(),
            new FakePcsPlaneRoute(
                player.getLocation().clone(),
                landing.clone(),
                launchDirection.normalize(),
                new Vector(0.0D, 0.0D, 0.0D),
                player.getLocation().getYaw()
            ),
            0.0D,
            Bukkit.getCurrentTick(),
            (int) FAKE_PCS_PLANE_DURATION_TICKS,
            FakePcsPhase.IN_PLANE,
            -1,
            -20
        );
        fakePcsStates.put(player.getUniqueId(), launchFakePcsJump(player, state, Bukkit.getCurrentTick()));
    }

    private boolean isFakePcsLanding(Player player) {
        if (player == null || !player.isOnline() || player.isDead()) {
            return true;
        }
        if (player.isOnGround() || player.isSwimming()) {
            return true;
        }
        Material feet = player.getLocation().getBlock().getType();
        return feet == Material.WATER || feet == Material.LAVA;
    }

    private FakePcsPlayerState fakePcsState(Player player) {
        return player == null ? null : fakePcsStates.get(player.getUniqueId());
    }

    private boolean isFakePcsControlled(Player player) {
        FakePcsPlayerState state = fakePcsState(player);
        return state != null && state.phase() != FakePcsPhase.LANDED;
    }

    private void clearFakePcsState(Player player) {
        if (player == null) {
            return;
        }
        UUID playerId = player.getUniqueId();
        fakePcsStates.remove(playerId);
        ItemStack originalChestplate = fakePcsOriginalChestplates.remove(playerId);
        clearFakePcsDiveDisplay(player, true);
        restoreFakePcsChestplate(player, originalChestplate);
        player.removePotionEffect(PotionEffectType.SLOW_FALLING);
        player.setGliding(false);
        if (!isCustomSpectator(player) && !player.isOp()) {
            player.setAllowFlight(false);
            player.setFlying(false);
        }
        player.setInvulnerable(false);
        player.setNoDamageTicks(0);
        player.setFallDistance(0.0F);
        player.updateInventory();
    }

    private void applyFakePcsGliderState(Player player, boolean gliderActive) {
        if (player == null) {
            return;
        }
        if (gliderActive) {
            ItemStack chestplate = player.getInventory().getChestplate();
            if (chestplate == null || chestplate.getType() != Material.ELYTRA) {
                player.getInventory().setChestplate(new ItemStack(Material.ELYTRA));
            }
            return;
        }
        restoreFakePcsChestplate(player, fakePcsOriginalChestplates.get(player.getUniqueId()));
    }

    private void restoreFakePcsChestplate(Player player, ItemStack originalChestplate) {
        if (player == null) {
            return;
        }
        ItemStack currentChestplate = player.getInventory().getChestplate();
        if (currentChestplate == null || currentChestplate.getType() != Material.ELYTRA) {
            return;
        }
        if (originalChestplate == null || originalChestplate.getType().isAir()) {
            player.getInventory().setChestplate(null);
        } else {
            player.getInventory().setChestplate(originalChestplate.clone());
        }
    }

    private void applyFakePcsDiveAnimation(Player player, boolean active, int nowTick) {
        if (player == null) {
            return;
        }
        UUID playerId = player.getUniqueId();
        if (!active) {
            clearFakePcsDiveDisplay(player, true);
            return;
        }

        if (!fakePcsOriginalInvisibleStates.containsKey(playerId)) {
            fakePcsOriginalInvisibleStates.put(playerId, player.isInvisible());
        }
        player.setInvisible(true);
        int startedTick = fakePcsDiveAnimStartedTicks.computeIfAbsent(playerId, ignored -> nowTick);
        int elapsedTicks = Math.max(0, nowTick - startedTick);
        int animationIndex = fakePcsDiveAnimationIndex(elapsedTicks);
        syncFakePcsDiveDisplay(player, animationIndex);
        fakePcsDiveAnimFrames.put(playerId, animationIndex);
    }

    private void syncFakePcsDiveDisplay(Player player, int animationIndex) {
        boolean useRigAnimation = fakePcsDiveUsesRigAnimation();
        EnumMap<FakePcsDivePart, ItemDisplay> displays = ensureFakePcsDiveDisplay(player, animationIndex);
        if (displays == null || displays.isEmpty()) {
            return;
        }
        Location baseLocation = fakePcsDiveDisplayLocation(player);
        Quaternionf modelRootRotation = fakePcsDiveModelRootRotation(player);
        FakePcsDiveGltfImporter.Pose rigPose = useRigAnimation ? fakePcsDiveRigPose(animationIndex) : null;
        for (FakePcsDivePart part : fakePcsDiveActiveParts()) {
            ItemDisplay display = displays.get(part);
            if (display == null || !display.isValid()) {
                continue;
            }
            updateFakePcsDiveDisplayItem(display, part, animationIndex);
            if (!useRigAnimation || !part.isRigPart() || rigPose == null) {
                display.teleport(baseLocation);
                display.setTransformation(fakePcsDiveTransformation(modelRootRotation));
                continue;
            }
            FakePcsDiveGltfImporter.PartTransform partTransform = rigPose.partTransform(part.rigPart());
            if (partTransform == null) {
                continue;
            }
            Quaternionf partRotation = new Quaternionf(modelRootRotation).mul(new Quaternionf(partTransform.rotation()));
            Vector3f partAnchor = new Vector3f(partTransform.translation()).rotate(new Quaternionf(modelRootRotation));
            Vector3f pivotCorrection = fakePcsDiveRigPivotCorrection(part, partRotation);
            display.teleport(baseLocation);
            display.setTransformation(new Transformation(
                partAnchor.add(pivotCorrection),
                partRotation,
                new Vector3f(fakePcsDiveModelScale),
                new Quaternionf()
            ));
        }
    }

    private EnumMap<FakePcsDivePart, ItemDisplay> ensureFakePcsDiveDisplay(Player player, int animationIndex) {
        if (player == null || !player.isOnline() || player.getWorld() == null) {
            return null;
        }
        UUID playerId = player.getUniqueId();
        Location spawnLocation = fakePcsDiveDisplayLocation(player);
        List<FakePcsDivePart> activeParts = fakePcsDiveActiveParts();
        EnumMap<FakePcsDivePart, UUID> displayIds = fakePcsDiveDisplayIds.computeIfAbsent(
            playerId,
            ignored -> new EnumMap<>(FakePcsDivePart.class)
        );
        for (Map.Entry<FakePcsDivePart, UUID> entry : new ArrayList<>(displayIds.entrySet())) {
            if (activeParts.contains(entry.getKey())) {
                continue;
            }
            removeFakePcsDiveDisplayEntity(entry.getValue());
            displayIds.remove(entry.getKey());
        }
        EnumMap<FakePcsDivePart, ItemDisplay> displays = new EnumMap<>(FakePcsDivePart.class);
        for (FakePcsDivePart part : activeParts) {
            UUID displayId = displayIds.get(part);
            ItemDisplay display = null;
            if (displayId != null) {
                Entity existing = Bukkit.getEntity(displayId);
                if (existing instanceof ItemDisplay itemDisplay && existing.isValid()) {
                    display = itemDisplay;
                }
            }
            if (display == null) {
                display = createFakePcsDiveDisplayPart(player, spawnLocation, part, animationIndex);
                if (display == null) {
                    continue;
                }
                displayIds.put(part, display.getUniqueId());
            }
            displays.put(part, display);
        }
        if (displays.isEmpty()) {
            fakePcsDiveDisplayIds.remove(playerId);
        }
        return displays;
    }

    private ItemDisplay createFakePcsDiveDisplayPart(
        Player player,
        Location spawnLocation,
        FakePcsDivePart part,
        int frameIndex
    ) {
        if (player == null || part == null || player.getWorld() == null) {
            return null;
        }
        ItemDisplay display = (ItemDisplay) player.getWorld().spawnEntity(spawnLocation, EntityType.ITEM_DISPLAY);
        display.setGravity(false);
        display.setPersistent(false);
        display.setInvulnerable(true);
        display.setBillboard(Display.Billboard.FIXED);
        display.setTransformation(new Transformation(
            new Vector3f(0.0F, 0.0F, 0.0F),
            new Quaternionf(),
            new Vector3f(1.0F, 1.0F, 1.0F),
            new Quaternionf()
        ));
        display.setInterpolationDelay(0);
        display.setInterpolationDuration(0);
        display.setTeleportDuration(0);
        display.setItemDisplayTransform(ItemDisplay.ItemDisplayTransform.NONE);
        display.setItemStack(createFakePcsDiveDisplayItem(fakePcsDiveDisplayModelKey(part, frameIndex)));
        return display;
    }

    private ItemStack createFakePcsDiveDisplayItem(NamespacedKey itemModelKey) {
        ItemStack displayItem = new ItemStack(Material.AMETHYST_SHARD);
        ItemMeta meta = displayItem.getItemMeta();
        if (meta == null || itemModelKey == null) {
            return displayItem;
        }
        meta.setItemModel(itemModelKey);
        meta.setDisplayName(ChatColor.DARK_AQUA + "Dive Animation");
        displayItem.setItemMeta(meta);
        return displayItem;
    }

    private void updateFakePcsDiveDisplayItem(ItemDisplay display, FakePcsDivePart part, int animationIndex) {
        if (display == null || !display.isValid()) {
            return;
        }
        NamespacedKey desiredModelKey = fakePcsDiveDisplayModelKey(part, animationIndex);
        if (desiredModelKey == null) {
            return;
        }
        ItemStack current = display.getItemStack();
        if (current != null && current.hasItemMeta()) {
            ItemMeta meta = current.getItemMeta();
            if (meta != null && meta.hasItemModel() && desiredModelKey.equals(meta.getItemModel())) {
                return;
            }
        }
        display.setItemStack(createFakePcsDiveDisplayItem(desiredModelKey));
    }

    private Location fakePcsDiveDisplayLocation(Player player) {
        Location location = player.getLocation().clone();
        Vector forward = player.getLocation().getDirection().clone().setY(0.0D);
        if (forward.lengthSquared() <= 0.0001D) {
            forward = new Vector(0.0D, 0.0D, 1.0D);
        } else {
            forward.normalize();
        }
        Vector right = new Vector(forward.getZ(), 0.0D, -forward.getX()).normalize();
        location.add(right.multiply(fakePcsDiveModelOffsetX));
        location.add(0.0D, fakePcsDiveModelOffsetY, 0.0D);
        location.add(forward.multiply(fakePcsDiveModelOffsetZ));
        location.setYaw(0.0F);
        location.setPitch(0.0F);
        return location;
    }

    private void clearFakePcsDiveDisplay(Player player, boolean restoreVisibility) {
        if (player == null) {
            return;
        }
        UUID playerId = player.getUniqueId();
        EnumMap<FakePcsDivePart, UUID> displayIds = fakePcsDiveDisplayIds.remove(playerId);
        if (displayIds != null) {
            for (UUID displayId : displayIds.values()) {
                removeFakePcsDiveDisplayEntity(displayId);
            }
        }
        fakePcsDiveAnimFrames.remove(playerId);
        fakePcsDiveAnimStartedTicks.remove(playerId);
        if (!restoreVisibility) {
            return;
        }
        Boolean originalInvisible = fakePcsOriginalInvisibleStates.remove(playerId);
        player.setInvisible(originalInvisible != null && originalInvisible);
    }

    private void clearAllFakePcsDiveDisplays() {
        for (EnumMap<FakePcsDivePart, UUID> displayIds : fakePcsDiveDisplayIds.values()) {
            if (displayIds == null) {
                continue;
            }
            for (UUID displayId : displayIds.values()) {
                removeFakePcsDiveDisplayEntity(displayId);
            }
        }
    }

    private Transformation fakePcsDiveTransformation(Quaternionf modelRootRotation) {
        return new Transformation(
            new Vector3f(0.0F, 0.0F, 0.0F),
            modelRootRotation,
            new Vector3f(fakePcsDiveModelScale),
            new Quaternionf()
        );
    }

    private Quaternionf fakePcsDiveModelRootRotation(Player player) {
        float yawDegrees = player == null ? 0.0F : player.getLocation().getYaw();
        float pitchDegrees = player == null ? 0.0F : player.getLocation().getPitch();
        Quaternionf rotation = new Quaternionf().rotateY((float) Math.toRadians(fakePcsDiveYawBiasDegrees - yawDegrees));
        if (fakePcsDiveFollowPlayerPitch) {
            rotation.rotateX((float) Math.toRadians(pitchDegrees + fakePcsDivePitchBiasDegrees));
        }
        return rotation.mul(fakePcsDiveQuaternion(fakePcsDiveBaseRotation));
    }

    private Quaternionf fakePcsDiveQuaternion(Vector3f eulerDegrees) {
        if (eulerDegrees == null) {
            return new Quaternionf();
        }
        return new Quaternionf().rotationXYZ(
            (float) Math.toRadians(eulerDegrees.x),
            (float) Math.toRadians(eulerDegrees.y),
            (float) Math.toRadians(eulerDegrees.z)
        );
    }

    private boolean fakePcsDiveUsesRigAnimation() {
        return fakePcsDiveAnimationMode == FakePcsDiveAnimationMode.RIG
            && fakePcsDiveRigPoses != null
            && !fakePcsDiveRigPoses.isEmpty();
    }

    private List<FakePcsDivePart> fakePcsDiveActiveParts() {
        return fakePcsDiveUsesRigAnimation() ? FAKE_PCS_DIVE_RIG_PARTS : List.of(FakePcsDivePart.FRAME);
    }

    private NamespacedKey fakePcsDiveDisplayModelKey(FakePcsDivePart part, int animationIndex) {
        if (part == null) {
            return null;
        }
        if (!part.isRigPart()) {
            return fakePcsDiveFrameModelKey(animationIndex);
        }
        return part.modelKey();
    }

    private void removeFakePcsDiveDisplayEntity(UUID displayId) {
        if (displayId == null) {
            return;
        }
        Entity display = Bukkit.getEntity(displayId);
        if (display != null && display.isValid()) {
            display.remove();
        }
    }

    private int fakePcsDiveAnimationIndex(int elapsedTicks) {
        if (!fakePcsDiveUsesRigAnimation()) {
            return fakePcsDiveScheduledFrameIndex(elapsedTicks);
        }
        return fakePcsDiveRigPoseIndex(elapsedTicks);
    }

    private int fakePcsDiveScheduledFrameIndex(int elapsedTicks) {
        if (fakePcsDiveFrameModelKeys == null || fakePcsDiveFrameModelKeys.isEmpty()) {
            return 0;
        }
        if (fakePcsDiveFramePoseTimesSeconds == null || fakePcsDiveFramePoseTimesSeconds.isEmpty()) {
            return fakePcsDiveFrameIndex(elapsedTicks);
        }
        double cycleSeconds = Math.max(
            fakePcsDiveFrameLoopSeconds,
            fakePcsDiveFramePoseTimesSeconds.get(fakePcsDiveFramePoseTimesSeconds.size() - 1)
        );
        if (cycleSeconds <= 0.0D) {
            return fakePcsDiveFrameIndex(elapsedTicks);
        }
        double elapsedSeconds = (elapsedTicks / 20.0D) % cycleSeconds;
        int poseIndex = 0;
        for (int i = 0; i < fakePcsDiveFramePoseTimesSeconds.size(); i++) {
            if (elapsedSeconds + 1.0E-6D >= fakePcsDiveFramePoseTimesSeconds.get(i)) {
                poseIndex = i + 1;
            }
        }
        return Math.min(poseIndex, fakePcsDiveFrameModelKeys.size() - 1);
    }

    private int fakePcsDiveRigPoseIndex(int elapsedTicks) {
        if (fakePcsDiveRigPoses == null || fakePcsDiveRigPoses.isEmpty()) {
            return 0;
        }
        double cycleSeconds = Math.max(
            fakePcsDiveGltfLoopSeconds,
            fakePcsDiveRigPoseTimesSeconds.isEmpty()
                ? DEFAULT_FAKE_PCS_DIVE_GLTF_LOOP_SECONDS
                : fakePcsDiveRigPoseTimesSeconds.get(fakePcsDiveRigPoseTimesSeconds.size() - 1)
        );
        if (cycleSeconds <= 0.0D) {
            cycleSeconds = DEFAULT_FAKE_PCS_DIVE_GLTF_LOOP_SECONDS;
        }
        double elapsedSeconds = (elapsedTicks / 20.0D) % cycleSeconds;
        int poseIndex = 0;
        for (int i = 0; i < fakePcsDiveRigPoseTimesSeconds.size(); i++) {
            if (elapsedSeconds + 1.0E-6D >= fakePcsDiveRigPoseTimesSeconds.get(i)) {
                poseIndex = i + 1;
            }
        }
        return Math.min(poseIndex, fakePcsDiveRigPoses.size() - 1);
    }

    private FakePcsDiveGltfImporter.Pose fakePcsDiveRigPose(int poseIndex) {
        if (fakePcsDiveRigPoses == null || fakePcsDiveRigPoses.isEmpty()) {
            return null;
        }
        int index = Math.floorMod(poseIndex, fakePcsDiveRigPoses.size());
        return fakePcsDiveRigPoses.get(index);
    }

    private Quaternionf fakePcsDiveRigBodyPoseRotation(FakePcsDiveGltfImporter.Pose pose) {
        if (pose == null) {
            return new Quaternionf();
        }
        FakePcsDiveGltfImporter.PartTransform body = pose.partTransform(FakePcsDiveGltfImporter.Part.BODY);
        return body == null ? new Quaternionf() : new Quaternionf(body.rotation());
    }

    private Vector3f fakePcsDiveRigPivotCorrection(FakePcsDivePart part, Quaternionf worldRotation) {
        Vector3f pivot = fakePcsDiveRigPivot(part);
        if (pivot.lengthSquared() <= 0.000001F) {
            return new Vector3f();
        }
        return new Vector3f(pivot).negate().rotate(new Quaternionf(worldRotation));
    }

    private Vector3f fakePcsDiveRigAnchor(FakePcsDivePart part) {
        if (part == null) {
            return new Vector3f();
        }
        return switch (part) {
            case HEAD -> new Vector3f(FAKE_PCS_DIVE_RIG_HEAD_ANCHOR);
            case BODY -> new Vector3f(FAKE_PCS_DIVE_RIG_BODY_ANCHOR);
            case RIGHT_ARM -> new Vector3f(FAKE_PCS_DIVE_RIG_RIGHT_ARM_ANCHOR);
            case LEFT_ARM -> new Vector3f(FAKE_PCS_DIVE_RIG_LEFT_ARM_ANCHOR);
            case RIGHT_LEG -> new Vector3f(FAKE_PCS_DIVE_RIG_RIGHT_LEG_ANCHOR);
            case LEFT_LEG -> new Vector3f(FAKE_PCS_DIVE_RIG_LEFT_LEG_ANCHOR);
            case FRAME -> new Vector3f();
        };
    }

    private Vector3f fakePcsDiveRigPivot(FakePcsDivePart part) {
        if (part == null) {
            return new Vector3f();
        }
        return switch (part) {
            case HEAD -> new Vector3f(FAKE_PCS_DIVE_RIG_HEAD_PIVOT);
            case BODY -> new Vector3f(FAKE_PCS_DIVE_RIG_BODY_PIVOT);
            case RIGHT_ARM -> new Vector3f(FAKE_PCS_DIVE_RIG_RIGHT_ARM_PIVOT);
            case LEFT_ARM -> new Vector3f(FAKE_PCS_DIVE_RIG_LEFT_ARM_PIVOT);
            case RIGHT_LEG -> new Vector3f(FAKE_PCS_DIVE_RIG_RIGHT_LEG_PIVOT);
            case LEFT_LEG -> new Vector3f(FAKE_PCS_DIVE_RIG_LEFT_LEG_PIVOT);
            case FRAME -> new Vector3f();
        };
    }

    private int fakePcsDiveFrameIndex(int nowTick) {
        if (fakePcsDiveFrameModelKeys == null || fakePcsDiveFrameModelKeys.isEmpty()) {
            return 0;
        }
        return Math.floorMod(nowTick / Math.max(1, fakePcsDiveFrameTicks), fakePcsDiveFrameModelKeys.size());
    }

    private NamespacedKey fakePcsDiveFrameModelKey(int frameIndex) {
        if (fakePcsDiveFrameModelKeys == null || fakePcsDiveFrameModelKeys.isEmpty()) {
            List<NamespacedKey> defaults = defaultFakePcsDiveFrameModelKeys();
            return defaults.isEmpty() ? null : defaults.get(0);
        }
        int index = Math.floorMod(frameIndex, fakePcsDiveFrameModelKeys.size());
        return fakePcsDiveFrameModelKeys.get(index);
    }

    private List<NamespacedKey> loadFakePcsDiveFrameModelKeys() {
        List<NamespacedKey> configured = normalizeFakePcsDiveFrameModelKeys(
            plugin.getConfig().getStringList("queue.fake_pcs.dive.frame_models")
        );
        if (!configured.isEmpty()) {
            plugin.getLogger().info("[Queue] Using " + configured.size() + " fake PCS dive frame model(s) from config.");
            return configured;
        }

        List<NamespacedKey> discovered = discoverFakePcsDiveFrameModelKeysFromPack();
        if (!discovered.isEmpty()) {
            plugin.getLogger().info("[Queue] Using " + discovered.size() + " fake PCS dive frame model(s) from resource pack.");
            return discovered;
        }

        return defaultFakePcsDiveFrameModelKeys();
    }

    private List<FakePcsDiveGltfImporter.Pose> loadFakePcsDiveRigAnimation() {
        if (fakePcsDiveAnimationMode != FakePcsDiveAnimationMode.RIG) {
            fakePcsDiveRigPoseTimesSeconds = List.of();
            return List.of();
        }
        Path gltfPath = resolveFakePcsDiveGltfPath(fakePcsDiveGltfPath);
        if (gltfPath == null || !Files.isRegularFile(gltfPath)) {
            return List.of();
        }
        try {
            FakePcsDiveGltfImporter.Animation animation = FakePcsDiveGltfImporter.load(gltfPath);
            fakePcsDiveRigPoseTimesSeconds = animation.keyTimesSeconds();
            plugin.getLogger().info("[Queue] Using fake PCS dive rig from " + gltfPath
                + " with " + animation.poses().size() + " pose(s).");
            return animation.poses();
        } catch (IOException | JsonParseException ex) {
            fakePcsDiveRigPoseTimesSeconds = List.of();
            plugin.getLogger().warning("[Queue] Failed loading fake PCS dive rig from "
                + gltfPath + ": " + ex.getMessage());
            return List.of();
        }
    }

    private Path resolveFakePcsDiveGltfPath(String rawPath) {
        String configuredPath = rawPath == null || rawPath.isBlank() ? DEFAULT_FAKE_PCS_DIVE_GLTF_PATH : rawPath.trim();
        try {
            Path path = Path.of(configuredPath);
            if (!path.isAbsolute()) {
                path = plugin.getDataFolder().toPath().resolve(path).normalize();
            }
            return path;
        } catch (RuntimeException ex) {
            plugin.getLogger().warning("[Queue] Invalid fake PCS dive glTF path '" + configuredPath + "'.");
            return null;
        }
    }

    private static List<Double> normalizeFakePcsDivePoseTimesSeconds(List<?> rawValues) {
        if (rawValues == null || rawValues.isEmpty()) {
            return List.of();
        }
        List<Double> out = new ArrayList<>();
        double previous = -1.0D;
        for (Object rawValue : rawValues) {
            if (rawValue == null) {
                continue;
            }
            double value;
            if (rawValue instanceof Number number) {
                value = number.doubleValue();
            } else {
                try {
                    value = Double.parseDouble(rawValue.toString().trim());
                } catch (NumberFormatException ex) {
                    continue;
                }
            }
            if (Double.isNaN(value) || Double.isInfinite(value) || value <= previous) {
                continue;
            }
            previous = value;
            out.add(value);
        }
        return out;
    }

    private List<NamespacedKey> discoverFakePcsDiveFrameModelKeysFromPack() {
        File packFile = new File(plugin.getDataFolder(), FAKE_PCS_DIVE_RESOURCE_PACK_PATH);
        if (!packFile.isFile()) {
            return List.of();
        }

        List<String> discoveredModelIds = new ArrayList<>();
        try (ZipFile zipFile = new ZipFile(packFile)) {
            Enumeration<? extends ZipEntry> entries = zipFile.entries();
            while (entries.hasMoreElements()) {
                ZipEntry entry = entries.nextElement();
                if (entry.isDirectory()) {
                    continue;
                }
                String entryName = entry.getName();
                if (!entryName.startsWith(FAKE_PCS_DIVE_FRAME_ENTRY_PREFIX) || !entryName.endsWith(".json")) {
                    continue;
                }
                String modelId = entryName.substring("assets/hydra/items/".length(), entryName.length() - ".json".length());
                discoveredModelIds.add("hydra:" + modelId);
            }
        } catch (IOException ex) {
            plugin.getLogger().warning("[Queue] Failed reading fake PCS dive frames from "
                + packFile.getName() + ": " + ex.getMessage());
            return List.of();
        }

        discoveredModelIds.sort(
            Comparator.comparingInt(QueueService::fakePcsDiveFrameSortOrder).thenComparing(String::compareTo)
        );
        return normalizeFakePcsDiveFrameModelKeys(discoveredModelIds);
    }

    private static int fakePcsDiveFrameSortOrder(String rawModelId) {
        if (rawModelId == null || rawModelId.isBlank()) {
            return Integer.MAX_VALUE;
        }
        int lastUnderscore = rawModelId.lastIndexOf('_');
        if (lastUnderscore < 0 || lastUnderscore >= rawModelId.length() - 1) {
            return Integer.MAX_VALUE;
        }
        try {
            return Integer.parseInt(rawModelId.substring(lastUnderscore + 1));
        } catch (NumberFormatException ex) {
            return Integer.MAX_VALUE;
        }
    }

    private static List<NamespacedKey> defaultFakePcsDiveFrameModelKeys() {
        return normalizeFakePcsDiveFrameModelKeys(DEFAULT_FAKE_PCS_DIVE_FRAME_MODEL_IDS);
    }

    private static List<NamespacedKey> normalizeFakePcsDiveFrameModelKeys(List<String> rawModelIds) {
        if (rawModelIds == null || rawModelIds.isEmpty()) {
            return List.of();
        }
        LinkedHashSet<NamespacedKey> out = new LinkedHashSet<>();
        for (String rawModelId : rawModelIds) {
            if (rawModelId == null || rawModelId.isBlank()) {
                continue;
            }
            NamespacedKey modelKey = NamespacedKey.fromString(rawModelId.trim().toLowerCase(Locale.ROOT));
            if (modelKey != null) {
                out.add(modelKey);
            }
        }
        return out.isEmpty() ? List.of() : List.copyOf(out);
    }

    private void applyHungerGamesStartFreeze(Player player, Location anchor) {
        if (player == null || anchor == null || hungerGamesStartFreezeSeconds <= 0) {
            return;
        }
        UUID playerId = player.getUniqueId();
        long freezeUntil = System.currentTimeMillis() + (hungerGamesStartFreezeSeconds * 1000L);
        Location lockedAnchor = anchor.clone();
        lockedAnchor.setPitch(player.getLocation().getPitch());
        lockedAnchor.setYaw(player.getLocation().getYaw());
        hungerGamesStartFreezeAnchors.put(playerId, lockedAnchor);
        hungerGamesStartFreezeUntilMs.put(playerId, freezeUntil);
        player.setSprinting(false);
        scheduleHungerGamesStartCountdown(playerId, freezeUntil, hungerGamesStartFreezeSeconds);
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            releaseHungerGamesStartFreeze(playerId, freezeUntil);
        }, Math.max(1L, hungerGamesStartFreezeSeconds * 20L));
    }

    private void scheduleHungerGamesStartCountdown(UUID playerId, long freezeUntil, int seconds) {
        int countdownSeconds = Math.max(1, seconds);
        for (int remaining = countdownSeconds; remaining >= 1; remaining--) {
            int titleNumber = remaining;
            long delayTicks = Math.max(0L, (countdownSeconds - remaining) * 20L);
            Bukkit.getScheduler().runTaskLater(plugin, () -> {
                Long currentFreezeUntil = hungerGamesStartFreezeUntilMs.get(playerId);
                if (currentFreezeUntil == null || currentFreezeUntil.longValue() != freezeUntil) {
                    return;
                }
                Player current = Bukkit.getPlayer(playerId);
                if (current == null || !current.isOnline() || !isHungerGames(inMatchTypes.get(playerId))) {
                    return;
                }
                current.sendTitle(
                    ChatColor.GOLD + "" + ChatColor.BOLD + titleNumber,
                    ChatColor.GRAY + "Get ready",
                    0,
                    22,
                    0
                );
                HydraSounds.playCountdownTick(current, titleNumber);
            }, delayTicks);
        }
    }

    private void releaseHungerGamesStartFreeze(UUID playerId, long freezeUntil) {
        Long currentFreezeUntil = hungerGamesStartFreezeUntilMs.get(playerId);
        if (currentFreezeUntil == null || currentFreezeUntil.longValue() != freezeUntil) {
            return;
        }
        hungerGamesStartFreezeUntilMs.remove(playerId);
        hungerGamesStartFreezeAnchors.remove(playerId);
        Player current = Bukkit.getPlayer(playerId);
        if (current != null && current.isOnline()) {
            current.setInvulnerable(false);
            current.setNoDamageTicks(0);
            startHungerGamesCombatGrace(current);
            String subtitle = hungerGamesCombatGraceSeconds > 0
                ? ChatColor.GRAY + "Grace for " + hungerGamesCombatGraceSeconds + "s"
                : "";
            current.sendTitle(ChatColor.GREEN + "" + ChatColor.BOLD + "GO!", subtitle, 0, 18, 10);
            String message = HYDRA_PREFIX + ChatColor.GREEN + "Go!";
            if (hungerGamesCombatGraceSeconds > 0) {
                message += ChatColor.GRAY + " Grace for " + hungerGamesCombatGraceSeconds + "s.";
            }
            current.sendMessage(message);
            HydraSounds.playGo(current);
        }
    }

    private void clearHungerGamesStartFreeze(Player player) {
        if (player == null) {
            return;
        }
        UUID playerId = player.getUniqueId();
        hungerGamesStartFreezeUntilMs.remove(playerId);
        hungerGamesStartFreezeAnchors.remove(playerId);
    }

    private void startHungerGamesCombatGrace(Player player) {
        if (player == null || hungerGamesCombatGraceSeconds <= 0) {
            return;
        }
        UUID playerId = player.getUniqueId();
        long graceUntil = System.currentTimeMillis() + (hungerGamesCombatGraceSeconds * 1000L);
        hungerGamesCombatGraceUntilMs.put(playerId, graceUntil);
        player.addPotionEffect(new PotionEffect(
            PotionEffectType.FIRE_RESISTANCE,
            Math.max(1, hungerGamesCombatGraceSeconds * 20 + 5),
            0,
            false,
            false,
            false
        ), true);
        Bukkit.getScheduler().runTaskLater(plugin, () -> releaseHungerGamesCombatGrace(playerId, graceUntil), Math.max(1L, hungerGamesCombatGraceSeconds * 20L));
    }

    private void releaseHungerGamesCombatGrace(UUID playerId, long graceUntil) {
        Long currentGraceUntil = hungerGamesCombatGraceUntilMs.get(playerId);
        if (currentGraceUntil == null || currentGraceUntil.longValue() != graceUntil) {
            return;
        }
        hungerGamesCombatGraceUntilMs.remove(playerId);
        Player current = Bukkit.getPlayer(playerId);
        if (current != null && current.isOnline()) {
            current.removePotionEffect(PotionEffectType.FIRE_RESISTANCE);
            current.sendMessage(HYDRA_PREFIX + ChatColor.RED + "Grace period ended.");
            current.playSound(current.getLocation(), Sound.BLOCK_NOTE_BLOCK_BASS, 0.8F, 0.95F);
        }
    }

    private void clearHungerGamesCombatGrace(Player player) {
        if (player == null) {
            return;
        }
        if (hungerGamesCombatGraceUntilMs.remove(player.getUniqueId()) != null) {
            player.removePotionEffect(PotionEffectType.FIRE_RESISTANCE);
        }
    }

    private boolean isHungerGamesCombatGraceActive(Player player) {
        if (player == null) {
            return false;
        }
        Long graceUntil = hungerGamesCombatGraceUntilMs.get(player.getUniqueId());
        if (graceUntil == null) {
            return false;
        }
        if (graceUntil <= System.currentTimeMillis()) {
            clearHungerGamesCombatGrace(player);
            return false;
        }
        return isHungerGames(inMatchTypes.get(player.getUniqueId()));
    }

    private boolean isHungerGamesStartFrozen(Player player) {
        if (player == null) {
            return false;
        }
        Long freezeUntil = hungerGamesStartFreezeUntilMs.get(player.getUniqueId());
        if (freezeUntil == null) {
            return false;
        }
        if (freezeUntil <= System.currentTimeMillis()) {
            clearHungerGamesStartFreeze(player);
            return false;
        }
        return isHungerGames(inMatchTypes.get(player.getUniqueId()));
    }

    private Location lockedHungerGamesStartLocation(Player player, float yaw, float pitch) {
        Location anchor = hungerGamesStartFreezeAnchors.get(player.getUniqueId());
        if (anchor == null) {
            return player.getLocation().clone().setDirection(player.getLocation().getDirection());
        }
        Location locked = anchor.clone();
        locked.setYaw(yaw);
        locked.setPitch(pitch);
        return locked;
    }

    private void scheduleHungerGamesPlacedBlockDecay(Player player, Block block, BlockData replacedData) {
        if (player == null || block == null || hungerGamesPlacedBlockDecaySeconds <= 0) {
            return;
        }
        if (!isHungerGames(inMatchTypes.get(player.getUniqueId()))) {
            return;
        }
        World world = block.getWorld();
        if (!isHungerGamesMatchWorld(world)) {
            return;
        }
        if (block.getType().isAir()) return;
        Location blockLocation = block.getLocation();
        String key = blockLocationKey(blockLocation);
        BlockData expectedData = block.getBlockData().clone();
        HungerGamesPlacedBlock placement = new HungerGamesPlacedBlock(expectedData, replacedData);
        HungerGamesPlacedBlock previous = hungerGamesPlacedBlocks.put(key, placement);
        if (previous != null && previous.task != null) previous.task.cancel();
        long delayTicks = Math.max(1L, hungerGamesPlacedBlockDecaySeconds * 20L);
        placement.task = Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (hungerGamesPlacedBlocks.get(key) != placement) return;
            hungerGamesPlacedBlocks.remove(key);
            World currentWorld = blockLocation.getWorld();
            if (!isHungerGamesMatchWorld(currentWorld)) {
                return;
            }
            Block currentBlock = currentWorld.getBlockAt(blockLocation);
            if (currentBlock.getType() != placement.expectedData.getMaterial()) {
                return;
            }
            if (!currentBlock.getBlockData().matches(placement.expectedData)) {
                return;
            }
            if (placement.replacedData != null && placement.replacedData.getMaterial() == Material.WATER) {
                currentBlock.setBlockData(placement.replacedData, false);
            } else {
                currentBlock.setType(Material.AIR, false);
            }
        }, delayTicks);
    }

    private static final class HungerGamesPlacedBlock {
        private final BlockData expectedData;
        private final BlockData replacedData;
        private BukkitTask task;

        private HungerGamesPlacedBlock(BlockData expectedData, BlockData replacedData) {
            this.expectedData = expectedData;
            this.replacedData = replacedData;
        }
    }

    private boolean handleHungerGamesRespawningDecorBreak(BlockBreakEvent event) {
        Player player = event.getPlayer();
        Block block = event.getBlock();
        if (player == null || block == null) {
            return false;
        }
        if (!isHungerGames(inMatchTypes.get(player.getUniqueId())) || !isHungerGamesMatchWorld(block.getWorld())) {
            return false;
        }
        if (!isHungerGamesRespawningDecor(block.getType())) {
            return false;
        }

        scheduleHungerGamesDecorRespawn(block);
        Material type = block.getType();
        if (type == Material.TALL_GRASS || type == Material.TALL_SEAGRASS) {
            Block above = block.getRelative(0, 1, 0);
            Block below = block.getRelative(0, -1, 0);
            if (above.getType() == type) {
                scheduleHungerGamesDecorRespawn(above);
            }
            if (below.getType() == type) {
                scheduleHungerGamesDecorRespawn(below);
            }
        }
        event.setDropItems(false);
        event.setExpToDrop(0);
        return true;
    }

    private void scheduleHungerGamesDecorRespawn(Block block) {
        if (block == null || !isHungerGamesMatchWorld(block.getWorld())) {
            return;
        }
        Location location = block.getLocation();
        BlockData originalData = block.getBlockData().clone();
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            World world = location.getWorld();
            if (!isHungerGamesMatchWorld(world)) {
                return;
            }
            Block current = world.getBlockAt(location);
            Material currentType = current.getType();
            if (!currentType.isAir() && currentType != Material.WATER && currentType != Material.LAVA && !current.isPassable()) {
                return;
            }
            current.setBlockData(originalData, false);
        }, 20L * 20L);
    }

    private boolean isHungerGamesRespawningDecor(Material type) {
        if (type == null || type.isAir()) {
            return false;
        }
        String name = type.name();
        return name.equals("SHORT_GRASS")
            || name.equals("TALL_GRASS")
            || name.equals("GRASS")
            || name.equals("FERN")
            || name.equals("LARGE_FERN")
            || name.equals("SEAGRASS")
            || name.equals("TALL_SEAGRASS")
            || name.contains("CORAL");
    }

    private void trackHungerGamesTemporaryFluid(Player player, Block block, Material fluidType) {
        if (block == null || hungerGamesPlacedBlockDecaySeconds <= 0) {
            return;
        }
        if (fluidType != Material.WATER && fluidType != Material.LAVA) {
            return;
        }
        if (player != null && !isHungerGames(inMatchTypes.get(player.getUniqueId()))) {
            return;
        }
        World world = block.getWorld();
        if (!isHungerGamesMatchWorld(world) || block.getType() != fluidType) {
            return;
        }
        String key = blockLocationKey(block.getLocation());
        if (hungerGamesTemporaryFluidBlocks.putIfAbsent(key, fluidType) != null) {
            return;
        }
        Location blockLocation = block.getLocation();
        long delayTicks = Math.max(1L, hungerGamesPlacedBlockDecaySeconds * 20L);
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            Material expected = hungerGamesTemporaryFluidBlocks.remove(key);
            if (expected == null) {
                return;
            }
            World currentWorld = blockLocation.getWorld();
            if (!isHungerGamesMatchWorld(currentWorld)) {
                return;
            }
            Block currentBlock = currentWorld.getBlockAt(blockLocation);
            if (currentBlock.getType() == expected) {
                currentBlock.setType(Material.AIR, false);
            }
        }, delayTicks);
    }

    private boolean handleHungerGamesOreBreak(Player player, Block block) {
        if (player == null || block == null) {
            return false;
        }
        Material blockType = block.getType();
        if (!isHungerGamesMineableOre(blockType)) {
            return false;
        }
        if (!isPickaxe(player.getInventory().getItemInMainHand())) {
            player.sendActionBar(Component.text("Use a pickaxe to mine ores.", net.kyori.adventure.text.format.NamedTextColor.RED));
            return true;
        }

        Collection<ItemStack> rawDrops = block.getDrops(player.getInventory().getItemInMainHand(), player);
        List<ItemStack> transformedDrops = new ArrayList<>();
        if (rawDrops.isEmpty()) {
            transformedDrops.add(defaultHungerGamesOreDrop(blockType));
        } else {
            for (ItemStack drop : rawDrops) {
                transformedDrops.add(transformHungerGamesOreDrop(drop));
            }
        }

        Location dropLocation = block.getLocation().add(0.5D, 0.5D, 0.5D);
        World world = block.getWorld();
        for (ItemStack stack : transformedDrops) {
            if (stack == null || stack.getType().isAir() || stack.getAmount() <= 0) {
                continue;
            }
            world.dropItem(dropLocation, stack);
        }

        String key = hungerGamesOreKey(block.getLocation());
        hungerGamesTemporaryOreRegeneration.put(key, randomHungerGamesOreReplacement(blockType));
        block.setType(Material.BEDROCK, false);
        world.playSound(dropLocation, Sound.BLOCK_STONE_BREAK, 0.8F, 1.1F);
        player.playSound(player.getLocation(), Sound.ENTITY_EXPERIENCE_ORB_PICKUP, 0.35F, 1.65F);
        scheduleHungerGamesOreRegeneration(block.getLocation(), key);
        return true;
    }

    private void scheduleHungerGamesOreRegeneration(Location location, String key) {
        long delayTicks = 20L * 60L;
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            Material replacement = hungerGamesTemporaryOreRegeneration.remove(key);
            if (replacement == null || location == null) {
                return;
            }
            World world = location.getWorld();
            if (world == null || !isHungerGamesMatchWorld(world)) {
                return;
            }
            Block currentBlock = world.getBlockAt(location);
            if (currentBlock.getType() != Material.BEDROCK) {
                return;
            }
            currentBlock.setType(replacement, false);
        }, delayTicks);
    }

    private boolean isHungerGamesTemporaryOreBedrock(Block block) {
        if (block == null || block.getType() != Material.BEDROCK) {
            return false;
        }
        return hungerGamesTemporaryOreRegeneration.containsKey(hungerGamesOreKey(block.getLocation()));
    }

    private static boolean isHungerGamesMineableOre(Material material) {
        return switch (material) {
            case COAL_ORE, DEEPSLATE_COAL_ORE,
                IRON_ORE, DEEPSLATE_IRON_ORE,
                COPPER_ORE, DEEPSLATE_COPPER_ORE,
                GOLD_ORE, DEEPSLATE_GOLD_ORE,
                REDSTONE_ORE, DEEPSLATE_REDSTONE_ORE,
                LAPIS_ORE, DEEPSLATE_LAPIS_ORE,
                DIAMOND_ORE, DEEPSLATE_DIAMOND_ORE,
                EMERALD_ORE, DEEPSLATE_EMERALD_ORE,
                NETHER_QUARTZ_ORE, NETHER_GOLD_ORE -> true;
            default -> false;
        };
    }

    private static boolean isPickaxe(ItemStack item) {
        if (item == null) {
            return false;
        }
        return switch (item.getType()) {
            case WOODEN_PICKAXE, STONE_PICKAXE, COPPER_PICKAXE, GOLDEN_PICKAXE, IRON_PICKAXE, DIAMOND_PICKAXE, NETHERITE_PICKAXE -> true;
            default -> false;
        };
    }

    private static ItemStack transformHungerGamesOreDrop(ItemStack drop) {
        if (drop == null) {
            return new ItemStack(Material.AIR);
        }
        Material target = switch (drop.getType()) {
            case RAW_IRON -> Material.IRON_INGOT;
            case RAW_GOLD -> Material.GOLD_INGOT;
            case RAW_COPPER -> Material.COPPER_INGOT;
            default -> drop.getType();
        };
        return new ItemStack(target, Math.max(1, drop.getAmount()));
    }

    private static ItemStack defaultHungerGamesOreDrop(Material blockType) {
        return switch (blockType) {
            case IRON_ORE, DEEPSLATE_IRON_ORE -> new ItemStack(Material.IRON_INGOT, 1);
            case GOLD_ORE, DEEPSLATE_GOLD_ORE, NETHER_GOLD_ORE -> new ItemStack(Material.GOLD_INGOT, 1);
            case COPPER_ORE, DEEPSLATE_COPPER_ORE -> new ItemStack(Material.COPPER_INGOT, 1);
            case DIAMOND_ORE, DEEPSLATE_DIAMOND_ORE -> new ItemStack(Material.DIAMOND, 1);
            case EMERALD_ORE, DEEPSLATE_EMERALD_ORE -> new ItemStack(Material.EMERALD, 1);
            case LAPIS_ORE, DEEPSLATE_LAPIS_ORE -> new ItemStack(Material.LAPIS_LAZULI, 4);
            case REDSTONE_ORE, DEEPSLATE_REDSTONE_ORE -> new ItemStack(Material.REDSTONE, 4);
            case NETHER_QUARTZ_ORE -> new ItemStack(Material.QUARTZ, 3);
            default -> new ItemStack(Material.COAL, 1);
        };
    }

    private static Material randomHungerGamesOreReplacement(Material original) {
        boolean deepslate = original.name().startsWith("DEEPSLATE_");
        Material[] pool = deepslate
            ? new Material[] {
                Material.DEEPSLATE_COAL_ORE,
                Material.DEEPSLATE_COAL_ORE,
                Material.DEEPSLATE_IRON_ORE,
                Material.DEEPSLATE_IRON_ORE,
                Material.DEEPSLATE_COPPER_ORE,
                Material.DEEPSLATE_REDSTONE_ORE,
                Material.DEEPSLATE_LAPIS_ORE,
                Material.DEEPSLATE_GOLD_ORE,
                Material.DEEPSLATE_DIAMOND_ORE,
                Material.DEEPSLATE_EMERALD_ORE
            }
            : new Material[] {
                Material.COAL_ORE,
                Material.COAL_ORE,
                Material.IRON_ORE,
                Material.IRON_ORE,
                Material.COPPER_ORE,
                Material.REDSTONE_ORE,
                Material.LAPIS_ORE,
                Material.GOLD_ORE,
                Material.DIAMOND_ORE,
                Material.EMERALD_ORE
            };
        return pool[ThreadLocalRandom.current().nextInt(pool.length)];
    }

    private static String hungerGamesOreKey(Location location) {
        return blockLocationKey(location);
    }

    private static String blockLocationKey(Location location) {
        return location.getWorld().getName() + ":" + location.getBlockX() + ":" + location.getBlockY() + ":" + location.getBlockZ();
    }

    private void removeFromMatch(UUID playerId, Player playerOrNull, boolean teleportToLobby) {
        inMatchPlayers.remove(playerId);
        QueueType type = inMatchTypes.remove(playerId);
        String worldName = inMatchWorlds.remove(playerId);
        clearCornucopiaCampState(playerId);
        duoTeamByPlayer.remove(playerId);
        if (playerOrNull != null) {
            clearHungerGamesStartFreeze(playerOrNull);
            clearHungerGamesCombatGrace(playerOrNull);
            if (isHungerGames(type)) {
                restoreStandardPlayerHealth(playerOrNull);
            }
        } else {
            hungerGamesStartFreezeUntilMs.remove(playerId);
            hungerGamesStartFreezeAnchors.remove(playerId);
            hungerGamesCombatGraceUntilMs.remove(playerId);
        }

        if (teleportToLobby && playerOrNull != null && playerOrNull.isOnline()) {
            clearFakePcsState(playerOrNull);
            returnToHub(playerOrNull, true);
        }
        if (teleportToLobby) {
            clearBattleRoyaleSnapshots(playerId);
        }
        if (teleportToLobby || !pendingSpectatorRespawnWorld.containsKey(playerId)) {
            matchKills.remove(playerId);
            resetMatchRewardStats(playerId);
        }

        if (type == null || worldName == null) {
            return;
        }
        syncSpectatorVisibility(worldName);
        maybeEvaluateMatchState(type, worldName);
    }

    private void maybeEvaluateMatchState(QueueType type, String worldName) {
        if (!autoWinTriggerEnabled) {
            return;
        }
        evaluateMatchState(type, worldName);
    }

    private boolean hasMatchPlayersInWorld(String worldName) {
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null) {
            return false;
        }
        if (activeBrTestPlaceholderCount(rootWorldName) > 0) {
            return true;
        }
        for (Map.Entry<UUID, String> entry : inMatchWorlds.entrySet()) {
            if (isSameMatchSessionWorld(rootWorldName, entry.getValue())
                && isLiveMatchCombatant(entry.getKey(), rootWorldName)) {
                return true;
            }
        }
        return false;
    }

    private List<UUID> activePlayersInWorld(String worldName) {
        String rootWorldName = rootMatchWorldName(worldName);
        List<UUID> players = new ArrayList<>();
        if (rootWorldName == null) {
            return players;
        }
        for (Map.Entry<UUID, String> entry : inMatchWorlds.entrySet()) {
            if (isSameMatchSessionWorld(rootWorldName, entry.getValue())
                && isLiveMatchCombatant(entry.getKey(), rootWorldName)) {
                players.add(entry.getKey());
            }
        }
        return players;
    }

    private int activeParticipantCountInWorld(String worldName) {
        return activePlayersInWorld(worldName).size() + activeBrTestPlaceholderCount(worldName);
    }

    private boolean isLiveMatchCombatant(UUID playerId, String rootWorldName) {
        if (playerId == null || rootWorldName == null) {
            return false;
        }
        Player player = Bukkit.getPlayer(playerId);
        if (player == null || !player.isOnline() || player.isDead()) {
            return false;
        }
        if (!isSameMatchSessionWorld(rootWorldName, player.getWorld().getName())) {
            return false;
        }
        if (isCustomSpectator(player)) {
            return false;
        }
        GameMode gameMode = player.getGameMode();
        return gameMode == GameMode.SURVIVAL || gameMode == GameMode.ADVENTURE;
    }

    private void clearStaleActiveMatchWorld(QueueType type, String worldName, String reason) {
        if (type == null || worldName == null || worldName.isBlank()) {
            return;
        }
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null) {
            return;
        }
        plugin.getLogger().info(reason + ": " + type.displayName() + " world=" + rootWorldName
            + " has no live combatants");
        finishMatchWorld(type, rootWorldName);
    }

    private boolean hasLiveMatchSession(QueueType type, String worldName) {
        if (type == null || worldName == null || worldName.isBlank()) {
            return false;
        }
        if (!activeMatchWorldsFor(type).contains(worldName)) {
            return false;
        }
        if (endingMatchWorlds.contains(worldName)) {
            return false;
        }
        return hasMatchPlayersInWorld(worldName);
    }

    private boolean hasLiveHungerGamesSession(String worldName) {
        QueueType type = resolveQueueTypeForWorld(worldName);
        return isHungerGames(type) && hasLiveMatchSession(type, worldName);
    }

    private void evaluateMatchState(QueueType type, String worldName) {
        if (isBrDevelopmentTestWorld(worldName)) {
            return;
        }
        if (endingMatchWorlds.contains(rootMatchWorldName(worldName))) {
            // The winner-return task already owns this match's result and cleanup.
            return;
        }
        List<UUID> active = activePlayersInWorld(worldName);
        if (active.isEmpty()) {
            finishMatchWorld(type, worldName);
            return;
        }
        boolean hgDuos = isHungerGames(type)
            && hungerGamesDuoWorlds.contains(rootMatchWorldName(worldName));
        if (type == QueueType.DUO || hgDuos) {
            Set<UUID> aliveTeams = new LinkedHashSet<>();
            for (UUID id : active) {
                aliveTeams.add(duoTeamByPlayer.getOrDefault(id, id));
            }
            if (aliveTeams.size() > 1) {
                return;
            }
            UUID winningTeamId = aliveTeams.iterator().next();
            List<UUID> winners = new ArrayList<>();
            if (hgDuos) {
                winners.addAll(hungerGamesDuoRosters.getOrDefault(rootMatchWorldName(worldName), Map.of())
                    .getOrDefault(winningTeamId, Set.of()));
            } else for (UUID id : active) {
                if (duoTeamByPlayer.getOrDefault(id, id).equals(winningTeamId)) winners.add(id);
            }
            startWinnerCountdown(type, worldName, winners);
            return;
        }
        if (active.size() > 1) {
            return;
        }
        startWinnerCountdown(type, worldName, List.of(active.get(0)));
    }

    private void startWinnerCountdown(QueueType type, String worldName, List<UUID> winnerIds) {
        if (!endingMatchWorlds.add(worldName)) {
            return;
        }

        List<UUID> winners = new ArrayList<>();
        for (UUID winnerId : winnerIds) {
            if (winnerId != null && !winners.contains(winnerId)) {
                winners.add(winnerId);
            }
        }
        if (winners.isEmpty()) {
            finishMatchWorld(type, worldName);
            return;
        }
        String winnerName;
        if (winners.size() == 1) {
            winnerName = displayName(winners.get(0));
        } else {
            List<String> names = new ArrayList<>();
            for (UUID winnerId : winners) {
                names.add(displayName(winnerId));
            }
            winnerName = String.join(ChatColor.GRAY + ", " + ChatColor.GOLD, names);
        }
        broadcastMatchWorldMessage(worldName, ChatColor.GOLD + "" + ChatColor.BOLD + "VICTORY");
        broadcastMatchWorldMessage(worldName, ChatColor.GOLD + winnerName + ChatColor.GREEN + " won.");
        plugin.getLogger().info("[Queue] match ended: " + type.displayName() + " world=" + worldName
            + " winner=" + ChatColor.stripColor(winnerName));
        for (UUID winnerId : winners) {
            recordLifetimeWin(winnerId, type);
            if (isHungerGames(type) && progressionService != null) {
                progressionService.grantShardFragments(winnerId, 1, "HUNGER_GAMES_WIN");
            }
            if (isHungerGames(type) && plugin instanceof HGLootPlugin hydra
                && hydra.battlePassService() != null) {
                hydra.battlePassService().completeHgMatch(winnerId, rootMatchWorldName(worldName), 1);
            }
        }
        Map<UUID, MatchWinSilverReward> silverRewards = new HashMap<>();
        for (UUID winnerId : winners) {
            MatchWinSilverReward reward = awardMatchWinSilver(winnerId, type);
            silverRewards.put(winnerId, reward);
            if (reward != null) {
                addMatchSilverEarned(winnerId, reward.awardedSilver());
            }
        }
        savePlayerStats();
        refreshAllDebugLeaderboards();

        for (UUID winnerId : winners) {
            Player winner = Bukkit.getPlayer(winnerId);
            if (winner != null && winner.isOnline()) {
                MatchWinSilverReward reward = silverRewards.get(winnerId);
                if (reward != null && reward.awardedSilver() > 0) {
                    winner.sendMessage(ChatColor.YELLOW + "Reward: " + ChatColor.WHITE + reward.awardedSilver() + " Coins");
                    if (reward.voiceBonus()) {
                        winner.sendMessage(ChatColor.GREEN + "Voice bonus: "
                            + ChatColor.YELLOW + "+" + voiceChatSilverBonusPercent() + "%");
                    }
                }
                winner.sendMessage(ChatColor.GREEN + "Returning to the Hub in 30s.");
                if (isHungerGames(type)
                    && plugin instanceof HGLootPlugin hydra
                    && hydra.victoryResultsService() != null) {
                    hydra.victoryResultsService().showVictory(winner, new VictoryResultsService.RewardSnapshot(
                        Math.max(0, matchXpEarned(winnerId) - HG_WIN_XP_REWARD),
                        matchSilverEarned(winnerId),
                        isHungerGames(type) ? 1 : 0,
                        null,
                        HG_WIN_XP_REWARD
                    ));
                } else {
                    showVictoryEffects(winner);
                }
            }
        }

        BukkitTask existing = winnerReturnTasks.remove(worldName);
        if (existing != null) {
            existing.cancel();
        }
        BukkitTask task = Bukkit.getScheduler().runTaskLater(plugin, () -> {
            LinkedHashSet<Player> returning = new LinkedHashSet<>();
            for (Player online : Bukkit.getOnlinePlayers()) {
                if (isSameMatchSessionWorld(worldName, online.getWorld().getName())) returning.add(online);
            }
            for (UUID winnerId : winners) {
                Player winner = Bukkit.getPlayer(winnerId);
                if (winner != null && winner.isOnline()) returning.add(winner);
            }
            Runnable finish = () -> {
                for (UUID winnerId : winners) {
                    inMatchPlayers.remove(winnerId);
                    inMatchTypes.remove(winnerId);
                    inMatchWorlds.remove(winnerId);
                    duoTeamByPlayer.remove(winnerId);
                    matchKills.remove(winnerId);
                    resetMatchRewardStats(winnerId);
                    clearBattleRoyaleSnapshots(winnerId);
                }
                finishMatchWorld(type, worldName);
                if (isHungerGames(type) && plugin instanceof HGLootPlugin hydra
                    && hydra.playerSettingsService() != null) {
                    hydra.playerSettingsService().requeueAfterCompletedSession(winners,
                        type == QueueType.HUNGERGAMES_DUOS
                            ? PlayerSettingsService.AutoQueue.HUNGER_GAMES_DUOS
                            : PlayerSettingsService.AutoQueue.HUNGER_GAMES_SOLO);
                }
            };
            if (plugin instanceof HGLootPlugin hydra) {
                hydra.transitionTravelGroup(returning, player -> returnToHub(player, true), finish);
            } else {
                returning.forEach(player -> returnToHub(player, true));
                finish.run();
            }
        }, WINNER_RETURN_DELAY_TICKS - TransitionService.Preset.NORMAL.fadeOutTicks);
        winnerReturnTasks.put(worldName, task);
    }

    private void finishMatchWorld(QueueType type, String worldName) {
        String rootWorldName = rootMatchWorldName(worldName);
        boolean completedHg = isHungerGames(type) && endingMatchWorlds.contains(worldName);
        LinkedHashSet<UUID> requeueCandidates = new LinkedHashSet<>();
        if (completedHg) {
            for (Map.Entry<UUID, String> entry : inMatchWorlds.entrySet()) {
                if (isSameMatchSessionWorld(rootWorldName, entry.getValue())) requeueCandidates.add(entry.getKey());
            }
            for (Map.Entry<UUID, String> entry : spectatingMatchWorlds.entrySet()) {
                if (isSameMatchSessionWorld(rootWorldName, entry.getValue())) requeueCandidates.add(entry.getKey());
            }
        }
        if (type == QueueType.HUNGERGAMES && networkHungerGamesReservationByWorld.containsKey(rootWorldName)
            && plugin instanceof HGLootPlugin hydra && hydra.networkBridgeService() != null) {
            hydra.networkBridgeService().matchFinished(rootWorldName);
        }
        BrGenerationFlight generationFlight = brGenerationFlightsByWorld.get(rootWorldName);
        boolean replaceConsumedValousFactoryWorld = generationFlight != null
            && generationFlight.factoryManaged
            && valousReadyFactoryEnabled;
        plugin.getLogger().info("[Queue] match cleanup start: " + type.displayName() + " world=" + worldName);
        BukkitTask task = winnerReturnTasks.remove(rootWorldName);
        if (task != null) {
            task.cancel();
        }
        cancelHungerGamesKothStart(rootWorldName);
        cancelHungerGamesChestRefill(rootWorldName);
        hungerGamesChestRefillCompleted.remove(rootWorldName);
        hungerGamesDuoWorlds.remove(rootWorldName);
        hungerGamesDuoRosters.remove(rootWorldName);
        hungerGamesDuoTeamColors.remove(rootWorldName);
        if (kothService != null) {
            kothService.stopEventInWorld(rootWorldName);
        }
        endingMatchWorlds.remove(rootWorldName);
        removeFakePcsPlaneDisplay(rootWorldName);

        removeActiveMatchWorld(type, rootWorldName);
        clearActiveBrTestPlaceholders(rootWorldName);
        brDevelopmentTestWorlds.remove(rootWorldName);
        if (!hasActiveBrDevelopmentTest()) {
            brDevelopmentTestQueues.remove(QueueType.SOLO);
        }
        matchStartedAtMs.remove(rootWorldName);
        matchBorderService.clear(rootWorldName);
        sweepMatchRuntimeEntities(rootWorldName);

        for (UUID id : new ArrayList<>(inMatchPlayers)) {
            String playerWorld = inMatchWorlds.get(id);
            if (!isSameMatchSessionWorld(rootWorldName, playerWorld)) {
                continue;
            }
            Player player = Bukkit.getPlayer(id);
            if (player != null && player.isOnline()) {
                returnToHub(player, true);
            }
            inMatchPlayers.remove(id);
            inMatchTypes.remove(id);
            inMatchWorlds.remove(id);
            duoTeamByPlayer.remove(id);
            pendingSpectatorRespawnWorld.remove(id);
            matchKills.remove(id);
            hungerGamesUtilityCrafts.remove(id);
            resetMatchRewardStats(id);
            clearBattleRoyaleSnapshots(id);
        }

        for (Map.Entry<UUID, String> entry : new ArrayList<>(spectatingMatchWorlds.entrySet())) {
            if (!isSameMatchSessionWorld(rootWorldName, entry.getValue())) {
                continue;
            }
            UUID id = entry.getKey();
            spectatingMatchWorlds.remove(id);
            matchKills.remove(id);
            hungerGamesUtilityCrafts.remove(id);
            resetMatchRewardStats(id);
            clearBattleRoyaleSnapshots(id);
            Player player = Bukkit.getPlayer(id);
            if (player != null && player.isOnline()) {
                returnToHub(player, true);
            }
        }

        for (UUID id : new ArrayList<>(reconnectZombieByPlayer.keySet())) {
            String zombieWorld = inMatchWorlds.get(id);
            BattleRoyalePlayerSnapshot snapshot = brRejoinSnapshots.get(id);
            if (isSameMatchSessionWorld(rootWorldName, zombieWorld)
                || (snapshot != null && isSameMatchSessionWorld(rootWorldName, snapshot.worldName))) {
                clearBattleRoyaleSnapshots(id);
            }
        }
        syncSpectatorVisibility(rootWorldName);

        if (matchWorldAutoCleanup && managedMatchWorlds.contains(rootWorldName)) {
            cleanupWorld(rootWorldName);
        }
        if (replaceConsumedValousFactoryWorld) {
            scheduleValousFactoryReplacement(rootWorldName);
        }
        if (type != null && queueSize(type) > 0) {
            maybePrewarmMatchWorld(type);
        }
        if (completedHg && plugin instanceof HGLootPlugin hydra && hydra.playerSettingsService() != null) {
            hydra.playerSettingsService().requeueAfterCompletedSession(requeueCandidates,
                type == QueueType.HUNGERGAMES_DUOS
                    ? PlayerSettingsService.AutoQueue.HUNGER_GAMES_DUOS
                    : PlayerSettingsService.AutoQueue.HUNGER_GAMES_SOLO);
        }
    }

    private void sweepMatchRuntimeEntities(String rootWorldName) {
        if (rootWorldName == null || rootWorldName.isBlank()) {
            return;
        }
        sweepSingleMatchRuntimeWorld(rootWorldName);
        String linkedNetherWorldName = linkedNetherWorldForRoot(rootWorldName);
        if (linkedNetherWorldName != null && !linkedNetherWorldName.equals(rootWorldName)) {
            sweepSingleMatchRuntimeWorld(linkedNetherWorldName);
        }
    }

    private void sweepSingleMatchRuntimeWorld(String worldName) {
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            return;
        }
        int removed = 0;
        for (Entity entity : new ArrayList<>(world.getEntities())) {
            if (entity instanceof Player) {
                continue;
            }
            if (entity instanceof org.bukkit.entity.Item
                || entity instanceof Projectile
                || entity instanceof TNTPrimed
                || entity instanceof Firework
                || entity.getScoreboardTags().contains("hydra_reconnect_body")) {
                entity.remove();
                removed++;
            }
        }
        if (removed > 0) {
            plugin.getLogger().info("[Queue] swept " + removed + " runtime entity/entities from " + worldName);
        }
    }

    private String nextMatchWorldName(QueueType type) {
        if (type == null) {
            throw new IllegalArgumentException("QueueType is required for match world naming.");
        }
        String prefix = isHungerGames(type)
            ? HUNGER_GAMES_WORLD_NAME_PREFIX
            : BATTLE_ROYALE_WORLD_NAME_PREFIX;
        for (int attempt = 0; attempt < 200_000; attempt++) {
            long sequence = takeNextMatchWorldNumber(type);
            String worldName = prefix + sequence;
            if (Bukkit.getWorld(worldName) != null) {
                continue;
            }
            if (managedMatchWorlds.contains(worldName)) {
                continue;
            }
            Path worldFolder = Bukkit.getWorldContainer().toPath().resolve(worldName);
            if (Files.exists(worldFolder)) {
                continue;
            }
            persistMatchWorldCounters();
            return worldName;
        }
        throw new IllegalStateException("Could not allocate a unique match world name for " + type.displayName());
    }

    private long takeNextMatchWorldNumber(QueueType type) {
        if (isHungerGames(type)) {
            return nextHungerGamesWorldNumber++;
        }
        return nextBattleRoyaleWorldNumber++;
    }

    private void persistMatchWorldCounters() {
        plugin.getConfig().set("queue.match_world.next_br_world_number", nextBattleRoyaleWorldNumber);
        plugin.getConfig().set("queue.match_world.next_hg_world_number", nextHungerGamesWorldNumber);
        plugin.saveConfig();
    }

    private World createMatchWorld(QueueType type) {
        return createMatchWorld(type, null);
    }

    private World createMatchWorld(
        QueueType type,
        ValousSeedSelector.Selection valousSelection
    ) {
        if (isHungerGames(type)) {
            String worldName = nextMatchWorldName(type);
            return createHungerGamesMatchWorld(worldName, type);
        }
        if (rejectValousLiveBr(type, null, "world_create", false)) {
            return null;
        }
        boolean rejectWetCenter = shouldRejectWetBrCenter(type);
        int maxAttempts = rejectWetCenter ? BR_CENTER_DRY_SEED_MAX_ATTEMPTS : 1;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            String worldName = nextMatchWorldName(type);
            String templateWorldName = effectiveTemplateWorldName(type);
            if (!templateWorldName.isBlank()) {
                if (hasTemplateWorld(templateWorldName)) {
                    return createTemplateMatchWorld(
                        templateWorldName,
                        worldName,
                        type,
                        valousSelection
                    );
                }
                if (brTerrainProfile == BrTerrainProfile.VALOUS) {
                    logValousDatapackUnavailable();
                    return null;
                }
                plugin.getLogger().warning("[Queue] Template world '" + templateWorldName
                    + "' is not present on disk. Falling back to direct world creation for '" + worldName + "'.");
            }

            boolean legacyPluginWorldgen = useLegacyPluginWorldgen(type);
            boolean runStructures = usePluginManagedStructurePlacement(type);
            prepareMatchWorldDatapacks(worldName);
            if (runStructures) {
                prepareMatchWorldStructureTemplates(worldName);
            }

            WorldCreator creator = new WorldCreator(worldName);
            creator.environment(matchWorldEnvironment);
            creator.type(WorldType.NORMAL);
            disableSpawnRetention(creator);
            if (shouldCreateFreshRandomBrWorld(type)) {
                creator.seed(ThreadLocalRandom.current().nextLong());
            }
            if (legacyPluginWorldgen) {
                creator.generator(createBrChunkGenerator());
                creator.biomeProvider(createBrBiomeProvider());
            }
            creator.generateStructures(!runStructures);

            World world = Bukkit.createWorld(creator);
            if (world == null) {
                return null;
            }
            if (useBrTerrain(type)) {
                brMatchWorlds.add(worldName);
            } else {
                brMatchWorlds.remove(worldName);
            }
            registerValousRuntimeMode(worldName);
            if (legacyPluginWorldgen && useAeosTerrain()) {
                ensureAeosTemplateWorldSynced(world);
            }
            configureMatchWorld(world, runStructures, type);
            if (rejectWetCenter && !isBrCenterDryEnoughForCornucopia(world)) {
                cleanupWorld(worldName);
                continue;
            }
            maybeStartBrWorldPreparation(world, type);
            if (runStructures && type == QueueType.SOLO) {
                plugin.getLogger().info("[Queue] Match world '" + worldName
                    + "' is using plugin-managed BR structures on the vanilla overworld.");
            } else if (useDatapackWorldgen(type)) {
                String biomeMode = brTerrainProfile == BrTerrainProfile.HYDRA_WILDS
                    ? " as Hydra Wilds with datapack-owned terrain, biomes, and structures"
                    : "";
                if (shouldCreateFreshRandomBrWorld(type)) {
                    plugin.getLogger().info("[Queue] Match world '" + worldName
                        + "' is using fresh random datapack worldgen" + biomeMode
                        + " (no template clone, seed=" + world.getSeed() + ").");
                } else {
                    plugin.getLogger().info("[Queue] Match world '" + worldName
                        + "' is using datapack-owned structures on the vanilla overworld" + biomeMode + ".");
                }
            }
            managedMatchWorlds.add(worldName);
            managedMatchWorldTypes.put(worldName, type);
            return world;
        }
        plugin.getLogger().warning("[Queue] Failed to create a dry-center BR world after "
            + maxAttempts + " attempt(s).");
        return null;
    }

    private Location findHungerGamesKothMarkerLocation(World world) {
        return scanHungerGamesKothMarkers(world).chosen();
    }

    private MarkerScan scanHungerGamesKothMarkers(World world) {
        if (world == null) {
            return new MarkerScan(null, 0, 0, List.of());
        }
        SearchBounds bounds = hungerGamesKothSearchBounds(world);
        int minY = Math.max(world.getMinHeight() + 1, hungerGamesOriginY - HUNGER_GAMES_SPAWN_MARKER_MIN_Y_OFFSET);
        int maxY = Math.min(world.getMaxHeight() - 2, hungerGamesOriginY + HUNGER_GAMES_SPAWN_MARKER_MAX_Y_OFFSET);
        List<Location> markers = new ArrayList<>();
        for (int x = bounds.minX(); x <= bounds.maxX(); x++) {
            for (int z = bounds.minZ(); z <= bounds.maxZ(); z++) {
                if (!isChunkLoadedAt(world, x, z)) {
                    world.getChunkAt(x >> 4, z >> 4);
                }
                for (int y = maxY; y >= minY; y--) {
                    Block block = world.getBlockAt(x, y, z);
                    if (block.getType() != Material.LODESTONE) {
                        continue;
                    }
                    markers.add(new Location(world, x + 0.5D, y + 1.0D, z + 0.5D));
                    break;
                }
            }
        }
        int found = markers.size();
        if (markers.isEmpty()) {
            return new MarkerScan(null, 0, 0, List.of());
        }
        Collections.shuffle(markers);
        // Every lodestone found here is a usable marker in the current logic; none are rejected.
        return new MarkerScan(markers.get(0), found, found, List.of());
    }

    private boolean shouldRejectWetBrCenter(QueueType type) {
        return false;
    }

    private boolean isBrCenterDryEnoughForCornucopia(World world) {
        if (world == null) {
            return false;
        }
        world.getChunkAt(MID_CENTER_X >> 4, MID_CENTER_Z >> 4).load(true);
        int radius = BR_CENTER_DRY_SEED_SAMPLE_RADIUS;
        int step = Math.max(1, BR_CENTER_DRY_SEED_SAMPLE_STEP);
        int samples = 0;
        int waterColumns = 0;
        int oceanBiomes = 0;
        int wetBiomes = 0;
        int centerWaterColumns = 0;
        for (int dx = -radius; dx <= radius; dx += step) {
            for (int dz = -radius; dz <= radius; dz += step) {
                double distance = Math.hypot(dx, dz);
                if (distance > radius + 0.5D) {
                    continue;
                }
                int x = MID_CENTER_X + dx;
                int z = MID_CENTER_Z + dz;
                int chunkX = x >> 4;
                int chunkZ = z >> 4;
                if (!world.isChunkLoaded(chunkX, chunkZ)) {
                    world.getChunkAt(chunkX, chunkZ).load(true);
                }
                int surfaceY = findRealSurfaceY(world, x, z, true, false);
                Material surfaceType = world.getBlockAt(x, surfaceY, z).getType();
                boolean water = isCornucopiaWaterMaterial(surfaceType);
                String biomeKey = biomeKey(world.getBiome(x, surfaceY, z));
                boolean ocean = isBrOceanCenterBiome(biomeKey);
                boolean wet = ocean || isBrWetCenterBiome(biomeKey);
                samples++;
                if (water) {
                    waterColumns++;
                    if (distance <= 32.0D) {
                        centerWaterColumns++;
                    }
                }
                if (ocean) {
                    oceanBiomes++;
                }
                if (wet) {
                    wetBiomes++;
                }
            }
        }
        if (samples <= 0) {
            plugin.getLogger().warning("[Queue] Rejected BR world " + world.getName()
                + " because center dryness could not be sampled.");
            return false;
        }
        double waterRatio = waterColumns / (double) samples;
        double oceanRatio = oceanBiomes / (double) samples;
        double wetBiomeRatio = wetBiomes / (double) samples;
        int heightRadius = BR_CENTER_DRY_SEED_HEIGHT_SAMPLE_RADIUS;
        int heightStep = Math.max(1, BR_CENTER_DRY_SEED_HEIGHT_SAMPLE_STEP);
        int centerTop = resolveBrCenterArenaTargetTop(world);
        int heightSamples = 0;
        int minSurfaceY = Integer.MAX_VALUE;
        int maxSurfaceY = Integer.MIN_VALUE;
        int steepHeightSamples = 0;
        for (int dx = -heightRadius; dx <= heightRadius; dx += heightStep) {
            for (int dz = -heightRadius; dz <= heightRadius; dz += heightStep) {
                double distance = Math.hypot(dx, dz);
                if (distance > heightRadius + 0.5D || distance < BR_CENTER_FLAT_DISK_TEST_RADIUS - 0.5D) {
                    continue;
                }
                int x = MID_CENTER_X + dx;
                int z = MID_CENTER_Z + dz;
                int chunkX = x >> 4;
                int chunkZ = z >> 4;
                if (!world.isChunkLoaded(chunkX, chunkZ)) {
                    world.getChunkAt(chunkX, chunkZ).load(true);
                }
                int surfaceY = findRealSurfaceY(world, x, z, true, false);
                minSurfaceY = Math.min(minSurfaceY, surfaceY);
                maxSurfaceY = Math.max(maxSurfaceY, surfaceY);
                if (Math.abs(surfaceY - centerTop) > BR_CENTER_DRY_SEED_MAX_HEIGHT_DELTA) {
                    steepHeightSamples++;
                }
                heightSamples++;
            }
        }
        int heightRange = heightSamples <= 0 ? 0 : maxSurfaceY - minSurfaceY;
        double steepHeightRatio = heightSamples <= 0 ? 0.0D : steepHeightSamples / (double) heightSamples;
        boolean accepted = centerWaterColumns == 0
            && waterRatio <= BR_CENTER_DRY_SEED_MAX_WATER_RATIO
            && oceanRatio <= BR_CENTER_DRY_SEED_MAX_OCEAN_RATIO
            && wetBiomeRatio <= BR_CENTER_DRY_SEED_MAX_WET_BIOME_RATIO
            && heightSamples > 0
            && heightRange <= BR_CENTER_DRY_SEED_MAX_HEIGHT_RANGE
            && steepHeightRatio <= BR_CENTER_DRY_SEED_MAX_STEEP_HEIGHT_RATIO;
        if (accepted) {
            plugin.getLogger().info("[Queue] Accepted BR center for " + world.getName()
                + " (samples=" + samples
                + ", waterRatio=" + formatRatio(waterRatio)
                + ", oceanRatio=" + formatRatio(oceanRatio)
                + ", wetBiomeRatio=" + formatRatio(wetBiomeRatio)
                + ", centerTop=" + centerTop
                + ", heightRange=" + heightRange
                + ", steepHeightRatio=" + formatRatio(steepHeightRatio) + ").");
            return true;
        }
        plugin.getLogger().info("[Queue] Rejected BR world " + world.getName()
            + " because center is too wet/steep for Cornucopia"
            + " (samples=" + samples
            + ", waterColumns=" + waterColumns
            + ", centerWaterColumns=" + centerWaterColumns
            + ", oceanBiomes=" + oceanBiomes
            + ", wetBiomes=" + wetBiomes
            + ", waterRatio=" + formatRatio(waterRatio)
            + ", oceanRatio=" + formatRatio(oceanRatio)
            + ", wetBiomeRatio=" + formatRatio(wetBiomeRatio)
            + ", heightSamples=" + heightSamples
            + ", centerTop=" + centerTop
            + ", minSurfaceY=" + (heightSamples <= 0 ? "n/a" : Integer.toString(minSurfaceY))
            + ", maxSurfaceY=" + (heightSamples <= 0 ? "n/a" : Integer.toString(maxSurfaceY))
            + ", heightRange=" + heightRange
            + ", steepHeightRatio=" + formatRatio(steepHeightRatio) + ").");
        return false;
    }

    private static boolean isBrOceanCenterBiome(String biomeKey) {
        return biomeKey != null && biomeKey.contains("ocean");
    }

    private static boolean isBrWetCenterBiome(String biomeKey) {
        if (biomeKey == null) {
            return false;
        }
        return biomeKey.contains("shore")
            || biomeKey.contains("beach")
            || biomeKey.contains("river")
            || biomeKey.contains("swamp")
            || biomeKey.contains("flood");
    }

    private static String formatRatio(double value) {
        return String.format(Locale.ROOT, "%.3f", value);
    }

    private CompletableFuture<World> createMatchWorldAsync(QueueType type) {
        if (isBattleRoyaleType(type)) {
            return acquireBrGenerationFlight(type);
        }
        if (!isHungerGames(type)) {
            return CompletableFuture.completedFuture(createMatchWorld(type));
        }
        String worldName = nextMatchWorldName(type);
        return createHungerGamesMatchWorldAsync(worldName, type);
    }

    private CompletableFuture<World> acquireBrGenerationFlight(QueueType type) {
        return acquireBrGenerationFlight(type, false);
    }

    private CompletableFuture<World> acquireBrGenerationFlight(QueueType type, boolean factoryRequest) {
        if (!isBattleRoyaleType(type)) {
            return CompletableFuture.completedFuture(null);
        }
        BrGenerationKey key = new BrGenerationKey(type, brTerrainProfile);
        BrGenerationCompatibility compatibility = currentBrGenerationCompatibility(type);
        synchronized (brGenerationFlights) {
            if (brTerrainProfile == BrTerrainProfile.VALOUS) {
                if (factoryRequest) {
                    BrGenerationFlight compatibleExisting = brGenerationFlights.values().stream()
                        .filter(flight -> flight.key.terrainProfile() == BrTerrainProfile.VALOUS)
                        .filter(flight -> !flight.isTerminal())
                        .filter(flight -> flight.compatibility.equals(compatibility))
                        .findFirst()
                        .orElse(null);
                    if (compatibleExisting != null) {
                        compatibleExisting.factoryManaged = true;
                        logBrGenerationEvent(compatibleExisting, "reused", "adopted_by_valous_factory");
                        return compatibleExisting.completionFuture;
                    }
                }
                BrGenerationFlight sharedFactory = findCompatibleValousFactoryFlight(compatibility);
                if (sharedFactory != null) {
                    if (factoryRequest) {
                        sharedFactory.factoryManaged = true;
                    }
                    logBrGenerationEvent(sharedFactory, "reused", "compatible_valous_factory");
                    return sharedFactory.completionFuture;
                }
            }
            BrGenerationFlight existing = brGenerationFlights.get(key);
            if (existing != null && !existing.isTerminal()) {
                if (existing.compatibility.equals(compatibility)) {
                    if (factoryRequest) {
                        existing.factoryManaged = true;
                    }
                    logBrGenerationEvent(existing, "reused", "compatible_single_flight");
                    return existing.completionFuture;
                }
                if (existing.isClaimed()) {
                    plugin.getLogger().warning("[Queue][BrGeneration] event=replacement_rejected queue="
                        + type.key() + " world=" + existing.worldName + " reason=claimed_incompatible");
                    return CompletableFuture.failedFuture(
                        new IllegalStateException("The existing BR generation is claimed and cannot be replaced."));
                }
                cancelBrGenerationFlight(existing, "incompatible_generation_request", true);
            }

            BrGenerationFlight flight = new BrGenerationFlight(key, compatibility);
            if (brTerrainProfile == BrTerrainProfile.VALOUS) {
                flight.valousPolicy = valousSelectionPolicy(valousGenerationSize);
            }
            flight.factoryManaged = factoryRequest;
            brGenerationFlights.put(key, flight);
            logBrGenerationEvent(flight, "created",
                factoryRequest ? "valous_factory_single_flight_registered" : "single_flight_registered");
            if (brTerrainProfile == BrTerrainProfile.VALOUS) {
                try {
                    ValousSeedSelector.prepare();
                } catch (RuntimeException ex) {
                    failBrGenerationFlight(
                        flight,
                        "seed_selector_prepare_exception:" + ex.getClass().getSimpleName()
                    );
                    plugin.getLogger().log(
                        java.util.logging.Level.SEVERE,
                        "[Queue][ValousTerrain] event=seed_selector_prepare_failed queue=" + type.key(),
                        ex
                    );
                    return flight.completionFuture;
                }
                CompletableFuture
                    .supplyAsync(() -> ValousSeedSelector.select(
                        flight.valousPolicy,
                        valousDiagnosticSeedFallbackEnabled
                    ))
                    .whenComplete((selection, error) -> {
                        if (!plugin.isEnabled()) {
                            return;
                        }
                        Bukkit.getScheduler().runTask(
                            plugin,
                            () -> completeValousFlightWorldCreation(flight, type, selection, error)
                        );
                    });
                logBrGenerationEvent(flight, "seed_search_started", "async_quality_selection");
                return flight.completionFuture;
            }

            World world = createBrGenerationFlightWorld(flight, type, null);
            registerCreatedBrGenerationWorld(flight, world);
            return flight.completionFuture;
        }
    }

    private void completeValousFlightWorldCreation(
        BrGenerationFlight flight,
        QueueType type,
        ValousSeedSelector.Selection selection,
        Throwable error
    ) {
        synchronized (brGenerationFlights) {
            if (!isCurrentBrGenerationFlight(flight) || flight.canceled || flight.isTerminal()) {
                plugin.getLogger().info("[Queue][BrGeneration] event=stale_seed_search_ignored queue="
                    + type.key() + " token=" + flight.token);
                return;
            }
            if (error != null || selection == null) {
                failBrGenerationFlight(
                    flight,
                    "seed_selection_exception:"
                        + (error == null ? "empty_result" : error.getClass().getSimpleName())
                );
                plugin.getLogger().log(
                    java.util.logging.Level.SEVERE,
                    "[Queue][ValousTerrain] event=seed_selection_failed queue=" + type.key()
                        + " token=" + flight.token,
                    error
                );
                return;
            }
            flight.seedSelectionMs = selection.selectionMs();
            flight.valousPolicy = selection.policy();
            flight.valousSeedSelection = selection;
            World world = createBrGenerationFlightWorld(flight, type, selection);
            registerCreatedBrGenerationWorld(flight, world);
        }
    }

    private static ValousSeedSelector.Policy valousSelectionPolicy(ValousGenerationSize size) {
        ValousGenerationSize resolved = size == null ? ValousGenerationSize.FULL : size;
        return switch (resolved) {
            case QUICK -> ValousSeedSelector.Policy.QUICK_PROTOTYPE;
            case MEDIUM -> ValousSeedSelector.Policy.MEDIUM_VALIDATION;
            case FULL -> ValousSeedSelector.Policy.FULL_PRODUCTION;
        };
    }

    private World createBrGenerationFlightWorld(
        BrGenerationFlight flight,
        QueueType type,
        ValousSeedSelector.Selection selection
    ) {
        brGenerationFlightCreationContext.set(flight);
        try {
            return createMatchWorld(type, selection);
        } catch (RuntimeException ex) {
            failBrGenerationFlight(
                flight,
                "world_creation_exception:" + ex.getClass().getSimpleName()
            );
            plugin.getLogger().log(
                java.util.logging.Level.SEVERE,
                "[Queue][BrGeneration] BR world creation failed for " + type.displayName() + ".",
                ex
            );
            return null;
        } finally {
            brGenerationFlightCreationContext.remove();
        }
    }

    private void registerCreatedBrGenerationWorld(BrGenerationFlight flight, World world) {
        if (flight.completionFuture.isDone()) {
            return;
        }
        if (world == null) {
            failBrGenerationFlight(flight, "world_creation_returned_null");
            return;
        }
        flight.worldName = world.getName();
        flight.seed = world.getSeed();
        brGenerationFlightsByWorld.put(world.getName(), flight);
        transitionBrGenerationFlight(flight, BrGenerationState.PREGENERATING, "world_created");
        BrWorldPreparationState preparation = brWorldPreparationStates.get(world.getName());
        if (preparation != null && preparation.phase == BrWorldPreparationPhase.READY) {
            completeBrGenerationFlightReady(flight, world);
        }
    }

    private BrGenerationFlight findCompatibleValousFactoryFlight(BrGenerationCompatibility compatibility) {
        if (compatibility == null) {
            return null;
        }
        return brGenerationFlights.values().stream()
            .filter(flight -> flight.factoryManaged)
            .filter(flight -> flight.key.terrainProfile() == BrTerrainProfile.VALOUS)
            .filter(flight -> !flight.isTerminal())
            .filter(flight -> flight.compatibility.equals(compatibility))
            .findFirst()
            .orElse(null);
    }

    private BrGenerationFlight currentValousFactoryFlight() {
        return brGenerationFlights.values().stream()
            .filter(flight -> flight.factoryManaged)
            .filter(flight -> flight.key.terrainProfile() == BrTerrainProfile.VALOUS)
            .filter(flight -> !flight.isTerminal())
            .findFirst()
            .orElse(null);
    }

    private BrGenerationCompatibility currentBrGenerationCompatibility(QueueType type) {
        return new BrGenerationCompatibility(
            BR_GENERATION_VERSION,
            currentBrDatapackVersion(),
            effectiveBrTerrainBorderDiameter(),
            effectiveBrTerrainPreloadDiameter(),
            matchWorldGenerationMode.name(),
            effectiveTemplateWorldName(type),
            usePluginManagedStructurePlacement(type),
            matchWorldEnvironment.name(),
            brTerrainProfile == BrTerrainProfile.VALOUS ? valousGenerationSize.key : "production",
            String.join(",",
                "map=" + brTerrainMapDiameter,
                "originSpawn=" + brForceOriginSpawn,
                "vertical=" + brTerrainMinYHint + ":" + brTerrainMaxYHint,
                "cornucopia=" + cornucopiaStructureId,
                "templateStructures=" + matchWorldTemplateRunStructures,
                "structureData=" + matchStructureDataFile
            )
        );
    }

    private String currentBrDatapackVersion() {
        Path path = brTerrainProfile == BrTerrainProfile.VALOUS
            ? Bukkit.getWorldContainer().toPath().resolve(VALOUS_TEMPLATE_WORLD_NAME)
                .resolve("datapacks").resolve(VALOUS_DATAPACK_FILE_NAME)
            : resolveMatchWorldDatapackSourcePath();
        try {
            if (path != null && Files.isRegularFile(path)) {
                return path.getFileName() + ":" + Files.size(path) + ":" + Files.getLastModifiedTime(path).toMillis();
            }
        } catch (IOException ignored) {
            // The missing/unreadable source is reflected in the fingerprint below.
        }
        return path == null ? "none" : path.toAbsolutePath().normalize() + ":unavailable";
    }

    private boolean claimBrGenerationFlight(QueueType type, UUID reservationId) {
        if (!isBattleRoyaleType(type) || reservationId == null) {
            return false;
        }
        BrGenerationFlight flight = brTerrainProfile == BrTerrainProfile.VALOUS
            ? findCompatibleValousFactoryFlight(currentBrGenerationCompatibility(type))
            : null;
        if (flight == null || flight.isTerminal()) {
            flight = brGenerationFlights.get(new BrGenerationKey(type, brTerrainProfile));
        }
        if (flight == null || flight.isTerminal()) {
            return false;
        }
        synchronized (flight) {
            if ((flight.ownerReservationId != null && !flight.ownerReservationId.equals(reservationId))
                || (flight.claimedQueueType != null && flight.claimedQueueType != type)) {
                plugin.getLogger().warning("[Queue][BrGeneration] event=claim_rejected queue=" + type.key()
                    + " token=" + flight.token + " world=" + flight.worldName + " reason=already_claimed");
                return false;
            }
            flight.ownerReservationId = reservationId;
            flight.claimedQueueType = type;
            transitionBrGenerationFlight(flight, BrGenerationState.CLAIMED, "pending_match_claimed");
            return true;
        }
    }

    private void claimReadyBrGenerationForStart(QueueType type, String worldName) {
        BrGenerationFlight flight = brGenerationFlightsByWorld.get(worldName);
        if (flight == null
            || (!flight.factoryManaged && flight.key.queueType() != type)
            || (flight.claimedQueueType != null && flight.claimedQueueType != type)
            || flight.isTerminal()) {
            return;
        }
        synchronized (flight) {
            if (flight.ownerReservationId == null) {
                flight.ownerReservationId = UUID.randomUUID();
            }
            flight.claimedQueueType = type;
            transitionBrGenerationFlight(flight, BrGenerationState.CLAIMED, "ready_world_claimed_for_start");
        }
    }

    private void completeBrGenerationFlightReady(BrGenerationFlight flight, World world) {
        if (!isCurrentBrGenerationFlight(flight) || flight.canceled || world == null) {
            return;
        }
        if (flight.state == BrGenerationState.ACTIVE || flight.completionFuture.isDone()) {
            return;
        }
        flight.generatedChunks = Math.max(flight.generatedChunks, flight.totalChunks);
        transitionBrGenerationFlight(
            flight,
            flight.ownerReservationId == null ? BrGenerationState.READY : BrGenerationState.CLAIMED,
            "preparation_ready"
        );
        flight.completionFuture.complete(world);
    }

    private void failBrGenerationFlight(BrGenerationFlight flight, String reason) {
        if (flight == null) {
            return;
        }
        flight.failureReason = reason;
        transitionBrGenerationFlight(flight, BrGenerationState.FAILED, reason);
        brGenerationFlights.remove(flight.key, flight);
        if (!"pending".equals(flight.worldName)) {
            brGenerationFlightsByWorld.remove(flight.worldName, flight);
        }
        flight.completionFuture.complete(null);
    }

    private void cancelBrGenerationFlight(BrGenerationFlight flight, String reason, boolean deleteWorld) {
        if (flight == null || flight.state == BrGenerationState.ACTIVE || flight.isClaimed()) {
            return;
        }
        synchronized (flight) {
            if (flight.canceled || flight.state == BrGenerationState.ACTIVE || flight.isClaimed()) {
                return;
            }
            flight.canceled = true;
            flight.failureReason = reason;
            transitionBrGenerationFlight(flight, BrGenerationState.CANCELING, reason);
        }
        brGenerationFlights.remove(flight.key, flight);
        if (!"pending".equals(flight.worldName)) {
            brGenerationFlightsByWorld.remove(flight.worldName, flight);
            WorldChunkPreloadState preload = fullWorldPreloadStates.remove(flight.worldName);
            if (preload != null && preload.task != null) {
                preload.task.cancel();
            }
            brWorldPreparationStates.remove(flight.worldName);
        }
        flight.completionFuture.complete(null);
        if (deleteWorld && !"pending".equals(flight.worldName)
            && !activeMatchWorldsFor(flight.key.queueType()).contains(flight.worldName)) {
            cleanupWorld(flight.worldName);
        }
    }

    private boolean isCurrentBrGenerationFlight(BrGenerationFlight flight) {
        return flight != null
            && brGenerationFlights.get(flight.key) == flight
            && ("pending".equals(flight.worldName)
                || brGenerationFlightsByWorld.get(flight.worldName) == flight);
    }

    private void transitionBrGenerationFlight(
        BrGenerationFlight flight,
        BrGenerationState next,
        String reason
    ) {
        if (flight == null || next == null) {
            return;
        }
        BrGenerationState previous;
        synchronized (flight) {
            previous = flight.state;
            if (previous == next) {
                return;
            }
            flight.state = next;
        }
        plugin.getLogger().info("[Queue][BrGeneration] event=state_transition queue="
            + flight.key.queueType().key() + " profile=" + flight.key.terrainProfile().configKey()
            + " world=" + flight.worldName + " token=" + flight.token
            + " from=" + previous + " to=" + next + " reason=" + reason);
    }

    private void logBrGenerationEvent(BrGenerationFlight flight, String event, String reason) {
        plugin.getLogger().info("[Queue][BrGeneration] event=" + event
            + " queue=" + flight.key.queueType().key()
            + " profile=" + flight.key.terrainProfile().configKey()
            + " world=" + flight.worldName + " token=" + flight.token + " reason=" + reason);
    }

    private World createHungerGamesMatchWorld(String worldName, QueueType type) {
        markHungerGamesPreparationStage(worldName, HungerGamesPreparationStage.PREWARM_STARTED);
        World world = createHungerGamesMatchWorldBase(worldName, type);
        if (world == null) {
            return null;
        }
        HungerGamesMapDefinition selectedMap = chooseHungerGamesMapForMatch();
        String selectedStructureId = selectedMap == null
            ? hungerGamesStructureId
            : normalizeStructureId(selectedMap.structureId());
        String selectedMapName = selectedMap == null ? hungerGamesMapName : selectedMap.displayName();
        if (!placeHungerGamesMap(world, selectedStructureId, selectedMapName)) {
            cleanupWorld(worldName);
            return null;
        }
        markHungerGamesPreparationStage(worldName, HungerGamesPreparationStage.PRELOAD_COMPLETE);
        markHungerGamesPreparationStage(worldName, HungerGamesPreparationStage.STRUCTURE_PASTE_COMPLETE);
        markHungerGamesPreparationStage(worldName, HungerGamesPreparationStage.LOOT_COMPLETE);
        return finalizeHungerGamesMatchWorld(world, selectedMap, selectedMapName, selectedStructureId, type);
    }

    private CompletableFuture<World> createHungerGamesMatchWorldAsync(String worldName) {
        return createHungerGamesMatchWorldAsync(worldName, QueueType.HUNGERGAMES);
    }

    private CompletableFuture<World> createHungerGamesMatchWorldAsync(String worldName, QueueType type) {
        CompletableFuture<World> future = new CompletableFuture<>();
        markHungerGamesPreparationStage(worldName, HungerGamesPreparationStage.PREWARM_STARTED);
        Bukkit.getScheduler().runTask(plugin, () -> {
            World world = createHungerGamesMatchWorldBase(worldName, type);
            if (world == null) {
                future.complete(null);
                return;
            }
            HungerGamesMapDefinition selectedMap = chooseHungerGamesMapForMatch();
            String selectedMapName = selectedMap == null ? hungerGamesMapName : selectedMap.displayName();
            String normalizedStructureId = selectedMap == null
                ? normalizeStructureId(hungerGamesStructureId)
                : normalizeStructureId(selectedMap.structureId());
            CompletableFuture
                .supplyAsync(() -> resolveHydraStructure(normalizedStructureId))
                .whenComplete((structure, structureError) -> Bukkit.getScheduler().runTask(plugin, () -> {
                    if (structureError != null) {
                        plugin.getLogger().warning("[Queue] async HG structure load failed for "
                            + normalizedStructureId + " in " + worldName + ": " + structureError.getMessage());
                        cleanupWorld(worldName);
                        future.complete(null);
                        return;
                    }
                    if (structure == null) {
                        plugin.getLogger().warning("Could not load Hunger Games map structure " + normalizedStructureId + ".");
                        cleanupWorld(worldName);
                        future.complete(null);
                        return;
                    }

                    BlockVector size = structure.getSize();
                    int pasteX = -Math.floorDiv(Math.max(1, size.getBlockX()), 2);
                    int pasteZ = -Math.floorDiv(Math.max(1, size.getBlockZ()), 2);
                    int pasteY = hungerGamesOriginY;
                    long preloadStartedAt = System.currentTimeMillis();
                    preloadStructureFootprintAsync(world, structure, pasteX, pasteZ, 1, true)
                        .whenComplete((loaded, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
                            if (error != null) {
                                plugin.getLogger().warning("[Queue] async HG map footprint preload failed for "
                                    + normalizedStructureId + " in " + worldName + ": " + error.getMessage());
                                cleanupWorld(worldName);
                                future.complete(null);
                                return;
                            }
                            if (!Boolean.TRUE.equals(loaded)) {
                                plugin.getLogger().warning("[Queue] async HG map footprint preload failed for "
                                    + normalizedStructureId + " in " + worldName + ".");
                                cleanupWorld(worldName);
                                future.complete(null);
                                return;
                            }
                            markHungerGamesPreparationStage(worldName, HungerGamesPreparationStage.PRELOAD_COMPLETE);
                            long preloadElapsed = System.currentTimeMillis() - preloadStartedAt;
                            if (preloadElapsed >= 1000L) {
                                plugin.getLogger().info("[Queue] Async-preloaded HG map footprint for " + normalizedStructureId
                                    + " in " + worldName + " in " + preloadElapsed + "ms.");
                            }
                            placeHydraStructurePaletteNoPhysicsAsync(world, normalizedStructureId, structure, pasteX, pasteY, pasteZ)
                                .whenComplete((placed, placeError) -> Bukkit.getScheduler().runTask(plugin, () -> {
                                    if (placeError != null || !Boolean.TRUE.equals(placed)) {
                                        cleanupWorld(worldName);
                                        future.complete(null);
                                        return;
                                    }
                                    markHungerGamesPreparationStage(
                                        worldName, HungerGamesPreparationStage.STRUCTURE_PASTE_COMPLETE);
                                    plugin.getLogger().info("[Queue] Pasted Hunger Games map " + selectedMapName + " (" + normalizedStructureId + ") at "
                                        + pasteX + "," + pasteY + "," + pasteZ + " in " + world.getName());
                                    if (hungerGamesFillChests) {
                                        populateHungerGamesMapLoot(world, normalizedStructureId, pasteX, pasteY, pasteZ, size, hungerGamesLootPlan(world.getName()));
                                    }
                                    markHungerGamesPreparationStage(worldName, HungerGamesPreparationStage.LOOT_COMPLETE);
                                    future.complete(finalizeHungerGamesMatchWorld(
                                        world, selectedMap, selectedMapName, normalizedStructureId, type));
                                }));
                        }));
                }));
        });
        return future;
    }

    private World createHungerGamesMatchWorldBase(String worldName, QueueType type) {
        if (!hungerGamesEnabled) {
            plugin.getLogger().warning("Hunger Games queue is enabled in menus, but queue.hunger_games.enabled=false.");
            return null;
        }
        if (hungerGamesStructureId.isBlank()) {
            plugin.getLogger().warning("Hunger Games map is not configured. Set queue.hunger_games.structure_id.");
            return null;
        }

        prepareMatchWorldDatapacks(worldName);

        WorldCreator creator = new WorldCreator(worldName);
        creator.environment(matchWorldEnvironment);
        creator.type(WorldType.NORMAL);
        disableSpawnRetention(creator);
        creator.generator(new EmptyChunkGenerator(hungerGamesOriginY + 4));
        creator.biomeProvider(new PlainsBiomeProvider());
        creator.generateStructures(false);

        World world = Bukkit.createWorld(creator);
        if (world == null) {
            return null;
        }
        brMatchWorlds.remove(worldName);
        managedMatchWorldTypes.put(worldName, type);
        markHungerGamesPreparationStage(worldName, HungerGamesPreparationStage.WORLD_CREATED);
        return world;
    }

    private World finalizeHungerGamesMatchWorld(
        World world,
        HungerGamesMapDefinition selectedMap,
        String mapName,
        String structureId,
        QueueType type
    ) {
        if (world == null) {
            return null;
        }
        world.getChunkAt(0, 0);
        int spawnY = world.getHighestBlockYAt(0, 0) + 1;
        if (spawnY <= world.getMinHeight()) {
            spawnY = Math.max(world.getMinHeight() + 1, hungerGamesOriginY + 2);
        }
        world.setSpawnLocation(0, spawnY, 0);
        hungerGamesMapKeysByWorld.put(
            world.getName(),
            selectedMap == null ? normalizeHungerGamesMapKey(mapName) : selectedMap.key()
        );
        configureMatchWorld(world, false, type);
        holdHungerGamesReadySpawnChunk(world);
        managedMatchWorlds.add(world.getName());
        managedMatchWorldTypes.put(world.getName(), type);
        markHungerGamesPreparationStage(world.getName(), HungerGamesPreparationStage.READY);
        plugin.getLogger().info("Created Hunger Games world '" + world.getName() + "' using map "
            + mapName + " (" + structureId + ").");
        return world;
    }

    private void holdHungerGamesReadySpawnChunk(World world) {
        if (world == null) {
            return;
        }
        Location spawn = world.getSpawnLocation();
        world.getChunkAt(spawn.getBlockX() >> 4, spawn.getBlockZ() >> 4).addPluginChunkTicket(plugin);
    }

    private void releaseHungerGamesReadySpawnChunk(String worldName) {
        World world = worldName == null ? null : Bukkit.getWorld(worldName);
        if (world == null) {
            return;
        }
        Location spawn = world.getSpawnLocation();
        world.getChunkAt(spawn.getBlockX() >> 4, spawn.getBlockZ() >> 4).removePluginChunkTicket(plugin);
    }

    private void markHungerGamesPreparationStage(String worldName, HungerGamesPreparationStage stage) {
        if (worldName == null || worldName.isBlank() || stage == null) {
            return;
        }
        long now = System.currentTimeMillis();
        if (stage == HungerGamesPreparationStage.PREWARM_STARTED) {
            hungerGamesPreparationStartedAtMs.put(worldName, now);
        }
        hungerGamesPreparationStages.put(worldName, stage);
        long elapsed = now - hungerGamesPreparationStartedAtMs.getOrDefault(worldName, now);
        plugin.getLogger().info("[Queue][HGPreparation] event=" + stage.name().toLowerCase(Locale.ROOT)
            + " world=" + worldName + " elapsed_ms=" + elapsed);
    }

    private boolean placeHungerGamesMap(World world, String structureId) {
        if (world == null || structureId == null || structureId.isBlank()) {
            return false;
        }
        String normalizedStructureId = normalizeStructureId(structureId);
        Structure structure = resolveHydraStructure(normalizedStructureId);
        if (structure == null) {
            plugin.getLogger().warning("Could not load Hunger Games map structure " + normalizedStructureId + ".");
            return false;
        }
        return placeHungerGamesMap(world, normalizedStructureId, hungerGamesMapName, structure, true);
    }

    private boolean placeHungerGamesMap(World world, String structureId, String mapName) {
        if (world == null || structureId == null || structureId.isBlank()) {
            return false;
        }
        String normalizedStructureId = normalizeStructureId(structureId);
        Structure structure = resolveHydraStructure(normalizedStructureId);
        if (structure == null) {
            plugin.getLogger().warning("Could not load Hunger Games map structure " + normalizedStructureId + ".");
            return false;
        }
        return placeHungerGamesMap(world, normalizedStructureId, mapName, structure, true);
    }

    private boolean placeHungerGamesMap(World world, String structureId, String mapName, Structure structure, boolean manualPaste) {
        if (world == null || structureId == null || structureId.isBlank() || structure == null) {
            return false;
        }
        BlockVector size = structure.getSize();
        int pasteX = -Math.floorDiv(Math.max(1, size.getBlockX()), 2);
        int pasteZ = -Math.floorDiv(Math.max(1, size.getBlockZ()), 2);
        int pasteY = hungerGamesOriginY;
        HungerGamesLootPlan lootPlan = hungerGamesLootPlan(world.getName());
        boolean placed = manualPaste
            ? placeHydraStructurePaletteNoPhysics(world, structureId, structure, pasteX, pasteY, pasteZ)
            : placeHydraStructureDirectly(world, structureId, pasteX, pasteY, pasteZ);
        if (placed) {
            plugin.getLogger().info("[Queue] Pasted Hunger Games map " + mapName + " (" + structureId + ") at "
                + pasteX + "," + pasteY + "," + pasteZ + " in " + world.getName());
            if (hungerGamesFillChests) {
                populateHungerGamesMapLoot(world, structureId, pasteX, pasteY, pasteZ, size, lootPlan);
            }
        }
        return placed;
    }

    private void populateHungerGamesMapLoot(
        World world,
        String structureId,
        int pasteX,
        int pasteY,
        int pasteZ,
        BlockVector size,
        HungerGamesLootPlan lootPlan
    ) {
        if (world == null || size == null || managedLootService == null || lootPlan == null) {
            return;
        }
        List<Block> containers = collectHungerGamesMapContainers(world, pasteX, pasteY, pasteZ, size);
        if (containers.isEmpty()) {
            plugin.getLogger().warning("[Loot] No HG containers found for " + structureId + " in " + world.getName() + ".");
            return;
        }
        List<String> initialTableIds = lootPlan.initialTableIds();
        if (initialTableIds.isEmpty()) {
            plugin.getLogger().warning("[Loot] No HG initial loot tables configured for " + world.getName() + ".");
            return;
        }
        Collections.shuffle(containers);
        int filled = 0;
        int totalGenerated = 0;
        String lootGroup = hungerGamesLootGroup(world);
        for (int i = 0; i < containers.size(); i++) {
            String tableId = initialTableIds.get(i % initialTableIds.size());
            int generated = managedLootService.populateManagedContainer(
                containers.get(i),
                tableId,
                ManagedLootService.SOURCE_HG_MAP,
                lootGroup
            );
            if (generated > 0) {
                tuneHungerGamesContainerLoot(containers.get(i), false);
                filled++;
                totalGenerated += generated;
            }
        }
        plugin.getLogger().info("[Loot] Filled " + filled + "/" + containers.size() + " containers for "
            + structureId + " in " + world.getName() + " using HG pool " + initialTableIds
            + ". Generated stacks=" + totalGenerated + ".");
    }

    private void refillHungerGamesMapLoot(World world, HungerGamesLootPlan lootPlan) {
        if (world == null || lootPlan == null || managedLootService == null) {
            return;
        }
        List<String> refillTableIds = lootPlan.refillTableIds();
        if (refillTableIds.isEmpty()) {
            return;
        }
        List<Block> containers = managedLootService.collectManagedContainers(
            world,
            ManagedLootService.SOURCE_HG_MAP,
            hungerGamesLootGroup(world)
        );
        if (containers.isEmpty()) {
            plugin.getLogger().warning("[Loot] No HG containers found for refill in " + world.getName() + ".");
            return;
        }
        Collections.shuffle(containers);
        int refillTarget = Math.max(1, (int) Math.round(containers.size() * hungerGamesChestRefillFillRatio));
        refillTarget = Math.min(refillTarget, containers.size());

        int refilled = 0;
        int totalGenerated = 0;
        for (int i = 0; i < refillTarget; i++) {
            Block containerBlock = containers.get(i);
            String tableId = refillTableIds.get(i % refillTableIds.size());
            int generated = managedLootService.populateManagedContainer(
                containerBlock,
                tableId,
                ManagedLootService.SOURCE_HG_MAP,
                hungerGamesLootGroup(world)
            );
            if (generated > 0) {
                tuneHungerGamesContainerLoot(containerBlock, true);
                refilled++;
                totalGenerated += generated;
            }
        }
        plugin.getLogger().info("[Loot] Refilled " + refilled + "/" + refillTarget + " targeted HG containers in "
            + world.getName() + " using refill pool " + refillTableIds + ". Generated stacks=" + totalGenerated + ".");
    }

    private void tuneHungerGamesContainerLoot(Block block, boolean refillLoot) {
        if (!(block.getState() instanceof Container container)) {
            return;
        }
        Inventory inventory = container.getInventory();
        if (inventory == null) {
            return;
        }

        if (!(container instanceof Chest)) {
            container.update(true, false);
        }
    }

    private HungerGamesLootPlan hungerGamesLootPlan(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return new HungerGamesLootPlan(List.of(), List.of());
        }
        HungerGamesLootPlan existing = hungerGamesLootPlans.get(worldName);
        if (existing != null) {
            return existing;
        }
        List<String> initialTableIds = new ArrayList<>(hungerGamesInitialLootTableIds);
        List<String> refillTableIds = new ArrayList<>(hungerGamesRefillLootTableIds);
        Collections.shuffle(initialTableIds);
        Collections.shuffle(refillTableIds);
        HungerGamesLootPlan plan = new HungerGamesLootPlan(List.copyOf(initialTableIds), List.copyOf(refillTableIds));
        hungerGamesLootPlans.put(worldName, plan);
        return plan;
    }

    private String hungerGamesLootGroup(World world) {
        return world == null ? null : "hg-map:" + world.getName();
    }

    private static List<String> expandWeightedTables(List<Map.Entry<String, Integer>> weights) {
        List<String> expanded = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : weights) {
            int count = Math.max(0, entry.getValue());
            for (int i = 0; i < count; i++) {
                expanded.add(entry.getKey());
            }
        }
        return List.copyOf(expanded);
    }

    private List<String> normalizeHungerGamesLootTableIds(List<String> configuredIds, List<String> fallbackIds) {
        List<String> normalized = new ArrayList<>();
        appendHungerGamesLootTableIds(normalized, configuredIds);
        if (normalized.isEmpty()) {
            appendHungerGamesLootTableIds(normalized, fallbackIds);
        }
        return normalized;
    }

    private void appendHungerGamesLootTableIds(List<String> output, List<String> rawIds) {
        if (rawIds == null) {
            return;
        }
        for (String rawId : rawIds) {
            if (rawId == null) {
                continue;
            }
            String value = rawId.trim();
            if (value.isBlank()) {
                continue;
            }
            LootCategory category = LootCategory.fromKey(value).orElse(null);
            if (category != null) {
                for (int index = 1; index <= category.chestCount(); index++) {
                    String tableId = category.tableId(index);
                    if (!output.contains(tableId)) {
                        output.add(tableId);
                    }
                }
                continue;
            }
            if (!output.contains(value)) {
                output.add(value);
            }
        }
    }

    private List<HungerGamesStrongPoint> defaultHungerGamesKothStrongPoints() {
        return List.of(
            new HungerGamesStrongPoint("Center", 0, 0),
            new HungerGamesStrongPoint("North", 0, -56),
            new HungerGamesStrongPoint("South", 0, 56),
            new HungerGamesStrongPoint("East", 56, 0),
            new HungerGamesStrongPoint("West", -56, 0),
            new HungerGamesStrongPoint("North-East", 56, -56),
            new HungerGamesStrongPoint("North-West", -56, -56),
            new HungerGamesStrongPoint("South-East", 56, 56),
            new HungerGamesStrongPoint("South-West", -56, 56)
        );
    }

    private List<HungerGamesStrongPoint> loadConfiguredHungerGamesKothStrongPoints() {
        List<HungerGamesStrongPoint> points = new ArrayList<>();
        for (Map<?, ?> entry : plugin.getConfig().getMapList("queue.hunger_games.koth_strong_points")) {
            Integer x = intValue(entry.get("x"));
            Integer z = intValue(entry.get("z"));
            if (x == null || z == null) {
                continue;
            }
            String name = entry.get("name") == null ? "" : entry.get("name").toString().trim();
            points.add(new HungerGamesStrongPoint(name, x, z));
        }
        if (points.isEmpty()) {
            points.addAll(defaultHungerGamesKothStrongPoints());
        }
        return points;
    }

    private List<Map<String, Object>> serializeHungerGamesKothStrongPoints() {
        List<Map<String, Object>> serialized = new ArrayList<>();
        for (HungerGamesStrongPoint strongPoint : hungerGamesKothStrongPoints) {
            Map<String, Object> entry = new LinkedHashMap<>();
            if (!strongPoint.name().isBlank()) {
                entry.put("name", strongPoint.name());
            }
            entry.put("x", strongPoint.x());
            entry.put("z", strongPoint.z());
            serialized.add(entry);
        }
        return serialized;
    }

    private Integer intValue(Object raw) {
        if (raw instanceof Number number) {
            return number.intValue();
        }
        if (raw == null) {
            return null;
        }
        try {
            return Integer.parseInt(raw.toString().trim());
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

    private static double clamp(double value, double min, double max) {
        return Math.max(min, Math.min(max, value));
    }

    private List<Block> collectHungerGamesMapContainers(
        World world,
        int pasteX,
        int pasteY,
        int pasteZ,
        BlockVector size
    ) {
        if (world == null || size == null) {
            return List.of();
        }
        int minX = pasteX - HUNGER_GAMES_LOOT_SCAN_PADDING;
        int maxX = pasteX + Math.max(0, size.getBlockX() - 1) + HUNGER_GAMES_LOOT_SCAN_PADDING;
        int minZ = pasteZ - HUNGER_GAMES_LOOT_SCAN_PADDING;
        int maxZ = pasteZ + Math.max(0, size.getBlockZ() - 1) + HUNGER_GAMES_LOOT_SCAN_PADDING;
        int minY = Math.max(world.getMinHeight(), pasteY - 4);
        int maxY = Math.min(
            world.getMaxHeight() - 1,
            pasteY + Math.max(Math.max(1, size.getBlockY()), HUNGER_GAMES_LOOT_Y_PADDING)
        );

        if (managedLootService == null) {
            return List.of();
        }
        return managedLootService.collectContainers(world, minX, maxX, minY, maxY, minZ, maxZ);
    }

    private World createTemplateMatchWorld(
        String templateWorldName,
        String worldName,
        QueueType type,
        ValousSeedSelector.Selection valousSelection
    ) {
        if (!prepareTemplateWorldForClone(templateWorldName)) {
            return null;
        }

        try {
            cloneTemplateWorld(templateWorldName, worldName);
        } catch (IOException ex) {
            plugin.getLogger().warning("Failed to clone template world '" + templateWorldName
                + "' to '" + worldName + "': " + ex.getMessage());
            return null;
        }

        if (brTerrainProfile == BrTerrainProfile.VALOUS) {
            ValousSeedSelector.Selection selection = valousSelection;
            if (selection == null) {
                plugin.getLogger().log(java.util.logging.Level.SEVERE,
                    "[Queue][ValousTerrain] event=seed_selection_failed world=" + worldName
                        + " action=world_creation_blocked reason=missing_async_selection");
                Path unusableClone = Bukkit.getWorldContainer().toPath().resolve(worldName);
                try {
                    deleteDirectoryRecursively(unusableClone);
                } catch (IOException cleanupEx) {
                    plugin.getLogger().warning("Failed removing Valous clone after seed selection failure '"
                        + worldName + "': " + cleanupEx.getMessage());
                }
                return null;
            }
            long seed = selection.seed();
            Path clonedWorld = Bukkit.getWorldContainer().toPath().resolve(worldName);
            if (!randomizeValousCloneSeed(clonedWorld, seed)) {
                try {
                    deleteDirectoryRecursively(clonedWorld);
                } catch (IOException cleanupEx) {
                    plugin.getLogger().warning("Failed removing unusable Valous clone '" + worldName
                        + "': " + cleanupEx.getMessage());
                }
                return null;
            }
            plugin.getLogger().info("[Queue][ValousTest] event=clone_seed_randomized world="
                + worldName + " seed=" + seed + " chunks=fresh");
            ValousSeedSelector.Evaluation layout = selection.evaluation();
            ValousSeedSelector.PrototypeEvaluation prototype = selection.prototype();
            plugin.getLogger().info("[Queue][ValousTerrain] event=island_seed_selected world="
                + worldName + " seed=" + seed
                + " policy=" + selection.policy().id()
                + " attempts=" + selection.attempts()
                + " selection_ms=" + selection.selectionMs()
                + " hard_candidates=" + selection.hardCandidateCount()
                + " soft_score=" + formatRatio(selection.softScore())
                + " quality=" + (selection.preferred()
                    ? "preferred"
                    : selection.diagnosticFallback() ? "diagnostic_fallback" : "hard_accepted")
                + " diagnostic_fallback=" + selection.diagnosticFallback()
                + " hard_failures=" + selection.failedHardChecks()
                + " soft_failures=" + selection.failedSoftChecks()
                + " center=" + formatRatio(layout.centerValue())
                + " center_land=" + formatRatio(layout.centerLandRatio())
                + " inner_land=" + formatRatio(layout.innerLandRatio())
                + " shoulder_land=" + formatRatio(layout.shoulderLandRatio())
                + " outer_land=" + formatRatio(layout.outerLandRatio())
                + " mushroom=" + formatRatio(layout.mushroomRatio())
                + " interior_land=" + formatRatio(layout.interiorLandRatio())
                + " connected_land=" + formatRatio(layout.connectedLandRatio())
                + " continuous_rays=" + formatRatio(layout.continuousRayRatio())
                + " coast_min=" + formatRatio(layout.minimumCoastRadius())
                + " coast_median=" + formatRatio(layout.medianCoastRadius())
                + " coast_max=" + formatRatio(layout.maximumCoastRadius())
                + " boil_dominant=" + formatRatio(layout.dominantBoilgroundsRatio())
                + " lush_entrances=" + prototype.lushEntranceCandidates()
                + " molten_routes=" + prototype.moltenEntranceCandidates()
                + " lush_regions=" + prototype.lushRegionSamples()
                + " molten_regions=" + prototype.moltenRegionSamples()
                + " frozen_regions=" + prototype.frozenRegionSamples()
                + " predicted_quick_boil=" + formatRatio(prototype.predictedQuickBoilgroundsRatio())
                + " quick_boil=" + formatRatio(prototype.quickBoilgroundsRatio())
                + " quick_coast=" + formatRatio(prototype.quickCoastShare())
                + " actual_lush=" + prototype.actualLushSamples()
                + " actual_molten=" + prototype.actualMoltenSamples()
                + " actual_frozen=" + prototype.actualFrozenSamples()
                + " actual_sculk=" + prototype.actualSculkSamples()
                + " planner_feed=" + selection.plannerFeed()
                + " candidate_comparisons=" + selection.candidateComparisons()
                + " ownership=datapack");
        }

        boolean legacyPluginWorldgen = useLegacyPluginWorldgen(type);
        boolean runStructures = matchWorldTemplateRunStructures || usePluginManagedStructurePlacement(type);
        prepareMatchWorldDatapacks(worldName);
        if (runStructures) {
            prepareMatchWorldStructureTemplates(worldName);
        }

        WorldCreator creator = new WorldCreator(worldName);
        disableSpawnRetention(creator);
        World world;
        try {
            world = Bukkit.createWorld(creator);
        } catch (RuntimeException ex) {
            plugin.getLogger().log(java.util.logging.Level.SEVERE,
                "Failed loading cloned template world '" + worldName + "' from '" + templateWorldName
                    + "'. The incomplete clone will be removed.", ex);
            Path failedWorldPath = Bukkit.getWorldContainer().toPath().resolve(worldName);
            try {
                if (Files.exists(failedWorldPath)) {
                    deleteDirectoryRecursively(failedWorldPath);
                }
            } catch (IOException cleanupEx) {
                plugin.getLogger().warning("Failed removing incomplete template clone '" + worldName
                    + "': " + cleanupEx.getMessage());
            }
            return null;
        }
        if (world == null) {
            plugin.getLogger().warning("Cloned template world '" + worldName + "' could not be loaded.");
            return null;
        }
        if (useBrTerrain(type)) {
            brMatchWorlds.add(worldName);
        } else {
            brMatchWorlds.remove(worldName);
        }
        registerValousRuntimeMode(worldName);
        if (legacyPluginWorldgen && useAeosTerrain()) {
            ensureAeosTemplateWorldSynced(world);
        }
        configureMatchWorld(world, runStructures, type);
        maybeStartBrWorldPreparation(world, type);
        if (runStructures && type == QueueType.SOLO) {
            plugin.getLogger().info("[Queue] Match world '" + worldName
                + "' is using plugin-managed BR structures on the vanilla overworld.");
        } else if (useDatapackWorldgen(type)) {
            String biomeMode = brTerrainProfile == BrTerrainProfile.HYDRA_WILDS
                ? " as Hydra Wilds with datapack-owned terrain, biomes, and structures"
                : "";
            plugin.getLogger().info("[Queue] Match world '" + worldName
                + "' is using cloned datapack-owned worldgen from template '" + templateWorldName + "'"
                + biomeMode + ".");
        }
        managedMatchWorlds.add(worldName);
        managedMatchWorldTypes.put(worldName, type);
        plugin.getLogger().info("Created match world '" + worldName + "' from template '" + templateWorldName + "'.");
        return world;
    }

    private World getOrCreateLinkedNetherWorld(String rootWorldName, QueueType type) {
        if (rootWorldName == null || rootWorldName.isBlank()) {
            return null;
        }
        String netherWorldName = linkedNetherWorldForRoot(rootWorldName);
        if (netherWorldName == null || netherWorldName.isBlank()) {
            netherWorldName = linkedNetherWorldName(rootWorldName);
        }
        if (netherWorldName == null || netherWorldName.isBlank()) {
            return null;
        }

        World existing = Bukkit.getWorld(netherWorldName);
        if (existing != null) {
            registerLinkedNetherWorld(rootWorldName, netherWorldName);
            syncLinkedNetherBorder(rootWorldName, borderInitialSizeForWorld(rootWorldName), 0);
            return existing;
        }

        prepareMatchWorldDatapacks(netherWorldName);
        prepareMatchWorldStructureTemplates(netherWorldName);

        WorldCreator creator = new WorldCreator(netherWorldName);
        creator.environment(World.Environment.NETHER);
        creator.type(WorldType.NORMAL);
        disableSpawnRetention(creator);
        creator.generateStructures(true);

        World world = Bukkit.createWorld(creator);
        if (world == null) {
            plugin.getLogger().warning("[Queue] Failed to create linked Nether world for " + rootWorldName + ".");
            return null;
        }

        registerLinkedNetherWorld(rootWorldName, netherWorldName);
        configureLinkedNetherWorld(world, rootWorldName, type);
        plugin.getLogger().info("[Queue] Linked Nether world ready: " + rootWorldName + " -> " + netherWorldName);
        return world;
    }

    private void configureLinkedNetherWorld(World world, String rootWorldName, QueueType type) {
        if (world == null) {
            return;
        }
        world.setAutoSave(false);
        world.setTime(18000L);
        world.setGameRule(GameRules.ADVANCE_TIME, false);
        world.setGameRule(GameRules.IMMEDIATE_RESPAWN, true);
        world.setGameRule(GameRules.LOCATOR_BAR, false);
        world.setGameRule(GameRules.SPREAD_VINES, false);
        world.setPVP(true);
        world.getWorldBorder().setCenter(0.0D, 0.0D);
        world.getWorldBorder().setSize(borderInitialSizeForWorld(rootWorldName));
        int spawnY = Math.max(world.getMinHeight() + 4, Math.min(world.getMaxHeight() - 4, 96));
        Location spawn = findSafePortalDestination(world, 0.0D, 0.0D, spawnY);
        if (spawn == null) {
            spawn = new Location(world, 0.5D, spawnY, 0.5D);
        }
        ensureSpawnSpace(spawn);
        world.setSpawnLocation(spawn);
        if (!isHungerGames(type)) {
            if (world.getMinHeight() > -64 || world.getMaxHeight() < 257) {
                plugin.getLogger().warning("[Queue] Linked Hellscape Nether '" + world.getName()
                    + "' is using dimension bounds minY=" + world.getMinHeight()
                    + ", maxY=" + world.getMaxHeight()
                    + ". Full sub-Nether/256 ceiling requires a tall Nether datapack.");
            }
        }
    }

    private double borderInitialSizeForWorld(String worldName) {
        if (isHungerGamesMatchWorldName(worldName)) {
            HungerGamesMapDefinition definition = hungerGamesMapDefinitionByKey(hungerGamesMapKeysByWorld.get(worldName));
            if (definition != null && definition.hasCustomBorderSize()) {
                return Math.max(16.0D, definition.borderSize());
            }
            return Math.max(16.0D, hungerGamesBorderSize);
        }
        if (isHydraBrWorldName(worldName)) {
            return Math.max(16.0D, effectiveBrTerrainBorderDiameter());
        }
        return Math.max(16.0D, matchBorderInitialSize);
    }

    private void disableSpawnRetention(WorldCreator creator) {
        if (creator == null) {
            return;
        }
        try {
            WorldCreator.class.getMethod("keepSpawnLoaded", TriState.class).invoke(creator, TriState.FALSE);
        } catch (ReflectiveOperationException | IllegalArgumentException ignored) {
            // Method signature varies across Paper versions.
        }
        try {
            WorldCreator.class.getMethod("keepSpawnInMemory", boolean.class).invoke(creator, false);
        } catch (ReflectiveOperationException | IllegalArgumentException ignored) {
            // Removed in Paper 1.21.11; safe to skip when unavailable.
        }
    }

    private Location findSafePortalDestination(World world, double targetX, double targetZ, int preferredY) {
        if (world == null) {
            return null;
        }
        double clampedX = clampPortalCoordinate(world, targetX, true);
        double clampedZ = clampPortalCoordinate(world, targetZ, false);
        Location existingPortal = findExistingPortalDestination(world, clampedX, clampedZ, preferredY);
        if (existingPortal != null) {
            return existingPortal;
        }
        Location natural = findNaturalSafePortalDestination(world, clampedX, clampedZ, preferredY);
        if (natural != null) {
            return natural;
        }
        return createEmergencyPortalLanding(world, clampedX, clampedZ, preferredY);
    }

    private double clampPortalCoordinate(World world, double value, boolean xAxis) {
        if (world == null) {
            return value;
        }
        WorldBorder border = world.getWorldBorder();
        if (border == null) {
            return value;
        }
        double half = Math.max(1.0D, (border.getSize() / 2.0D) - PORTAL_DESTINATION_BORDER_BUFFER);
        double center = xAxis ? border.getCenter().getX() : border.getCenter().getZ();
        return Math.max(center - half, Math.min(center + half, value));
    }

    private Location findExistingPortalDestination(World world, double targetX, double targetZ, int preferredY) {
        int originX = (int) Math.round(targetX);
        int originZ = (int) Math.round(targetZ);
        int minY = Math.max(world.getMinHeight() + 1, Math.min(preferredY - 48, world.getMaxHeight() - 3));
        int maxY = Math.max(minY + 2, Math.min(world.getMaxHeight() - 3, Math.max(preferredY + 32, preferredY)));

        for (int radius = 0; radius <= PORTAL_DESTINATION_SEARCH_RADIUS; radius++) {
            for (int dx = -radius; dx <= radius; dx++) {
                for (int dz = -radius; dz <= radius; dz++) {
                    if (radius > 0 && Math.abs(dx) != radius && Math.abs(dz) != radius) {
                        continue;
                    }
                    int x = originX + dx;
                    int z = originZ + dz;
                    if (!isWithinWorldBorder(world, x, z, PORTAL_DESTINATION_BORDER_BUFFER)) {
                        continue;
                    }
                    world.getChunkAt(x >> 4, z >> 4);
                    for (int y = maxY; y >= minY; y--) {
                        Block block = world.getBlockAt(x, y, z);
                        if (block.getType() != Material.NETHER_PORTAL) {
                            continue;
                        }
                        Location standLocation = findStandLocationNearPortal(block);
                        if (standLocation != null) {
                            return standLocation;
                        }
                    }
                }
            }
        }
        return null;
    }

    private Location findStandLocationNearPortal(Block portalBlock) {
        if (portalBlock == null) {
            return null;
        }
        World world = portalBlock.getWorld();
        int x = portalBlock.getX();
        int y = portalBlock.getY();
        int z = portalBlock.getZ();
        int[][] offsets = new int[][] {
            {1, 0},
            {-1, 0},
            {0, 1},
            {0, -1},
            {0, 0}
        };
        for (int[] offset : offsets) {
            int candidateX = x + offset[0];
            int candidateZ = z + offset[1];
            if (!isWithinWorldBorder(world, candidateX, candidateZ, PORTAL_DESTINATION_BORDER_BUFFER)) {
                continue;
            }
            if (!isSafePortalStandLocation(world, candidateX, y, candidateZ)) {
                continue;
            }
            return new Location(world, candidateX + 0.5D, y, candidateZ + 0.5D);
        }
        return null;
    }

    private Location findNaturalSafePortalDestination(World world, double targetX, double targetZ, int preferredY) {
        int originX = (int) Math.round(targetX);
        int originZ = (int) Math.round(targetZ);
        int minY = Math.max(world.getMinHeight() + 1, Math.min(preferredY - 48, world.getMaxHeight() - 3));
        int maxY = Math.max(minY + 2, Math.min(world.getMaxHeight() - 3, Math.max(preferredY + 32, preferredY)));

        for (int radius = 0; radius <= PORTAL_DESTINATION_SEARCH_RADIUS; radius++) {
            for (int dx = -radius; dx <= radius; dx++) {
                for (int dz = -radius; dz <= radius; dz++) {
                    if (radius > 0 && Math.abs(dx) != radius && Math.abs(dz) != radius) {
                        continue;
                    }
                    int x = originX + dx;
                    int z = originZ + dz;
                    if (!isWithinWorldBorder(world, x, z, PORTAL_DESTINATION_BORDER_BUFFER)) {
                        continue;
                    }
                    world.getChunkAt(x >> 4, z >> 4);
                    for (int y = maxY; y >= minY; y--) {
                        if (!isSafePortalStandLocation(world, x, y, z)) {
                            continue;
                        }
                        return new Location(world, x + 0.5D, y, z + 0.5D);
                    }
                }
            }
        }
        return null;
    }

    private Location createEmergencyPortalLanding(World world, double targetX, double targetZ, int preferredY) {
        if (world == null) {
            return null;
        }
        int x = (int) Math.round(targetX);
        int z = (int) Math.round(targetZ);
        int y = Math.max(world.getMinHeight() + 2, Math.min(world.getMaxHeight() - 3, preferredY));
        Material platform = world.getEnvironment() == World.Environment.NETHER ? Material.OBSIDIAN : Material.STONE;

        for (int dx = -1; dx <= 1; dx++) {
            for (int dz = -1; dz <= 1; dz++) {
                world.getBlockAt(x + dx, y - 1, z + dz).setType(platform, false);
                world.getBlockAt(x + dx, y, z + dz).setType(Material.AIR, false);
                world.getBlockAt(x + dx, y + 1, z + dz).setType(Material.AIR, false);
            }
        }
        world.getBlockAt(x, y + 2, z).setType(Material.AIR, false);
        return new Location(world, x + 0.5D, y, z + 0.5D);
    }

    private boolean isSafePortalStandLocation(World world, int x, int y, int z) {
        if (world == null || y <= world.getMinHeight() || y >= world.getMaxHeight() - 1) {
            return false;
        }
        Block below = world.getBlockAt(x, y - 1, z);
        Block feet = world.getBlockAt(x, y, z);
        Block head = world.getBlockAt(x, y + 1, z);
        Material belowType = below.getType();
        if (belowType.isAir() || below.isPassable() || belowType == Material.LAVA || belowType == Material.FIRE || belowType == Material.SOUL_FIRE) {
            return false;
        }
        if (!feet.isPassable() || feet.getType() == Material.LAVA || feet.getType() == Material.FIRE || feet.getType() == Material.SOUL_FIRE) {
            return false;
        }
        if (!head.isPassable() || head.getType() == Material.LAVA || head.getType() == Material.FIRE || head.getType() == Material.SOUL_FIRE) {
            return false;
        }
        return true;
    }

    private void configureMatchWorld(World world, boolean runStructures, QueueType type) {
        world.setAutoSave(false);
        world.setTime(useValousTerrain() && useBrTerrain(type) ? 18000L : 6000L);
        world.setGameRule(GameRules.ADVANCE_TIME, false);
        world.setGameRule(GameRules.SHOW_ADVANCEMENT_MESSAGES, false);
        world.setGameRule(GameRule.DO_FIRE_TICK, false);
        if (useValousTerrain() && useBrTerrain(type)) {
            world.setGameRule(GameRules.ADVANCE_WEATHER, true);
            world.setStorm(false);
            world.setThundering(false);
            world.setClearWeatherDuration(20 * 60 * 5);
        }
        world.setGameRule(GameRules.IMMEDIATE_RESPAWN, true);
        world.setGameRule(GameRules.LOCATOR_BAR, false);
        world.setGameRule(GameRules.SPREAD_VINES, false);
        if (isHungerGames(type)) {
            world.setGameRule(GameRules.SPAWN_MOBS, !hungerGamesDisableMobSpawns);
            world.setGameRule(GameRules.NATURAL_HEALTH_REGENERATION, true);
            world.setPVP(true);
        }
        Location center = world.getSpawnLocation();
        boolean allowCustomStructurePlacement = runStructures;
        if (useBrTerrain(type)) {
            boolean deferredValousSpawn = useValousTerrain() && isValousWorld(world);
            int spawnY = deferredValousSpawn
                ? Math.max(world.getMinHeight() + 1, Math.min(world.getMaxHeight() - 2, 120))
                : world.getHighestBlockYAt(0, 0) + 1;
            if (spawnY <= world.getMinHeight()) {
                spawnY = Math.max(world.getMinHeight() + 1, Math.min(world.getMaxHeight() - 2, 120));
            }
            world.setSpawnLocation(0, spawnY, 0);
            center = world.getSpawnLocation();
            if (deferredValousSpawn) {
                plugin.getLogger().info("[Queue][ValousPreparation] event=spawn_deferred world="
                    + world.getName() + " provisional_y=" + spawnY + " reason=center_not_pregenerated");
            }
        }
        if (isHungerGames(type)) {
            HungerGamesMapDefinition definition = hungerGamesMapDefinitionByKey(hungerGamesMapKeysByWorld.get(world.getName()));
            double borderCenterX = definition != null && definition.hasCustomCenter()
                ? definition.borderCenterX() : center.getX();
            double borderCenterZ = definition != null && definition.hasCustomCenter()
                ? definition.borderCenterZ() : center.getZ();
            double hgBorderSize = definition != null && definition.hasCustomBorderSize()
                ? definition.borderSize()
                : hungerGamesBorderSize;
            matchBorderService.applyInitial(world, borderCenterX, borderCenterZ, Math.max(16.0D, hgBorderSize));
        } else if (useBrTerrain(type)) {
            matchBorderService.applyInitial(world, 0.0D, 0.0D,
                Math.max(16.0D, effectiveBrTerrainBorderDiameter()));
        } else {
            matchBorderService.applyInitial(world, center.getX(), center.getZ(), matchBorderInitialSize);
        }
        configureValousRuntimeLimits(world);
        if (type == QueueType.SOLO && useHellscapeTerrain()) {
            if (world.getMinHeight() > -64 || world.getMaxHeight() < 257) {
                plugin.getLogger().warning("[Queue] Hellscape world '" + world.getName()
                    + "' is using dimension bounds minY=" + world.getMinHeight()
                    + ", maxY=" + world.getMaxHeight()
                    + ". Full sub-Nether/256 ceiling requires a tall Nether datapack.");
            }
        }
        if (allowCustomStructurePlacement) {
            syncExternalStructureTemplates(world);
        }
        if (allowCustomStructurePlacement) {
            runStructureCommands(world);
            if (useBrTerrain(type)) {
                placeExtraVanillaVillages(world);
            }
        }
    }

    private void placeExtraVanillaVillages(World world) {
        if (world == null || world.getEnvironment() != World.Environment.NORMAL) {
            return;
        }
        double half = (world.getWorldBorder().getSize() / 2.0D) - BR_EXTRA_VILLAGE_EDGE_BUFFER;
        if (half <= 220.0D) {
            return;
        }

        List<Location> occupiedCenters = new ArrayList<>(collectStructureMarkerCenters(world));
        List<Location> villageCenters = new ArrayList<>();
        for (Location center : occupiedCenters) {
            if (center == null || center.getWorld() == null || !center.getWorld().equals(world)) {
                continue;
            }
            Chunk chunk = center.getChunk();
            for (Entity entity : chunk.getEntities()) {
                if (!isStructureMarker(entity)) {
                    continue;
                }
                String id = markerStructureId(entity);
                if (id != null && id.startsWith("minecraft:village_")) {
                    villageCenters.add(entity.getLocation());
                }
            }
        }

        int placed = 0;
        int attempts = 0;
        Map<String, Integer> rejectCounts = new HashMap<>();
        String searchId = VANILLA_VILLAGE_PLAINS_ID;
        StructureRule searchRule = structureRuleFor(searchId);
        double centerX = world.getWorldBorder().getCenter().getX();
        double centerZ = world.getWorldBorder().getCenter().getZ();

        while (placed < BR_EXTRA_VILLAGE_TARGET && attempts < BR_EXTRA_VILLAGE_PLACEMENT_ATTEMPTS) {
            attempts++;
            Location candidate = findPlacementCandidate(
                world,
                centerX,
                centerZ,
                half,
                false,
                searchId,
                occupiedCenters,
                BR_EXTRA_VILLAGE_MIN_DISTANCE,
                Math.max(matchStructureZipEdgeBuffer, BR_EXTRA_VILLAGE_EDGE_BUFFER),
                null,
                searchRule,
                villageCenters,
                List.of(),
                rejectCounts
            );
            if (candidate == null) {
                break;
            }
            int x = candidate.getBlockX();
            int z = candidate.getBlockZ();
            if (isInsideAeosRegion(world.getSeed(), x, z)) {
                incrementCount(rejectCounts, "reject_aeos_region");
                occupiedCenters.add(candidate);
                continue;
            }

            int surfaceY = findRealSurfaceY(world, x, z, false);
            Biome surfaceBiome = world.getBiome(x, surfaceY, z);
            String villageId = villageStructureIdForBiome(surfaceBiome);
            StructureRule villageRule = structureRuleFor(villageId);
            if (!placeStructureAt(world, villageId, x, candidate.getBlockY(), z, true, villageRule)) {
                occupiedCenters.add(candidate);
                continue;
            }

            Location placedCenter = new Location(world, x, candidate.getBlockY(), z);
            occupiedCenters.add(placedCenter);
            villageCenters.add(placedCenter);
            placed++;
        }

        plugin.getLogger().info("[Villages] Placed " + placed + "/" + BR_EXTRA_VILLAGE_TARGET
            + " extra villages in " + world.getName() + " after " + attempts + " attempts.");
    }

    private void placeCornucopiaAtOrigin(World world) {
        if (world == null) {
            return;
        }
        String worldName = world.getName();
        if (!cornucopiaPlacementInProgress.add(worldName)) {
            return;
        }
        String structureId = normalizeStructureId(cornucopiaStructureId);
        if (structureId.isBlank()) {
            cornucopiaPlacementInProgress.remove(worldName);
            return;
        }
        StructureRule cornucopiaRule = structureRuleFor(structureId);
        if (!isWorldAllowedForStructure(world, structureId)) {
            plugin.getLogger().warning("Skipped cornucopia structure " + structureId
                + " in " + world.getName() + " (not allowed in current environment).");
            cornucopiaPlacementInProgress.remove(worldName);
            return;
        }
        CompletableFuture<Boolean> preloadFuture = ensureStructurePlacementAreaLoadedAsync(
            world,
            structureId,
            cornucopiaAnchorX(),
            cornucopiaAnchorZ(),
            1,
            true
        );
        preloadFuture
            .whenComplete((loaded, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
                try {
                    World liveWorld = Bukkit.getWorld(worldName);
                    if (liveWorld == null) {
                        return;
                    }
                    if (error != null || !Boolean.TRUE.equals(loaded)
                        || !isStructurePlacementAreaLoaded(liveWorld, structureId, cornucopiaAnchorX(), cornucopiaAnchorZ(), 1)) {
                        plugin.getLogger().warning("Skipping cornucopia placement because anchor chunk is not loaded in " + worldName);
                        scheduleCornucopiaCenterEnsure(liveWorld, 40L);
                        return;
                    }

                    int x = cornucopiaAnchorX();
                    int z = cornucopiaAnchorZ();
                    int y = resolveCornucopiaPlacementY(liveWorld);
                    Set<Long> waterColumns = surveyCornucopiaWaterFootprint(liveWorld, y);
                    clearCornucopiaPlacementVolume(liveWorld, structureId, y);
                    dryCornucopiaWaterFootprint(liveWorld, y, waterColumns);
                    prepareCornucopiaTerrain(liveWorld, y);
                    buildCornucopiaFoundation(liveWorld, y);
                    boolean placed = placeCornucopiaStructureAt(liveWorld, structureId, x, y, z, cornucopiaRule);
                    if (placed) {
                        boolean lootFilled = populateCornucopiaInitialLoot(liveWorld, structureId, y, cornucopiaRule);
                        if (!lootFilled) {
                            plugin.getLogger().warning("[Cornucopia] Placement completed but initial loot was not ready in "
                                + worldName + "; BR preparation will remain in PLACING_CORNUCOPIA.");
                            scheduleCornucopiaCenterEnsure(liveWorld, 40L);
                            return;
                        }
                        markStructurePlacement(liveWorld, structureId, x, y, z);
                        registerStructureZone(liveWorld, structureId, x, y, z, cornucopiaRule);
                        plugin.getLogger().info("Placed cornucopia structure " + structureId + " at "
                            + x + "," + y + "," + z + " in " + worldName);
                        BrWorldPreparationState prepState = brWorldPreparationStates.get(worldName);
                        if (prepState != null) {
                            markBrWorldPreparationReady(prepState, "Cornucopia placed, loot filled, and zones registered");
                        }
                        scheduleCornucopiaCenterEnsure(liveWorld, 2L);
                        scheduleCornucopiaCenterEnsure(liveWorld, 40L);
                    } else if (hasCornucopiaPresenceAtOrigin(liveWorld)
                        || hasProtectedZoneOverlap(liveWorld, new Location(liveWorld, x, y, z), cornucopiaRule.zoneRadius())) {
                        ensureCornucopiaCenterState(liveWorld);
                        BrWorldPreparationState prepState = brWorldPreparationStates.get(worldName);
                        if (prepState != null && isCornucopiaReadyForMatchStart(liveWorld)) {
                            markBrWorldPreparationReady(prepState, "existing Cornucopia presence verified");
                        }
                    } else {
                        plugin.getLogger().warning("Failed to place cornucopia structure " + structureId + " at "
                            + x + "," + y + "," + z + " in " + worldName);
                        scheduleCornucopiaCenterEnsure(liveWorld, 40L);
                    }
                } finally {
                    cornucopiaPlacementInProgress.remove(worldName);
                }
            }));
    }

    private void ensureCornucopiaAndPedestalsAtOrigin(World world) {
        if (world == null || !brMatchWorlds.contains(world.getName())) {
            return;
        }
        if (!isCornucopiaCenterAreaReady(world)) {
            ensureCornucopiaCenterAreaReadyAsync(world);
            return;
        }
        if (!hasCornucopiaPresenceAtOrigin(world)) {
            placeCornucopiaAtOrigin(world);
            return;
        }
        ensureCornucopiaCenterState(world);
    }

    private void ensureCornucopiaCenterState(World world) {
        if (world == null) {
            return;
        }
        if (!isCornucopiaCenterAreaReady(world)) {
            scheduleCornucopiaCenterEnsure(world, 20L);
        }
    }

    private int resolveCornucopiaPlacementY(World world) {
        if (world == null) {
            return CORNUCOPIA_FIXED_STRUCTURE_Y;
        }
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int surfaceY = resolveCornucopiaSurfaceY(world, MID_CENTER_X, MID_CENTER_Z);
        int placementY = surfaceY + 1 - CORNUCOPIA_UNDERGROUND_ANCHOR_DEPTH;
        return Math.max(minY, Math.min(maxY, placementY));
    }

    private int cornucopiaTerrainTopY(int placementY) {
        return placementY + CORNUCOPIA_UNDERGROUND_ANCHOR_DEPTH - 1;
    }

    private int resolveCornucopiaSurfaceY(World world, int x, int z) {
        int drySurfaceY = findRealSurfaceY(world, x, z, false, false);
        int wetSurfaceY = findRealSurfaceY(world, x, z, true, false);
        Material wetType = world.getBlockAt(x, wetSurfaceY, z).getType();
        if (isCornucopiaWaterMaterial(wetType)) {
            return Math.max(drySurfaceY, wetSurfaceY);
        }
        return drySurfaceY;
    }

    private void prepareCornucopiaTerrain(World world, int placementY) {
        if (world == null) {
            return;
        }
        lightlyFlattenCornucopiaPlatform(world, placementY);
    }

    private void clearCornucopiaPlacementVolume(World world, String structureId, int placementY) {
        if (world == null) {
            return;
        }
        Structure structure = resolveHydraStructure(normalizeStructureId(structureId));
        int structureHeight = structure == null ? 32 : Math.max(1, structure.getSize().getBlockY());
        int minY = Math.max(world.getMinHeight() + 1, placementY - CORNUCOPIA_FOUNDATION_DEPTH);
        int maxY = Math.min(world.getMaxHeight() - 2, Math.max(
            placementY + structureHeight + CORNUCOPIA_CLEARANCE_HEADROOM,
            CORNUCOPIA_CLEARANCE_MIN_TOP_Y
        ));
        int pad = CORNUCOPIA_CLEARANCE_PADDING;
        int cleared = 0;
        for (int x = cornucopiaFootprintMinX() - pad; x <= cornucopiaFootprintMaxX() + pad; x++) {
            for (int z = cornucopiaFootprintMinZ() - pad; z <= cornucopiaFootprintMaxZ() + pad; z++) {
                for (int y = minY; y <= maxY; y++) {
                    Block block = world.getBlockAt(x, y, z);
                    Material type = block.getType();
                    if (type == Material.BEDROCK || type.isAir()) {
                        continue;
                    }
                    if (y < placementY && type.isSolid() && !isSoftClearMaterial(type)) {
                        continue;
                    }
                    block.setType(Material.AIR, false);
                    cleared++;
                }
            }
        }
        plugin.getLogger().info("[Cornucopia] Cleared placement volume in " + world.getName()
            + " for " + normalizeStructureId(structureId) + " (blocks=" + cleared
            + ", y=" + minY + ".." + maxY + ", padding=" + pad
            + ", anchorDepth=" + CORNUCOPIA_UNDERGROUND_ANCHOR_DEPTH + ").");
    }

    private Set<Long> surveyCornucopiaWaterFootprint(World world, int placementY) {
        Set<Long> columns = new HashSet<>();
        if (world == null) {
            return columns;
        }
        int targetTop = cornucopiaTerrainTopY(placementY);
        int radius = Math.max(12, Math.max(cornucopiaSpanX(), cornucopiaSpanZ()) / 2 + CORNUCOPIA_DRY_FOOTPRINT_PADDING);
        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                if (Math.hypot(dx, dz) > radius + 0.5D) {
                    continue;
                }
                int x = cornucopiaCenterBlockX() + dx;
                int z = cornucopiaCenterBlockZ() + dz;
                if (isCornucopiaWaterColumn(world, x, z, targetTop)) {
                    columns.add((((long) x) << 32) ^ (z & 0xffffffffL));
                }
            }
        }
        if (!columns.isEmpty()) {
            plugin.getLogger().info("[Cornucopia] Found " + columns.size()
                + " water/lake column(s) inside the center footprint in " + world.getName()
                + "; drying them before placement.");
        }
        return columns;
    }

    private boolean isCornucopiaWaterColumn(World world, int x, int z, int targetTop) {
        int minY = Math.max(world.getMinHeight() + 1, targetTop - CORNUCOPIA_FOUNDATION_DEPTH - 4);
        int maxY = Math.min(world.getMaxHeight() - 2, Math.max(
            targetTop + CORNUCOPIA_CLEARANCE_HEADROOM,
            CORNUCOPIA_CLEARANCE_MIN_TOP_Y
        ));
        int surfaceY = findRealSurfaceY(world, x, z, true, false);
        if (isCornucopiaWaterMaterial(world.getBlockAt(x, surfaceY, z).getType())) {
            return true;
        }
        for (int y = maxY; y >= minY; y--) {
            if (isCornucopiaWaterMaterial(world.getBlockAt(x, y, z).getType())) {
                return true;
            }
        }
        return false;
    }

    private void dryCornucopiaWaterFootprint(World world, int placementY, Set<Long> waterColumns) {
        if (world == null || waterColumns == null || waterColumns.isEmpty()) {
            return;
        }
        int targetTop = cornucopiaTerrainTopY(placementY);
        int minY = Math.max(world.getMinHeight() + 1, targetTop - CORNUCOPIA_FOUNDATION_DEPTH);
        int maxY = Math.min(world.getMaxHeight() - 2, Math.max(
            targetTop + CORNUCOPIA_CLEARANCE_HEADROOM,
            CORNUCOPIA_CLEARANCE_MIN_TOP_Y
        ));
        int changed = 0;
        for (long key : waterColumns) {
            int x = (int) (key >> 32);
            int z = (int) key;
            for (int y = minY; y <= targetTop; y++) {
                Block block = world.getBlockAt(x, y, z);
                if (block.getType() == Material.BEDROCK) {
                    continue;
                }
                block.setType(y == targetTop ? Material.GRASS_BLOCK : Material.DIRT, false);
                changed++;
            }
            for (int y = targetTop + 1; y <= maxY; y++) {
                Block block = world.getBlockAt(x, y, z);
                Material type = block.getType();
                if (type == Material.BEDROCK || type.isAir()) {
                    continue;
                }
                if (isCornucopiaWaterMaterial(type) || isSoftClearMaterial(type)) {
                    block.setType(Material.AIR, false);
                    changed++;
                }
            }
        }
        plugin.getLogger().info("[Cornucopia] Dried center water footprint in " + world.getName()
            + " (columns=" + waterColumns.size() + ", blocks=" + changed + ").");
    }

    private static boolean isCornucopiaWaterMaterial(Material type) {
        return type == Material.WATER || type == Material.LAVA;
    }

    private void lightlyFlattenCornucopiaPlatform(World world, int placementY) {
        if (world == null) {
            return;
        }
        int targetTop = cornucopiaTerrainTopY(placementY);
        int maxY = world.getMaxHeight() - 2;
        int footprintHalfSpan = Math.max(
            Math.max(1, cornucopiaSpanX()) / 2,
            Math.max(1, cornucopiaSpanZ()) / 2
        );
        int innerRadius = Math.min(
            Math.max(12, CORNUCOPIA_FLATTEN_RADIUS),
            Math.max(12, footprintHalfSpan - 24)
        );
        int outerRadius = Math.min(
            Math.max(innerRadius + CORNUCOPIA_FLATTEN_BLEND_WIDTH, innerRadius + 8),
            Math.max(innerRadius + 8, footprintHalfSpan)
        );
        for (int dx = -outerRadius; dx <= outerRadius; dx++) {
            for (int dz = -outerRadius; dz <= outerRadius; dz++) {
                int x = cornucopiaCenterBlockX() + dx;
                int z = cornucopiaCenterBlockZ() + dz;
                double distance = Math.hypot(dx, dz);
                if (distance > outerRadius + 0.5D) {
                    continue;
                }
                int desiredTop = targetTop;
                if (distance > innerRadius) {
                    double t = smoothstep(clamp(
                        (distance - innerRadius) / (double) Math.max(1, outerRadius - innerRadius),
                        0.0D,
                        1.0D
                    ));
                    int currentTop = Math.max(world.getMinHeight() + 1, Math.min(maxY, findRealSurfaceY(world, x, z, false, false)));
                    desiredTop = (int) Math.round((targetTop * (1.0D - t)) + (currentTop * t));
                    desiredTop -= (int) Math.round((1.0D - t) * CORNUCOPIA_FLATTEN_EDGE_DROP);
                }
                int currentTop = Math.max(world.getMinHeight() + 1, Math.min(maxY, findRealSurfaceY(world, x, z, false, false)));
                if (distance > innerRadius && Math.abs(currentTop - desiredTop) > 6) {
                    continue;
                }
                shapeTerrainColumn(
                    world,
                    x,
                    z,
                    desiredTop,
                    Math.min(maxY, targetTop + CORNUCOPIA_FOUNDATION_CLEARANCE),
                    distance <= innerRadius ? 6 : CORNUCOPIA_MAX_FLATTEN_RAISE,
                    CORNUCOPIA_MAX_FLATTEN_CUT,
                    4
                );
            }
        }
    }

    private void buildCornucopiaFoundation(World world, int placementY) {
        if (world == null) {
            return;
        }
        int targetTop = cornucopiaTerrainTopY(placementY);
        int maxRadius = Math.max(12, Math.max(cornucopiaSpanX(), cornucopiaSpanZ()) / 2 - 8);
        int minRadius = Math.max(8, (int) Math.round(maxRadius * 0.52D));
        long seed = world.getSeed() ^ 0xC0A11C0FEE12L;
        int built = 0;
        for (int x = cornucopiaCenterBlockX() - maxRadius - 3; x <= cornucopiaCenterBlockX() + maxRadius + 3; x++) {
            for (int z = cornucopiaCenterBlockZ() - maxRadius - 3; z <= cornucopiaCenterBlockZ() + maxRadius + 3; z++) {
                double distance = Math.hypot(x - cornucopiaCenterX(), z - cornucopiaCenterZ());
                Material fillMaterial = supportFillMaterial(world, x, z);
                Material topMaterial = surfaceTopMaterial(fillMaterial);
                for (int depth = 0; depth <= CORNUCOPIA_FOUNDATION_DEPTH; depth++) {
                    int y = targetTop - depth;
                    if (y <= world.getMinHeight()) {
                        break;
                    }
                    double t = depth / (double) Math.max(1, CORNUCOPIA_FOUNDATION_DEPTH);
                    double radius = brLerp(maxRadius, minRadius, smoothstep(t));
                    radius += cornucopiaSupportNoise(seed, x, z, depth);
                    if (distance > radius) {
                        continue;
                    }
                    Block block = world.getBlockAt(x, y, z);
                    Material type = block.getType();
                    if (type == Material.BEDROCK) {
                        continue;
                    }
                    if (depth > 0 && isStructuralSupport(block, true) && !isSoftClearMaterial(type)) {
                        break;
                    }
                    block.setType(depth == 0 ? topMaterial : fillMaterial, false);
                    built++;
                }
            }
        }
        plugin.getLogger().info("[Cornucopia] Built tapered support base in " + world.getName()
            + " (blocks=" + built + ", topRadius=" + maxRadius + ", bottomRadius=" + minRadius + ").");
    }

    private double cornucopiaSupportNoise(long seed, int x, int z, int depth) {
        double coarse = brHashToUnit(seed + 0x51A7L + depth, Math.floorDiv(x, 4), Math.floorDiv(z, 4));
        double fine = brHashToUnit(seed + 0x51A8L + depth, x, z);
        double erosion = Math.max(0.0D, depth - 2.0D) / Math.max(1.0D, CORNUCOPIA_FOUNDATION_DEPTH - 2.0D);
        return (coarse * 3.5D) + (fine * 1.4D) - (erosion * 2.0D);
    }

    private void reinforceCornucopiaFoundationColumn(
        World world,
        int x,
        int z,
        int targetTop,
        Material fillMaterial,
        Material topMaterial,
        int maxDepth
    ) {
        if (world == null) {
            return;
        }
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int clampedTop = Math.max(minY, Math.min(maxY, targetTop));
        Block top = world.getBlockAt(x, clampedTop, z);
        if (top.getType() != Material.BEDROCK && (top.getType().isAir() || isSoftClearMaterial(top.getType()))) {
            top.setType(topMaterial, false);
        }
        int lowest = Math.max(minY, clampedTop - Math.max(1, maxDepth));
        for (int y = clampedTop - 1; y >= lowest; y--) {
            Block block = world.getBlockAt(x, y, z);
            Material type = block.getType();
            if (isStructuralSupport(block, true) && !isSoftClearMaterial(type)) {
                break;
            }
            if (type != Material.BEDROCK) {
                block.setType(fillMaterial, false);
            }
        }
    }

    private boolean populateCornucopiaInitialLoot(World world, String structureId, int baseY, StructureRule rule) {
        if (world == null || managedLootService == null) {
            return false;
        }
        List<Block> containers = collectCornucopiaContainers(world, structureId, baseY, rule);
        if (containers.isEmpty()) {
            plugin.getLogger().warning("[Cornucopia] No supported containers found in " + world.getName() + ".");
            return false;
        }
        int filled = 0;
        int totalGenerated = 0;
        String lootGroup = cornucopiaLootGroup(world);
        for (Block block : containers) {
            int generated = managedLootService.populateManagedContainer(
                block,
                BR_CORNUCOPIA_INITIAL_LOOT_TABLE_ID,
                ManagedLootService.SOURCE_CORNUCOPIA,
                lootGroup
            );
            if (generated > 0) {
                filled++;
                totalGenerated += generated;
            }
        }
        plugin.getLogger().info("[Cornucopia] Filled " + filled + "/" + containers.size()
            + " containers in " + world.getName() + " using " + BR_CORNUCOPIA_INITIAL_LOOT_TABLE_ID
            + ". Generated stacks=" + totalGenerated + ".");
        return filled == containers.size();
    }

    private List<Block> collectCornucopiaContainers(World world, String structureId, int baseY, StructureRule rule) {
        if (world == null || managedLootService == null) {
            return List.of();
        }
        Structure structure = resolveHydraStructure(normalizeStructureId(structureId));
        int spanY = structure == null ? 72 : Math.max(1, structure.getSize().getBlockY());
        int minY = Math.max(world.getMinHeight(), baseY - 4);
        int maxY = Math.min(world.getMaxHeight() - 1, baseY + spanY + 8);
        List<Block> containers = managedLootService.collectContainers(
            world,
            cornucopiaFootprintMinX() - 2,
            cornucopiaFootprintMaxX() + 2,
            minY,
            maxY,
            cornucopiaFootprintMinZ() - 2,
            cornucopiaFootprintMaxZ() + 2
        );
        if (usesBarrelOnlyCornucopiaLoot(structureId)) {
            containers = containers.stream()
                .filter(block -> block.getType() == Material.BARREL)
                .toList();
        }
        return containers;
    }

    private String cornucopiaLootGroup(World world) {
        return world == null ? null : "cornucopia:" + world.getName();
    }

    private boolean hasCornucopiaMarkerAtOrigin(World world) {
        if (world == null) {
            return false;
        }
        String expectedId = normalizeStructureId(cornucopiaStructureId);
        for (Entity entity : world.getNearbyEntities(cornucopiaAnchorProbe(world), 32.0D, 80.0D, 32.0D)) {
            if (!isStructureMarker(entity)) {
                continue;
            }
            String id = markerStructureId(entity);
            if (expectedId.equals(normalizeStructureId(id))) {
                return true;
            }
        }
        return false;
    }

    private boolean hasCornucopiaPresenceAtOrigin(World world) {
        if (hasCornucopiaMarkerAtOrigin(world)) {
            return true;
        }
        if (world == null) {
            return false;
        }
        StructureRule cornucopiaRule = structureRuleFor(cornucopiaStructureId);
        if (hasProtectedZoneOverlap(world, cornucopiaAnchorProbe(world), cornucopiaRule.zoneRadius())) {
            return true;
        }
        return hasProtectedZoneOverlap(world, cornucopiaAnchorCenter(world), cornucopiaRule.zoneRadius());
    }

    private Location midCenter(World world) {
        if (!isChunkSquareLoaded(world, MID_CENTER_X, MID_CENTER_Z, 1)) {
            return new Location(world, MID_CENTER_X + 0.5D, fixedCornucopiaPlatformY(world) + 1.0D, MID_CENTER_Z + 0.5D);
        }
        int y = fixedCornucopiaPlatformY(world) + 1;
        return new Location(world, MID_CENTER_X + 0.5D, y, MID_CENTER_Z + 0.5D);
    }

    private int cornucopiaSpanX() {
        return cornucopiaSpan(true);
    }

    private int cornucopiaSpanZ() {
        return cornucopiaSpan(false);
    }

    private int cornucopiaSpan(boolean xAxis) {
        Structure structure = resolveHydraStructure(normalizeStructureId(cornucopiaStructureId));
        if (structure != null) {
            BlockVector size = structure.getSize();
            int span = Math.max(1, xAxis ? size.getBlockX() : size.getBlockZ());
            return span;
        }
        return xAxis ? CORNUCOPIA_DEFAULT_SPAN_X : CORNUCOPIA_DEFAULT_SPAN_Z;
    }

    private int cornucopiaAnchorX() {
        return MID_CENTER_X - Math.floorDiv(Math.max(1, cornucopiaSpanX()) - 1, 2);
    }

    private int cornucopiaAnchorZ() {
        return MID_CENTER_Z - Math.floorDiv(Math.max(1, cornucopiaSpanZ()) - 1, 2);
    }

    private double cornucopiaCenterX() {
        return cornucopiaAnchorX() + ((cornucopiaSpanX() - 1) / 2.0D);
    }

    private double cornucopiaCenterZ() {
        return cornucopiaAnchorZ() + ((cornucopiaSpanZ() - 1) / 2.0D);
    }

    private int cornucopiaCenterBlockX() {
        return (int) Math.round(cornucopiaCenterX());
    }

    private int cornucopiaCenterBlockZ() {
        return (int) Math.round(cornucopiaCenterZ());
    }

    private double cornucopiaHalfSpanX() {
        return Math.max(0.5D, (cornucopiaSpanX() - 1) / 2.0D);
    }

    private double cornucopiaHalfSpanZ() {
        return Math.max(0.5D, (cornucopiaSpanZ() - 1) / 2.0D);
    }

    private int cornucopiaFootprintMinX() {
        return cornucopiaAnchorX();
    }

    private int cornucopiaFootprintMaxX() {
        return cornucopiaAnchorX() + Math.max(1, cornucopiaSpanX()) - 1;
    }

    private int cornucopiaFootprintMinZ() {
        return cornucopiaAnchorZ();
    }

    private int cornucopiaFootprintMaxZ() {
        return cornucopiaAnchorZ() + Math.max(1, cornucopiaSpanZ()) - 1;
    }

    private boolean isInsideCornucopiaFootprint(int x, int z, int padding) {
        int pad = Math.max(0, padding);
        return x >= cornucopiaFootprintMinX() - pad
            && x <= cornucopiaFootprintMaxX() + pad
            && z >= cornucopiaFootprintMinZ() - pad
            && z <= cornucopiaFootprintMaxZ() + pad;
    }

    private int cornucopiaFootprintRadius() {
        return (int) Math.ceil(Math.hypot(cornucopiaHalfSpanX(), cornucopiaHalfSpanZ()));
    }

    private int cornucopiaProtectedRadius() {
        return cornucopiaFootprintRadius() + 2;
    }

    private Location cornucopiaAnchorCenter(World world) {
        if (!isStructurePlacementAreaLoaded(world, cornucopiaStructureId, cornucopiaAnchorX(), cornucopiaAnchorZ(), 1)) {
            return cornucopiaCenterProbe(world);
        }
        int y = fixedCornucopiaPlatformY(world) + 1;
        return new Location(world, cornucopiaCenterX(), y, cornucopiaCenterZ());
    }

    private Location cornucopiaCenterProbe(World world) {
        return new Location(
            world,
            cornucopiaCenterX(),
            Math.max(world.getMinHeight() + 8, world.getSeaLevel() + 8),
            cornucopiaCenterZ()
        );
    }

    private Location cornucopiaAnchorProbe(World world) {
        return new Location(
            world,
            cornucopiaAnchorX() + 0.5D,
            Math.max(world.getMinHeight() + 8, world.getSeaLevel() + 8),
            cornucopiaAnchorZ() + 0.5D
        );
    }

    private double distanceToCornucopiaAnchor(double x, double z) {
        return Math.hypot(x - cornucopiaCenterX(), z - cornucopiaCenterZ());
    }

    private boolean isInsideCornucopiaProtectedZone(Location location) {
        if (location == null || location.getWorld() == null || !isHydraBrWorld(location.getWorld())) {
            return false;
        }
        return distanceToCornucopiaAnchor(location.getX(), location.getZ()) <= cornucopiaProtectedRadius() + 0.5D;
    }

    public boolean isLegendaryTerrainDamageProtected(Block block) {
        if (block == null) {
            return true;
        }
        BlockState state = block.getState();
        if (state instanceof Container || state instanceof TileState) {
            return true;
        }
        Material type = block.getType();
        if (type == Material.STRUCTURE_BLOCK
            || type == Material.STRUCTURE_VOID
            || type == Material.JIGSAW
            || type == Material.COMMAND_BLOCK
            || type == Material.CHAIN_COMMAND_BLOCK
            || type == Material.REPEATING_COMMAND_BLOCK
            || type == Material.BARRIER
            || type == Material.LIGHT) {
            return true;
        }
        World world = block.getWorld();
        if (!isHydraBrWorld(world)) {
            return false;
        }
        Location location = block.getLocation();
        if (isInsideCornucopiaProtectedZone(location)) {
            return true;
        }
        List<StructureProtectionBox> zones = STRUCTURE_PROTECTION_MASKS.get(world.getName());
        if (zones == null || zones.isEmpty()) {
            return false;
        }
        int x = block.getX();
        int y = block.getY();
        int z = block.getZ();
        synchronized (zones) {
            for (StructureProtectionBox box : zones) {
                if (box != null
                    && x >= box.minX() && x <= box.maxX()
                    && y >= box.minY() && y <= box.maxY()
                    && z >= box.minZ() && z <= box.maxZ()) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean prepareTemplateWorldForClone(String templateWorldName) {
        if (templateWorldName == null || templateWorldName.isBlank()) {
            return false;
        }

        World templateWorld = Bukkit.getWorld(templateWorldName);
        if (templateWorld == null) {
            return true;
        }
        if (!templateWorld.getPlayers().isEmpty()) {
            plugin.getLogger().warning("Template world '" + templateWorldName
                + "' is loaded with players. Move players out and unload it.");
            return false;
        }
        if (!Bukkit.unloadWorld(templateWorld, false)) {
            plugin.getLogger().warning("Could not unload template world '" + templateWorldName
                + "'. Match world clone cancelled.");
            return false;
        }
        return true;
    }

    private String effectiveTemplateWorldName(QueueType type) {
        if (isHungerGames(type)) {
            return "";
        }
        if (isBattleRoyaleType(type) && brTerrainProfile == BrTerrainProfile.VALOUS) {
            return VALOUS_TEMPLATE_WORLD_NAME;
        }
        if (shouldCreateFreshRandomBrWorld(type)) {
            return "";
        }
        if (matchWorldTemplateName != null && !matchWorldTemplateName.isBlank()) {
            return matchWorldTemplateName;
        }
        return "";
    }

    private boolean hasTemplateWorld(String templateWorldName) {
        if (templateWorldName == null || templateWorldName.isBlank()) {
            return false;
        }
        Path worldPath = Bukkit.getWorldContainer().toPath().resolve(templateWorldName);
        return Files.isDirectory(worldPath);
    }

    private void cloneTemplateWorld(String sourceWorldName, String targetWorldName) throws IOException {
        Path worldContainer = Bukkit.getWorldContainer().toPath();
        Path source = worldContainer.resolve(sourceWorldName);
        Path target = worldContainer.resolve(targetWorldName);
        if (!Files.isDirectory(source)) {
            throw new IOException("Template folder not found: " + sourceWorldName);
        }
        if (Files.exists(target)) {
            deleteDirectoryRecursively(target);
        }

        List<Path> paths;
        try (Stream<Path> walk = Files.walk(source)) {
            paths = walk.toList();
        }
        for (Path sourcePath : paths) {
            if (shouldSkipTemplatePath(source, sourcePath)) {
                continue;
            }
            Path relative = source.relativize(sourcePath);
            Path targetPath = target.resolve(relative.toString());
            if (Files.isDirectory(sourcePath)) {
                Files.createDirectories(targetPath);
                continue;
            }
            Path parent = targetPath.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.copy(sourcePath, targetPath);
        }
    }

    private void registerValousRuntimeMode(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return;
        }
        if (brTerrainProfile == BrTerrainProfile.VALOUS) {
            valousGenerationSizesByWorld.put(worldName, valousGenerationSize);
        } else {
            valousGenerationSizesByWorld.remove(worldName);
        }
    }

    private void configureValousRuntimeLimits(World world) {
        if (world == null) {
            return;
        }
        ValousGenerationSize size = valousGenerationSizesByWorld.get(rootMatchWorldName(world.getName()));
        if (size == null) {
            return;
        }
        int viewDistance = valousViewDistance(size);
        world.setViewDistance(viewDistance);
        world.setSimulationDistance(Math.min(viewDistance, world.getSimulationDistance()));
        boolean reduced = size != ValousGenerationSize.FULL;
        String pcsMode = reduced ? "bypassed" : fakePcsEnabled ? "normal" : "disabled_by_config";
        plugin.getLogger().warning("[Queue][ValousTest] event=runtime_limits_applied world="
            + world.getName() + " size=" + size.key
            + " view_distance=" + viewDistance
            + " simulation_distance=" + world.getSimulationDistance()
            + " preload=" + valousPreloadDiameter(size)
            + " pcs=" + pcsMode
            + " mode=" + (reduced ? "reduced_terrain_test" : "full_validation")
            + " development_only=true");
    }

    private static int valousViewDistance(ValousGenerationSize size) {
        return size == ValousGenerationSize.FULL
            ? VALOUS_FULL_VIEW_DISTANCE
            : VALOUS_DEVELOPMENT_VIEW_DISTANCE;
    }

    private static int valousPreloadDiameter(ValousGenerationSize size) {
        ValousGenerationSize resolved = size == null ? ValousGenerationSize.FULL : size;
        int borderDiameter = resolved.borderDiameter;
        int bufferPerSide = resolved == ValousGenerationSize.FULL
            ? VALOUS_FULL_PRELOAD_BUFFER_PER_SIDE
            : VALOUS_DEVELOPMENT_PRELOAD_BUFFER_PER_SIDE;
        return alignChunkPreloadDiameter(borderDiameter + (bufferPerSide * 2));
    }

    private boolean randomizeValousCloneSeed(Path worldRoot, long seed) {
        Path levelDat = worldRoot.resolve("level.dat");
        Path stagedLevelDat = worldRoot.resolve("level.dat.hydra-seed");
        try {
            Class<?> nbtIoClass = Class.forName("net.minecraft.nbt.NbtIo");
            Class<?> nbtAccounterClass = Class.forName("net.minecraft.nbt.NbtAccounter");
            Object nbtAccounter = nbtAccounterClass.getMethod("unlimitedHeap").invoke(null);
            Object rootTag = nbtIoClass.getMethod("readCompressed", Path.class, nbtAccounterClass)
                .invoke(null, levelDat, nbtAccounter);
            Object dataTag = requiredNbtCompound(rootTag, "Data");
            Object worldGenSettings = requiredNbtCompound(dataTag, "WorldGenSettings");
            synchronizeValousCloneBiomeSource(worldGenSettings, worldRoot.getFileName().toString());
            worldGenSettings.getClass().getMethod("putLong", String.class, long.class)
                .invoke(worldGenSettings, "seed", seed);
            nbtIoClass.getMethod("writeCompressed", rootTag.getClass(), Path.class)
                .invoke(null, rootTag, stagedLevelDat);
            Files.move(stagedLevelDat, levelDat, StandardCopyOption.REPLACE_EXISTING);
            Files.deleteIfExists(worldRoot.resolve("level.dat_old"));
            clearValousTemplateGeneratedChunks(worldRoot);
            return true;
        } catch (ReflectiveOperationException | IOException | RuntimeException ex) {
            try {
                Files.deleteIfExists(stagedLevelDat);
            } catch (IOException ignored) {
                // The disposable clone is removed by the caller.
            }
            plugin.getLogger().log(java.util.logging.Level.SEVERE,
                "[Queue][ValousTest] event=clone_seed_failed world=" + worldRoot.getFileName()
                    + " action=match_start_blocked", ex);
            return false;
        }
    }

    private void synchronizeValousCloneBiomeSource(
        Object worldGenSettings,
        String worldName
    ) throws ReflectiveOperationException {
        Object dimensions = requiredNbtCompound(worldGenSettings, "dimensions");
        Object overworld = requiredNbtCompound(dimensions, "minecraft:overworld");
        Object generator = requiredNbtCompound(overworld, "generator");
        Object biomeSource = requiredNbtCompound(generator, "biome_source");
        Object biomesOptional = biomeSource.getClass().getMethod("getList", String.class)
            .invoke(biomeSource, "biomes");
        if (!(biomesOptional instanceof Optional<?> optional) || optional.isEmpty()) {
            throw new IllegalStateException("Valous template biome source has no biome list.");
        }
        Object biomes = optional.get();
        Method sizeMethod = biomes.getClass().getMethod("size");
        Method getCompoundOrEmpty = biomes.getClass().getMethod("getCompoundOrEmpty", int.class);
        int count = ((Number) sizeMethod.invoke(biomes)).intValue();
        boolean coastUpdated = false;
        boolean inlandUpdated = false;
        for (int index = 0; index < count; index++) {
            Object entry = getCompoundOrEmpty.invoke(biomes, index);
            String biome = (String) entry.getClass()
                .getMethod("getStringOr", String.class, String.class)
                .invoke(entry, "biome", "");
            if (!ValousPrototypeValidator.MUSHROOM_THICKET_COAST.equals(biome)
                && !ValousPrototypeValidator.MUSHROOM_THICKET.equals(biome)) {
                continue;
            }
            Object parameters = requiredNbtCompound(entry, "parameters");
            float minimum = ValousPrototypeValidator.MUSHROOM_THICKET_COAST.equals(biome)
                ? 0.18F
                : 0.19F;
            float maximum = ValousPrototypeValidator.MUSHROOM_THICKET_COAST.equals(biome)
                ? 0.19F
                : 1.0F;
            putNbtFloatRange(parameters, "continentalness", minimum, maximum);
            if (ValousPrototypeValidator.MUSHROOM_THICKET_COAST.equals(biome)) {
                coastUpdated = true;
            } else {
                inlandUpdated = true;
            }
        }
        if (!coastUpdated || !inlandUpdated) {
            throw new IllegalStateException(
                "Valous template biome source is missing Mushroom Thicket coast routing."
            );
        }
        plugin.getLogger().info("[Queue][ValousTemplate] event=biome_source_synchronized world="
            + worldName + " coast=0.18..0.19 inland=0.19..1.0 source=current_datapack");
    }

    private void putNbtFloatRange(
        Object compound,
        String key,
        float minimum,
        float maximum
    ) throws ReflectiveOperationException {
        Class<?> tagClass = Class.forName("net.minecraft.nbt.Tag");
        Class<?> listTagClass = Class.forName("net.minecraft.nbt.ListTag");
        Class<?> floatTagClass = Class.forName("net.minecraft.nbt.FloatTag");
        Object range = listTagClass.getConstructor().newInstance();
        Method valueOf = floatTagClass.getMethod("valueOf", float.class);
        Method add = listTagClass.getMethod("add", int.class, tagClass);
        add.invoke(range, 0, valueOf.invoke(null, minimum));
        add.invoke(range, 1, valueOf.invoke(null, maximum));
        compound.getClass().getMethod("put", String.class, tagClass)
            .invoke(compound, key, range);
    }

    private Object requiredNbtCompound(Object parentTag, String key) throws ReflectiveOperationException {
        Object result = parentTag.getClass().getMethod("getCompound", String.class).invoke(parentTag, key);
        if (result instanceof java.util.Optional<?> optional && optional.isPresent()) {
            return optional.get();
        }
        throw new IllegalStateException("Missing required NBT compound: " + key);
    }

    private void clearValousTemplateGeneratedChunks(Path worldRoot) throws IOException {
        for (String directoryName : List.of("region", "entities", "poi")) {
            Path generatedData = worldRoot.resolve(directoryName);
            if (Files.exists(generatedData)) {
                deleteDirectoryRecursively(generatedData);
            }
        }
    }

    private void prepareMatchWorldDatapacks(String worldName) {
        List<Path> sources = resolveMatchWorldDatapackSourcePaths();
        if (sources.isEmpty() || worldName == null || worldName.isBlank()) {
            return;
        }

        Path worldRoot = Bukkit.getWorldContainer().toPath().resolve(worldName);
        Path datapacksDir = worldRoot.resolve("datapacks");
        try {
            List<String> copied = copyDatapacksIntoDirectory(sources, worldRoot, datapacksDir);
            if (!copied.isEmpty()) {
                plugin.getLogger().info("[Queue] Prepared datapack(s) for match world '" + worldName
                    + "': " + String.join(", ", copied));
            }
        } catch (IOException ex) {
            plugin.getLogger().warning("Failed preparing datapacks for match world '"
                + worldName + "': " + ex.getMessage());
        }
    }

    private void ensureBundledMatchWorldDatapackAvailable() {
        for (String resource : BUNDLED_MATCH_WORLD_DATAPACK_RESOURCES) {
            try {
                plugin.saveResource(resource, true);
            } catch (IllegalArgumentException ignored) {
                plugin.getLogger().warning("Bundled match world datapack resource is missing: " + resource);
            } catch (Exception ex) {
                plugin.getLogger().warning("Failed to sync bundled match world datapack '" + resource
                    + "': " + ex.getMessage());
            }
        }
    }

    private void ensureBundledHellscapeStructureTemplatesAvailable() {
        for (String resource : BUNDLED_HELLSCAPE_STRUCTURE_RESOURCES) {
            try {
                plugin.saveResource(resource, true);
            } catch (IllegalArgumentException ignored) {
                plugin.getLogger().warning("Bundled Hellscape structure template is missing: " + resource);
            } catch (Exception ex) {
                plugin.getLogger().warning("Failed to sync Hellscape structure template '" + resource
                    + "': " + ex.getMessage());
            }
        }
    }

    private void ensureBundledHungerGamesMapStructureTemplatesAvailable() {
        for (String resource : BUNDLED_HUNGER_GAMES_MAP_STRUCTURE_RESOURCES) {
            try {
                plugin.saveResource(resource, true);
            } catch (IllegalArgumentException ignored) {
                plugin.getLogger().warning("Bundled Hunger Games map template is missing: " + resource);
            } catch (Exception ex) {
                plugin.getLogger().warning("Failed to sync Hunger Games map template '" + resource
                    + "': " + ex.getMessage());
            }
        }
    }

    private void syncStartupWorldDatapacks() {
        List<Path> sources = resolveMatchWorldDatapackSourcePaths();
        if (sources.isEmpty()) {
            return;
        }

        Path startupWorldRoot = resolvePrimaryLevelWorldRoot();
        if (startupWorldRoot == null) {
            return;
        }

        Path datapacksDir = startupWorldRoot.resolve("datapacks");
        try {
            List<String> copied = copyDatapacksIntoDirectory(sources, startupWorldRoot, datapacksDir);
            if (!copied.isEmpty()) {
                plugin.getLogger().info("[Queue] Synced startup-world datapack(s) into '"
                    + startupWorldRoot.getFileName() + "' for next boot: " + String.join(", ", copied));
            }
        } catch (IOException ex) {
            plugin.getLogger().warning("Failed syncing startup-world datapacks into '"
                + startupWorldRoot.getFileName() + "': " + ex.getMessage());
        }
    }

    private Path resolvePrimaryLevelWorldRoot() {
        Path worldContainer = Bukkit.getWorldContainer().toPath().normalize();
        String levelName = DEFAULT_PRIMARY_LEVEL_NAME;
        Path serverProperties = worldContainer.resolve("server.properties");
        if (Files.isRegularFile(serverProperties)) {
            Properties properties = new Properties();
            try (InputStream input = Files.newInputStream(serverProperties)) {
                properties.load(input);
                String configured = properties.getProperty("level-name");
                if (configured != null && !configured.isBlank()) {
                    levelName = configured.trim();
                }
            } catch (IOException ex) {
                plugin.getLogger().warning("Failed reading server.properties for level-name: " + ex.getMessage());
            }
        }
        if (levelName.isBlank()) {
            levelName = DEFAULT_PRIMARY_LEVEL_NAME;
        }
        return worldContainer.resolve(levelName).normalize();
    }

    private List<String> copyDatapacksIntoDirectory(List<Path> sources, Path worldRoot, Path datapacksDir) throws IOException {
        Files.createDirectories(datapacksDir);
        List<String> copied = new ArrayList<>();
        for (Path source : sources) {
            if (Files.isDirectory(source)) {
                Path targetPath;
                if (isDatapackRootDirectory(source)) {
                    targetPath = datapacksDir.resolve(source.getFileName().toString());
                    copyDatapackDirectory(source, targetPath);
                } else {
                    targetPath = datapacksDir;
                    copyDatapackDirectoryContents(source, datapacksDir);
                }
                copied.add(source.getFileName() + " -> " + worldRoot.relativize(targetPath));
                continue;
            }
            Path targetPath = datapacksDir.resolve(source.getFileName());
            Files.copy(source, targetPath, StandardCopyOption.REPLACE_EXISTING);
            copied.add(source.getFileName() + " -> " + worldRoot.relativize(targetPath));
        }
        return copied;
    }

    private void prepareMatchWorldStructureTemplates(String worldName) {
        if (worldName == null || worldName.isBlank()) {
            return;
        }
        Path sourceRoot = resolveActiveStructureTemplateSource();
        if (sourceRoot == null) {
            plugin.getLogger().warning("Structure template source path is null for match world '" + worldName + "'.");
            return;
        }
        if (!Files.isDirectory(sourceRoot)) {
            plugin.getLogger().warning("Structure template source path is not a directory for match world '"
                + worldName + "': " + sourceRoot);
            return;
        }
        Path worldPath = Bukkit.getWorldContainer().toPath().resolve(worldName);
        int copied = copyExternalStructureTemplatesIntoWorld(sourceRoot, worldPath);
        if (copied > 0) {
            plugin.getLogger().info("Prepared " + copied + " Hydra structure template(s) from "
                + sourceRoot + " into " + worldName + "/generated before world load.");
        }
        syncGlobalStructureTemplatesFrom(sourceRoot);
    }

    private Path resolveMatchWorldDatapackSourcePath() {
        if (matchWorldDatapackSourcePath == null || matchWorldDatapackSourcePath.isBlank()) {
            return null;
        }
        String trimmed = matchWorldDatapackSourcePath.trim();
        try {
            Path path = Path.of(trimmed);
            if (path.isAbsolute()) {
                Path normalized = path.normalize();
                if (Files.exists(normalized)) {
                    return normalized;
                }
                String trimmedAbsolute = trimmed.startsWith("/") || trimmed.startsWith("\\")
                    ? trimmed.substring(1)
                    : trimmed;
                if (!trimmedAbsolute.isBlank()) {
                    Path worldContainer = Bukkit.getWorldContainer().toPath().normalize();
                    Path serverRelative = worldContainer.resolve(trimmedAbsolute).normalize();
                    if (Files.exists(serverRelative)) {
                        return serverRelative;
                    }
                }
                return normalized;
            }
            Path worldContainer = Bukkit.getWorldContainer().toPath().normalize();
            Path worldRelative = worldContainer.resolve(path).normalize();
            if (Files.exists(worldRelative)) {
                return worldRelative;
            }
            Path dataRelative = plugin.getDataFolder().toPath().resolve(path).normalize();
            if (!Files.exists(dataRelative) && DEFAULT_MATCH_WORLD_DATAPACK_SOURCE.equals(trimmed)) {
                ensureBundledMatchWorldDatapackAvailable();
            }
            return dataRelative;
        } catch (Exception ex) {
            plugin.getLogger().warning("Invalid match world datapack source path '" + trimmed + "': " + ex.getMessage());
            return null;
        }
    }

    private List<Path> resolveMatchWorldDatapackSourcePaths() {
        ensureBundledMatchWorldDatapackAvailable();

        LinkedHashSet<Path> sources = new LinkedHashSet<>();
        Path configured = resolveMatchWorldDatapackSourcePath();
        if (configured != null && Files.exists(configured)) {
            sources.add(configured.normalize());
        } else if (configured != null) {
            plugin.getLogger().warning("Configured match world datapack source does not exist: " + configured);
        }

        for (String resource : BUNDLED_MATCH_WORLD_DATAPACK_RESOURCES) {
            Path bundled = plugin.getDataFolder().toPath().resolve(resource).normalize();
            if (Files.exists(bundled)) {
                sources.add(bundled);
            }
        }
        return List.copyOf(sources);
    }

    private boolean isDatapackRootDirectory(Path source) {
        if (source == null || !Files.isDirectory(source)) {
            return false;
        }
        return Files.isRegularFile(source.resolve("pack.mcmeta"));
    }

    private void copyDatapackDirectory(Path source, Path target) throws IOException {
        if (Files.exists(target)) {
            deleteDirectoryRecursively(target);
        }
        List<Path> paths;
        try (Stream<Path> walk = Files.walk(source)) {
            paths = walk.toList();
        }
        for (Path sourcePath : paths) {
            Path relative = source.relativize(sourcePath);
            Path targetPath = target.resolve(relative.toString());
            if (Files.isDirectory(sourcePath)) {
                Files.createDirectories(targetPath);
                continue;
            }
            Path parent = targetPath.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.copy(sourcePath, targetPath, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    private void copyDatapackDirectoryContents(Path source, Path target) throws IOException {
        try (Stream<Path> children = Files.list(source)) {
            for (Path child : children.toList()) {
                Path childTarget = target.resolve(child.getFileName().toString());
                if (Files.isDirectory(child)) {
                    copyDatapackDirectory(child, childTarget);
                } else {
                    Files.copy(child, childTarget, StandardCopyOption.REPLACE_EXISTING);
                }
            }
        }
    }

    private boolean shouldSkipTemplatePath(Path templateRoot, Path sourcePath) {
        Path relative = templateRoot.relativize(sourcePath);
        if (relative.getNameCount() > 0) {
            String top = relative.getName(0).toString().toLowerCase(Locale.ROOT);
            if ("playerdata".equals(top) || "stats".equals(top) || "advancements".equals(top)) {
                return true;
            }
        }

        Path fileName = sourcePath.getFileName();
        if (fileName == null) {
            return false;
        }
        String lower = fileName.toString().toLowerCase(Locale.ROOT);
        return "uid.dat".equals(lower) || "session.lock".equals(lower) || lower.endsWith(".lock");
    }

    private void deleteDirectoryRecursively(Path directory) throws IOException {
        List<Path> paths;
        try (Stream<Path> walk = Files.walk(directory)) {
            paths = new ArrayList<>(walk.toList());
        }
        Collections.reverse(paths);
        for (Path path : paths) {
            Files.deleteIfExists(path);
        }
    }

    private void runStructureCommands(World world) {
        dispatchConfiguredStructureCommands(world);
        startZipStructurePlacementAsync(world);
    }

    private void dispatchConfiguredStructureCommands(World world) {
        for (String rawCommand : matchStructureCommands) {
            if (rawCommand == null || rawCommand.isBlank()) {
                continue;
            }
            String command = rawCommand
                .replace("{dimension}", commandWorldId(world))
                .replace("{world}", world.getName());
            String worldExecutePrefix = "execute in " + world.getName() + " ";
            if (command.contains(worldExecutePrefix)) {
                command = command.replace(worldExecutePrefix, "execute in " + commandWorldId(world) + " ");
            }
            command = rewriteVanillaStructurePlaceToSurface(world, command);
            if (command == null) {
                continue;
            }
            if (isOriginStructurePlaceCommand(command)) {
                plugin.getLogger().warning("Skipping structure command in forbidden center zone (radius="
                    + originExclusionRadius() + "): " + command);
                continue;
            }
            Bukkit.dispatchCommand(Bukkit.getConsoleSender(), command);
        }
    }

    private String rewriteVanillaStructurePlaceToSurface(World world, String command) {
        if (world == null || command == null || command.isBlank()) {
            return command;
        }
        String[] parts = command.trim().split("\\s+");
        for (int i = 0; i < parts.length - 5; i++) {
            if (!parts[i].equalsIgnoreCase("place") || !parts[i + 1].equalsIgnoreCase("structure")) {
                continue;
            }
            String structureId = normalizeStructureId(parts[i + 2]);
            if (!structureId.startsWith("minecraft:")) {
                continue;
            }
            plugin.getLogger().info("Skipping vanilla structure command in BR world (" + structureId + "): " + command);
            return null;
        }
        return command;
    }

    private List<String> planStructureIdsForMatch(List<String> availableIds, int targetCount) {
        if (availableIds == null || availableIds.isEmpty() || targetCount <= 0) {
            return List.of();
        }
        Map<String, List<String>> idsByFamily = new HashMap<>();
        for (String rawId : availableIds) {
            String id = normalizeStructureId(rawId);
            StructureRule rule = structureRuleFor(id);
            String family = structureFamilyKey(rule);
            List<String> familyIds = idsByFamily.get(family);
            if (familyIds == null) {
                familyIds = new ArrayList<>();
                idsByFamily.put(family, familyIds);
            }
            familyIds.add(id);
        }
        for (List<String> familyIds : idsByFamily.values()) {
            Collections.shuffle(familyIds, ThreadLocalRandom.current());
        }

        List<String> families = new ArrayList<>(idsByFamily.keySet());
        families.sort((a, b) -> Integer.compare(
            tierPriority(primaryTierForFamily(idsByFamily, b)),
            tierPriority(primaryTierForFamily(idsByFamily, a))
        ));

        Map<String, Integer> selectedPerFamily = new HashMap<>();
        List<String> planned = new ArrayList<>();

        // Pass 1: one structure per family (prevents early same-family spam).
        for (String family : families) {
            if (planned.size() >= targetCount) {
                break;
            }
            List<String> pool = idsByFamily.get(family);
            if (pool == null || pool.isEmpty()) {
                continue;
            }
            planned.add(pool.remove(0));
            selectedPerFamily.put(family, selectedPerFamily.getOrDefault(family, 0) + 1);
        }

        // Pass 2: fill by tier while respecting family caps.
        boolean progressed = true;
        while (planned.size() < targetCount && progressed) {
            progressed = false;
            for (String family : families) {
                if (planned.size() >= targetCount) {
                    break;
                }
                List<String> pool = idsByFamily.get(family);
                if (pool == null || pool.isEmpty()) {
                    continue;
                }
                StructureRule rule = structureRuleFor(pool.get(0));
                int selected = selectedPerFamily.getOrDefault(family, 0);
                if (selected >= Math.max(1, rule.maxPerMatch())) {
                    continue;
                }
                planned.add(pool.remove(0));
                selectedPerFamily.put(family, selected + 1);
                progressed = true;
            }
        }

        return planned;
    }

    private List<String> filterHellscapeStructurePlan(World world, List<String> plannedIds) {
        if (plannedIds == null || plannedIds.isEmpty()) {
            return List.of();
        }
        if (world == null || world.getEnvironment() != World.Environment.NETHER) {
            return plannedIds.stream()
                .filter(id -> !isHellscapeStructure(id))
                .toList();
        }
        List<String> out = new ArrayList<>();
        int hellscapeCandidates = 0;
        int hellscapePicked = 0;
        for (String rawId : plannedIds) {
            String id = normalizeStructureId(rawId);
            if (!isHellscapeStructure(id)) {
                out.add(id);
                continue;
            }
            hellscapeCandidates++;
            double chance = hellscapeStructurePlacementChance(id);
            if (ThreadLocalRandom.current().nextDouble() <= chance) {
                out.add(id);
                hellscapePicked++;
            }
        }
        if (hellscapeCandidates > 0) {
            plugin.getLogger().info("[Hellscape] Selected " + hellscapePicked + "/" + hellscapeCandidates
                + " terrain feature template(s) for " + world.getName() + ".");
        }
        return out;
    }

    private static double hellscapeStructurePlacementChance(String structureId) {
        String path = hellscapeStructurePath(structureId);
        return switch (path) {
            case "the_colossus" -> 0.04D;
            case "infernal_canyon", "basalt_wall" -> 0.16D;
            case "dead_titan_ribcage", "basalt_crown" -> 0.20D;
            case "basalt_smoke_stack", "lavafall_cliffs", "blackstone_shelf", "hanging_lava_shelf",
                 "lava_delta", "broken_arch" -> 0.32D;
            case "ash_basin", "molten_crater", "basalt_teeth", "quartz_outcrop" -> 0.45D;
            case "magma_veins", "lava_chimneys", "charred_forest_remains", "soul_fissure", "ash_dunes" -> 0.62D;
            default -> 0.30D;
        };
    }

    private static int tierPriority(StructureTier tier) {
        return switch (tier) {
            case MAJOR -> 4;
            case SPECIAL -> 3;
            case MEDIUM -> 2;
            case MICRO -> 1;
        };
    }

    private StructureTier primaryTierForFamily(Map<String, List<String>> idsByFamily, String family) {
        if (idsByFamily == null || family == null) {
            return StructureTier.MICRO;
        }
        List<String> ids = idsByFamily.get(family);
        if (ids == null || ids.isEmpty()) {
            return StructureTier.MICRO;
        }
        return structureRuleFor(ids.get(0)).tier();
    }

    private static String structureFamilyKey(StructureRule rule) {
        if (rule == null) {
            return "misc";
        }
        String family = rule.family();
        if (family == null || family.isBlank()) {
            return "misc";
        }
        return family;
    }

    private static void addFamilyLocation(Map<String, List<Location>> families, String family, Location location) {
        if (families == null || family == null || location == null) {
            return;
        }
        List<Location> list = families.get(family);
        if (list == null) {
            list = new ArrayList<>();
            families.put(family, list);
        }
        list.add(location);
    }

    private void startZipStructurePlacementAsync(World world) {
        if (world == null || !matchStructureZipEnabled || matchStructureZipIds.isEmpty()) {
            return;
        }
        String worldName = world.getName();
        if (!asyncZipPlacementInProgress.add(worldName)) {
            return;
        }
        AsyncZipPlacementState state = createAsyncZipPlacementState(world);
        if (state == null) {
            asyncZipPlacementInProgress.remove(worldName);
            return;
        }
        continueZipStructurePlacement(state);
    }

    private AsyncZipPlacementState createAsyncZipPlacementState(World world) {
        if (world == null || !matchStructureZipEnabled || matchStructureZipIds.isEmpty()) {
            return null;
        }
        boolean placeAllIds = matchStructureZipPlaceAllIds;
        List<String> ids = new ArrayList<>(matchStructureZipIds);
        Collections.shuffle(ids, ThreadLocalRandom.current());
        if (!placeAllIds && matchStructureZipMaxCount > 0 && ids.size() > matchStructureZipMaxCount) {
            ids = new ArrayList<>(ids.subList(0, matchStructureZipMaxCount));
        }
        List<String> plannedIds = placeAllIds ? ids : planStructureIdsForMatch(ids, ids.size());
        plannedIds = filterHellscapeStructurePlan(world, plannedIds);
        if (plannedIds.isEmpty()) {
            plugin.getLogger().warning("No planned structure IDs after metadata filtering in " + world.getName());
            return null;
        }

        WorldBorder border = world.getWorldBorder();
        double half = Math.max(16.0D, (border.getSize() / 2.0D) - 8.0D);
        double radius = Math.min(matchStructureZipRadius, half);
        double centerX = border.getCenter().getX();
        double centerZ = border.getCenter().getZ();
        double minDistance = structureZoneRadius();
        List<Location> placedCenters = new ArrayList<>(collectStructureMarkerCenters(world));
        List<PlacedStructure> placedStructures = new ArrayList<>();
        Map<String, Integer> familyPlacedCount = new HashMap<>();
        Map<String, List<Location>> familyPlacedLocations = new HashMap<>();
        for (ArmorStand stand : world.getEntitiesByClass(ArmorStand.class)) {
            if (!isStructureMarker(stand)) {
                continue;
            }
            String id = markerStructureId(stand);
            if (id == null || id.isBlank()) {
                continue;
            }
            StructureRule placedRule = structureRuleFor(id);
            String family = structureFamilyKey(placedRule);
            familyPlacedCount.put(family, familyPlacedCount.getOrDefault(family, 0) + 1);
            addFamilyLocation(familyPlacedLocations, family, stand.getLocation());
            placedStructures.add(new PlacedStructure(stand.getLocation(), family, placedRule.tier()));
        }

        Set<Integer> bundleSlots = (placeAllIds || !matchStructureBundleEnabled)
            ? Set.of()
            : pickBundleSlots(plannedIds.size(), matchStructureBundleRolls);
        EnumMap<ResourceZone, Integer> zoneCounts = new EnumMap<>(ResourceZone.class);
        for (ResourceZone zone : ResourceZone.values()) {
            zoneCounts.put(zone, 0);
        }
        int plannedPerLandZone = Math.max(1, (int) Math.ceil(plannedIds.size() / 3.0D));
        return new AsyncZipPlacementState(
            world.getName(),
            plannedIds,
            centerX,
            centerZ,
            radius,
            minDistance,
            bundleSlots,
            zoneCounts,
            plannedPerLandZone,
            placedCenters,
            placedStructures,
            familyPlacedCount,
            familyPlacedLocations,
            new HashMap<>()
        );
    }

    private void continueZipStructurePlacement(AsyncZipPlacementState state) {
        if (state == null) {
            return;
        }
        World world = Bukkit.getWorld(state.worldName());
        if (world == null) {
            asyncZipPlacementInProgress.remove(state.worldName());
            return;
        }

        while (state.index < state.plannedIds().size()) {
            int planIndex = state.index++;
            String id = state.plannedIds().get(planIndex);
            StructureRule rule = structureRuleFor(id);
            String family = structureFamilyKey(rule);
            if ("cornucopia".equalsIgnoreCase(family)) {
                continue;
            }
            if (isExcludedFromMatchStructurePool(id)) {
                incrementCount(state.rejectCounts(), "reject_pool_excluded");
                continue;
            }
            if (!isWorldAllowedForStructure(world, id)) {
                plugin.getLogger().info("Skipping structure " + id
                    + " in " + world.getName() + " (Nether-only placement rule).");
                continue;
            }
            if (!matchStructureZipPlaceAllIds
                && state.familyPlacedCount().getOrDefault(family, 0) >= Math.max(1, rule.maxPerMatch())) {
                incrementCount(state.rejectCounts(), "reject_family_cap");
                continue;
            }

            boolean requireWater = requiresWaterSpawn(id);
            boolean requireMineshaft = isMineshaftStructure(id);
            ResourceZone preferredZone = requireWater
                ? ResourceZone.WETLAND
                : (requireMineshaft
                    ? ResourceZone.ROCK
                    : pickLeastFilledLandZone(state.zoneCounts(), state.plannedPerLandZone()));
            List<Location> familyLocations = state.familyPlacedLocations().getOrDefault(family, List.of());
            findPlacementCandidateAsync(
                world,
                state.centerX(),
                state.centerZ(),
                state.radius(),
                requireWater,
                id,
                state.placedCenters(),
                state.minDistance(),
                matchStructureZipEdgeBuffer,
                preferredZone,
                rule,
                familyLocations,
                state.placedStructures(),
                state.rejectCounts(),
                target -> {
                    World liveWorld = Bukkit.getWorld(state.worldName());
                    if (liveWorld == null) {
                        asyncZipPlacementInProgress.remove(state.worldName());
                        return;
                    }
                    if (target == null) {
                        plugin.getLogger().warning("Could not find placement for structure " + id
                            + " (requireWater=" + requireWater + ").");
                        continueZipStructurePlacement(state);
                        return;
                    }

                    int x = target.getBlockX();
                    int y = target.getBlockY();
                    int z = target.getBlockZ();
                    boolean ok;
                    if (!state.bundleSlots().isEmpty() && state.bundleSlots().contains(planIndex)) {
                        int bundlePlaced = placeStructureBundleAt(
                            liveWorld,
                            id,
                            x,
                            y,
                            z,
                            matchStructureBundleDepth,
                            state.placedCenters(),
                            state.minDistance(),
                            state.familyPlacedCount(),
                            state.familyPlacedLocations(),
                            state.placedStructures(),
                            state.rejectCounts()
                        );
                        ok = bundlePlaced > 0;
                        if (ok) {
                            state.bundled++;
                            state.placed += bundlePlaced;
                        }
                    } else {
                        ok = placeStructureAt(liveWorld, id, x, y, z, true, rule);
                    }
                    if (ok) {
                        if (state.bundleSlots().isEmpty() || !state.bundleSlots().contains(planIndex)) {
                            state.placed++;
                            state.placedCenters().add(target);
                            state.familyPlacedCount().put(family, state.familyPlacedCount().getOrDefault(family, 0) + 1);
                            addFamilyLocation(state.familyPlacedLocations(), family, target);
                            state.placedStructures().add(new PlacedStructure(target, family, rule.tier()));
                        }
                        ResourceZone placedZone = classifyResourceZone(
                            liveWorld,
                            target.getBlockX(),
                            target.getBlockY(),
                            target.getBlockZ(),
                            requireWater
                        );
                        plugin.getLogger().info("[Structures] Placed " + id + " at "
                            + x + "," + y + "," + z + " in " + liveWorld.getName());
                        state.zoneCounts().computeIfPresent(placedZone, (k, v) -> v + 1);
                    }
                    continueZipStructurePlacement(state);
                }
            );
            return;
        }

        plugin.getLogger().info("Placed " + state.placed + "/" + state.plannedIds().size()
            + " zip structures in " + world.getName()
            + " (bundled=" + state.bundled + ", depth=" + matchStructureBundleDepth
            + ", zoneRadius=" + Math.round(state.minDistance())
            + ", centerExclusion=" + structurePlacementOriginExclusionRadius()
            + ", centerBias=" + String.format(Locale.US, "%.2f", matchStructureZipCenterBias)
            + ", zones=" + state.zoneCounts()
            + ", rejects=" + formatRejectCounts(state.rejectCounts(), 12) + ").");
        storeStructureRejectSummary(world, state.plannedIds().size(), state.placed, state.bundled, state.rejectCounts());
        asyncZipPlacementInProgress.remove(state.worldName());
    }

    private void placeZipStructures(World world) {
        if (!matchStructureZipEnabled || matchStructureZipIds.isEmpty()) {
            return;
        }

        boolean placeAllIds = matchStructureZipPlaceAllIds;
        List<String> ids = new ArrayList<>(matchStructureZipIds);
        Collections.shuffle(ids, ThreadLocalRandom.current());
        if (!placeAllIds && matchStructureZipMaxCount > 0 && ids.size() > matchStructureZipMaxCount) {
            ids = new ArrayList<>(ids.subList(0, matchStructureZipMaxCount));
        }
        List<String> plannedIds = placeAllIds ? ids : planStructureIdsForMatch(ids, ids.size());
        plannedIds = filterHellscapeStructurePlan(world, plannedIds);
        if (plannedIds.isEmpty()) {
            plugin.getLogger().warning("No planned structure IDs after metadata filtering in " + world.getName());
            return;
        }

        WorldBorder border = world.getWorldBorder();
        double half = Math.max(16.0D, (border.getSize() / 2.0D) - 8.0D);
        double radius = Math.min(matchStructureZipRadius, half);
        double centerX = border.getCenter().getX();
        double centerZ = border.getCenter().getZ();
        double minDistance = structureZoneRadius();
        List<Location> placedCenters = new ArrayList<>(collectStructureMarkerCenters(world));
        List<PlacedStructure> placedStructures = new ArrayList<>();
        Map<String, Integer> familyPlacedCount = new HashMap<>();
        Map<String, List<Location>> familyPlacedLocations = new HashMap<>();
        Map<String, Integer> rejectCounts = new HashMap<>();
        STRUCTURE_PROTECTION_MASKS.remove(world.getName());

        for (ArmorStand stand : world.getEntitiesByClass(ArmorStand.class)) {
            if (!isStructureMarker(stand)) {
                continue;
            }
            String id = markerStructureId(stand);
            if (id == null || id.isBlank()) {
                continue;
            }
            StructureRule rule = structureRuleFor(id);
            String family = structureFamilyKey(rule);
            Location loc = stand.getLocation().clone();
            familyPlacedCount.put(family, familyPlacedCount.getOrDefault(family, 0) + 1);
            addFamilyLocation(familyPlacedLocations, family, loc);
            placedStructures.add(new PlacedStructure(loc, family, rule.tier()));
            registerStructureZone(world, id, loc.getBlockX(), loc.getBlockY(), loc.getBlockZ(), rule);
        }

        int placed = 0;
        int bundled = 0;
        Set<Integer> bundleSlots = (placeAllIds || !matchStructureBundleEnabled)
            ? Set.of()
            : pickBundleSlots(plannedIds.size(), matchStructureBundleRolls);
        Map<ResourceZone, Integer> zoneCounts = new EnumMap<>(ResourceZone.class);
        for (ResourceZone zone : ResourceZone.values()) {
            zoneCounts.put(zone, 0);
        }
        int plannedPerLandZone = Math.max(1, (int) Math.ceil(plannedIds.size() / 3.0D));

        for (int i = 0; i < plannedIds.size(); i++) {
            String id = plannedIds.get(i);
            StructureRule rule = structureRuleFor(id);
            String family = structureFamilyKey(rule);
            if ("cornucopia".equalsIgnoreCase(family)) {
                continue;
            }
            if (isExcludedFromMatchStructurePool(id)) {
                incrementCount(rejectCounts, "reject_pool_excluded");
                continue;
            }
            if (!isWorldAllowedForStructure(world, id)) {
                plugin.getLogger().info("Skipping structure " + id
                    + " in " + world.getName() + " (Nether-only placement rule).");
                continue;
            }
            if (!placeAllIds && familyPlacedCount.getOrDefault(family, 0) >= Math.max(1, rule.maxPerMatch())) {
                incrementCount(rejectCounts, "reject_family_cap");
                continue;
            }
            boolean requireWater = requiresWaterSpawn(id);
            boolean requireMineshaft = isMineshaftStructure(id);
            ResourceZone preferredZone = requireWater
                ? ResourceZone.WETLAND
                : (requireMineshaft ? ResourceZone.ROCK : pickLeastFilledLandZone(zoneCounts, plannedPerLandZone));
            List<Location> familyLocations = familyPlacedLocations.get(family);
            if (familyLocations == null) {
                familyLocations = List.of();
            }
            Location target = findPlacementCandidate(
                world,
                centerX,
                centerZ,
                radius,
                requireWater,
                id,
                placedCenters,
                minDistance,
                matchStructureZipEdgeBuffer,
                preferredZone,
                rule,
                familyLocations,
                placedStructures,
                rejectCounts
            );
            if (target == null) {
                plugin.getLogger().warning("Could not find placement for structure " + id
                    + " (requireWater=" + requireWater + ").");
                continue;
            }

            int x = target.getBlockX();
            int y = target.getBlockY();
            int z = target.getBlockZ();
            boolean ok;
            if (!bundleSlots.isEmpty() && bundleSlots.contains(i)) {
                int bundlePlaced = placeStructureBundleAt(
                    world,
                    id,
                    x,
                    y,
                    z,
                    matchStructureBundleDepth,
                    placedCenters,
                    minDistance,
                    familyPlacedCount,
                    familyPlacedLocations,
                    placedStructures,
                    rejectCounts
                );
                ok = bundlePlaced > 0;
                if (ok) {
                    bundled++;
                    placed += bundlePlaced;
                }
            } else {
                ok = placeStructureAt(world, id, x, y, z, true, rule);
            }
            if (ok) {
                if (bundleSlots.isEmpty() || !bundleSlots.contains(i)) {
                    placed++;
                    placedCenters.add(target);
                    familyPlacedCount.put(family, familyPlacedCount.getOrDefault(family, 0) + 1);
                    addFamilyLocation(familyPlacedLocations, family, target);
                    placedStructures.add(new PlacedStructure(target, family, rule.tier()));
                }
                ResourceZone placedZone = classifyResourceZone(
                    world,
                    target.getBlockX(),
                    target.getBlockY(),
                    target.getBlockZ(),
                    requireWater
                );
                plugin.getLogger().info("[Structures] Placed " + id + " at "
                    + x + "," + y + "," + z + " in " + world.getName());
                zoneCounts.computeIfPresent(placedZone, (k, v) -> v + 1);
            }
        }

        plugin.getLogger().info("Placed " + placed + "/" + plannedIds.size()
            + " zip structures in " + world.getName()
            + " (bundled=" + bundled + ", depth=" + matchStructureBundleDepth
            + ", zoneRadius=" + Math.round(minDistance)
            + ", centerExclusion=" + structurePlacementOriginExclusionRadius()
            + ", centerBias=" + String.format(Locale.US, "%.2f", matchStructureZipCenterBias)
            + ", zones=" + zoneCounts
            + ", rejects=" + formatRejectCounts(rejectCounts, 12) + ").");
        storeStructureRejectSummary(world, plannedIds.size(), placed, bundled, rejectCounts);
    }

    private Location findPlacementCandidate(
        World world,
        double centerX,
        double centerZ,
        double radius,
        boolean requireWater,
        String structureId,
        List<Location> placedCenters,
        double minDistance,
        int edgeBuffer,
        ResourceZone preferredZone
    ) {
        StructureRule rule = structureRuleFor(structureId);
        return findPlacementCandidate(
            world,
            centerX,
            centerZ,
            radius,
            requireWater,
            structureId,
            placedCenters,
            minDistance,
            edgeBuffer,
            preferredZone,
            rule,
            List.of(),
            List.of(),
            new HashMap<>()
        );
    }

    private Location findPlacementCandidate(
        World world,
        double centerX,
        double centerZ,
        double radius,
        boolean requireWater,
        String structureId,
        List<Location> placedCenters,
        double minDistance,
        int edgeBuffer,
        ResourceZone preferredZone,
        StructureRule rule,
        List<Location> familyLocations,
        List<PlacedStructure> placedStructures,
        Map<String, Integer> rejectCounts
    ) {
        StructureRule activeRule = rule == null ? structureRuleFor(structureId) : rule;
        List<Location> safeFamilyLocations = familyLocations == null ? List.of() : familyLocations;
        List<PlacedStructure> safePlacedStructures = placedStructures == null ? List.of() : placedStructures;

        boolean requireMineshaft = isMineshaftStructure(structureId);
        int preferredFastAttempts = preferredZone == null ? 0 : Math.max(8, STRUCTURE_FAST_ATTEMPTS / 2);
        double minSamplingRadius = samplingInnerRadius(world, centerX, centerZ, radius);
        int chunkRadius = placementChunkRadius(structureId, activeRule);
        for (int attempt = 0; attempt < STRUCTURE_FAST_ATTEMPTS; attempt++) {
            double angle = ThreadLocalRandom.current().nextDouble(0.0D, Math.PI * 2.0D);
            double dist = samplePlacementDistance(minSamplingRadius, radius);
            int x = (int) Math.round(centerX + (Math.cos(angle) * dist));
            int z = (int) Math.round(centerZ + (Math.sin(angle) * dist));
            if (!isOutsideOriginExclusion(x, z)) {
                incrementCount(rejectCounts, "reject_center_exclusion");
                continue;
            }
            if (isStructureSuppressedInAeos(world, x, z)) {
                incrementCount(rejectCounts, "reject_aeos_region");
                continue;
            }
            if (!isWithinWorldBorder(world, x, z, edgeBuffer)) {
                incrementCount(rejectCounts, "reject_border");
                continue;
            }
            if (!isChunkSquareLoaded(world, x, z, chunkRadius)) {
                incrementCount(rejectCounts, "reject_chunk_unloaded");
                continue;
            }
            Location candidate = validateLoadedPlacementCandidate(
                world,
                structureId,
                requireWater,
                activeRule,
                x,
                z,
                attempt,
                preferredZone,
                preferredFastAttempts,
                placedCenters,
                minDistance,
                safeFamilyLocations,
                safePlacedStructures,
                rejectCounts,
                requireMineshaft
            );
            if (candidate != null) {
                return candidate;
            }
        }
        return null;
    }

    private void findPlacementCandidateAsync(
        World world,
        double centerX,
        double centerZ,
        double radius,
        boolean requireWater,
        String structureId,
        List<Location> placedCenters,
        double minDistance,
        int edgeBuffer,
        ResourceZone preferredZone,
        StructureRule rule,
        List<Location> familyLocations,
        List<PlacedStructure> placedStructures,
        Map<String, Integer> rejectCounts,
        Consumer<Location> callback
    ) {
        if (world == null) {
            callback.accept(null);
            return;
        }
        StructureRule activeRule = rule == null ? structureRuleFor(structureId) : rule;
        List<Location> safeFamilyLocations = familyLocations == null ? List.of() : familyLocations;
        List<PlacedStructure> safePlacedStructures = placedStructures == null ? List.of() : placedStructures;
        boolean requireMineshaft = isMineshaftStructure(structureId);
        int preferredFastAttempts = preferredZone == null ? 0 : Math.max(4, STRUCTURE_ASYNC_ATTEMPTS / 2);
        double minSamplingRadius = samplingInnerRadius(world, centerX, centerZ, radius);
        int chunkRadius = placementChunkRadius(structureId, activeRule);
        continueFindPlacementCandidateAsync(
            world.getName(),
            centerX,
            centerZ,
            radius,
            requireWater,
            structureId,
            placedCenters,
            minDistance,
            edgeBuffer,
            preferredZone,
            activeRule,
            safeFamilyLocations,
            safePlacedStructures,
            rejectCounts,
            requireMineshaft,
            preferredFastAttempts,
            minSamplingRadius,
            chunkRadius,
            0,
            callback
        );
    }

    private void continueFindPlacementCandidateAsync(
        String worldName,
        double centerX,
        double centerZ,
        double radius,
        boolean requireWater,
        String structureId,
        List<Location> placedCenters,
        double minDistance,
        int edgeBuffer,
        ResourceZone preferredZone,
        StructureRule rule,
        List<Location> familyLocations,
        List<PlacedStructure> placedStructures,
        Map<String, Integer> rejectCounts,
        boolean requireMineshaft,
        int preferredFastAttempts,
        double minSamplingRadius,
        int chunkRadius,
        int attempt,
        Consumer<Location> callback
    ) {
        World world = Bukkit.getWorld(worldName);
        if (world == null) {
            callback.accept(null);
            return;
        }
        if (attempt >= STRUCTURE_ASYNC_ATTEMPTS) {
            callback.accept(null);
            return;
        }

        double angle = ThreadLocalRandom.current().nextDouble(0.0D, Math.PI * 2.0D);
        double dist = samplePlacementDistance(minSamplingRadius, radius);
        int x = (int) Math.round(centerX + (Math.cos(angle) * dist));
        int z = (int) Math.round(centerZ + (Math.sin(angle) * dist));
        if (!isOutsideOriginExclusion(x, z)) {
            incrementCount(rejectCounts, "reject_center_exclusion");
            continueFindPlacementCandidateAsync(
                worldName, centerX, centerZ, radius, requireWater, structureId, placedCenters, minDistance, edgeBuffer,
                preferredZone, rule, familyLocations, placedStructures, rejectCounts, requireMineshaft, preferredFastAttempts,
                minSamplingRadius, chunkRadius, attempt + 1, callback
            );
            return;
        }
        if (isStructureSuppressedInAeos(world, x, z)) {
            incrementCount(rejectCounts, "reject_aeos_region");
            continueFindPlacementCandidateAsync(
                worldName, centerX, centerZ, radius, requireWater, structureId, placedCenters, minDistance, edgeBuffer,
                preferredZone, rule, familyLocations, placedStructures, rejectCounts, requireMineshaft, preferredFastAttempts,
                minSamplingRadius, chunkRadius, attempt + 1, callback
            );
            return;
        }
        if (!isWithinWorldBorder(world, x, z, edgeBuffer)) {
            incrementCount(rejectCounts, "reject_border");
            continueFindPlacementCandidateAsync(
                worldName, centerX, centerZ, radius, requireWater, structureId, placedCenters, minDistance, edgeBuffer,
                preferredZone, rule, familyLocations, placedStructures, rejectCounts, requireMineshaft, preferredFastAttempts,
                minSamplingRadius, chunkRadius, attempt + 1, callback
            );
            return;
        }

        ensureChunkSquareLoadedAsync(world, x, z, chunkRadius, true)
            .whenComplete((loaded, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
                World liveWorld = Bukkit.getWorld(worldName);
                if (liveWorld == null) {
                    callback.accept(null);
                    return;
                }
                if (error != null || !Boolean.TRUE.equals(loaded) || !isChunkSquareLoaded(liveWorld, x, z, chunkRadius)) {
                    incrementCount(rejectCounts, "reject_chunk_load");
                    continueFindPlacementCandidateAsync(
                        worldName, centerX, centerZ, radius, requireWater, structureId, placedCenters, minDistance, edgeBuffer,
                        preferredZone, rule, familyLocations, placedStructures, rejectCounts, requireMineshaft, preferredFastAttempts,
                        minSamplingRadius, chunkRadius, attempt + 1, callback
                    );
                    return;
                }
                Location candidate = validateLoadedPlacementCandidate(
                    liveWorld,
                    structureId,
                    requireWater,
                    rule,
                    x,
                    z,
                    attempt,
                    preferredZone,
                    preferredFastAttempts,
                    placedCenters,
                    minDistance,
                    familyLocations,
                    placedStructures,
                    rejectCounts,
                    requireMineshaft
                );
                if (candidate != null) {
                    callback.accept(candidate);
                    return;
                }
                continueFindPlacementCandidateAsync(
                    worldName, centerX, centerZ, radius, requireWater, structureId, placedCenters, minDistance, edgeBuffer,
                    preferredZone, rule, familyLocations, placedStructures, rejectCounts, requireMineshaft, preferredFastAttempts,
                    minSamplingRadius, chunkRadius, attempt + 1, callback
                );
            }));
    }

    private Location validateLoadedPlacementCandidate(
        World world,
        String structureId,
        boolean requireWater,
        StructureRule rule,
        int x,
        int z,
        int attempt,
        ResourceZone preferredZone,
        int preferredAttempts,
        List<Location> placedCenters,
        double minDistance,
        List<Location> familyLocations,
        List<PlacedStructure> placedStructures,
        Map<String, Integer> rejectCounts,
        boolean requireMineshaft
    ) {
        StructurePlacementValidation validation = validateStructurePlacementCandidate(
            world,
            structureId,
            requireWater,
            rule,
            x,
            z,
            requireMineshaft
        );
        if (!validation.valid()) {
            incrementCount(rejectCounts, validation.rejectReason());
            return null;
        }
        int y = validation.y();
        ResourceZone zone = validation.zone();
        if (preferredZone != null && attempt < preferredAttempts && zone != preferredZone) {
            incrementCount(rejectCounts, "reject_zone_bias");
            return null;
        }
        Location candidate = new Location(world, x, y, z);
        if (minDistance > 0.0D && !isFarEnough(placedCenters, candidate, minDistance)) {
            incrementCount(rejectCounts, "reject_min_distance");
            return null;
        }
        if (!isFamilySpacingValid(familyLocations, candidate, rule.minFamilySpacing())) {
            incrementCount(rejectCounts, "reject_family_spacing");
            return null;
        }
        if (!isVisibilityDensityValid(placedStructures, candidate, rule)) {
            incrementCount(rejectCounts, "reject_visibility_density");
            return null;
        }
        if (hasCanopyObstruction(world, x, z, rule)) {
            incrementCount(rejectCounts, "reject_canopy");
            return null;
        }
        if (hasProtectedZoneOverlap(world, candidate, rule.zoneRadius())) {
            incrementCount(rejectCounts, "reject_zone_overlap");
            return null;
        }
        return candidate;
    }

    private boolean isFamilySpacingValid(List<Location> familyLocations, Location candidate, int minSpacing) {
        if (candidate == null || familyLocations == null || familyLocations.isEmpty() || minSpacing <= 0) {
            return true;
        }
        for (Location prior : familyLocations) {
            if (prior == null || prior.getWorld() == null || candidate.getWorld() == null) {
                continue;
            }
            if (!prior.getWorld().equals(candidate.getWorld())) {
                continue;
            }
            if (prior.distance(candidate) < minSpacing) {
                return false;
            }
        }
        return true;
    }

    private boolean isVisibilityDensityValid(List<PlacedStructure> placedStructures, Location candidate, StructureRule rule) {
        if (candidate == null || placedStructures == null || placedStructures.isEmpty() || rule == null) {
            return true;
        }
        double normalRadiusSq = STRUCTURE_VISIBILITY_RADIUS * STRUCTURE_VISIBILITY_RADIUS;
        double majorRadiusSq = STRUCTURE_MAJOR_VISIBILITY_RADIUS * STRUCTURE_MAJOR_VISIBILITY_RADIUS;
        int sameFamily = 0;
        int nearbyMedium = 0;
        int nearbyMajor = 0;
        for (PlacedStructure placed : placedStructures) {
            if (placed == null || placed.location() == null) {
                continue;
            }
            Location existing = placed.location();
            if (existing.getWorld() == null || !existing.getWorld().equals(candidate.getWorld())) {
                continue;
            }
            double distSq = existing.distanceSquared(candidate);
            if (distSq <= normalRadiusSq) {
                if (placed.family().equals(rule.family())) {
                    sameFamily++;
                }
                if (placed.tier() == StructureTier.MEDIUM) {
                    nearbyMedium++;
                } else if (placed.tier() == StructureTier.MAJOR) {
                    nearbyMajor++;
                }
            } else if (distSq <= majorRadiusSq && placed.tier() == StructureTier.MAJOR) {
                nearbyMajor++;
            }
        }
        if (sameFamily >= 1) {
            return false;
        }
        if (rule.tier() == StructureTier.MAJOR && nearbyMajor >= 1) {
            return false;
        }
        if (rule.tier() != StructureTier.MICRO && nearbyMedium >= 3) {
            return false;
        }
        return true;
    }

    private TerrainAssessment assessTerrain(World world, int x, int y, int z, StructureRule rule) {
        if (world == null || rule == null) {
            return new TerrainAssessment(y, 0, 0.0D, 1.0D, 0.0D, 0.0D);
        }
        int radius = Math.max(2, rule.footprintRadius());
        int step = radius >= 8 ? 2 : 1;
        int minSurfaceY = Integer.MAX_VALUE;
        int maxSurfaceY = Integer.MIN_VALUE;
        int total = 0;
        int airBelow = 0;
        int support = 0;
        int waterTop = 0;
        int badGround = 0;
        long sumSurfaceY = 0L;
        int sampleY = Math.max(world.getMinHeight() + 1, Math.min(world.getMaxHeight() - 2, y - 1));
        boolean allowWaterSurface = rule.placementMode() == PlacementMode.WATER;

        for (int dx = -radius; dx <= radius; dx += step) {
            for (int dz = -radius; dz <= radius; dz += step) {
                int sx = x + dx;
                int sz = z + dz;
                int surfaceY = findRealSurfaceY(world, sx, sz, allowWaterSurface, rule.canopyAllowed());
                minSurfaceY = Math.min(minSurfaceY, surfaceY);
                maxSurfaceY = Math.max(maxSurfaceY, surfaceY);
                sumSurfaceY += surfaceY;
                total++;

                Material topType = world.getBlockAt(sx, surfaceY, sz).getType();
                if (topType == Material.WATER) {
                    waterTop++;
                }
                if (!rule.canopyAllowed() && isGroundRejectMaterial(topType, false)) {
                    badGround++;
                }

                Block below = world.getBlockAt(sx, sampleY, sz);
                if (isStructuralSupport(below, rule.canopyAllowed())) {
                    support++;
                } else {
                    airBelow++;
                }
            }
        }

        if (total <= 0) {
            return new TerrainAssessment(y, 0, 0.0D, 1.0D, 0.0D, 0.0D);
        }
        int suggestedY = (int) Math.round((sumSurfaceY / (double) total) + 1.0D);
        int slopeDelta = Math.max(0, maxSurfaceY - minSurfaceY);
        double airBelowPercent = airBelow / (double) total;
        double supportPercent = support / (double) total;
        double waterTopPercent = waterTop / (double) total;
        double badGroundPercent = badGround / (double) total;
        return new TerrainAssessment(suggestedY, slopeDelta, airBelowPercent, supportPercent, waterTopPercent, badGroundPercent);
    }

    private StructurePlacementValidation validateStructurePlacementCandidate(
        World world,
        String structureId,
        boolean requireWater,
        StructureRule rule,
        int x,
        int z,
        boolean requireMineshaft
    ) {
        Integer y = pickPlacementYForStructure(world, structureId, x, z, requireWater, rule);
        if (y == null) {
            return StructurePlacementValidation.reject("reject_no_surface");
        }
        if (!isBiomeAllowedForStructure(world, x, y, z, rule)) {
            return StructurePlacementValidation.reject("reject_biome");
        }
        if (requireMineshaft && (!isMountainSurfaceBiome(world, x, z) || !hasTreeCoverNear(world, x, z, 6))) {
            return StructurePlacementValidation.reject("reject_mineshaft_context");
        }
        TerrainAssessment terrain = assessTerrain(world, x, y, z, rule);
        String terrainReject = terrainRejectReason(terrain, rule, requireWater);
        if (terrainReject != null) {
            return StructurePlacementValidation.reject(terrainReject);
        }
        int zoneY = requireMineshaft ? findRealSurfaceY(world, x, z, false) : y;
        if (hasProtectedZoneOverlap(world, new Location(world, x, zoneY, z), rule.zoneRadius())) {
            return StructurePlacementValidation.reject("reject_zone_overlap");
        }
        ResourceZone zone = classifyResourceZone(world, x, zoneY, z, requireWater);
        return StructurePlacementValidation.allow(y, zone, terrain);
    }

    private String terrainRejectReason(TerrainAssessment terrain, StructureRule rule, boolean requireWater) {
        if (terrain == null || rule == null) {
            return null;
        }
        if (requireWater || rule.placementMode() == PlacementMode.WATER) {
            return terrain.waterTopPercent() < 0.20D ? "reject_water_surface" : null;
        }
        if (rule.grounding() == GroundingMode.CAVE_EMBED) {
            return null;
        }
        if (!rule.canopyAllowed() && terrain.badGroundPercent() > 0.30D) {
            return "reject_bad_ground";
        }
        if ("cornucopia".equalsIgnoreCase(rule.family())) {
            return null;
        }
        if (terrain.slopeDelta() > rule.maxSlopeDelta()) {
            return "reject_slope";
        }
        double maxAir = rule.maxAirBelowPercent();
        double minSupport = rule.minSupportPercent();
        boolean cornucopiaFamily = "cornucopia".equalsIgnoreCase(rule.family());
        if (rule.grounding() == GroundingMode.PILLAR_SUPPORT) {
            maxAir = Math.max(maxAir, 0.72D);
            minSupport = Math.min(minSupport, 0.30D);
        } else if (!cornucopiaFamily
            && (rule.grounding() == GroundingMode.FLATTEN || rule.grounding() == GroundingMode.SURFACE_ONLY)) {
            maxAir = Math.max(maxAir, 0.38D);
            minSupport = Math.min(minSupport, 0.58D);
            if (rule.footprintRadius() >= 8) {
                maxAir = Math.max(maxAir, 0.46D);
                minSupport = Math.min(minSupport, 0.50D);
            }
        }
        if (terrain.airBelowPercent() > maxAir) {
            return "reject_air_below";
        }
        if (terrain.supportPercent() < minSupport) {
            return "reject_support";
        }
        return null;
    }

    private static boolean isStructuralSupport(Block block, boolean allowCanopy) {
        if (block == null) {
            return false;
        }
        Material type = block.getType();
        if (type == Material.WATER || type == Material.LAVA || type.isAir()) {
            return false;
        }
        if (isGroundRejectMaterial(type, allowCanopy)) {
            return false;
        }
        return type.isSolid() && !block.isPassable();
    }

    private boolean hasCanopyObstruction(World world, int x, int z, StructureRule rule) {
        if (world == null || rule == null || rule.canopyAllowed()) {
            return false;
        }
        int radius = Math.max(2, rule.footprintRadius());
        int step = radius >= 8 ? 2 : 1;
        int obstructed = 0;
        int total = 0;
        for (int dx = -radius; dx <= radius; dx += step) {
            for (int dz = -radius; dz <= radius; dz += step) {
                int sx = x + dx;
                int sz = z + dz;
                int surfaceY = findRealSurfaceY(world, sx, sz, false, false);
                total++;
                for (int yy = surfaceY + 1; yy <= Math.min(world.getMaxHeight() - 1, surfaceY + 8); yy++) {
                    Material type = world.getBlockAt(sx, yy, sz).getType();
                    if (!isSoftClearMaterial(type)) {
                        continue;
                    }
                    String name = type.name();
                    if (name.endsWith("_LEAVES")
                        || name.endsWith("_LOG")
                        || name.endsWith("_WOOD")
                        || name.endsWith("_VINES")
                        || name.equals("VINE")
                        || name.equals("BAMBOO")) {
                        obstructed++;
                        break;
                    }
                }
            }
        }
        if (total <= 0) {
            return false;
        }
        return (obstructed / (double) total) > 0.10D;
    }

    private boolean hasProtectedZoneOverlap(World world, Location candidate, int zoneRadius) {
        if (world == null || candidate == null) {
            return false;
        }
        List<StructureProtectionBox> zones = STRUCTURE_PROTECTION_MASKS.get(world.getName());
        if (zones == null || zones.isEmpty()) {
            return false;
        }
        int r = protectionRadiusFromZone(zoneRadius);
        int minX = candidate.getBlockX() - r;
        int maxX = candidate.getBlockX() + r;
        int minY = candidate.getBlockY() - 64;
        int maxY = candidate.getBlockY() + 64;
        int minZ = candidate.getBlockZ() - r;
        int maxZ = candidate.getBlockZ() + r;
        synchronized (zones) {
            for (StructureProtectionBox box : zones) {
                if (box == null) {
                    continue;
                }
                if (maxX < box.minX() || minX > box.maxX()) {
                    continue;
                }
                if (maxY < box.minY() || minY > box.maxY()) {
                    continue;
                }
                if (maxZ < box.minZ() || minZ > box.maxZ()) {
                    continue;
                }
                return true;
            }
        }
        return false;
    }

    private void registerStructureZone(World world, String id, int x, int y, int z, StructureRule rule) {
        if (world == null || rule == null) {
            return;
        }
        int radius = protectionRadiusFromZone(rule.zoneRadius());
        if ("cornucopia".equalsIgnoreCase(rule.family())) {
            radius = Math.max(radius, Math.max(40, originExclusionRadius() - 12));
        }
        int minX = x - radius;
        int maxX = x + radius;
        int minY = Math.max(world.getMinHeight(), y - 64);
        int maxY = Math.min(world.getMaxHeight() - 1, y + 96);
        int minZ = z - radius;
        int maxZ = z + radius;
        List<StructureProtectionBox> zones = STRUCTURE_PROTECTION_MASKS.computeIfAbsent(
            world.getName(),
            unused -> Collections.synchronizedList(new ArrayList<>())
        );
        zones.add(new StructureProtectionBox(
            world.getName(),
            minX,
            maxX,
            minY,
            maxY,
            minZ,
            maxZ
        ));
    }

    private double samplingInnerRadius(World world, double centerX, double centerZ, double maxRadius) {
        if (maxRadius <= 0.0D) {
            return 0.0D;
        }
        WorldBorder border = world.getWorldBorder();
        double borderCenterX = border.getCenter().getX();
        double borderCenterZ = border.getCenter().getZ();
        boolean isWorldCenterSample = Math.hypot(centerX - borderCenterX, centerZ - borderCenterZ) <= 2.0D;
        boolean borderCenterNearOrigin = Math.hypot(borderCenterX, borderCenterZ) <= 24.0D;
        if (!isWorldCenterSample || !borderCenterNearOrigin || maxRadius < 96.0D) {
            return 0.0D;
        }
        double structureExclusion = Math.max(0.0D, structurePlacementOriginExclusionRadius());
        if (structureExclusion <= 0.0D) {
            return 0.0D;
        }
        double midOffset = Math.hypot(cornucopiaCenterX() - centerX, cornucopiaCenterZ() - centerZ);
        double inner = Math.max(0.0D, structureExclusion + midOffset + 18.0D);
        return Math.min(inner, Math.max(0.0D, maxRadius - 12.0D));
    }

    private double samplePlacementDistance(double minRadius, double maxRadius) {
        if (maxRadius <= 0.0D) {
            return 0.0D;
        }
        double min = Math.max(0.0D, Math.min(minRadius, maxRadius));
        if (maxRadius - min <= 0.0001D) {
            return min;
        }
        double minSq = min * min;
        double maxSq = maxRadius * maxRadius;
        double sampledSq = minSq + (ThreadLocalRandom.current().nextDouble() * (maxSq - minSq));
        return Math.sqrt(sampledSq);
    }

    private static int protectionRadiusFromZone(int zoneRadius) {
        int radius = Math.max(1, zoneRadius);
        return Math.max(24, Math.min(radius, (int) Math.round(radius * 0.55D)));
    }

    private ResourceZone pickLeastFilledLandZone(Map<ResourceZone, Integer> counts, int softTarget) {
        ResourceZone best = ResourceZone.FOREST;
        int bestScore = Integer.MAX_VALUE;
        for (ResourceZone zone : List.of(ResourceZone.FOREST, ResourceZone.DESERT, ResourceZone.ROCK)) {
            int count = counts.getOrDefault(zone, 0);
            int penalty = count;
            if (count >= softTarget) {
                penalty += (count - softTarget) * 3;
            }
            if (penalty < bestScore) {
                bestScore = penalty;
                best = zone;
            }
        }
        return best;
    }

    private ResourceZone classifyResourceZone(World world, int x, int y, int z, boolean requireWater) {
        if (requireWater) {
            return ResourceZone.WETLAND;
        }
        Biome biome = world.getBiome(x, y, z);
        String biomeKey = biomeKey(biome);
        if (biomeMatches(biomeKey, "stony_peaks", "jagged_peaks", "snowy_taiga", "dripstone_caves")) {
            return ResourceZone.ROCK;
        }
        if (biomeMatches(biomeKey, "eroded_badlands", "badlands", "wooded_badlands")) {
            return ResourceZone.DESERT;
        }
        if (biomeMatches(biomeKey, "river", "frozen_river", "swamp", "mangrove_swamp", "beach", "stony_shore")) {
            return ResourceZone.WETLAND;
        }
        return ResourceZone.FOREST;
    }

    private static String biomeKey(Biome biome) {
        if (biome == null) {
            return "";
        }
        String key = biome.toString().toLowerCase(Locale.ROOT);
        int colon = key.indexOf(':');
        return colon >= 0 ? key.substring(colon + 1) : key;
    }

    private static boolean biomeMatches(String biomeKey, String... candidates) {
        for (String candidate : candidates) {
            if (biomeKey.equals(candidate)) {
                return true;
            }
        }
        return false;
    }

    private boolean isBiomeAllowedForStructure(World world, int x, int y, int z, StructureRule rule) {
        if (world == null || rule == null) {
            return true;
        }
        int sampleY = Math.max(world.getMinHeight() + 1, Math.min(world.getMaxHeight() - 1, y));
        String currentBiomeKey = biomeKey(world.getBiome(x, sampleY, z));
        if (blocksHydraLandStructureInDesert(rule, currentBiomeKey)) {
            return false;
        }
        Set<String> allowedBiomeKeys = rule.allowedBiomeKeys();
        if (allowedBiomeKeys == null || allowedBiomeKeys.isEmpty()) {
            return true;
        }
        return allowedBiomeKeys.contains(currentBiomeKey);
    }

    private boolean blocksHydraLandStructureInDesert(StructureRule rule, String biomeKey) {
        if (rule == null || biomeKey == null || biomeKey.isBlank()) {
            return false;
        }
        if (!biomeMatches(biomeKey, "desert", "badlands", "wooded_badlands", "eroded_badlands")) {
            return false;
        }
        String id = normalizeStructureId(rule.id());
        if (!id.startsWith(HYDRA_STRUCTURE_NAMESPACE + ":")) {
            return false;
        }
        if ("cornucopia".equalsIgnoreCase(rule.family())) {
            return false;
        }
        return rule.placementMode() != PlacementMode.WATER;
    }

    private static Integer findWaterSurfaceY(World world, int x, int z) {
        Block highest = world.getHighestBlockAt(x, z);
        Material topType = highest.getType();
        if (topType == Material.WATER) {
            return highest.getY();
        }
        // Handle columns where the highest block may be kelp/seagrass.
        Block cursor = highest;
        for (int i = 0; i < 8; i++) {
            Material type = cursor.getType();
            if (type == Material.WATER) {
                return cursor.getY();
            }
            if (type != Material.KELP
                && type != Material.KELP_PLANT
                && type != Material.SEAGRASS
                && type != Material.TALL_SEAGRASS) {
                break;
            }
            cursor = cursor.getRelative(0, -1, 0);
        }
        return null;
    }

    private static int findRealSurfaceY(World world, int x, int z, boolean allowWaterSurface) {
        return findRealSurfaceY(world, x, z, allowWaterSurface, false);
    }

    private static int findRealSurfaceY(
        World world,
        int x,
        int z,
        boolean allowWaterSurface,
        boolean allowCanopySurface
    ) {
        int minY = world.getMinHeight() + 1;
        int y = world.getHighestBlockYAt(x, z);
        if (y < minY) {
            return minY;
        }
        for (int yy = y; yy >= minY; yy--) {
            Material type = world.getBlockAt(x, yy, z).getType();
            if (type.isAir()) {
                continue;
            }
            if (allowWaterSurface && type == Material.WATER) {
                return yy;
            }
            if (!isGroundRejectMaterial(type, allowCanopySurface)) {
                return yy;
            }
        }
        return y;
    }

    private static boolean isGroundRejectMaterial(Material type, boolean allowCanopy) {
        if (type == null || type.isAir()) {
            return true;
        }
        if (type == Material.WATER || type == Material.LAVA) {
            return true;
        }
        String name = type.name();
        if (!allowCanopy && (name.endsWith("_LEAVES")
            || name.endsWith("_LOG")
            || name.endsWith("_WOOD")
            || name.endsWith("_SAPLING")
            || name.endsWith("_FUNGUS")
            || name.endsWith("_ROOTS")
            || name.endsWith("_MUSHROOM_BLOCK")
            || name.equals("MUSHROOM_STEM")
            || name.endsWith("_VINES")
            || name.endsWith("_MUSHROOM")
            || name.endsWith("_FLOWER")
            || name.endsWith("_BUSH")
            || name.endsWith("_CARPET")
            || name.endsWith("_GRASS")
            || name.endsWith("_FERN")
            || name.startsWith("POTTED_")
            || name.equals("BAMBOO")
            || name.equals("BAMBOO_SAPLING")
            || name.equals("VINE")
            || name.equals("KELP")
            || name.equals("KELP_PLANT")
            || name.equals("SEAGRASS")
            || name.equals("TALL_SEAGRASS")
            || name.equals("SNOW"))) {
            return true;
        }
        return !type.isSolid();
    }

    private static Integer pickPlacementY(World world, int x, int z, boolean requireWater) {
        return pickPlacementY(world, x, z, requireWater, false);
    }

    private static Integer pickPlacementY(
        World world,
        int x,
        int z,
        boolean requireWater,
        boolean allowCanopySurface
    ) {
        if (requireWater) {
            return findWaterSurfaceY(world, x, z);
        }
        int surfaceY = findRealSurfaceY(world, x, z, false, allowCanopySurface);
        Material type = world.getBlockAt(x, surfaceY, z).getType();
        if (type == Material.WATER || type.isAir() || isGroundRejectMaterial(type, allowCanopySurface)) {
            return null;
        }
        return surfaceY + 1;
    }

    private static Integer pickPlacementYForStructure(World world, String structureId, int x, int z, boolean requireWater) {
        return pickPlacementYForStructure(world, structureId, x, z, requireWater, null);
    }

    private static Integer pickPlacementYForStructure(
        World world,
        String structureId,
        int x,
        int z,
        boolean requireWater,
        StructureRule rule
    ) {
        boolean allowCanopySurface = rule != null && rule.canopyAllowed();
        Integer baseY = pickPlacementY(world, x, z, requireWater, allowCanopySurface);
        if (baseY == null) {
            return null;
        }
        String normalizedId = normalizeStructureId(structureId);
        if (!requireWater && isMineshaftStructure(structureId)) {
            int buried = baseY - 20;
            int minSafe = world.getMinHeight() + 8;
            int maxSafe = world.getMaxHeight() - 32;
            if (maxSafe < minSafe) {
                maxSafe = minSafe;
            }
            return Math.max(minSafe, Math.min(maxSafe, buried));
        }
        if (normalizedId.endsWith(":grannys_house")) {
            int buried = baseY - 4;
            int minSafe = world.getMinHeight() + 4;
            int maxSafe = world.getMaxHeight() - 10;
            if (maxSafe < minSafe) {
                maxSafe = minSafe;
            }
            return Math.max(minSafe, Math.min(maxSafe, buried));
        }
        if (rule != null && rule.placementMode() == PlacementMode.BURIED) {
            int buried = baseY - 2;
            int minSafe = world.getMinHeight() + 4;
            int maxSafe = world.getMaxHeight() - 8;
            if (maxSafe < minSafe) {
                maxSafe = minSafe;
            }
            return Math.max(minSafe, Math.min(maxSafe, buried));
        }
        return baseY;
    }

    private static boolean isChunkSquareLoaded(World world, int blockX, int blockZ, int chunkRadius) {
        int cx = blockX >> 4;
        int cz = blockZ >> 4;
        int radius = Math.max(0, chunkRadius);
        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                if (!world.isChunkLoaded(cx + dx, cz + dz)) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean loadChunkSquare(World world, int blockX, int blockZ, int chunkRadius) {
        return loadChunkSquare(world, blockX, blockZ, chunkRadius, true);
    }

    private static boolean loadChunkSquare(World world, int blockX, int blockZ, int chunkRadius, boolean generate) {
        int cx = blockX >> 4;
        int cz = blockZ >> 4;
        int radius = Math.max(0, chunkRadius);
        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                int tx = cx + dx;
                int tz = cz + dz;
                if (!world.isChunkLoaded(tx, tz)) {
                    boolean loaded = world.loadChunk(tx, tz, generate);
                    if (!loaded && !world.isChunkLoaded(tx, tz)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private CompletableFuture<Boolean> ensureChunkSquareLoadedAsync(
        World world,
        int blockX,
        int blockZ,
        int chunkRadius,
        boolean generate
    ) {
        if (world == null) {
            return CompletableFuture.completedFuture(false);
        }
        int cx = blockX >> 4;
        int cz = blockZ >> 4;
        int radius = Math.max(0, chunkRadius);
        List<CompletableFuture<Chunk>> futures = new ArrayList<>();
        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                int tx = cx + dx;
                int tz = cz + dz;
                if (world.isChunkLoaded(tx, tz)) {
                    continue;
                }
                futures.add(world.getChunkAtAsync(tx, tz, generate, true));
            }
        }
        if (futures.isEmpty()) {
            return CompletableFuture.completedFuture(true);
        }
        return CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new))
            .handle((ignored, error) -> error == null && isChunkSquareLoaded(world, blockX, blockZ, chunkRadius));
    }

    private CompletableFuture<Boolean> preloadMatchStartChunksAsync(World world, List<Location> locations, int chunkRadius) {
        if (world == null || locations == null || locations.isEmpty()) {
            return CompletableFuture.completedFuture(false);
        }
        int radius = Math.max(0, chunkRadius);
        Set<Long> chunkKeys = new LinkedHashSet<>();
        for (Location location : locations) {
            if (location == null || location.getWorld() == null || !world.equals(location.getWorld())) {
                continue;
            }
            int cx = location.getBlockX() >> 4;
            int cz = location.getBlockZ() >> 4;
            for (int dx = -radius; dx <= radius; dx++) {
                for (int dz = -radius; dz <= radius; dz++) {
                    int tx = cx + dx;
                    int tz = cz + dz;
                    long key = (((long) tx) << 32) ^ (tz & 0xFFFFFFFFL);
                    chunkKeys.add(key);
                }
            }
        }
        if (chunkKeys.isEmpty()) {
            return CompletableFuture.completedFuture(true);
        }
        List<CompletableFuture<Chunk>> futures = new ArrayList<>();
        for (long key : chunkKeys) {
            int chunkX = (int) (key >> 32);
            int chunkZ = (int) key;
            if (world.isChunkLoaded(chunkX, chunkZ)) {
                continue;
            }
            futures.add(world.getChunkAtAsync(chunkX, chunkZ, true, true));
        }
        if (futures.isEmpty()) {
            return CompletableFuture.completedFuture(true);
        }
        return CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new))
            .handle((ignored, error) -> {
                if (error != null) {
                    return false;
                }
                for (long key : chunkKeys) {
                    int chunkX = (int) (key >> 32);
                    int chunkZ = (int) key;
                    if (!world.isChunkLoaded(chunkX, chunkZ)) {
                        return false;
                    }
                }
                return true;
            });
    }

    private CompletableFuture<Boolean> preloadBrSpawnCandidateChunksAsync(World world) {
        if (world == null) {
            return CompletableFuture.completedFuture(false);
        }
        int minRing = Math.max(64, Math.min(brTerrainSpawnRingMin, brTerrainSpawnRingMax));
        int maxRing = Math.max(minRing + 8, Math.max(brTerrainSpawnRingMin, brTerrainSpawnRingMax));
        int maxChunkRadius = Math.max(1, (int) Math.ceil(maxRing / 16.0D) + 1);
        int minChunkRadius = Math.max(0, (int) Math.floor(minRing / 16.0D) - 1);
        List<CompletableFuture<Chunk>> futures = new ArrayList<>();
        for (int cx = -maxChunkRadius; cx <= maxChunkRadius; cx++) {
            for (int cz = -maxChunkRadius; cz <= maxChunkRadius; cz++) {
                double chunkCenterX = (cx * 16.0D) + 8.0D;
                double chunkCenterZ = (cz * 16.0D) + 8.0D;
                double distance = Math.hypot(chunkCenterX, chunkCenterZ);
                if (distance < (minChunkRadius * 16.0D) || distance > ((maxChunkRadius + 1) * 16.0D)) {
                    continue;
                }
                if (world.isChunkLoaded(cx, cz)) {
                    continue;
                }
                futures.add(world.getChunkAtAsync(cx, cz, true, true));
            }
        }
        if (futures.isEmpty()) {
            return CompletableFuture.completedFuture(true);
        }
        return CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new))
            .handle((ignored, error) -> error == null);
    }

    private boolean isChunkLoadedAt(World world, int blockX, int blockZ) {
        return world != null && world.isChunkLoaded(blockX >> 4, blockZ >> 4);
    }

    public void startFullWorldChunkPreload(World world, CommandSender notifier) {
        if (world == null) {
            if (notifier != null) {
                notifier.sendMessage(ChatColor.RED + "World not found.");
            }
            return;
        }
        String worldName = world.getName();
        if (fullWorldPreloadStates.containsKey(worldName)) {
            if (notifier != null) {
                notifier.sendMessage(ChatColor.YELLOW + "Full chunk preload is already running for " + worldName + ".");
            }
            return;
        }
        ChunkPreloadArea area = resolveFullWorldPreloadArea(world);
        if (area == null) {
            if (notifier != null) {
                notifier.sendMessage(ChatColor.RED + "No chunks resolved for preload.");
            }
            return;
        }
        List<Long> chunkKeys = new ArrayList<>();
        for (int cx = area.minChunkX(); cx <= area.maxChunkX(); cx++) {
            for (int cz = area.minChunkZ(); cz <= area.maxChunkZ(); cz++) {
                long key = (((long) cx) << 32) ^ (cz & 0xFFFFFFFFL);
                chunkKeys.add(key);
            }
        }
        if (chunkKeys.isEmpty()) {
            if (notifier != null) {
                notifier.sendMessage(ChatColor.RED + "No chunks resolved for border preload.");
            }
            return;
        }
        BrGenerationFlight flight = brGenerationFlightsByWorld.get(worldName);
        if (flight == null) {
            BrGenerationFlight creationFlight = brGenerationFlightCreationContext.get();
            if (creationFlight != null
                && !creationFlight.canceled
                && !creationFlight.isTerminal()
                && isCurrentBrGenerationFlight(creationFlight)) {
                flight = creationFlight;
            }
        }
        WorldChunkPreloadState state = new WorldChunkPreloadState(
            world,
            chunkKeys,
            notifier,
            area,
            flight
        );
        BukkitTask task = Bukkit.getScheduler().runTaskTimer(plugin, () -> tickFullWorldChunkPreload(state), 1L, 1L);
        state.task = task;
        fullWorldPreloadStates.put(worldName, state);
        BrWorldPreparationState prepState = brWorldPreparationStates.get(worldName);
        if (prepState != null) {
            prepState.setPhase(BrWorldPreparationPhase.PREGENERATING, 0, state.totalChunks);
        }
        updateBrGenerationProgress(worldName, 0, state.totalChunks);
        String preloadSummary = isHydraBrWorld(world)
            ? state.totalChunks + " chunks, border=" + effectiveBrTerrainBorderDiameter()
                + ", preload=" + effectiveBrTerrainPreloadDiameter()
            : state.totalChunks + " chunks";
        plugin.getLogger().info("[Queue] Started full chunk preload for " + worldName + " (" + preloadSummary + ").");
        if (notifier != null) {
            notifier.sendMessage(ChatColor.GREEN + "Started full chunk preload for " + worldName
                + ChatColor.GRAY + " (" + preloadSummary + ").");
        }
    }

    private void tickFullWorldChunkPreload(WorldChunkPreloadState state) {
        if (state == null) {
            return;
        }
        if (state.batchInProgress) {
            return;
        }
        World world = Bukkit.getWorld(state.worldName);
        if (world == null) {
            finishFullWorldChunkPreload(state, false, "world unloaded");
            return;
        }
        int end = Math.min(state.totalChunks, state.index + FULL_MATCH_PRELOAD_BATCH_SIZE);
        List<CompletableFuture<Chunk>> futures = new ArrayList<>();
        List<Long> batchKeys = new ArrayList<>();
        for (int i = state.index; i < end; i++) {
            long key = state.chunkKeys.get(i);
            int chunkX = (int) (key >> 32);
            int chunkZ = (int) key;
            batchKeys.add(key);
            futures.add(world.getChunkAtAsync(chunkX, chunkZ, true, true));
        }
        if (futures.isEmpty()) {
            finishFullWorldChunkPreload(state, true, null);
            return;
        }
        state.batchInProgress = true;
        CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new))
            .whenComplete((ignored, error) -> Bukkit.getScheduler().runTask(plugin, () -> {
                state.batchInProgress = false;
                if (!fullWorldPreloadStates.containsKey(state.worldName)) {
                    return;
                }
                for (int index = 0; index < futures.size(); index++) {
                    CompletableFuture<Chunk> future = futures.get(index);
                    long key = batchKeys.get(index);
                    try {
                        Chunk chunk = future.join();
                        if (chunk == null) {
                            state.failedChunkKeys.add(key);
                        } else {
                            state.completedChunkKeys.add(key);
                        }
                    } catch (RuntimeException ex) {
                        state.failedChunkKeys.add(key);
                        if (state.firstFailure == null) {
                            state.firstFailure = ex;
                        }
                    }
                }
                if (error != null || !state.failedChunkKeys.isEmpty()) {
                    String failure = error == null
                        ? "chunk_future_failed"
                        : error.getClass().getSimpleName() + ":" + error.getMessage();
                    finishFullWorldChunkPreload(state, false, failure);
                    return;
                }
                state.index = end;
                updateBrGenerationProgress(state.worldName, state.index, state.totalChunks);
                if (state.index >= state.totalChunks) {
                    finishFullWorldChunkPreload(state, true, null);
                    return;
                }
                if (state.index % FULL_MATCH_PRELOAD_PROGRESS_INTERVAL == 0) {
                    plugin.getLogger().info("[Queue] Full chunk preload progress for " + state.worldName + ": "
                        + state.index + "/" + state.totalChunks);
                    if (state.notifier != null) {
                        state.notifier.sendMessage(ChatColor.GRAY + "Chunk preload progress for " + state.worldName + ": "
                            + state.index + "/" + state.totalChunks);
                    }
                }
            }));
    }

    private void finishFullWorldChunkPreload(WorldChunkPreloadState state, boolean success, String reason) {
        if (state == null) {
            return;
        }
        fullWorldPreloadStates.remove(state.worldName);
        if (state.task != null) {
            state.task.cancel();
        }
        BrGenerationFlight flight = brGenerationFlightsByWorld.get(state.worldName);
        boolean canceled = flight == null || flight.canceled || !isCurrentBrGenerationFlight(flight);
        ValousPregenerationLedger ledger = state.toLedger(canceled);
        if (flight != null && flight.key.terrainProfile() == BrTerrainProfile.VALOUS) {
            valousPregenerationLedgers.put(state.worldName, ledger);
            plugin.getLogger().info("[Queue][ValousHandoff] event=ledger_completed world="
                + state.worldName + " world_uuid=" + ledger.worldId()
                + " token=" + ledger.generationToken()
                + " expected=" + ledger.expectedChunkCount()
                + " completed=" + ledger.completedChunkKeys().size()
                + " failed=" + ledger.failedChunkKeys().size()
                + " canceled=" + ledger.canceled()
                + " chunk_bounds=" + ledger.minChunkX() + "," + ledger.minChunkZ()
                + ".." + ledger.maxChunkX() + "," + ledger.maxChunkZ());
        }
        if (success
            && flight != null
            && flight.key.terrainProfile() == BrTerrainProfile.VALOUS
            && !ledger.isComplete()) {
            success = false;
            reason = "ledger_incomplete:expected=" + ledger.expectedChunkCount()
                + ",completed=" + ledger.completedChunkKeys().size()
                + ",failed=" + ledger.failedChunkKeys().size()
                + ",canceled=" + ledger.canceled();
        }
        if (success) {
            BrWorldPreparationState prepState = brWorldPreparationStates.get(state.worldName);
            if (prepState != null) {
                prepState.setPhase(BrWorldPreparationPhase.CHUNK_HANDOFF, 0, 1);
            }
            plugin.getLogger().info("[Queue] Full chunk preload finished for " + state.worldName + ".");
            if (state.notifier != null) {
                state.notifier.sendMessage(ChatColor.GREEN + "Full chunk preload finished for " + state.worldName + ".");
            }
        } else {
            plugin.getLogger().warning("[Queue] Full chunk preload stopped for " + state.worldName + " (" + reason + ").");
            if (flight != null && isCurrentBrGenerationFlight(flight)) {
                failBrGenerationFlight(flight, "preload_failed:" + reason);
                pendingMatchStarts.remove(flight.key.queueType());
                clearMatchStartInProgress(flight.key.queueType());
                cleanupWorld(state.worldName);
            }
            if (state.notifier != null) {
                state.notifier.sendMessage(ChatColor.RED + "Full chunk preload stopped for " + state.worldName
                    + " (" + reason + ").");
            }
        }
    }

    private static boolean isWithinWorldBorder(World world, double x, double z, int edgeBuffer) {
        WorldBorder border = world.getWorldBorder();
        double allowedHalf = (border.getSize() / 2.0D) - Math.max(0, edgeBuffer);
        if (allowedHalf <= 1.0D) {
            return false;
        }
        double centerX = border.getCenter().getX();
        double centerZ = border.getCenter().getZ();
        return Math.abs(x - centerX) <= allowedHalf && Math.abs(z - centerZ) <= allowedHalf;
    }

    private static boolean isFarEnough(List<Location> existing, Location candidate, double minDistance) {
        for (Location prior : existing) {
            if (!prior.getWorld().equals(candidate.getWorld())) {
                continue;
            }
            if (prior.distance(candidate) < minDistance) {
                return false;
            }
        }
        return true;
    }

    private double structureZoneRadius() {
        return Math.max(60.0D, matchStructureZipZoneRadius);
    }

    private int structureZoneRadiusInt() {
        return Math.max(60, (int) Math.round(structureZoneRadius()));
    }

    private int originExclusionRadius() {
        return Math.max(
            Math.max(STRUCTURE_CENTER_EXCLUSION_MIN, Math.max(0, matchStructureZipCenterExclusionRadius)),
            cornucopiaProtectedRadius() + 24
        );
    }

    private int structurePlacementOriginExclusionRadius() {
        return originExclusionRadius();
    }

    private static void incrementCount(Map<String, Integer> counters, String key) {
        if (counters == null || key == null || key.isBlank()) {
            return;
        }
        Integer current = counters.get(key);
        counters.put(key, current == null ? 1 : current + 1);
    }

    private static int totalRejects(Map<String, Integer> counters) {
        if (counters == null || counters.isEmpty()) {
            return 0;
        }
        int total = 0;
        for (Integer value : counters.values()) {
            if (value != null && value > 0) {
                total += value;
            }
        }
        return total;
    }

    private static List<Map.Entry<String, Integer>> sortedRejectEntries(Map<String, Integer> counters) {
        if (counters == null || counters.isEmpty()) {
            return List.of();
        }
        List<Map.Entry<String, Integer>> entries = new ArrayList<>();
        for (Map.Entry<String, Integer> entry : counters.entrySet()) {
            if (entry == null || entry.getKey() == null || entry.getKey().isBlank()) {
                continue;
            }
            int value = entry.getValue() == null ? 0 : Math.max(0, entry.getValue());
            entries.add(Map.entry(entry.getKey(), value));
        }
        entries.sort((a, b) -> {
            int byValue = Integer.compare(b.getValue(), a.getValue());
            if (byValue != 0) {
                return byValue;
            }
            return a.getKey().compareToIgnoreCase(b.getKey());
        });
        return entries;
    }

    private static String formatRejectCounts(Map<String, Integer> counters, int maxReasons) {
        List<Map.Entry<String, Integer>> entries = sortedRejectEntries(counters);
        if (entries.isEmpty()) {
            return "{}";
        }
        int limit = Math.max(1, maxReasons);
        StringBuilder out = new StringBuilder("{");
        for (int i = 0; i < entries.size() && i < limit; i++) {
            if (i > 0) {
                out.append(", ");
            }
            Map.Entry<String, Integer> entry = entries.get(i);
            out.append(entry.getKey()).append('=').append(entry.getValue());
        }
        if (entries.size() > limit) {
            out.append(", +").append(entries.size() - limit).append(" more");
        }
        out.append('}');
        return out.toString();
    }

    private void storeStructureRejectSummary(
        World world,
        int planned,
        int placed,
        int bundled,
        Map<String, Integer> rejectCounts
    ) {
        if (world == null) {
            return;
        }
        Map<String, Integer> snapshot = new HashMap<>();
        if (rejectCounts != null) {
            for (Map.Entry<String, Integer> entry : rejectCounts.entrySet()) {
                if (entry == null || entry.getKey() == null || entry.getKey().isBlank()) {
                    continue;
                }
                int value = entry.getValue() == null ? 0 : Math.max(0, entry.getValue());
                if (value > 0) {
                    snapshot.put(entry.getKey(), value);
                }
            }
        }
        StructureRejectSummary summary = new StructureRejectSummary(
            System.currentTimeMillis(),
            planned,
            placed,
            bundled,
            Map.copyOf(snapshot)
        );
        structureRejectSummaries.put(world.getName(), summary);
        plugin.getLogger().info("[Structures] Reject summary for " + world.getName()
            + ": total=" + totalRejects(snapshot)
            + ", reasons=" + formatRejectCounts(snapshot, 14));
    }

    private boolean isOutsideOriginExclusion(int x, int z) {
        double exclusionRadius = Math.max(0, structurePlacementOriginExclusionRadius());
        if (exclusionRadius <= 0.0D) {
            return true;
        }
        return Math.hypot(x - cornucopiaCenterX(), z - cornucopiaCenterZ()) >= exclusionRadius;
    }

    private List<Location> collectStructureMarkerCenters(World world) {
        List<Location> centers = new ArrayList<>();
        if (world == null) {
            return centers;
        }
        for (ArmorStand stand : world.getEntitiesByClass(ArmorStand.class)) {
            if (!isStructureMarker(stand)) {
                continue;
            }
            centers.add(stand.getLocation().clone());
        }
        return centers;
    }

    private Objective ensureStructurePlaceSuccessObjective() {
        ScoreboardManager manager = Bukkit.getScoreboardManager();
        if (manager == null) {
            return null;
        }
        Scoreboard board = manager.getMainScoreboard();
        if (board == null) {
            return null;
        }
        Objective objective = board.getObjective(STRUCTURE_PLACE_SUCCESS_OBJECTIVE);
        if (objective != null) {
            return objective;
        }
        try {
            return board.registerNewObjective(
                STRUCTURE_PLACE_SUCCESS_OBJECTIVE,
                Criteria.DUMMY,
                " "
            );
        } catch (IllegalArgumentException ignored) {
            return board.getObjective(STRUCTURE_PLACE_SUCCESS_OBJECTIVE);
        }
    }

    private boolean dispatchPlacementCommandWithSuccess(String rawCommand) {
        if (rawCommand == null || rawCommand.isBlank()) {
            return false;
        }
        Objective objective = ensureStructurePlaceSuccessObjective();
        if (objective == null) {
            return Bukkit.dispatchCommand(Bukkit.getConsoleSender(), rawCommand);
        }
        String probe = "hgplace_" + Integer.toUnsignedString(++structurePlaceProbeCounter, 36);
        objective.getScore(probe).setScore(0);
        String wrapped = "execute store success score " + probe + " " + objective.getName() + " run " + rawCommand;
        boolean dispatched = Bukkit.dispatchCommand(Bukkit.getConsoleSender(), wrapped);
        boolean success = false;
        if (dispatched) {
            try {
                success = objective.getScore(probe).getScore() > 0;
            } catch (IllegalStateException ignored) {
                success = false;
            }
        }
        objective.getScoreboard().resetScores(probe);
        return dispatched && success;
    }

    private boolean placeStructureAt(World world, String id, int x, int y, int z, boolean mark) {
        return placeStructureAt(world, id, x, y, z, mark, structureRuleFor(id));
    }

    private boolean placeStructureAt(World world, String id, int x, int y, int z, boolean mark, StructureRule rule) {
        return placeStructureAt(world, id, x, y, z, mark, rule, false);
    }

    private boolean placeStructureAt(World world, String id, int x, int y, int z, boolean mark, StructureRule rule, boolean allowCenterPlacement) {
        StructureRule activeRule = rule == null ? structureRuleFor(id) : rule;
        if (!allowCenterPlacement && !isOutsideOriginExclusion(x, z)) {
            plugin.getLogger().warning("Blocked structure placement for " + id + " at forbidden center zone in "
                + world.getName() + " (x=" + x + ", z=" + z + ", radius=" + structurePlacementOriginExclusionRadius() + ")");
            return false;
        }
        if (isStructureSuppressedInAeos(world, x, z)) {
            plugin.getLogger().info("Skipped structure placement for " + id + " inside Aeos no-structure zone in "
                + world.getName() + " at " + x + "," + z + ".");
            return false;
        }
        String normalizedId = normalizeStructureId(id);
        boolean allowStructureFallback = normalizedId.startsWith("minecraft:");
        if (!allowStructureFallback && unavailableTemplateIds.contains(normalizedId)) {
            return false;
        }
        boolean useDirectHydraPlacement = !allowStructureFallback
            && normalizedId.startsWith(HYDRA_STRUCTURE_NAMESPACE + ":")
            && hydraStructureTemplateFiles.containsKey(normalizedId);
        boolean chunksLoaded = useDirectHydraPlacement
            ? isStructurePlacementAreaLoaded(world, normalizedId, x, z, 1)
            : isChunkSquareLoaded(world, x, z, placementChunkRadius(id, activeRule));
        if (!chunksLoaded) {
            plugin.getLogger().warning("Skipped placement for " + id + " at " + x + "," + y + "," + z
                + " in " + world.getName() + " (required chunks are not loaded).");
            return false;
        }
        StructurePlacementValidation validation = validateStructurePlacementCandidate(
            world,
            id,
            activeRule.placementMode() == PlacementMode.WATER,
            activeRule,
            x,
            z,
            isMineshaftStructure(id)
        );
        if (!validation.valid()) {
            plugin.getLogger().warning("Skipped placement for " + id + " at " + x + "," + y + "," + z
                + " in " + world.getName() + " (" + validation.rejectReason() + ").");
            return false;
        }

        int placeY = resolvePlacementYForRule(world, y, validation.terrain(), activeRule);
        prepareGroundBeforePlacement(world, x, placeY, z, activeRule);

        boolean ok;
        if (useDirectHydraPlacement) {
            ok = placeHydraStructureDirectly(world, normalizedId, x, placeY, z);
        } else {
            String templateCommand = "execute in " + commandWorldId(world)
                + " run place template " + normalizedId + " " + x + " " + placeY + " " + z;
            ok = dispatchPlacementCommandWithSuccess(templateCommand);
            if (!ok && !allowStructureFallback && normalizedId.startsWith(HYDRA_STRUCTURE_NAMESPACE + ":")) {
                syncGlobalStructureTemplatesFrom(resolveActiveStructureTemplateSource());
                ok = dispatchPlacementCommandWithSuccess(templateCommand);
            }
            if (!ok && allowStructureFallback) {
                String structureCommand = "execute in " + commandWorldId(world)
                    + " run place structure " + normalizedId + " " + x + " " + placeY + " " + z;
                ok = dispatchPlacementCommandWithSuccess(structureCommand);
                if (!ok) {
                    plugin.getLogger().warning("Structure/template placement command failed: "
                        + templateCommand + " | fallback=" + structureCommand);
                    return false;
                }
            } else if (!ok) {
                unavailableTemplateIds.add(normalizedId);
                plugin.getLogger().warning("Template placement command failed: " + templateCommand);
                return false;
            }
        }
        if (ok) {
            unavailableTemplateIds.remove(normalizedId);
        }
        if (!ok) {
            unavailableTemplateIds.add(normalizedId);
            plugin.getLogger().warning("Hydra structure placement failed: " + normalizedId
                + " at " + x + "," + placeY + "," + z + " in " + world.getName());
            return false;
        }
        applyGroundingAfterPlacement(world, x, placeY, z, activeRule);
        adaptTerrainToStructure(world, x, placeY, z, activeRule);
        schedulePlacedStructureLoot(world, normalizedId, x, placeY, z, activeRule);
        if (isMineshaftStructure(normalizedId)) {
            exposeMineshaftEntrance(world, x, placeY, z, 20);
        }
        if (mark) {
            markStructurePlacement(world, normalizedId, x, placeY, z);
        }
        registerStructureZone(world, normalizedId, x, placeY, z, activeRule);
        return true;
    }

    private boolean placeCornucopiaStructureAt(World world, String id, int x, int y, int z, StructureRule rule) {
        if (world == null || id == null || id.isBlank()) {
            return false;
        }
        StructureRule activeRule = rule == null ? structureRuleFor(id) : rule;
        String normalizedId = normalizeStructureId(id);
        boolean chunksLoaded = isStructurePlacementAreaLoaded(world, normalizedId, x, z, 1);
        if (!chunksLoaded) {
            plugin.getLogger().warning("Skipped cornucopia placement for " + normalizedId + " at "
                + x + "," + y + "," + z + " in " + world.getName() + " (required chunks are not loaded).");
            return false;
        }
        if (resolveHydraStructure(normalizedId) == null) {
            plugin.getLogger().warning("Skipped cornucopia placement for " + normalizedId + " in "
                + world.getName() + " (template could not be loaded).");
            return false;
        }

        boolean ok = placeHydraStructureDirectly(world, normalizedId, x, y, z);
        if (!ok) {
            plugin.getLogger().warning("Cornucopia direct placement failed for " + normalizedId
                + " at " + x + "," + y + "," + z + " in " + world.getName() + ".");
            return false;
        }

        return true;
    }

    private void schedulePlacedStructureLoot(World world, String structureId, int x, int y, int z, StructureRule rule) {
        if (world == null || structureId == null || structureId.isBlank() || rule == null || menuService == null) {
            return;
        }
        String worldName = world.getName();
        String normalizedId = normalizeStructureId(structureId);
        Bukkit.getScheduler().runTask(plugin, () -> {
            World liveWorld = Bukkit.getWorld(worldName);
            if (liveWorld == null) {
                return;
            }
            populatePlacedStructureLoot(liveWorld, normalizedId, x, y, z, rule);
        });
    }

    private void populatePlacedStructureLoot(World world, String structureId, int x, int y, int z, StructureRule rule) {
        if (world == null || structureId == null || structureId.isBlank() || rule == null || managedLootService == null) {
            return;
        }
        int horizontalRadius = structureScanRadius(structureId, rule);
        int minY = Math.max(world.getMinHeight(), y - 8);
        int maxY = Math.min(world.getMaxHeight() - 1, y + Math.max(24, horizontalRadius));
        List<Block> containers = managedLootService.collectContainers(
            world,
            x - horizontalRadius,
            x + horizontalRadius,
            minY,
            maxY,
            z - horizontalRadius,
            z + horizontalRadius
        );
        if (usesBarrelOnlyCornucopiaLoot(structureId)) {
            containers = containers.stream()
                .filter(block -> block.getType() == Material.BARREL)
                .toList();
        }
        if (containers.isEmpty()) {
            return;
        }

        LootCategory category = lootCategoryForStructure(world, structureId, x, y, z);
        int totalGenerated = 0;
        int filled = 0;
        String lootGroup = structureLootGroup(world, structureId, x, y, z);
        for (int i = 0; i < containers.size(); i++) {
            String tableId = category.tableId((i % Math.max(1, category.chestCount())) + 1);
            int generated = managedLootService.populateManagedContainer(
                containers.get(i),
                tableId,
                ManagedLootService.SOURCE_STRUCTURE,
                lootGroup
            );
            if (generated > 0) {
                filled++;
                totalGenerated += generated;
            }
        }
        plugin.getLogger().info("[Loot] Filled " + filled + "/" + containers.size() + " containers for "
            + structureId + " in " + world.getName() + " using " + category.key()
            + " loot. Generated stacks=" + totalGenerated + ".");
    }

    private String structureLootGroup(World world, String structureId, int x, int y, int z) {
        if (world == null || structureId == null || structureId.isBlank()) {
            return null;
        }
        return world.getName() + ":" + normalizeStructureId(structureId) + ":" + x + ":" + y + ":" + z;
    }

    private LootCategory lootCategoryForStructure(World world, String structureId, int x, int y, int z) {
        String id = normalizeStructureId(structureId);
        if (id.equals(normalizeStructureId(cornucopiaStructureId))
            || distanceToCornucopiaAnchor(x, z) <= cornucopiaProtectedRadius()) {
            return LootCategory.CORNUCOPIA;
        }
        if (requiresNetherSpawn(id) || world.getEnvironment() == World.Environment.NETHER) {
            return LootCategory.BASTION;
        }
        if (requiresWaterSpawn(id)) {
            return LootCategory.OCEAN;
        }
        String key = id.contains(":") ? id.substring(id.indexOf(':') + 1) : id;
        if (key.contains("balloon") || key.contains("air")) {
            return LootCategory.AIR;
        }
        if (key.contains("desert")) {
            return LootCategory.SAND;
        }
        if (key.contains("jungle")) {
            return LootCategory.JUNGLE;
        }

        Biome biome = world.getBiome(x, Math.max(world.getMinHeight() + 1, Math.min(world.getMaxHeight() - 1, y)), z);
        if (biome == Biome.JUNGLE || biome == Biome.BAMBOO_JUNGLE || biome == Biome.SPARSE_JUNGLE) {
            return LootCategory.JUNGLE;
        }
        if (biome == Biome.DESERT || biome == Biome.BADLANDS || biome == Biome.WOODED_BADLANDS || biome == Biome.ERODED_BADLANDS) {
            return LootCategory.SAND;
        }
        if (biome == Biome.OCEAN || biome == Biome.DEEP_OCEAN || biome == Biome.COLD_OCEAN
            || biome == Biome.DEEP_COLD_OCEAN || biome == Biome.LUKEWARM_OCEAN || biome == Biome.DEEP_LUKEWARM_OCEAN
            || biome == Biome.WARM_OCEAN || biome == Biome.DEEP_FROZEN_OCEAN || biome == Biome.FROZEN_OCEAN
            || biome == Biome.RIVER || biome == Biome.FROZEN_RIVER || biome == Biome.BEACH || biome == Biome.STONY_SHORE) {
            return LootCategory.OCEAN;
        }
        return LootCategory.STANDARD;
    }

    private boolean usesBarrelOnlyCornucopiaLoot(String structureId) {
        String normalizedId = normalizeStructureId(structureId);
        return COPPER_GOLEM_CORNUCOPIA_STRUCTURE_ID.equals(normalizedId);
    }

    private int resolvePlacementYForRule(World world, int requestedY, TerrainAssessment terrain, StructureRule rule) {
        int minY = world.getMinHeight() + 2;
        int maxY = world.getMaxHeight() - 2;
        int y = Math.max(minY, Math.min(maxY, requestedY));
        if (terrain != null) {
            switch (rule.grounding()) {
                case FLATTEN -> y = Math.max(minY, Math.min(maxY, terrain.suggestedY()));
                case BURY -> y = Math.max(minY, Math.min(maxY, terrain.suggestedY() - 1));
                case PILLAR_SUPPORT, SURFACE_ONLY, WATER_SURFACE -> y = Math.max(minY, Math.min(maxY, Math.max(y, terrain.suggestedY())));
                case CAVE_EMBED -> {
                    // Keep requested cave Y for embedded structures.
                }
            }
        }
        return y;
    }

    private void prepareGroundBeforePlacement(World world, int x, int y, int z, StructureRule rule) {
        if (isHellscapeStructure(rule.id())) {
            prepareHellscapeGroundBeforePlacement(world, x, y, z, rule);
            return;
        }
        if (rule.grounding() != GroundingMode.FLATTEN && rule.grounding() != GroundingMode.SURFACE_ONLY) {
            return;
        }
        int radius = Math.max(2, rule.footprintRadius());
        int minY = world.getMinHeight() + 1;
        int clearTop = Math.min(world.getMaxHeight() - 2, y + 6);
        boolean circular = "cornucopia".equalsIgnoreCase(rule.family());
        int targetSurfaceY = Math.max(minY, y - 1);
        boolean softerSurfaceOnly = rule.grounding() == GroundingMode.SURFACE_ONLY;
        int maxRaise = circular ? 3 : (softerSurfaceOnly ? 4 : 3);
        int maxCut = circular ? 1 : (softerSurfaceOnly ? 2 : 1);
        int fillDepth = circular ? 5 : (softerSurfaceOnly ? 5 : 4);
        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                if (circular && Math.hypot(dx, dz) > radius + 0.5D) {
                    continue;
                }
                int tx = x + dx;
                int tz = z + dz;
                shapeTerrainColumn(world, tx, tz, targetSurfaceY, clearTop, maxRaise, maxCut, fillDepth);
            }
        }
    }

    private void applyGroundingAfterPlacement(World world, int x, int y, int z, StructureRule rule) {
        if (rule.grounding() != GroundingMode.PILLAR_SUPPORT) {
            return;
        }
        int radius = Math.max(2, rule.footprintRadius());
        int minY = world.getMinHeight() + 1;
        for (int dx = -radius; dx <= radius; dx++) {
            for (int dz = -radius; dz <= radius; dz++) {
                if (Math.abs(dx) != radius && Math.abs(dz) != radius && (((dx + dz) & 1) != 0)) {
                    continue;
                }
                int tx = x + dx;
                int tz = z + dz;
                int depthLimit = 28;
                Material fillMaterial = supportFillMaterial(world, tx, tz);
                for (int yy = y - 1; yy >= minY && depthLimit-- > 0; yy--) {
                    Block block = world.getBlockAt(tx, yy, tz);
                    if (isStructuralSupport(block, rule.canopyAllowed())) {
                        break;
                    }
                    if (block.getType() != Material.BEDROCK) {
                        block.setType(fillMaterial, false);
                    }
                }
            }
        }
    }

    private void adaptTerrainToStructure(World world, int x, int y, int z, StructureRule rule) {
        if (isHellscapeStructure(rule.id())) {
            adaptTerrainToHellscapeFeature(world, x, y, z, rule);
            return;
        }
        if (rule.placementMode() == PlacementMode.WATER
            || rule.grounding() == GroundingMode.CAVE_EMBED
            || "cornucopia".equalsIgnoreCase(rule.family())
            || (rule.grounding() != GroundingMode.FLATTEN
                && rule.grounding() != GroundingMode.SURFACE_ONLY
                && rule.grounding() != GroundingMode.PILLAR_SUPPORT)) {
            return;
        }
        int inner = Math.max(2, rule.footprintRadius()) + 2;
        int outer = inner + 6;
        int targetY = y - 1;
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;

        for (int dx = -outer; dx <= outer; dx++) {
            for (int dz = -outer; dz <= outer; dz++) {
                double ring = Math.max(Math.abs(dx), Math.abs(dz));
                if (ring <= inner || ring > outer) {
                    continue;
                }
                int tx = x + dx;
                int tz = z + dz;
                double t = clamp((ring - inner) / Math.max(1.0D, outer - inner), 0.0D, 1.0D);
                int currentTop = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, tx, tz, false, false)));
                int blendTarget = (int) Math.round((targetY * (1.0D - t)) + (currentTop * t));
                blendTarget = Math.max(minY, Math.min(maxY, blendTarget));
                shapeTerrainColumn(world, tx, tz, blendTarget, Math.min(maxY, targetY + 3), 6, 4, 4);
            }
        }
    }

    private void prepareHellscapeGroundBeforePlacement(World world, int x, int y, int z, StructureRule rule) {
        int radius = Math.max(3, rule.footprintRadius());
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int targetSurfaceY = Math.max(minY, Math.min(maxY, y - 1));
        String path = hellscapeStructurePath(rule.id());
        boolean terrainAdapts = hellscapeTerrainAdaptsToFeature(path);
        int prepRadius = terrainAdapts ? radius : Math.max(3, radius / 3);
        int clearTop = Math.min(maxY, y + (terrainAdapts ? 8 : 3));
        int maxRaise = terrainAdapts ? hellscapeMaxRaise(path) : 2;
        int maxCut = terrainAdapts ? hellscapeMaxCut(path) : 1;
        int fillDepth = terrainAdapts ? 8 : 4;

        for (int dx = -prepRadius; dx <= prepRadius; dx++) {
            for (int dz = -prepRadius; dz <= prepRadius; dz++) {
                double distance = Math.hypot(dx, dz);
                if (distance > prepRadius + 0.5D) {
                    continue;
                }
                int tx = x + dx;
                int tz = z + dz;
                int currentTop = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, tx, tz, false, false)));
                double edge = clamp(distance / Math.max(1.0D, prepRadius), 0.0D, 1.0D);
                int blendedTarget = terrainAdapts
                    ? (int) Math.round((targetSurfaceY * (1.0D - (edge * 0.35D))) + (currentTop * edge * 0.35D))
                    : Math.max(targetSurfaceY - 1, Math.min(targetSurfaceY + 1, currentTop));
                shapeTerrainColumn(world, tx, tz, blendedTarget, clearTop, maxRaise, maxCut, fillDepth);
            }
        }
    }

    private void adaptTerrainToHellscapeFeature(World world, int x, int y, int z, StructureRule rule) {
        String path = hellscapeStructurePath(rule.id());
        boolean terrainAdapts = hellscapeTerrainAdaptsToFeature(path);
        int inner = Math.max(3, rule.footprintRadius()) + (terrainAdapts ? 1 : 0);
        int outer = inner + (terrainAdapts ? 10 : 4);
        int targetY = y - 1;
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int maxRaise = terrainAdapts ? hellscapeMaxRaise(path) : 2;
        int maxCut = terrainAdapts ? hellscapeMaxCut(path) : 1;
        int fillDepth = terrainAdapts ? 8 : 4;

        for (int dx = -outer; dx <= outer; dx++) {
            for (int dz = -outer; dz <= outer; dz++) {
                double ring = Math.hypot(dx, dz);
                if (ring <= inner || ring > outer) {
                    continue;
                }
                int tx = x + dx;
                int tz = z + dz;
                double t = clamp((ring - inner) / Math.max(1.0D, outer - inner), 0.0D, 1.0D);
                int currentTop = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, tx, tz, false, false)));
                int blendTarget = (int) Math.round((targetY * (1.0D - t)) + (currentTop * t));
                blendTarget = Math.max(minY, Math.min(maxY, blendTarget));
                shapeTerrainColumn(world, tx, tz, blendTarget, Math.min(maxY, targetY + 4), maxRaise, maxCut, fillDepth);
            }
        }
    }

    private static boolean hellscapeTerrainAdaptsToFeature(String path) {
        return switch (path) {
            case "basalt_smoke_stack", "lavafall_cliffs", "blackstone_shelf", "ash_basin",
                 "infernal_canyon", "basalt_wall", "molten_crater", "hanging_lava_shelf",
                 "lava_delta", "the_colossus" -> true;
            default -> false;
        };
    }

    private static int hellscapeMaxRaise(String path) {
        return switch (path) {
            case "infernal_canyon", "basalt_wall", "lavafall_cliffs", "hanging_lava_shelf" -> 10;
            case "the_colossus", "basalt_smoke_stack", "blackstone_shelf" -> 8;
            case "ash_basin", "molten_crater", "lava_delta" -> 5;
            default -> 3;
        };
    }

    private static int hellscapeMaxCut(String path) {
        return switch (path) {
            case "infernal_canyon", "basalt_wall", "lavafall_cliffs", "hanging_lava_shelf" -> 6;
            case "ash_basin", "molten_crater", "lava_delta" -> 4;
            default -> 3;
        };
    }

    private void shapeTerrainColumn(
        World world,
        int x,
        int z,
        int desiredTop,
        int clearTop,
        int maxRaise,
        int maxCut,
        int fillDepth
    ) {
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int rawTargetTop = Math.max(minY, Math.min(maxY, desiredTop));
        int currentTop = Math.max(minY, Math.min(maxY, findRealSurfaceY(world, x, z, false, false)));
        if (currentTop - rawTargetTop > 10) {
            return;
        }
        int targetTop = rawTargetTop;
        if (maxRaise >= 0) {
            targetTop = Math.min(targetTop, currentTop + Math.max(0, maxRaise));
        }
        if (maxCut >= 0) {
            targetTop = Math.max(targetTop, currentTop - Math.max(0, maxCut));
        }
        Material fillMaterial = surfaceFillMaterial(world, x, z);
        Material topMaterial = surfaceTopMaterial(fillMaterial);

        if (currentTop < targetTop) {
            for (int yy = currentTop + 1; yy <= targetTop; yy++) {
                Block block = world.getBlockAt(x, yy, z);
                if (block.getType() == Material.BEDROCK) {
                    continue;
                }
                block.setType(yy == targetTop ? topMaterial : fillMaterial, false);
            }
        } else if (currentTop > targetTop) {
            for (int yy = currentTop; yy > targetTop; yy--) {
                Block block = world.getBlockAt(x, yy, z);
                if (block.getType() == Material.BEDROCK) {
                    continue;
                }
                if (yy == currentTop || isSoftClearMaterial(block.getType())) {
                    block.setType(Material.AIR, false);
                }
            }
            Block top = world.getBlockAt(x, targetTop, z);
            if (top.getType() != Material.BEDROCK) {
                top.setType(topMaterial, false);
            }
        } else {
            Block top = world.getBlockAt(x, targetTop, z);
            if (top.getType() != Material.BEDROCK && (top.getType().isAir() || !top.getType().isSolid())) {
                top.setType(topMaterial, false);
            }
        }

        for (int yy = targetTop + 1; yy <= Math.min(maxY, clearTop); yy++) {
            Block block = world.getBlockAt(x, yy, z);
            if (block.getType() == Material.BEDROCK) {
                continue;
            }
            if (isSoftClearMaterial(block.getType())) {
                block.setType(Material.AIR, false);
            }
        }

        for (int yy = targetTop - 1; yy >= Math.max(minY, targetTop - Math.max(1, fillDepth)); yy--) {
            Block block = world.getBlockAt(x, yy, z);
            if (isStructuralSupport(block, true)) {
                break;
            }
            if (block.getType() != Material.BEDROCK) {
                block.setType(fillMaterial, false);
            }
        }
    }

    private Material surfaceTopMaterial(Material fillMaterial) {
        if (fillMaterial == null) {
            return Material.GRASS_BLOCK;
        }
        return switch (fillMaterial) {
            case DIRT, COARSE_DIRT, PODZOL, MYCELIUM, MUD -> Material.GRASS_BLOCK;
            default -> fillMaterial;
        };
    }

    private int fixedCornucopiaPlatformY(World world) {
        Integer markerY = findCornucopiaPlacementY(world);
        if (markerY != null) {
            int minY = world.getMinHeight() + 1;
            int maxY = world.getMaxHeight() - 2;
            return Math.max(minY, Math.min(maxY, cornucopiaTerrainTopY(markerY)));
        }
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int baseline = CORNUCOPIA_FIXED_STRUCTURE_Y;
        return Math.max(minY, Math.min(maxY, baseline));
    }

    private Integer findCornucopiaPlacementY(World world) {
        if (world == null) {
            return null;
        }
        String expectedId = normalizeStructureId(cornucopiaStructureId);
        Location probe = cornucopiaAnchorProbe(world);
        for (Entity entity : world.getNearbyEntities(probe, 96.0D, 256.0D, 96.0D)) {
            if (!isStructureMarker(entity)) {
                continue;
            }
            String id = markerStructureId(entity);
            if (!expectedId.equals(normalizeStructureId(id))) {
                continue;
            }
            return entity.getLocation().getBlockY();
        }
        return null;
    }

    private static boolean isSoftClearMaterial(Material type) {
        if (type == null || type == Material.BEDROCK || type.isAir()) {
            return false;
        }
        String name = type.name();
        return !type.isSolid()
            || name.endsWith("_LEAVES")
            || name.endsWith("_LOG")
            || name.endsWith("_WOOD")
            || name.endsWith("_SAPLING")
            || name.endsWith("_FUNGUS")
            || name.endsWith("_ROOTS")
            || name.endsWith("_VINES")
            || name.endsWith("_MUSHROOM")
            || name.endsWith("_FLOWER")
            || name.endsWith("_BUSH")
            || name.endsWith("_CARPET")
            || name.endsWith("_GRASS")
            || name.endsWith("_FERN")
            || name.startsWith("POTTED_")
            || name.equals("BAMBOO")
            || name.equals("BAMBOO_SAPLING")
            || name.equals("VINE")
            || name.equals("KELP")
            || name.equals("KELP_PLANT")
            || name.equals("SEAGRASS")
            || name.equals("TALL_SEAGRASS")
            || name.equals("SNOW");
    }

    private Material surfaceFillMaterial(World world, int x, int z) {
        int y = findRealSurfaceY(world, x, z, false);
        Material top = world.getBlockAt(x, y, z).getType();
        if (world.getEnvironment() == World.Environment.NETHER) {
            return switch (top) {
                case NETHERRACK, BASALT, SMOOTH_BASALT, BLACKSTONE, POLISHED_BLACKSTONE, MAGMA_BLOCK,
                     SOUL_SAND, SOUL_SOIL, GRAVEL, NETHER_QUARTZ_ORE, NETHER_GOLD_ORE -> top;
                case LAVA -> Material.MAGMA_BLOCK;
                default -> Material.NETHERRACK;
            };
        }
        return switch (top) {
            case SAND, RED_SAND, GRAVEL, SNOW_BLOCK, PODZOL, COARSE_DIRT, MYCELIUM, MUD, CLAY, STONE, COBBLESTONE -> top;
            default -> Material.DIRT;
        };
    }

    private Material supportFillMaterial(World world, int x, int z) {
        Material fill = surfaceFillMaterial(world, x, z);
        if (world.getEnvironment() == World.Environment.NETHER) {
            return switch (fill) {
                case BASALT, SMOOTH_BASALT, BLACKSTONE, POLISHED_BLACKSTONE, MAGMA_BLOCK,
                     SOUL_SAND, SOUL_SOIL, GRAVEL -> fill;
                default -> Material.NETHERRACK;
            };
        }
        return switch (fill) {
            case SAND, RED_SAND -> fill;
            case SNOW_BLOCK -> Material.SNOW_BLOCK;
            case PODZOL, COARSE_DIRT, MYCELIUM, MUD, CLAY -> fill;
            case STONE, COBBLESTONE, GRAVEL -> Material.STONE;
            default -> Material.DIRT;
        };
    }

    private void exposeMineshaftEntrance(World world, int x, int y, int z, int exposedHeight) {
        int minY = world.getMinHeight() + 1;
        int maxY = world.getMaxHeight() - 2;
        int startY = Math.max(minY, y);
        int surfaceY = findRealSurfaceY(world, x, z, false) + 1;
        int endY = Math.min(maxY, Math.max(y + Math.max(8, exposedHeight), surfaceY));
        for (int yy = startY; yy <= endY; yy++) {
            for (int dx = -1; dx <= 1; dx++) {
                for (int dz = -1; dz <= 1; dz++) {
                    if ((dx * dx) + (dz * dz) > 2) {
                        continue;
                    }
                    Block block = world.getBlockAt(x + dx, yy, z + dz);
                    Material type = block.getType();
                    if (type == Material.BEDROCK) {
                        continue;
                    }
                    if (!type.isAir()) {
                        block.setType(Material.AIR, false);
                    }
                }
            }
        }
    }

    private int placeStructureBundleAt(
        World world,
        String seedId,
        int x,
        int y,
        int z,
        int depth,
        List<Location> occupiedCenters,
        double zoneRadius
    ) {
        return placeStructureBundleAt(
            world,
            seedId,
            x,
            y,
            z,
            depth,
            occupiedCenters,
            zoneRadius,
            new HashMap<>(),
            new HashMap<>(),
            new ArrayList<>(),
            new HashMap<>()
        );
    }

    private int placeStructureBundleAt(
        World world,
        String seedId,
        int x,
        int y,
        int z,
        int depth,
        List<Location> occupiedCenters,
        double zoneRadius,
        Map<String, Integer> familyPlacedCount,
        Map<String, List<Location>> familyPlacedLocations,
        List<PlacedStructure> placedStructures,
        Map<String, Integer> rejectCounts
    ) {
        int targetDepth = Math.max(1, depth);
        List<String> bundleIds = rollBundleIds(seedId, targetDepth);
        int success = 0;
        List<Location> blockedCenters = occupiedCenters == null
            ? new ArrayList<>(collectStructureMarkerCenters(world))
            : occupiedCenters;
        List<Location> localPlacements = new ArrayList<>();
        int spreadRadius = Math.max(
            Math.max(0, matchStructureBundleSpreadRadius),
            (int) Math.ceil(Math.max(0.0D, zoneRadius) * 1.8D)
        );
        double localMinDistance = Math.max(Math.max(0.0D, zoneRadius), Math.max(0.0D, matchStructureBundleMinDistance));

        for (String id : bundleIds) {
            StructureRule rule = structureRuleFor(id);
            String family = structureFamilyKey(rule);
            if (isExcludedFromMatchStructurePool(id)) {
                incrementCount(rejectCounts, "reject_pool_excluded");
                continue;
            }
            if (!isWorldAllowedForStructure(world, id)) {
                plugin.getLogger().info("Skipping bundled structure " + id
                    + " in " + world.getName() + " (Nether-only placement rule).");
                continue;
            }
            if (familyPlacedCount != null && familyPlacedCount.getOrDefault(family, 0) >= Math.max(1, rule.maxPerMatch())) {
                incrementCount(rejectCounts, "reject_family_cap");
                continue;
            }
            List<Location> familyLocations = familyPlacedLocations == null
                ? List.of()
                : (familyPlacedLocations.get(family) == null ? List.of() : familyPlacedLocations.get(family));
            Location placement = findBundlePlacement(
                world,
                id,
                x,
                z,
                spreadRadius,
                localPlacements,
                localMinDistance,
                blockedCenters,
                zoneRadius,
                rule,
                familyLocations,
                placedStructures,
                rejectCounts
            );
            if (placement == null) {
                plugin.getLogger().warning("Bundle placement failed for " + id
                    + " near " + x + "," + z + " (spread=" + spreadRadius + ").");
                continue;
            }
            if (placeStructureAt(world, id, placement.getBlockX(), placement.getBlockY(), placement.getBlockZ(), true, rule)) {
                success++;
                localPlacements.add(placement);
                blockedCenters.add(placement);
                if (familyPlacedCount != null) {
                    familyPlacedCount.put(family, familyPlacedCount.getOrDefault(family, 0) + 1);
                }
                if (familyPlacedLocations != null) {
                    addFamilyLocation(familyPlacedLocations, family, placement);
                }
                if (placedStructures != null) {
                    placedStructures.add(new PlacedStructure(placement, family, rule.tier()));
                }
            }
        }
        if (success == 0) {
            return 0;
        }
        plugin.getLogger().info("Placed bundled structure cluster near "
            + x + "," + y + "," + z + " -> " + bundleIds + " (placed=" + success + ")");
        return success;
    }

    private Location findBundlePlacement(
        World world,
        String structureId,
        int centerX,
        int centerZ,
        int spreadRadius,
        List<Location> localPlacements,
        double localMinDistance,
        List<Location> occupiedCenters,
        double occupiedMinDistance,
        StructureRule rule,
        List<Location> familyLocations,
        List<PlacedStructure> placedStructures,
        Map<String, Integer> rejectCounts
    ) {
        StructureRule activeRule = rule == null ? structureRuleFor(structureId) : rule;
        List<Location> safeFamilyLocations = familyLocations == null ? List.of() : familyLocations;
        List<PlacedStructure> safePlacedStructures = placedStructures == null ? List.of() : placedStructures;
        boolean requireWater = requiresWaterSpawn(structureId);
        boolean requireMineshaft = isMineshaftStructure(structureId);
        int chunkRadius = Math.max(1, ((Math.max(1, activeRule.footprintRadius()) + 6) + 15) / 16);
        for (int attempt = 0; attempt < STRUCTURE_FAST_ATTEMPTS; attempt++) {
            int x = centerX;
            int z = centerZ;
            if (attempt > 0 && spreadRadius > 0) {
                double angle = ThreadLocalRandom.current().nextDouble(0.0D, Math.PI * 2.0D);
                double distance = ThreadLocalRandom.current().nextDouble(0.0D, spreadRadius + 0.001D);
                x = centerX + (int) Math.round(Math.cos(angle) * distance);
                z = centerZ + (int) Math.round(Math.sin(angle) * distance);
            }
            if (!isOutsideOriginExclusion(x, z)) {
                incrementCount(rejectCounts, "reject_center_exclusion");
                continue;
            }
            if (isStructureSuppressedInAeos(world, x, z)) {
                incrementCount(rejectCounts, "reject_aeos_region");
                continue;
            }
            if (!isWithinWorldBorder(world, x, z, matchStructureZipEdgeBuffer)) {
                incrementCount(rejectCounts, "reject_border");
                continue;
            }
            if (!isChunkSquareLoaded(world, x, z, chunkRadius)) {
                incrementCount(rejectCounts, "reject_chunk_unloaded");
                continue;
            }
            Integer y = pickPlacementYForStructure(world, structureId, x, z, requireWater, activeRule);
            if (y == null) {
                incrementCount(rejectCounts, "reject_no_surface");
                continue;
            }
            if (requireMineshaft) {
                if (!isMountainSurfaceBiome(world, x, z) || !hasTreeCoverNear(world, x, z, 6)) {
                    incrementCount(rejectCounts, "reject_mineshaft_context");
                    continue;
                }
            }
            Location candidate = new Location(world, x, y, z);
            if (localMinDistance > 0.0D && !isFarEnough(localPlacements, candidate, localMinDistance)) {
                incrementCount(rejectCounts, "reject_bundle_local_spacing");
                continue;
            }
            if (occupiedMinDistance > 0.0D && !isFarEnough(occupiedCenters, candidate, occupiedMinDistance)) {
                incrementCount(rejectCounts, "reject_min_distance");
                continue;
            }
            if (!isFamilySpacingValid(safeFamilyLocations, candidate, activeRule.minFamilySpacing())) {
                incrementCount(rejectCounts, "reject_family_spacing");
                continue;
            }
            if (!isVisibilityDensityValid(safePlacedStructures, candidate, activeRule)) {
                incrementCount(rejectCounts, "reject_visibility_density");
                continue;
            }
            TerrainAssessment terrain = assessTerrain(world, x, y, z, activeRule);
            String terrainReject = terrainRejectReason(terrain, activeRule, requireWater);
            if (terrainReject != null) {
                incrementCount(rejectCounts, terrainReject);
                continue;
            }
            if (hasProtectedZoneOverlap(world, candidate, activeRule.zoneRadius())) {
                incrementCount(rejectCounts, "reject_zone_overlap");
                continue;
            }
            return candidate;
        }

        for (int attempt = 0; attempt < STRUCTURE_SLOW_ATTEMPTS; attempt++) {
            int x = centerX;
            int z = centerZ;
            if (spreadRadius > 0) {
                double angle = ThreadLocalRandom.current().nextDouble(0.0D, Math.PI * 2.0D);
                double distance = ThreadLocalRandom.current().nextDouble(0.0D, spreadRadius + 0.001D);
                x = centerX + (int) Math.round(Math.cos(angle) * distance);
                z = centerZ + (int) Math.round(Math.sin(angle) * distance);
            }
            if (!isOutsideOriginExclusion(x, z)) {
                incrementCount(rejectCounts, "reject_center_exclusion");
                continue;
            }
            if (isStructureSuppressedInAeos(world, x, z)) {
                incrementCount(rejectCounts, "reject_aeos_region");
                continue;
            }
            if (!isWithinWorldBorder(world, x, z, matchStructureZipEdgeBuffer)) {
                incrementCount(rejectCounts, "reject_border");
                continue;
            }
            if (!loadChunkSquare(world, x, z, chunkRadius)) {
                incrementCount(rejectCounts, "reject_chunk_load");
                continue;
            }
            Integer y = pickPlacementYForStructure(world, structureId, x, z, requireWater, activeRule);
            if (y == null) {
                incrementCount(rejectCounts, "reject_no_surface");
                continue;
            }
            if (requireMineshaft) {
                if (!isMountainSurfaceBiome(world, x, z) || !hasTreeCoverNear(world, x, z, 6)) {
                    incrementCount(rejectCounts, "reject_mineshaft_context");
                    continue;
                }
            }
            Location candidate = new Location(world, x, y, z);
            if (localMinDistance > 0.0D && !isFarEnough(localPlacements, candidate, localMinDistance)) {
                incrementCount(rejectCounts, "reject_bundle_local_spacing");
                continue;
            }
            if (occupiedMinDistance > 0.0D && !isFarEnough(occupiedCenters, candidate, occupiedMinDistance)) {
                incrementCount(rejectCounts, "reject_min_distance");
                continue;
            }
            if (!isFamilySpacingValid(safeFamilyLocations, candidate, activeRule.minFamilySpacing())) {
                incrementCount(rejectCounts, "reject_family_spacing");
                continue;
            }
            if (!isVisibilityDensityValid(safePlacedStructures, candidate, activeRule)) {
                incrementCount(rejectCounts, "reject_visibility_density");
                continue;
            }
            TerrainAssessment terrain = assessTerrain(world, x, y, z, activeRule);
            String terrainReject = terrainRejectReason(terrain, activeRule, requireWater);
            if (terrainReject != null) {
                incrementCount(rejectCounts, terrainReject);
                continue;
            }
            if (hasProtectedZoneOverlap(world, candidate, activeRule.zoneRadius())) {
                incrementCount(rejectCounts, "reject_zone_overlap");
                continue;
            }
            return candidate;
        }
        return null;
    }

    private List<String> rollBundleIds(String seedId, int depth) {
        LinkedHashSet<String> picked = new LinkedHashSet<>();
        picked.add(seedId);
        if (matchStructureZipIds.isEmpty()) {
            return new ArrayList<>(picked);
        }
        List<String> pool = new ArrayList<>(matchStructureZipIds);
        Collections.shuffle(pool, ThreadLocalRandom.current());
        for (String candidate : pool) {
            picked.add(candidate);
            if (picked.size() >= depth) {
                break;
            }
        }
        List<String> out = new ArrayList<>(picked);
        while (out.size() < depth && !out.isEmpty()) {
            out.add(out.get(ThreadLocalRandom.current().nextInt(out.size())));
        }
        return out;
    }

    private static Set<Integer> pickBundleSlots(int poolSize, int rolls) {
        if (poolSize <= 0 || rolls <= 0) {
            return Set.of();
        }
        List<Integer> indexes = new ArrayList<>(poolSize);
        for (int i = 0; i < poolSize; i++) {
            indexes.add(i);
        }
        Collections.shuffle(indexes, ThreadLocalRandom.current());
        int count = Math.min(poolSize, rolls);
        return new LinkedHashSet<>(indexes.subList(0, count));
    }

    private void markStructurePlacement(World world, String id, int x, int y, int z) {
        Location markerLoc = new Location(world, x + 0.5D, y + 0.1D, z + 0.5D);
        ArmorStand marker = world.spawn(markerLoc, ArmorStand.class, stand -> {
            stand.setVisible(false);
            stand.setMarker(true);
            stand.setGravity(false);
            stand.setInvulnerable(true);
            stand.setSilent(true);
            stand.setCollidable(false);
            stand.setCustomNameVisible(false);
            stand.setPersistent(true);
        });
        marker.getPersistentDataContainer().set(structureMarkerKey, PersistentDataType.BYTE, (byte) 1);
        marker.getPersistentDataContainer().set(structureMarkerIdKey, PersistentDataType.STRING, normalizeStructureId(id));
    }

    private boolean isStructureMarker(Entity entity) {
        if (!(entity instanceof ArmorStand stand)) {
            return false;
        }
        Byte marker = stand.getPersistentDataContainer().get(structureMarkerKey, PersistentDataType.BYTE);
        return marker != null && marker == (byte) 1;
    }

    private String markerStructureId(Entity entity) {
        if (!(entity instanceof ArmorStand stand)) {
            return null;
        }
        return stand.getPersistentDataContainer().get(structureMarkerIdKey, PersistentDataType.STRING);
    }

    private StructureRule structureRuleFor(String structureId) {
        String id = normalizeStructureId(structureId);
        StructureRule cached = structureRuleCache.get(id);
        if (cached != null) {
            return cached;
        }

        String family = inferStructureFamily(id);
        boolean requireWater = requiresWaterSpawn(id);
        boolean mineshaft = isMineshaftStructure(id);

        StructureTier tier = inferStructureTier(id, family);
        GroundingMode grounding = inferGroundingMode(id, family, requireWater, mineshaft);
        PlacementMode placementMode = inferPlacementMode(requireWater, mineshaft, grounding);

        int maxPerMatch = inferMaxPerMatch(family, tier);
        int minFamilySpacing = inferMinFamilySpacing(family, tier);
        int maxSlopeDelta = inferMaxSlopeDelta(family, tier, grounding);
        int footprintRadius = inferFootprintRadius(family, tier);
        int zoneRadius = Math.max(structureZoneRadiusInt(), inferZoneRadius(family, tier, footprintRadius));
        double maxAirBelowPercent = STRUCTURE_DEFAULT_MAX_AIR_BELOW;
        double minSupportPercent = STRUCTURE_DEFAULT_MIN_SUPPORT;
        boolean canopyAllowed = false;
        boolean flattenRequired = false;
        Set<String> allowedBiomeKeys = inferDefaultAllowedBiomeKeys(id, family);
        Set<World.Environment> allowedEnvironments = inferAllowedEnvironments(id);

        StructureRuleOverride override = overrideForStructureId(id);
        if (override != null) {
            family = override.family() != null ? override.family() : family;
            tier = override.tier() != null ? override.tier() : tier;
            maxPerMatch = override.maxPerMatch() != null ? override.maxPerMatch() : maxPerMatch;
            minFamilySpacing = override.minFamilySpacing() != null ? override.minFamilySpacing() : minFamilySpacing;
            maxSlopeDelta = override.maxSlopeDelta() != null ? override.maxSlopeDelta() : maxSlopeDelta;
            grounding = override.grounding() != null ? override.grounding() : grounding;
            placementMode = override.placementMode() != null ? override.placementMode() : placementMode;
            zoneRadius = override.zoneRadius() != null ? override.zoneRadius() : zoneRadius;
            footprintRadius = override.footprintRadius() != null ? override.footprintRadius() : footprintRadius;
            maxAirBelowPercent = override.maxAirBelowPercent() != null ? override.maxAirBelowPercent() : maxAirBelowPercent;
            minSupportPercent = override.minSupportPercent() != null ? override.minSupportPercent() : minSupportPercent;
            canopyAllowed = override.canopyAllowed() != null ? override.canopyAllowed() : canopyAllowed;
            flattenRequired = override.flattenRequired() != null ? override.flattenRequired() : flattenRequired;
            allowedBiomeKeys = override.allowedBiomeKeys() != null ? override.allowedBiomeKeys() : allowedBiomeKeys;
            allowedEnvironments = override.allowedEnvironments() != null ? override.allowedEnvironments() : allowedEnvironments;
        }

        boolean cornucopiaFamily = "cornucopia".equalsIgnoreCase(family);
        if (id.endsWith(":grannys_house")) {
            family = "estate";
            tier = StructureTier.MAJOR;
            grounding = GroundingMode.BURY;
            placementMode = PlacementMode.BURIED;
            flattenRequired = false;
            footprintRadius = Math.max(footprintRadius, 11);
            zoneRadius = Math.min(zoneRadius, 88);
            maxSlopeDelta = Math.max(maxSlopeDelta, 9);
            maxAirBelowPercent = Math.max(maxAirBelowPercent, 0.60D);
            minSupportPercent = Math.min(minSupportPercent, 0.35D);
        } else if (id.endsWith(":noob_house")) {
            family = "house";
            tier = StructureTier.MEDIUM;
            grounding = GroundingMode.SURFACE_ONLY;
            placementMode = PlacementMode.SURFACE;
            flattenRequired = false;
            footprintRadius = Math.max(footprintRadius, 7);
            zoneRadius = Math.min(zoneRadius, 82);
            maxSlopeDelta = Math.max(maxSlopeDelta, 10);
            maxAirBelowPercent = Math.max(maxAirBelowPercent, 0.42D);
            minSupportPercent = Math.min(minSupportPercent, 0.52D);
        } else if (id.endsWith(":desert_temple")) {
            allowedBiomeKeys = Set.of("desert");
        }
        cornucopiaFamily = "cornucopia".equalsIgnoreCase(family);
        if (cornucopiaFamily) {
            footprintRadius = Math.max(footprintRadius, 14);
            zoneRadius = Math.min(zoneRadius, 96);
            maxSlopeDelta = Math.max(maxSlopeDelta, 12);
            maxAirBelowPercent = Math.max(maxAirBelowPercent, 0.98D);
            minSupportPercent = Math.min(minSupportPercent, 0.02D);
        }

        if (flattenRequired && placementMode == PlacementMode.SURFACE) {
            grounding = GroundingMode.FLATTEN;
            if (!cornucopiaFamily) {
                maxSlopeDelta = Math.max(maxSlopeDelta, 8);
            }
        }

        boolean largeGrounded = placementMode == PlacementMode.SURFACE
            && (tier == StructureTier.MAJOR || footprintRadius >= 9);
        if (largeGrounded && grounding == GroundingMode.PILLAR_SUPPORT) {
            grounding = GroundingMode.FLATTEN;
        }
        if (largeGrounded && !cornucopiaFamily) {
            maxSlopeDelta = Math.max(maxSlopeDelta, footprintRadius >= 10 ? 11 : 9);
            maxAirBelowPercent = Math.max(maxAirBelowPercent, footprintRadius >= 10 ? 0.46D : 0.38D);
            minSupportPercent = Math.min(minSupportPercent, footprintRadius >= 10 ? 0.50D : 0.58D);
            minFamilySpacing = Math.min(minFamilySpacing, Math.max(140, footprintRadius * 14));
            zoneRadius = Math.min(zoneRadius, Math.max(structureZoneRadiusInt() + 16, footprintRadius * 6));
        }
        if (grounding == GroundingMode.FLATTEN && placementMode == PlacementMode.SURFACE && !cornucopiaFamily) {
            maxSlopeDelta = Math.max(maxSlopeDelta, 8);
        }

        StructureRule rule = new StructureRule(
            id,
            family,
            tier,
            maxPerMatch,
            minFamilySpacing,
            maxSlopeDelta,
            grounding,
            placementMode,
            zoneRadius,
            footprintRadius,
            maxAirBelowPercent,
            minSupportPercent,
            canopyAllowed,
            flattenRequired,
            allowedBiomeKeys,
            allowedEnvironments
        );
        structureRuleCache.put(id, rule);
        return rule;
    }

    private String inferStructureFamily(String structureId) {
        String id = normalizeStructureId(structureId);
        String key = id.contains(":") ? id.substring(id.indexOf(':') + 1) : id;
        if (isLikelyLargeStructureKey(key)) {
            return "estate";
        }
        if (key.contains("spruce_hut") || key.contains("hut")) {
            return "spruce_hut";
        }
        if (key.contains("watchtower") || key.contains("tower")) {
            return "watchtower";
        }
        if (key.contains("factory")) {
            return "factory";
        }
        if (key.contains("portal")) {
            return "portal";
        }
        if (key.contains("windmill")) {
            return "windmill";
        }
        if (key.contains("castle")) {
            return "castle";
        }
        if (key.contains("mineshaft") || key.contains("minshaft")) {
            return "mineshaft";
        }
        if (key.contains("boat") || key.contains("ship")) {
            return "boat";
        }
        if (key.contains("bridge")) {
            return "bridge";
        }
        if (key.contains("temple")) {
            return "temple";
        }
        if (key.contains("house") || key.contains("home")) {
            return "house";
        }
        return key.replaceAll("_[0-9]+$", "");
    }

    private StructureTier inferStructureTier(String structureId, String family) {
        String id = normalizeStructureId(structureId);
        String fam = family == null ? "" : family;
        if (fam.equals("factory") || fam.equals("castle") || fam.equals("estate")) {
            return StructureTier.MAJOR;
        }
        if (fam.equals("portal") || fam.equals("mineshaft") || fam.equals("temple")) {
            return StructureTier.SPECIAL;
        }
        if (fam.equals("watchtower") || fam.equals("windmill") || fam.equals("spruce_hut")) {
            return StructureTier.MEDIUM;
        }
        if (id.contains("ruined") || id.contains("ruin") || id.contains("boat") || id.contains("ship")) {
            return StructureTier.MICRO;
        }
        return StructureTier.MEDIUM;
    }

    private GroundingMode inferGroundingMode(String structureId, String family, boolean requireWater, boolean mineshaft) {
        String id = normalizeStructureId(structureId);
        String fam = family == null ? "" : family;
        if (requireWater) {
            return GroundingMode.WATER_SURFACE;
        }
        if (mineshaft) {
            return GroundingMode.CAVE_EMBED;
        }
        if (fam.equals("factory") || fam.equals("castle") || fam.equals("estate")) {
            return GroundingMode.FLATTEN;
        }
        if (fam.equals("portal")) {
            return GroundingMode.BURY;
        }
        if (fam.equals("spruce_hut") || fam.equals("watchtower") || fam.equals("windmill") || fam.equals("house")) {
            return GroundingMode.PILLAR_SUPPORT;
        }
        if (id.contains("ruined")) {
            return GroundingMode.BURY;
        }
        return GroundingMode.SURFACE_ONLY;
    }

    private PlacementMode inferPlacementMode(boolean requireWater, boolean mineshaft, GroundingMode grounding) {
        if (requireWater || grounding == GroundingMode.WATER_SURFACE) {
            return PlacementMode.WATER;
        }
        if (mineshaft || grounding == GroundingMode.CAVE_EMBED) {
            return PlacementMode.CAVE;
        }
        if (grounding == GroundingMode.BURY) {
            return PlacementMode.BURIED;
        }
        return PlacementMode.SURFACE;
    }

    private Set<World.Environment> inferAllowedEnvironments(String structureId) {
        if (requiresNetherSpawn(structureId)) {
            return Set.of(World.Environment.NETHER);
        }
        return Set.of(World.Environment.NORMAL);
    }

    private Set<String> inferDefaultAllowedBiomeKeys(String structureId, String family) {
        String id = normalizeStructureId(structureId);
        String fam = family == null ? "" : family;
        if (id.contains("desert_temple") || "desert_temple".equals(fam)) {
            return Set.of("desert");
        }
        return Set.of();
    }

    private int inferMaxPerMatch(String family, StructureTier tier) {
        return switch (family) {
            case "factory", "portal", "mineshaft", "estate" -> 1;
            case "watchtower", "spruce_hut", "windmill" -> 2;
            case "castle", "temple" -> 1;
            default -> switch (tier) {
                case MAJOR -> 1;
                case SPECIAL -> 1;
                case MEDIUM -> 2;
                case MICRO -> 3;
            };
        };
    }

    private int inferMinFamilySpacing(String family, StructureTier tier) {
        return switch (family) {
            case "factory" -> 320;
            case "estate" -> 320;
            case "portal" -> 240;
            case "watchtower" -> 220;
            case "spruce_hut" -> 180;
            case "mineshaft" -> 260;
            default -> switch (tier) {
                case MAJOR -> 280;
                case SPECIAL -> 220;
                case MEDIUM -> 170;
                case MICRO -> 130;
            };
        };
    }

    private int inferMaxSlopeDelta(String family, StructureTier tier, GroundingMode grounding) {
        if (grounding == GroundingMode.FLATTEN) {
            return 5;
        }
        if (grounding == GroundingMode.PILLAR_SUPPORT) {
            return 8;
        }
        if (family.equals("portal")) {
            return 6;
        }
        return switch (tier) {
            case MAJOR -> 5;
            case SPECIAL -> 6;
            case MEDIUM -> 7;
            case MICRO -> 9;
        };
    }

    private int inferFootprintRadius(String family, StructureTier tier) {
        return switch (family) {
            case "factory" -> 10;
            case "estate" -> 11;
            case "castle" -> 11;
            case "watchtower" -> 6;
            case "spruce_hut", "windmill", "house" -> 5;
            case "portal", "temple" -> 5;
            case "mineshaft" -> 4;
            default -> switch (tier) {
                case MAJOR -> 10;
                case SPECIAL -> 5;
                case MEDIUM -> 5;
                case MICRO -> 4;
            };
        };
    }

    private int inferZoneRadius(String family, StructureTier tier, int footprintRadius) {
        int tierRadius = switch (tier) {
            case MAJOR -> 115;
            case SPECIAL -> 100;
            case MEDIUM -> 90;
            case MICRO -> 80;
        };
        int familyRadius = switch (family) {
            case "factory" -> 130;
            case "estate" -> 140;
            case "watchtower" -> 105;
            case "spruce_hut" -> 90;
            case "portal" -> 105;
            case "mineshaft" -> 100;
            default -> tierRadius;
        };
        return Math.max(familyRadius, footprintRadius * 8);
    }

    private static boolean isLikelyLargeStructureKey(String key) {
        if (key == null || key.isBlank()) {
            return false;
        }
        String normalized = key.toLowerCase(Locale.ROOT);
        return normalized.contains("mansion")
            || normalized.contains("manor")
            || normalized.contains("estate")
            || normalized.contains("palace")
            || normalized.contains("citadel")
            || normalized.contains("compound")
            || normalized.contains("stronghold")
            || normalized.contains("fortress")
            || normalized.contains("townhall")
            || normalized.contains("guildhall")
            || normalized.contains("cathedral")
            || normalized.contains("grand_house")
            || normalized.contains("large_house")
            || normalized.contains("big_house");
    }

