    private static void addHellscapeOverride(
        Map<String, StructureRuleOverride> overrides,
        String path,
        String family,
        StructureTier tier,
        int maxPerMatch,
        int spacing,
        int maxSlopeDelta,
        GroundingMode grounding,
        int zoneRadius,
        int footprintRadius,
        double maxAirBelow,
        double minSupport
    ) {
        addStructureOverride(overrides, HELLSCAPE_STRUCTURE_PREFIX + path, new StructureRuleOverride(
            family, tier, maxPerMatch, spacing, maxSlopeDelta,
            grounding, PlacementMode.SURFACE,
            zoneRadius, footprintRadius, maxAirBelow, minSupport, true, grounding == GroundingMode.FLATTEN,
            Set.of("nether_wastes", "hydra_wastes"),
            Set.of(World.Environment.NETHER)
        ));
    }

    private static List<Map<String, Object>> defaultStructureRuleOverrideConfigEntries() {
        List<Map<String, Object>> entries = new ArrayList<>();
        for (String path : DEFAULT_STRUCTURE_OVERRIDE_PATHS) {
            String id = HYDRA_STRUCTURE_NAMESPACE + ":" + path;
            StructureRuleOverride override = STRUCTURE_RULE_OVERRIDES.get(id);
            if (override == null) {
                continue;
            }
            Map<String, Object> row = new HashMap<>();
            row.put("id", id);
            if (override.family() != null && !override.family().isBlank()) {
                row.put("family", override.family());
            }
            if (override.tier() != null) {
                row.put("tier", override.tier().name());
            }
            if (override.maxPerMatch() != null) {
                row.put("max_per_match", override.maxPerMatch());
            }
            if (override.minFamilySpacing() != null) {
                row.put("min_family_spacing", override.minFamilySpacing());
            }
            if (override.maxSlopeDelta() != null) {
                row.put("max_slope_delta", override.maxSlopeDelta());
            }
            if (override.grounding() != null) {
                row.put("grounding", override.grounding().name());
            }
            if (override.placementMode() != null) {
                row.put("placement_mode", override.placementMode().name());
            }
            if (override.zoneRadius() != null) {
                row.put("zone_radius", override.zoneRadius());
            }
            if (override.footprintRadius() != null) {
                row.put("footprint_radius", override.footprintRadius());
            }
            if (override.maxAirBelowPercent() != null) {
                row.put("max_air_below_percent", override.maxAirBelowPercent());
            }
            if (override.minSupportPercent() != null) {
                row.put("min_support_percent", override.minSupportPercent());
            }
            if (override.canopyAllowed() != null) {
                row.put("canopy_allowed", override.canopyAllowed());
            }
            if (override.flattenRequired() != null) {
                row.put("flatten_required", override.flattenRequired());
            }
            if (override.allowedBiomeKeys() != null && !override.allowedBiomeKeys().isEmpty()) {
                row.put("allowed_biomes", new ArrayList<>(override.allowedBiomeKeys()));
            }
            if (override.allowedEnvironments() != null && !override.allowedEnvironments().isEmpty()) {
                List<String> environments = override.allowedEnvironments().stream()
                    .map(World.Environment::name)
                    .toList();
                row.put("allowed_dimensions", environments);
            }
            entries.add(row);
        }
        return entries;
    }

    private void reloadStructureRuleOverridesFromConfig() {
        structureRuleOverrides.clear();
        structureRuleOverrides.putAll(STRUCTURE_RULE_OVERRIDES);

        List<Map<?, ?>> configured = plugin.getConfig().getMapList(STRUCTURE_RULE_OVERRIDES_PATH);
        int loaded = 0;
        for (Map<?, ?> row : configured) {
            if (row == null || row.isEmpty()) {
                continue;
            }
            String id = readString(row, "id", "structure", "structure_id", "name");
            if (id == null || id.isBlank()) {
                continue;
            }
            StructureRuleOverride override = parseStructureRuleOverride(row);
            if (override == null) {
                continue;
            }
            addRuntimeStructureOverride(structureRuleOverrides, id, override);
            loaded++;
        }
        structureRuleCache.clear();
        if (loaded > 0) {
            plugin.getLogger().info("[Queue] Loaded " + loaded + " structure rule override(s) from config.");
        }
    }

    private static Object firstRawValue(Map<?, ?> row, String... keys) {
        if (row == null || keys == null) {
            return null;
        }
        for (String key : keys) {
            if (key == null || key.isBlank()) {
                continue;
            }
            if (row.containsKey(key)) {
                return row.get(key);
            }
        }
        return null;
    }

    private static String readString(Map<?, ?> row, String... keys) {
        Object raw = firstRawValue(row, keys);
        if (raw == null) {
            return null;
        }
        String text = raw.toString().trim();
        return text.isEmpty() ? null : text;
    }

    private static <E extends Enum<E>> E parseEnumValue(Class<E> type, Object raw) {
        if (type == null || raw == null) {
            return null;
        }
        String text = raw.toString().trim();
        if (text.isEmpty()) {
            return null;
        }
        String normalized = text.toUpperCase(Locale.ROOT).replace('-', '_').replace(' ', '_');
        try {
            return Enum.valueOf(type, normalized);
        } catch (IllegalArgumentException ignored) {
            return null;
        }
    }

    private static Integer parseOptionalInt(Object raw, int min, int max) {
        if (raw == null) {
            return null;
        }
        int value;
        if (raw instanceof Number number) {
            value = number.intValue();
        } else {
            try {
                value = Integer.parseInt(raw.toString().trim());
            } catch (NumberFormatException ignored) {
                return null;
            }
        }
        int low = Math.min(min, max);
        int high = Math.max(min, max);
        if (value < low) {
            return low;
        }
        if (value > high) {
            return high;
        }
        return value;
    }

    private static Double parseOptionalDouble(Object raw, double min, double max) {
        if (raw == null) {
            return null;
        }
        double value;
        if (raw instanceof Number number) {
            value = number.doubleValue();
        } else {
            try {
                value = Double.parseDouble(raw.toString().trim());
            } catch (NumberFormatException ignored) {
                return null;
            }
        }
        if (Double.isNaN(value) || Double.isInfinite(value)) {
            return null;
        }
        double low = Math.min(min, max);
        double high = Math.max(min, max);
        if (value < low) {
            return low;
        }
        if (value > high) {
            return high;
        }
        return value;
    }

    private static Boolean parseOptionalBoolean(Object raw) {
        if (raw == null) {
            return null;
        }
        if (raw instanceof Boolean bool) {
            return bool;
        }
        String text = raw.toString().trim().toLowerCase(Locale.ROOT);
        if (text.isEmpty()) {
            return null;
        }
        return switch (text) {
            case "true", "yes", "y", "1", "on", "enabled", "enable" -> true;
            case "false", "no", "n", "0", "off", "disabled", "disable" -> false;
            default -> null;
        };
    }

    private static Set<String> parseOptionalStringSet(Object raw) {
        if (raw == null) {
            return null;
        }
        LinkedHashSet<String> values = new LinkedHashSet<>();
        if (raw instanceof Iterable<?> iterable) {
            for (Object entry : iterable) {
                if (entry == null) {
                    continue;
                }
                String text = entry.toString().trim();
                if (!text.isEmpty()) {
                    values.add(text);
                }
            }
        } else {
            String text = raw.toString().trim();
            if (text.isEmpty()) {
                return null;
            }
            for (String part : text.split(",")) {
                String trimmed = part.trim();
                if (!trimmed.isEmpty()) {
                    values.add(trimmed);
                }
            }
        }
        return values.isEmpty() ? null : Set.copyOf(values);
    }

    private static String normalizeBiomeFilterKey(String raw) {
        if (raw == null || raw.isBlank()) {
            return "";
        }
        String text = raw.trim().toLowerCase(Locale.ROOT);
        int colon = text.indexOf(':');
        if (colon >= 0 && colon < text.length() - 1) {
            text = text.substring(colon + 1);
        }
        return text.replace('-', '_').replace(' ', '_');
    }

    private static Set<String> parseOptionalBiomeSet(Object raw) {
        Set<String> values = parseOptionalStringSet(raw);
        if (values == null || values.isEmpty()) {
            return null;
        }
        LinkedHashSet<String> normalized = new LinkedHashSet<>();
        for (String value : values) {
            String key = normalizeBiomeFilterKey(value);
            if (!key.isBlank()) {
                normalized.add(key);
            }
        }
        return normalized.isEmpty() ? null : Set.copyOf(normalized);
    }

    private static Set<World.Environment> parseOptionalEnvironmentSet(Object raw) {
        Set<String> values = parseOptionalStringSet(raw);
        if (values == null || values.isEmpty()) {
            return null;
        }
        EnumSet<World.Environment> environments = EnumSet.noneOf(World.Environment.class);
        for (String value : values) {
            World.Environment environment = parseEnumValue(World.Environment.class, value);
            if (environment != null) {
                environments.add(environment);
            }
        }
        return environments.isEmpty() ? null : Set.copyOf(environments);
    }

    private static StructureRuleOverride parseStructureRuleOverride(Map<?, ?> row) {
        String family = readString(row, "family");
        StructureTier tier = parseEnumValue(StructureTier.class, firstRawValue(row, "tier"));
        Integer maxPerMatch = parseOptionalInt(firstRawValue(row, "max_per_match", "maxPerMatch"), 1, 256);
        Integer minFamilySpacing = parseOptionalInt(firstRawValue(row, "min_family_spacing", "minFamilySpacing"), 1, 1024);
        Integer maxSlopeDelta = parseOptionalInt(firstRawValue(row, "max_slope_delta", "maxSlopeDelta"), 1, 64);
        GroundingMode grounding = parseEnumValue(GroundingMode.class, firstRawValue(row, "grounding"));
        PlacementMode placementMode = parseEnumValue(PlacementMode.class, firstRawValue(row, "placement_mode", "placementMode"));
        Integer zoneRadius = parseOptionalInt(firstRawValue(row, "zone_radius", "zoneRadius"), 1, 2048);
        Integer footprintRadius = parseOptionalInt(firstRawValue(row, "footprint_radius", "footprintRadius"), 1, 256);
        Double maxAirBelowPercent = parseOptionalDouble(
            firstRawValue(row, "max_air_below_percent", "maxAirBelowPercent"),
            0.0D,
            1.0D
        );
        Double minSupportPercent = parseOptionalDouble(
            firstRawValue(row, "min_support_percent", "minSupportPercent"),
            0.0D,
            1.0D
        );
        Boolean canopyAllowed = parseOptionalBoolean(firstRawValue(row, "canopy_allowed", "canopyAllowed"));
        Boolean flattenRequired = parseOptionalBoolean(firstRawValue(row, "flatten_required", "flattenRequired"));
        Set<String> allowedBiomeKeys = parseOptionalBiomeSet(firstRawValue(row, "allowed_biomes", "biomes", "allowedBiomes"));
        Set<World.Environment> allowedEnvironments = parseOptionalEnvironmentSet(
            firstRawValue(row, "allowed_dimensions", "dimensions", "allowed_environments", "environments")
        );
        if (family != null && family.isBlank()) {
            family = null;
        }
        boolean hasAnyField = family != null
            || tier != null
            || maxPerMatch != null
            || minFamilySpacing != null
            || maxSlopeDelta != null
            || grounding != null
            || placementMode != null
            || zoneRadius != null
            || footprintRadius != null
            || maxAirBelowPercent != null
            || minSupportPercent != null
            || canopyAllowed != null
            || flattenRequired != null
            || allowedBiomeKeys != null
            || allowedEnvironments != null;
        if (!hasAnyField) {
            return null;
        }
        return new StructureRuleOverride(
            family,
            tier,
            maxPerMatch,
            minFamilySpacing,
            maxSlopeDelta,
            grounding,
            placementMode,
            zoneRadius,
            footprintRadius,
            maxAirBelowPercent,
            minSupportPercent,
            canopyAllowed,
            flattenRequired,
            allowedBiomeKeys,
            allowedEnvironments
        );
    }

    private static void addRuntimeStructureOverride(
        Map<String, StructureRuleOverride> overrides,
        String rawId,
        StructureRuleOverride override
    ) {
        if (overrides == null || rawId == null || rawId.isBlank() || override == null) {
            return;
        }
        String id = rawId.trim().toLowerCase(Locale.ROOT);
        if (!id.contains(":")) {
            addStructureOverride(overrides, id, override);
            return;
        }
        overrides.put(id, override);
        int colon = id.indexOf(':');
        if (colon <= 0 || colon >= id.length() - 1) {
            return;
        }
        String namespace = id.substring(0, colon);
        String path = id.substring(colon + 1);
        if (namespace.equals(HYDRA_STRUCTURE_NAMESPACE)) {
            overrides.put("skyforge:" + path, override);
        } else if (namespace.equals("skyforge")) {
            overrides.put(HYDRA_STRUCTURE_NAMESPACE + ":" + path, override);
        }
    }

    private static void addStructureOverride(
        Map<String, StructureRuleOverride> overrides,
        String idPath,
        StructureRuleOverride override
    ) {
        if (overrides == null || idPath == null || idPath.isBlank() || override == null) {
            return;
        }
        String key = idPath.toLowerCase(Locale.ROOT);
        overrides.put(HYDRA_STRUCTURE_NAMESPACE + ":" + key, override);
        overrides.put("skyforge:" + key, override);
    }

    private StructureRuleOverride overrideForStructureId(String normalizedId) {
        if (normalizedId == null || normalizedId.isBlank()) {
            return null;
        }
        int colon = normalizedId.indexOf(':');
        String path = colon >= 0 && colon < normalizedId.length() - 1
            ? normalizedId.substring(colon + 1)
            : normalizedId;
        if ("noob_house".equals(path)) {
            // Keep noob_house datapack-owned for clean worldgen testing.
            return null;
        }
        StructureRuleOverride direct = structureRuleOverrides.get(normalizedId);
        if (direct != null) {
            return direct;
        }
        if (colon <= 0 || colon >= normalizedId.length() - 1) {
            return null;
        }
        StructureRuleOverride byHydraPath = structureRuleOverrides.get(HYDRA_STRUCTURE_NAMESPACE + ":" + path);
        if (byHydraPath != null) {
            return byHydraPath;
        }
        StructureRuleOverride skyforge = structureRuleOverrides.get("skyforge:" + path);
        if (skyforge != null) {
            return skyforge;
        }
        StructureRuleOverride builtinDirect = STRUCTURE_RULE_OVERRIDES.get(normalizedId);
        if (builtinDirect != null) {
            return builtinDirect;
        }
        StructureRuleOverride builtinHydra = STRUCTURE_RULE_OVERRIDES.get(HYDRA_STRUCTURE_NAMESPACE + ":" + path);
        if (builtinHydra != null) {
            return builtinHydra;
        }
        return STRUCTURE_RULE_OVERRIDES.get("skyforge:" + path);
    }

    private static boolean isBoatOrShipStructure(String structureId) {
        String id = normalizeStructureId(structureId);
        String key = id.contains(":") ? id.substring(id.indexOf(':') + 1) : id;
        return key.contains("boat") || key.contains("ship");
    }

    private static boolean isBastionStructure(String structureId) {
        String id = normalizeStructureId(structureId);
        String key = id.contains(":") ? id.substring(id.indexOf(':') + 1) : id;
        return key.contains("bastion");
    }

    private static boolean isHungerGamesOnlyStructure(String structureId) {
        String id = normalizeStructureId(structureId);
        return id.equals(DEFAULT_HUNGER_GAMES_STRUCTURE_ID)
            || id.equals(WILD_WEST_HUNGER_GAMES_STRUCTURE_ID);
    }

    private static boolean isExcludedFromMatchStructurePool(String structureId) {
        return isBoatOrShipStructure(structureId)
            || isBastionStructure(structureId)
            || isHungerGamesOnlyStructure(structureId);
    }

    private static boolean requiresWaterSpawn(String structureId) {
        String id = normalizeStructureId(structureId);
        if (requiresNetherSpawn(id)) {
            return false;
        }
        return id.endsWith(":gray_boat")
            || id.endsWith(":pale_ship")
            || id.endsWith("_boat")
            || id.endsWith("_ship")
            || id.endsWith(":boat")
            || id.endsWith(":ship");
    }

    private static boolean requiresNetherSpawn(String structureId) {
        String id = normalizeStructureId(structureId);
        return isBastionStructure(id)
            || isHellscapeStructure(id)
            || id.endsWith(":warped_boat")
            || id.endsWith(":warped_ship")
            || id.endsWith(":warped_tower");
    }

    private static boolean isHellscapeStructure(String structureId) {
        return !hellscapeStructurePath(structureId).isBlank();
    }

    private static String hellscapeStructurePath(String structureId) {
        String id = normalizeStructureId(structureId);
        if (id.isBlank()) {
            return "";
        }
        String key = id.contains(":") ? id.substring(id.indexOf(':') + 1) : id;
        if (!key.startsWith(HELLSCAPE_STRUCTURE_PREFIX) || key.length() <= HELLSCAPE_STRUCTURE_PREFIX.length()) {
            return "";
        }
        return key.substring(HELLSCAPE_STRUCTURE_PREFIX.length());
    }

    private static boolean isMineshaftStructure(String structureId) {
        String id = normalizeStructureId(structureId);
        return id.endsWith(":mineshaft") || id.endsWith(":minshaft");
    }

    private static boolean isMountainSurfaceBiome(World world, int x, int z) {
        int y = findRealSurfaceY(world, x, z, false);
        Biome biome = world.getBiome(x, y, z);
        return biome == Biome.WINDSWEPT_HILLS
            || biome == Biome.STONY_PEAKS
            || biome == Biome.JAGGED_PEAKS
            || biome == Biome.SNOWY_SLOPES
            || biome == Biome.FROZEN_PEAKS;
    }

    private static boolean hasTreeCoverNear(World world, int x, int z, int radius) {
        int step = 2;
        for (int dx = -radius; dx <= radius; dx += step) {
            for (int dz = -radius; dz <= radius; dz += step) {
                int tx = x + dx;
                int tz = z + dz;
                int ty = world.getHighestBlockYAt(tx, tz);
                Material top = world.getBlockAt(tx, ty, tz).getType();
                Material below = world.getBlockAt(tx, Math.max(world.getMinHeight(), ty - 1), tz).getType();
                if (isTreeMaterial(top) || isTreeMaterial(below)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean isTreeMaterial(Material type) {
        return switch (type) {
            case OAK_LOG, SPRUCE_LOG, BIRCH_LOG, JUNGLE_LOG, ACACIA_LOG, DARK_OAK_LOG, MANGROVE_LOG, CHERRY_LOG,
                OAK_LEAVES, SPRUCE_LEAVES, BIRCH_LEAVES, JUNGLE_LEAVES, ACACIA_LEAVES, DARK_OAK_LEAVES,
                MANGROVE_LEAVES, CHERRY_LEAVES -> true;
            default -> false;
        };
    }

    private boolean isWorldAllowedForStructure(World world, String structureId) {
        if (world == null) {
            return false;
        }
        StructureRule rule = structureRuleFor(structureId);
        Set<World.Environment> allowedEnvironments = rule.allowedEnvironments();
        if (allowedEnvironments != null && !allowedEnvironments.isEmpty() && !allowedEnvironments.contains(world.getEnvironment())) {
            return false;
        }
        if (!requiresNetherSpawn(structureId)) {
            return true;
        }
        return world.getEnvironment() == World.Environment.NETHER;
    }

    private boolean isInsideAeosRegion(long seed, int x, int z) {
        if (brTerrainProfile != BrTerrainProfile.AEOS_ISLES) {
            return false;
        }
        double mapRadius = Math.max(256.0D, brTerrainMapDiameter / 2.0D);
        return aeosRegionStrength(seed, x, z, mapRadius) > 0.18D;
    }

    private boolean isStructureSuppressedInAeos(World world, int x, int z) {
        if (world == null) {
            return false;
        }
        if (aeosPreviewWorlds.contains(world.getName())) {
            return true;
        }
        if (!brMatchWorlds.contains(world.getName()) || brTerrainProfile != BrTerrainProfile.AEOS_ISLES) {
            return false;
        }
        double mapRadius = Math.max(256.0D, brTerrainMapDiameter / 2.0D);
        return aeosRegionStrength(world.getSeed(), x, z, mapRadius) > 0.08D;
    }

    private static String villageStructureIdForBiome(Biome biome) {
        if (biome == null) {
            return VANILLA_VILLAGE_PLAINS_ID;
        }
        if (biome == Biome.DESERT
            || biome == Biome.BADLANDS
            || biome == Biome.WOODED_BADLANDS
            || biome == Biome.ERODED_BADLANDS) {
            return VANILLA_VILLAGE_DESERT_ID;
        }
        if (biome == Biome.SAVANNA || biome == Biome.WINDSWEPT_SAVANNA) {
            return VANILLA_VILLAGE_SAVANNA_ID;
        }
        if (biome == Biome.TAIGA
            || biome == Biome.SNOWY_TAIGA
            || biome == Biome.GROVE
            || biome == Biome.WINDSWEPT_HILLS) {
            return VANILLA_VILLAGE_TAIGA_ID;
        }
        if (biome == Biome.SNOWY_PLAINS
            || biome == Biome.ICE_SPIKES
            || biome == Biome.FROZEN_OCEAN) {
            return VANILLA_VILLAGE_SNOWY_ID;
        }
        return VANILLA_VILLAGE_PLAINS_ID;
    }

    private void awardKill(PlayerDeathEvent event) {
        Player victim = event.getEntity();
        Player killer = victim.getKiller();
        if (killer == null) {
            return;
        }
        UUID killerId = killer.getUniqueId();
        if (!inMatchPlayers.contains(killerId)) {
            return;
        }
        String victimWorld = inMatchWorlds.get(victim.getUniqueId());
        String killerWorld = inMatchWorlds.get(killerId);
        if (victimWorld == null || killerWorld == null || !isSameMatchSessionWorld(victimWorld, killerWorld)) {
            return;
        }
        QueueType matchType = inMatchTypes.get(killerId);
        if (matchType == null) {
            matchType = resolveQueueTypeForWorld(killerWorld);
        }
        int nextKills = matchKills.getOrDefault(killerId, 0) + 1;
        matchKills.put(killerId, nextKills);
        if (isHungerGames(matchType) && plugin instanceof HGLootPlugin hydra
            && hydra.battlePassService() != null) {
            hydra.battlePassService().recordHgElimination(killerId, rootMatchWorldName(killerWorld));
        }
        if (!isBrDevelopmentTestWorld(killerWorld)) {
            recordLifetimeKill(killerId, matchType);
        }
        String killMessageName = menuService == null ? null : menuService.selectedKillMessageDisplayName(killerId);
        String killMessageRarity = menuService == null ? null : menuService.selectedKillMessageRarity(killerId);
        killer.sendActionBar(Component.text(ChatColor.GREEN + "+1 Kill"));
        HydraSounds.playKill(killer);
        if (killMessageName != null && !killMessageName.isBlank()) {
            killer.playSound(
                killer.getLocation(),
                Sound.ENTITY_EXPERIENCE_ORB_PICKUP,
                0.55F,
                "epic".equalsIgnoreCase(killMessageRarity) ? 1.4F : 1.22F
            );
        }
        int critParticles = "epic".equalsIgnoreCase(killMessageRarity) ? 24 : 18;
        killer.getWorld().spawnParticle(
            Particle.CRIT,
            killer.getLocation().clone().add(0.0D, 1.0D, 0.0D),
            critParticles,
            0.35D,
            0.45D,
            0.35D,
            0.02D
        );
        if ("epic".equalsIgnoreCase(killMessageRarity)) {
            killer.getWorld().spawnParticle(
                Particle.SOUL_FIRE_FLAME,
                killer.getLocation().clone().add(0.0D, 1.0D, 0.0D),
                10,
                0.25D,
                0.25D,
                0.25D,
                0.01D
            );
        } else if ("rare".equalsIgnoreCase(killMessageRarity)) {
            killer.getWorld().spawnParticle(
                Particle.ENCHANT,
                killer.getLocation().clone().add(0.0D, 1.0D, 0.0D),
                8,
                0.25D,
                0.25D,
                0.25D,
                0.01D
            );
        }
        refreshAllDebugLeaderboards();
    }

    private void applyCustomDeathMessage(PlayerDeathEvent event) {
        if (event == null) {
            return;
        }
        Player victim = event.getEntity();
        LegendaryKillContext context = pendingLegendaryKillContexts.remove(victim.getUniqueId());
        if (context != null && context.killerName() != null && context.messageSuffix() != null) {
            event.setDeathMessage(ChatColor.RED + victim.getName() + ChatColor.GRAY + " " + context.messageSuffix());
            return;
        }
        Player killer = victim.getKiller();
        if (killer != null) {
            if (menuService != null) {
                String customMessage = menuService.customKillMessage(killer.getUniqueId(), killer.getName(), victim.getName());
                if (customMessage != null && !customMessage.isBlank()) {
                    event.setDeathMessage(
                        ChatColor.GRAY + customMessage
                    );
                    return;
                }
            }
            event.setDeathMessage(
                ChatColor.RED + victim.getName()
                    + ChatColor.GRAY + " was killed by "
                    + ChatColor.WHITE + killer.getName()
            );
            return;
        }
        event.setDeathMessage(
            ChatColor.RED + victim.getName()
                + ChatColor.GRAY + " "
                + environmentalDeathSuffix(event)
        );
    }

    private LegendaryKillContext resolveLegendaryKillContext(Player attacker) {
        if (attacker == null) {
            return null;
        }
        ItemStack mainHand = attacker.getInventory().getItemInMainHand();
        String displayName = displayNameForLegendary(mainHand);
        if (displayName == null) {
            return null;
        }
        String plain = ChatColor.stripColor(displayName);
        if (plain == null) {
            return null;
        }
        return switch (plain.toLowerCase(Locale.ROOT)) {
            case "knight's saddle" -> new LegendaryKillContext(attacker.getName(), "was trampled by Knight's Saddle");
            case "spider staff" -> new LegendaryKillContext(attacker.getName(), "was devoured by the Spider Staff");
            case "sponge saber", "wet sponge saber" -> new LegendaryKillContext(attacker.getName(), "was washed away by the Sponge Saber");
            case "electric conch" -> new LegendaryKillContext(attacker.getName(), "was struck down by the Electric Conch");
            case "fractial's dwarven bow", "dwarf bow" -> new LegendaryKillContext(attacker.getName(), "was pierced by the Dwarf Bow");
            case "skeletal barber" -> new LegendaryKillContext(attacker.getName(), "was obliterated by the Skeletal Barber");
            case "ghlochester" -> new LegendaryKillContext(attacker.getName(), "was cursed by Ghlochester");
            case "hooked grappler" -> new LegendaryKillContext(attacker.getName(), "was reeled in by the Hooked Grappler");
            case "wonder pickaxe" -> new LegendaryKillContext(attacker.getName(), "was shattered by the Wonder Pickaxe");
            case "loki's scepter" -> new LegendaryKillContext(attacker.getName(), "was outplayed by Loki's Scepter");
            case "druid's daggers" -> new LegendaryKillContext(attacker.getName(), "was cut down by Druid's Daggers");
            case "architect's drill" -> new LegendaryKillContext(attacker.getName(), "was drilled through by the Architect's Drill");
            case "plasma distorter", "enderious" -> new LegendaryKillContext(attacker.getName(), "was destabilized by Plasma Distorter");
            case "scarab's wrath" -> new LegendaryKillContext(attacker.getName(), "was consumed by the Scarab's Wrath");
            default -> null;
        };
    }

    private void sendDeathRecap(Player player, PlayerDeathEvent event) {
        if (player == null || event == null) {
            return;
        }
        Player killer = player.getKiller();
        if (killer != null) {
            player.sendMessage(ChatColor.GRAY + "Killed by " + ChatColor.WHITE + killer.getName());
        } else {
            player.sendMessage(ChatColor.GRAY + deathRecapCauseText(event));
        }
        Double hearts = lastDamageTakenHearts.remove(player.getUniqueId());
        if (hearts != null && hearts > 0.0D) {
            player.sendMessage(ChatColor.GRAY + "Damage: " + ChatColor.RED + formatHearts(hearts) + "❤");
        }
    }

    private String environmentalDeathSuffix(PlayerDeathEvent event) {
        if (event == null || event.getEntity() == null) {
            return "died";
        }
        EntityDamageEvent lastDamage = event.getEntity().getLastDamageCause();
        if (lastDamage == null) {
            return "died";
        }
        return switch (lastDamage.getCause()) {
            case VOID -> "fell into the void";
            case FALL -> "fell";
            case LAVA -> "tried to swim in lava";
            case FIRE, FIRE_TICK -> "burned up";
            case DROWNING -> "drowned";
            case FREEZE -> "froze";
            case ENTITY_EXPLOSION, BLOCK_EXPLOSION -> "blew up";
            case WORLD_BORDER -> "hit the border";
            default -> "died";
        };
    }

    private String deathRecapCauseText(PlayerDeathEvent event) {
        String suffix = environmentalDeathSuffix(event);
        if (suffix.isEmpty()) {
            return "Died.";
        }
        return Character.toUpperCase(suffix.charAt(0)) + suffix.substring(1) + ".";
    }

    private String formatHearts(double hearts) {
        double rounded = Math.round(hearts * 10.0D) / 10.0D;
        if (Math.abs(rounded - Math.rint(rounded)) < 0.01D) {
            return String.valueOf((int) Math.rint(rounded));
        }
        return String.format(Locale.US, "%.1f", rounded);
    }

    private String displayNameForLegendary(ItemStack stack) {
        if (stack == null || stack.getType() == Material.AIR || !stack.hasItemMeta()) {
            return null;
        }
        ItemMeta meta = stack.getItemMeta();
        if (meta == null || !meta.hasDisplayName()) {
            return null;
        }
        return meta.getDisplayName();
    }

    public QueueType resolveQueueTypeForWorld(String worldName) {
        if (worldName == null) {
            return null;
        }
        String rootWorldName = rootMatchWorldName(worldName);
        for (Map.Entry<QueueType, String> entry : activeMatchWorldEntries()) {
            if (Objects.equals(rootWorldName, entry.getValue())) {
                return entry.getKey();
            }
        }
        return managedMatchWorldTypes.get(rootWorldName);
    }

    private MatchWinSilverReward awardMatchWinSilver(UUID winnerId, QueueType type) {
        int baseSilver = matchWinSilverReward(type);
        return awardWinSilver(winnerId, baseSilver, "MATCH_WIN:" + (type == null ? "unknown" : type.key()));
    }

    private MatchWinSilverReward awardWinSilver(UUID winnerId, int baseSilver, String reason) {
        if (winnerId == null || auctionHouseService == null || baseSilver <= 0) {
            return MatchWinSilverReward.none();
        }
        boolean voiceBonus = isVoiceChatSilverBonusApplied(winnerId);
        double multiplier = voiceBonus ? Math.max(1.0D, voiceChatWinSilverRewardMultiplier) : 1.0D;
        int awardedSilver = Math.max(1, (int) Math.round(baseSilver * multiplier));
        String source = (reason == null || reason.isBlank()) ? "MATCH_WIN" : reason;
        boolean granted = auctionHouseService.grantSilver(
            winnerId,
            awardedSilver,
            source + (voiceBonus ? ":voice_bonus" : "")
        );
        return granted ? new MatchWinSilverReward(baseSilver, awardedSilver, voiceBonus) : MatchWinSilverReward.none();
    }

    private int matchWinSilverReward(QueueType type) {
        if (isHungerGames(type)) {
            return hungerGamesWinSilverReward;
        }
        return isBattleRoyaleType(type) ? battleRoyaleWinSilverReward : 0;
    }

    private boolean isVoiceChatSilverBonusApplied(UUID playerId) {
        if (playerId == null || !isVoiceChatSilverBonusEnabled()) {
            return false;
        }
        if (!(plugin instanceof HGLootPlugin hydra) || hydra.hydraVoiceChatService() == null) {
            return false;
        }
        return hydra.hydraVoiceChatService().isVoiceChatActive(playerId);
    }

    private boolean isBattleRoyaleType(QueueType type) {
        return type == QueueType.SOLO || type == QueueType.DUO;
    }

    private boolean supportsReviveSnapshot(QueueType type) {
        return isBattleRoyaleType(type) || isHungerGames(type);
    }

    private boolean hasActiveBattleRoyaleSession(QueueType type, String worldName) {
        if (!isBattleRoyaleType(type)) {
            return false;
        }
        return hasActiveMatchSession(type, worldName);
    }

    private boolean hasActiveMatchSession(QueueType type, String worldName) {
        if (type == null) {
            return false;
        }
        String rootWorldName = rootMatchWorldName(worldName);
        if (rootWorldName == null || endingMatchWorlds.contains(rootWorldName)) {
            return false;
        }
        return activeMatchWorldsFor(type).contains(rootWorldName);
    }

    private void spawnReconnectZombie(Player player, BattleRoyalePlayerSnapshot snapshot) {
        if (player == null || snapshot == null || snapshot.spectator || snapshot.location == null) {
            return;
        }
        removeReconnectZombie(player.getUniqueId(), false);
        World world = snapshot.location.getWorld();
        if (world == null) {
            world = Bukkit.getWorld(snapshot.worldName);
        }
        if (world == null) {
            return;
        }
        Location spawn = snapshot.location.clone();
        if (spawn.getWorld() == null) {
            spawn.setWorld(world);
        }
        Zombie zombie = world.spawn(spawn, Zombie.class, body -> {
            body.setAI(false);
            body.setSilent(true);
            body.setCanPickupItems(false);
            body.setRemoveWhenFarAway(false);
            body.setPersistent(true);
            body.setCustomName(ChatColor.RED + player.getName());
            body.setCustomNameVisible(true);
            body.setAdult();
            AttributeInstance maxHealth = body.getAttribute(Attribute.MAX_HEALTH);
            double maxHealthValue = maxHealth == null ? 20.0D : Math.max(1.0D, maxHealth.getValue());
            body.setHealth(Math.max(1.0D, Math.min(maxHealthValue, snapshot.health)));
            body.addScoreboardTag("hydra_reconnect_body");
            body.addScoreboardTag("hydra_reconnect_" + player.getUniqueId());
            EntityEquipment equipment = body.getEquipment();
            if (equipment != null) {
                ItemStack[] armor = cloneItemStacks(snapshot.armor);
                equipment.setArmorContents(armor);
                equipment.setItemInMainHand(firstHeldItem(snapshot));
                equipment.setItemInOffHand(cloneItem(snapshot.offHand));
                equipment.setHelmetDropChance(0.0F);
                equipment.setChestplateDropChance(0.0F);
                equipment.setLeggingsDropChance(0.0F);
                equipment.setBootsDropChance(0.0F);
                equipment.setItemInMainHandDropChance(0.0F);
                equipment.setItemInOffHandDropChance(0.0F);
            }
        });
        reconnectZombieByPlayer.put(player.getUniqueId(), zombie.getUniqueId());
        reconnectPlayerByZombie.put(zombie.getUniqueId(), player.getUniqueId());
        long expiresAtMs = System.currentTimeMillis() + RECONNECT_BODY_TIMEOUT_MS;
        reconnectZombieExpiresAtMs.put(player.getUniqueId(), expiresAtMs);
        Bukkit.getScheduler().runTaskLater(plugin, () -> cleanupExpiredReconnectBody(player.getUniqueId(), expiresAtMs), RECONNECT_BODY_TIMEOUT_MS / 50L);
    }

    private ItemStack firstHeldItem(BattleRoyalePlayerSnapshot snapshot) {
        if (snapshot == null || snapshot.contents == null) {
            return null;
        }
        for (ItemStack stack : snapshot.contents) {
            if (stack != null && stack.getType() != Material.AIR) {
                return cloneItem(stack);
            }
        }
        return null;
    }

    private void removeReconnectZombie(UUID playerId, boolean dropLoot) {
        if (playerId == null) {
            return;
        }
        UUID zombieId = reconnectZombieByPlayer.remove(playerId);
        reconnectZombieExpiresAtMs.remove(playerId);
        if (zombieId == null) {
            return;
        }
        reconnectPlayerByZombie.remove(zombieId);
        Entity entity = Bukkit.getEntity(zombieId);
        if (entity == null || !entity.isValid()) {
            return;
        }
        if (!dropLoot) {
            entity.remove();
        }
    }

    private void cleanupExpiredReconnectBody(UUID playerId, long expectedExpiryMs) {
        if (playerId == null || shuttingDown) {
            return;
        }
        Long currentExpiryMs = reconnectZombieExpiresAtMs.get(playerId);
        if (currentExpiryMs == null || currentExpiryMs.longValue() != expectedExpiryMs || System.currentTimeMillis() < currentExpiryMs) {
            return;
        }
        UUID zombieId = reconnectZombieByPlayer.get(playerId);
        Location lootLocation = null;
        if (zombieId != null) {
            Entity entity = Bukkit.getEntity(zombieId);
            if (entity != null && entity.isValid()) {
                lootLocation = entity.getLocation();
            }
        }
        BattleRoyalePlayerSnapshot snapshot = brRejoinSnapshots.get(playerId);
        if (snapshot != null && lootLocation == null && snapshot.location != null) {
            lootLocation = snapshot.location;
        }
        if (lootLocation != null) {
            dropReconnectSnapshotLoot(playerId, lootLocation);
        }
        removeReconnectZombie(playerId, false);
        brRejoinSnapshots.remove(playerId);
        brReviveSnapshots.remove(playerId);
        if (snapshot != null) {
            removeFromMatch(playerId, null, false);
            maybeEvaluateMatchState(snapshot.type, snapshot.worldName);
        }
    }

    private void cleanupAllReconnectBodies(boolean dropLoot) {
        for (UUID playerId : new ArrayList<>(reconnectZombieByPlayer.keySet())) {
            if (dropLoot) {
                UUID zombieId = reconnectZombieByPlayer.get(playerId);
                Entity entity = zombieId == null ? null : Bukkit.getEntity(zombieId);
                if (entity != null && entity.isValid()) {
                    dropReconnectSnapshotLoot(playerId, entity.getLocation());
                }
            }
            removeReconnectZombie(playerId, false);
        }
    }

    private void dropReconnectSnapshotLoot(UUID playerId, Location location) {
        BattleRoyalePlayerSnapshot snapshot = brRejoinSnapshots.get(playerId);
        if (snapshot == null || location == null || location.getWorld() == null) {
            return;
        }
        dropSnapshotItems(location, snapshot.contents);
        dropSnapshotItems(location, snapshot.armor);
        dropSnapshotItems(location, new ItemStack[] {snapshot.offHand});
    }

    private void dropSnapshotItems(Location location, ItemStack[] stacks) {
        if (location == null || location.getWorld() == null || stacks == null) {
            return;
        }
        for (ItemStack stack : stacks) {
            if (stack == null || stack.getType() == Material.AIR) {
                continue;
            }
            location.getWorld().dropItemNaturally(location, cloneItem(stack));
        }
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onReconnectZombieDeath(EntityDeathEvent event) {
        UUID playerId = reconnectPlayerByZombie.remove(event.getEntity().getUniqueId());
        if (playerId == null) {
            return;
        }
        reconnectZombieByPlayer.remove(playerId);
        reconnectZombieExpiresAtMs.remove(playerId);
        event.getDrops().clear();
        dropReconnectSnapshotLoot(playerId, event.getEntity().getLocation());
        BattleRoyalePlayerSnapshot snapshot = brRejoinSnapshots.remove(playerId);
        brReviveSnapshots.remove(playerId);
        if (snapshot != null) {
            removeFromMatch(playerId, null, false);
            maybeEvaluateMatchState(snapshot.type, snapshot.worldName);
        }
    }

    private void clearBattleRoyaleSnapshots(UUID playerId) {
        if (playerId == null) {
            return;
        }
        removeReconnectZombie(playerId, false);
        brRejoinSnapshots.remove(playerId);
        brReviveSnapshots.remove(playerId);
    }

    private BattleRoyalePlayerSnapshot captureBattleRoyaleSnapshot(Player player, QueueType type, String worldName, boolean spectator) {
        if (player == null || worldName == null || !supportsReviveSnapshot(type)) {
            return null;
        }
        Location location = player.getLocation() == null ? null : player.getLocation().clone();
        if (location == null || location.getWorld() == null) {
            World fallbackWorld = Bukkit.getWorld(worldName);
            location = fallbackWorld == null ? null : fallbackWorld.getSpawnLocation();
        }
        if (location == null || location.getWorld() == null) {
            return null;
        }
        AttributeInstance maxHealthAttribute = player.getAttribute(Attribute.MAX_HEALTH);
        double maxHealth = maxHealthAttribute == null ? 20.0D : Math.max(1.0D, maxHealthAttribute.getValue());
        double storedHealth = spectator ? maxHealth : Math.max(1.0D, Math.min(maxHealth, player.getHealth()));
        UUID duoTeamId = duoTeamByPlayer.get(player.getUniqueId());
        if (duoTeamId == null && isHungerGames(type)) {
            duoTeamId = hungerGamesDuoTeamId(player.getUniqueId());
        }
        return new BattleRoyalePlayerSnapshot(
            type,
            worldName,
            duoTeamId,
            matchKills.getOrDefault(player.getUniqueId(), 0),
            spectator,
            location,
            cloneItemStacks(player.getInventory().getContents()),
            cloneItemStacks(player.getInventory().getArmorContents()),
            cloneItem(player.getInventory().getItemInOffHand()),
            storedHealth,
            player.getFoodLevel(),
            player.getSaturation(),
            player.getLevel(),
            player.getExp()
        );
    }

    private boolean restoreBattleRoyaleLiveState(Player player, BattleRoyalePlayerSnapshot snapshot, boolean fullHeal) {
        World world = Bukkit.getWorld(snapshot.worldName);
        if (world == null) {
            return false;
        }
        UUID playerId = player.getUniqueId();
        pendingSpectatorRespawnWorld.remove(playerId);
        spectatingMatchWorlds.remove(playerId);
        clearCustomSpectatorState(player);
        inMatchPlayers.add(playerId);
        inMatchTypes.put(playerId, snapshot.type);
        inMatchWorlds.put(playerId, snapshot.worldName);
        if (snapshot.duoTeamId != null) {
            duoTeamByPlayer.put(playerId, snapshot.duoTeamId);
        } else {
            duoTeamByPlayer.remove(playerId);
        }
        matchKills.put(playerId, Math.max(0, snapshot.killCount));

        if (menuService != null) {
            menuService.preparePlayerForMatch(player);
        }
        Location targetLocation = snapshot.location == null ? world.getSpawnLocation() : snapshot.location.clone();
        if (targetLocation.getWorld() == null) {
            targetLocation.setWorld(world);
        }
        player.teleport(targetLocation);
        player.setGameMode(GameMode.SURVIVAL);
        player.getInventory().setContents(cloneItemStacks(snapshot.contents));
        player.getInventory().setArmorContents(cloneItemStacks(snapshot.armor));
        player.getInventory().setItemInOffHand(cloneItem(snapshot.offHand));
        player.updateInventory();

        if (fullHeal) {
            fullyHealMatchPlayer(player, snapshot.type);
        } else {
            AttributeInstance maxHealthAttribute = player.getAttribute(Attribute.MAX_HEALTH);
            double maxHealth = maxHealthAttribute == null ? 20.0D : Math.max(1.0D, maxHealthAttribute.getValue());
            player.setHealth(Math.max(1.0D, Math.min(maxHealth, snapshot.health)));
            player.setFoodLevel(Math.max(0, Math.min(20, snapshot.foodLevel)));
            player.setSaturation(Math.max(0.0F, snapshot.saturation));
            player.setLevel(Math.max(0, snapshot.level));
            player.setExp(Math.max(0.0F, Math.min(1.0F, snapshot.exp)));
            player.setFireTicks(0);
            player.setFreezeTicks(0);
            player.setFallDistance(0.0F);
            player.setNoDamageTicks(0);
        }
        syncSpectatorVisibility(snapshot.worldName);
        refreshSidebar(player);
        return true;
    }

    private boolean restoreBattleRoyaleSpectatorState(Player player, BattleRoyalePlayerSnapshot snapshot) {
        World world = Bukkit.getWorld(snapshot.worldName);
        if (world == null) {
            return false;
        }
        UUID playerId = player.getUniqueId();
        inMatchPlayers.remove(playerId);
        inMatchTypes.remove(playerId);
        inMatchWorlds.remove(playerId);
        if (snapshot.duoTeamId != null) {
            duoTeamByPlayer.put(playerId, snapshot.duoTeamId);
        } else {
            duoTeamByPlayer.remove(playerId);
        }
        pendingSpectatorRespawnWorld.remove(playerId);
        clearCustomSpectatorState(player);
        setCustomSpectatorState(player, snapshot.worldName, false);
        Location targetLocation = isHungerGames(snapshot.type) || snapshot.location == null
            ? world.getSpawnLocation() : snapshot.location.clone();
        if (targetLocation.getWorld() == null) {
            targetLocation.setWorld(world);
        }
        player.teleport(targetLocation);
        syncSpectatorVisibility(snapshot.worldName);
        refreshSidebar(player);
        return true;
    }

    private ItemStack[] cloneItemStacks(ItemStack[] source) {
        if (source == null) {
            return new ItemStack[0];
        }
        ItemStack[] clone = new ItemStack[source.length];
        for (int i = 0; i < source.length; i++) {
            clone[i] = cloneItem(source[i]);
        }
        return clone;
    }

    private ItemStack cloneItem(ItemStack stack) {
        return stack == null ? null : stack.clone();
    }

    private void tickMatchBorders() {
        if (noActiveMatchWorlds()) return;
        long now = System.currentTimeMillis();
        for (String worldName : allActiveMatchWorlds()) {
            if (worldName == null || endingMatchWorlds.contains(worldName)) continue;
            World world = Bukkit.getWorld(worldName);
            if (world == null) continue;
            matchBorderService.tick(world, () -> {
                String linkedName = linkedNetherWorldForRoot(worldName);
                return linkedName == null ? null : Bukkit.getWorld(linkedName);
            }, isHungerGames(managedMatchWorldTypes.get(worldName)),
                matchStartedAtMs.get(worldName), borderSettingsForWorld(worldName), now);
        }
    }

    private void syncLinkedNetherBorder(String rootWorldName, double targetSize, int shrinkDurationSeconds) {
        String linkedNetherWorldName = linkedNetherWorldForRoot(rootWorldName);
        World linkedWorld = linkedNetherWorldName == null ? null : Bukkit.getWorld(linkedNetherWorldName);
        matchBorderService.syncLinkedNether(linkedWorld, targetSize, shrinkDurationSeconds);
    }

    /**
     * Invalidates the cached hub-sidebar signature for a player so the next
     * {@link #refreshSidebar(Player)} is forced to rebuild the scoreboard. Minigame
     * services must call this when a player leaves a match, because the match sidebar
     * reuses the same "hydra_hud" objective name and would otherwise be mistaken for
     * an already-applied hub sidebar.
     */
    public void clearSidebarCache(UUID playerId) {
        if (playerId != null) {
            sidebarContentSignatures.remove(playerId);
        }
    }

    public void refreshSidebar(Player player) {
        if (player == null || !player.isOnline()) {
            return;
        }
        if (plugin instanceof HGLootPlugin hydra && hydra.kitEditorService() != null
            && hydra.kitEditorService().isEditing(player.getUniqueId())) {
            return;
        }
        if (plugin instanceof HGLootPlugin hydra
            && hydra.combatChamberService() != null
            && hydra.combatChamberService().isPlayerInActiveRing(player)) {
            return;
        }
        if (plugin instanceof HGLootPlugin hydra
            && hydra.spleefService() != null
            && hydra.spleefService().isInSpleef(player.getUniqueId())) {
            return;
        }
        if (plugin instanceof HGLootPlugin hydra
            && hydra.voidRouletteService() != null
            && hydra.voidRouletteService().isInVoidRoulette(player.getUniqueId())) {
            return;
        }
        if (plugin instanceof HGLootPlugin hydra
            && hydra.bridgeService() != null
            && hydra.bridgeService().isInBridge(player.getUniqueId())) {
            return;
        }
        if (plugin instanceof HGLootPlugin hydra
            && hydra.bossRushService() != null
            && hydra.bossRushService().ownsSidebar(player)) {
            hydra.bossRushService().updateBossRushSidebar(player);
            return;
        }
        if (plugin instanceof HGLootPlugin hydra
            && hydra.minigameRouletteService() != null
            && hydra.minigameRouletteService().ownsSidebar(player.getUniqueId())) {
            return;
        }
        UUID playerId = player.getUniqueId();
        String currentWorldName = player.getWorld() == null ? null : player.getWorld().getName();
        String worldName = inMatchWorlds.get(playerId);
        if (worldName == null) {
            worldName = spectatingMatchWorlds.get(playerId);
        }
        if (worldName != null && isSameMatchSessionWorld(worldName, currentWorldName)) {
            QueueType type = inMatchTypes.get(playerId);
            if (type == null) {
                type = resolveQueueTypeForWorld(worldName);
            }
            updateMatchSidebar(player, type, rootMatchWorldName(worldName));
            return;
        }

        QueueType queuedType = queuedPlayers.get(playerId);
        if (queuedType != null) {
            updateQueueSidebar(player, queuedType);
            return;
        }

        updateLobbySidebar(player);
    }

    private void updateAllSidebars() {
        for (Player player : Bukkit.getOnlinePlayers()) {
            refreshSidebar(player);
        }
    }

    private void updateQueueSidebar(Player player, QueueType type) {
        CountdownState countdown = countdowns.get(type);
        int seconds = countdown == null ? -1 : Math.max(0, countdown.secondsRemaining);
        String prepLabel = brWorldPreparationSidebarLine(type);

        List<String> lines = new ArrayList<>();
        if (isHungerGames(type)) {
            lines.add(sidebarSystem("Type", type == QueueType.HUNGERGAMES_DUOS ? "Duos" : "Solos", ChatColor.WHITE));
            lines.add(sidebarSystem("Players", queueSize(type) + "/" + idealPlayersFor(type), ChatColor.WHITE));
            lines.add(sidebarSystem("Status", seconds < 0 ? "Waiting" : "Starting", ChatColor.WHITE));
            if (seconds >= 0) lines.add(sidebarSystem("Starting", formatClock(seconds), ChatColor.AQUA));
            lines.add(sidebarBlank(0));
            lines.add(ChatColor.AQUA + "HydraMC.net");
            updateHydraSidebar(player, false, lines, "HUNGER GAMES");
            return;
        }
        String startLabel = seconds < 0 ? "Waiting" : formatClock(seconds);
        appendFightPitLeaders(lines);
        lines.add(sidebarBlank(0));
        lines.add(sidebarSystem("Mode", isHungerGames(type) ? "Hunger Games" : "Battle Royale", ChatColor.WHITE));
        lines.add(sidebarSystem("Queue", isHungerGames(type)
            ? hungerGamesQueueModeLabel(type)
            : type.displayName(), ChatColor.WHITE));
        if (hungerGamesLocalLobbyIds.containsKey(type)) {
            lines.add(sidebarSystem("Lobby", hungerGamesLocalLobbyIds.get(type), ChatColor.WHITE));
        }
        lines.add(sidebarSystem("Players", queueSize(type) + "/" + idealPlayersFor(type), ChatColor.YELLOW));
        lines.add(sidebarSystem("Needed", String.valueOf(minPlayersToStartFor(type)), ChatColor.WHITE));
        lines.add(sidebarSystem("Start", startLabel, seconds < 0 ? ChatColor.GRAY : ChatColor.YELLOW));
        if (prepLabel != null) {
            lines.add(sidebarSystem("Prep", prepLabel, ChatColor.YELLOW));
        }
        lines.add(sidebarBlank(1));
        lines.add(ChatColor.AQUA + "HydraMC.net");
        updateHydraSidebar(player, !isHungerGames(type), lines);
    }

    private void sendHungerGamesDeathMessage(PlayerDeathEvent event) {
        Player victim = event.getEntity();
        String audienceKey = playerAudienceKey(victim);
        if (audienceKey == null) return;
        Component message = event.deathMessage();
        event.deathMessage(null);
        if (message == null) return;
        for (Player viewer : Bukkit.getOnlinePlayers()) {
            if (audienceKey.equals(playerAudienceKey(viewer))) {
                viewer.sendMessage(message);
            }
        }
    }

    private void appendFightPitLeaders(List<String> lines) {
        GameHubService gameHub = plugin instanceof HGLootPlugin hydra ? hydra.gameHubService() : null;
        List<GameHubService.FightPitLeader> leaders = gameHub == null
            ? List.of()
            : gameHub.fightPitKillLeaders(3);
        if (leaders.isEmpty()) {
            lines.add(ChatColor.GRAY + "No Fight Pit kills");
            return;
        }
        for (int index = 0; index < leaders.size(); index++) {
            GameHubService.FightPitLeader leader = leaders.get(index);
            lines.add(ChatColor.GOLD + "" + (index + 1) + ". " + ChatColor.WHITE + leader.playerName()
                + ChatColor.GRAY + " - " + ChatColor.RED + leader.kills());
        }
    }

    private void registerBrTabHealthObjective(Scoreboard board, QueueType type) {
        if (board == null || type == null || isHungerGames(type)) {
            return;
        }
        if (board.getObjective(BR_TAB_HEALTH_OBJECTIVE) != null) {
            return;
        }
        Objective health = board.registerNewObjective(
            BR_TAB_HEALTH_OBJECTIVE,
            Criteria.HEALTH,
            ChatColor.RED + "❤",
            RenderType.HEARTS
        );
        health.setDisplaySlot(DisplaySlot.PLAYER_LIST);
    }

    private void updateLobbySidebar(Player player) {
        UUID playerId = player.getUniqueId();
        int silver = auctionHouseService != null ? auctionHouseService.getSilverBalance(playerId) : 0;
        String rank = sidebarRankTag(player);
        int level = progressionService == null ? 0 : progressionService.level(playerId);
        int battlePassTier = plugin instanceof HGLootPlugin hydra && hydra.battlePassService() != null
            ? hydra.battlePassService().tier(playerId) : 1;
        int prestigeProgress = progressionService == null ? 0 : progressionService.prestigeProgress(playerId);
        int prestigeLevelSize = progressionService == null ? 1000 : progressionService.prestigeLevelSize(playerId);
        int shards = progressionService == null ? 0 : progressionService.shards(playerId);
        int shardFragments = progressionService == null ? 0 : progressionService.shardFragments(playerId);
        int fragmentsPerShard = progressionService == null
            ? ProgressionService.FRAGMENTS_PER_SHARD
            : progressionService.fragmentsPerShard();

        List<String> lines = new ArrayList<>();
        lines.add(sidebarRankSystem("Rank", rank));
        lines.add(sidebarSystem("Level", String.valueOf(level), ChatColor.WHITE));
        lines.add(sidebarSystem("Tier", String.valueOf(battlePassTier), ChatColor.WHITE));
        lines.add(sidebarSystem("XP", formatNumber(prestigeProgress) + "/" + formatNumber(prestigeLevelSize), ChatColor.WHITE));
        lines.add(sidebarSeparator(0));
        lines.add(sidebarSystem("Online", String.valueOf(Bukkit.getOnlinePlayers().size()), ChatColor.WHITE));
        lines.add(sidebarSeparator(1));
        lines.add(sidebarSystem("Coins", formatNumber(silver), ChatColor.WHITE));
        lines.add(SIDEBAR_INFO_COLOR + "Shards " + HydraIcons.SHARD + " "
            + ChatColor.WHITE + formatNumber(shards));
        lines.add(sidebarSystem("Fragments", shardFragments + "/" + fragmentsPerShard, ChatColor.WHITE));
        lines.add(ChatColor.AQUA + "HydraMC.net");
        updateHydraSidebar(player, false, lines);
    }

    public String activeMatchModeLabel(Player player) {
        if (player == null) {
            return null;
        }
        QueueType type = inMatchTypes.get(player.getUniqueId());
        if (type == null) {
            return null;
        }
        return isHungerGames(type)
            ? hungerGamesMatchModeLabel(player.getWorld().getName())
            : "Battle Royale";
    }

    private void updateMatchSidebar(Player player, QueueType type, String worldName) {
        ScoreboardManager manager = Bukkit.getScoreboardManager();
        if (manager == null) {
            return;
        }
        String rootWorldName = rootMatchWorldName(worldName);
        World world = Bukkit.getWorld(rootWorldName);
        if (world == null) {
            return;
        }

        int alive = activeParticipantCountInWorld(rootWorldName);
        int kills = matchKills.getOrDefault(player.getUniqueId(), 0);
        UUID playerId = player.getUniqueId();
        int level = progressionService == null ? 0 : progressionService.level(playerId);
        int battlePassTier = plugin instanceof HGLootPlugin hydra && hydra.battlePassService() != null
            ? hydra.battlePassService().tier(playerId) : 1;
        int prestigeProgress = progressionService == null ? 0 : progressionService.prestigeProgress(playerId);
        int prestigeLevelSize = progressionService == null ? 1000 : progressionService.prestigeLevelSize(playerId);
        int borderMeters = (int) Math.round(world.getWorldBorder().getSize());
        long now = System.currentTimeMillis();
        int nextShrink = matchBorderService.sidebarNext(rootWorldName, borderSettingsForWorld(rootWorldName), now);
        String kothLine = kothService == null ? null : isHungerGames(type)
            ? kothService.sidebarLocationLine(rootWorldName) : kothService.sidebarLine(rootWorldName);
        if (kothLine == null) {
            kothLine = scheduledHungerGamesKothSidebarLine(rootWorldName, now);
        }
        String refillLine = scheduledHungerGamesRefillSidebarLine(rootWorldName, now);
        List<String> eventLines = new ArrayList<>();
        if (kothLine != null) {
            eventLines.add(isHungerGames(type) ? kothLine : sidebarEventContent(kothLine));
        }
        if (refillLine != null) {
            eventLines.add(sidebarEventContent(refillLine));
        }
        String hgBorderLine = isHungerGames(type)
            ? hungerGamesBorderSidebarLine(rootWorldName, now) : null;

        List<String> lines = new ArrayList<>();
        lines.add(sidebarSystem("Alive", String.valueOf(alive), ChatColor.YELLOW));
        lines.add(sidebarSystem("Kills", String.valueOf(kills), ChatColor.RED));
        lines.add(sidebarSeparator(0));
        if (!isHungerGames(type)) {
            lines.add(sidebarSystem("Level", String.valueOf(level), ChatColor.YELLOW));
            lines.add(sidebarSystem("Tier", String.valueOf(battlePassTier), ChatColor.GOLD));
            lines.add(sidebarSystem("XP", formatNumber(prestigeProgress) + "/" + formatNumber(prestigeLevelSize), ChatColor.WHITE));
            lines.add(sidebarSeparator(1));
        }
        lines.add(sidebarSectionHeader("This Match"));
        lines.add(sidebarSystem("Coins", formatNumber(matchSilverEarned(playerId)), ChatColor.WHITE));
        lines.add(sidebarSystem("XP", formatNumber(matchXpEarned(playerId)), ChatColor.YELLOW));
        if (!eventLines.isEmpty()) {
            lines.add(sidebarSeparator(2));
            lines.add(sidebarSectionHeader("Events"));
            int variant = 20;
            for (String eventLine : eventLines) {
                lines.add(sidebarContent(eventLine, variant++));
            }
        }
        if (hgBorderLine != null) {
            lines.add(sidebarSystem("Border", hgBorderLine, ChatColor.WHITE));
        }
        if (eventLines.isEmpty() && !isHungerGames(type)) {
            lines.add(sidebarSeparator(2));
            lines.add(sidebarSectionHeader("World"));
            lines.add(sidebarSystem("Border", borderMeters + "m", ChatColor.RED));
            lines.add(sidebarSystem("Next", formatClock(nextShrink), ChatColor.WHITE));
        }
        lines.add(ChatColor.AQUA + "HydraMC.net");
        updateHydraSidebar(player, !isHungerGames(type), lines,
            isHungerGames(type)
                ? hungerGamesMatchModeLabel(rootWorldName).toUpperCase(Locale.ROOT)
                : "BATTLE ROYALE");
    }

    private void updateHydraSidebar(Player player, boolean keepBrHealthObjective, List<String> lines) {
        updateHydraSidebar(player, keepBrHealthObjective, lines, "HYDRA NETWORK");
    }

    private void updateHydraSidebar(Player player, boolean keepBrHealthObjective, List<String> lines, String title) {
        ScoreboardManager manager = Bukkit.getScoreboardManager();
        if (manager == null || player == null || lines == null) {
            return;
        }
        String signature = keepBrHealthObjective + "|" + title + "|" + String.join("\n", lines);
        Objective current = player.getScoreboard() == null ? null : player.getScoreboard().getObjective(SIDEBAR_OBJECTIVE);
        if (signature.equals(sidebarContentSignatures.get(player.getUniqueId())) && current != null) {
            reapplyHydraPlusDisplay(player);
            return;
        }

        Scoreboard board = prepareHydraSidebarBoard(player, manager, keepBrHealthObjective);
        Objective objective = board.registerNewObjective(
            SIDEBAR_OBJECTIVE, Criteria.DUMMY, sidebarTitle(title));
        objective.setDisplaySlot(DisplaySlot.SIDEBAR);
        registerBrTabHealthObjective(board, keepBrHealthObjective ? QueueType.SOLO : QueueType.HUNGERGAMES);

        int score = lines.size();
        int duplicateVariant = 100;
        Set<String> usedEntries = new HashSet<>();
        for (String rawLine : lines) {
            String entry = rawLine == null ? sidebarBlank(duplicateVariant++) : rawLine;
            while (!usedEntries.add(entry)) {
                entry = entry + sidebarUniqueSuffix(duplicateVariant++);
            }
            objective.getScore(entry).setScore(score--);
        }

        sidebarContentSignatures.put(player.getUniqueId(), signature);
        assignHydraSidebarBoard(player, board);
        reapplyHydraPlusDisplay(player);
    }

    private Scoreboard prepareHydraSidebarBoard(Player player, ScoreboardManager manager, boolean keepBrHealthObjective) {
        Scoreboard board = player.getScoreboard();
        if (board == null || board == manager.getMainScoreboard()) {
            board = manager.getNewScoreboard();
        }
        Objective existing = board.getObjective(SIDEBAR_OBJECTIVE);
        if (existing != null) {
            existing.unregister();
        }
        if (!keepBrHealthObjective) {
            Objective health = board.getObjective(BR_TAB_HEALTH_OBJECTIVE);
            if (health != null) {
                health.unregister();
            }
        }
        reapplyNpcNameHiding(board);
        return board;
    }

    private void assignHydraSidebarBoard(Player player, Scoreboard board) {
        if (player.getScoreboard() != board) {
            player.setScoreboard(board);
        }
    }

    private void reapplyNpcNameHiding(Scoreboard board) {
        if (!(plugin instanceof HGLootPlugin hydra) || hydra.npcService() == null) {
            return;
        }
        hydra.npcService().applyHiddenNameTeam(board);
    }

    private void reapplyHydraPlusDisplay(Player player) {
        if (!(plugin instanceof HGLootPlugin hydra) || hydra.hydraPlusService() == null) {
            return;
        }
        hydra.hydraPlusService().applyToViewer(player);
    }

