    private String sidebarRankLabel(Player player) {
        if (plugin instanceof HGLootPlugin hydra) {
            String staffRank = hydra.staffRankModeFor(player.getUniqueId());
            if (!"none".equalsIgnoreCase(staffRank)) {
                return switch (staffRank) {
                    case "owner" -> "OWNER";
                    case "dev" -> "DEVELOPER";
                    case "admin" -> "ADMIN";
                    case "mod" -> "MOD";
                    case "staff" -> "STAFF";
                    case "trialstaff" -> "TRIAL STAFF";
                    case "helper" -> "HELPER";
                    case "media" -> "MEDIA";
                    case "creator" -> "CREATOR";
                    default -> "STAFF";
                };
            }
            return switch (hydra.hydraRankModeFor(player.getUniqueId())) {
                case "tier3" -> "HYDRA+++";
                case "tier2" -> "HYDRA++";
                case "tier1" -> "HYDRA+";
                case "base" -> "HYDRA";
                default -> "Player";
            };
        }
        return "Player";
    }

    private ChatColor sidebarRankColor(Player player) {
        if (plugin instanceof HGLootPlugin hydra) {
            String staffRank = hydra.staffRankModeFor(player.getUniqueId());
            if (!"none".equalsIgnoreCase(staffRank)) {
                return switch (staffRank) {
                    case "owner" -> ChatColor.RED;
                    case "dev", "media", "creator" -> ChatColor.LIGHT_PURPLE;
                    case "admin" -> ChatColor.DARK_RED;
                    case "helper", "trialstaff" -> ChatColor.AQUA;
                    case "mod", "staff" -> ChatColor.GREEN;
                    default -> ChatColor.GREEN;
                };
            }
            return switch (hydra.hydraRankModeFor(player.getUniqueId())) {
                case "tier3" -> ChatColor.AQUA;
                case "tier2" -> ChatColor.DARK_AQUA;
                case "tier1", "base" -> ChatColor.BLUE;
                default -> ChatColor.WHITE;
            };
        }
        return ChatColor.WHITE;
    }

