    private List<String> loadStructureCommandsFromDataFile() {
        if (matchStructureDataFile == null || matchStructureDataFile.isBlank()) {
            return List.of();
        }
        if (!plugin.getDataFolder().exists() && !plugin.getDataFolder().mkdirs()) {
            return List.of();
        }

        Path path = plugin.getDataFolder().toPath().resolve(matchStructureDataFile);
        if (!Files.exists(path)) {
            return List.of();
        }

        try {
            String raw = Files.readString(path, StandardCharsets.UTF_8);
            List<String> commands = parseStructureData(raw);
            if (!commands.isEmpty()) {
                plugin.getLogger().info("Loaded " + commands.size()
                    + " structure command(s) from " + path.getFileName());
            } else {
                plugin.getLogger().warning("Structure data file is present but no commands were found: " + path.getFileName());
            }
            return commands;
        } catch (IOException ex) {
            plugin.getLogger().warning("Failed reading structure data file " + path.getFileName() + ": " + ex.getMessage());
            return List.of();
        }
    }

    private List<String> loadStructureCommandsFromZipFile() {
        boolean zipPathMissing = matchStructureZipFile == null || matchStructureZipFile.isBlank();
        boolean folderPathMissing = matchStructureNbtSourcePath == null || matchStructureNbtSourcePath.isBlank();
        if (!matchStructureZipEnabled || (zipPathMissing && folderPathMissing)) {
            return List.of();
        }
        if (!plugin.getDataFolder().exists() && !plugin.getDataFolder().mkdirs()) {
            return List.of();
        }

        Path externalDirectorySource = resolveActiveStructureTemplateSource();
        Path zipSource = resolveStructureSourcePath(matchStructureZipFile);

        List<StructureTemplateSource> discovered = new ArrayList<>();
        Path activeSource = null;
        if (externalDirectorySource != null && Files.isDirectory(externalDirectorySource)) {
            collectStructureTemplateSourcesFromDirectory(externalDirectorySource, discovered);
            activeSource = externalDirectorySource;
        } else if (zipSource != null && Files.exists(zipSource)) {
            if (Files.isDirectory(zipSource)) {
                collectStructureTemplateSourcesFromDirectory(zipSource, discovered);
            } else {
                collectStructureTemplateSourcesFromZip(zipSource, discovered);
            }
            activeSource = zipSource;
        }
        if (discovered.isEmpty()) {
            plugin.getLogger().warning("No structure templates discovered from configured sources. nbtSource="
                + externalDirectorySource + ", zipSource=" + zipSource + ", nbtConfig='" + matchStructureNbtSourcePath
                + "', zipConfig='" + matchStructureZipFile + "'");
            return List.of();
        }

        LinkedHashMap<String, StructureTemplateSource> uniqueTemplateSources = new LinkedHashMap<>();
        for (StructureTemplateSource source : discovered) {
            if (source == null || source.id() == null || source.id().isBlank()) {
                continue;
            }
            String normalizedId = normalizeStructureId(source.id());
            if (normalizedId.isBlank()) {
                continue;
            }
            uniqueTemplateSources.putIfAbsent(normalizedId, source);
        }

        List<String> ids = new ArrayList<>(uniqueTemplateSources.keySet());
        ids.sort(String::compareToIgnoreCase);
        if (ids.isEmpty()) {
            plugin.getLogger().warning("Structure source found but no structure NBT entries detected.");
            return List.of();
        }

        for (HungerGamesMapDefinition definition : hungerGamesMapDefinitions()) {
            String normalizedHungerGamesId = normalizeStructureId(definition.structureId());
            if (normalizedHungerGamesId.isBlank()) {
                continue;
            }
            StructureTemplateSource hungerGamesTemplate = uniqueTemplateSources.get(normalizedHungerGamesId);
            if (hungerGamesTemplate != null && hungerGamesTemplate.sourcePath() != null) {
                hydraStructureTemplateFiles.put(normalizedHungerGamesId, hungerGamesTemplate.sourcePath());
            }
        }

        List<String> filtered = new ArrayList<>();
        int netherOnlySkipped = 0;
        int foreignNamespaceSkipped = 0;
        int poolExcludedSkipped = 0;
        for (String id : ids) {
            if (!normalizeStructureId(id).startsWith(HYDRA_STRUCTURE_NAMESPACE + ":")) {
                foreignNamespaceSkipped++;
                continue;
            }
            if (!hungerGamesStructureId.isBlank()
                && normalizeStructureId(id).equals(normalizeStructureId(hungerGamesStructureId))) {
                continue;
            }
            if (matchWorldEnvironment != World.Environment.NETHER && requiresNetherSpawn(id)) {
                netherOnlySkipped++;
                continue;
            }
            if (isExcludedFromMatchStructurePool(id)) {
                poolExcludedSkipped++;
                continue;
            }
            if (matchStructureZipExclude.contains(normalizeStructureId(id))) {
                continue;
            }
            filtered.add(id);
        }
        if (filtered.isEmpty()) {
            plugin.getLogger().warning("All structure ids from configured source are excluded.");
            return List.of();
        }
        matchStructureZipIds.addAll(filtered);
        for (String id : filtered) {
            StructureTemplateSource source = uniqueTemplateSources.get(id);
            if (source != null && source.sourcePath() != null) {
                hydraStructureTemplateFiles.put(id, source.sourcePath());
            }
        }

        String sourceLabel = activeSource == null ? "unknown" : activeSource.getFileName().toString();
        plugin.getLogger().info("Loaded " + filtered.size()
            + " structure id(s) from " + sourceLabel
            + " [excluded=" + (ids.size() - filtered.size())
            + ", netherOnlySkipped=" + netherOnlySkipped
            + ", poolExcludedSkipped=" + poolExcludedSkipped
            + ", foreignNamespaceSkipped=" + foreignNamespaceSkipped + "]");
        return List.of();
    }

    private void syncExternalStructureTemplates(World world) {
        if (world == null) {
            return;
        }
        Path externalDirectorySource = resolveActiveStructureTemplateSource();
        if (externalDirectorySource == null) {
            plugin.getLogger().warning("Structure template source path is null while syncing world " + world.getName() + ".");
            return;
        }
        if (!Files.isDirectory(externalDirectorySource)) {
            plugin.getLogger().warning("Structure template source path is not a directory while syncing world "
                + world.getName() + ": " + externalDirectorySource);
            return;
        }
        Path worldPath = Bukkit.getWorldContainer().toPath().resolve(world.getName());
        int copied = copyExternalStructureTemplatesIntoWorld(externalDirectorySource, worldPath);
        if (copied > 0) {
            plugin.getLogger().info("Synced " + copied + " external structure template(s) from "
                + externalDirectorySource + " into " + world.getName() + "/generated");
        }
        syncGlobalStructureTemplatesFrom(externalDirectorySource);
    }

    private void prepareGlobalStructureTemplates() {
        Path sourceRoot = resolveActiveStructureTemplateSource();
        syncGlobalStructureTemplatesFrom(sourceRoot);
    }

    private void syncGlobalStructureTemplatesFrom(Path sourceRoot) {
        if (sourceRoot == null || !Files.isDirectory(sourceRoot)) {
            return;
        }
        Path globalWorldPath = resolveGlobalStructureTemplateWorldPath();
        if (globalWorldPath == null) {
            return;
        }
        int copied = copyExternalStructureTemplatesIntoWorld(sourceRoot, globalWorldPath);
        if (copied > 0) {
            String worldLabel = globalWorldPath.getFileName() == null
                ? globalWorldPath.toString()
                : globalWorldPath.getFileName().toString();
            plugin.getLogger().info("Synced " + copied + " Hydra structure template(s) from "
                + sourceRoot + " into " + worldLabel + "/generated for template commands.");
        }
    }

    private Path resolveGlobalStructureTemplateWorldPath() {
        World primaryNormalWorld = Bukkit.getWorlds().stream()
            .filter(world -> world.getEnvironment() == World.Environment.NORMAL)
            .findFirst()
            .orElse(null);
        if (primaryNormalWorld != null) {
            return Bukkit.getWorldContainer().toPath().resolve(primaryNormalWorld.getName());
        }
        return Bukkit.getWorldContainer().toPath().resolve("world");
    }

    private Path resolveActiveStructureTemplateSource() {
        Path configured = resolveStructureSourcePath(matchStructureNbtSourcePath);
        if (configured != null && Files.isDirectory(configured)) {
            return configured;
        }
        Path bundled = plugin.getDataFolder().toPath().resolve("Structure nbt").normalize();
        if (Files.isDirectory(bundled)) {
            return bundled;
        }
        return configured;
    }

    private int copyExternalStructureTemplatesIntoWorld(Path externalDirectorySource, Path worldPath) {
        if (externalDirectorySource == null || worldPath == null || !Files.isDirectory(externalDirectorySource)) {
            return 0;
        }

        List<StructureTemplateSource> discovered = new ArrayList<>();
        collectStructureTemplateSourcesFromDirectory(externalDirectorySource, discovered);
        if (discovered.isEmpty()) {
            return 0;
        }

        LinkedHashMap<String, Path> uniqueTemplates = new LinkedHashMap<>();
        for (StructureTemplateSource source : discovered) {
            if (source == null || source.id() == null || source.id().isBlank() || source.sourcePath() == null) {
                continue;
            }
            String normalizedId = normalizeStructureId(source.id());
            if (normalizedId.isBlank() || !normalizedId.startsWith(HYDRA_STRUCTURE_NAMESPACE + ":")) {
                continue;
            }
            if (matchWorldEnvironment != World.Environment.NETHER && requiresNetherSpawn(normalizedId)) {
                continue;
            }
            if (isExcludedFromMatchStructurePool(normalizedId) || matchStructureZipExclude.contains(normalizedId)) {
                continue;
            }
            uniqueTemplates.putIfAbsent(normalizedId, source.sourcePath());
        }
        if (uniqueTemplates.isEmpty()) {
            return 0;
        }

        Path generatedPath = worldPath.resolve("generated");
        int copied = 0;
        for (Map.Entry<String, Path> template : uniqueTemplates.entrySet()) {
            String id = template.getKey();
            int colon = id.indexOf(':');
            if (colon <= 0 || colon >= id.length() - 1) {
                continue;
            }
            String namespace = id.substring(0, colon);
            String relative = id.substring(colon + 1);
            Path destination = generatedPath.resolve(namespace).resolve("structures").resolve(relative + ".nbt");
            try {
                Files.createDirectories(destination.getParent());
                Files.copy(template.getValue(), destination, StandardCopyOption.REPLACE_EXISTING);
                copied++;
            } catch (IOException ex) {
                String worldLabel = worldPath.getFileName() == null ? worldPath.toString() : worldPath.getFileName().toString();
                plugin.getLogger().warning("Failed syncing template " + id + " into world " + worldLabel
                    + ": " + ex.getMessage());
            }
        }
        return copied;
    }

    private Path resolveStructureSourcePath(String configuredPath) {
        if (configuredPath == null || configuredPath.isBlank()) {
            return null;
        }
        String trimmed = configuredPath.trim();
        try {
            Path path = Path.of(trimmed);
            if (path.isAbsolute()) {
                return path.normalize();
            }
            Path normalized = path.normalize();
            if (Files.exists(normalized)) {
                return normalized;
            }

            Path worldContainer = Bukkit.getWorldContainer().toPath().normalize();
            Path worldRelative = worldContainer.resolve(path).normalize();
            if (Files.exists(worldRelative)) {
                return worldRelative;
            }

            Path pluginRelative = plugin.getDataFolder().toPath().resolve(path).normalize();
            if (Files.exists(pluginRelative)) {
                return pluginRelative;
            }

            // Keep the plugin-relative fallback for future writes even if the path does not exist yet.
            return pluginRelative;
        } catch (Exception ex) {
            plugin.getLogger().warning("Invalid structure source path '" + trimmed + "': " + ex.getMessage());
            return null;
        }
    }

    private void collectStructureTemplateSourcesFromDirectory(Path root, List<StructureTemplateSource> out) {
        if (root == null || out == null || !Files.isDirectory(root)) {
            return;
        }
        try (Stream<Path> walk = Files.walk(root)) {
            for (Path file : walk.filter(Files::isRegularFile).toList()) {
                String relative = root.relativize(file).toString().replace('\\', '/');
                String id = structureIdFromTemplatePath(relative);
                if (id == null || id.isBlank()) {
                    continue;
                }
                out.add(new StructureTemplateSource(id, file));
            }
        } catch (IOException ex) {
            plugin.getLogger().warning("Failed reading structure directory " + root + ": " + ex.getMessage());
        }
    }

    private void collectStructureTemplateSourcesFromZip(Path zipPath, List<StructureTemplateSource> out) {
        if (zipPath == null || out == null || !Files.exists(zipPath)) {
            return;
        }
        try (ZipFile zipFile = new ZipFile(zipPath.toFile())) {
            Enumeration<? extends ZipEntry> entries = zipFile.entries();
            while (entries.hasMoreElements()) {
                ZipEntry entry = entries.nextElement();
                if (entry.isDirectory()) {
                    continue;
                }
                String id = structureIdFromTemplatePath(entry.getName());
                if (id == null || id.isBlank()) {
                    continue;
                }
                out.add(new StructureTemplateSource(id, null));
            }
        } catch (IOException ex) {
            plugin.getLogger().warning("Failed reading structure zip file " + zipPath.getFileName() + ": " + ex.getMessage());
        }
    }

    private String structureIdFromTemplatePath(String templatePath) {
        if (templatePath == null || templatePath.isBlank()) {
            return null;
        }
        String normalized = templatePath.replace('\\', '/');
        String lower = normalized.toLowerCase(Locale.ROOT);
        if (!lower.endsWith(".nbt")) {
            return null;
        }

        String noExtension = normalized.substring(0, normalized.length() - 4);
        String[] parts = noExtension.split("/");
        if (parts.length == 1) {
            String simple = canonicalHydraSimpleStructureName(parts[0]);
            if (simple.isBlank()) {
                return null;
            }
            return normalizeStructureId(HYDRA_STRUCTURE_NAMESPACE + ":" + simple);
        }
        if (parts.length < 2) {
            return null;
        }

        for (int i = 0; i <= parts.length - 4; i++) {
            if (!"data".equalsIgnoreCase(parts[i])) {
                continue;
            }
            String container = parts[i + 2];
            if (!"structure".equalsIgnoreCase(container) && !"structures".equalsIgnoreCase(container)) {
                continue;
            }
            String namespace = parts[i + 1];
            String relative = joinPathParts(parts, i + 3);
            if (namespace.isBlank() || relative.isBlank()) {
                return null;
            }
            return normalizeStructureId(namespace + ":" + relative);
        }

        if (parts.length >= 3
            && ("structure".equalsIgnoreCase(parts[1]) || "structures".equalsIgnoreCase(parts[1]))) {
            String namespace = parts[0];
            String relative = joinPathParts(parts, 2);
            if (namespace.isBlank() || relative.isBlank()) {
                return null;
            }
            return normalizeStructureId(namespace + ":" + relative);
        }

        // Support simple folder roots like "ancient_city/.../*.nbt" in external references.
        String namespace = parts[0];
        String relative = joinPathParts(parts, 1);
        if (namespace.isBlank() || relative.isBlank()) {
            return null;
        }
        return normalizeStructureId(namespace + ":" + relative);
    }

    private static String sanitizeSimpleStructureName(String raw) {
        if (raw == null || raw.isBlank()) {
            return "";
        }
        StringBuilder builder = new StringBuilder(raw.length());
        for (char c : raw.toLowerCase(Locale.ROOT).toCharArray()) {
            if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '/') {
                builder.append(c);
            } else if (Character.isWhitespace(c)) {
                builder.append('_');
            } else {
                builder.append('_');
            }
        }
        return builder.toString().replaceAll("_+", "_");
    }

    private static String normalizeHungerGamesMapKey(String raw) {
        if (raw == null || raw.isBlank()) {
            return "";
        }
        return sanitizeSimpleStructureName(raw)
            .replace('-', '_')
            .replace('/', '_');
    }

    private static List<HungerGamesMapDefinition> hungerGamesMapDefinitions() {
        return List.of(
            new HungerGamesMapDefinition(
                OUTCOVE_HUNGER_GAMES_MAP_KEY,
                DEFAULT_HUNGER_GAMES_MAP_NAME,
                DEFAULT_HUNGER_GAMES_STRUCTURE_ID,
                null,
                null,
                null
            ),
            new HungerGamesMapDefinition(
                WILD_WEST_HUNGER_GAMES_MAP_KEY,
                WILD_WEST_HUNGER_GAMES_MAP_NAME,
                WILD_WEST_HUNGER_GAMES_STRUCTURE_ID,
                WILD_WEST_BORDER_CENTER_X,
                WILD_WEST_BORDER_CENTER_Z,
                WILD_WEST_BORDER_SIZE
            ),
            new HungerGamesMapDefinition(
                AZTEC_JUNGLE_HUNGER_GAMES_MAP_KEY,
                AZTEC_JUNGLE_HUNGER_GAMES_MAP_NAME,
                AZTEC_JUNGLE_HUNGER_GAMES_STRUCTURE_ID,
                null,
                null,
                AZTEC_JUNGLE_BORDER_SIZE
            )
        );
    }

    private static HungerGamesMapDefinition hungerGamesMapDefinitionByKey(String rawKey) {
        String key = normalizeHungerGamesMapKey(rawKey);
        if (key.isBlank()) {
            return null;
        }
        return hungerGamesMapDefinitions().stream()
            .filter(definition -> definition.key().equals(key))
            .findFirst()
            .orElse(null);
    }

    private static HungerGamesMapDefinition resolveHungerGamesMapDefinition(String structureId, String mapNameOrKey) {
        String normalizedStructureId = normalizeStructureId(structureId);
        for (HungerGamesMapDefinition definition : hungerGamesMapDefinitions()) {
            if (normalizeStructureId(definition.structureId()).equals(normalizedStructureId)) {
                return definition;
            }
        }
        String normalizedKey = normalizeHungerGamesMapKey(mapNameOrKey);
        if (normalizedKey.equals("ruined_city") || normalizedKey.equals("ruined_city_hg_map")
            || normalizedKey.equals("city_hg_map") || normalizedKey.equals("city")) {
            normalizedKey = OUTCOVE_HUNGER_GAMES_MAP_KEY;
        }
        if (normalizedKey.equals("outcove_hg_map")) {
            normalizedKey = OUTCOVE_HUNGER_GAMES_MAP_KEY;
        }
        if (normalizedKey.equals("wildwest")) {
            normalizedKey = WILD_WEST_HUNGER_GAMES_MAP_KEY;
        }
        if (normalizedKey.equals("forest") || normalizedKey.equals("aztec") || normalizedKey.equals("jungle")) {
            normalizedKey = AZTEC_JUNGLE_HUNGER_GAMES_MAP_KEY;
        }
        return hungerGamesMapDefinitionByKey(normalizedKey);
    }

    private static String canonicalHydraSimpleStructureName(String raw) {
        String simple = sanitizeSimpleStructureName(raw);
        if (simple.isBlank()) {
            return "";
        }
        simple = simple.replaceAll("_v\\d+$", "");
        String[] knownPrefixes = {
            "cornucopia_structure_",
            "cornucopia_house_",
            "cornucopia_boat_",
            "cornucopia_nature_",
            "cornucopia_",
            "overworld_structure_",
            "overworld_house_",
            "overworld_boat_",
            "overworld_nature_",
            "nether_structure_",
            "nether_boat_",
            "nether_nature_",
            "valous_structure_",
            "valous_house_",
            "valous_boat_",
            "valous_nature_"
        };
        for (String prefix : knownPrefixes) {
            if (simple.startsWith(prefix) && simple.length() > prefix.length()) {
                simple = simple.substring(prefix.length());
                break;
            }
        }
        return switch (simple) {
            case "granny" -> "grannys_house";
            case "noob" -> "noob_house";
            case "pale" -> "pale_boat";
            case "spruce" -> "spruce_boat";
            case "warped" -> "warped_boat";
            default -> simple;
        };
    }

    private static String joinPathParts(String[] parts, int start) {
        if (parts == null || start < 0 || start >= parts.length) {
            return "";
        }
        StringBuilder builder = new StringBuilder();
        for (int i = start; i < parts.length; i++) {
            if (parts[i] == null || parts[i].isBlank()) {
                continue;
            }
            if (!builder.isEmpty()) {
                builder.append('/');
            }
            builder.append(parts[i]);
        }
        return builder.toString();
    }

