    private List<String> parseStructureData(String raw) {
        if (raw == null) {
            return List.of();
        }
        String trimmed = raw.trim();
        if (trimmed.isEmpty()) {
            return List.of();
        }

        if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
            try {
                JsonElement root = JsonParser.parseString(trimmed);
                List<String> commands = new ArrayList<>();
                if (root.isJsonArray()) {
                    appendCommandsFromArray(root.getAsJsonArray(), commands);
                } else if (root.isJsonObject()) {
                    JsonObject object = root.getAsJsonObject();
                    JsonElement commandsElement = object.get("commands");
                    if (commandsElement != null && commandsElement.isJsonArray()) {
                        appendCommandsFromArray(commandsElement.getAsJsonArray(), commands);
                    }
                    JsonElement structuresElement = object.get("structures");
                    if (structuresElement != null && structuresElement.isJsonArray()) {
                        for (JsonElement element : structuresElement.getAsJsonArray()) {
                            if (!element.isJsonObject()) {
                                continue;
                            }
                            JsonObject structure = element.getAsJsonObject();
                            JsonElement command = structure.get("command");
                            if (command != null && command.isJsonPrimitive()) {
                                addCommand(commands, command.getAsString());
                            }
                        }
                    }
                }
                return commands;
            } catch (JsonParseException ignored) {
                // Fall through to line-based parsing below.
            }
        }

        List<String> commands = new ArrayList<>();
        for (String line : raw.split("\\R")) {
            addCommand(commands, line);
        }
        return commands;
    }

    private static void appendCommandsFromArray(JsonArray array, List<String> out) {
        for (JsonElement element : array) {
            if (element != null && element.isJsonPrimitive()) {
                addCommand(out, element.getAsString());
            }
        }
    }

    private static void addCommand(List<String> out, String raw) {
        if (raw == null) {
            return;
        }
        String command = raw.trim();
        if (command.isEmpty() || command.startsWith("#")) {
            return;
        }
        out.add(command);
    }

    private static String normalizeStructureId(String raw) {
        if (raw == null) {
            return "";
        }
        String id = raw.trim().toLowerCase(Locale.ROOT);
        if (id.isEmpty()) {
            return "";
        }
        if (!id.contains(":")) {
            return "minecraft:" + id;
        }
        return id;
    }

    private static String normalizeHydraQueueStructureId(String raw) {
        if (raw == null) {
            return "";
        }
        String id = raw.trim();
        if (id.isBlank()) {
            return "";
        }
        if (!id.contains(":")) {
            String simple = canonicalHydraSimpleStructureName(id);
            return simple.isBlank() ? "" : HYDRA_STRUCTURE_NAMESPACE + ":" + simple;
        }
        return normalizeStructureId(id);
    }

    private boolean isOriginStructurePlaceCommand(String command) {
        if (command == null || command.isBlank()) {
            return false;
        }
        int exclusionRadius = originExclusionRadius();
        if (exclusionRadius <= 0) {
            return false;
        }
        String[] parts = command.trim().split("\\s+");
        for (int i = 0; i < parts.length - 5; i++) {
            if (!parts[i].equalsIgnoreCase("place")) {
                continue;
            }
            String kind = parts[i + 1].toLowerCase(Locale.ROOT);
            if (!kind.equals("template") && !kind.equals("structure")) {
                continue;
            }
            String xToken = parts[i + 3];
            String zToken = parts[i + 5];
            Integer x = parseIntOrNull(xToken);
            Integer z = parseIntOrNull(zToken);
            if (x != null && z != null && Math.hypot(x - cornucopiaCenterX(), z - cornucopiaCenterZ()) < exclusionRadius) {
                return true;
            }
        }
        return false;
    }

    private static Integer parseIntOrNull(String token) {
        if (token == null) {
            return null;
        }
        try {
            return Integer.parseInt(token);
        } catch (NumberFormatException ignored) {
            return null;
        }
    }

