    public enum DebugLeaderboardType {
        KILLS("kills", "TOP KILLS", "Kills"),
        WINS_TOTAL("wins_total", "TOP TOTAL WINS", "Total Wins"),
        WINS_BR("wins_br", "TOP BR WINS", "BR Wins"),
        WINS_HG("wins_hg", "TOP HG WINS", "HG Wins"),
        LEVEL("level", "TOP LEVEL", "Level"),
        MONEY("money", "TOP COINS", "Coins");

        private final String key;
        private final String title;
        private final String menuLabel;

        DebugLeaderboardType(String key, String title, String menuLabel) {
            this.key = key;
            this.title = title;
            this.menuLabel = menuLabel;
        }

        public String key() {
            return key;
        }

        public String title() {
            return title;
        }

        public String menuLabel() {
            return menuLabel;
        }

        public boolean isWinsBoard() {
            return this == WINS_TOTAL || this == WINS_BR || this == WINS_HG;
        }

        public DebugLeaderboardType nextCycleType() {
            DebugLeaderboardType[] cycle = {
                KILLS,
                WINS_TOTAL,
                WINS_HG,
                WINS_BR,
                LEVEL,
                MONEY
            };
            for (int i = 0; i < cycle.length; i++) {
                if (cycle[i] == this) {
                    return cycle[(i + 1) % cycle.length];
                }
            }
            return KILLS;
        }

        public static DebugLeaderboardType fromKey(String raw) {
            if (raw == null || raw.isBlank()) {
                return null;
            }
            String normalized = raw.trim().toLowerCase(Locale.ROOT);
            if (normalized.equals("kills_all") || normalized.equals("kills_br") || normalized.equals("kills_hg")) {
                return KILLS;
            }
            if (normalized.equals("wins") || normalized.equals("wins_all")
                || normalized.equals("total_wins") || normalized.equals("overall_wins")) {
                return WINS_TOTAL;
            }
            if (normalized.equals("coins") || normalized.equals("coin") || normalized.equals("gold") || normalized.equals("silver") || normalized.equals("balance")) {
                return MONEY;
            }
            for (DebugLeaderboardType type : values()) {
                if (type.key.equalsIgnoreCase(normalized)) {
                    return type;
                }
            }
            return null;
        }
    }

