    private static final class BrWorldPreparationState {
        private final String worldName;
        private final QueueType type;
        private volatile BrWorldPreparationPhase phase;
        private volatile int completedUnits;
        private volatile int totalUnits;

        private BrWorldPreparationState(String worldName, QueueType type) {
            this.worldName = worldName;
            this.type = type;
            this.phase = BrWorldPreparationPhase.CREATING;
            this.completedUnits = 0;
            this.totalUnits = 1;
        }

        private void setPhase(BrWorldPreparationPhase phase, int completedUnits, int totalUnits) {
            this.phase = phase == null ? BrWorldPreparationPhase.CREATING : phase;
            this.totalUnits = Math.max(1, totalUnits);
            this.completedUnits = Math.max(0, Math.min(this.totalUnits, completedUnits));
        }

        private int progressPercent() {
            if (phase == BrWorldPreparationPhase.READY) {
                return 100;
            }
            if (phase == BrWorldPreparationPhase.PLACING_CORNUCOPIA) {
                return 99;
            }
            if (phase == BrWorldPreparationPhase.PROTOTYPE_VALIDATION) {
                return 99;
            }
            if (phase == BrWorldPreparationPhase.CHUNK_HANDOFF) {
                return 93;
            }
            if (phase == BrWorldPreparationPhase.POST_PROCESSING) {
                return 94;
            }
            if (phase == BrWorldPreparationPhase.CENTER_TERRAIN) {
                return 96;
            }
            if (totalUnits <= 0) {
                return 0;
            }
            return Math.max(0, Math.min(99, (int) Math.floor((completedUnits * 100.0D) / totalUnits)));
        }

        private int progressPercentRoundedToTen() {
            if (phase == BrWorldPreparationPhase.READY) {
                return 100;
            }
            int percent = progressPercent();
            return Math.max(0, Math.min(90, (percent / 10) * 10));
        }
    }

