    private static final class BrGenerationFlight {
        private final BrGenerationKey key;
        private final UUID token;
        private final BrGenerationCompatibility compatibility;
        private final long createdAtMs;
        private final CompletableFuture<World> completionFuture;
        private volatile String worldName;
        private volatile long seed;
        private volatile BrGenerationState state;
        private volatile int generatedChunks;
        private volatile int totalChunks;
        private volatile long seedSelectionMs;
        private volatile ValousSeedSelector.Policy valousPolicy =
            ValousSeedSelector.Policy.FULL_PRODUCTION;
        private volatile ValousSeedSelector.Selection valousSeedSelection;
        private volatile UUID ownerReservationId;
        private volatile QueueType claimedQueueType;
        private volatile boolean factoryManaged;
        private volatile boolean canceled;
        private volatile String failureReason;

        private BrGenerationFlight(BrGenerationKey key, BrGenerationCompatibility compatibility) {
            this.key = key;
            this.token = UUID.randomUUID();
            this.compatibility = compatibility;
            this.createdAtMs = System.currentTimeMillis();
            this.completionFuture = new CompletableFuture<>();
            this.worldName = "pending";
            this.state = BrGenerationState.CREATING;
            this.totalChunks = 1;
        }

        private boolean isTerminal() {
            return state == BrGenerationState.CANCELING || state == BrGenerationState.FAILED;
        }

        private boolean isClaimed() {
            return ownerReservationId != null
                || state == BrGenerationState.CLAIMED
                || state == BrGenerationState.ACTIVE;
        }
    }

