    private enum HellscapeRegion {
        MAGMA_CAVERNS(true, Biome.BASALT_DELTAS),
        SCORCHED_STEPS(false, Biome.BASALT_DELTAS),
        FUME_VENTS(false, Biome.SOUL_SAND_VALLEY),
        NETHER_WASTES(false, Biome.NETHER_WASTES),
        NETHER_WASTES_DEEP(false, Biome.NETHER_WASTES),
        SOUL_SAND_VALLEY(false, Biome.SOUL_SAND_VALLEY),
        CRIMSON_FOREST(false, Biome.CRIMSON_FOREST),
        WARPED_FOREST(false, Biome.WARPED_FOREST),
        BASALT_DELTAS(false, Biome.BASALT_DELTAS);

        private final boolean guaranteed;
        private final Biome vanillaBiome;

        HellscapeRegion(boolean guaranteed, Biome vanillaBiome) {
            this.guaranteed = guaranteed;
            this.vanillaBiome = vanillaBiome;
        }

        private boolean guaranteed() {
            return guaranteed;
        }

        private Biome vanillaBiome() {
            return vanillaBiome;
        }
    }

    private record HellscapeBiomeSelection(
        EnumSet<HellscapeRegion> activeRegions,
        List<HellscapeRegion> activeSurfaceRegions
    ) {
        private boolean isActive(HellscapeRegion region) {
            return activeRegions.contains(region);
        }
    }

    private record HellscapeSurfaceBlend(
        HellscapeRegion primary,
        HellscapeRegion secondary,
        double secondaryWeight
    ) {
        private HellscapeSurfaceBlend {
            Objects.requireNonNull(primary, "primary");
            if (secondary == null) {
                secondary = primary;
            }
            if (primary == secondary) {
                secondaryWeight = 0.0D;
            } else {
                secondaryWeight = clamp(secondaryWeight, 0.0D, 0.48D);
            }
        }

        private boolean transition() {
            return primary != secondary && secondaryWeight > 0.01D;
        }

        private double blend(double primaryValue, double secondaryValue) {
            return transition() ? brLerp(primaryValue, secondaryValue, secondaryWeight) : primaryValue;
        }
    }

    private enum ValousCaveRegion {
        MOLTEN_CAVERNS,
        FROZEN_CAVES,
        SCULK_ABYSS,
        LUSH_JUNGLE
    }

    private static final List<HellscapeRegion> HELLSCAPE_OPTIONAL_POOL = List.of(
        HellscapeRegion.SCORCHED_STEPS,
        HellscapeRegion.FUME_VENTS,
        HellscapeRegion.NETHER_WASTES,
        HellscapeRegion.NETHER_WASTES_DEEP,
        HellscapeRegion.SOUL_SAND_VALLEY,
        HellscapeRegion.CRIMSON_FOREST,
        HellscapeRegion.WARPED_FOREST,
        HellscapeRegion.BASALT_DELTAS
    );

    private static HellscapeBiomeSelection selectHellscapeBiomeSelection(long seed) {
        List<HellscapeRegion> shuffledPool = new ArrayList<>(HELLSCAPE_OPTIONAL_POOL);
        Collections.shuffle(shuffledPool, new Random(seed ^ 0x78D4_0C31_13A2_5F0BL));

        List<HellscapeRegion> picked = new ArrayList<>(shuffledPool.subList(0, Math.min(5, shuffledPool.size())));
        if (picked.contains(HellscapeRegion.NETHER_WASTES_DEEP) && !picked.contains(HellscapeRegion.NETHER_WASTES)) {
            for (int i = 0; i < picked.size(); i++) {
                if (picked.get(i) != HellscapeRegion.NETHER_WASTES_DEEP) {
                    picked.set(i, HellscapeRegion.NETHER_WASTES);
                    break;
                }
            }
        }

        EnumSet<HellscapeRegion> active = EnumSet.of(HellscapeRegion.MAGMA_CAVERNS);
        active.addAll(picked);
        if (active.contains(HellscapeRegion.NETHER_WASTES_DEEP)) {
            active.add(HellscapeRegion.NETHER_WASTES);
        }

        List<HellscapeRegion> surface = new ArrayList<>();
        for (HellscapeRegion region : picked) {
            if (region == HellscapeRegion.NETHER_WASTES_DEEP) {
                continue;
            }
            if (!surface.contains(region)) {
                surface.add(region);
            }
        }
        if (surface.isEmpty()) {
            surface.add(HellscapeRegion.NETHER_WASTES);
        }
        if (active.contains(HellscapeRegion.NETHER_WASTES) && !surface.contains(HellscapeRegion.NETHER_WASTES)) {
            surface.add(HellscapeRegion.NETHER_WASTES);
        }

        return new HellscapeBiomeSelection(active, List.copyOf(surface));
    }

    private static double valousSurfaceSignal(long seed, int x, int z) {
        return brNoise2(seed + 0x7104L, x * 0.0035D, z * 0.0035D)
            + (brNoise2(seed + 0x7105L, x * 0.0011D, z * 0.0011D) * 0.18D);
    }

    private static boolean valousIsBoilgroundsColumn(long seed, int x, int z) {
        return valousSurfaceSignal(seed, x, z) < -0.18D;
    }

    private static ValousCaveRegion valousCaveRegionFor(long seed, int x, int y, int z) {
        if (y < -108) {
            return ValousCaveRegion.SCULK_ABYSS;
        }
        double macro = brNoise2(seed + 0x7701L, x * 0.0022D, z * 0.0022D);
        double detail = brNoise2(seed + 0x7702L + (y * 17L), x * 0.0075D, z * 0.0075D);
        double depthBias = clamp((-18.0D - y) / 128.0D, -0.30D, 0.70D);
        double value = macro + (detail * 0.32D);
        if (value < -0.42D) {
            return ValousCaveRegion.MOLTEN_CAVERNS;
        }
        if (value > 0.42D) {
            return ValousCaveRegion.FROZEN_CAVES;
        }
        if (detail + depthBias > 0.48D && y > -82) {
            return ValousCaveRegion.LUSH_JUNGLE;
        }
        return ValousCaveRegion.SCULK_ABYSS;
    }

    private static HellscapeRegion selectHellscapeSurfaceRegion(
        long seed,
        long salt,
        double mapRadius,
        int x,
        int z,
        List<HellscapeRegion> activeSurfaceRegions
    ) {
        return selectHellscapeSurfaceBlend(seed, salt, mapRadius, x, z, activeSurfaceRegions).primary();
    }

    private static HellscapeSurfaceBlend selectHellscapeSurfaceBlend(
        long seed,
        long salt,
        double mapRadius,
        int x,
        int z,
        List<HellscapeRegion> activeSurfaceRegions
    ) {
        if (activeSurfaceRegions == null || activeSurfaceRegions.isEmpty()) {
            return new HellscapeSurfaceBlend(HellscapeRegion.NETHER_WASTES, HellscapeRegion.NETHER_WASTES, 0.0D);
        }
        double distance = Math.hypot(x, z);
        HellscapeRegion centerRegion = activeSurfaceRegions.contains(HellscapeRegion.NETHER_WASTES)
            ? HellscapeRegion.NETHER_WASTES
            : activeSurfaceRegions.get(0);
        if (distance <= 170.0D) {
            return new HellscapeSurfaceBlend(centerRegion, centerRegion, 0.0D);
        }

        double warpX = x + (brNoise2(seed + salt + 0x51L, x * 0.0021D, z * 0.0021D) * 96.0D);
        double warpZ = z + (brNoise2(seed + salt + 0x52L, z * 0.0021D, x * 0.0021D) * 96.0D);
        double bestScore = Double.MAX_VALUE;
        double secondScore = Double.MAX_VALUE;
        HellscapeRegion best = centerRegion;
        HellscapeRegion second = centerRegion;
        for (int i = 0; i < activeSurfaceRegions.size(); i++) {
            HellscapeRegion region = activeSurfaceRegions.get(i);
            double angle = ((Math.PI * 2.0D) / activeSurfaceRegions.size()) * i;
            angle += brNoise2(seed + salt + 0x61L, i * 0.47D, 0.19D) * 0.92D;
            double radius = (mapRadius * 0.42D)
                + (((brNoise2(seed + salt + 0x62L, i * 0.37D, 0.71D) + 1.0D) * 0.5D) * mapRadius * 0.22D);
            double anchorX = Math.cos(angle) * radius;
            double anchorZ = Math.sin(angle) * radius;
            double score = Math.hypot(warpX - anchorX, warpZ - anchorZ)
                + (Math.abs(brNoise2(seed + salt + 0x63L + i, x * 0.0056D, z * 0.0056D)) * 64.0D);
            if (score < bestScore) {
                secondScore = bestScore;
                second = best;
                bestScore = score;
                best = region;
            } else if (score < secondScore) {
                secondScore = score;
                second = region;
            }
        }
        if (second == best || secondScore == Double.MAX_VALUE) {
            return new HellscapeSurfaceBlend(best, best, 0.0D);
        }

        double gap = Math.max(0.0D, secondScore - bestScore);
        double transitionBand = 72.0D
            + (Math.abs(brNoise2(seed + salt + 0x64L, x * 0.0028D, z * 0.0028D)) * 24.0D);
        double edge = 1.0D - clamp(gap / transitionBand, 0.0D, 1.0D);
        edge = smoothstep(edge);
        double secondaryWeight = edge
            * (0.42D + (Math.max(0.0D, brNoise2(seed + salt + 0x65L, x * 0.0062D, z * 0.0062D)) * 0.06D));
        double centerFade = clamp((distance - 170.0D) / 48.0D, 0.0D, 1.0D);
        secondaryWeight *= centerFade;
        return new HellscapeSurfaceBlend(best, second, secondaryWeight);
    }

    private static double hellscapeBaseFloorHeight(long seed, HellscapeRegion region, int x, int z) {
        double macro = brNoise2(seed + 0x5100L + region.ordinal(), x * 0.00095D, z * 0.00095D);
        double broad = brNoise2(seed + 0x5101L + region.ordinal(), x * 0.0019D, z * 0.0019D);
        double detail = brNoise2(seed + 0x5102L + region.ordinal(), x * 0.0065D, z * 0.0065D);
        double ridges = Math.abs(brNoise2(seed + 0x5103L + region.ordinal(), x * 0.0031D, z * 0.0031D));
        double shelves = Math.max(0.0D, brNoise2(seed + 0x5105L + region.ordinal(), x * 0.0028D, z * 0.0028D));
        return switch (region) {
            case SCORCHED_STEPS -> 80.0D + (macro * 20.0D) + (ridges * 118.0D) + (shelves * 24.0D) + (detail * 24.0D);
            case FUME_VENTS -> 24.0D + (macro * 14.0D) + (broad * 16.0D) + (shelves * 12.0D) + (detail * 18.0D);
            case NETHER_WASTES -> {
                double rolling = 39.0D + (macro * 10.0D) + (broad * 12.0D) + (detail * 5.0D);
                double plateau = Math.round((rolling + (shelves * 8.0D)) / 5.0D) * 5.0D;
                yield brLerp(rolling, plateau, 0.24D) + (shelves * 5.0D);
            }
            case SOUL_SAND_VALLEY -> 26.0D + (macro * 14.0D) + (ridges * 30.0D) + (shelves * 22.0D) + (detail * 12.0D);
            case CRIMSON_FOREST -> 36.0D + (macro * 16.0D) + (broad * 20.0D) + (shelves * 16.0D) + (detail * 14.0D);
            case WARPED_FOREST -> 40.0D + (macro * 18.0D) + (broad * 22.0D) + (shelves * 18.0D) + (detail * 18.0D);
            case BASALT_DELTAS -> 30.0D + (macro * 10.0D) + (ridges * 56.0D) + (shelves * 10.0D) + (detail * 12.0D);
            default -> 34.0D + (macro * 16.0D) + (broad * 18.0D) + (shelves * 14.0D) + (detail * 12.0D);
        };
    }

    private static double hellscapeBaseCeilingHeight(long seed, HellscapeRegion region, int x, int z, double floorHeight) {
        double macro = brNoise2(seed + 0x5200L + region.ordinal(), x * 0.00085D, z * 0.00085D);
        double broad = brNoise2(seed + 0x5201L + region.ordinal(), x * 0.0015D, z * 0.0015D);
        double detail = brNoise2(seed + 0x5202L + region.ordinal(), x * 0.0048D, z * 0.0048D);
        double base = switch (region) {
            case SCORCHED_STEPS -> 232.0D + (macro * 12.0D) + (broad * 18.0D) + (detail * 10.0D);
            case FUME_VENTS -> 132.0D + (macro * 10.0D) + (broad * 18.0D) + (detail * 10.0D);
            case NETHER_WASTES -> 140.0D + (macro * 12.0D) + (broad * 18.0D) + (detail * 10.0D);
            case SOUL_SAND_VALLEY -> 152.0D + (macro * 12.0D) + (broad * 16.0D) + (detail * 10.0D);
            case CRIMSON_FOREST -> 160.0D + (macro * 12.0D) + (broad * 18.0D) + (detail * 10.0D);
            case WARPED_FOREST -> 168.0D + (macro * 12.0D) + (broad * 18.0D) + (detail * 12.0D);
            case BASALT_DELTAS -> 150.0D + (macro * 8.0D) + (broad * 16.0D) + (detail * 8.0D);
            default -> 144.0D + (macro * 10.0D) + (broad * 18.0D) + (detail * 10.0D);
        };
        return Math.max(base, floorHeight + 28.0D);
    }

    private static int computeHellscapeBlendedFloorY(
        long seed,
        HellscapeSurfaceBlend blend,
        int x,
        int z,
        int minY,
        int maxY
    ) {
        double primary = hellscapeBaseFloorHeight(seed, blend.primary(), x, z);
        double secondary = hellscapeBaseFloorHeight(seed, blend.secondary(), x, z);
        double mixed = blend.blend(primary, secondary);
        if (blend.transition()) {
            mixed += brNoise2(seed + 0x5104L, x * 0.0034D, z * 0.0034D) * 5.0D * blend.secondaryWeight();
        }
        return clamp((int) Math.round(mixed), Math.max(minY + 8, 8), maxY - 24);
    }

    private static int computeHellscapeBlendedCeilingY(
        long seed,
        HellscapeSurfaceBlend blend,
        int x,
        int z,
        int floorY,
        int maxY
    ) {
        double primary = hellscapeBaseCeilingHeight(seed, blend.primary(), x, z, floorY);
        double secondary = hellscapeBaseCeilingHeight(seed, blend.secondary(), x, z, floorY);
        double mixed = blend.blend(primary, secondary);
        if (blend.transition()) {
            mixed += brNoise2(seed + 0x5204L, x * 0.0028D, z * 0.0028D) * 4.0D * blend.secondaryWeight();
        }
        return clamp((int) Math.round(mixed), floorY + 20, maxY - 2);
    }

    private static HellscapeRegion selectHellscapeMaterialRegion(HellscapeSurfaceBlend blend, long seed, int x, int z) {
        if (!blend.transition()) {
            return blend.primary();
        }
        double chooser = ((brNoise2(seed + 0x5399L, x * 0.0105D, z * 0.0105D) + 1.0D) * 0.5D);
        return chooser < blend.secondaryWeight() ? blend.secondary() : blend.primary();
    }

    private static int computeHellscapeLavaLakeDepth(long seed, HellscapeRegion region, int x, int z) {
        if (region == HellscapeRegion.SCORCHED_STEPS || region == HellscapeRegion.MAGMA_CAVERNS) {
            return 0;
        }
        double basin = brNoise2(seed + 0x5D01L + region.ordinal(), x * 0.0022D, z * 0.0022D)
            + (brNoise2(seed + 0x5D02L + region.ordinal(), x * 0.0088D, z * 0.0088D) * 0.42D);
        double threshold = switch (region) {
            case BASALT_DELTAS -> 0.46D;
            case FUME_VENTS -> 0.58D;
            case NETHER_WASTES -> 0.52D;
            case SOUL_SAND_VALLEY -> 0.60D;
            case CRIMSON_FOREST, WARPED_FOREST -> 0.62D;
            default -> 0.72D;
        };
        if (basin <= threshold) {
            return 0;
        }
        return switch (region) {
            case BASALT_DELTAS -> 6 + (int) Math.round((basin - threshold) * 16.0D);
            case NETHER_WASTES -> 5 + (int) Math.round((basin - threshold) * 14.0D);
            case FUME_VENTS, SOUL_SAND_VALLEY -> 4 + (int) Math.round((basin - threshold) * 10.0D);
            default -> 3 + (int) Math.round((basin - threshold) * 8.0D);
        };
    }

    private static int computeHellscapeLavaLakeTopY(long seed, HellscapeRegion region, int x, int z, int floorY, int lakeDepth) {
        if (lakeDepth <= 0) {
            return Integer.MIN_VALUE;
        }
        double base = switch (region) {
            case BASALT_DELTAS -> 34.0D;
            case NETHER_WASTES -> 32.0D;
            case FUME_VENTS -> 28.0D;
            case SOUL_SAND_VALLEY -> 26.0D;
            case CRIMSON_FOREST, WARPED_FOREST -> 30.0D;
            default -> 30.0D;
        };
        double noise = brNoise2(seed + 0x5D03L + region.ordinal(), x * 0.0044D, z * 0.0044D) * 4.0D;
        int lakeTopY = (int) Math.round(Math.min(floorY - 1, base + noise));
        return clamp(lakeTopY, floorY + 1, floorY + Math.max(2, lakeDepth));
    }

    private static boolean shouldCarveHellscapeFloorCave(
        long seed,
        HellscapeRegion region,
        int x,
        int y,
        int z,
        int floorY
    ) {
        if (y > floorY - 4 || y < floorY - 26) {
            return false;
        }
        double planar = brNoise2(seed + 0x5E01L + region.ordinal(), x * 0.018D, z * 0.018D) * 0.44D;
        double skewA = brNoise2(seed + 0x5E02L + region.ordinal(), x * 0.022D, y * 0.022D) * 0.28D;
        double skewB = brNoise2(seed + 0x5E03L + region.ordinal(), z * 0.022D, y * 0.022D) * 0.28D;
        double verticalEase = 1.0D - clamp(Math.abs((floorY - 12) - y) / 14.0D, 0.0D, 1.0D);
        double threshold = switch (region) {
            case FUME_VENTS -> 0.22D;
            case NETHER_WASTES, NETHER_WASTES_DEEP -> 0.24D;
            case SOUL_SAND_VALLEY -> 0.26D;
            case BASALT_DELTAS -> 0.20D;
            default -> 0.30D;
        };
        return (planar + skewA + skewB + (verticalEase * 0.10D)) > threshold;
    }

    private static int hellscapeVentAnchorX(long seed, int cellX, int cellZ) {
        return (cellX * HELLSCAPE_FUME_VENT_SPACING)
            + (int) Math.round(((brHashToUnit(seed + 0x5A01L, cellX, cellZ) + 1.0D) * 0.5D) * (HELLSCAPE_FUME_VENT_SPACING - 1));
    }

    private static int hellscapeVentAnchorZ(long seed, int cellX, int cellZ) {
        return (cellZ * HELLSCAPE_FUME_VENT_SPACING)
            + (int) Math.round(((brHashToUnit(seed + 0x5A02L, cellZ, cellX) + 1.0D) * 0.5D) * (HELLSCAPE_FUME_VENT_SPACING - 1));
    }

    private static int hellscapeVentHeight(long seed, int cellX, int cellZ) {
        return 3 + Math.max(0, (int) Math.round(((brHashToUnit(seed + 0x5A03L, cellX, cellZ) + 1.0D) * 0.5D) * 2.0D));
    }

    private static HellscapeRegion hellscapeRegionAt(
        HellscapeBiomeSelection selection,
        long seed,
        long salt,
        double mapRadius,
        int x,
        int y,
        int z
    ) {
        if (y < 0 && selection.isActive(HellscapeRegion.MAGMA_CAVERNS)) {
            return HellscapeRegion.MAGMA_CAVERNS;
        }
        HellscapeRegion surface = selectHellscapeSurfaceRegion(seed, salt, mapRadius, x, z, selection.activeSurfaceRegions());
        if (surface == HellscapeRegion.SCORCHED_STEPS
            && selection.isActive(HellscapeRegion.FUME_VENTS)
            && y < 72) {
            return HellscapeRegion.FUME_VENTS;
        }
        if (surface == HellscapeRegion.NETHER_WASTES
            && selection.isActive(HellscapeRegion.NETHER_WASTES_DEEP)
            && y < 40) {
            return HellscapeRegion.NETHER_WASTES_DEEP;
        }
        return surface;
    }

